begin;
create table if not exists public.zchat_device_ids (
  user_id uuid not null,
  device_id text not null,
  first_seen timestamptz not null default now(),
  last_seen timestamptz not null default now(),
  primary key (user_id, device_id)
);
create index if not exists zchat_device_ids_device on public.zchat_device_ids (device_id);
alter table public.zchat_device_ids enable row level security;
revoke all on public.zchat_device_ids from public, anon, authenticated;
grant select on public.zchat_device_ids to authenticated;
grant all on public.zchat_device_ids to service_role;
drop policy if exists "zchat device ids admins" on public.zchat_device_ids;
create policy "zchat device ids admins" on public.zchat_device_ids for select to authenticated using ((select public.zchat_is_admin()));

create table if not exists public.zchat_profile_hidden (
  id uuid primary key,
  avatar text,
  last_seen timestamptz,
  updated_at timestamptz not null default now()
);
alter table public.zchat_profile_hidden enable row level security;
revoke all on public.zchat_profile_hidden from public, anon, authenticated;
grant all on public.zchat_profile_hidden to service_role;

create or replace function public.zchat_profile_private_cols()
returns text[]
language sql
immutable
as $$
  select array[
    'device_id', 'whatsapp', 'banned_reason', 'banned_at', 'is_admin', 'limits_until', 'limit_strangers', 'limit_recent',
    'chat_lock_hash', 'chat_lock_enabled', 'verified_seen', 'avatar_frame_seen', 'custom_badge_seen', 'username_changed_at',
    'alert_moment', 'alert_birthday', 'typing_privacy', 'hide_activity', 'hide_age', 'hide_bio', 'hide_country', 'hide_gender', 'hide_photo',
    'privacy_profile', 'privacy_online', 'privacy_leaderboard', 'privacy_messages', 'privacy_comments', 'privacy_mentions', 'privacy_calls',
    'privacy_story_replies', 'privacy_bio', 'privacy_groups', 'privacy_lastseen', 'privacy_tags',
    'bio', 'social_links', 'age', 'gender', 'country'
  ]::text[]
$$;

create or replace function public.zchat_activity_public(p_hide boolean, p_lastseen text, p_online text)
returns boolean
language sql
immutable
as $$
  select not coalesce(p_hide, false) and coalesce(p_lastseen, 'everyone') = 'everyone' and coalesce(p_online, 'everyone') = 'everyone'
$$;

create or replace function public.zchat_pv_allows(p_setting text, p_scope text, p_fol boolean, p_rev boolean, p_chosen text[])
returns boolean
language sql
immutable
as $$
  select case coalesce(p_setting, 'everyone')
    when 'everyone' then true
    when 'followers' then coalesce(p_fol, false)
    when 'following' then coalesce(p_rev, false)
    when 'chosen' then p_scope = any (coalesce(p_chosen, '{}'::text[]))
    when 'nobody' then false
    when 'off' then false
    else true
  end
$$;

create or replace function public.zchat_profile_split()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  h_avatar text;
  h_seen timestamptz;
  had boolean := false;
  vis_photo boolean;
  vis_seen boolean;
  old_photo boolean := true;
  old_seen boolean := true;
  t_avatar text;
  t_seen timestamptz;
begin
  if new.device_id is not null then
    if btrim(new.device_id) <> '' and length(new.device_id) <= 120 then
      insert into public.zchat_device_ids (user_id, device_id) values (new.id, new.device_id)
        on conflict (user_id, device_id) do update set last_seen = now();
    end if;
    new.device_id := null;
  end if;
  if tg_op = 'UPDATE' and coalesce(new.is_deleted, false) and not coalesce(old.is_deleted, false) then
    delete from public.zchat_profile_hidden where id = new.id;
    return new;
  end if;
  vis_photo := not coalesce(new.hide_photo, false) or coalesce(new.is_deleted, false);
  vis_seen := public.zchat_activity_public(new.hide_activity, new.privacy_lastseen, new.privacy_online);
  if tg_op = 'UPDATE' then
    old_photo := not coalesce(old.hide_photo, false) or coalesce(old.is_deleted, false);
    old_seen := public.zchat_activity_public(old.hide_activity, old.privacy_lastseen, old.privacy_online);
  end if;
  if vis_photo and vis_seen and old_photo and old_seen then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    select z.avatar, z.last_seen into h_avatar, h_seen from public.zchat_profile_hidden z where z.id = new.id;
    had := found;
  end if;
  if tg_op = 'INSERT' or new.avatar is distinct from old.avatar then
    t_avatar := new.avatar;
  elsif old_photo or not had then
    t_avatar := old.avatar;
  else
    t_avatar := h_avatar;
  end if;
  if tg_op = 'INSERT' or new.last_seen is distinct from old.last_seen then
    t_seen := new.last_seen;
  elsif old_seen or not had then
    t_seen := old.last_seen;
  else
    t_seen := h_seen;
  end if;
  if not vis_photo or not vis_seen then
    insert into public.zchat_profile_hidden (id, avatar, last_seen, updated_at)
      values (new.id, t_avatar, t_seen, now())
      on conflict (id) do update set avatar = excluded.avatar, last_seen = excluded.last_seen, updated_at = now();
  end if;
  new.avatar := case when vis_photo then t_avatar else null end;
  new.last_seen := case when vis_seen then t_seen else null end;
  return new;
end
$$;

drop trigger if exists zchat_profile_split on public.profiles;
create trigger zchat_profile_split
  before insert or update on public.profiles
  for each row execute function public.zchat_profile_split();

insert into public.zchat_device_ids (user_id, device_id)
  select p.id, p.device_id from public.profiles p
  where p.device_id is not null and btrim(p.device_id) <> '' and length(p.device_id) <= 120
  on conflict (user_id, device_id) do nothing;

update public.profiles p set avatar = p.avatar
  where coalesce(p.hide_photo, false) and not coalesce(p.is_deleted, false) and p.avatar is not null;
update public.profiles p set last_seen = p.last_seen
  where p.last_seen is not null and not public.zchat_activity_public(p.hide_activity, p.privacy_lastseen, p.privacy_online);

create or replace function public.zchat_profile_grants()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  cols text;
  n integer;
begin
  select string_agg(quote_ident(c.column_name), ', ' order by c.ordinal_position), count(*)
    into cols, n
    from information_schema.columns c
    where c.table_schema = 'public' and c.table_name = 'profiles'
      and not (c.column_name = any (public.zchat_profile_private_cols()));
  execute 'revoke select on public.profiles from anon, authenticated';
  execute format('grant select (%s) on public.profiles to anon, authenticated', cols);
  execute 'grant select on public.profiles to service_role';
  return n;
end
$$;
revoke execute on function public.zchat_profile_grants() from public, anon, authenticated;
select public.zchat_profile_grants();

create or replace function public.zchat_my_profile()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select (to_jsonb(p) - 'device_id') || jsonb_build_object(
    'avatar', case when coalesce(p.hide_photo, false) and not coalesce(p.is_deleted, false) and h.id is not null then h.avatar else p.avatar end,
    'last_seen', case when h.id is not null and not public.zchat_activity_public(p.hide_activity, p.privacy_lastseen, p.privacy_online) then coalesce(h.last_seen, p.last_seen) else p.last_seen end)
  from public.profiles p
  left join public.zchat_profile_hidden h on h.id = p.id
  where p.id = auth.uid()
$$;
revoke execute on function public.zchat_my_profile() from public, anon;
grant execute on function public.zchat_my_profile() to authenticated, service_role;

create or replace function public.zchat_profile_view(p_ids uuid[])
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  with viewer as (
    select auth.uid() as uid
  ),
  ids as (
    select distinct x as id from unnest(coalesce(p_ids, '{}'::uuid[])) x where x is not null limit 1000
  ),
  base as (
    select p as pr, p.id, h.avatar as h_avatar, h.last_seen as h_seen, (h.id is not null) as h_has,
      (v.uid is not null and p.id = v.uid) as own,
      (v.uid is not null and exists (select 1 from public.follows f where f.follower_id = v.uid and f.following_id = p.id and coalesce(f.status, 'accepted') = 'accepted')) as fol,
      (v.uid is not null and exists (select 1 from public.follows f where f.follower_id = p.id and f.following_id = v.uid and coalesce(f.status, 'accepted') = 'accepted')) as rev,
      (v.uid is not null and exists (select 1 from public.blocks b where (b.blocker_id = p.id and b.blocked_id = v.uid) or (b.blocker_id = v.uid and b.blocked_id = p.id))) as blk,
      coalesce((select array_agg(a.scope) from public.privacy_allow a where a.user_id = p.id and a.viewer_id = v.uid), '{}'::text[]) as chosen
    from ids
    join public.profiles p on p.id = ids.id
    left join public.zchat_profile_hidden h on h.id = p.id
    cross join viewer v
  ),
  shaped as (
    select b.*,
      not b.blk and (not coalesce((b.pr).is_private, false) or b.fol) and public.zchat_pv_allows((b.pr).privacy_profile, 'privacy_profile', b.fol, b.rev, b.chosen) as det,
      case when b.h_has and not public.zchat_activity_public((b.pr).hide_activity, (b.pr).privacy_lastseen, (b.pr).privacy_online) then coalesce(b.h_seen, (b.pr).last_seen) else (b.pr).last_seen end as true_seen,
      case when b.h_has and coalesce((b.pr).hide_photo, false) and not coalesce((b.pr).is_deleted, false) then b.h_avatar else (b.pr).avatar end as true_avatar
    from base b
  )
  select coalesce(jsonb_agg(
    case when s.own then
      (to_jsonb(s.pr) - 'device_id') || jsonb_build_object('avatar', s.true_avatar, 'last_seen', s.true_seen)
    else
      (to_jsonb(s.pr) - public.zchat_profile_private_cols()) || jsonb_build_object(
        'avatar', case when coalesce((s.pr).hide_photo, false) and not coalesce((s.pr).is_deleted, false) then null else s.true_avatar end,
        'last_seen', case when not s.blk and not coalesce((s.pr).hide_activity, false) and public.zchat_pv_allows((s.pr).privacy_lastseen, 'privacy_lastseen', s.fol, s.rev, s.chosen) then s.true_seen end,
        'bio', case when s.det and not coalesce((s.pr).hide_bio, false) and public.zchat_pv_allows((s.pr).privacy_bio, 'privacy_bio', s.fol, s.rev, s.chosen) then (s.pr).bio end,
        'social_links', case when s.det and public.zchat_pv_allows((s.pr).privacy_bio, 'privacy_bio', s.fol, s.rev, s.chosen) then (s.pr).social_links end,
        'whatsapp', case when s.det and public.zchat_pv_allows((s.pr).privacy_bio, 'privacy_bio', s.fol, s.rev, s.chosen) then (s.pr).whatsapp end,
        'age', case when s.det and not coalesce((s.pr).hide_age, false) then (s.pr).age end,
        'country', case when s.det and not coalesce((s.pr).hide_country, false) then (s.pr).country end,
        'gender', case when s.det and not coalesce((s.pr).hide_gender, false) then (s.pr).gender end,
        'hide_activity', coalesce((s.pr).hide_activity, false) or s.blk,
        'hide_photo', false, 'hide_age', false, 'hide_bio', false, 'hide_country', false, 'hide_gender', false,
        'privacy_profile', case when not s.blk and public.zchat_pv_allows((s.pr).privacy_profile, 'privacy_profile', s.fol, s.rev, s.chosen) then 'everyone' else 'nobody' end,
        'privacy_bio', case when not s.blk and public.zchat_pv_allows((s.pr).privacy_bio, 'privacy_bio', s.fol, s.rev, s.chosen) then 'everyone' else 'nobody' end,
        'privacy_online', case when not s.blk and public.zchat_pv_allows((s.pr).privacy_online, 'privacy_online', s.fol, s.rev, s.chosen) then 'everyone' else 'nobody' end,
        'privacy_lastseen', case when not s.blk and public.zchat_pv_allows((s.pr).privacy_lastseen, 'privacy_lastseen', s.fol, s.rev, s.chosen) then 'everyone' else 'nobody' end,
        'privacy_tags', case when not s.blk and public.zchat_pv_allows((s.pr).privacy_tags, 'privacy_tags', s.fol, s.rev, s.chosen) then 'everyone' else 'nobody' end,
        'privacy_groups', case when not s.blk and public.zchat_pv_allows((s.pr).privacy_groups, 'privacy_groups', s.fol, s.rev, s.chosen) then 'everyone' else 'nobody' end,
        'privacy_leaderboard', case when not s.blk and public.zchat_pv_allows((s.pr).privacy_leaderboard, 'privacy_leaderboard', s.fol, s.rev, s.chosen) then 'everyone' else 'nobody' end,
        'privacy_mentions', case when not s.blk and public.zchat_pv_allows((s.pr).privacy_mentions, 'privacy_mentions', s.fol, s.rev, s.chosen) then 'everyone' else 'nobody' end,
        'privacy_calls', case when not s.blk and public.zchat_pv_allows((s.pr).privacy_calls, 'privacy_calls', s.fol, s.rev, s.chosen) then 'everyone' else 'nobody' end,
        'typing_privacy', case when not s.blk and public.zchat_pv_allows((s.pr).typing_privacy, 'typing_privacy', s.fol, s.rev, s.chosen) then 'everyone' else 'nobody' end,
        'privacy_comments', case when not s.blk and public.zchat_pv_allows((s.pr).privacy_comments, 'privacy_comments', s.fol, s.rev, s.chosen) then 'everyone' else 'off' end,
        'privacy_story_replies', case when not s.blk and public.zchat_pv_allows((s.pr).privacy_story_replies, 'privacy_story_replies', s.fol, s.rev, s.chosen) then 'everyone' else 'off' end,
        'privacy_messages', case when not s.blk and public.zchat_pv_allows((s.pr).privacy_messages, 'privacy_messages', s.fol, s.rev, s.chosen) then 'everyone' else 'following' end
      )
    end), '[]'::jsonb)
  from shaped s
$$;
revoke execute on function public.zchat_profile_view(uuid[]) from public, anon;
grant execute on function public.zchat_profile_view(uuid[]) to authenticated, service_role;

create or replace function public.zchat_note_device(p_device text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
begin
  if me is null or p_device is null or btrim(p_device) = '' or length(p_device) > 120 then
    return;
  end if;
  insert into public.zchat_device_ids (user_id, device_id) values (me, p_device)
    on conflict (user_id, device_id) do update set last_seen = now()
    where public.zchat_device_ids.last_seen < now() - interval '1 hour';
end
$$;
revoke execute on function public.zchat_note_device(text) from public, anon;
grant execute on function public.zchat_note_device(text) to authenticated, service_role;

create or replace function public.is_blocked(p_device text, p_email text)
returns boolean
language sql
security definer
set search_path = public
as $$
  select exists (
      select 1 from public.bans b
      where (nullif(p_device, '') is not null and b.device_id = p_device)
         or (nullif(p_email, '') is not null and lower(b.email) = lower(p_email))
    )
    or (nullif(p_device, '') is not null and exists (
      select 1 from public.zchat_device_ids d
      join public.profiles p on p.id = d.user_id
      where d.device_id = p_device and coalesce(p.banned, false)
    ))
$$;
grant execute on function public.is_blocked(text, text) to anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.zchat_chat_list(p_reads jsonb DEFAULT NULL::jsonb, p_window integer DEFAULT 400, p_per integer DEFAULT 4)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  win integer := least(greatest(coalesce(p_window, 400), 50), 600);
  per integer := least(greatest(coalesce(p_per, 4), 2), 20);
  reads jsonb := case when jsonb_typeof(p_reads) = 'object' then p_reads else '{}'::jsonb end;
  hid jsonb := '{}'::jsonb;
  out_convs jsonb;
  out_msgs jsonb;
  out_sent jsonb;
  out_profiles jsonb;
  out_nicks jsonb;
  out_aliases jsonb;
  out_unread jsonb;
  out_members jsonb;
  out_groups jsonb;
  out_gmsgs jsonb;
  out_gunread jsonb;
  out_gnames jsonb;
  out_locks jsonb;
  out_blocks jsonb;
  out_blocked_by jsonb;
begin
  if me is null then
    return jsonb_build_object('v', 1, 'ok', false);
  end if;
  if (select count(*) from jsonb_object_keys(reads)) > 500 then
    reads := '{}'::jsonb;
  end if;

  if to_regclass('public.hidden_messages') is not null then
    select coalesce(jsonb_object_agg(h.message_id, true), '{}'::jsonb) into hid
    from (select distinct h0.message_id from public.hidden_messages h0 where h0.user_id = me and h0.message_id not like 'chat:%' limit 20000) h;
  end if;

  select coalesce(jsonb_agg(to_jsonb(c) order by c.last_message_at desc nulls first), '[]'::jsonb) into out_convs
  from public.conversations c
  where c.user_a = me or c.user_b = me;

  with mine as (
    select m.id, m.sender_id, m.receiver_id, m.type, m.content, m.deleted, m.created_at, m.read, m.delivered, m.story_id, m.expires_at, m.media_url
    from public.messages m
    where m.sender_id = me and m.group_id is null
    order by m.created_at desc
    limit win
  ), theirs as (
    select m.id, m.sender_id, m.receiver_id, m.type, m.content, m.deleted, m.created_at, m.read, m.delivered, m.story_id, m.expires_at, m.media_url
    from public.messages m
    where m.receiver_id = me and m.group_id is null and m.sender_id is distinct from me
    order by m.created_at desc
    limit win
  ), w as (
    select u.* from (select * from mine union all select * from theirs) u
    order by u.created_at desc
    limit win
  ), tagged as (
    select w.*,
      case when w.sender_id = me then w.receiver_id else w.sender_id end as other,
      (hid ? w.id::text) as is_hidden,
      (w.expires_at is not null and w.expires_at <= now()) as is_gone
    from w
  ), ranked as (
    select t.*,
      row_number() over (partition by t.other order by t.created_at desc, t.id desc) as rn_any,
      row_number() over (partition by t.other, (not t.is_hidden and not t.is_gone) order by t.created_at desc, t.id desc) as rn_ok
    from tagged t
    where t.other is not null
  )
  select
    coalesce(jsonb_agg(
      jsonb_strip_nulls(jsonb_build_object('id', r.id, 'sender_id', r.sender_id, 'receiver_id', r.receiver_id, 'type', r.type, 'content', r.content,
        'deleted', r.deleted, 'created_at', r.created_at, 'read', r.read, 'delivered', r.delivered, 'story_id', r.story_id,
        'expires_at', r.expires_at,
        'media_url', case when r.media_url ~* '^https://[a-z0-9.]*giphy\.com/' then r.media_url end,
        'hid', case when r.is_hidden then true end))
      order by r.created_at desc
    ) filter (where r.rn_any = 1 or (not r.is_hidden and not r.is_gone and r.rn_ok <= per)), '[]'::jsonb),
    coalesce(jsonb_agg(distinct r.other) filter (where r.sender_id = me), '[]'::jsonb)
  into out_msgs, out_sent
  from ranked r;

  out_profiles := public.zchat_profile_view(array(
    select distinct case when c.user_a = me then c.user_b else c.user_a end
    from public.conversations c
    where c.user_a = me or c.user_b = me
  ));

  if to_regclass('public.contact_nicknames') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(n)), ''[]''::jsonb) from public.contact_nicknames n where n.owner_id = $1' into out_nicks using me;
  end if;
  if to_regclass('public.self_aliases') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(a)), ''[]''::jsonb) from public.self_aliases a where a.viewer_id = $1' into out_aliases using me;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('id', u.id, 'sender_id', u.sender_id)), '[]'::jsonb) into out_unread
  from (
    select m.id, m.sender_id
    from public.messages m
    where m.receiver_id = me and m.group_id is null and m.read = false and m.deleted is not true
    order by m.created_at desc
    limit 1000
  ) u;

  select coalesce(jsonb_agg(to_jsonb(gm)), '[]'::jsonb) into out_members
  from public.group_members gm
  where gm.user_id = me;

  select coalesce(jsonb_agg(to_jsonb(g)), '[]'::jsonb) into out_groups
  from public.groups g
  where g.id in (select gm.group_id from public.group_members gm where gm.user_id = me);

  select coalesce(jsonb_agg(
      jsonb_strip_nulls(jsonb_build_object('id', x.id, 'group_id', x.group_id, 'sender_id', x.sender_id, 'type', x.type, 'content', x.content,
        'created_at', x.created_at, 'deleted', x.deleted, 'expires_at', x.expires_at, 'story_id', x.story_id,
        'media_url', case when x.media_url ~* '^https://[a-z0-9.]*giphy\.com/' then x.media_url end))
      order by x.created_at desc), '[]'::jsonb),
    coalesce(jsonb_agg(distinct x.sender_id) filter (where x.sender_id is distinct from me and x.type is distinct from 'system' and x.sender_id is not null), '[]'::jsonb)
  into out_gmsgs, out_gnames
  from public.group_members gm
  cross join lateral (
    select m.id, m.group_id, m.sender_id, m.type, m.content, m.created_at, m.deleted, m.expires_at, m.story_id, m.media_url
    from public.messages m
    where m.group_id = gm.group_id
      and not (hid ? m.id::text)
      and (m.expires_at is null or m.expires_at > now())
    order by m.created_at desc
    limit per
  ) x
  where gm.user_id = me;

  select coalesce(jsonb_object_agg(p.id, p.name), '{}'::jsonb) into out_gnames
  from public.profiles p
  where p.id in (select (jsonb_array_elements_text(out_gnames))::uuid);

  select coalesce(jsonb_object_agg(k.group_id, k.n), '{}'::jsonb) into out_gunread
  from (
    select gm.group_id, (
      select count(*) from (
        select 1
        from public.messages m
        where m.group_id = gm.group_id
          and m.created_at > public.zchat_core_ts(reads ->> gm.group_id::text)
          and m.sender_id is distinct from me
          and m.type is distinct from 'system'
          and m.deleted is not true
          and (m.expires_at is null or m.expires_at > now())
          and not (hid ? m.id::text)
        limit 100
      ) z
    ) as n
    from public.group_members gm
    where gm.user_id = me
      and public.zchat_core_ts(reads ->> gm.group_id::text) is not null
  ) k;

  if to_regclass('public.chat_locks') is not null then
    execute 'select coalesce(jsonb_agg(l.conversation_id), ''[]''::jsonb) from public.chat_locks l where l.owner_id = $1' into out_locks using me;
  end if;

  select coalesce(jsonb_agg(b.blocked_id), '[]'::jsonb) into out_blocks from public.blocks b where b.blocker_id = me;
  select coalesce(jsonb_agg(b.blocker_id), '[]'::jsonb) into out_blocked_by from public.blocks b where b.blocked_id = me;

  return jsonb_build_object(
    'v', 1, 'ok', true, 'me', me,
    'convs', out_convs, 'msgs', out_msgs, 'sent', out_sent, 'profiles', out_profiles,
    'nicks', out_nicks, 'aliases', out_aliases, 'unread', out_unread,
    'members', out_members, 'groups', out_groups, 'gmsgs', out_gmsgs, 'gunread', out_gunread, 'gnames', out_gnames,
    'locks', out_locks, 'blocks', out_blocks, 'blocked_by', out_blocked_by
  );
end $function$;

grant execute on function public.zchat_chat_list(jsonb, integer, integer) to authenticated, service_role;
revoke execute on function public.zchat_chat_list(jsonb, integer, integer) from anon;

do $do$
declare
  rt text;
begin
  rt := coalesce((select pg_get_function_result(p.oid) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'public_profile_preview' and pg_get_function_identity_arguments(p.oid) = 'p_id text'), 'jsonb');
  execute format($f$
create or replace function public.public_profile_preview(p_id text)
returns %s
language plpgsql
stable
security definer
set search_path = public
as $body$
declare
  p public.profiles%%rowtype;
  priv boolean;
  open_profile boolean;
  posts jsonb := '[]'::jsonb;
  n_posts int;
  n_foll int;
  n_fing int;
begin
  select * into p from public.profiles where id::text = p_id limit 1;
  if not found or coalesce(p.is_deleted, false) or coalesce(p.banned, false) then
    return jsonb_build_object('found', false);
  end if;
  priv := coalesce(p.is_private, false);
  open_profile := public.zchat_owner_visible(p.id, 'posts');
  select count(*) into n_posts from public.posts x where x.user_id = p.id and (x.scheduled_for is null or x.scheduled_for <= now());
  select count(*) into n_foll from public.follows where following_id = p.id and status = 'accepted';
  select count(*) into n_fing from public.follows where follower_id = p.id and status = 'accepted';
  if open_profile then
    select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'media_url', x.media_url, 'media_type', x.media_type)), '[]'::jsonb)
      into posts
      from (select id, media_url, media_type from public.posts
            where user_id = p.id and (scheduled_for is null or scheduled_for <= now())
            order by created_at desc limit 9) x;
  end if;
  return jsonb_build_object('found', true, 'id', p.id, 'name', p.name, 'username', p.username,
    'avatar', case when coalesce(p.hide_photo, false) then '' else coalesce(p.avatar, '') end,
    'avatar_frame', to_jsonb(p.avatar_frame), 'verified', to_jsonb(p.verified), 'custom_badge', to_jsonb(p.custom_badge),
    'bio', case when open_profile and not coalesce(p.hide_bio, false) and public.zchat_pv_allows(p.privacy_bio, 'privacy_bio', false, false, null) then coalesce(p.bio, '') else '' end,
    'is_private', priv, 'posts_count', n_posts, 'followers_count', n_foll, 'following_count', n_fing, 'posts', posts);
end
$body$;
$f$, rt);
  execute 'grant execute on function public.public_profile_preview(text) to anon, authenticated, service_role';
end
$do$;

do $do$
declare
  rt text;
begin
  rt := coalesce((select pg_get_function_result(p.oid) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'public_post_preview' and pg_get_function_identity_arguments(p.oid) = 'p_id text'), 'jsonb');
  execute format($f$
create or replace function public.public_post_preview(p_id text)
returns %s
language plpgsql
stable
security definer
set search_path = public
as $body$
declare
  po public.posts%%rowtype;
  o public.profiles%%rowtype;
  card jsonb;
  n_likes int;
  n_comments int;
begin
  select * into po from public.posts where id::text = p_id limit 1;
  if not found or (po.scheduled_for is not null and po.scheduled_for > now()) then
    return jsonb_build_object('found', false);
  end if;
  select * into o from public.profiles pr where pr.id = po.user_id;
  if not found or coalesce(o.is_deleted, false) or coalesce(o.banned, false) then
    return jsonb_build_object('found', false);
  end if;
  card := jsonb_build_object('id', o.id, 'name', o.name, 'username', o.username,
    'avatar', case when coalesce(o.hide_photo, false) then '' else coalesce(o.avatar, '') end,
    'avatar_frame', to_jsonb(o.avatar_frame), 'verified', to_jsonb(o.verified), 'custom_badge', to_jsonb(o.custom_badge));
  if not public.zchat_owner_visible(po.user_id, 'posts') then
    return jsonb_build_object('found', true, 'restricted', true, 'owner', card);
  end if;
  select count(*) into n_likes from public.post_likes where post_id = po.id;
  select count(*) into n_comments from public.post_comments where post_id = po.id;
  return jsonb_build_object('found', true, 'restricted', false, 'owner', card, 'media_url', po.media_url,
    'media_type', po.media_type, 'caption', po.caption, 'created_at', po.created_at, 'likes', n_likes, 'comments', n_comments);
end
$body$;
$f$, rt);
  execute 'grant execute on function public.public_post_preview(text) to anon, authenticated, service_role';
end
$do$;

select public.zchat_apply_session_gate();
commit;

begin;
alter table public.groups add column if not exists approve_posts boolean not null default false;
alter table public.groups add column if not exists admin_links boolean not null default false;
alter table public.groups add column if not exists read_only boolean not null default false;
alter table public.groups add column if not exists welcome_text text;
alter table public.groups add column if not exists welcome_name boolean not null default true;
alter table public.groups add column if not exists group_rules jsonb;
alter table public.groups add column if not exists rules_version integer not null default 0;
alter table public.groups add column if not exists join_questions jsonb;

alter table public.group_members add column if not exists nick text;

alter table public.messages add column if not exists as_group boolean not null default false;
alter table public.messages add column if not exists asked_at timestamptz;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'zchat_g1_groups_ok' and conrelid = 'public.groups'::regclass) then
    alter table public.groups add constraint zchat_g1_groups_ok check (
      (welcome_text is null or char_length(welcome_text) <= 400)
      and (group_rules is null or (jsonb_typeof(group_rules) = 'array' and jsonb_array_length(group_rules) <= 10 and length(group_rules::text) <= 2600))
      and (join_questions is null or (jsonb_typeof(join_questions) = 'array' and jsonb_array_length(join_questions) <= 3 and length(join_questions::text) <= 700))
      and rules_version >= 0
    ) not valid;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'zchat_g1_nick_len' and conrelid = 'public.group_members'::regclass) then
    alter table public.group_members add constraint zchat_g1_nick_len check (nick is null or char_length(nick) between 1 and 32) not valid;
  end if;
end $$;

create or replace function public.zchat_g1_rank(p_group uuid, p_user uuid)
returns integer
language sql
stable
security definer
set search_path to 'public'
as $$
  select case
    when p_group is null or p_user is null then -1
    when exists (select 1 from public.groups g where g.id = p_group and g.created_by = p_user) then 3
    else coalesce((
      select case gm.role when 'admin' then 2 when 'moderator' then 1 else 0 end
      from public.group_members gm where gm.group_id = p_group and gm.user_id = p_user
    ), -1)
  end
$$;

create or replace function public.zchat_g1_my_rank(p_group uuid)
returns integer
language sql
stable
security definer
set search_path to 'public'
as $$
  select public.zchat_g1_rank(p_group, auth.uid())
$$;

create or replace function public.zchat_g1_is_bot(p_user uuid)
returns boolean
language sql
stable
security definer
set search_path to 'public'
as $$
  select coalesce((select p.is_bot from public.profiles p where p.id = p_user), false)
$$;

create or replace function public.zchat_g1_clean(p_text text, p_max integer, p_lines boolean default false)
returns text
language sql
immutable
as $$
  select nullif(left(btrim(
    case when p_lines
      then regexp_replace(regexp_replace(regexp_replace(coalesce(p_text, ''), E'[\\u0000-\\u0009\\u000B-\\u001F\\u007F-\\u009F\\u200B-\\u200F\\u202A-\\u202E\\u2060-\\u206F\\uFEFF]+', '', 'g'), E'[ \\t]+', ' ', 'g'), E'\\n{3,}', E'\n\n', 'g')
      else regexp_replace(regexp_replace(coalesce(p_text, ''), E'[\\u0000-\\u001F\\u007F-\\u009F\\u200B-\\u200F\\u202A-\\u202E\\u2060-\\u206F\\uFEFF]+', ' ', 'g'), E'\\s+', ' ', 'g')
    end), p_max), '')
$$;

create or replace function public.zchat_g1_name_key(p_text text)
returns text
language sql
immutable
as $$
  select nullif(translate(regexp_replace(lower(coalesce(p_text, '')), '[^[:alnum:]]+', '', 'g'), '013457', 'oleast'), '')
$$;

create or replace function public.zchat_g1_has_link(p_text text)
returns boolean
language sql
immutable
as $$
  select coalesce(p_text, '') ~* '(https?://|(^|[^[:alnum:]_])www\.[[:alnum:]-]+\.[[:alnum:]]|[[:alnum:]._%+-]+@[[:alnum:]-]+\.[[:alpha:]]{2,}|(^|[^[:alnum:]_@./-])[[:alnum:]][[:alnum:]-]*\.(com|net|org|io|co|me|app|gg|ly|xyz|info|biz|link|site|online|store|shop|lk|in|uk|us|tv|to|be|dev|ai|ru|cn|de|fr|es|it|nl|au|ca|br|club|top|live|click|fun|vip|page|cc|ws|im|tk|ml|ga|cf|gq|gl|gd|pw|sh|so|st|su|fm)([/?#:]|[^[:alnum:]_-]|$))'
$$;

create or replace function public.zchat_g1_list(p_value jsonb, p_items integer, p_len integer)
returns jsonb
language plpgsql
immutable
as $$
declare
  out jsonb := '[]'::jsonb;
  item jsonb;
  t text;
begin
  if p_value is null or jsonb_typeof(p_value) <> 'array' then
    return null;
  end if;
  for item in select value from jsonb_array_elements(p_value) loop
    if jsonb_typeof(item) <> 'string' then
      continue;
    end if;
    t := public.zchat_g1_clean(item #>> '{}', p_len);
    if t is null or out @> jsonb_build_array(t) then
      continue;
    end if;
    out := out || jsonb_build_array(t);
    exit when jsonb_array_length(out) >= p_items;
  end loop;
  return case when jsonb_array_length(out) = 0 then null else out end;
end $$;

drop policy if exists "zchat g1 members update own row" on public.group_members;
create policy "zchat g1 members update own row" on public.group_members
  for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create or replace function public.zchat_g1_member_guard()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  k text;
  r_me integer;
begin
  if tg_op = 'UPDATE' and me is not null and coalesce(current_setting('zchat.g1_ok', true), '') <> '1'
     and (new.joined_at is distinct from old.joined_at or new.id is distinct from old.id) then
    raise exception 'This part of a membership cannot be changed' using errcode = '42501';
  end if;
  if tg_op = 'UPDATE' and new.nick is not distinct from old.nick then
    return new;
  end if;
  if tg_op = 'INSERT' and new.nick is null then
    return new;
  end if;
  new.nick := public.zchat_g1_clean(new.nick, 64);
  if me is not null and coalesce(current_setting('zchat.g1_ok', true), '') <> '1' then
    if tg_op = 'INSERT' and new.nick is not null then
      new.nick := null;
      return new;
    end if;
    if old.user_id is distinct from me then
      r_me := public.zchat_g1_rank(old.group_id, me);
      if new.nick is not null or r_me < 2 or r_me <= public.zchat_g1_rank(old.group_id, old.user_id) then
        raise exception 'Only they can change their name in this group' using errcode = '42501';
      end if;
      return new;
    end if;
  end if;
  if new.nick is null then
    return new;
  end if;
  if char_length(new.nick) > 32 then
    raise exception 'Keep your name in this group to 32 characters' using errcode = '22023';
  end if;
  k := public.zchat_g1_name_key(new.nick);
  if k is null then
    raise exception 'Use some letters or numbers in your name' using errcode = '22023';
  end if;
  if exists (
    select 1
    from public.group_members gm
    left join public.profiles p on p.id = gm.user_id
    where gm.group_id = new.group_id
      and gm.user_id <> new.user_id
      and (public.zchat_g1_name_key(gm.nick) = k or public.zchat_g1_name_key(p.name) = k or public.zchat_g1_name_key(p.username) = k)
  ) then
    raise exception 'Someone in this group already goes by that name' using errcode = '23505';
  end if;
  return new;
end $$;

drop trigger if exists zchat_g1_member_guard on public.group_members;
create trigger zchat_g1_member_guard
  before insert or update on public.group_members
  for each row execute function public.zchat_g1_member_guard();

create unique index if not exists zchat_g1_nick_unique on public.group_members (group_id, public.zchat_g1_name_key(nick)) where nick is not null;

