begin;
create or replace function public.zchat_g1_post_gate()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  g record;
  who uuid;
  r integer;
  waiting integer;
  recent integer;
  body jsonb;
  pid bigint;
  has_rules boolean;
begin
  if new.group_id is null then
    return new;
  end if;
  if coalesce(current_setting('zchat.g1_ok', true), '') = '1' then
    return new;
  end if;
  new.asked_at := null;
  select x.read_only, x.approve_posts, x.admin_links, x.group_rules, x.rules_version, coalesce(x.send_policy, 'everyone') as send_policy
    into g from public.groups x where x.id = new.group_id;
  if not found then
    new.as_group := false;
    return new;
  end if;
  if g.read_only and coalesce(current_setting('zchat.role_ok', true), '') <> '1' and coalesce(current_setting('zchat.comm_ok', true), '') <> '1' then
    raise exception 'This group is read only' using errcode = 'P0001';
  end if;
  if coalesce(new.as_group, false) then
    if coalesce(new.type, 'text') = 'system' then
      new.as_group := false;
    else
      if me is null or (new.sender_id is not null and new.sender_id <> me) or public.zchat_g1_rank(new.group_id, me) < 2 then
        raise exception 'Only admins can post as the group' using errcode = '42501';
      end if;
      insert into public.zchat_grp_as_group (message_id, group_id, sender_id) values (new.id, new.group_id, me)
        on conflict (message_id) do nothing;
      new.sender_id := null;
      return new;
    end if;
  end if;
  who := new.sender_id;
  if who is null then
    return new;
  end if;
  r := public.zchat_g1_rank(new.group_id, who);
  if r >= 2 or public.zchat_g1_is_bot(who) then
    return new;
  end if;
  has_rules := g.group_rules is not null and jsonb_typeof(g.group_rules) = 'array' and jsonb_array_length(g.group_rules) > 0 and g.rules_version > 0;
  if coalesce(new.type, 'text') = 'system' then
    if r >= 1 or coalesce(current_setting('zchat.role_ok', true), '') = '1' or coalesce(current_setting('zchat.comm_ok', true), '') = '1' then
      return new;
    end if;
    if (g.approve_posts or has_rules)
       and not (char_length(coalesce(new.content, '')) <= 400
         and (coalesce(new.content, '') ~ '^(zshot:|zbuzz:|call:)' or coalesce(new.content, '') ~ ' (left the group|joined with the invite link|joined the group)$')) then
      raise exception 'Only admins can post updates here' using errcode = '42501';
    end if;
    return new;
  end if;
  if g.send_policy = 'admins' and coalesce(current_setting('zchat.role_ok', true), '') <> '1' and coalesce(current_setting('zchat.comm_ok', true), '') <> '1' then
    raise exception 'Only admins can send messages in this group' using errcode = '42501';
  end if;
  if has_rules and not exists (
    select 1 from public.zchat_grp_rules_ok a where a.group_id = new.group_id and a.user_id = who and a.version >= g.rules_version
  ) then
    raise exception 'Read the group rules and tap I agree before you post' using errcode = 'P0001';
  end if;
  if g.admin_links and public.zchat_g1_has_link(coalesce(new.content, '') || ' ' || coalesce(new.forwarded_from_name, '')) then
    raise exception 'Only admins can post links here' using errcode = 'P0001';
  end if;
  if g.approve_posts and r < 1 then
    select count(*), count(*) filter (where p.created_at > now() - interval '1 minute')
      into waiting, recent
      from public.zchat_grp_pending p
      where p.group_id = new.group_id and p.sender_id = who and p.status = 'pending';
    if waiting >= 20 or recent >= 6 then
      raise exception 'You have a lot of posts waiting. Give the admins a moment.' using errcode = 'P0001';
    end if;
    body := jsonb_strip_nulls(to_jsonb(new) - array['id', 'created_at', 'read', 'delivered', 'deleted', 'pinned_until', 'pinned_by', 'pinned_at', 'bot_reply', 'edited', 'as_group', 'asked_at', 'expires_at', 'sender_id', 'receiver_id']);
    insert into public.zchat_grp_pending (group_id, sender_id, payload, client_id)
      values (new.group_id, who, body, new.client_id)
      returning id into pid;
    perform set_config('zchat.g1_pid', pid::text, true);
    return null;
  end if;
  return new;
end $$;

drop trigger if exists zchat_zg1_post_gate on public.messages;
create trigger zchat_zg1_post_gate
  before insert on public.messages
  for each row execute function public.zchat_g1_post_gate();

drop policy if exists "zchat g1 post as the group" on public.messages;
create policy "zchat g1 post as the group" on public.messages
  for insert to authenticated
  with check (group_id is not null and sender_id is null and as_group is true and public.zchat_g1_rank(group_id, (select auth.uid())) >= 2);

create or replace function public.zchat_g1_freeze_messages()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  free text[] := array['read', 'delivered', 'read_at', 'delivered_at', 'seen_at'];
begin
  if old.group_id is null or auth.uid() is null or coalesce(current_setting('zchat.g1_ok', true), '') = '1' then
    return new;
  end if;
  if new.as_group is distinct from old.as_group or new.asked_at is distinct from old.asked_at then
    raise exception 'This part of a message cannot be changed' using errcode = '42501';
  end if;
  if exists (select 1 from public.groups g where g.id = old.group_id and g.read_only)
     and (to_jsonb(new) - free) is distinct from (to_jsonb(old) - free) then
    raise exception 'This group is read only' using errcode = 'P0001';
  end if;
  return new;
end $$;

drop trigger if exists zchat_zg1_freeze on public.messages;
create trigger zchat_zg1_freeze
  before update on public.messages
  for each row execute function public.zchat_g1_freeze_messages();

create or replace function public.zchat_g1_freeze_likes()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  mid bigint;
  e text;
begin
  if tg_op = 'DELETE' then
    mid := old.message_id;
    e := old.emoji;
  else
    mid := new.message_id;
    e := new.emoji;
  end if;
  if auth.uid() is not null and coalesce(current_setting('zchat.g1_ok', true), '') <> '1' and coalesce(e, '') <> 'zo'
     and exists (select 1 from public.messages m join public.groups g on g.id = m.group_id where m.id = mid and g.read_only) then
    raise exception 'This group is read only' using errcode = 'P0001';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end $$;

drop trigger if exists zchat_zg1_likes_freeze on public.message_likes;
create trigger zchat_zg1_likes_freeze
  before insert or update or delete on public.message_likes
  for each row execute function public.zchat_g1_freeze_likes();

create or replace function public.zchat_can_post_group(p_group uuid, p_type text)
 returns boolean
 language sql
 stable security definer
 set search_path to 'public'
as $function$
  select auth.uid() is not null and p_group is not null and (
    public.zchat_is_admin_id(auth.uid())
    or exists (
      select 1 from public.groups g
      where g.id = p_group and (
        g.created_by = auth.uid()
        or exists (
          select 1 from public.group_members gm
          where gm.group_id = g.id and gm.user_id = auth.uid()
            and (coalesce(p_type, 'text') = 'system' or coalesce(to_jsonb(g) ->> 'send_policy', 'everyone') <> 'admins' or gm.role = 'admin')
        )
      )
    )
  ) and not exists (select 1 from public.groups ro where ro.id = p_group and ro.read_only)
$function$;

create or replace function public.zchat_mod_delete(p_message bigint)
 returns jsonb
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  me uuid := auth.uid();
  m record;
  r_me integer;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  select x.id, x.group_id, x.sender_id, x.deleted, x.as_group into m from public.messages x where x.id = p_message for update;
  if not found or m.group_id is null then
    return jsonb_build_object('ok', false, 'reason', 'That message is not here anymore.');
  end if;
  r_me := public.zchat_group_role_rank(m.group_id, me);
  if r_me < 0 then
    return jsonb_build_object('ok', false, 'reason', 'That message is not here anymore.');
  end if;
  if m.sender_id is distinct from me and (r_me < 1 or r_me <= public.zchat_group_role_rank(m.group_id, m.sender_id)) then
    return jsonb_build_object('ok', false, 'reason', 'You can only delete messages from people with a lower role than yours.');
  end if;
  if m.sender_id is null and coalesce(m.as_group, false) and r_me < 2 then
    return jsonb_build_object('ok', false, 'reason', 'Only admins can delete posts from the group.');
  end if;
  if coalesce(m.deleted, false) then
    return jsonb_build_object('ok', true, 'already', true);
  end if;
  if exists (select 1 from public.groups g where g.id = m.group_id and g.read_only) then
    return jsonb_build_object('ok', false, 'reason', 'This group is read only.');
  end if;
  perform set_config('zchat.role_ok', '1', true);
  update public.messages set deleted = true, content = null, media_url = null, pinned_until = null, pinned_by = null, pinned_at = null
    where id = m.id;
  perform set_config('zchat.role_ok', '', true);
  return jsonb_build_object('ok', true);
end $function$;

revoke execute on function public.zchat_g1_post_gate() from anon, authenticated;
revoke execute on function public.zchat_g1_freeze_messages() from anon, authenticated;
revoke execute on function public.zchat_g1_freeze_likes() from anon, authenticated;

create or replace function public.zchat_g1_send(p_row jsonb)
returns jsonb
language plpgsql
security invoker
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  r public.messages;
  pid text;
  p public.zchat_grp_pending;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if p_row is null or jsonb_typeof(p_row) <> 'object' or nullif(p_row ->> 'group_id', '') is null then
    return jsonb_build_object('ok', false, 'reason', 'That did not send. Try again.');
  end if;
  perform set_config('zchat.g1_pid', '', true);
  insert into public.messages (sender_id, group_id, type, content, media_url, forwarded, forwarded_from_name, reply_to_id, topic, client_id, bubble_style, text_size, text_color, text_font, overlay_url, story_id, story_owner_id, story_media_url, story_media_type)
  select me, x.group_id, coalesce(x.type, 'text'), x.content, x.media_url, coalesce(x.forwarded, false), x.forwarded_from_name, x.reply_to_id, x.topic, x.client_id, x.bubble_style, x.text_size, x.text_color, x.text_font, x.overlay_url, x.story_id, x.story_owner_id, x.story_media_url, x.story_media_type
  from jsonb_populate_record(null::public.messages, p_row - array['id', 'sender_id', 'receiver_id', 'created_at', 'as_group', 'asked_at', 'deleted', 'read', 'delivered', 'bot_reply', 'edited']) x
  returning * into r;
  if r.id is not null then
    return jsonb_build_object('ok', true, 'message', to_jsonb(r));
  end if;
  pid := nullif(current_setting('zchat.g1_pid', true), '');
  if pid is null then
    return jsonb_build_object('ok', false, 'reason', 'That did not send. Try again.');
  end if;
  select * into p from public.zchat_grp_pending x where x.id = pid::bigint;
  return jsonb_build_object('ok', true, 'pending', true, 'id', p.id, 'created_at', p.created_at);
end $$;

create or replace function public.zchat_g1_review(p_id bigint, p_ok boolean)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  p public.zchat_grp_pending;
  r public.messages;
  x public.messages;
  why text;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  select * into p from public.zchat_grp_pending where id = p_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'That post is not waiting anymore.', 'gone', true);
  end if;
  if public.zchat_g1_rank(p.group_id, me) < 1 then
    return jsonb_build_object('ok', false, 'reason', 'Only admins and moderators can check posts.');
  end if;
  if p.status <> 'pending' then
    return jsonb_build_object('ok', false, 'reason', 'Someone already answered that post.', 'gone', true, 'status', p.status);
  end if;
  if coalesce(p_ok, false) then
    if not exists (select 1 from public.group_members gm where gm.group_id = p.group_id and gm.user_id = p.sender_id) then
      why := 'They are not in the group anymore.';
    elsif public.zchat_group_role_is_muted(p.group_id, p.sender_id) then
      why := 'They are muted right now. Unmute them first, or decline.';
    elsif exists (select 1 from public.groups g where g.id = p.group_id and g.read_only) then
      why := 'This group is read only.';
    end if;
    if why is not null then
      return jsonb_build_object('ok', false, 'reason', why);
    end if;
    x := jsonb_populate_record(null::public.messages, p.payload);
    begin
      perform set_config('zchat.g1_ok', '1', true);
      insert into public.messages (sender_id, group_id, type, content, media_url, forwarded, forwarded_from_name, reply_to_id, topic, client_id, bubble_style, text_size, text_color, text_font, overlay_url, story_id, story_owner_id, story_media_url, story_media_type, asked_at)
        values (p.sender_id, p.group_id, coalesce(x.type, 'text'), x.content, x.media_url, coalesce(x.forwarded, false), x.forwarded_from_name,
          case when x.reply_to_id is not null and exists (select 1 from public.messages q where q.id = x.reply_to_id and q.group_id = p.group_id) then x.reply_to_id end,
          x.topic, x.client_id, x.bubble_style, x.text_size, x.text_color, x.text_font, x.overlay_url, x.story_id, x.story_owner_id, x.story_media_url, x.story_media_type, p.created_at)
        returning * into r;
      perform set_config('zchat.g1_ok', '', true);
    exception when others then
      perform set_config('zchat.g1_ok', '', true);
      return jsonb_build_object('ok', false, 'reason', 'That post could not go up. Try again.');
    end;
    update public.zchat_grp_pending set status = 'approved', reviewed_by = me, reviewed_at = now(), message_id = r.id where id = p.id;
    return jsonb_build_object('ok', true, 'approved', true, 'message', to_jsonb(r), 'sender_id', p.sender_id);
  end if;
  update public.zchat_grp_pending set status = 'declined', reviewed_by = me, reviewed_at = now() where id = p.id;
  return jsonb_build_object('ok', true, 'approved', false, 'sender_id', p.sender_id);
end $$;

create or replace function public.zchat_g1_pending_drop(p_id bigint)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  n integer;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  delete from public.zchat_grp_pending where id = p_id and sender_id = me and status in ('pending', 'declined');
  get diagnostics n = row_count;
  if n = 0 then
    return jsonb_build_object('ok', false, 'reason', 'That post was already answered.', 'gone', true);
  end if;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.zchat_g1_rules_accept(p_group uuid, p_version integer)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  g record;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  select x.group_rules, x.rules_version into g from public.groups x where x.id = p_group;
  if not found or public.zchat_g1_rank(p_group, me) < 0 then
    return jsonb_build_object('ok', false, 'reason', 'You are not in this group anymore.');
  end if;
  if coalesce(p_version, -1) <> g.rules_version then
    return jsonb_build_object('ok', false, 'reason', 'The rules just changed. Read them again.', 'version', g.rules_version, 'rules', g.group_rules);
  end if;
  insert into public.zchat_grp_rules_ok (group_id, user_id, version, accepted_at)
    values (p_group, me, g.rules_version, now())
    on conflict (group_id, user_id) do update set version = excluded.version, accepted_at = excluded.accepted_at;
  return jsonb_build_object('ok', true, 'version', g.rules_version);
end $$;

create or replace function public.zchat_g1_join_answer(p_group uuid, p_answers jsonb)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  g record;
  clean jsonb := '[]'::jsonb;
  i integer;
  t text;
  n integer;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  select x.join_questions, x.join_approval into g from public.groups x where x.id = p_group;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'This group is not around anymore.');
  end if;
  if exists (select 1 from public.group_members gm where gm.group_id = p_group and gm.user_id = me) then
    return jsonb_build_object('ok', false, 'reason', 'You are already in this group.');
  end if;
  n := case when g.join_questions is null or jsonb_typeof(g.join_questions) <> 'array' then 0 else jsonb_array_length(g.join_questions) end;
  if n = 0 then
    return jsonb_build_object('ok', true, 'none', true);
  end if;
  if p_answers is null or jsonb_typeof(p_answers) <> 'array' then
    return jsonb_build_object('ok', false, 'reason', 'Answer the questions first.');
  end if;
  for i in 0 .. n - 1 loop
    t := public.zchat_g1_clean(p_answers ->> i, 300);
    if t is null then
      return jsonb_build_object('ok', false, 'reason', 'Answer every question first.');
    end if;
    clean := clean || jsonb_build_array(t);
  end loop;
  insert into public.zchat_grp_join_answers (group_id, user_id, answers, created_at)
    values (p_group, me, clean, now())
    on conflict (group_id, user_id) do update set answers = excluded.answers, created_at = excluded.created_at;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.zchat_g1_join_gate()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  q jsonb;
begin
  if auth.uid() is null or new.status <> 'pending' or new.user_id is distinct from auth.uid() then
    return new;
  end if;
  select g.join_questions into q from public.groups g where g.id = new.group_id;
  if q is not null and jsonb_typeof(q) = 'array' and jsonb_array_length(q) > 0
     and not exists (select 1 from public.zchat_grp_join_answers a where a.group_id = new.group_id and a.user_id = new.user_id and jsonb_array_length(a.answers) >= jsonb_array_length(q)) then
    raise exception 'Answer the questions to ask to join' using errcode = 'P0001';
  end if;
  return new;
end $$;

drop trigger if exists zchat_zg1_join_gate on public.group_join_requests;
create trigger zchat_zg1_join_gate
  before insert or update on public.group_join_requests
  for each row execute function public.zchat_g1_join_gate();

create or replace function public.zchat_g1_join_answers_gone()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  delete from public.zchat_grp_join_answers a where a.group_id = old.group_id and a.user_id = old.user_id;
  return null;
end $$;

drop trigger if exists zchat_zg1_join_answers_gone on public.group_join_requests;
create trigger zchat_zg1_join_answers_gone
  after delete on public.group_join_requests
  for each row execute function public.zchat_g1_join_answers_gone();

create or replace function public.zchat_g1_nick_clear(p_group uuid, p_user uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  r_me integer;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  r_me := public.zchat_g1_rank(p_group, me);
  if p_user is null or (p_user <> me and (r_me < 2 or r_me <= public.zchat_g1_rank(p_group, p_user))) then
    return jsonb_build_object('ok', false, 'reason', 'Only admins can clear someone''s name in this group.');
  end if;
  update public.group_members set nick = null where group_id = p_group and user_id = p_user and nick is not null;
  return jsonb_build_object('ok', true);
end $$;

