create or replace function public.zchat_g1_groups_guard()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  r integer;
begin
  new.welcome_text := public.zchat_g1_clean(new.welcome_text, 300, true);
  new.group_rules := public.zchat_g1_list(new.group_rules, 10, 120);
  new.join_questions := public.zchat_g1_list(new.join_questions, 3, 100);
  if tg_op = 'INSERT' then
    new.rules_version := case when new.group_rules is null then 0 else 1 end;
    return new;
  end if;
  if new.group_rules is distinct from old.group_rules then
    new.rules_version := old.rules_version + 1;
  else
    new.rules_version := old.rules_version;
  end if;
  if me is null or coalesce(current_setting('zchat.g1_ok', true), '') = '1' then
    return new;
  end if;
  if new.read_only is distinct from old.read_only
     or new.approve_posts is distinct from old.approve_posts
     or new.admin_links is distinct from old.admin_links
     or new.welcome_text is distinct from old.welcome_text
     or new.welcome_name is distinct from old.welcome_name
     or new.group_rules is distinct from old.group_rules
     or new.join_questions is distinct from old.join_questions then
    r := public.zchat_g1_rank(old.id, me);
    if new.read_only is distinct from old.read_only and r < 3 then
      raise exception 'Only the owner can change read only' using errcode = '42501';
    end if;
    if r < 2 then
      raise exception 'Only admins can change group settings' using errcode = '42501';
    end if;
  end if;
  return new;
end $$;

drop trigger if exists zchat_zg1_groups_guard on public.groups;
create trigger zchat_zg1_groups_guard
  before insert or update on public.groups
  for each row execute function public.zchat_g1_groups_guard();

create or replace function public.zchat_g1_line(p_group uuid, p_actor uuid, p_text text)
returns void
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  if p_group is null or p_actor is null or coalesce(btrim(p_text), '') = '' then
    return;
  end if;
  perform set_config('zchat.g1_ok', '1', true);
  insert into public.messages (sender_id, group_id, type, content) values (p_actor, p_group, 'system', left(p_text, 300));
  perform set_config('zchat.g1_ok', '', true);
exception when others then
  perform set_config('zchat.g1_ok', '', true);
end $$;

create or replace function public.zchat_g1_groups_lines()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  who text;
begin
  if me is null then
    return null;
  end if;
  who := public.zchat_group_role_name(me);
  if new.read_only is distinct from old.read_only then
    perform public.zchat_g1_line(new.id, me, case when new.read_only then who || ' made the group read only' else who || ' turned off read only' end);
  end if;
  if new.approve_posts is distinct from old.approve_posts then
    perform public.zchat_g1_line(new.id, me, case when new.approve_posts then who || ' turned on post approval. Admins check new posts first.' else who || ' turned off post approval' end);
  end if;
  if new.admin_links is distinct from old.admin_links then
    perform public.zchat_g1_line(new.id, me, case when new.admin_links then who || ' made links admins only' else who || ' let everyone post links' end);
  end if;
  if new.group_rules is distinct from old.group_rules then
    perform public.zchat_g1_line(new.id, me, case when new.group_rules is null then who || ' removed the group rules' when old.group_rules is null then who || ' added group rules' else who || ' updated the group rules' end);
  end if;
  return null;
end $$;

drop trigger if exists zchat_zg1_groups_lines on public.groups;
create trigger zchat_zg1_groups_lines
  after update on public.groups
  for each row execute function public.zchat_g1_groups_lines();

create or replace function public.zchat_g1_greeting(p_first text, p_text text)
returns text
language sql
immutable
as $$
  select case
    when coalesce(p_first, '') = '' then p_text
    when lower(substring(p_text from '^[[:alpha:]'']+')) = any (array['welcome', 'hi', 'hey', 'hello', 'glad', 'good', 'great', 'nice', 'thanks', 'thank', 'please', 'say', 'read', 'be', 'we', 'we''re', 'you', 'you''re', 'your', 'this', 'here', 'make', 'feel', 'take', 'check', 'so', 'enjoy', 'have', 'come', 'meet', 'join', 'it', 'it''s', 'our', 'introduce', 'tell', 'share', 'drop', 'start', 'happy', 'lovely', 'awesome', 'great'])
      then p_first || ', ' || lower(left(p_text, 1)) || substring(p_text from 2)
    else p_first || ', ' || p_text
  end
$$;

create or replace function public.zchat_g1_on_join()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  g record;
  first text;
  body text;
begin
  select x.welcome_text, x.welcome_name, x.created_by into g from public.groups x where x.id = new.group_id;
  if not found or g.welcome_text is null or new.user_id = g.created_by or public.zchat_g1_is_bot(new.user_id) then
    return null;
  end if;
  if exists (select 1 from public.zchat_grp_welcomed w where w.group_id = new.group_id and w.user_id = new.user_id and w.at > now() - interval '10 minutes') then
    return null;
  end if;
  insert into public.zchat_grp_welcomed (group_id, user_id, at) values (new.group_id, new.user_id, now())
    on conflict (group_id, user_id) do update set at = excluded.at;
  if g.welcome_name then
    select split_part(public.zchat_g1_clean(coalesce(nullif(btrim(p.name), ''), p.username), 40), ' ', 1) into first from public.profiles p where p.id = new.user_id;
  end if;
  body := public.zchat_g1_greeting(first, g.welcome_text);
  perform set_config('zchat.g1_ok', '1', true);
  insert into public.messages (sender_id, group_id, type, content, as_group)
    values (null, new.group_id, 'text', E'\u2063\u2064' || left(body, 360), true);
  perform set_config('zchat.g1_ok', '', true);
  return null;
exception when others then
  perform set_config('zchat.g1_ok', '', true);
  return null;
end $$;

drop trigger if exists zchat_zg1_on_join on public.group_members;
create trigger zchat_zg1_on_join
  after insert on public.group_members
  for each row execute function public.zchat_g1_on_join();

revoke execute on function public.zchat_g1_groups_guard() from anon, authenticated;
revoke execute on function public.zchat_g1_line(uuid, uuid, text) from anon, authenticated;
revoke execute on function public.zchat_g1_groups_lines() from anon, authenticated;
revoke execute on function public.zchat_g1_on_join() from anon, authenticated;

create or replace function public.zchat_g1_log(p_group uuid, p_actor uuid, p_action text, p_target uuid, p_detail jsonb)
returns void
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  if p_group is null or p_action is null then
    return;
  end if;
  insert into public.zchat_grp_log (group_id, actor_id, action, target_id, detail)
    select p_group, p_actor, left(p_action, 40), p_target, case when p_detail is null or p_detail = '{}'::jsonb then null else p_detail end
    where exists (select 1 from public.groups g where g.id = p_group);
  if random() < 0.03 then
    delete from public.zchat_grp_log l where l.group_id = p_group and l.created_at < now() - interval '90 days';
  end if;
exception when others then
  null;
end $$;

create or replace function public.zchat_g1_short(p_text text, p_max integer default 80)
returns text
language sql
immutable
as $$
  select case when p_text is null then null when char_length(p_text) > p_max then left(p_text, p_max - 1) || E'\u2026' else p_text end
$$;

create or replace function public.zchat_g1_log_groups()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  n jsonb;
  o jsonb;
  k text;
begin
  if tg_op = 'INSERT' then
    perform public.zchat_g1_log(new.id, coalesce(me, new.created_by), 'created', null, jsonb_build_object('name', public.zchat_g1_short(new.name)));
    return null;
  end if;
  if new.name is distinct from old.name then
    perform public.zchat_g1_log(new.id, me, 'name', null, jsonb_build_object('from', public.zchat_g1_short(old.name), 'to', public.zchat_g1_short(new.name)));
  end if;
  if new.avatar is distinct from old.avatar then
    perform public.zchat_g1_log(new.id, me, case when new.avatar is null then 'photo_off' else 'photo' end, null, null);
  end if;
  if new.bio is distinct from old.bio then
    perform public.zchat_g1_log(new.id, me, 'bio', null, null);
  end if;
  if new.created_by is distinct from old.created_by then
    perform public.zchat_g1_log(new.id, me, 'owner', new.created_by, null);
  end if;
  if new.invite_code is distinct from old.invite_code and old.invite_code is not null then
    perform public.zchat_g1_log(new.id, me, 'invite_reset', null, null);
  end if;
  if new.group_rules is distinct from old.group_rules then
    perform public.zchat_g1_log(new.id, me, 'rules', null, jsonb_build_object('n', coalesce(jsonb_array_length(new.group_rules), 0)));
  end if;
  n := to_jsonb(new);
  o := to_jsonb(old);
  foreach k in array array['send_policy', 'slow_secs', 'mention_all', 'join_approval', 'invite_enabled', 'add_members_policy', 'disappear_secs', 'wallpaper', 'accent', 'topics', 'approve_posts', 'admin_links', 'read_only', 'welcome_text', 'welcome_name', 'join_questions', 'name_bar'] loop
    if (n -> k) is distinct from (o -> k) then
      perform public.zchat_g1_log(new.id, me, 'setting', null, jsonb_build_object('key', k, 'value',
        case when k in ('welcome_text', 'topics', 'join_questions', 'wallpaper', 'accent', 'name_bar') then to_jsonb((n -> k) is not null and (n -> k) <> 'null'::jsonb) else n -> k end));
    end if;
  end loop;
  return null;
end $$;

drop trigger if exists zchat_zg1_log_groups on public.groups;
create trigger zchat_zg1_log_groups
  after insert or update on public.groups
  for each row execute function public.zchat_g1_log_groups();

create or replace function public.zchat_g1_log_members()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
begin
  if tg_op = 'INSERT' then
    if new.added_by is not null and new.added_by <> new.user_id then
      perform public.zchat_g1_log(new.group_id, new.added_by, 'added', new.user_id, null);
    elsif me is not null and me <> new.user_id then
      perform public.zchat_g1_log(new.group_id, me, 'let_in', new.user_id, null);
    else
      perform public.zchat_g1_log(new.group_id, new.user_id, 'joined', new.user_id, null);
    end if;
    return null;
  end if;
  if tg_op = 'DELETE' then
    if not exists (select 1 from public.groups g where g.id = old.group_id) then
      return null;
    end if;
    if me is not null and me <> old.user_id then
      perform public.zchat_g1_log(old.group_id, me, 'removed', old.user_id, null);
    else
      perform public.zchat_g1_log(old.group_id, old.user_id, 'left', old.user_id, null);
    end if;
    return null;
  end if;
  if new.role is distinct from old.role then
    perform public.zchat_g1_log(new.group_id, me, 'role', new.user_id, jsonb_build_object('from', coalesce(old.role, 'member'), 'to', coalesce(new.role, 'member')));
  end if;
  if coalesce(new.muted, false) is distinct from coalesce(old.muted, false) or new.muted_until is distinct from old.muted_until then
    if coalesce(new.muted, false) or (new.muted_until is not null and new.muted_until > now()) then
      perform public.zchat_g1_log(new.group_id, me, 'muted', new.user_id, jsonb_build_object('until', new.muted_until));
    else
      perform public.zchat_g1_log(new.group_id, me, 'unmuted', new.user_id, null);
    end if;
  end if;
  if new.title is distinct from old.title then
    perform public.zchat_g1_log(new.group_id, me, 'title', new.user_id, jsonb_build_object('to', public.zchat_g1_short(new.title, 40)));
  end if;
  return null;
end $$;

drop trigger if exists zchat_zg1_log_members on public.group_members;
create trigger zchat_zg1_log_members
  after insert or update or delete on public.group_members
  for each row execute function public.zchat_g1_log_members();

create or replace function public.zchat_g1_log_pending()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  t text;
begin
  if new.status is distinct from old.status and new.status in ('approved', 'declined') then
    t := coalesce(nullif(public.zchat_g1_clean(new.payload ->> 'content', 80), ''), case new.payload ->> 'type' when 'image' then 'Photo' when 'video' then 'Video' when 'audio' then 'Voice message' when 'sticker' then 'Sticker' else 'Post' end);
    if t ~ '^z[a-z]+:\{' then
      t := 'Card';
    end if;
    perform public.zchat_g1_log(new.group_id, coalesce(new.reviewed_by, auth.uid()), case when new.status = 'approved' then 'post_ok' else 'post_no' end, new.sender_id, jsonb_build_object('text', t));
  end if;
  return null;
end $$;

drop trigger if exists zchat_zg1_log_pending on public.zchat_grp_pending;
create trigger zchat_zg1_log_pending
  after update on public.zchat_grp_pending
  for each row execute function public.zchat_g1_log_pending();

create or replace function public.zchat_g1_log_messages()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
begin
  if me is null or new.group_id is null then
    return null;
  end if;
  if coalesce(new.deleted, false) and not coalesce(old.deleted, false) and old.sender_id is distinct from me then
    perform public.zchat_g1_log(new.group_id, me, 'deleted', old.sender_id, null);
  end if;
  if new.pinned_until is distinct from old.pinned_until and new.pinned_until is not null and new.pinned_until > now() and old.pinned_until is null then
    perform public.zchat_g1_log(new.group_id, me, 'pinned', old.sender_id, null);
  end if;
  return null;
end $$;

drop trigger if exists zchat_zg1_log_messages on public.messages;
create trigger zchat_zg1_log_messages
  after update of deleted, pinned_until on public.messages
  for each row
  when (new.group_id is not null and (new.deleted is distinct from old.deleted or new.pinned_until is distinct from old.pinned_until))
  execute function public.zchat_g1_log_messages();

create or replace function public.zchat_g1_log_room()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  perform public.zchat_g1_log(new.group_id, coalesce(auth.uid(), new.by_user), 'room_kick', new.user_id, null);
  return null;
end $$;

do $$
begin
  if to_regclass('public.voice_room_bans') is not null and exists (
    select 1 from information_schema.columns where table_schema = 'public' and table_name = 'voice_room_bans' and column_name = 'by_user'
  ) then
    execute 'drop trigger if exists zchat_zg1_log_room on public.voice_room_bans';
    execute 'create trigger zchat_zg1_log_room after insert on public.voice_room_bans for each row execute function public.zchat_g1_log_room()';
  end if;
end $$;

revoke execute on function public.zchat_g1_log(uuid, uuid, text, uuid, jsonb) from anon, authenticated;
revoke execute on function public.zchat_g1_log_groups() from anon, authenticated;
