create table if not exists public.zchat_grp_hidden (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  group_id uuid not null references public.groups(id) on delete cascade,
  hidden_id uuid not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  constraint zchat_grp_hidden_not_self check (user_id <> hidden_id)
);
create unique index if not exists zchat_grp_hidden_one on public.zchat_grp_hidden (user_id, group_id, hidden_id);
create index if not exists zchat_grp_hidden_by_group on public.zchat_grp_hidden (group_id, hidden_id);

alter table public.zchat_grp_hidden enable row level security;
revoke all on table public.zchat_grp_hidden from anon, authenticated;
grant select, insert, delete on table public.zchat_grp_hidden to authenticated;
grant all on table public.zchat_grp_hidden to service_role;

drop policy if exists "zchat grp hidden read own" on public.zchat_grp_hidden;
create policy "zchat grp hidden read own" on public.zchat_grp_hidden
  for select to authenticated
  using (user_id = (select auth.uid()));

drop policy if exists "zchat grp hidden add own" on public.zchat_grp_hidden;
create policy "zchat grp hidden add own" on public.zchat_grp_hidden
  for insert to authenticated
  with check (
    user_id = (select auth.uid())
    and hidden_id <> (select auth.uid())
    and exists (select 1 from public.group_members gm where gm.group_id = zchat_grp_hidden.group_id and gm.user_id = (select auth.uid()))
  );

drop policy if exists "zchat grp hidden remove own" on public.zchat_grp_hidden;
create policy "zchat grp hidden remove own" on public.zchat_grp_hidden
  for delete to authenticated
  using (user_id = (select auth.uid()));

create or replace function public.zchat_grp_hidden_gate()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  n integer;
begin
  new.created_at := now();
  if not exists (select 1 from public.group_members gm where gm.group_id = new.group_id and gm.user_id = new.hidden_id) then
    raise exception 'They are not in this group' using errcode = '22023';
  end if;
  select count(*) into n from public.zchat_grp_hidden h where h.user_id = new.user_id and h.group_id = new.group_id;
  if n >= 100 then
    raise exception 'You can hide up to 100 people in one group' using errcode = 'P0001';
  end if;
  select count(*) into n from public.zchat_grp_hidden h where h.user_id = new.user_id and h.created_at > now() - interval '1 hour';
  if n >= 60 then
    raise exception 'That is a lot of changes. Try again in a little while' using errcode = 'P0001';
  end if;
  return new;
end
$function$;

drop trigger if exists zchat_grp_hidden_gate on public.zchat_grp_hidden;
create trigger zchat_grp_hidden_gate before insert on public.zchat_grp_hidden
  for each row execute function public.zchat_grp_hidden_gate();

create or replace function public.zchat_grp_hid(p_user uuid, p_group uuid, p_sender uuid)
returns boolean
language sql
stable
security definer
set search_path to 'public'
as $function$
  select p_user is not null and p_group is not null and p_sender is not null
    and exists (select 1 from public.zchat_grp_hidden h where h.user_id = p_user and h.group_id = p_group and h.hidden_id = p_sender)
$function$;
revoke all on function public.zchat_grp_hid(uuid, uuid, uuid) from public, anon, authenticated;
grant execute on function public.zchat_grp_hid(uuid, uuid, uuid) to service_role;

do $do$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'zchat_grp_hidden') then
    execute 'alter publication supabase_realtime add table public.zchat_grp_hidden';
  end if;
end
$do$;

select public.zchat_apply_session_gate();
commit;

begin;
create table if not exists public.zchat_grp_emoji (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.groups(id) on delete cascade,
  name text not null,
  url text not null,
  path text,
  animated boolean not null default false,
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  constraint zchat_grp_emoji_name_ok check (name ~ '^[a-z][a-z0-9]{1,23}$'),
  constraint zchat_grp_emoji_url_ok check (char_length(url) between 8 and 600)
);
create unique index if not exists zchat_grp_emoji_name_one on public.zchat_grp_emoji (group_id, name);
alter table public.zchat_grp_emoji drop constraint if exists zchat_grp_emoji_name_ok;
alter table public.zchat_grp_emoji add constraint zchat_grp_emoji_name_ok check (name ~ '^[a-z][a-z0-9]{1,23}$') not valid;

alter table public.zchat_grp_emoji enable row level security;
revoke all on table public.zchat_grp_emoji from anon, authenticated;
grant select on table public.zchat_grp_emoji to authenticated;
grant all on table public.zchat_grp_emoji to service_role;

drop policy if exists "zchat grp emoji members read" on public.zchat_grp_emoji;
create policy "zchat grp emoji members read" on public.zchat_grp_emoji
  for select to authenticated
  using (exists (select 1 from public.group_members gm where gm.group_id = zchat_grp_emoji.group_id and gm.user_id = (select auth.uid())));

create or replace function public.zchat_grp_emoji_add(p_group uuid, p_name text, p_path text, p_url text)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  me uuid := auth.uid();
  nm text := lower(btrim(replace(coalesce(p_name, ''), ':', '')));
  pth text := btrim(coalesce(p_path, ''));
  u text := btrim(coalesce(p_url, ''));
  obj record;
  sz bigint;
  mt text;
  n integer;
  row public.zchat_grp_emoji%rowtype;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  if not public.zchat_session_ok() then
    raise exception 'Approve this login first' using errcode = '42501';
  end if;
  if p_group is null or public.zchat_group_role_rank(p_group, me) < 2 then
    return jsonb_build_object('ok', false, 'reason', 'Only group admins can add emoji.');
  end if;
  if nm !~ '^[a-z][a-z0-9]{1,23}$' then
    return jsonb_build_object('ok', false, 'reason', 'Start with a letter and use 2 to 24 letters or numbers.');
  end if;
  if pth !~ ('^' || me::text || '/gemoji/' || p_group::text || '/[A-Za-z0-9]{6,40}\.(png|webp|gif)$') then
    return jsonb_build_object('ok', false, 'reason', 'That picture did not upload. Try again.');
  end if;
  if u !~ '^https://' or right(u, length('/storage/v1/object/public/chat-media/' || pth)) <> '/storage/v1/object/public/chat-media/' || pth then
    return jsonb_build_object('ok', false, 'reason', 'That picture did not upload. Try again.');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('zchat_grp_emoji:' || p_group::text, 0));
  select count(*) into n from public.zchat_grp_emoji e where e.group_id = p_group;
  if n >= 50 then
    return jsonb_build_object('ok', false, 'reason', 'This group already has 50 emoji. Remove one first.');
  end if;
  if exists (select 1 from public.zchat_grp_emoji e where e.group_id = p_group and e.name = nm) then
    return jsonb_build_object('ok', false, 'reason', 'There is already an emoji called :' || nm || ':');
  end if;
  select count(*) into n from public.zchat_grp_emoji e where e.created_by = me and e.created_at > now() - interval '1 hour';
  if n >= 40 then
    return jsonb_build_object('ok', false, 'reason', 'That is a lot of emoji for one hour. Try again later.');
  end if;
  select o.metadata into obj from storage.objects o where o.bucket_id = 'chat-media' and o.name = pth limit 1;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'That picture did not upload. Try again.');
  end if;
  begin
    sz := nullif(obj.metadata ->> 'size', '')::bigint;
  exception when others then
    sz := null;
  end;
  mt := lower(coalesce(obj.metadata ->> 'mimetype', ''));
  if sz is null or sz > 102400 then
    return jsonb_build_object('ok', false, 'reason', 'Emoji must be 100 KB or smaller.');
  end if;
  if mt not in ('image/png', 'image/webp', 'image/gif') then
    return jsonb_build_object('ok', false, 'reason', 'Use a PNG, WebP or GIF picture.');
  end if;
  insert into public.zchat_grp_emoji (group_id, name, url, path, animated, created_by)
  values (p_group, nm, u, pth, mt = 'image/gif', me)
  returning * into row;
  return jsonb_build_object('ok', true, 'emoji', to_jsonb(row));
end
$function$;
revoke all on function public.zchat_grp_emoji_add(uuid, text, text, text) from public, anon;
grant execute on function public.zchat_grp_emoji_add(uuid, text, text, text) to authenticated, service_role;

create or replace function public.zchat_grp_emoji_remove(p_id uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  me uuid := auth.uid();
  g uuid;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  if not public.zchat_session_ok() then
    raise exception 'Approve this login first' using errcode = '42501';
  end if;
  select e.group_id into g from public.zchat_grp_emoji e where e.id = p_id;
  if not found then
    return jsonb_build_object('ok', true, 'gone', true);
  end if;
  if public.zchat_group_role_rank(g, me) < 2 then
    return jsonb_build_object('ok', false, 'reason', 'Only group admins can remove emoji.');
  end if;
  delete from public.zchat_grp_emoji e where e.id = p_id;
  return jsonb_build_object('ok', true);
end
$function$;
revoke all on function public.zchat_grp_emoji_remove(uuid) from public, anon;
grant execute on function public.zchat_grp_emoji_remove(uuid) to authenticated, service_role;

do $do$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'zchat_grp_emoji') then
    execute 'alter publication supabase_realtime add table public.zchat_grp_emoji';
  end if;
end
$do$;

select public.zchat_apply_session_gate();
commit;

begin;
create table if not exists public.zchat_poll_meta (
  message_id bigint primary key references public.messages(id) on delete cascade,
  group_id uuid,
  sender_id uuid,
  receiver_id uuid,
  options smallint not null,
  multi boolean not null default false,
  quiz boolean not null default false,
  anonymous boolean not null default false,
  closes_at timestamptz,
  photos text[] not null default '{}',
  finished_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists zchat_poll_meta_due on public.zchat_poll_meta (closes_at) where finished_at is null and closes_at is not null;
create index if not exists zchat_poll_meta_photos on public.zchat_poll_meta using gin (photos);

create table if not exists public.zchat_poll_tally (
  message_id bigint primary key references public.messages(id) on delete cascade,
  counts integer[] not null default '{}',
  voters integer not null default 0,
  updated_at timestamptz not null default now()
);

alter table public.zchat_poll_meta enable row level security;
alter table public.zchat_poll_tally enable row level security;
revoke all on table public.zchat_poll_meta from anon, authenticated;
revoke all on table public.zchat_poll_tally from anon, authenticated;
grant select on table public.zchat_poll_meta to authenticated;
grant select on table public.zchat_poll_tally to authenticated;
grant all on table public.zchat_poll_meta to service_role;
grant all on table public.zchat_poll_tally to service_role;

drop policy if exists "zchat poll meta read visible" on public.zchat_poll_meta;
create policy "zchat poll meta read visible" on public.zchat_poll_meta
  for select to authenticated
  using (exists (select 1 from public.messages m where m.id = zchat_poll_meta.message_id));

drop policy if exists "zchat poll tally read visible" on public.zchat_poll_tally;
create policy "zchat poll tally read visible" on public.zchat_poll_tally
  for select to authenticated
  using (exists (select 1 from public.messages m where m.id = zchat_poll_tally.message_id));

create or replace function public.zchat_poll_json(p_content text)
returns jsonb
language plpgsql
immutable
set search_path to 'public'
as $function$
declare
  j jsonb;
begin
  if p_content is null or left(p_content, 6) <> 'zpoll:' then
    return null;
  end if;
  begin
    j := substr(p_content, 7)::jsonb;
  exception when others then
    return null;
  end;
  if jsonb_typeof(j) <> 'object' or jsonb_typeof(j -> 'o') <> 'array' then
    return null;
  end if;
  return j;
end
$function$;

create or replace function public.zchat_poll_recount(p_message bigint)
returns void
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  n integer;
  cs integer[];
  nv integer;
begin
  select pm.options into n from public.zchat_poll_meta pm where pm.message_id = p_message;
  if not found then
    return;
  end if;
  with votes as (
    select string_to_array(substr(l.emoji, 4), ',')::int[] as picks
    from public.message_likes l
    where l.message_id = p_message and l.emoji ~ '^zv:[0-9]{1,2}(,[0-9]{1,2}){0,11}$'
  )
  select array(select (select count(*) from votes where i = any (votes.picks))::int from generate_series(0, n - 1) i),
         (select count(*) from votes)::int
    into cs, nv;
  insert into public.zchat_poll_tally (message_id, counts, voters, updated_at)
  values (p_message, cs, nv, now())
  on conflict (message_id) do update set counts = excluded.counts, voters = excluded.voters, updated_at = excluded.updated_at
  where zchat_poll_tally.counts is distinct from excluded.counts or zchat_poll_tally.voters is distinct from excluded.voters;
end
$function$;
revoke all on function public.zchat_poll_recount(bigint) from public, anon, authenticated;

create or replace function public.zchat_poll_meta_make(p_message bigint)
returns public.zchat_poll_meta
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  r public.zchat_poll_meta%rowtype;
  m record;
  j jsonb;
  n integer;
  c timestamptz;
  ph text[];
  q boolean;
begin
  select * into r from public.zchat_poll_meta pm where pm.message_id = p_message;
  if found then
    return r;
  end if;
  select x.id, x.sender_id, x.receiver_id, x.group_id, x.content, x.created_at into m from public.messages x where x.id = p_message;
  if not found then
    return null;
  end if;
  j := public.zchat_poll_json(m.content);
  if j is null then
    return null;
  end if;
  n := jsonb_array_length(j -> 'o');
  if n < 2 or n > 12 then
    return null;
  end if;
  begin
    c := nullif(j ->> 'e', '')::timestamptz;
  exception when others then
    c := null;
  end;
  q := case when jsonb_typeof(j -> 'a') = 'number' then (j ->> 'a')::numeric >= 0 and (j ->> 'a')::numeric < n and (j ->> 'a')::numeric = floor((j ->> 'a')::numeric) else false end;
  select coalesce(array_agg(substr(v, 4)), '{}') into ph
  from jsonb_array_elements_text(case when jsonb_typeof(j -> 'p') = 'array' then j -> 'p' else '[]'::jsonb end) v
  where v ~ ('^zp:' || m.sender_id::text || '/[A-Za-z0-9._-]{1,120}$');
  insert into public.zchat_poll_meta (message_id, group_id, sender_id, receiver_id, options, multi, quiz, anonymous, closes_at, photos, created_at)
  values (m.id, m.group_id, m.sender_id, m.receiver_id, n, (not q) and coalesce(j ->> 'm', '') in ('1', 'true'), q, coalesce(j ->> 'an', '') in ('1', 'true'), c, ph, coalesce(m.created_at, now()))
  on conflict (message_id) do nothing;
  insert into public.zchat_poll_tally (message_id, counts, voters)
  values (m.id, array_fill(0, array[n]), 0)
  on conflict (message_id) do nothing;
  perform public.zchat_poll_recount(m.id);
  select * into r from public.zchat_poll_meta pm where pm.message_id = p_message;
  return r;
end
$function$;
revoke all on function public.zchat_poll_meta_make(bigint) from public, anon, authenticated;

create or replace function public.zchat_poll_on_message()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $function$
begin
  if left(coalesce(new.content, ''), 6) = 'zpoll:' then
    begin
      perform public.zchat_poll_meta_make(new.id);
    exception when others then
      raise notice 'zchat poll meta skipped: %', sqlerrm;
    end;
  end if;
  return null;
end
$function$;

drop trigger if exists zchat_poll_on_message on public.messages;
create trigger zchat_poll_on_message after insert on public.messages
  for each row execute function public.zchat_poll_on_message();

create or replace function public.zchat_poll_guard()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  oj jsonb;
  nj jsonb;
  oe timestamptz;
  ne timestamptz;
  pm public.zchat_poll_meta%rowtype;
begin
  if left(coalesce(old.content, ''), 6) <> 'zpoll:' or new.content is not distinct from old.content then
    return new;
  end if;
  if new.content is null or coalesce(new.deleted, false) then
    return new;
  end if;
  if coalesce(nullif(current_setting('role', true), ''), 'none') not in ('authenticated', 'anon') then
    return new;
  end if;
  oj := public.zchat_poll_json(old.content);
  if oj is null then
    return new;
  end if;
  nj := public.zchat_poll_json(new.content);
  if nj is null or (oj - 'e') is distinct from (nj - 'e') then
    raise exception 'A poll cannot be changed after it is sent' using errcode = '42501';
  end if;
  begin
    ne := nullif(nj ->> 'e', '')::timestamptz;
  exception when others then
    raise exception 'That closing time is not valid' using errcode = '22023';
  end;
  pm := public.zchat_poll_meta_make(old.id);
  oe := pm.closes_at;
  if oe is not null and oe <= now() then
    raise exception 'This poll has already closed' using errcode = 'P0001';
  end if;
  if ne is null or (oe is not null and ne > oe) then
    raise exception 'A poll can close earlier, not later' using errcode = 'P0001';
  end if;
  update public.zchat_poll_meta set closes_at = ne where message_id = old.id;
  return new;
end
$function$;

drop trigger if exists zchat_poll_guard on public.messages;
create trigger zchat_poll_guard before update of content on public.messages
  for each row execute function public.zchat_poll_guard();

create or replace function public.zchat_poll_vote_guard()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  mid bigint;
  vote_new boolean := false;
  vote_old boolean := false;
  pm public.zchat_poll_meta%rowtype;
  s text;
  picks integer[];
begin
  if coalesce(nullif(current_setting('role', true), ''), 'none') not in ('authenticated', 'anon') then
    return coalesce(new, old);
  end if;
  if tg_op = 'DELETE' then
    if left(coalesce(old.emoji, ''), 3) <> 'zv:' then
      return old;
    end if;
    vote_old := true;
    mid := old.message_id;
  else
    vote_new := left(coalesce(new.emoji, ''), 3) = 'zv:';
    vote_old := tg_op = 'UPDATE' and left(coalesce(old.emoji, ''), 3) = 'zv:';
    if not vote_new and not vote_old then
      return new;
    end if;
    mid := new.message_id;
  end if;
  if not exists (select 1 from public.messages m where m.id = mid and left(coalesce(m.content, ''), 6) = 'zpoll:' and not coalesce(m.deleted, false)) then
    return coalesce(new, old);
  end if;
  pm := public.zchat_poll_meta_make(mid);
  if pm.message_id is null then
    return coalesce(new, old);
  end if;
  if pm.closes_at is not null and pm.closes_at <= now() then
    raise exception 'Voting has ended for this poll' using errcode = 'P0001';
  end if;
  if tg_op = 'DELETE' then
    if pm.quiz and old.emoji ~ '^zv:[0-9]' then
      raise exception 'Quiz answers cannot be changed' using errcode = 'P0001';
    end if;
    return old;
  end if;
  if pm.quiz and vote_old and old.emoji ~ '^zv:[0-9]' and new.emoji is distinct from old.emoji then
    raise exception 'Quiz answers cannot be changed' using errcode = 'P0001';
  end if;
  if not vote_new then
    return new;
  end if;
  s := substr(new.emoji, 4);
  if s = '' then
    new.super_key := null;
    return new;
  end if;
  if s !~ '^[0-9]{1,2}(,[0-9]{1,2}){0,11}$' then
    raise exception 'That vote is not valid' using errcode = '22023';
  end if;
  select array_agg(distinct x order by x) into picks from unnest(string_to_array(s, ',')::int[]) x;
  if exists (select 1 from unnest(picks) x where x < 0 or x >= pm.options) then
    raise exception 'That vote is not valid' using errcode = '22023';
  end if;
  if cardinality(picks) > 1 and not pm.multi then
    raise exception 'Pick one answer in this poll' using errcode = '22023';
  end if;
  new.emoji := 'zv:' || array_to_string(picks, ',');
  new.super_key := null;
  return new;
end
$function$;

drop trigger if exists zchat_poll_vote_guard on public.message_likes;
create trigger zchat_poll_vote_guard before insert or update or delete on public.message_likes
  for each row execute function public.zchat_poll_vote_guard();

create or replace function public.zchat_poll_tally_sync()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  mid bigint;
begin
  if tg_op = 'DELETE' then
    if left(coalesce(old.emoji, ''), 3) <> 'zv:' then
      return null;
    end if;
    mid := old.message_id;
  else
    if left(coalesce(new.emoji, ''), 3) <> 'zv:' and not (tg_op = 'UPDATE' and left(coalesce(old.emoji, ''), 3) = 'zv:') then
      return null;
    end if;
    mid := new.message_id;
  end if;
  if exists (select 1 from public.zchat_poll_meta pm where pm.message_id = mid) then
    perform public.zchat_poll_recount(mid);
  end if;
  return null;
exception when others then
  return null;
end
$function$;

drop trigger if exists zchat_poll_tally_sync on public.message_likes;
create trigger zchat_poll_tally_sync after insert or update or delete on public.message_likes
  for each row execute function public.zchat_poll_tally_sync();

create or replace function public.zchat_poll_is_anon(p_message bigint)
returns boolean
language sql
stable
security definer
set search_path to 'public'
as $function$
  select coalesce(
    (select pm.anonymous from public.zchat_poll_meta pm where pm.message_id = p_message),
    (select coalesce(public.zchat_poll_json(m.content) ->> 'an', '') in ('1', 'true') from public.messages m where m.id = p_message),
    false
  )
$function$;
revoke all on function public.zchat_poll_is_anon(bigint) from public, anon;
grant execute on function public.zchat_poll_is_anon(bigint) to authenticated, service_role;

drop policy if exists "zchat poll votes private" on public.message_likes;
create policy "zchat poll votes private" on public.message_likes
  as restrictive for select to authenticated
  using (user_id = (select auth.uid()) or left(coalesce(emoji, ''), 3) <> 'zv:' or not public.zchat_poll_is_anon(message_id));

create or replace function public.zchat_poll_counts(p_ids bigint[])
returns jsonb
language sql
stable
security invoker
set search_path to 'public'
as $function$
  select jsonb_build_object(
    'now', (extract(epoch from clock_timestamp()) * 1000)::bigint,
    'polls', coalesce((
      select jsonb_agg(jsonb_build_object('id', t.message_id, 'counts', to_jsonb(t.counts), 'voters', t.voters, 'closes_at', pm.closes_at, 'anonymous', pm.anonymous, 'finished', pm.finished_at is not null))
      from public.zchat_poll_tally t
      join public.zchat_poll_meta pm on pm.message_id = t.message_id
      where t.message_id = any ((coalesce(p_ids, '{}'::bigint[]))[1:200])
    ), '[]'::jsonb)
  )
$function$;
revoke all on function public.zchat_poll_counts(bigint[]) from public, anon;
grant execute on function public.zchat_poll_counts(bigint[]) to authenticated, service_role;

create or replace function public.zchat_poll_finish_one(p_message bigint)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  pm public.zchat_poll_meta%rowtype;
  t public.zchat_poll_tally%rowtype;
  m record;
  j jsonb;
  q text;
  top integer;
  winners text[];
  txt text;
  right_n integer;
begin
  update public.zchat_poll_meta set finished_at = now()
  where message_id = p_message and finished_at is null and closes_at is not null and closes_at <= now()
  returning * into pm;
  if not found then
    return null;
  end if;
  select x.content, x.deleted, x.sender_id, x.receiver_id, x.group_id into m from public.messages x where x.id = p_message;
  if not found or coalesce(m.deleted, false) then
    return null;
  end if;
  j := public.zchat_poll_json(m.content);
  if j is null then
    return null;
  end if;
  perform public.zchat_poll_recount(p_message);
  select * into t from public.zchat_poll_tally x where x.message_id = p_message;
  q := left(btrim(coalesce(j ->> 'q', '')), 80);
  top := coalesce((select max(c) from unnest(t.counts) c), 0);
  if coalesce(t.voters, 0) = 0 or top = 0 then
    txt := 'No one voted.';
  elsif pm.quiz then
    right_n := coalesce(t.counts[(j ->> 'a')::int + 1], 0);
    txt := t.voters || case when t.voters = 1 then ' person answered, ' else ' people answered, ' end || right_n || ' got it right.';
  else
    select array_agg(left(o.value, 40) order by o.ordinality) into winners
    from jsonb_array_elements_text(j -> 'o') with ordinality o
    where t.counts[o.ordinality::int] = top;
    if cardinality(winners) = 1 then
      txt := winners[1] || ' won with ' || top || case when top = 1 then ' vote.' else ' votes.' end;
    else
      txt := array_to_string(winners[1:3], ' and ') || ' tied with ' || top || case when top = 1 then ' vote each.' else ' votes each.' end;
    end if;
  end if;
  perform public.zchat_notify(m.sender_id, case when m.group_id is null then m.receiver_id else null end, 'poll', null, txt,
    jsonb_build_object('message_id', p_message, 'group_id', m.group_id, 'q', q, 'voters', coalesce(t.voters, 0)));
  return jsonb_build_object('creator', m.sender_id, 'q', q, 'text', txt, 'group_id', m.group_id, 'voters', coalesce(t.voters, 0));
end
$function$;
revoke all on function public.zchat_poll_finish_one(bigint) from public, anon, authenticated;

create or replace function public.zchat_poll_finish(p_message bigint)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  me uuid := auth.uid();
  m record;
  r jsonb;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  select x.sender_id, x.receiver_id, x.group_id into m from public.messages x where x.id = p_message;
  if not found then
    return jsonb_build_object('ok', false);
  end if;
  if not ((m.group_id is null and me in (m.sender_id, m.receiver_id))
      or (m.group_id is not null and exists (select 1 from public.group_members gm where gm.group_id = m.group_id and gm.user_id = me))) then
    return jsonb_build_object('ok', false);
  end if;
  r := public.zchat_poll_finish_one(p_message);
  if r is null then
    return jsonb_build_object('ok', true, 'first', false);
  end if;
  return r || jsonb_build_object('ok', true, 'first', true);
end
$function$;
revoke all on function public.zchat_poll_finish(bigint) from public, anon;
grant execute on function public.zchat_poll_finish(bigint) to authenticated, service_role;

create or replace function public.zchat_poll_tick()
returns integer
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  r record;
  n integer := 0;
begin
  for r in
    select pm.message_id from public.zchat_poll_meta pm
    where pm.finished_at is null and pm.closes_at is not null and pm.closes_at <= now() and pm.closes_at > now() - interval '3 days'
    order by pm.closes_at
    limit 300
  loop
    begin
      if public.zchat_poll_finish_one(r.message_id) is not null then
        n := n + 1;
      end if;
    exception when others then
      raise notice 'zchat poll tick skipped %: %', r.message_id, sqlerrm;
    end;
  end loop;
  update public.zchat_poll_meta set finished_at = now() where finished_at is null and closes_at < now() - interval '3 days';
  return n;
end
$function$;
revoke all on function public.zchat_poll_tick() from public, anon, authenticated;
grant execute on function public.zchat_poll_tick() to service_role;

do $do$
begin
  if exists (select 1 from pg_namespace where nspname = 'cron') then
    perform cron.schedule('zchat-polls', '* * * * *', 'select public.zchat_poll_tick()');
  end if;
end
$do$;

CREATE OR REPLACE FUNCTION public.zchat_can_read_media(p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  ok boolean := false;
begin
  if me is null or p_name is null then
    return false;
  end if;
  if split_part(p_name, '/', 1) = me::text or public.zchat_is_admin_id(me) then
    return true;
  end if;
  select exists (
    select 1 from public.messages m
    where m.media_url = 'zp:' || p_name
      and (m.sender_id = me or m.receiver_id = me
        or (m.group_id is not null and exists (select 1 from public.group_members gm where gm.group_id = m.group_id and gm.user_id = me)))
      and not (
        m.sender_id <> me and coalesce(m.content, '') like 'zonce:%'
        and exists (select 1 from public.message_likes l where l.message_id = m.id and l.user_id = me and l.emoji = 'zo')
      )
  ) into ok;
  if ok then
    return true;
  end if;
  select exists (
    select 1 from public.zchat_capsules c
    join public.messages m on m.id = c.message_id
    where c.media_path = p_name
      and c.open_at <= now()
      and not coalesce(m.deleted, false)
      and (c.receiver_id = me or (c.group_id is not null and exists (select 1 from public.group_members gm where gm.group_id = c.group_id and gm.user_id = me)))
  ) into ok;
  if ok then
    return true;
  end if;
  select exists (
    select 1 from public.album_photos ph join public.albums a on a.id = ph.album_id
    where ph.media_url = 'zp:' || p_name and public.zchat_in_chat(a.chat_key)
  ) into ok;
  if ok then
    return true;
  end if;
  begin
    select exists (
      select 1 from public.zchat_poll_meta pm
      join public.messages m on m.id = pm.message_id
      where pm.photos @> array[p_name]
        and not coalesce(m.deleted, false)
        and (m.sender_id = me or m.receiver_id = me
          or (m.group_id is not null and exists (select 1 from public.group_members gm where gm.group_id = m.group_id and gm.user_id = me)))
    ) into ok;
  exception when others then
    ok := false;
  end;
  if ok then
    return true;
  end if;
  begin
    execute 'select exists (select 1 from public.saved_messages s where s.user_id = $1 and s.media_url = $2)' into ok using me, 'zp:' || p_name;
  exception when others then
    ok := false;
  end;
  return coalesce(ok, false);
end $function$;

do $do$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'zchat_poll_tally') then
    execute 'alter publication supabase_realtime add table public.zchat_poll_tally';
  end if;
end
$do$;

select public.zchat_apply_session_gate();
commit;

begin;
create table if not exists public.zchat_grp_keywords (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  group_id uuid not null references public.groups(id) on delete cascade,
  words text[] not null default '{}',
  updated_at timestamptz not null default now(),
  constraint zchat_grp_keywords_one unique (user_id, group_id),
  constraint zchat_grp_keywords_count check (cardinality(words) <= 10)
);
create index if not exists zchat_grp_keywords_group on public.zchat_grp_keywords (group_id);

alter table public.zchat_grp_keywords enable row level security;
revoke all on table public.zchat_grp_keywords from anon, authenticated;
grant select, insert, update, delete on table public.zchat_grp_keywords to authenticated;
grant all on table public.zchat_grp_keywords to service_role;

drop policy if exists "zchat grp keywords read own" on public.zchat_grp_keywords;
create policy "zchat grp keywords read own" on public.zchat_grp_keywords
  for select to authenticated
  using (user_id = (select auth.uid()));

drop policy if exists "zchat grp keywords add own" on public.zchat_grp_keywords;
create policy "zchat grp keywords add own" on public.zchat_grp_keywords
  for insert to authenticated
  with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.group_members gm where gm.group_id = zchat_grp_keywords.group_id and gm.user_id = (select auth.uid()))
  );

drop policy if exists "zchat grp keywords change own" on public.zchat_grp_keywords;
create policy "zchat grp keywords change own" on public.zchat_grp_keywords
  for update to authenticated
  using (user_id = (select auth.uid()))
  with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.group_members gm where gm.group_id = zchat_grp_keywords.group_id and gm.user_id = (select auth.uid()))
  );

drop policy if exists "zchat grp keywords remove own" on public.zchat_grp_keywords;
create policy "zchat grp keywords remove own" on public.zchat_grp_keywords
  for delete to authenticated
  using (user_id = (select auth.uid()));

create or replace function public.zchat_re_escape(p text)
returns text
language sql
immutable
set search_path to 'public'
as $function$
  select regexp_replace(coalesce(p, ''), '([][(){}.*+?^$|\\])', '\\\1', 'g')
$function$;

create or replace function public.zchat_grp_keywords_clean()
returns trigger
language plpgsql
set search_path to 'public'
as $function$
declare
  out_words text[] := '{}';
  w text;
begin
  if tg_op = 'UPDATE' and (new.user_id is distinct from old.user_id or new.group_id is distinct from old.group_id) then
    raise exception 'This cannot be moved' using errcode = '42501';
  end if;
  foreach w in array coalesce(new.words, '{}') loop
    w := lower(btrim(regexp_replace(coalesce(w, ''), '[[:space:][:cntrl:]]+', ' ', 'g')));
    if char_length(w) < 2 or char_length(w) > 40 or w !~ '[[:alnum:]]' then
      continue;
    end if;
    if not (w = any (out_words)) then
      out_words := out_words || w;
    end if;
  end loop;
  if cardinality(out_words) > 10 then
    raise exception 'You can have up to 10 words in one group' using errcode = 'P0001';
  end if;
  new.words := out_words;
  new.updated_at := now();
  return new;
end
$function$;

drop trigger if exists zchat_grp_keywords_clean on public.zchat_grp_keywords;
create trigger zchat_grp_keywords_clean before insert or update on public.zchat_grp_keywords
  for each row execute function public.zchat_grp_keywords_clean();

create or replace function public.zchat_kw_hit(p_text text, p_words text[])
returns text
language sql
immutable
set search_path to 'public'
as $function$
  select w from unnest(coalesce(p_words, '{}')) w
  where coalesce(p_text, '') ~* ('(^|[^[:alnum:]_])' || public.zchat_re_escape(w) || '($|[^[:alnum:]_])')
  limit 1
$function$;

create or replace function public.zchat_grp_kw_any(p_group uuid)
returns boolean
language sql
stable
security definer
set search_path to 'public'
as $function$
  select auth.uid() is not null
    and exists (select 1 from public.group_members gm where gm.group_id = p_group and gm.user_id = auth.uid())
    and exists (select 1 from public.zchat_grp_keywords k where k.group_id = p_group and k.user_id <> auth.uid() and cardinality(k.words) > 0)
$function$;
revoke all on function public.zchat_grp_kw_any(uuid) from public, anon;
grant execute on function public.zchat_grp_kw_any(uuid) to authenticated, service_role;

do $do$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'zchat_grp_keywords') then
    execute 'alter publication supabase_realtime add table public.zchat_grp_keywords';
  end if;
end
$do$;

select public.zchat_apply_session_gate();

create table if not exists public.zchat_grp_alerts (
  id bigint generated always as identity primary key,
  message_id bigint not null references public.messages(id) on delete cascade,
  group_id uuid not null,
  sender_id uuid not null,
  user_id uuid not null references public.profiles(id) on delete cascade,
  kind text not null,
  word text,
  pushed_at timestamptz,
  created_at timestamptz not null default now(),
  constraint zchat_grp_alerts_kind_ok check (kind in ('kw', 'admins'))
);
create unique index if not exists zchat_grp_alerts_one on public.zchat_grp_alerts (message_id, user_id);
create index if not exists zchat_grp_alerts_tags on public.zchat_grp_alerts (sender_id, group_id, created_at) where kind = 'admins';
create index if not exists zchat_grp_alerts_time on public.zchat_grp_alerts (created_at);

alter table public.zchat_grp_alerts enable row level security;
revoke all on table public.zchat_grp_alerts from anon, authenticated;
grant select on table public.zchat_grp_alerts to authenticated;
grant all on table public.zchat_grp_alerts to service_role;

drop policy if exists "zchat grp alerts read own" on public.zchat_grp_alerts;
create policy "zchat grp alerts read own" on public.zchat_grp_alerts
  for select to authenticated
  using (user_id = (select auth.uid()));

CREATE OR REPLACE FUNCTION public.zchat_marks_on_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_reply uuid;
  v_handles text[];
  v_all boolean := false;
  v_admins boolean := false;
  v_kw boolean := false;
  v_text text;
begin
  if new.type = 'system' or coalesce(new.deleted, false) or new.sender_id is null then
    return null;
  end if;
  if new.group_id is not null and new.content is not null and new.type in ('text', 'image', 'video') and new.content !~ '^z[a-z]{2,10}:[\[{]'
     and exists (select 1 from public.zchat_grp_keywords k where k.group_id = new.group_id and k.user_id <> new.sender_id and cardinality(k.words) > 0) then
    v_kw := true;
  end if;
  if new.reply_to_id is null and not v_kw and (new.type <> 'text' or position('@' in coalesce(new.content, '')) = 0) then
    return null;
  end if;
  begin
    if new.reply_to_id is not null then
      select m.sender_id into v_reply
      from public.messages m
      where m.id = new.reply_to_id
        and not coalesce(m.deleted, false)
        and m.group_id is not distinct from new.group_id
        and (new.group_id is not null or (m.sender_id in (new.sender_id, new.receiver_id) and m.receiver_id in (new.sender_id, new.receiver_id)));
      if v_reply = new.sender_id then
        v_reply := null;
      end if;
    end if;
    if new.type = 'text' and position('@' in coalesce(new.content, '')) > 0 then
      select array_agg(distinct h) into v_handles
      from (
        select lower(regexp_replace(x[2], '\.+$', '')) as h
        from regexp_matches(left(new.content, 4000), '(^|[^a-zA-Z0-9._@])@([a-zA-Z0-9._]{3,30})', 'g') as x
      ) s
      where length(h) >= 3;
    end if;
    if v_reply is null and v_handles is null and not v_kw then
      return null;
    end if;
    if new.group_id is null then
      if v_reply is null and v_handles is null then
        return null;
      end if;
      if new.receiver_id is null or new.receiver_id = new.sender_id or public.zchat_blocked_pair(new.sender_id, new.receiver_id) then
        return null;
      end if;
      insert into public.zchat_chat_marks (user_id, message_id, kind, chat_key, actor_id)
      select p.id, new.id, 'at', 'dm-' || new.sender_id, new.sender_id
      from public.profiles p
      where p.id = new.receiver_id
        and not coalesce(p.is_bot, false)
        and not coalesce(p.is_deleted, false)
        and (
          p.id = v_reply
          or (v_handles is not null and lower(p.username) = any (v_handles) and public.zchat_can_interact_as(new.sender_id, 'mention', p.id))
        )
      on conflict do nothing;
      return null;
    end if;
    if v_handles && array['everyone', 'all'] then
      select coalesce(g.mention_all, 'everyone') <> 'admins'
          or g.created_by = new.sender_id
          or exists (select 1 from public.group_members a where a.group_id = g.id and a.user_id = new.sender_id and a.role = 'admin')
        into v_all
      from public.groups g
      where g.id = new.group_id;
    end if;
    if v_handles && array['admins'] then
      perform pg_advisory_xact_lock(hashtextextended('zchat_grp_admins:' || new.sender_id::text || ':' || new.group_id::text, 0));
      v_admins := (
        select count(distinct a.message_id) from public.zchat_grp_alerts a
        where a.sender_id = new.sender_id and a.group_id = new.group_id and a.kind = 'admins' and a.created_at > now() - interval '1 hour'
      ) < 5;
    end if;
    if v_admins then
      insert into public.zchat_grp_alerts (message_id, group_id, sender_id, user_id, kind, pushed_at)
      select new.id, new.group_id, new.sender_id, gm.user_id, 'admins', now()
      from public.group_members gm
      join public.groups g on g.id = gm.group_id
      join public.profiles p on p.id = gm.user_id
      where gm.group_id = new.group_id
        and gm.user_id <> new.sender_id
        and (gm.role = 'admin' or g.created_by = gm.user_id)
        and not coalesce(p.is_bot, false)
        and not coalesce(p.is_deleted, false)
        and not public.zchat_grp_hid(gm.user_id, new.group_id, new.sender_id)
        and not public.zchat_blocked_pair(new.sender_id, gm.user_id)
      on conflict do nothing;
    end if;
    if v_reply is not null or v_handles is not null then
      insert into public.zchat_chat_marks (user_id, message_id, kind, chat_key, actor_id)
      select gm.user_id, new.id, 'at', 'group-' || new.group_id, new.sender_id
      from public.group_members gm
      join public.groups g on g.id = gm.group_id
      join public.profiles p on p.id = gm.user_id
      where gm.group_id = new.group_id
        and gm.user_id <> new.sender_id
        and not coalesce(p.is_bot, false)
        and not coalesce(p.is_deleted, false)
        and (
          gm.user_id = v_reply
          or coalesce(v_all, false)
          or (v_admins and (gm.role = 'admin' or g.created_by = gm.user_id))
          or (v_handles is not null and lower(p.username) = any (v_handles) and public.zchat_can_interact_as(new.sender_id, 'mention', gm.user_id))
        )
        and not public.zchat_blocked_pair(new.sender_id, gm.user_id)
        and not public.zchat_grp_hid(gm.user_id, new.group_id, new.sender_id)
      on conflict do nothing;
    end if;
    if v_kw then
      v_text := left(new.content, 4000);
      insert into public.zchat_grp_alerts (message_id, group_id, sender_id, user_id, kind, word)
      select new.id, new.group_id, new.sender_id, k.user_id, 'kw', public.zchat_kw_hit(v_text, k.words)
      from public.zchat_grp_keywords k
      join public.group_members gm on gm.group_id = k.group_id and gm.user_id = k.user_id
      join public.profiles p on p.id = k.user_id
      where k.group_id = new.group_id
        and k.user_id <> new.sender_id
        and cardinality(k.words) > 0
        and not coalesce(p.is_deleted, false)
        and public.zchat_kw_hit(v_text, k.words) is not null
        and not exists (select 1 from public.zchat_chat_marks cm where cm.user_id = k.user_id and cm.message_id = new.id)
        and not public.zchat_blocked_pair(new.sender_id, k.user_id)
        and not public.zchat_grp_hid(k.user_id, new.group_id, new.sender_id)
      on conflict do nothing;
      insert into public.zchat_chat_marks (user_id, message_id, kind, chat_key, actor_id)
      select a.user_id, new.id, 'at', 'group-' || new.group_id, new.sender_id
      from public.zchat_grp_alerts a
      where a.message_id = new.id and a.kind = 'kw'
      on conflict do nothing;
    end if;
  exception when others then
    return null;
  end;
  return null;
end $function$;

create or replace function public.zchat_grp_alert_claim(p_caller uuid, p_message bigint)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  m record;
  g record;
  s record;
  targets jsonb;
begin
  if p_caller is null or p_message is null then
    return jsonb_build_object('ok', false);
  end if;
  select x.id, x.sender_id, x.group_id, x.content, x.type, x.created_at, x.deleted into m
  from public.messages x
  where x.id = p_message and x.sender_id = p_caller and x.group_id is not null;
  if not found or coalesce(m.deleted, false) or m.created_at < now() - interval '10 minutes' then
    return jsonb_build_object('ok', false);
  end if;
  select gg.id, gg.name, gg.avatar into g from public.groups gg where gg.id = m.group_id;
  select p.name, p.avatar, coalesce(p.banned, false) as banned, coalesce(p.is_deleted, false) as gone into s from public.profiles p where p.id = p_caller;
  if not found or s.banned or s.gone then
    return jsonb_build_object('ok', false);
  end if;
  with claimed as (
    update public.zchat_grp_alerts a set pushed_at = now()
    where a.id in (
      select a2.id from public.zchat_grp_alerts a2
      where a2.message_id = p_message and a2.kind = 'kw' and a2.pushed_at is null
      order by a2.id
      limit 200
    )
    returning a.user_id, a.word
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'user_id', c.user_id,
    'word', c.word,
    'subs', coalesce((
      select jsonb_agg(jsonb_build_object('endpoint', ps.endpoint, 'p256dh', ps.p256dh, 'auth', ps.auth))
      from (
        select x.endpoint, x.p256dh, x.auth from public.push_subscriptions x
        where x.user_id = c.user_id and x.endpoint is not null
        order by x.seen_at desc nulls last, x.id
        limit 10
      ) ps
    ), '[]'::jsonb)
  )), '[]'::jsonb) into targets
  from claimed c
  join public.profiles tp on tp.id = c.user_id
  join public.group_members gm on gm.group_id = m.group_id and gm.user_id = c.user_id
  where not coalesce(tp.banned, false) and not coalesce(tp.is_deleted, false)
    and gm.notify_muted_until is not null and gm.notify_muted_until > now();
  return jsonb_build_object(
    'ok', true,
    'group', jsonb_build_object('id', g.id, 'name', g.name, 'avatar', g.avatar),
    'sender', jsonb_build_object('name', s.name, 'avatar', s.avatar),
    'preview', left(case when m.type = 'text' then coalesce(m.content, '') else coalesce(nullif(m.content, ''), 'Photo') end, 160),
    'targets', targets
  );
end
$function$;
revoke all on function public.zchat_grp_alert_claim(uuid, bigint) from public, anon, authenticated;
grant execute on function public.zchat_grp_alert_claim(uuid, bigint) to service_role;

create or replace function public.zchat_grp_alerts_purge()
returns void
language sql
security definer
set search_path to 'public'
as $function$
  delete from public.zchat_grp_alerts where created_at < now() - interval '7 days';
$function$;
revoke all on function public.zchat_grp_alerts_purge() from public, anon, authenticated;
grant execute on function public.zchat_grp_alerts_purge() to service_role;

do $do$
begin
  if exists (select 1 from pg_namespace where nspname = 'cron') then
    perform cron.schedule('zchat-grp-alerts-purge', '41 4 * * *', 'select public.zchat_grp_alerts_purge()');
  end if;
end
$do$;

CREATE OR REPLACE FUNCTION public.zchat_push_gate(p_caller uuid, p_target uuid, p_tag text DEFAULT NULL::text, p_clear boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  t text := nullif(btrim(coalesce(p_tag, '')), '');
  c_banned boolean;
  c_gone boolean;
  t_banned boolean;
  t_gone boolean;
  n integer;
  n_targets integer;
  subs jsonb;
begin
  if p_caller is null or p_target is null then
    return jsonb_build_object('ok', false, 'why', 'input');
  end if;
  if t is not null and (length(t) > 100 or t !~ '^[A-Za-z][A-Za-z0-9-]*$') then
    t := null;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('zchat_push:' || p_caller::text, 0));
  if random() < 0.02 then
    delete from public.zchat_push_log where at < now() - interval '2 hours';
    delete from public.zchat_push_tags where greatest(coalesce(pushed_at, '-infinity'::timestamptz), coalesce(cleared_at, '-infinity'::timestamptz)) < now() - interval '14 days';
  end if;

  if coalesce(p_clear, false) then
    if p_target <> p_caller or t is null then
      return jsonb_build_object('ok', false, 'why', 'input');
    end if;
    update public.zchat_push_tags
      set cleared_at = clock_timestamp()
      where user_id = p_caller and tag = t and pushed_at is not null and pushed_at > coalesce(cleared_at, '-infinity'::timestamptz);
    if not found then
      return jsonb_build_object('ok', false, 'why', 'nothing');
    end if;
    select coalesce(jsonb_agg(jsonb_build_object('endpoint', s.endpoint, 'p256dh', s.p256dh, 'auth', s.auth)), '[]'::jsonb)
      into subs
      from (
        select endpoint, p256dh, auth from public.push_subscriptions
        where user_id = p_caller and sw >= 1 and endpoint is not null
        order by seen_at desc nulls last, id
        limit 10
      ) s;
    return jsonb_build_object('ok', true, 'subs', subs);
  end if;

  select coalesce(p.banned, false), coalesce(p.is_deleted, false) into c_banned, c_gone from public.profiles p where p.id = p_caller;
  if not found or c_banned or c_gone then
    return jsonb_build_object('ok', false, 'why', 'caller');
  end if;
  if p_target <> p_caller then
    select coalesce(p.banned, false), coalesce(p.is_deleted, false) into t_banned, t_gone from public.profiles p where p.id = p_target;
    if not found or t_banned or t_gone then
      return jsonb_build_object('ok', false, 'why', 'target');
    end if;
    if exists (
      select 1 from public.blocks b
      where (b.blocker_id = p_caller and b.blocked_id = p_target) or (b.blocker_id = p_target and b.blocked_id = p_caller)
    ) then
      return jsonb_build_object('ok', false, 'why', 'blocked');
    end if;
    if t is not null and t ~ '^group-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       and public.zchat_grp_hid(p_target, substr(t, 7)::uuid, p_caller) then
      return jsonb_build_object('ok', false, 'why', 'hidden');
    end if;
  end if;

  select count(*) into n from public.zchat_push_log where caller = p_caller and target = p_target and at > now() - interval '1 minute';
  if n >= 30 then
    return jsonb_build_object('ok', false, 'why', 'busy');
  end if;
  select count(*) into n from public.zchat_push_log where caller = p_caller and target = p_target and at > now() - interval '1 hour';
  if n >= 300 then
    return jsonb_build_object('ok', false, 'why', 'busy');
  end if;
  select count(*) into n from public.zchat_push_log where caller = p_caller and at > now() - interval '1 minute';
  if n >= 1200 then
    return jsonb_build_object('ok', false, 'why', 'busy');
  end if;
  select count(*), count(distinct target) into n, n_targets from public.zchat_push_log where caller = p_caller and at > now() - interval '1 hour';
  if n >= 6000 then
    return jsonb_build_object('ok', false, 'why', 'busy');
  end if;
  if n_targets >= 1000 and not exists (
    select 1 from public.zchat_push_log where caller = p_caller and target = p_target and at > now() - interval '1 hour'
  ) then
    return jsonb_build_object('ok', false, 'why', 'busy');
  end if;

  insert into public.zchat_push_log (caller, target) values (p_caller, p_target);

  select coalesce(jsonb_agg(jsonb_build_object('endpoint', s.endpoint, 'p256dh', s.p256dh, 'auth', s.auth)), '[]'::jsonb)
    into subs
    from (
      select endpoint, p256dh, auth from public.push_subscriptions
      where user_id = p_target and endpoint is not null
      order by seen_at desc nulls last, id
      limit 10
    ) s;
  if t is not null and jsonb_array_length(subs) > 0 then
    insert into public.zchat_push_tags (user_id, tag, pushed_at) values (p_target, t, clock_timestamp())
    on conflict (user_id, tag) do update set pushed_at = excluded.pushed_at;
  end if;
  return jsonb_build_object('ok', true, 'subs', subs);
end
$function$;

select public.zchat_apply_session_gate();
commit;

begin;
create table if not exists public.zchat_grp_links (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.groups(id) on delete cascade,
  code text not null,
  name text not null,
  expires_at timestamptz,
  max_uses integer,
  uses integer not null default 0,
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint zchat_grp_links_code_ok check (code ~ '^[A-Za-z0-9]{10,40}$'),
  constraint zchat_grp_links_name_ok check (char_length(name) between 1 and 32),
  constraint zchat_grp_links_max_ok check (max_uses is null or max_uses between 1 and 100000)
);
create unique index if not exists zchat_grp_links_code_one on public.zchat_grp_links (code);
create index if not exists zchat_grp_links_group on public.zchat_grp_links (group_id);

create table if not exists public.zchat_grp_link_joins (
  link_id uuid not null references public.zchat_grp_links(id) on delete cascade,
  group_id uuid not null,
  user_id uuid not null,
  joined_at timestamptz,
  created_at timestamptz not null default now(),
  primary key (link_id, user_id)
);
create index if not exists zchat_grp_link_joins_open on public.zchat_grp_link_joins (group_id, user_id) where joined_at is null;

alter table public.zchat_grp_links enable row level security;
alter table public.zchat_grp_link_joins enable row level security;
revoke all on table public.zchat_grp_links from anon, authenticated;
revoke all on table public.zchat_grp_link_joins from anon, authenticated;
grant select on table public.zchat_grp_links to authenticated;
grant all on table public.zchat_grp_links to service_role;
grant all on table public.zchat_grp_link_joins to service_role;

drop policy if exists "zchat grp links admins read" on public.zchat_grp_links;
create policy "zchat grp links admins read" on public.zchat_grp_links
  for select to authenticated
  using (public.zchat_group_role_rank(group_id, (select auth.uid())) >= 2);

create or replace function public.zchat_grp_link_save(p_group uuid, p_link uuid, p_name text, p_expires_secs integer, p_max integer)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  me uuid := auth.uid();
  nm text := btrim(regexp_replace(coalesce(p_name, ''), '[[:space:][:cntrl:]]+', ' ', 'g'));
  secs integer := nullif(coalesce(p_expires_secs, 0), 0);
  mx integer := nullif(coalesce(p_max, 0), 0);
  cd text;
  n integer;
  row public.zchat_grp_links%rowtype;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  if not public.zchat_session_ok() then
    raise exception 'Approve this login first' using errcode = '42501';
  end if;
  if p_group is null or public.zchat_group_role_rank(p_group, me) < 2 then
    return jsonb_build_object('ok', false, 'reason', 'Only group admins can make invite links.');
  end if;
  if char_length(nm) < 1 then
    nm := 'Invite link';
  end if;
  if char_length(nm) > 32 then
    return jsonb_build_object('ok', false, 'reason', 'Keep the name under 32 letters.');
  end if;
  if secs is not null and (secs < 300 or secs > 30 * 86400) then
    return jsonb_build_object('ok', false, 'reason', 'Pick when the link expires.');
  end if;
  if mx is not null and (mx < 1 or mx > 100000) then
    return jsonb_build_object('ok', false, 'reason', 'Pick how many people can join.');
  end if;
  select count(*) into n from public.zchat_grp_links l where l.created_by = me and l.updated_at > now() - interval '1 hour';
  if n >= 40 then
    return jsonb_build_object('ok', false, 'reason', 'That is a lot of links for one hour. Try again later.');
  end if;
  if p_link is null then
    perform pg_advisory_xact_lock(hashtextextended('zchat_grp_links:' || p_group::text, 0));
    select count(*) into n from public.zchat_grp_links l where l.group_id = p_group;
    if n >= 20 then
      return jsonb_build_object('ok', false, 'reason', 'A group can have 20 extra links. Delete one first.');
    end if;
    loop
      cd := substr(regexp_replace(encode(extensions.gen_random_bytes(18), 'base64'), '[^A-Za-z0-9]', '', 'g'), 1, 14);
      exit when char_length(cd) = 14
        and not exists (select 1 from public.zchat_grp_links l where l.code = cd)
        and not exists (select 1 from public.groups g where g.invite_code = cd);
    end loop;
    insert into public.zchat_grp_links (group_id, code, name, expires_at, max_uses, created_by)
    values (p_group, cd, nm, case when secs is null then null else now() + make_interval(secs => secs) end, mx, me)
    returning * into row;
  else
    update public.zchat_grp_links l
      set name = nm,
          expires_at = case when secs is null then null else now() + make_interval(secs => secs) end,
          max_uses = mx,
          updated_at = now()
      where l.id = p_link and l.group_id = p_group
      returning * into row;
    if not found then
      return jsonb_build_object('ok', false, 'reason', 'This link was deleted.');
    end if;
  end if;
  return jsonb_build_object('ok', true, 'link', to_jsonb(row));
end
$function$;
revoke all on function public.zchat_grp_link_save(uuid, uuid, text, integer, integer) from public, anon;
grant execute on function public.zchat_grp_link_save(uuid, uuid, text, integer, integer) to authenticated, service_role;

create or replace function public.zchat_grp_link_delete(p_link uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  me uuid := auth.uid();
  g uuid;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  if not public.zchat_session_ok() then
    raise exception 'Approve this login first' using errcode = '42501';
  end if;
  select l.group_id into g from public.zchat_grp_links l where l.id = p_link;
  if not found then
    return jsonb_build_object('ok', true, 'gone', true);
  end if;
  if public.zchat_group_role_rank(g, me) < 2 then
    return jsonb_build_object('ok', false, 'reason', 'Only group admins can delete invite links.');
  end if;
  delete from public.zchat_grp_links l where l.id = p_link;
  return jsonb_build_object('ok', true);
end
$function$;
revoke all on function public.zchat_grp_link_delete(uuid) from public, anon;
grant execute on function public.zchat_grp_link_delete(uuid) to authenticated, service_role;

create or replace function public.zchat_grp_link_count()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $function$
begin
  with hit as (
    update public.zchat_grp_link_joins j set joined_at = now()
    where j.group_id = new.group_id and j.user_id = new.user_id and j.joined_at is null and j.created_at > now() - interval '30 days'
    returning j.link_id
  )
  update public.zchat_grp_links l set uses = l.uses + 1 where l.id in (select link_id from hit);
  return null;
exception when others then
  return null;
end
$function$;

drop trigger if exists zchat_grp_link_count on public.group_members;
create trigger zchat_grp_link_count after insert on public.group_members
  for each row execute function public.zchat_grp_link_count();

CREATE OR REPLACE FUNCTION public.zchat_group_invite(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  g public.groups%rowtype;
  n integer;
  my_role text;
  req text;
  lk public.zchat_grp_links%rowtype;
begin
  if me is null or coalesce(btrim(p_code), '') = '' then
    return null;
  end if;
  select * into g from public.groups x where x.invite_code = btrim(p_code) limit 1;
  if not found then
    select * into lk from public.zchat_grp_links l where l.code = btrim(p_code) limit 1;
    if not found then
      return null;
    end if;
    select * into g from public.groups x where x.id = lk.group_id;
    if not found then
      return null;
    end if;
  end if;
  if coalesce((to_jsonb(g) ->> 'invite_enabled')::boolean, true) = false then
    return null;
  end if;
  select count(*) into n from public.group_members gm where gm.group_id = g.id;
  select gm.role into my_role from public.group_members gm where gm.group_id = g.id and gm.user_id = me;
  if lk.id is not null and my_role is null and ((lk.expires_at is not null and lk.expires_at <= now()) or (lk.max_uses is not null and lk.uses >= lk.max_uses)) then
    return jsonb_build_object('expired', true);
  end if;
  select r.status into req from public.group_join_requests r where r.group_id = g.id and r.user_id = me;
  return jsonb_build_object(
    'group', to_jsonb(g),
    'count', n,
    'role', my_role,
    'request', req,
    'admins', (select coalesce(jsonb_agg(gm.user_id), '[]'::jsonb) from public.group_members gm where gm.group_id = g.id and gm.role = 'admin'),
    'link', case when lk.id is null then null else jsonb_build_object('name', lk.name) end
  );
end $function$;

CREATE OR REPLACE FUNCTION public.zchat_join_group(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  code text := btrim(coalesce(p_code, ''));
  g public.groups%rowtype;
  my_role text;
  lk public.zchat_grp_links%rowtype;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if code = '' then
    return jsonb_build_object('ok', false, 'reason', 'This invite link isn''t valid anymore');
  end if;
  select * into g from public.groups x where x.invite_code = code limit 1;
  if not found then
    select * into lk from public.zchat_grp_links l where l.code = btrim(coalesce(p_code, '')) limit 1 for update;
    if found then
      select * into g from public.groups x where x.id = lk.group_id;
    end if;
  end if;
  if g.id is null or coalesce((to_jsonb(g) ->> 'invite_enabled')::boolean, true) = false then
    return jsonb_build_object('ok', false, 'reason', 'This invite link isn''t valid anymore');
  end if;
  select gm.role into my_role from public.group_members gm where gm.group_id = g.id and gm.user_id = me;
  if found then
    return jsonb_build_object('ok', true, 'already', true, 'role', my_role, 'group', to_jsonb(g));
  end if;
  if lk.id is not null and ((lk.expires_at is not null and lk.expires_at <= now()) or (lk.max_uses is not null and lk.uses >= lk.max_uses)) then
    return jsonb_build_object('ok', false, 'expired', true, 'reason', 'This invite link has expired');
  end if;
  if exists (select 1 from public.profiles p where p.id = me and (coalesce(p.banned, false) or coalesce(p.is_deleted, false))) then
    return jsonb_build_object('ok', false, 'reason', 'You cannot join groups right now.');
  end if;
  if public.zchat_blocked_pair(me, g.created_by) then
    return jsonb_build_object('ok', false, 'reason', 'You cannot join this group.');
  end if;
  if lk.id is not null then
    insert into public.zchat_grp_link_joins (link_id, group_id, user_id) values (lk.id, g.id, me)
    on conflict (link_id, user_id) do update set created_at = now() where zchat_grp_link_joins.joined_at is null;
  end if;
  if coalesce(g.join_approval, false) and g.created_by is distinct from me
     and not exists (select 1 from public.group_join_requests r where r.group_id = g.id and r.user_id = me and r.status = 'approved') then
    return jsonb_build_object('ok', false, 'approval', true, 'group', to_jsonb(g));
  end if;
  insert into public.group_members (group_id, user_id, role) values (g.id, me, 'member') on conflict do nothing;
  return jsonb_build_object('ok', true, 'role', 'member', 'group', to_jsonb(g));
end $function$;

do $do$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'zchat_grp_links') then
    execute 'alter publication supabase_realtime add table public.zchat_grp_links';
  end if;
end
$do$;

select public.zchat_apply_session_gate();

create or replace function public.zchat_ct_key_ok(p_key text)
returns boolean
language sql
immutable
as $$
  select case
    when p_key is null then false
    when p_key ~ '^g:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then true
    when p_key ~ '^dm:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then split_part(p_key, ':', 2)::uuid < split_part(p_key, ':', 3)::uuid
    else false
  end
$$;

create or replace function public.zchat_ct_other(p_key text)
returns uuid
language sql
stable
security definer
set search_path to 'public'
as $$
  select case
    when auth.uid() is null or p_key is null or p_key not like 'dm:%' or not public.zchat_ct_key_ok(p_key) then null
    when split_part(p_key, ':', 2)::uuid = auth.uid() then split_part(p_key, ':', 3)::uuid
    when split_part(p_key, ':', 3)::uuid = auth.uid() then split_part(p_key, ':', 2)::uuid
    else null
  end
$$;

create or replace function public.zchat_ct_member(p_key text)
returns boolean
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  other uuid;
begin
  if me is null or not public.zchat_ct_key_ok(p_key) then
    return false;
  end if;
  if p_key like 'g:%' then
    return exists (select 1 from public.group_members m where m.group_id = substr(p_key, 3)::uuid and m.user_id = me);
  end if;
  other := public.zchat_ct_other(p_key);
  if other is null or other = me then
    return false;
  end if;
  return not public.zchat_blocked_pair(me, other);
end
$$;

create or replace function public.zchat_ct_can_write(p_key text)
returns boolean
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  other uuid;
begin
  if not public.zchat_ct_member(p_key) then
    return false;
  end if;
  if p_key like 'g:%' then
    return not public.zchat_group_role_is_muted(substr(p_key, 3)::uuid, me);
  end if;
  other := public.zchat_ct_other(p_key);
  return exists (
    select 1 from public.profiles p
    where p.id = other
      and not coalesce(p.is_deleted, false)
      and not coalesce(p.is_bot, false)
      and not coalesce(p.banned, false)
  ) and not exists (
    select 1 from public.blocks b
    where (b.blocker_id = me and b.blocked_id = other) or (b.blocker_id = other and b.blocked_id = me)
  );
end
$$;

create or replace function public.zchat_ct_is_admin(p_key text)
returns boolean
language sql
stable
security definer
set search_path to 'public'
as $$
  select case
    when auth.uid() is null or p_key is null or p_key not like 'g:%' or not public.zchat_ct_key_ok(p_key) then false
    else public.zchat_group_role_rank(substr(p_key, 3)::uuid, auth.uid()) >= 2
  end
$$;

create table if not exists public.zchat_ct_rate (
  user_id uuid not null,
  bucket text not null,
  win timestamptz not null default now(),
  n integer not null default 0,
  primary key (user_id, bucket)
);
alter table public.zchat_ct_rate enable row level security;
revoke all on table public.zchat_ct_rate from anon, authenticated;

create or replace function public.zchat_ct_hit(p_bucket text, p_max integer, p_secs integer)
returns boolean
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  cnt integer;
begin
  if me is null then
    return false;
  end if;
  insert into public.zchat_ct_rate as r (user_id, bucket, win, n)
  values (me, p_bucket, now(), 1)
  on conflict (user_id, bucket) do update
    set n = case when r.win < now() - make_interval(secs => p_secs) then 1 else r.n + 1 end,
        win = case when r.win < now() - make_interval(secs => p_secs) then now() else r.win end
  returning n into cnt;
  return cnt <= p_max;
end
$$;

create or replace function public.zchat_ct_name(p_user uuid)
returns text
language sql
stable
security definer
set search_path to 'public'
as $$
  select coalesce(nullif(split_part(btrim(coalesce(p.name, '')), ' ', 1), ''), p.username, 'Someone')
  from public.profiles p where p.id = p_user
$$;

