begin;
create table if not exists public.zchat_playlist_songs (
  id uuid primary key default gen_random_uuid(),
  chat_key text not null,
  song_id text not null,
  song jsonb not null,
  added_by uuid not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  gone_at timestamptz,
  constraint zchat_playlist_songs_key check (public.zchat_ct_key_ok(chat_key)),
  constraint zchat_playlist_songs_size check (pg_column_size(song) <= 4000 and char_length(song_id) between 1 and 80)
);
create index if not exists zchat_playlist_songs_chat on public.zchat_playlist_songs (chat_key, created_at desc);
create unique index if not exists zchat_playlist_songs_one on public.zchat_playlist_songs (chat_key, song_id) where gone_at is null;

alter table public.zchat_playlist_songs enable row level security;
drop policy if exists "zchat playlist read" on public.zchat_playlist_songs;
create policy "zchat playlist read" on public.zchat_playlist_songs for select to authenticated using (public.zchat_in_chat(chat_key));
revoke all on table public.zchat_playlist_songs from anon;
revoke insert, update, delete, truncate, references, trigger on table public.zchat_playlist_songs from authenticated;
grant select on table public.zchat_playlist_songs to authenticated;

create or replace function public.zchat_ct_song(s jsonb)
returns jsonb
language plpgsql
immutable
as $$
declare
  t text;
  a text;
  p text;
  art text;
  u text;
  sid text;
begin
  if s is null or jsonb_typeof(s) <> 'object' then
    return null;
  end if;
  t := left(btrim(regexp_replace(coalesce(s ->> 't', ''), '[[:cntrl:]]+', ' ', 'g')), 120);
  p := btrim(coalesce(s ->> 'p', ''));
  if t = '' or char_length(p) > 600 or p !~* '^https://([a-z0-9-]+\.)*(apple|mzstatic)\.com/' then
    return null;
  end if;
  a := left(btrim(regexp_replace(coalesce(s ->> 'a', ''), '[[:cntrl:]]+', ' ', 'g')), 120);
  art := btrim(coalesce(s ->> 'art', ''));
  if char_length(art) > 600 or art !~* '^https://([a-z0-9-]+\.)*mzstatic\.com/' then
    art := null;
  end if;
  u := btrim(coalesce(s ->> 'u', ''));
  if char_length(u) > 600 or u !~* '^https://music\.apple\.com/' then
    u := null;
  end if;
  sid := left(regexp_replace(coalesce(s ->> 'id', ''), '[^A-Za-z0-9._:-]+', '', 'g'), 80);
  if sid = '' then
    sid := left(md5(p), 24);
  end if;
  return jsonb_strip_nulls(jsonb_build_object('id', sid, 't', t, 'a', nullif(a, ''), 'art', art, 'p', p, 'u', u));
end
$$;

create or replace function public.zchat_playlist_add(p_key text, p_songs jsonb)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  s jsonb;
  clean jsonb;
  r public.zchat_playlist_songs;
  added jsonb := '[]'::jsonb;
  n_added integer := 0;
  n_dup integer := 0;
  n_active integer;
  is_full boolean := false;
  g uuid;
  other uuid;
  card_id bigint;
  card_body text;
  old jsonb;
  n_total integer;
  shown jsonb;
  v_text text;
  v_content text;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  if not public.zchat_ct_can_write(p_key) then
    raise exception 'You can not add songs to this playlist' using errcode = '42501';
  end if;
  if p_songs is null or jsonb_typeof(p_songs) <> 'array' or jsonb_array_length(p_songs) < 1 or jsonb_array_length(p_songs) > 25 then
    raise exception 'Add up to 25 songs at a time' using errcode = '22023';
  end if;
  if not public.zchat_ct_hit('playlist', 40, 60) then
    raise exception 'That is a lot of songs at once. Wait a minute and try again.' using errcode = '54000';
  end if;
  perform pg_advisory_xact_lock(hashtext('zchat_playlist:' || p_key));
  select count(*) into n_active from public.zchat_playlist_songs where chat_key = p_key and gone_at is null;
  for s in select value from jsonb_array_elements(p_songs) loop
    clean := public.zchat_ct_song(s);
    if clean is null then
      continue;
    end if;
    if n_active >= 300 then
      is_full := true;
      exit;
    end if;
    insert into public.zchat_playlist_songs (chat_key, song_id, song, added_by)
    values (p_key, clean ->> 'id', clean, me)
    on conflict (chat_key, song_id) where gone_at is null do nothing
    returning * into r;
    if not found then
      n_dup := n_dup + 1;
      continue;
    end if;
    added := added || jsonb_build_array(to_jsonb(r));
    n_added := n_added + 1;
    n_active := n_active + 1;
  end loop;
  if n_added > 0 then
    if p_key like 'g:%' then
      g := substr(p_key, 3)::uuid;
    else
      other := public.zchat_ct_other(p_key);
    end if;
    select m.id, m.content into card_id, card_body
    from public.messages m
    where m.sender_id = me
      and m.created_at > now() - interval '5 minutes'
      and coalesce(m.deleted, false) = false
      and m.content like 'zplay:%'
      and ((g is not null and m.group_id = g) or (g is null and m.group_id is null and m.receiver_id = other))
    order by m.created_at desc
    limit 1;
    if card_id is not null then
      old := public.zchat_try_jsonb(substr(card_body, 7));
      n_total := n_added + case when coalesce(old ->> 'n', '') ~ '^[0-9]{1,3}$' then (old ->> 'n')::integer else 0 end;
      select coalesce(jsonb_agg(x order by o, ord), '[]'::jsonb) into shown from (
        select q.x, q.o, q.ord from (
          select jsonb_strip_nulls(jsonb_build_object('t', e -> 'song' ->> 't', 'a', e -> 'song' ->> 'a', 'art', e -> 'song' ->> 'art')) as x, 0 as o, t.ord
          from jsonb_array_elements(added) with ordinality as t(e, ord)
          union all
          select t2.e, 1, t2.ord
          from jsonb_array_elements(case when jsonb_typeof(old -> 's') = 'array' then old -> 's' else '[]'::jsonb end) with ordinality as t2(e, ord)
        ) q
        order by q.o, q.ord
        limit 3
      ) z;
      v_text := coalesce(public.zchat_ct_name(me), 'Someone') || ' added ' || case when n_total = 1 then 'a song' else n_total || ' songs' end || ' to your playlist';
      v_content := 'zplay:' || json_build_object('t', v_text, 'n', n_total, 's', shown)::text;
      update public.messages set content = v_content where id = card_id;
    end if;
  end if;
  return jsonb_build_object(
    'ok', true,
    'rows', added,
    'total', n_active,
    'dup', n_dup,
    'full', is_full,
    'card', case when card_id is null then null else jsonb_build_object('id', card_id, 'content', v_content) end
  );
end
$$;

revoke all on function public.zchat_ct_song(jsonb) from public, anon;
grant execute on function public.zchat_ct_song(jsonb) to authenticated, service_role;
revoke all on function public.zchat_playlist_add(text, jsonb) from public, anon;
grant execute on function public.zchat_playlist_add(text, jsonb) to authenticated, service_role;

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
