create table if not exists public.zchat_board_items (
  id uuid primary key default gen_random_uuid(),
  chat_key text not null,
  kind text not null,
  body text,
  media_url text,
  media_w integer,
  media_h integer,
  link_url text,
  tone smallint not null default 0,
  message_id bigint references public.messages(id) on delete cascade,
  author_id uuid,
  pinned_by uuid not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  gone_at timestamptz,
  constraint zchat_board_items_key check (public.zchat_ct_key_ok(chat_key)),
  constraint zchat_board_items_kind check (kind in ('photo', 'note', 'link', 'text')),
  constraint zchat_board_items_body check (body is null or char_length(body) <= 1200),
  constraint zchat_board_items_media check (media_url is null or (char_length(media_url) <= 700 and public.zchat_url_ok(media_url))),
  constraint zchat_board_items_link check (link_url is null or (char_length(link_url) <= 700 and link_url ~* '^https?://')),
  constraint zchat_board_items_dims check ((media_w is null or media_w between 1 and 20000) and (media_h is null or media_h between 1 and 20000)),
  constraint zchat_board_items_tone check (tone between 0 and 5)
);
create index if not exists zchat_board_items_chat on public.zchat_board_items (chat_key, created_at desc);
create index if not exists zchat_board_items_msg on public.zchat_board_items (message_id) where message_id is not null;
create index if not exists zchat_board_items_zp on public.zchat_board_items (media_url) where media_url like 'zp:%';
create unique index if not exists zchat_board_items_one on public.zchat_board_items (chat_key, message_id) where message_id is not null and gone_at is null;

