create or replace function public.zchat_board_add(p_key text, p_kind text, p_body text, p_media text, p_w integer, p_h integer, p_tone integer, p_msg bigint)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  g uuid;
  other uuid;
  m record;
  v_kind text;
  v_body text;
  v_media text;
  v_link text;
  v_author uuid;
  n_active integer;
  r public.zchat_board_items;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  if not public.zchat_ct_can_write(p_key) then
    raise exception 'You can not pin to this board' using errcode = '42501';
  end if;
  if not public.zchat_ct_hit('board', 30, 60) then
    raise exception 'That is a lot of pins at once. Wait a minute and try again.' using errcode = '54000';
  end if;
  if p_key like 'g:%' then
    g := substr(p_key, 3)::uuid;
  else
    other := public.zchat_ct_other(p_key);
  end if;
  if p_msg is not null then
    select id, sender_id, receiver_id, group_id, type, content, media_url, deleted into m
    from public.messages where id = p_msg;
    if not found or coalesce(m.deleted, false)
       or not ((g is not null and m.group_id = g)
         or (g is null and m.group_id is null and ((m.sender_id = me and m.receiver_id = other) or (m.sender_id = other and m.receiver_id = me)))) then
      raise exception 'That message is not in this chat' using errcode = '22023';
    end if;
    select * into r from public.zchat_board_items where chat_key = p_key and message_id = p_msg and gone_at is null;
    if found then
      return jsonb_build_object('ok', true, 'dup', true, 'row', to_jsonb(r));
    end if;
    if m.type = 'image' and m.media_url is not null and coalesce(m.content, '') not like 'zonce:%' then
      v_kind := 'photo';
      v_media := m.media_url;
      v_body := case when coalesce(m.content, '') ~ '^(z[a-z]{2,10}|call):' then null else nullif(left(btrim(coalesce(m.content, '')), 1200), '') end;
    elsif m.type = 'text' and coalesce(m.content, '') <> '' and m.content !~ '^(z[a-z]{2,10}|call):\s*[\{\[]' then
      v_body := left(btrim(m.content), 1200);
      v_link := substring(m.content from '(https?://[^[:space:]<>"]+)');
      v_kind := case when v_link is not null then 'link' else 'text' end;
      if v_link is not null and char_length(v_link) > 700 then
        v_link := null;
        v_kind := 'text';
      end if;
    else
      raise exception 'That message can not go on the board' using errcode = '22023';
    end if;
    v_author := m.sender_id;
  else
    v_kind := p_kind;
    if v_kind = 'photo' then
      v_media := btrim(coalesce(p_media, ''));
      if v_media = '' or char_length(v_media) > 700 or not public.zchat_url_ok(v_media)
         or not (v_media like ('zp:' || me::text || '/%') or v_media ~* '^https://') then
        raise exception 'That photo did not upload. Try again.' using errcode = '22023';
      end if;
      v_body := nullif(left(btrim(coalesce(p_body, '')), 1200), '');
    elsif v_kind = 'note' then
      v_body := left(btrim(coalesce(p_body, '')), 1200);
      if v_body = '' then
        raise exception 'Write something first' using errcode = '22023';
      end if;
    else
      raise exception 'Pick a photo or write a note' using errcode = '22023';
    end if;
    v_author := me;
  end if;
  perform pg_advisory_xact_lock(hashtext('zchat_board:' || p_key));
  select count(*) into n_active from public.zchat_board_items where chat_key = p_key and gone_at is null;
  if n_active >= 500 then
    raise exception 'This board is full. Remove a few pins first.' using errcode = '54000';
  end if;
  insert into public.zchat_board_items (chat_key, kind, body, media_url, media_w, media_h, link_url, tone, message_id, author_id, pinned_by)
  values (
    p_key, v_kind, v_body, v_media,
    case when v_media is not null and p_w between 1 and 20000 then p_w else null end,
    case when v_media is not null and p_h between 1 and 20000 then p_h else null end,
    v_link,
    case when p_tone between 0 and 5 then p_tone else 0 end,
    p_msg, v_author, me
  )
  returning * into r;
  return jsonb_build_object('ok', true, 'dup', false, 'row', to_jsonb(r));
end
$$;

revoke all on function public.zchat_board_add(text, text, text, text, integer, integer, integer, bigint) from public, anon;
