create or replace function public.zchat_joke_save(p_key text, p_id uuid, p_phrase text, p_meaning text)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  v_phrase text;
  v_meaning text;
  n_active integer;
  cur public.zchat_inside_jokes;
  r public.zchat_inside_jokes;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  if not public.zchat_ct_can_write(p_key) then
    raise exception 'You can not save inside jokes here' using errcode = '42501';
  end if;
  v_phrase := btrim(regexp_replace(regexp_replace(coalesce(p_phrase, ''), '[[:cntrl:]]+', ' ', 'g'), '\s+', ' ', 'g'));
  v_meaning := btrim(regexp_replace(coalesce(p_meaning, ''), '[[:cntrl:]]+', ' ', 'g'));
  if char_length(v_phrase) < 1 or char_length(v_phrase) > 40 or v_phrase !~ '[[:alnum:]]' then
    raise exception 'Pick a word or a short phrase' using errcode = '22023';
  end if;
  if char_length(v_meaning) < 1 or char_length(v_meaning) > 300 then
    raise exception 'Write what it means in a few words' using errcode = '22023';
  end if;
  if not public.zchat_ct_hit('jokes', 30, 60) then
    raise exception 'Slow down a little and try again in a minute' using errcode = '54000';
  end if;
  perform pg_advisory_xact_lock(hashtext('zchat_jokes:' || p_key));
  if exists (
    select 1 from public.zchat_inside_jokes j
    where j.chat_key = p_key and j.gone_at is null and lower(j.phrase) = lower(v_phrase) and (p_id is null or j.id <> p_id)
  ) then
    raise exception 'That one is already saved in this chat' using errcode = '23505';
  end if;
  if p_id is null then
    select count(*) into n_active from public.zchat_inside_jokes where chat_key = p_key and gone_at is null;
    if n_active >= 100 then
      raise exception 'This chat has 100 inside jokes. Remove one to add another.' using errcode = '54000';
    end if;
    insert into public.zchat_inside_jokes (chat_key, phrase, meaning, created_by)
    values (p_key, v_phrase, v_meaning, me)
    returning * into r;
  else
    select * into cur from public.zchat_inside_jokes where id = p_id and chat_key = p_key and gone_at is null for update;
    if not found then
      raise exception 'That inside joke is gone' using errcode = '22023';
    end if;
    if cur.created_by <> me and p_key like 'g:%' and not public.zchat_ct_is_admin(p_key) then
      raise exception 'Only the person who saved it or an admin can change it' using errcode = '42501';
    end if;
    update public.zchat_inside_jokes
    set phrase = v_phrase, meaning = v_meaning, updated_by = me, updated_at = now()
    where id = p_id
    returning * into r;
  end if;
  return jsonb_build_object('ok', true, 'row', to_jsonb(r));
end
$$;

revoke all on function public.zchat_joke_save(text, uuid, text, text) from public, anon;
grant execute on function public.zchat_joke_save(text, uuid, text, text) to authenticated, service_role;

