create or replace function public.zchat_moment_add(p_key text, p_msg bigint, p_title text)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  other uuid;
  m record;
  v_title text;
  n_active integer;
  r public.zchat_us_moments;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  if p_key not like 'dm:%' or not public.zchat_ct_can_write(p_key) then
    raise exception 'Moments are just for the two of you' using errcode = '42501';
  end if;
  other := public.zchat_ct_other(p_key);
  v_title := btrim(regexp_replace(regexp_replace(coalesce(p_title, ''), '[[:cntrl:]]+', ' ', 'g'), '\s+', ' ', 'g'));
  if char_length(v_title) < 1 or char_length(v_title) > 60 then
    raise exception 'Give it a short title' using errcode = '22023';
  end if;
  select id, sender_id, receiver_id, group_id, type, deleted into m from public.messages where id = p_msg;
  if not found or coalesce(m.deleted, false) or m.group_id is not null or coalesce(m.type, 'text') = 'system'
     or not ((m.sender_id = me and m.receiver_id = other) or (m.sender_id = other and m.receiver_id = me)) then
    raise exception 'That message is not in this chat' using errcode = '22023';
  end if;
  if not public.zchat_ct_hit('moments', 30, 60) then
    raise exception 'Slow down a little and try again in a minute' using errcode = '54000';
  end if;
  perform pg_advisory_xact_lock(hashtext('zchat_moments:' || p_key));
  update public.zchat_us_moments set title = v_title where chat_key = p_key and message_id = p_msg and gone_at is null returning * into r;
  if not found then
    select count(*) into n_active from public.zchat_us_moments where chat_key = p_key and gone_at is null;
    if n_active >= 200 then
      raise exception 'Your story has 200 moments. Remove one to add another.' using errcode = '54000';
    end if;
    insert into public.zchat_us_moments (chat_key, message_id, title, created_by)
    values (p_key, p_msg, v_title, me)
    returning * into r;
  end if;
  return jsonb_build_object('ok', true, 'row', to_jsonb(r));
end
$$;

create or replace function public.zchat_story_of_us(p_other uuid, p_tz text default 'UTC')
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  v_tz text := 'UTC';
  v_key text;
  out jsonb;
begin
  if me is null or p_other is null or p_other = me then
    return null;
  end if;
  if not exists (select 1 from public.profiles p where p.id = p_other and not coalesce(p.is_deleted, false) and not coalesce(p.is_bot, false)) then
    return null;
  end if;
  if public.zchat_blocked_pair(me, p_other) then
    return null;
  end if;
  begin
    perform now() at time zone p_tz;
    v_tz := coalesce(nullif(p_tz, ''), 'UTC');
  exception when others then
    v_tz := 'UTC';
  end;
  v_key := 'dm:' || least(me, p_other)::text || ':' || greatest(me, p_other)::text;
  with pair as materialized (
    select m.id, m.sender_id, coalesce(m.type, 'text') as type,
      case when m.content like 'zgame:%' or m.content like 'call:%' or m.content like 'zonce:%' then left(m.content, 120) end as content,
      case when m.type = 'image' then m.media_url end as media_url, m.created_at
    from public.messages m
    where m.sender_id = me and m.receiver_id = p_other and m.group_id is null and coalesce(m.deleted, false) = false
    union all
    select m.id, m.sender_id, coalesce(m.type, 'text'),
      case when m.content like 'zgame:%' or m.content like 'call:%' or m.content like 'zonce:%' then left(m.content, 120) end,
      case when m.type = 'image' then m.media_url end, m.created_at
    from public.messages m
    where m.sender_id = p_other and m.receiver_id = me and m.group_id is null and coalesce(m.deleted, false) = false
  ),
  real_msgs as (select p.*, (p.created_at at time zone v_tz) as lt from pair p where p.type <> 'system'),
  stats as (
    select count(*) as total,
      count(*) filter (where sender_id = me) as mine,
      count(*) filter (where type in ('image', 'video')) as photos,
      count(*) filter (where type = 'audio') as voice,
      count(distinct substring(content from '"id":"([^"]+)"')) filter (where content like 'zgame:%') as games
    from real_msgs
  ),
  busy as (
    select lt::date as d, count(*) as n
    from real_msgs group by 1 order by 2 desc, 1 desc limit 1
  )
  select jsonb_build_object(
    'total', (select total from stats),
    'mine', (select mine from stats),
    'photos', (select photos from stats),
    'voice', (select voice from stats),
    'games', (select games from stats),
    'calls', (select count(*) from pair where content like 'call:%'),
    'hour', (select extract(hour from lt)::integer from real_msgs group by 1 order by count(*) desc, 1 limit 1),
    'groups', (select count(*) from public.group_members a join public.group_members b on b.group_id = a.group_id where a.user_id = me and b.user_id = p_other),
    'first', (select jsonb_build_object('id', f.id, 's', f.sender_id, 'k', f.type, 't', (select left(x.content, 200) from public.messages x where x.id = f.id), 'at', f.created_at)
              from (select id, sender_id, type, created_at from real_msgs order by created_at, id limit 1) f),
    'photo', (select jsonb_build_object('id', id, 's', sender_id, 'k', type, 'm', media_url, 'at', created_at) from real_msgs
              where type = 'image' and media_url is not null and coalesce(content, '') not like 'zonce:%' and media_url !~* 'giphy\.com' order by created_at, id limit 1),
    'voice_note', (select jsonb_build_object('id', id, 's', sender_id, 'k', type, 'at', created_at) from real_msgs
              where type = 'audio' and coalesce(content, '') not like 'zonce:%' order by created_at, id limit 1),
    'call', (select jsonb_build_object('id', id, 's', sender_id, 'k', type, 't', content, 'at', created_at) from pair
              where content like 'call:%' order by (content ~ '"s":"(missed|declined)"'), created_at, id limit 1),
    'busiest', (select jsonb_build_object('d', b.d, 'n', b.n, 'id',
              (select r.id from real_msgs r where r.lt::date = b.d order by r.created_at, r.id limit 1)) from busy b),
    'moments', (select coalesce(jsonb_agg(jsonb_build_object('id', mo.id, 'title', mo.title, 'by', mo.created_by, 'at', mo.created_at,
                  'm', jsonb_build_object('id', ms.id, 's', ms.sender_id, 'k', coalesce(ms.type, 'text'), 't', left(ms.content, 160), 'u', ms.media_url, 'at', ms.created_at))
                  order by ms.created_at, ms.id), '[]'::jsonb)
                from public.zchat_us_moments mo join public.messages ms on ms.id = mo.message_id
                where mo.chat_key = v_key and mo.gone_at is null and coalesce(ms.deleted, false) = false),
    'key', v_key
  ) into out;
  return out;
end
$$;

