create or replace function public.zchat_note_save(p_key text, p_body text, p_base integer, p_restore boolean default false)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  v_body text;
  cur public.zchat_chat_notes;
  r public.zchat_chat_notes;
  last_v public.zchat_chat_note_versions;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  if not public.zchat_ct_can_write(p_key) then
    raise exception 'You can not edit this note' using errcode = '42501';
  end if;
  v_body := coalesce(p_body, '');
  if char_length(v_body) > 20000 then
    raise exception 'Notes can be up to 20,000 characters' using errcode = '22023';
  end if;
  if not public.zchat_ct_hit('note', 150, 60) then
    raise exception 'Saving very fast. Give it a moment.' using errcode = '54000';
  end if;
  select * into cur from public.zchat_chat_notes where chat_key = p_key for update;
  if not found then
    if coalesce(p_base, 0) <> 0 then
      return jsonb_build_object('ok', false, 'conflict', true, 'note', null);
    end if;
    if v_body = '' then
      return jsonb_build_object('ok', true, 'note', null);
    end if;
    insert into public.zchat_chat_notes (chat_key, body, version, updated_by, updated_at)
    values (p_key, v_body, 1, me, now())
    on conflict (chat_key) do nothing
    returning * into r;
    if not found then
      select * into cur from public.zchat_chat_notes where chat_key = p_key;
      return jsonb_build_object('ok', false, 'conflict', true, 'note', to_jsonb(cur));
    end if;
  else
    if cur.version <> coalesce(p_base, -1) then
      return jsonb_build_object('ok', false, 'conflict', true, 'note', to_jsonb(cur));
    end if;
    if cur.body = v_body then
      return jsonb_build_object('ok', true, 'note', to_jsonb(cur));
    end if;
    update public.zchat_chat_notes
    set body = v_body, version = cur.version + 1, updated_by = me, updated_at = now()
    where chat_key = p_key
    returning * into r;
  end if;
  select * into last_v from public.zchat_chat_note_versions where chat_key = p_key order by created_at desc, version desc limit 1;
  if found and not coalesce(p_restore, false) and last_v.edited_by = me and last_v.created_at > now() - interval '10 minutes' then
    update public.zchat_chat_note_versions set body = r.body, version = r.version, updated_at = now() where id = last_v.id;
  else
    insert into public.zchat_chat_note_versions (chat_key, body, version, edited_by) values (p_key, r.body, r.version, me);
    delete from public.zchat_chat_note_versions v
    where v.chat_key = p_key
      and v.id not in (select k.id from public.zchat_chat_note_versions k where k.chat_key = p_key order by k.created_at desc, k.version desc limit 20);
  end if;
  return jsonb_build_object('ok', true, 'note', to_jsonb(r));
end
$$;

revoke all on function public.zchat_note_save(text, text, integer, boolean) from public, anon;
grant execute on function public.zchat_note_save(text, text, integer, boolean) to authenticated, service_role;

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'zchat_chat_notes') then
    execute 'alter publication supabase_realtime add table public.zchat_chat_notes';
  end if;
end $$;

select public.zchat_apply_session_gate();
commit;

begin;
create table if not exists public.zchat_time_polls (
  id uuid primary key default gen_random_uuid(),
  chat_key text not null,
  created_by uuid not null references auth.users(id) on delete cascade,
  title text,
  starts timestamptz[] not null,
  step smallint not null,
  slots smallint not null,
  tz text,
  picked smallint,
  picked_at timestamptz,
  closed_at timestamptz,
  created_at timestamptz not null default now(),
  constraint zchat_time_polls_key check (public.zchat_ct_key_ok(chat_key)),
  constraint zchat_time_polls_title check (title is null or char_length(title) <= 60),
  constraint zchat_time_polls_days check (array_length(starts, 1) between 1 and 7),
  constraint zchat_time_polls_step check (step in (30, 60)),
  constraint zchat_time_polls_slots check (slots between 1 and 48 and slots * step <= 1440),
  constraint zchat_time_polls_tz check (tz is null or char_length(tz) <= 64)
);
create index if not exists zchat_time_polls_chat on public.zchat_time_polls (chat_key, created_at desc);

create table if not exists public.zchat_time_votes (
  poll_id uuid not null references public.zchat_time_polls(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  chat_key text not null,
  slots smallint[] not null default '{}',
  updated_at timestamptz not null default now(),
  primary key (poll_id, user_id),
  constraint zchat_time_votes_size check (coalesce(array_length(slots, 1), 0) <= 336)
);
create index if not exists zchat_time_votes_chat on public.zchat_time_votes (chat_key);

alter table public.zchat_time_polls enable row level security;
alter table public.zchat_time_votes enable row level security;
drop policy if exists "zchat time polls read" on public.zchat_time_polls;
create policy "zchat time polls read" on public.zchat_time_polls for select to authenticated using (public.zchat_in_chat(chat_key));
drop policy if exists "zchat time votes read" on public.zchat_time_votes;
create policy "zchat time votes read" on public.zchat_time_votes for select to authenticated using (public.zchat_in_chat(chat_key));
revoke all on table public.zchat_time_polls from anon;
revoke all on table public.zchat_time_votes from anon;
revoke insert, update, delete, truncate, references, trigger on table public.zchat_time_polls from authenticated;
revoke insert, update, delete, truncate, references, trigger on table public.zchat_time_votes from authenticated;
grant select on table public.zchat_time_polls to authenticated;
grant select on table public.zchat_time_votes to authenticated;

drop function if exists public.zchat_time_create(text, text, timestamptz[], integer, integer, text);
create or replace function public.zchat_time_create(p_key text, p_title text, p_starts timestamptz[], p_step integer, p_slots integer, p_tz text, p_id uuid default null)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  v_title text;
  n integer;
  i integer;
  r public.zchat_time_polls;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  if not public.zchat_ct_can_write(p_key) then
    raise exception 'You can not plan in this chat' using errcode = '42501';
  end if;
  n := coalesce(array_length(p_starts, 1), 0);
  if n < 1 or n > 7 then
    raise exception 'Pick between 1 and 7 days' using errcode = '22023';
  end if;
  if p_step not in (30, 60) or p_slots < 1 or p_slots > 48 or p_slots * p_step > 1440 then
    raise exception 'Pick a time range inside one day' using errcode = '22023';
  end if;
  for i in 1 .. n loop
    if p_starts[i] is null then
      raise exception 'Pick between 1 and 7 days' using errcode = '22023';
    end if;
    if i > 1 and p_starts[i] < p_starts[i - 1] + make_interval(mins => p_slots * p_step) then
      raise exception 'Days must be in order' using errcode = '22023';
    end if;
  end loop;
  if p_starts[n] + make_interval(mins => p_slots * p_step) < now() or p_starts[1] > now() + interval '120 days' or p_starts[n] - p_starts[1] > interval '30 days' then
    raise exception 'Pick days coming up soon' using errcode = '22023';
  end if;
  if not public.zchat_ct_hit('findtime', 20, 3600) then
    raise exception 'You made a lot of plans this hour. Try again later.' using errcode = '54000';
  end if;
  v_title := nullif(btrim(regexp_replace(regexp_replace(coalesce(p_title, ''), '[[:cntrl:]]+', ' ', 'g'), '\s+', ' ', 'g')), '');
  if p_id is not null and exists (select 1 from public.zchat_time_polls where id = p_id) then
    raise exception 'That plan was already made' using errcode = '23505';
  end if;
  insert into public.zchat_time_polls (id, chat_key, created_by, title, starts, step, slots, tz)
  values (coalesce(p_id, gen_random_uuid()), p_key, me, left(v_title, 60), p_starts, p_step, p_slots, left(nullif(btrim(coalesce(p_tz, '')), ''), 64))
  returning * into r;
  return jsonb_build_object('ok', true, 'row', to_jsonb(r));
end
$$;

create or replace function public.zchat_time_vote(p_poll uuid, p_slots integer[])
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  pl public.zchat_time_polls;
  total integer;
  clean smallint[];
  r public.zchat_time_votes;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  select * into pl from public.zchat_time_polls where id = p_poll;
  if not found or not public.zchat_ct_member(pl.chat_key) then
    raise exception 'This plan is not in your chats' using errcode = '42501';
  end if;
  if pl.chat_key like 'dm:%' and not public.zchat_ct_can_write(pl.chat_key) then
    raise exception 'You can not plan in this chat' using errcode = '42501';
  end if;
  if pl.closed_at is not null then
    raise exception 'A time was already picked' using errcode = '22023';
  end if;
  total := array_length(pl.starts, 1) * pl.slots;
  if coalesce(array_length(p_slots, 1), 0) > total then
    raise exception 'Those times are not in this plan' using errcode = '22023';
  end if;
  if exists (select 1 from unnest(coalesce(p_slots, '{}'::integer[])) s where s is null or s < 0 or s >= total) then
    raise exception 'Those times are not in this plan' using errcode = '22023';
  end if;
  if not public.zchat_ct_hit('findtime_vote', 240, 60) then
    raise exception 'Saving very fast. Give it a moment.' using errcode = '54000';
  end if;
  select coalesce(array_agg(distinct s order by s), '{}'::smallint[]) into clean from unnest(coalesce(p_slots, '{}'::integer[])) s;
  insert into public.zchat_time_votes (poll_id, user_id, chat_key, slots, updated_at)
  values (p_poll, me, pl.chat_key, clean, now())
  on conflict (poll_id, user_id) do update set slots = excluded.slots, updated_at = now()
  returning * into r;
  return jsonb_build_object('ok', true, 'row', to_jsonb(r));
end
$$;

create or replace function public.zchat_time_pick(p_poll uuid, p_slot integer)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  pl public.zchat_time_polls;
  total integer;
  r public.zchat_time_polls;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  select * into pl from public.zchat_time_polls where id = p_poll for update;
  if not found or not public.zchat_ct_member(pl.chat_key) then
    raise exception 'This plan is not in your chats' using errcode = '42501';
  end if;
  if pl.chat_key like 'dm:%' and not public.zchat_ct_can_write(pl.chat_key) then
    raise exception 'You can not plan in this chat' using errcode = '42501';
  end if;
  if pl.created_by <> me then
    raise exception 'Only the person who made this plan can pick the time' using errcode = '42501';
  end if;
  if pl.closed_at is not null then
    raise exception 'A time was already picked' using errcode = '22023';
  end if;
  total := array_length(pl.starts, 1) * pl.slots;
  if p_slot is null or p_slot < 0 or p_slot >= total then
    raise exception 'That time is not in this plan' using errcode = '22023';
  end if;
  update public.zchat_time_polls
  set picked = p_slot,
      picked_at = pl.starts[(p_slot / pl.slots) + 1] + make_interval(mins => (p_slot % pl.slots) * pl.step),
      closed_at = now()
  where id = p_poll
  returning * into r;
  return jsonb_build_object('ok', true, 'row', to_jsonb(r));
end
$$;

revoke all on function public.zchat_time_create(text, text, timestamptz[], integer, integer, text, uuid) from public, anon;
grant execute on function public.zchat_time_create(text, text, timestamptz[], integer, integer, text, uuid) to authenticated, service_role;
revoke all on function public.zchat_time_vote(uuid, integer[]) from public, anon;
grant execute on function public.zchat_time_vote(uuid, integer[]) to authenticated, service_role;
revoke all on function public.zchat_time_pick(uuid, integer) from public, anon;
grant execute on function public.zchat_time_pick(uuid, integer) to authenticated, service_role;

