create or replace function public.zchat_ct_remove(p_kind text, p_id uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  v_key text;
  v_owner uuid;
  v_gone timestamptz;
  ok boolean;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  if p_kind = 'song' then
    select chat_key, added_by, gone_at into v_key, v_owner, v_gone from public.zchat_playlist_songs where id = p_id;
  elsif p_kind = 'board' then
    select chat_key, pinned_by, gone_at into v_key, v_owner, v_gone from public.zchat_board_items where id = p_id;
  elsif p_kind = 'joke' then
    select chat_key, created_by, gone_at into v_key, v_owner, v_gone from public.zchat_inside_jokes where id = p_id;
  elsif p_kind = 'moment' then
    select chat_key, created_by, gone_at into v_key, v_owner, v_gone from public.zchat_us_moments where id = p_id;
  else
    raise exception 'Unknown item' using errcode = '22023';
  end if;
  if v_key is null or not public.zchat_ct_member(v_key) then
    raise exception 'That is not in your chats' using errcode = '42501';
  end if;
  if v_gone is not null then
    return jsonb_build_object('ok', true, 'gone', true);
  end if;
  ok := v_owner = me
    or public.zchat_ct_is_admin(v_key)
    or (p_kind in ('joke', 'moment') and v_key like 'dm:%');
  if not ok then
    raise exception 'Only the person who added it or an admin can remove it' using errcode = '42501';
  end if;
  if p_kind = 'song' then
    update public.zchat_playlist_songs set gone_at = now() where id = p_id and gone_at is null;
    delete from public.zchat_playlist_songs where chat_key = v_key and gone_at < now() - interval '2 days';
  elsif p_kind = 'board' then
    update public.zchat_board_items set gone_at = now() where id = p_id and gone_at is null;
    delete from public.zchat_board_items where chat_key = v_key and gone_at < now() - interval '2 days';
  elsif p_kind = 'joke' then
    update public.zchat_inside_jokes set gone_at = now() where id = p_id and gone_at is null;
    delete from public.zchat_inside_jokes where chat_key = v_key and gone_at < now() - interval '2 days';
  else
    update public.zchat_us_moments set gone_at = now() where id = p_id and gone_at is null;
    delete from public.zchat_us_moments where chat_key = v_key and gone_at < now() - interval '2 days';
  end if;
  return jsonb_build_object('ok', true);
end
$$;

create or replace function public.zchat_ct_summary(p_key text)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
as $$
begin
  if not public.zchat_ct_member(p_key) then
    return null;
  end if;
  return jsonb_build_object(
    'songs', (select count(*) from public.zchat_playlist_songs where chat_key = p_key and gone_at is null),
    'board', (select count(*) from public.zchat_board_items where chat_key = p_key and gone_at is null),
    'jokes', (select count(*) from public.zchat_inside_jokes where chat_key = p_key and gone_at is null),
    'moments', (select count(*) from public.zchat_us_moments where chat_key = p_key and gone_at is null),
    'note', (select jsonb_build_object('line', left(split_part(btrim(n.body), E'\n', 1), 120), 'by', n.updated_by, 'at', n.updated_at, 'version', n.version, 'body', case when length(n.body) <= 4000 then n.body end)
             from public.zchat_chat_notes n where n.chat_key = p_key and btrim(n.body) <> '')
  );
end
$$;

create or replace function public.zchat_ct_message_gone()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  update public.zchat_board_items set gone_at = now() where message_id = old.id and gone_at is null;
  update public.zchat_us_moments set gone_at = now() where message_id = old.id and gone_at is null;
  return null;
end
$$;

drop trigger if exists zchat_ct_message_gone on public.messages;
create trigger zchat_ct_message_gone
  after update of deleted on public.messages
  for each row
  when (new.deleted is true and old.deleted is distinct from true)
  execute function public.zchat_ct_message_gone();

create or replace function public.zchat_can_read_media(p_name text)
 returns boolean
 language plpgsql
 stable security definer
 set search_path to 'public'
as $function$
declare
  me uuid := auth.uid();
  ok boolean := false;
begin
  if me is null or p_name is null then
    return false;
  end if;
  if split_part(p_name, '/', 1) = me::text or public.zchat_is_admin_id(me) then
    return true;
  end if;
  select exists (
    select 1 from public.messages m
    where m.media_url = 'zp:' || p_name
      and (m.sender_id = me or m.receiver_id = me
        or (m.group_id is not null and exists (select 1 from public.group_members gm where gm.group_id = m.group_id and gm.user_id = me)))
      and not (
        m.sender_id <> me and coalesce(m.content, '') like 'zonce:%'
        and exists (select 1 from public.message_likes l where l.message_id = m.id and l.user_id = me and l.emoji = 'zo')
      )
  ) into ok;
  if ok then
    return true;
  end if;
  select exists (
    select 1 from public.zchat_capsules c
    join public.messages m on m.id = c.message_id
    where c.media_path = p_name
      and c.open_at <= now()
      and not coalesce(m.deleted, false)
      and (c.receiver_id = me or (c.group_id is not null and exists (select 1 from public.group_members gm where gm.group_id = c.group_id and gm.user_id = me)))
  ) into ok;
  if ok then
    return true;
  end if;
  select exists (
    select 1 from public.album_photos ph join public.albums a on a.id = ph.album_id
    where ph.media_url = 'zp:' || p_name and public.zchat_in_chat(a.chat_key)
  ) into ok;
  if ok then
    return true;
  end if;
  select exists (
    select 1 from public.zchat_board_items bi
    where bi.media_url = 'zp:' || p_name and bi.gone_at is null and public.zchat_in_chat(bi.chat_key)
  ) into ok;
  if ok then
    return true;
  end if;
  begin
    execute 'select exists (select 1 from public.saved_messages s where s.user_id = $1 and s.media_url = $2)' into ok using me, 'zp:' || p_name;
  exception when others then
    ok := false;
  end;
  return coalesce(ok, false);
end $function$;

revoke all on function public.zchat_ct_remove(text, uuid) from public, anon;
grant execute on function public.zchat_ct_remove(text, uuid) to authenticated, service_role;
revoke all on function public.zchat_ct_summary(text) from public, anon;
grant execute on function public.zchat_ct_summary(text) to authenticated, service_role;
revoke all on function public.zchat_ct_message_gone() from public, anon, authenticated;
commit;

begin;
create index if not exists zchat_messages_pinned_until on public.messages (pinned_until) where pinned_until is not null;

create or replace function public.zchat_pin_forever()
returns timestamptz
language sql
immutable
set search_path to 'public'
as $$
  select '9999-12-31 00:00:00+00'::timestamptz
$$;

create or replace function public.zchat_pin_message(p_message bigint, p_days integer)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  m record;
  days integer := coalesce(p_days, 0);
  v_until timestamptz;
  v_at timestamptz := now();
  dropped bigint[];
  recent integer;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if days not in (-1, 0, 1, 7, 30) then
    return jsonb_build_object('ok', false, 'reason', 'Pick 24 hours, 7 days, 30 days or until you unpin.');
  end if;
  select x.id, x.sender_id, x.receiver_id, x.group_id, x.deleted, x.type into m from public.messages x where x.id = p_message for update;
  if not found or m.group_id is not null or (m.sender_id is distinct from me and m.receiver_id is distinct from me) then
    return jsonb_build_object('ok', false, 'reason', 'That message is not here anymore.');
  end if;
  if days = 0 then
    update public.messages set pinned_until = null, pinned_by = null, pinned_at = null where id = m.id;
    return jsonb_build_object('ok', true, 'pinned', false);
  end if;
  if coalesce(m.deleted, false) or coalesce(m.type, 'text') = 'system' then
    return jsonb_build_object('ok', false, 'reason', 'This message cannot be pinned.');
  end if;
  select count(*) into recent from public.messages x
  where x.group_id is null and x.pinned_by = me and x.pinned_at > now() - interval '1 minute'
    and ((x.sender_id = m.sender_id and x.receiver_id = m.receiver_id) or (x.sender_id = m.receiver_id and x.receiver_id = m.sender_id));
  if recent >= 12 then
    return jsonb_build_object('ok', false, 'reason', 'That is a lot of pins at once. Wait a minute and try again.');
  end if;
  v_until := case when days = -1 then public.zchat_pin_forever() else now() + make_interval(days => days) end;
  with old_pins as (
    select x.id from public.messages x
    where x.group_id is null and x.id <> m.id and x.pinned_until > now() and not coalesce(x.deleted, false)
      and ((x.sender_id = m.sender_id and x.receiver_id = m.receiver_id) or (x.sender_id = m.receiver_id and x.receiver_id = m.sender_id))
    order by x.pinned_at desc nulls last
    offset 2
  ), cleared as (
    update public.messages x set pinned_until = null, pinned_by = null, pinned_at = null
    from old_pins where x.id = old_pins.id
    returning x.id
  )
  select coalesce(array_agg(id), array[]::bigint[]) into dropped from cleared;
  update public.messages set pinned_until = v_until, pinned_by = me, pinned_at = v_at where id = m.id;
  return jsonb_build_object('ok', true, 'pinned', true, 'pinned_until', v_until, 'pinned_at', v_at, 'unpinned', to_jsonb(dropped), 'now', now());
end $$;

revoke all on function public.zchat_pin_message(bigint, integer) from public, anon;
grant execute on function public.zchat_pin_message(bigint, integer) to authenticated;

create or replace function public.zchat_mod_pin(p_message bigint, p_days integer)
 returns jsonb
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  me uuid := auth.uid();
  m record;
  days integer := coalesce(p_days, 0);
  v_until timestamptz;
  v_at timestamptz := now();
  dropped bigint[];
  msg public.messages;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  select x.id, x.group_id, x.deleted, x.type into m from public.messages x where x.id = p_message for update;
  if not found or m.group_id is null or public.zchat_group_role_rank(m.group_id, me) < 0 then
    return jsonb_build_object('ok', false, 'reason', 'That message is not here anymore.');
  end if;
  if public.zchat_group_role_rank(m.group_id, me) < 1 then
    return jsonb_build_object('ok', false, 'reason', 'Only moderators can pin messages in this group.');
  end if;
  if (days > 0 or days = -1) and public.zchat_group_role_busy(m.group_id) then
    return jsonb_build_object('ok', false, 'reason', 'That is a lot of changes at once. Wait a minute and try again.');
  end if;
  perform set_config('zchat.role_ok', '1', true);
  if days <= 0 and days <> -1 then
    update public.messages set pinned_until = null, pinned_by = null, pinned_at = null where id = m.id;
    perform set_config('zchat.role_ok', '', true);
    return jsonb_build_object('ok', true, 'pinned', false);
  end if;
  if coalesce(m.deleted, false) or coalesce(m.type, 'text') = 'system' then
    perform set_config('zchat.role_ok', '', true);
    return jsonb_build_object('ok', false, 'reason', 'This message cannot be pinned.');
  end if;
  v_until := case when days = -1 then public.zchat_pin_forever() else now() + make_interval(days => least(days, 30)) end;
  with old_pins as (
    select x.id from public.messages x
    where x.group_id = m.group_id and x.id <> m.id and x.pinned_until > now() and not coalesce(x.deleted, false)
    order by x.pinned_at desc nulls last
    offset 2
  ), cleared as (
    update public.messages x set pinned_until = null, pinned_by = null, pinned_at = null
    from old_pins where x.id = old_pins.id
    returning x.id
  )
  select coalesce(array_agg(id), array[]::bigint[]) into dropped from cleared;
  update public.messages set pinned_until = v_until, pinned_by = me, pinned_at = v_at where id = m.id;
  perform set_config('zchat.role_ok', '', true);
  msg := public.zchat_group_role_line(m.group_id, public.zchat_group_role_name(me) || ' pinned a message');
  return jsonb_build_object('ok', true, 'pinned', true, 'pinned_until', v_until, 'pinned_at', v_at, 'unpinned', to_jsonb(dropped), 'line', to_jsonb(msg), 'now', now());
end $function$;

create or replace function public.zchat_pins_tick()
returns integer
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  n integer;
begin
  perform set_config('zchat.role_ok', '1', true);
  with gone as (
    select x.id from public.messages x
    where x.pinned_until is not null and x.pinned_until <= now()
    order by x.pinned_until
    limit 500
  )
  update public.messages x set pinned_until = null, pinned_by = null, pinned_at = null
  from gone where x.id = gone.id;
  get diagnostics n = row_count;
  perform set_config('zchat.role_ok', '', true);
  return n;
end $$;

revoke all on function public.zchat_pins_tick() from public, anon, authenticated;

do $$
begin
  if to_regprocedure('cron.schedule(text,text,text)') is not null then
    if to_regclass('cron.job') is null or not exists (select 1 from cron.job where jobname = 'zchat-pins-expire') then
      perform cron.schedule('zchat-pins-expire', '* * * * *', 'select public.zchat_pins_tick()');
    end if;
  end if;
end $$;

create table if not exists public.zchat_saved_folders (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  name text not null,
  created_at timestamptz not null default now(),
  constraint zchat_saved_folders_name_len check (char_length(btrim(name)) between 1 and 40)
);
create index if not exists zchat_saved_folders_user on public.zchat_saved_folders (user_id, created_at);
create unique index if not exists zchat_saved_folders_user_name on public.zchat_saved_folders (user_id, lower(btrim(name)));

alter table public.zchat_saved_folders enable row level security;
revoke all on public.zchat_saved_folders from anon;
grant select, insert, update, delete on public.zchat_saved_folders to authenticated;
drop policy if exists "zchat saved folders own" on public.zchat_saved_folders;
create policy "zchat saved folders own" on public.zchat_saved_folders for all to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

create or replace function public.zchat_saved_folders_guard()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  n integer;
begin
  new.name := btrim(regexp_replace(coalesce(new.name, ''), '[\u0000-\u001f\u007f\u200b-\u200f\u202a-\u202e\u2060-\u2069\ufeff]+', ' ', 'g'));
  new.name := left(regexp_replace(new.name, '\s+', ' ', 'g'), 40);
  if tg_op = 'UPDATE' then
    if new.user_id is distinct from old.user_id then
      raise exception 'This folder is not yours' using errcode = '42501';
    end if;
    return new;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('zchat_saved_folders:' || new.user_id::text, 0));
  select count(*) into n from public.zchat_saved_folders f where f.user_id = new.user_id;
  if n >= 50 then
    raise exception 'You can have up to 50 folders' using errcode = 'P0001';
  end if;
  return new;
end $$;

drop trigger if exists zchat_saved_folders_guard on public.zchat_saved_folders;
create trigger zchat_saved_folders_guard before insert or update on public.zchat_saved_folders
  for each row execute function public.zchat_saved_folders_guard();

delete from public.saved_messages a using public.saved_messages b
where a.source_message_id is not null and a.user_id = b.user_id and a.source_message_id = b.source_message_id
  and (a.created_at < b.created_at or (a.created_at = b.created_at and a.id < b.id));
create unique index if not exists zchat_saved_messages_source on public.saved_messages (user_id, source_message_id);

alter table public.saved_messages add column if not exists folder_id uuid;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'saved_messages_folder_id_fkey') then
    alter table public.saved_messages add constraint saved_messages_folder_id_fkey foreign key (folder_id) references public.zchat_saved_folders(id) on delete set null;
  end if;
end $$;
create index if not exists zchat_saved_messages_folder on public.saved_messages (user_id, folder_id);

create or replace function public.zchat_saved_folder_check()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  if new.folder_id is not null and not exists (select 1 from public.zchat_saved_folders f where f.id = new.folder_id and f.user_id = new.user_id) then
    raise exception 'That folder is not yours' using errcode = '42501';
  end if;
  return new;
end $$;

drop trigger if exists zchat_saved_folder_check on public.saved_messages;
create trigger zchat_saved_folder_check before insert or update of folder_id, user_id on public.saved_messages
  for each row execute function public.zchat_saved_folder_check();

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') and not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'zchat_saved_folders') then
    execute 'alter publication supabase_realtime add table public.zchat_saved_folders';
  end if;
end $$;

select public.zchat_apply_session_gate();
commit;

begin;
alter table public.conversations add column if not exists read_receipts_a text;
alter table public.conversations add column if not exists read_receipts_b text;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'zchat_conv_receipts_ok') then
    alter table public.conversations add constraint zchat_conv_receipts_ok check ((read_receipts_a is null or read_receipts_a in ('on', 'off')) and (read_receipts_b is null or read_receipts_b in ('on', 'off')));
  end if;
end $$;

create table if not exists public.zchat_dm_reads (
  user_id uuid not null references auth.users(id) on delete cascade,
  other_id uuid not null,
  last_id bigint not null default 0,
  read_at timestamptz not null default now(),
  primary key (user_id, other_id)
);
alter table public.zchat_dm_reads enable row level security;
revoke all on public.zchat_dm_reads from anon, authenticated;
grant select on public.zchat_dm_reads to authenticated;
drop policy if exists "zchat dm reads own" on public.zchat_dm_reads;
create policy "zchat dm reads own" on public.zchat_dm_reads for select to authenticated using (user_id = auth.uid());

create or replace function public.zchat_dm_receipts_on(p_a uuid, p_b uuid)
returns boolean
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  c record;
  va text;
  vb text;
  da boolean;
  db boolean;
begin
  if p_a is null or p_b is null or p_a = p_b then
    return true;
  end if;
  select p.read_receipts into da from public.profiles p where p.id = p_a;
  select p.read_receipts into db from public.profiles p where p.id = p_b;
  select x.user_a, x.read_receipts_a, x.read_receipts_b into c
  from public.conversations x
  where (x.user_a = p_a and x.user_b = p_b) or (x.user_a = p_b and x.user_b = p_a)
  limit 1;
  if found then
    va := case when c.user_a = p_a then c.read_receipts_a else c.read_receipts_b end;
    vb := case when c.user_a = p_a then c.read_receipts_b else c.read_receipts_a end;
  end if;
  return (case va when 'on' then true when 'off' then false else coalesce(da, true) end)
     and (case vb when 'on' then true when 'off' then false else coalesce(db, true) end);
end $$;
revoke all on function public.zchat_dm_receipts_on(uuid, uuid) from public, anon, authenticated;

create or replace function public.zchat_dm_read_guard()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
begin
  if old.group_id is not null or new.read is not true or old.read is true or me is null
     or me is distinct from old.receiver_id or old.sender_id is null or old.sender_id = me then
    return new;
  end if;
  if public.zchat_dm_receipts_on(old.sender_id, old.receiver_id) then
    return new;
  end if;
  insert into public.zchat_dm_reads as r (user_id, other_id, last_id, read_at)
  values (me, old.sender_id, old.id, now())
  on conflict (user_id, other_id) do update set last_id = excluded.last_id, read_at = excluded.read_at
  where r.last_id < excluded.last_id;
  new.read := false;
  if to_jsonb(new) = to_jsonb(old) then
    return null;
  end if;
  return new;
end $$;

drop trigger if exists zchat_dm_read_guard on public.messages;
create trigger zchat_dm_read_guard before update of read on public.messages
  for each row execute function public.zchat_dm_read_guard();

create or replace function public.zchat_dm_unread(p_limit integer default 1000)
returns table (id bigint, sender_id uuid)
language sql
stable
set search_path to 'public'
as $$
  select m.id, m.sender_id
  from public.messages m
  where m.receiver_id = auth.uid() and m.group_id is null and m.read = false and m.deleted is not true
    and not exists (select 1 from public.zchat_dm_reads r where r.user_id = auth.uid() and r.other_id = m.sender_id and r.last_id >= m.id)
  order by m.created_at desc
  limit least(greatest(coalesce(p_limit, 1000), 1), 1000)
$$;
revoke all on function public.zchat_dm_unread(integer) from public, anon;
grant execute on function public.zchat_dm_unread(integer) to authenticated;

CREATE OR REPLACE FUNCTION public.zchat_chat_list(p_reads jsonb DEFAULT NULL::jsonb, p_window integer DEFAULT 400, p_per integer DEFAULT 4)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  win integer := least(greatest(coalesce(p_window, 400), 50), 600);
  per integer := least(greatest(coalesce(p_per, 4), 2), 20);
  reads jsonb := case when jsonb_typeof(p_reads) = 'object' then p_reads else '{}'::jsonb end;
  hid jsonb := '{}'::jsonb;
  out_convs jsonb;
  out_msgs jsonb;
  out_sent jsonb;
  out_profiles jsonb;
  out_nicks jsonb;
  out_aliases jsonb;
  out_unread jsonb;
  out_members jsonb;
  out_groups jsonb;
  out_gmsgs jsonb;
  out_gunread jsonb;
  out_gnames jsonb;
  out_locks jsonb;
  out_blocks jsonb;
  out_blocked_by jsonb;
  out_dmreads jsonb;
begin
  if me is null then
    return jsonb_build_object('v', 1, 'ok', false);
  end if;
  if (select count(*) from jsonb_object_keys(reads)) > 500 then
    reads := '{}'::jsonb;
  end if;

  if to_regclass('public.hidden_messages') is not null then
    select coalesce(jsonb_object_agg(h.message_id, true), '{}'::jsonb) into hid
    from (select distinct h0.message_id from public.hidden_messages h0 where h0.user_id = me and h0.message_id not like 'chat:%' limit 20000) h;
  end if;

  select coalesce(jsonb_agg(to_jsonb(c) order by c.last_message_at desc nulls first), '[]'::jsonb) into out_convs
  from public.conversations c
  where c.user_a = me or c.user_b = me;

  with mine as (
    select m.id, m.sender_id, m.receiver_id, m.type, m.content, m.deleted, m.created_at, m.read, m.delivered, m.story_id, m.expires_at, m.media_url
    from public.messages m
    where m.sender_id = me and m.group_id is null
    order by m.created_at desc
    limit win
  ), theirs as (
    select m.id, m.sender_id, m.receiver_id, m.type, m.content, m.deleted, m.created_at, m.read, m.delivered, m.story_id, m.expires_at, m.media_url
    from public.messages m
    where m.receiver_id = me and m.group_id is null and m.sender_id is distinct from me
    order by m.created_at desc
    limit win
  ), w as (
    select u.* from (select * from mine union all select * from theirs) u
    order by u.created_at desc
    limit win
  ), tagged as (
    select w.*,
      case when w.sender_id = me then w.receiver_id else w.sender_id end as other,
      (hid ? w.id::text) as is_hidden,
      (w.expires_at is not null and w.expires_at <= now()) as is_gone
    from w
  ), ranked as (
    select t.*,
      row_number() over (partition by t.other order by t.created_at desc, t.id desc) as rn_any,
      row_number() over (partition by t.other, (not t.is_hidden and not t.is_gone) order by t.created_at desc, t.id desc) as rn_ok
    from tagged t
    where t.other is not null
  )
  select
    coalesce(jsonb_agg(
      jsonb_strip_nulls(jsonb_build_object('id', r.id, 'sender_id', r.sender_id, 'receiver_id', r.receiver_id, 'type', r.type, 'content', r.content,
        'deleted', r.deleted, 'created_at', r.created_at, 'read', r.read, 'delivered', r.delivered, 'story_id', r.story_id,
        'expires_at', r.expires_at,
        'media_url', case when r.media_url ~* '^https://[a-z0-9.]*giphy\.com/' then r.media_url end,
        'hid', case when r.is_hidden then true end))
      order by r.created_at desc
    ) filter (where r.rn_any = 1 or (not r.is_hidden and not r.is_gone and r.rn_ok <= per)), '[]'::jsonb),
    coalesce(jsonb_agg(distinct r.other) filter (where r.sender_id = me), '[]'::jsonb)
  into out_msgs, out_sent
  from ranked r;

  out_profiles := public.zchat_profile_view(array(
    select distinct case when c.user_a = me then c.user_b else c.user_a end
    from public.conversations c
    where c.user_a = me or c.user_b = me
  ));

  if to_regclass('public.contact_nicknames') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(n)), ''[]''::jsonb) from public.contact_nicknames n where n.owner_id = $1' into out_nicks using me;
  end if;
  if to_regclass('public.self_aliases') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(a)), ''[]''::jsonb) from public.self_aliases a where a.viewer_id = $1' into out_aliases using me;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('id', u.id, 'sender_id', u.sender_id)), '[]'::jsonb) into out_unread
  from (
    select m.id, m.sender_id
    from public.messages m
    where m.receiver_id = me and m.group_id is null and m.read = false and m.deleted is not true
      and not exists (select 1 from public.zchat_dm_reads r where r.user_id = me and r.other_id = m.sender_id and r.last_id >= m.id)
    order by m.created_at desc
    limit 1000
  ) u;

  select coalesce(jsonb_agg(to_jsonb(gm)), '[]'::jsonb) into out_members
  from public.group_members gm
  where gm.user_id = me;

  select coalesce(jsonb_agg(to_jsonb(g)), '[]'::jsonb) into out_groups
  from public.groups g
  where g.id in (select gm.group_id from public.group_members gm where gm.user_id = me);

  select coalesce(jsonb_agg(
      jsonb_strip_nulls(jsonb_build_object('id', x.id, 'group_id', x.group_id, 'sender_id', x.sender_id, 'type', x.type, 'content', x.content,
        'created_at', x.created_at, 'deleted', x.deleted, 'expires_at', x.expires_at, 'story_id', x.story_id,
        'media_url', case when x.media_url ~* '^https://[a-z0-9.]*giphy\.com/' then x.media_url end))
      order by x.created_at desc), '[]'::jsonb),
    coalesce(jsonb_agg(distinct x.sender_id) filter (where x.sender_id is distinct from me and x.type is distinct from 'system' and x.sender_id is not null), '[]'::jsonb)
  into out_gmsgs, out_gnames
  from public.group_members gm
  cross join lateral (
    select m.id, m.group_id, m.sender_id, m.type, m.content, m.created_at, m.deleted, m.expires_at, m.story_id, m.media_url
    from public.messages m
    where m.group_id = gm.group_id
      and not (hid ? m.id::text)
      and (m.expires_at is null or m.expires_at > now())
    order by m.created_at desc
    limit per
  ) x
  where gm.user_id = me;

  select coalesce(jsonb_object_agg(p.id, p.name), '{}'::jsonb) into out_gnames
  from public.profiles p
  where p.id in (select (jsonb_array_elements_text(out_gnames))::uuid);

  select coalesce(jsonb_object_agg(k.group_id, k.n), '{}'::jsonb) into out_gunread
  from (
    select gm.group_id, (
      select count(*) from (
        select 1
        from public.messages m
        where m.group_id = gm.group_id
          and m.created_at > public.zchat_core_ts(reads ->> gm.group_id::text)
          and m.sender_id is distinct from me
          and m.type is distinct from 'system'
          and m.deleted is not true
          and (m.expires_at is null or m.expires_at > now())
          and not (hid ? m.id::text)
        limit 100
      ) z
    ) as n
    from public.group_members gm
    where gm.user_id = me
      and public.zchat_core_ts(reads ->> gm.group_id::text) is not null
  ) k;

  if to_regclass('public.chat_locks') is not null then
    execute 'select coalesce(jsonb_agg(l.conversation_id), ''[]''::jsonb) from public.chat_locks l where l.owner_id = $1' into out_locks using me;
  end if;

  select coalesce(jsonb_object_agg(r.other_id, r.last_id), '{}'::jsonb) into out_dmreads from public.zchat_dm_reads r where r.user_id = me;

  select coalesce(jsonb_agg(b.blocked_id), '[]'::jsonb) into out_blocks from public.blocks b where b.blocker_id = me;
  select coalesce(jsonb_agg(b.blocker_id), '[]'::jsonb) into out_blocked_by from public.blocks b where b.blocked_id = me;

  return jsonb_build_object(
    'v', 1, 'ok', true, 'me', me,
    'convs', out_convs, 'msgs', out_msgs, 'sent', out_sent, 'profiles', out_profiles,
    'nicks', out_nicks, 'aliases', out_aliases, 'unread', out_unread,
    'members', out_members, 'groups', out_groups, 'gmsgs', out_gmsgs, 'gunread', out_gunread, 'gnames', out_gnames,
    'locks', out_locks, 'blocks', out_blocks, 'blocked_by', out_blocked_by, 'dmreads', out_dmreads
  );
end $function$;

select public.zchat_apply_session_gate();

create or replace function public.zchat_msg_link(p_message bigint)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  m record;
  gone boolean;
begin
  if me is null or not public.zchat_session_ok() then
    return jsonb_build_object('ok', false, 'reason', 'login');
  end if;
  if p_message is null or p_message <= 0 then
    return jsonb_build_object('ok', false, 'reason', 'not_in_chat');
  end if;
  select x.id, x.sender_id, x.receiver_id, x.group_id, x.created_at, x.deleted, x.expires_at, x.type, x.topic into m
  from public.messages x where x.id = p_message;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_in_chat');
  end if;
  if m.group_id is not null then
    if not exists (select 1 from public.group_members gm where gm.group_id = m.group_id and gm.user_id = me) then
      return jsonb_build_object('ok', false, 'reason', 'not_in_chat');
    end if;
  elsif m.sender_id is distinct from me and m.receiver_id is distinct from me then
    return jsonb_build_object('ok', false, 'reason', 'not_in_chat');
  end if;
  gone := (m.expires_at is not null and m.expires_at <= now())
    or exists (select 1 from public.hidden_messages h where h.user_id = me and h.message_id = m.id::text);
  if m.group_id is not null then
    return jsonb_build_object('ok', true, 'kind', 'group', 'group', m.group_id, 'id', m.id, 'at', m.created_at, 'topic', m.topic, 'gone', gone);
  end if;
  return jsonb_build_object('ok', true, 'kind', 'dm', 'peer', case when m.sender_id = me then m.receiver_id else m.sender_id end, 'id', m.id, 'at', m.created_at, 'gone', gone);
end $$;

