create or replace function public.zchat_sticker_react_guard()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  k text;
  sid uuid;
begin
  if new.emoji is null or left(new.emoji, 4) <> 'zst:' then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.emoji is not distinct from old.emoji and new.user_id is not distinct from old.user_id then
    return new;
  end if;
  k := substr(new.emoji, 5);
  new.super_key := null;
  if char_length(new.emoji) > 60 then
    raise exception 'That sticker is not available' using errcode = '22023';
  end if;
  if left(k, 2) = 'u:' then
    sid := public.zchat_try_uuid(substr(k, 3));
    if sid is null or not exists (select 1 from public.user_stickers s where s.id = sid and s.user_id = new.user_id) then
      raise exception 'Only your own saved stickers can be used' using errcode = '42501';
    end if;
    new.emoji := 'zst:u:' || sid::text;
    return new;
  end if;
  if not (k = any (public.zchat_sticker_keys())) then
    raise exception 'That sticker is not available' using errcode = '22023';
  end if;
  return new;
end $$;

drop trigger if exists zchat_sticker_react_guard on public.message_likes;
create trigger zchat_sticker_react_guard before insert or update of emoji, user_id on public.message_likes
  for each row execute function public.zchat_sticker_react_guard();
commit;

begin;
create table if not exists public.zchat_tones (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  name text not null,
  path text not null,
  secs numeric(4, 1),
  created_at timestamptz not null default now(),
  constraint zchat_tones_name_len check (char_length(btrim(name)) between 1 and 40),
  constraint zchat_tones_secs_ok check (secs is null or (secs > 0 and secs <= 10))
);
create index if not exists zchat_tones_user on public.zchat_tones (user_id, created_at);

alter table public.zchat_tones enable row level security;
revoke all on public.zchat_tones from anon;
grant select, insert, update, delete on public.zchat_tones to authenticated;
drop policy if exists "zchat tones own" on public.zchat_tones;
create policy "zchat tones own" on public.zchat_tones for all to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

create or replace function public.zchat_tones_guard()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  n integer;
begin
  new.name := left(btrim(regexp_replace(coalesce(new.name, ''), '[\u0000-\u001f\u007f\u200b-\u200f\u202a-\u202e\u2060-\u2069\ufeff]+', ' ', 'g')), 40);
  if tg_op = 'UPDATE' and (new.user_id is distinct from old.user_id or new.path is distinct from old.path) then
    raise exception 'Only the name of a tone can change' using errcode = '42501';
  end if;
  if new.path !~ ('^zp:' || new.user_id::text || '/tones/[A-Za-z0-9-]{8,64}\.(wav|webm|ogg|m4a|mp3)$') then
    raise exception 'Tones live in your own folder' using errcode = '42501';
  end if;
  if tg_op = 'INSERT' then
    perform pg_advisory_xact_lock(hashtextextended('zchat_tones:' || new.user_id::text, 0));
    select count(*) into n from public.zchat_tones t where t.user_id = new.user_id;
    if n >= 20 then
      raise exception 'You can keep up to 20 tones' using errcode = 'P0001';
    end if;
  end if;
  return new;
end $$;

drop trigger if exists zchat_tones_guard on public.zchat_tones;
create trigger zchat_tones_guard before insert or update on public.zchat_tones
  for each row execute function public.zchat_tones_guard();

select public.zchat_apply_session_gate();

alter table public.messages add column if not exists tr_from text;
alter table public.messages add column if not exists tr_orig text;
alter table public.messages add column if not exists reply_more bigint[];

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'zchat_cm_tr_check' and conrelid = 'public.messages'::regclass) then
    alter table public.messages add constraint zchat_cm_tr_check check (
      (tr_from is null or tr_from ~ '^[a-z]{2}$')
      and (tr_orig is null or char_length(tr_orig) between 1 and 4000)
      and ((tr_from is null) = (tr_orig is null))
    ) not valid;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'zchat_cm_reply_more_check' and conrelid = 'public.messages'::regclass) then
    alter table public.messages add constraint zchat_cm_reply_more_check check (
      reply_more is null or (cardinality(reply_more) between 1 and 9 and array_position(reply_more, null) is null)
    ) not valid;
  end if;
end $$;

create or replace function public.zchat_cm_reply_more_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  bad integer;
begin
  if new.reply_more is null then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.reply_more is not distinct from old.reply_more then
    return new;
  end if;
  if new.reply_to_id is null then
    raise exception 'Pick the first message you are replying to' using errcode = '22023';
  end if;
  if cardinality(new.reply_more) <> (select count(distinct x) from unnest(new.reply_more) x) or new.reply_to_id = any(new.reply_more) then
    raise exception 'Each message can be quoted once' using errcode = '22023';
  end if;
  select count(*) into bad
  from unnest(new.reply_more || new.reply_to_id) as q(id)
  where not exists (
    select 1 from public.messages m
    where m.id = q.id
      and (
        (new.group_id is not null and m.group_id = new.group_id)
        or (new.group_id is null and m.group_id is null and (
          (m.sender_id = new.sender_id and m.receiver_id = new.receiver_id)
          or (m.sender_id = new.receiver_id and m.receiver_id = new.sender_id)
        ))
      )
  );
  if bad > 0 then
    raise exception 'You can only quote messages from this chat' using errcode = '22023';
  end if;
  return new;
end $$;

drop trigger if exists zchat_cm_reply_more_guard on public.messages;
create trigger zchat_cm_reply_more_guard
  before insert or update of reply_more on public.messages
  for each row when (new.reply_more is not null)
  execute function public.zchat_cm_reply_more_guard();

alter table public.conversations add column if not exists live_typing_a boolean not null default false;
alter table public.conversations add column if not exists live_typing_b boolean not null default false;

create table if not exists public.zchat_cm_waiting (
  id uuid primary key default gen_random_uuid(),
  sender_id uuid not null references public.profiles(id) on delete cascade,
  receiver_id uuid not null references public.profiles(id) on delete cascade,
  content text not null,
  client_id text,
  created_at timestamptz not null default now(),
  constraint zchat_cm_waiting_content check (char_length(content) between 1 and 4000),
  constraint zchat_cm_waiting_client check (client_id is null or char_length(client_id) <= 80),
  constraint zchat_cm_waiting_pair check (sender_id <> receiver_id)
);
create index if not exists zchat_cm_waiting_to on public.zchat_cm_waiting (receiver_id, created_at);
create index if not exists zchat_cm_waiting_from on public.zchat_cm_waiting (sender_id, created_at);

alter table public.zchat_cm_waiting enable row level security;
revoke all on public.zchat_cm_waiting from anon;
revoke insert, update on public.zchat_cm_waiting from authenticated;
grant select, delete on public.zchat_cm_waiting to authenticated;
drop policy if exists "zchat cm waiting read own" on public.zchat_cm_waiting;
create policy "zchat cm waiting read own" on public.zchat_cm_waiting for select to authenticated using (sender_id = auth.uid());
drop policy if exists "zchat cm waiting delete own" on public.zchat_cm_waiting;
create policy "zchat cm waiting delete own" on public.zchat_cm_waiting for delete to authenticated using (sender_id = auth.uid());

create or replace function public.zchat_cm_hides_online(p_user uuid, p_viewer uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((
    select not public.zchat_activity_public(p.hide_activity, p.privacy_lastseen, p.privacy_online)
    from public.profiles p where p.id = p_user
  ), true)
$$;
revoke all on function public.zchat_cm_hides_online(uuid, uuid) from public, anon, authenticated;

create or replace function public.zchat_cm_can_send(p_from uuid, p_to uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select p_from is not null and p_to is not null and p_from <> p_to
    and not exists (
      select 1 from public.blocks x
      where (x.blocker_id = p_from and x.blocked_id = p_to) or (x.blocker_id = p_to and x.blocked_id = p_from)
    )
    and exists (select 1 from public.profiles p where p.id = p_from and not coalesce(p.is_deleted, false) and not coalesce(p.banned, false))
    and exists (select 1 from public.profiles p where p.id = p_to and not coalesce(p.is_deleted, false) and not coalesce(p.banned, false) and not coalesce(p.is_bot, false))
    and (
      public.zchat_is_admin_id(p_from)
      or exists (select 1 from public.chat_accepts a where a.user_id = p_to and a.other_id = p_from)
      or public.zchat_follows(p_to, p_from)
      or (
        not public.zchat_limited(p_from, p_to)
        and coalesce((select coalesce(p.privacy_messages, 'everyone') <> 'following' from public.profiles p where p.id = p_to), true)
      )
    )
$$;
revoke all on function public.zchat_cm_can_send(uuid, uuid) from public, anon, authenticated;

create or replace function public.zchat_cm_release(p_receiver uuid, p_from_job boolean default false)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  r record;
  n integer := 0;
  a uuid;
  b uuid;
begin
  if p_receiver is null then
    return 0;
  end if;
  for r in
    select w.* from public.zchat_cm_waiting w
    where w.receiver_id = p_receiver
    order by w.created_at
    limit 20
    for update skip locked
  loop
    if not p_from_job and public.zchat_cm_hides_online(r.receiver_id, r.sender_id) then
      continue;
    end if;
    if not public.zchat_cm_can_send(r.sender_id, r.receiver_id) then
      continue;
    end if;
    begin
      delete from public.zchat_cm_waiting where id = r.id;
      insert into public.messages (sender_id, receiver_id, group_id, type, content, client_id)
      values (r.sender_id, r.receiver_id, null, 'text', r.content, r.client_id);
      a := least(r.sender_id, r.receiver_id);
      b := greatest(r.sender_id, r.receiver_id);
      insert into public.conversations (user_a, user_b, last_message, last_message_at, last_sender_id)
      values (a, b, left(r.content, 200), now(), r.sender_id)
      on conflict (user_a, user_b) do update set last_message = excluded.last_message, last_message_at = excluded.last_message_at, last_sender_id = excluded.last_sender_id;
      n := n + 1;
    exception when others then
      raise notice 'zchat waiting message kept: %', sqlerrm;
    end;
  end loop;
  return n;
end $$;
revoke all on function public.zchat_cm_release(uuid, boolean) from public, anon, authenticated;

create or replace function public.zchat_cm_release_due()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  r record;
  n integer := 0;
begin
  for r in
    select distinct w.receiver_id
    from public.zchat_cm_waiting w
    join public.profiles p on p.id = w.receiver_id
    left join public.zchat_profile_hidden z on z.id = w.receiver_id
    where coalesce(p.last_seen, z.last_seen) > now() - interval '2 minutes'
    limit 500
  loop
    n := n + public.zchat_cm_release(r.receiver_id, true);
  end loop;
  return n;
end $$;
revoke all on function public.zchat_cm_release_due() from public, anon, authenticated;

create or replace function public.zchat_cm_on_seen()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.last_seen is not null
     and new.last_seen > coalesce(old.last_seen, '-infinity'::timestamptz)
     and new.last_seen > now() - interval '2 minutes'
     and exists (select 1 from public.zchat_cm_waiting w where w.receiver_id = new.id) then
    begin
      perform public.zchat_cm_release(new.id, false);
    exception when others then
      null;
    end;
  end if;
  return null;
end $$;

drop trigger if exists zchat_cm_on_seen on public.profiles;
create trigger zchat_cm_on_seen
  after update of last_seen on public.profiles
  for each row execute function public.zchat_cm_on_seen();

create or replace function public.zchat_cm_wait(p_to uuid, p_content text, p_client text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  body text := left(coalesce(p_content, ''), 4000);
  cid text := nullif(left(coalesce(p_client, ''), 80), '');
  n integer;
  w public.zchat_cm_waiting;
  hidden boolean;
  seen timestamptz;
  sent integer := 0;
begin
  if me is null then
    raise exception 'Log in to send messages' using errcode = '42501';
  end if;
  if p_to is null or p_to = me then
    return jsonb_build_object('ok', false, 'reason', 'target');
  end if;
  if btrim(body) = '' then
    return jsonb_build_object('ok', false, 'reason', 'empty');
  end if;
  if body ~ '^z[a-z]+:' then
    return jsonb_build_object('ok', false, 'reason', 'card');
  end if;
  if not public.zchat_cm_can_send(me, p_to) then
    return jsonb_build_object('ok', false, 'reason', 'closed');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('zchat_cm_wait:' || me::text, 0));
  if cid is not null and exists (select 1 from public.zchat_cm_waiting x where x.sender_id = me and x.client_id = cid) then
    select * into w from public.zchat_cm_waiting x where x.sender_id = me and x.client_id = cid limit 1;
    return jsonb_build_object('ok', true, 'id', w.id, 'created_at', w.created_at, 'hidden', public.zchat_cm_hides_online(p_to, me), 'sent', false);
  end if;
  select count(*) into n from public.zchat_cm_waiting x where x.sender_id = me;
  if n >= 20 then
    return jsonb_build_object('ok', false, 'reason', 'full');
  end if;
  insert into public.zchat_cm_waiting (sender_id, receiver_id, content, client_id)
  values (me, p_to, body, cid)
  returning * into w;
  hidden := public.zchat_cm_hides_online(p_to, me);
  if not hidden then
    select p.last_seen into seen from public.profiles p where p.id = p_to;
    if seen > now() - interval '40 seconds' then
      sent := public.zchat_cm_release(p_to, false);
    end if;
  end if;
  return jsonb_build_object('ok', true, 'id', w.id, 'created_at', w.created_at, 'hidden', hidden, 'sent', sent > 0 and not exists (select 1 from public.zchat_cm_waiting x where x.id = w.id));
end $$;
revoke all on function public.zchat_cm_wait(uuid, text, text) from public, anon;
grant execute on function public.zchat_cm_wait(uuid, text, text) to authenticated;

select public.zchat_apply_session_gate();

alter table public.scheduled_messages add column if not exists repeat text;
alter table public.scheduled_messages add column if not exists repeat_anchor timestamptz;
alter table public.scheduled_messages add column if not exists tz text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'zchat_cm_repeat_check' and conrelid = 'public.scheduled_messages'::regclass) then
    alter table public.scheduled_messages add constraint zchat_cm_repeat_check check (repeat is null or repeat in ('day', 'week', 'month', 'year'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'zchat_cm_tz_check' and conrelid = 'public.scheduled_messages'::regclass) then
    alter table public.scheduled_messages add constraint zchat_cm_tz_check check (tz is null or (char_length(tz) <= 64 and tz ~ '^[A-Za-z0-9_+/-]+$'));
  end if;
end $$;

create index if not exists zchat_cm_sched_repeat on public.scheduled_messages (sender_id) where repeat is not null;

create or replace function public.zchat_cm_next_at(p_anchor timestamptz, p_repeat text, p_tz text, p_after timestamptz default now())
returns timestamptz
language plpgsql
stable
set search_path = public
as $$
declare
  step interval;
  z text := coalesce(nullif(p_tz, ''), 'UTC');
  base timestamp;
  t timestamptz;
  k integer := 0;
begin
  step := case p_repeat when 'day' then interval '1 day' when 'week' then interval '7 days' when 'month' then interval '1 month' when 'year' then interval '1 year' else null end;
  if step is null or p_anchor is null then
    return null;
  end if;
  begin
    base := p_anchor at time zone z;
  exception when others then
    z := 'UTC';
    base := p_anchor at time zone z;
  end;
  if p_repeat in ('day', 'week') and p_after > p_anchor then
    k := greatest(0, floor(extract(epoch from (p_after - p_anchor)) / extract(epoch from step))::integer - 1);
  elsif p_repeat = 'month' and p_after > p_anchor then
    k := greatest(0, ((extract(year from p_after) - extract(year from p_anchor)) * 12 + extract(month from p_after) - extract(month from p_anchor))::integer - 1);
  elsif p_repeat = 'year' and p_after > p_anchor then
    k := greatest(0, (extract(year from p_after) - extract(year from p_anchor))::integer - 1);
  end if;
  loop
    k := k + 1;
    t := (base + step * k) at time zone z;
    exit when t > p_after or k > 100000;
  end loop;
  return t;
end $$;

create or replace function public.zchat_cm_sched_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  n integer;
begin
  if new.repeat is null then
    new.repeat_anchor := null;
    return new;
  end if;
  if tg_op = 'INSERT' or new.repeat_anchor is null or new.send_at is distinct from old.send_at and old.repeat is distinct from new.repeat then
    new.repeat_anchor := coalesce(new.repeat_anchor, new.send_at);
  end if;
  if tg_op = 'INSERT' or old.repeat is null then
    perform pg_advisory_xact_lock(hashtextextended('zchat_cm_repeat:' || new.sender_id::text, 0));
    select count(*) into n from public.scheduled_messages s where s.sender_id = new.sender_id and s.repeat is not null and s.id <> new.id;
    if n >= 30 then
      raise exception 'You can have up to 30 repeating messages. Stop one first.' using errcode = 'P0001';
    end if;
  end if;
  return new;
end $$;

drop trigger if exists zchat_cm_sched_guard on public.scheduled_messages;
create trigger zchat_cm_sched_guard
  before insert or update of repeat, send_at, repeat_anchor on public.scheduled_messages
  for each row execute function public.zchat_cm_sched_guard();

create or replace function public.zchat_cm_sched_claim(p_id uuid, p_due timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  s public.scheduled_messages;
  nxt timestamptz;
begin
  if me is null or p_id is null then
    return jsonb_build_object('ok', false, 'reason', 'input');
  end if;
  select * into s from public.scheduled_messages x where x.id = p_id and x.sender_id = me for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  if s.repeat is null then
    if p_due is not null and s.send_at is distinct from p_due then
      return jsonb_build_object('ok', false, 'reason', 'moved', 'at', s.send_at);
    end if;
    delete from public.scheduled_messages where id = s.id;
    return jsonb_build_object('ok', true, 'next', null);
  end if;
  if p_due is not null and abs(extract(epoch from (s.send_at - p_due))) > 1 then
    return jsonb_build_object('ok', false, 'reason', 'moved', 'at', s.send_at);
  end if;
  if s.send_at > now() + interval '2 minutes' then
    return jsonb_build_object('ok', false, 'reason', 'early', 'at', s.send_at);
  end if;
  nxt := public.zchat_cm_next_at(s.repeat_anchor, s.repeat, s.tz, greatest(now(), s.send_at));
  update public.scheduled_messages set send_at = nxt where id = s.id;
  return jsonb_build_object('ok', true, 'next', nxt);
end $$;
revoke all on function public.zchat_cm_sched_claim(uuid, timestamptz) from public, anon;
grant execute on function public.zchat_cm_sched_claim(uuid, timestamptz) to authenticated;

create or replace function public.zchat_send_due_scheduled()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  n integer := 0;
  preview text;
  allowed boolean;
begin
  for r in
    select s.* from public.scheduled_messages s
    where s.id in (select s2.id from public.scheduled_messages s2 where s2.send_at <= now() - interval '90 seconds' order by s2.send_at limit 200)
    for update skip locked
  loop
    begin
      allowed := true;
      if r.group_id is not null and not exists (select 1 from public.group_members gm where gm.group_id = r.group_id and gm.user_id = r.sender_id) then
        allowed := false;
      end if;
      if allowed and r.group_id is not null and not exists (
        select 1 from public.groups g
        where g.id = r.group_id
          and (g.created_by = r.sender_id
            or coalesce(to_jsonb(g) ->> 'send_policy', 'everyone') <> 'admins'
            or exists (select 1 from public.group_members gm where gm.group_id = g.id and gm.user_id = r.sender_id and gm.role = 'admin'))
      ) then
        allowed := false;
      end if;
      if allowed and r.receiver_id is not null and not public.zchat_can_dm(r.sender_id, r.receiver_id) then
        allowed := false;
      end if;
      if allowed and r.receiver_id is not null and exists (
        select 1 from public.blocks x
        where (x.blocker_id = r.sender_id and x.blocked_id = r.receiver_id) or (x.blocker_id = r.receiver_id and x.blocked_id = r.sender_id)
      ) then
        allowed := false;
      end if;
      if allowed and r.repeat is not null and r.receiver_id is not null and r.send_at > r.repeat_anchor + interval '1 minute'
         and not exists (select 1 from public.conversations c where c.user_a = least(r.sender_id, r.receiver_id) and c.user_b = greatest(r.sender_id, r.receiver_id)) then
        allowed := false;
      end if;
      if r.repeat is null or not allowed then
        delete from public.scheduled_messages where id = r.id;
      else
        update public.scheduled_messages set send_at = public.zchat_cm_next_at(r.repeat_anchor, r.repeat, r.tz, greatest(now(), r.send_at)) where id = r.id;
      end if;
      if allowed then
        insert into public.messages (sender_id, receiver_id, group_id, type, content)
        values (r.sender_id, r.receiver_id, r.group_id, 'text', r.content);
        if r.receiver_id is not null then
          preview := left(r.content, 200);
          insert into public.conversations (user_a, user_b, last_message, last_message_at, last_sender_id)
          values (least(r.sender_id, r.receiver_id), greatest(r.sender_id, r.receiver_id), preview, now(), r.sender_id)
          on conflict (user_a, user_b) do update set last_message = excluded.last_message, last_message_at = excluded.last_message_at, last_sender_id = excluded.last_sender_id;
        end if;
        n := n + 1;
      end if;
    exception when others then
      begin
        if r.repeat is null then
          delete from public.scheduled_messages where id = r.id;
        else
          update public.scheduled_messages set send_at = public.zchat_cm_next_at(r.repeat_anchor, r.repeat, r.tz, greatest(now(), r.send_at)) where id = r.id;
        end if;
      exception when others then
        null;
      end;
    end;
  end loop;
  begin
    n := n + public.zchat_cm_release_due();
  exception when others then
    null;
  end;
  return n;
end $function$;
commit;

begin;
create table if not exists public.zchat_cm_lt_keys (
  conv_id uuid primary key references public.conversations(id) on delete cascade,
  k text not null,
  created_at timestamptz not null default now()
);
alter table public.zchat_cm_lt_keys enable row level security;
revoke all on public.zchat_cm_lt_keys from anon, authenticated;

create or replace function public.zchat_cm_lt_key(p_peer uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  c public.conversations;
  key text;
  mine boolean;
  theirs boolean;
begin
  if me is null or p_peer is null or p_peer = me then
    return jsonb_build_object('ok', false, 'reason', 'input');
  end if;
  select * into c from public.conversations x where x.user_a = least(me, p_peer) and x.user_b = greatest(me, p_peer);
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'chat', 'mine', false, 'theirs', false);
  end if;
  mine := case when c.user_a = me then c.live_typing_a else c.live_typing_b end;
  theirs := case when c.user_a = me then c.live_typing_b else c.live_typing_a end;
  if not (coalesce(mine, false) and coalesce(theirs, false)) then
    return jsonb_build_object('ok', false, 'reason', 'off', 'mine', coalesce(mine, false), 'theirs', coalesce(theirs, false));
  end if;
  if exists (select 1 from public.blocks x where (x.blocker_id = me and x.blocked_id = p_peer) or (x.blocker_id = p_peer and x.blocked_id = me)) then
    return jsonb_build_object('ok', false, 'reason', 'off', 'mine', true, 'theirs', false);
  end if;
  insert into public.zchat_cm_lt_keys (conv_id, k)
  values (c.id, replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''))
  on conflict (conv_id) do nothing;
  select x.k into key from public.zchat_cm_lt_keys x where x.conv_id = c.id;
  return jsonb_build_object('ok', true, 'k', key, 'mine', true, 'theirs', true);
end $$;
revoke all on function public.zchat_cm_lt_key(uuid) from public, anon;
grant execute on function public.zchat_cm_lt_key(uuid) to authenticated;

create or replace function public.zchat_cm_lt_reset()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if not (coalesce(new.live_typing_a, false) and coalesce(new.live_typing_b, false)) then
    delete from public.zchat_cm_lt_keys where conv_id = new.id;
  end if;
  return null;
end $$;

drop trigger if exists zchat_cm_lt_reset on public.conversations;
create trigger zchat_cm_lt_reset
  after update of live_typing_a, live_typing_b on public.conversations
  for each row execute function public.zchat_cm_lt_reset();

create or replace function public.zchat_cm_lt_block()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  delete from public.zchat_cm_lt_keys k
  using public.conversations c
  where k.conv_id = c.id and c.user_a = least(new.blocker_id, new.blocked_id) and c.user_b = greatest(new.blocker_id, new.blocked_id);
  return null;
end $$;

drop trigger if exists zchat_cm_lt_block on public.blocks;
create trigger zchat_cm_lt_block
  after insert on public.blocks
  for each row execute function public.zchat_cm_lt_block();

select public.zchat_apply_session_gate();

create or replace function public.zchat_can_read_media(p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  ok boolean := false;
begin
  if me is null or p_name is null then
    return false;
  end if;
  if split_part(p_name, '/', 1) = me::text or public.zchat_is_admin_id(me) then
    return true;
  end if;
  select exists (
    select 1 from public.messages m
    where m.media_url = 'zp:' || p_name
      and (m.sender_id = me or m.receiver_id = me
        or (m.group_id is not null and exists (select 1 from public.group_members gm where gm.group_id = m.group_id and gm.user_id = me)))
      and not (
        m.sender_id <> me and coalesce(m.content, '') like 'zonce:%'
        and exists (select 1 from public.message_likes l where l.message_id = m.id and l.user_id = me and l.emoji = 'zo')
      )
  ) into ok;
  if ok then
    return true;
  end if;
  select exists (
    select 1 from public.zchat_capsules c
    join public.messages m on m.id = c.message_id
    where c.media_path = p_name
      and c.open_at <= now()
      and not coalesce(m.deleted, false)
      and (c.receiver_id = me or (c.group_id is not null and exists (select 1 from public.group_members gm where gm.group_id = c.group_id and gm.user_id = me)))
  ) into ok;
  if ok then
    return true;
  end if;
  select exists (
    select 1 from public.album_photos ph join public.albums a on a.id = ph.album_id
    where ph.media_url = 'zp:' || p_name and public.zchat_in_chat(a.chat_key)
  ) into ok;
  if ok then
    return true;
  end if;
  begin
    select exists (
      select 1 from public.zchat_board_items bi
      where bi.media_url = 'zp:' || p_name and bi.gone_at is null and public.zchat_in_chat(bi.chat_key)
    ) into ok;
  exception when others then
    ok := false;
  end;
  if ok then
    return true;
  end if;
  begin
    select exists (
      select 1 from public.zchat_poll_meta pm
      join public.messages m on m.id = pm.message_id
      where pm.photos @> array[p_name]
        and not coalesce(m.deleted, false)
        and (m.sender_id = me or m.receiver_id = me
          or (m.group_id is not null and exists (select 1 from public.group_members gm where gm.group_id = m.group_id and gm.user_id = me)))
    ) into ok;
  exception when others then
    ok := false;
  end;
  if ok then
    return true;
  end if;
  begin
    execute 'select exists (select 1 from public.saved_messages s where s.user_id = $1 and s.media_url = $2)' into ok using me, 'zp:' || p_name;
  exception when others then
    ok := false;
  end;
  return coalesce(ok, false);
end $function$;

select public.zchat_apply_session_gate();

create or replace function public.zchat_ct_can_write(p_key text)
returns boolean
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  other uuid;
begin
  if not public.zchat_ct_member(p_key) then
    return false;
  end if;
  if p_key like 'g:%' then
    if exists (select 1 from public.groups g where g.id = substr(p_key, 3)::uuid and g.read_only) then
      raise exception 'This group is read only' using errcode = '42501';
    end if;
    return not public.zchat_group_role_is_muted(substr(p_key, 3)::uuid, me);
  end if;
  other := public.zchat_ct_other(p_key);
  return exists (
    select 1 from public.profiles p
    where p.id = other
      and not coalesce(p.is_deleted, false)
      and not coalesce(p.is_bot, false)
      and not coalesce(p.banned, false)
  ) and not exists (
    select 1 from public.blocks b
    where (b.blocker_id = me and b.blocked_id = other) or (b.blocker_id = other and b.blocked_id = me)
  );
end
$$;
commit;

begin;
create table if not exists public.zchat_app_prefs (
  user_id uuid primary key default auth.uid() references public.profiles(id) on delete cascade,
  tabs text[],
  labs text[] not null default '{}',
  email_missed boolean not null default false,
  tz text,
  tz_share text not null default 'followers',
  email_token uuid not null default gen_random_uuid(),
  email_sent_at timestamptz,
  updated_at timestamptz not null default now()
);

alter table public.zchat_app_prefs add column if not exists tabs text[];
alter table public.zchat_app_prefs add column if not exists labs text[] not null default '{}';
alter table public.zchat_app_prefs add column if not exists email_missed boolean not null default false;
alter table public.zchat_app_prefs add column if not exists tz text;
alter table public.zchat_app_prefs add column if not exists tz_share text not null default 'followers';
alter table public.zchat_app_prefs add column if not exists email_token uuid not null default gen_random_uuid();
alter table public.zchat_app_prefs add column if not exists email_sent_at timestamptz;
alter table public.zchat_app_prefs add column if not exists updated_at timestamptz not null default now();

create unique index if not exists zchat_app_prefs_token on public.zchat_app_prefs (email_token);
create index if not exists zchat_app_prefs_mail on public.zchat_app_prefs (email_sent_at nulls first) where email_missed;

alter table public.zchat_app_prefs drop constraint if exists zchat_app_prefs_tabs_ok;
alter table public.zchat_app_prefs add constraint zchat_app_prefs_tabs_ok check (
  tabs is null or (cardinality(tabs) between 1 and 5 and 'chats' = any (tabs)
    and tabs <@ array['chats', 'moments', 'create', 'calls', 'me', 'communities', 'shop']::text[]));
alter table public.zchat_app_prefs drop constraint if exists zchat_app_prefs_labs_ok;
alter table public.zchat_app_prefs add constraint zchat_app_prefs_labs_ok check (cardinality(labs) <= 30);
alter table public.zchat_app_prefs drop constraint if exists zchat_app_prefs_share_ok;
alter table public.zchat_app_prefs add constraint zchat_app_prefs_share_ok check (tz_share in ('everyone', 'followers', 'nobody'));
alter table public.zchat_app_prefs drop constraint if exists zchat_app_prefs_tz_ok;
alter table public.zchat_app_prefs add constraint zchat_app_prefs_tz_ok check (
  tz is null or (char_length(tz) <= 64 and tz ~ '^[A-Za-z_]+(/[A-Za-z0-9_+-]+){0,2}$'));

create or replace function public.zchat_app_prefs_guard()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if new.tabs is not null and cardinality(new.tabs) = 0 then
    new.tabs := null;
  end if;
  if new.tabs is not null and exists (select 1 from unnest(new.tabs) x group by x having count(*) > 1) then
    raise exception 'Each tab can show only once' using errcode = '22023';
  end if;
  new.labs := coalesce(new.labs, '{}'::text[]);
  if exists (select 1 from unnest(new.labs) x where x is null or x !~ '^[a-z0-9_]{1,40}$') then
    raise exception 'That test feature is not known' using errcode = '22023';
  end if;
  new.labs := array(select distinct x from unnest(new.labs) x order by x);
  if new.tz is not null then
    begin
      perform now() at time zone new.tz;
    exception when others then
      raise exception 'That time zone is not known' using errcode = '22023';
    end;
  end if;
  if current_user in ('authenticated', 'anon') then
    if tg_op = 'INSERT' then
      new.email_token := gen_random_uuid();
      new.email_sent_at := null;
    else
      new.email_token := old.email_token;
      new.email_sent_at := old.email_sent_at;
      new.user_id := old.user_id;
    end if;
  end if;
  new.updated_at := now();
  return new;
end $$;

drop trigger if exists zchat_app_prefs_guard on public.zchat_app_prefs;
create trigger zchat_app_prefs_guard before insert or update on public.zchat_app_prefs
  for each row execute function public.zchat_app_prefs_guard();

alter table public.zchat_app_prefs enable row level security;
revoke all on public.zchat_app_prefs from public, anon, authenticated;
grant select (user_id, tabs, labs, email_missed, tz, tz_share, email_sent_at, updated_at) on public.zchat_app_prefs to authenticated;
grant insert (user_id, tabs, labs, email_missed, tz, tz_share) on public.zchat_app_prefs to authenticated;
grant update (user_id, tabs, labs, email_missed, tz, tz_share) on public.zchat_app_prefs to authenticated;
grant delete on public.zchat_app_prefs to authenticated;
grant all on public.zchat_app_prefs to service_role;

drop policy if exists "zchat app prefs own read" on public.zchat_app_prefs;
create policy "zchat app prefs own read" on public.zchat_app_prefs
  for select to authenticated using (user_id = auth.uid());

