create or replace function public.zchat_local_time(p_user uuid)
returns text
language sql
stable
security definer
set search_path = public
as $$
  select case
    when auth.uid() is null or p_user is null or p.tz is null then null
    when p.user_id = auth.uid() then p.tz
    when public.zchat_blocked_pair(p.user_id, auth.uid()) then null
    when p.tz_share = 'everyone' then p.tz
    when p.tz_share = 'followers' and exists (
      select 1 from public.follows f
      where f.follower_id = auth.uid() and f.following_id = p.user_id and coalesce(f.status, 'accepted') = 'accepted'
    ) then p.tz
    else null
  end
  from public.zchat_app_prefs p
  join public.profiles pr on pr.id = p.user_id
  where p.user_id = p_user
    and not coalesce(pr.is_deleted, false)
    and not coalesce(pr.banned, false)
$$;

revoke execute on function public.zchat_local_time(uuid) from public, anon;
grant execute on function public.zchat_local_time(uuid) to authenticated, service_role;

create or replace function public.zchat_local_times(p_users uuid[])
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(jsonb_object_agg(x.id::text, public.zchat_local_time(x.id)), '{}'::jsonb)
  from (select distinct u as id from unnest(coalesce(p_users, '{}'::uuid[])) u where u is not null limit 100) x
  where auth.uid() is not null
$$;

revoke execute on function public.zchat_local_times(uuid[]) from public, anon;
grant execute on function public.zchat_local_times(uuid[]) to authenticated, service_role;

