create or replace function public.zchat_problem_reports_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  role_now text := coalesce(nullif(current_setting('request.jwt.claim.role', true), ''), nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '');
  p text;
begin
  if role_now = 'service_role' or (role_now = '' and me is null) then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if not public.zchat_is_admin() then
      raise exception 'Only the ZChat team can change a report' using errcode = '42501';
    end if;
    new.id := old.id;
    new.user_id := old.user_id;
    new.kind := old.kind;
    new.lab := old.lab;
    new.body := old.body;
    new.shots := old.shots;
    new.device := old.device;
    new.created_at := old.created_at;
    return new;
  end if;
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  new.user_id := me;
  new.status := 'new';
  new.admin_note := null;
  new.created_at := now();
  new.body := btrim(coalesce(new.body, ''));
  if char_length(new.body) < 2 then
    raise exception 'Tell us a little more about it' using errcode = '22023';
  end if;
  new.shots := coalesce(new.shots, '{}'::text[]);
  foreach p in array new.shots loop
    if p is null or p !~ ('^' || me::text || '/[A-Za-z0-9._-]{1,100}$') then
      raise exception 'That screenshot cannot be added' using errcode = '22023';
    end if;
  end loop;
  if new.device is not null and (jsonb_typeof(new.device) <> 'object' or pg_column_size(new.device) > 8000) then
    raise exception 'Too much device detail' using errcode = '22023';
  end if;
  if (select count(*) from public.zchat_problem_reports r where r.user_id = me and r.created_at > now() - interval '10 minutes') >= 5
     or (select count(*) from public.zchat_problem_reports r where r.user_id = me and r.created_at > now() - interval '1 day') >= 30 then
    raise exception 'You sent a few reports just now. Try again in a little while' using errcode = '54000';
  end if;
  return new;
end $$;

