create or replace function public.zchat_digest_due(p_limit integer default 100)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_lim integer := least(greatest(coalesce(p_limit, 100), 1), 500);
  v_out jsonb;
begin
  if not public.zchat_digest_role_ok() then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  with cand as (
    select p.user_id, p.email_token, p.email_sent_at, pr.name, u.email,
      greatest(pr.last_seen, h.last_seen) as seen_at
    from public.zchat_app_prefs p
    join public.profiles pr on pr.id = p.user_id
    join auth.users u on u.id = p.user_id
    left join public.zchat_profile_hidden h on h.id = p.user_id
    where p.email_missed
      and (p.email_sent_at is null or p.email_sent_at < now() - interval '23 hours')
      and (p.tz is null or extract(hour from (now() at time zone p.tz)) between 8 and 20)
      and not coalesce(pr.is_deleted, false) and not coalesce(pr.banned, false) and not coalesce(pr.is_bot, false)
      and u.email is not null and u.email like '%@%'
      and u.deleted_at is null and (u.banned_until is null or u.banned_until < now())
    order by p.email_sent_at nulls first
    limit v_lim * 4
  ),
  waiting as (
    select c.user_id, m.sender_id, count(*) as n, min(m.created_at) as first_at, max(m.created_at) as last_at
    from cand c
    join public.messages m on m.receiver_id = c.user_id and m.group_id is null
    where not coalesce(m.read, false)
      and not coalesce(m.deleted, false)
      and m.sender_id is not null and m.sender_id <> c.user_id
      and m.created_at > coalesce(c.seen_at, '-infinity'::timestamptz)
      and m.created_at > now() - interval '14 days'
      and (m.expires_at is null or m.expires_at > now())
    group by c.user_id, m.sender_id
  ),
  kept as (
    select w.user_id, w.n, w.first_at, w.last_at, s.name as sender_name
    from waiting w
    join public.profiles s on s.id = w.sender_id
    where not coalesce(s.is_deleted, false) and not coalesce(s.banned, false) and not coalesce(s.is_bot, false)
      and not public.zchat_blocked_pair(w.user_id, w.sender_id)
      and (
        exists (select 1 from public.follows f where f.follower_id = w.user_id and f.following_id = w.sender_id and coalesce(f.status, 'accepted') = 'accepted')
        or exists (select 1 from public.messages mm where mm.sender_id = w.user_id and mm.receiver_id = w.sender_id and mm.group_id is null)
      )
      and not exists (
        select 1 from public.conversations cv
        where (cv.user_a = w.user_id and cv.user_b = w.sender_id and cv.muted_until_a > now())
           or (cv.user_b = w.user_id and cv.user_a = w.sender_id and cv.muted_until_b > now())
      )
  ),
  per_user as (
    select c.user_id, c.email, c.name, c.email_token, c.email_sent_at,
      sum(k.n)::integer as total, count(*)::integer as people,
      bool_or(k.first_at < now() - interval '1 day') as old_enough,
      max(k.last_at) as newest,
      jsonb_agg(jsonb_build_object('name', coalesce(nullif(btrim(k.sender_name), ''), 'Someone'), 'n', k.n) order by k.n desc, k.sender_name) as senders
    from cand c
    join kept k on k.user_id = c.user_id
    group by c.user_id, c.email, c.name, c.email_token, c.email_sent_at
  )
  select coalesce(jsonb_agg(jsonb_build_object('user_id', x.user_id, 'email', x.email, 'name', coalesce(nullif(btrim(x.name), ''), 'there'), 'token', x.email_token, 'total', x.total, 'people', x.people, 'senders', x.senders) order by x.total desc), '[]'::jsonb)
  into v_out
  from (
    select * from per_user
    where old_enough and (email_sent_at is null or newest > email_sent_at)
    order by total desc
    limit v_lim
  ) x;
  return v_out;
end $$;

revoke execute on function public.zchat_digest_due(integer) from public, anon, authenticated;
grant execute on function public.zchat_digest_due(integer) to service_role;

create or replace function public.zchat_digest_mark(p_users uuid[])
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_n integer;
begin
  if not public.zchat_digest_role_ok() then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  update public.zchat_app_prefs p set email_sent_at = now()
  where p.user_id = any (coalesce(p_users, '{}'::uuid[])) and p.email_missed;
  get diagnostics v_n = row_count;
  return v_n;
end $$;

revoke execute on function public.zchat_digest_mark(uuid[]) from public, anon, authenticated;
grant execute on function public.zchat_digest_mark(uuid[]) to service_role;

create or replace function public.zchat_email_unsub(p_token uuid)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_hit uuid;
begin
  if not public.zchat_digest_role_ok() then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  if p_token is null then
    return false;
  end if;
  update public.zchat_app_prefs p set email_missed = false
  where p.email_token = p_token
  returning p.user_id into v_hit;
  return v_hit is not null;
end $$;

revoke execute on function public.zchat_email_unsub(uuid) from public, anon, authenticated;
grant execute on function public.zchat_email_unsub(uuid) to service_role;
commit;

