create or replace function public.zchat_live_poll_start(p_live uuid, p_group uuid, p_question text, p_options jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  q text := left(public.zchat_live_clean(p_question, 140), 140);
  opts jsonb := '[]'::jsonb;
  seen text[] := '{}';
  x text;
  o text;
  s public.live_sessions;
  n integer;
  p public.live_polls;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'signin');
  end if;
  if (p_live is null) = (p_group is null) then
    return jsonb_build_object('ok', false, 'reason', 'where');
  end if;
  if q is null then
    return jsonb_build_object('ok', false, 'reason', 'question');
  end if;
  if p_options is null or jsonb_typeof(p_options) <> 'array' or jsonb_array_length(p_options) > 4 then
    return jsonb_build_object('ok', false, 'reason', 'options');
  end if;
  for x in select e.value from jsonb_array_elements_text(p_options) e loop
    o := left(public.zchat_live_clean(x, 60), 60);
    if o is not null and not (lower(o) = any (seen)) then
      seen := seen || lower(o);
      opts := opts || to_jsonb(o);
    end if;
  end loop;
  if jsonb_array_length(opts) < 2 then
    return jsonb_build_object('ok', false, 'reason', 'options');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('zchat_live_poll:' || coalesce(p_live, p_group)::text, 0));
  if p_live is not null then
    select * into s from public.live_sessions where id = p_live;
    if not found then
      return jsonb_build_object('ok', false, 'reason', 'gone');
    end if;
    if s.status <> 'live' then
      return jsonb_build_object('ok', false, 'reason', 'ended');
    end if;
    if not (s.host_id = me or me = any (s.mods)) then
      return jsonb_build_object('ok', false, 'reason', 'host');
    end if;
  else
    if public.zchat_room_rank(p_group, me) < 1 then
      return jsonb_build_object('ok', false, 'reason', 'mod');
    end if;
    if exists (select 1 from public.voice_rooms r where r.group_id = p_group and not r.enabled) then
      return jsonb_build_object('ok', false, 'reason', 'off');
    end if;
  end if;
  if exists (select 1 from public.live_polls lp where lp.created_by = me and lp.created_at > now() - interval '8 seconds') then
    return jsonb_build_object('ok', false, 'reason', 'slow');
  end if;
  select count(*) into n from public.live_polls lp
    where (lp.live_id = p_live or lp.group_id = p_group) and lp.created_at > now() - interval '1 hour';
  if n >= 30 then
    return jsonb_build_object('ok', false, 'reason', 'busy');
  end if;
  update public.live_polls set status = 'ended', ended_at = now()
    where status = 'open' and (live_id = p_live or group_id = p_group);
  insert into public.live_polls (live_id, group_id, created_by, question, options, counts)
    values (p_live, p_group, me, q, opts, array_fill(0, array[jsonb_array_length(opts)]))
    returning * into p;
  return jsonb_build_object('ok', true, 'poll', to_jsonb(p) || jsonb_build_object('mine', null));
end $$;

create or replace function public.zchat_live_poll_vote(p_poll uuid, p_choice integer)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  p public.live_polls;
  s public.live_sessions;
  had smallint;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'signin');
  end if;
  select * into p from public.live_polls where id = p_poll for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  if p.live_id is not null then
    select * into s from public.live_sessions where id = p.live_id;
    if not found or not public.zchat_live_visible(s.host_id) then
      return jsonb_build_object('ok', false, 'reason', 'gone');
    end if;
    if exists (select 1 from public.live_bans b where b.live_id = s.id and b.user_id = me and b.kind = 'remove') then
      return jsonb_build_object('ok', false, 'reason', 'removed');
    end if;
  elsif public.zchat_room_rank(p.group_id, me) < 0 then
    return jsonb_build_object('ok', false, 'reason', 'member');
  end if;
  select v.choice into had from public.live_poll_votes v where v.poll_id = p_poll and v.user_id = me;
  if found then
    return jsonb_build_object('ok', false, 'reason', 'voted', 'mine', had, 'poll', to_jsonb(p) || jsonb_build_object('mine', had));
  end if;
  if p.status <> 'open' or (p.live_id is not null and s.status <> 'live') then
    return jsonb_build_object('ok', false, 'reason', 'ended', 'poll', to_jsonb(p) || jsonb_build_object('mine', null));
  end if;
  if p_choice is null or p_choice < 0 or p_choice >= jsonb_array_length(p.options) then
    return jsonb_build_object('ok', false, 'reason', 'choice');
  end if;
  insert into public.live_poll_votes (poll_id, user_id, choice) values (p_poll, me, p_choice);
  update public.live_polls
    set counts[p_choice + 1] = counts[p_choice + 1] + 1, total = total + 1
    where id = p_poll
    returning * into p;
  return jsonb_build_object('ok', true, 'mine', p_choice, 'poll', to_jsonb(p) || jsonb_build_object('mine', p_choice));
end $$;

create or replace function public.zchat_live_poll_end(p_poll uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  p public.live_polls;
  allowed boolean;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'signin');
  end if;
  select * into p from public.live_polls where id = p_poll for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  if p.live_id is not null then
    allowed := p.created_by = me or public.zchat_live_is_mod(p.live_id, me);
  else
    allowed := p.created_by = me or public.zchat_room_rank(p.group_id, me) >= 1;
  end if;
  if not allowed then
    return jsonb_build_object('ok', false, 'reason', 'mod');
  end if;
  if p.status = 'open' then
    update public.live_polls set status = 'ended', ended_at = now() where id = p_poll returning * into p;
  end if;
  return jsonb_build_object('ok', true, 'poll', to_jsonb(p) || jsonb_build_object('mine', (select v.choice from public.live_poll_votes v where v.poll_id = p.id and v.user_id = me)));
end $$;

create or replace function public.zchat_live_poll_now(p_live uuid, p_group uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  p public.live_polls;
  mine smallint;
begin
  if me is null or ((p_live is null) = (p_group is null)) then
    return jsonb_build_object('ok', false, 'reason', 'where');
  end if;
  if not public.zchat_live_poll_visible(p_live, p_group) then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  select * into p from public.live_polls lp
    where (lp.live_id = p_live or lp.group_id = p_group)
      and (lp.status = 'open' or lp.ended_at > now() - interval '12 seconds')
    order by lp.created_at desc
    limit 1;
  if not found then
    return jsonb_build_object('ok', true, 'poll', null);
  end if;
  select v.choice into mine from public.live_poll_votes v where v.poll_id = p.id and v.user_id = me;
  return jsonb_build_object('ok', true, 'poll', to_jsonb(p) || jsonb_build_object('mine', mine));
end $$;

