create or replace function public.zchat_live_question_visible(p_live uuid, p_user uuid, p_status text, p_shown timestamptz)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select auth.uid() is not null and exists (
    select 1 from public.live_sessions s
    where s.id = p_live and public.zchat_live_visible(s.host_id)
      and (p_user = auth.uid() or s.host_id = auth.uid() or auth.uid() = any (s.mods) or p_status in ('showing', 'answered') or (p_status = 'removed' and p_shown is not null))
  ) and (p_user = auth.uid() or not public.zchat_blocked_pair(auth.uid(), p_user))
$$;
revoke all on function public.zchat_live_question_visible(uuid, uuid, text, timestamptz) from public, anon;
