create or replace function public.zchat_live_ask(p_live uuid, p_body text, p_cid text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  s public.live_sessions;
  b text := left(public.zchat_live_clean(p_body, 200), 200);
  cid text := left(nullif(btrim(coalesce(p_cid, '')), ''), 40);
  last_at timestamptz;
  n integer;
  q public.live_questions;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'signin');
  end if;
  if b is null then
    return jsonb_build_object('ok', false, 'reason', 'empty');
  end if;
  select * into s from public.live_sessions where id = p_live;
  if not found or not public.zchat_live_visible(s.host_id) then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  if s.status <> 'live' then
    return jsonb_build_object('ok', false, 'reason', 'ended');
  end if;
  if s.host_id = me then
    return jsonb_build_object('ok', false, 'reason', 'host');
  end if;
  if not s.qa_on then
    return jsonb_build_object('ok', false, 'reason', 'off');
  end if;
  if exists (select 1 from public.user_restrictions r where r.user_id = me and r.kind = 'chat' and not r.lifted and r.until > now()) then
    return jsonb_build_object('ok', false, 'reason', 'paused');
  end if;
  if exists (select 1 from public.live_bans x where x.live_id = p_live and x.user_id = me) then
    return jsonb_build_object('ok', false, 'reason', 'muted');
  end if;
  if exists (select 1 from public.profiles p where p.id = me and (coalesce(p.banned, false) or coalesce(p.is_deleted, false))) then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('zchat_live_ask:' || me::text, 0));
  if exists (select 1 from public.live_questions w where w.live_id = p_live and w.user_id = me and w.status = 'waiting') then
    return jsonb_build_object('ok', false, 'reason', 'waiting');
  end if;
  select max(w.created_at) into last_at from public.live_questions w where w.live_id = p_live and w.user_id = me;
  if last_at is not null and last_at > now() - interval '30 seconds' then
    return jsonb_build_object('ok', false, 'reason', 'slow', 'wait', greatest(1, ceil(extract(epoch from (last_at + interval '30 seconds' - now()))))::integer);
  end if;
  select count(*) into n from public.live_questions w where w.user_id = me and w.created_at > now() - interval '1 hour';
  if n >= 40 then
    return jsonb_build_object('ok', false, 'reason', 'slow', 'wait', 60);
  end if;
  insert into public.live_questions (live_id, user_id, body, client_id) values (p_live, me, b, cid) returning * into q;
  return jsonb_build_object('ok', true, 'question', to_jsonb(q));
end $$;

create or replace function public.zchat_live_question_set(p_question uuid, p_action text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  q public.live_questions;
  s public.live_sessions;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'signin');
  end if;
  select * into q from public.live_questions where id = p_question for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  select * into s from public.live_sessions where id = q.live_id;
  if not found or s.status <> 'live' then
    return jsonb_build_object('ok', false, 'reason', 'ended');
  end if;
  if p_action = 'show' then
    if me is distinct from s.host_id then
      return jsonb_build_object('ok', false, 'reason', 'host');
    end if;
    if q.status <> 'waiting' then
      return jsonb_build_object('ok', false, 'reason', 'state', 'question', to_jsonb(q));
    end if;
    update public.live_questions set status = 'answered', answered_at = now() where live_id = q.live_id and status = 'showing';
    update public.live_questions set status = 'showing', shown_at = now() where id = q.id returning * into q;
  elsif p_action = 'done' then
    if me is distinct from s.host_id then
      return jsonb_build_object('ok', false, 'reason', 'host');
    end if;
    if q.status in ('waiting', 'showing') then
      update public.live_questions set status = 'answered', answered_at = now() where id = q.id returning * into q;
    end if;
  elsif p_action = 'remove' then
    if not (me = s.host_id or me = any (s.mods) or (q.user_id = me and q.status = 'waiting')) then
      return jsonb_build_object('ok', false, 'reason', 'mod');
    end if;
    if q.status <> 'removed' then
      update public.live_questions set status = 'removed', body = case when shown_at is null then body else '' end where id = q.id returning * into q;
    end if;
  else
    return jsonb_build_object('ok', false, 'reason', 'action');
  end if;
  return jsonb_build_object('ok', true, 'question', to_jsonb(q));
end $$;

create or replace function public.zchat_live_questions(p_live uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  s public.live_sessions;
  modr boolean;
begin
  if me is null then
    return '[]'::jsonb;
  end if;
  select * into s from public.live_sessions where id = p_live;
  if not found or not public.zchat_live_visible(s.host_id) then
    return '[]'::jsonb;
  end if;
  modr := s.host_id = me or me = any (s.mods);
  return coalesce((
    select jsonb_agg(to_jsonb(x) order by x.created_at) from (
      select q.id, q.live_id, q.user_id, q.body, q.client_id, q.status, q.created_at, q.shown_at, q.answered_at,
        (select jsonb_build_object('name', p.name, 'username', p.username, 'avatar', p.avatar) from public.profiles p where p.id = q.user_id) as who
      from public.live_questions q
      where q.live_id = p_live and q.status <> 'removed'
        and (modr or q.user_id = me or q.status in ('showing', 'answered'))
        and (q.user_id = me or not public.zchat_blocked_pair(me, q.user_id))
      order by q.created_at desc
      limit 100
    ) x
  ), '[]'::jsonb);
end $$;

