create or replace function public.zchat_live_goal_count()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.live_goals g
    set progress = least(g.progress + new.amount, 1000000000),
        status = case when g.status = 'active' and g.progress + new.amount >= g.target then 'reached' else g.status end,
        reached_at = case when g.status = 'active' and g.progress + new.amount >= g.target then now() else g.reached_at end
    where g.live_id = new.live_id and g.status <> 'ended' and g.created_at <= new.created_at;
  return null;
end $$;
revoke all on function public.zchat_live_goal_count() from public, anon, authenticated;

drop trigger if exists zchat_live_goal_count on public.live_gifts;
create trigger zchat_live_goal_count after insert on public.live_gifts for each row execute function public.zchat_live_goal_count();

create or replace function public.zchat_live_goal_set(p_live uuid, p_title text, p_target integer)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  s public.live_sessions;
  t text := left(public.zchat_live_clean(p_title, 40), 40);
  n integer;
  g public.live_goals;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'signin');
  end if;
  select * into s from public.live_sessions where id = p_live for update;
  if not found or s.host_id is distinct from me then
    return jsonb_build_object('ok', false, 'reason', 'host');
  end if;
  if s.status <> 'live' then
    return jsonb_build_object('ok', false, 'reason', 'ended');
  end if;
  if t is null then
    return jsonb_build_object('ok', false, 'reason', 'title');
  end if;
  if p_target is null or p_target < 10 or p_target > 100000 then
    return jsonb_build_object('ok', false, 'reason', 'target');
  end if;
  select count(*) into n from public.live_goals x where x.live_id = p_live;
  if n >= 20 then
    return jsonb_build_object('ok', false, 'reason', 'busy');
  end if;
  if exists (select 1 from public.live_goals x where x.live_id = p_live and x.created_at > now() - interval '3 seconds') then
    return jsonb_build_object('ok', false, 'reason', 'slow');
  end if;
  update public.live_goals set status = 'ended', ended_at = now() where live_id = p_live and status <> 'ended';
  insert into public.live_goals (live_id, host_id, title, target) values (p_live, me, t, p_target) returning * into g;
  return jsonb_build_object('ok', true, 'goal', to_jsonb(g));
end $$;

create or replace function public.zchat_live_goal_end(p_live uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  s public.live_sessions;
  g public.live_goals;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'signin');
  end if;
  select * into s from public.live_sessions where id = p_live for update;
  if not found or s.host_id is distinct from me then
    return jsonb_build_object('ok', false, 'reason', 'host');
  end if;
  update public.live_goals set status = 'ended', ended_at = now()
    where live_id = p_live and status <> 'ended'
    returning * into g;
  return jsonb_build_object('ok', true, 'goal', case when g.id is null then null else to_jsonb(g) end);
end $$;

