create or replace function public.zchat_live_top(p_live uuid, p_viewer uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'user_id', x.user_id, 'coins', x.coins, 'gifts', x.gifts,
      'name', x.name, 'username', x.username, 'avatar', x.avatar
    ) order by x.coins desc, x.first_at), '[]'::jsonb)
  from (
    select g.user_id, sum(g.amount)::integer as coins, count(*)::integer as gifts, min(g.created_at) as first_at,
      p.name, p.username, p.avatar
    from public.live_gifts g
    join public.profiles p on p.id = g.user_id
    where g.live_id = p_live
      and not coalesce(p.is_deleted, false) and not coalesce(p.banned, false)
      and (p_viewer is null or g.user_id = p_viewer or not public.zchat_blocked_pair(p_viewer, g.user_id))
    group by g.user_id, p.name, p.username, p.avatar
    order by sum(g.amount) desc, min(g.created_at)
    limit 5
  ) x
$$;
revoke all on function public.zchat_live_top(uuid, uuid) from public, anon, authenticated;

create or replace function public.zchat_live_supporters(p_live uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  s public.live_sessions;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'signin');
  end if;
  select * into s from public.live_sessions where id = p_live;
  if not found or not public.zchat_live_visible(s.host_id) then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  if s.host_id <> me and not (s.status = 'ended' and s.show_supporters) then
    return jsonb_build_object('ok', true, 'shown', false, 'list', '[]'::jsonb);
  end if;
  return jsonb_build_object('ok', true, 'shown', s.show_supporters, 'thanked', s.thanked_at is not null, 'list', public.zchat_live_top(p_live, me));
end $$;

create or replace function public.zchat_live_supporters_show(p_live uuid, p_on boolean)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  s public.live_sessions;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'signin');
  end if;
  select * into s from public.live_sessions where id = p_live for update;
  if not found or s.host_id is distinct from me then
    return jsonb_build_object('ok', false, 'reason', 'host');
  end if;
  if s.show_supporters is distinct from coalesce(p_on, false) then
    update public.live_sessions set show_supporters = coalesce(p_on, false) where id = p_live returning * into s;
  end if;
  return jsonb_build_object('ok', true, 'shown', s.show_supporters);
end $$;

create or replace function public.zchat_live_thank(p_live uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  s public.live_sessions;
  top jsonb;
  ids uuid[];
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'signin');
  end if;
  select * into s from public.live_sessions where id = p_live for update;
  if not found or s.host_id is distinct from me then
    return jsonb_build_object('ok', false, 'reason', 'host');
  end if;
  if s.status = 'live' then
    return jsonb_build_object('ok', false, 'reason', 'live');
  end if;
  if s.thanked_at is not null then
    return jsonb_build_object('ok', true, 'already', true, 'push', '[]'::jsonb);
  end if;
  top := public.zchat_live_top(p_live, me);
  select array_agg((e ->> 'user_id')::uuid) into ids from jsonb_array_elements(top) e;
  if ids is null then
    return jsonb_build_object('ok', false, 'reason', 'nobody');
  end if;
  perform public.zchat_notify(u, me, 'live_thanks', null, left(s.title, 80), jsonb_build_object('live', s.id)) from unnest(ids) as u;
  update public.live_sessions set thanked_at = now() where id = p_live;
  return jsonb_build_object('ok', true, 'sent', coalesce(array_length(ids, 1), 0), 'push', to_jsonb(ids));
end $$;

revoke all on function public.zchat_live_supporters(uuid) from public, anon;
revoke all on function public.zchat_live_supporters_show(uuid, boolean) from public, anon;
revoke all on function public.zchat_live_thank(uuid) from public, anon;
grant execute on function public.zchat_live_supporters(uuid) to authenticated;
grant execute on function public.zchat_live_supporters_show(uuid, boolean) to authenticated;
grant execute on function public.zchat_live_thank(uuid) to authenticated;
commit;

begin;
create table if not exists public.live_plans (
  id uuid primary key default gen_random_uuid(),
  host_id uuid not null references public.profiles(id) on delete cascade,
  kind text not null,
  group_id uuid references public.groups(id) on delete cascade,
  title text not null,
  cover text,
  starts_at timestamptz not null,
  status text not null default 'planned',
  live_id uuid references public.live_sessions(id) on delete set null,
  reminders integer not null default 0,
  reminded_at timestamptz,
  nudged_at timestamptz,
  pushed_at timestamptz,
  started_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint live_plans_kind_ok check (kind in ('live', 'room')),
  constraint live_plans_group_ok check ((kind = 'room') = (group_id is not null)),
  constraint live_plans_title_ok check (char_length(title) between 1 and 80),
  constraint live_plans_cover_ok check (cover is null or char_length(cover) <= 600),
  constraint live_plans_status_ok check (status in ('planned', 'started', 'cancelled', 'missed')),
  constraint live_plans_reminders_ok check (reminders >= 0)
);
alter table public.live_plans add column if not exists card jsonb;
alter table public.live_plans drop constraint if exists live_plans_card_ok;
alter table public.live_plans add constraint live_plans_card_ok check (card is null or (jsonb_typeof(card) = 'object' and length(card::text) <= 2000));
create index if not exists zchat_live_plans_host on public.live_plans (host_id, starts_at);
create index if not exists zchat_live_plans_group on public.live_plans (group_id, starts_at) where group_id is not null;
create index if not exists zchat_live_plans_due on public.live_plans (starts_at) where status = 'planned';

create table if not exists public.live_plan_reminders (
  plan_id uuid not null references public.live_plans(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (plan_id, user_id)
);
create index if not exists zchat_live_plan_reminders_user on public.live_plan_reminders (user_id, created_at desc);

create or replace function public.zchat_plan_visible(p_kind text, p_host uuid, p_group uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select auth.uid() is not null and p_host is not null and (
    p_host = auth.uid()
    or (p_kind = 'live' and public.zchat_live_visible(p_host))
    or (p_kind = 'room' and p_group is not null and public.zchat_room_rank(p_group, auth.uid()) >= 0)
  )
$$;
revoke all on function public.zchat_plan_visible(text, uuid, uuid) from public, anon;
grant execute on function public.zchat_plan_visible(text, uuid, uuid) to authenticated;

alter table public.live_plans enable row level security;
alter table public.live_plan_reminders enable row level security;
drop policy if exists "zchat live plans read" on public.live_plans;
create policy "zchat live plans read" on public.live_plans for select to authenticated using (public.zchat_plan_visible(kind, host_id, group_id));
drop policy if exists "zchat live plan reminders read" on public.live_plan_reminders;
create policy "zchat live plan reminders read" on public.live_plan_reminders for select to authenticated using (
  user_id = auth.uid() or exists (select 1 from public.live_plans p where p.id = live_plan_reminders.plan_id and p.host_id = auth.uid())
);
revoke all on public.live_plans from anon;
revoke all on public.live_plan_reminders from anon;
revoke insert, update, delete, truncate on public.live_plans from authenticated;
revoke insert, update, delete, truncate on public.live_plan_reminders from authenticated;
grant select on public.live_plans to authenticated;
grant select on public.live_plan_reminders to authenticated;

create or replace function public.zchat_plan_cover_ok(p_cover text, p_user uuid)
returns boolean
language sql
immutable
as $$
  select p_cover is null or (
    char_length(p_cover) <= 600
    and p_cover ~ ('^https://[A-Za-z0-9.-]+/storage/v1/object/public/chat-media/' || p_user::text || '/[A-Za-z0-9._-]+$')
  )
$$;
revoke all on function public.zchat_plan_cover_ok(text, uuid) from public, anon, authenticated;

create or replace function public.zchat_plan_row(p public.live_plans)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select (to_jsonb(p) - 'reminded_at' - 'nudged_at' - 'pushed_at' - 'card') || jsonb_build_object(
    'host', (select jsonb_build_object('id', pr.id, 'name', pr.name, 'username', pr.username, 'avatar', pr.avatar, 'verified', pr.verified) from public.profiles pr where pr.id = p.host_id),
    'group', case when p.group_id is null then null else (select jsonb_build_object('id', g.id, 'name', g.name, 'avatar', g.avatar) from public.groups g where g.id = p.group_id) end,
    'mine', exists (select 1 from public.live_plan_reminders r where r.plan_id = p.id and r.user_id = auth.uid())
  )
$$;
revoke all on function public.zchat_plan_row(public.live_plans) from public, anon, authenticated;

create or replace function public.zchat_plan_create(p_kind text, p_title text, p_starts_at timestamptz, p_group uuid default null, p_cover text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  t text := left(public.zchat_live_clean(p_title, 80), 80);
  cv text := nullif(btrim(coalesce(p_cover, '')), '');
  pr record;
  n integer;
  p public.live_plans;
  cd jsonb;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'signin');
  end if;
  if p_kind is null or p_kind not in ('live', 'room') or (p_kind = 'live' and p_group is not null) then
    return jsonb_build_object('ok', false, 'reason', 'kind');
  end if;
  select x.is_deleted, x.banned, x.is_bot into pr from public.profiles x where x.id = me;
  if not found or coalesce(pr.is_deleted, false) or coalesce(pr.banned, false) or coalesce(pr.is_bot, false) then
    return jsonb_build_object('ok', false, 'reason', 'account');
  end if;
  if exists (select 1 from public.user_restrictions r where r.user_id = me and r.kind = 'post' and not r.lifted and r.until > now()) then
    return jsonb_build_object('ok', false, 'reason', 'paused');
  end if;
  if t is null then
    return jsonb_build_object('ok', false, 'reason', 'title');
  end if;
  if p_starts_at is null or p_starts_at < now() + interval '9 minutes' or p_starts_at > now() + interval '30 days' then
    return jsonb_build_object('ok', false, 'reason', 'time');
  end if;
  if not public.zchat_plan_cover_ok(cv, me) then
    return jsonb_build_object('ok', false, 'reason', 'cover');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('zchat_plan:' || me::text, 0));
  select count(*) into n from public.live_plans x where x.host_id = me and x.created_at > now() - interval '1 day';
  if n >= 12 then
    return jsonb_build_object('ok', false, 'reason', 'slow');
  end if;
  if p_kind = 'room' then
    if p_group is null or public.zchat_room_rank(p_group, me) < 0 then
      return jsonb_build_object('ok', false, 'reason', 'member');
    end if;
    if exists (select 1 from public.voice_rooms r where r.group_id = p_group and not r.enabled) then
      return jsonb_build_object('ok', false, 'reason', 'off');
    end if;
    select count(*) into n from public.live_plans x where x.group_id = p_group and x.status = 'planned' and x.starts_at > now() - interval '1 hour';
    if n >= 6 then
      return jsonb_build_object('ok', false, 'reason', 'full');
    end if;
    select count(*) into n from public.live_plans x where x.group_id = p_group and x.host_id = me and x.status = 'planned' and x.starts_at > now() - interval '1 hour';
    if n >= 3 then
      return jsonb_build_object('ok', false, 'reason', 'full');
    end if;
  else
    select count(*) into n from public.live_plans x where x.host_id = me and x.kind = 'live' and x.status = 'planned' and x.starts_at > now() - interval '1 hour';
    if n >= 5 then
      return jsonb_build_object('ok', false, 'reason', 'full');
    end if;
  end if;
  cd := jsonb_build_object(
    'host', (select jsonb_build_object('id', x.id, 'name', left(x.name, 80), 'username', x.username, 'avatar', left(x.avatar, 600), 'verified', x.verified) from public.profiles x where x.id = me),
    'group', case when p_kind = 'room' then (select jsonb_build_object('id', g.id, 'name', left(g.name, 80), 'avatar', left(g.avatar, 600)) from public.groups g where g.id = p_group) end);
  if length(cd::text) > 2000 then
    cd := null;
  end if;
  insert into public.live_plans (host_id, kind, group_id, title, cover, starts_at, card)
    values (me, p_kind, case when p_kind = 'room' then p_group end, t, cv, p_starts_at, cd)
    returning * into p;
  return jsonb_build_object('ok', true, 'plan', public.zchat_plan_row(p));
end $$;

create or replace function public.zchat_plan_edit(p_plan uuid, p_title text, p_starts_at timestamptz, p_cover text default null, p_cover_set boolean default false)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  p public.live_plans;
  t text := left(public.zchat_live_clean(p_title, 80), 80);
  cv text := nullif(btrim(coalesce(p_cover, '')), '');
  moved boolean;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'signin');
  end if;
  select * into p from public.live_plans where id = p_plan for update;
  if not found or p.host_id is distinct from me then
    return jsonb_build_object('ok', false, 'reason', 'host');
  end if;
  if p.status <> 'planned' then
    return jsonb_build_object('ok', false, 'reason', 'state');
  end if;
  if t is null then
    return jsonb_build_object('ok', false, 'reason', 'title');
  end if;
  if p_starts_at is null or p_starts_at > now() + interval '30 days'
     or (p_starts_at <> p.starts_at and p_starts_at < now() + interval '9 minutes') then
    return jsonb_build_object('ok', false, 'reason', 'time');
  end if;
  if coalesce(p_cover_set, false) and not public.zchat_plan_cover_ok(cv, me) then
    return jsonb_build_object('ok', false, 'reason', 'cover');
  end if;
  moved := abs(extract(epoch from (p_starts_at - p.starts_at))) >= 60;
  update public.live_plans set
      title = t,
      starts_at = p_starts_at,
      cover = case when coalesce(p_cover_set, false) then cv else cover end,
      reminded_at = case when moved then null else reminded_at end,
      nudged_at = case when moved then null else nudged_at end,
      pushed_at = case when moved then null else pushed_at end,
      updated_at = now()
    where id = p_plan
    returning * into p;
  return jsonb_build_object('ok', true, 'plan', public.zchat_plan_row(p));
end $$;

create or replace function public.zchat_plan_cancel(p_plan uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  p public.live_plans;
  gname text;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'signin');
  end if;
  select * into p from public.live_plans where id = p_plan for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  if not (p.host_id = me or (p.kind = 'room' and public.zchat_room_rank(p.group_id, me) >= 2)) then
    return jsonb_build_object('ok', false, 'reason', 'host');
  end if;
  if p.status <> 'planned' then
    return jsonb_build_object('ok', true, 'plan', public.zchat_plan_row(p));
  end if;
  update public.live_plans set status = 'cancelled', updated_at = now() where id = p_plan returning * into p;
  if p.group_id is not null then
    select g.name into gname from public.groups g where g.id = p.group_id;
  end if;
  perform public.zchat_notify(r.user_id, p.host_id, 'plan_off', null, p.title, jsonb_build_object('plan', p.id, 'kind', p.kind, 'group', p.group_id, 'gname', gname))
    from public.live_plan_reminders r where r.plan_id = p.id;
  return jsonb_build_object('ok', true, 'plan', public.zchat_plan_row(p));
end $$;

create or replace function public.zchat_plan_remind(p_plan uuid, p_on boolean)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  p public.live_plans;
  n integer;
  hit integer := 0;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'signin');
  end if;
  select * into p from public.live_plans where id = p_plan for update;
  if not found or not public.zchat_plan_visible(p.kind, p.host_id, p.group_id) then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  if p.host_id = me then
    return jsonb_build_object('ok', false, 'reason', 'host');
  end if;
  if coalesce(p_on, false) then
    if p.status <> 'planned' then
      return jsonb_build_object('ok', false, 'reason', 'state', 'status', p.status);
    end if;
    select count(*) into n from public.live_plan_reminders r where r.user_id = me and r.created_at > now() - interval '1 minute';
    if n >= 20 then
      return jsonb_build_object('ok', false, 'reason', 'slow');
    end if;
    insert into public.live_plan_reminders (plan_id, user_id) values (p_plan, me) on conflict do nothing;
    get diagnostics hit = row_count;
    if hit > 0 then
      update public.live_plans set reminders = reminders + 1 where id = p_plan returning * into p;
    end if;
  else
    delete from public.live_plan_reminders where plan_id = p_plan and user_id = me;
    get diagnostics hit = row_count;
    if hit > 0 then
      update public.live_plans set reminders = greatest(reminders - 1, 0) where id = p_plan returning * into p;
    end if;
  end if;
  return jsonb_build_object('ok', true, 'on', coalesce(p_on, false), 'reminders', p.reminders);
end $$;

create or replace function public.zchat_plan_list(p_host uuid default null, p_group uuid default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    return '[]'::jsonb;
  end if;
  if p_host is not null then
    if not public.zchat_live_visible(p_host) then
      return '[]'::jsonb;
    end if;
    return coalesce((
      select jsonb_agg(public.zchat_plan_row(p) order by p.starts_at)
      from public.live_plans p
      where p.id in (
        select x.id from public.live_plans x
        where x.host_id = p_host and x.kind = 'live' and x.status = 'planned' and x.starts_at > now() - interval '1 hour'
        order by x.starts_at limit 10
      )
    ), '[]'::jsonb);
  end if;
  if p_group is not null then
    if public.zchat_room_rank(p_group, me) < 0 then
      return '[]'::jsonb;
    end if;
    return coalesce((
      select jsonb_agg(public.zchat_plan_row(p) order by p.starts_at)
      from public.live_plans p
      where p.id in (
        select x.id from public.live_plans x
        where x.group_id = p_group and x.status = 'planned' and x.starts_at > now() - interval '1 hour'
        order by x.starts_at limit 10
      )
    ), '[]'::jsonb);
  end if;
  return coalesce((
    select jsonb_agg(public.zchat_plan_row(p) order by p.starts_at)
    from public.live_plans p
    where p.id in (
      select x.id from public.live_plans x
      where x.status = 'planned' and x.starts_at > now() - interval '1 hour' and x.starts_at < now() + interval '31 days'
        and (
          x.host_id = me
          or (x.kind = 'live'
              and (exists (select 1 from public.follows f where f.follower_id = me and f.following_id = x.host_id and f.status = 'accepted')
                   or exists (select 1 from public.live_plan_reminders r where r.plan_id = x.id and r.user_id = me))
              and public.zchat_live_visible(x.host_id))
          or (x.kind = 'room' and exists (select 1 from public.group_members gm where gm.group_id = x.group_id and gm.user_id = me))
        )
      order by x.starts_at
      limit 30
    )
  ), '[]'::jsonb);
end $$;

create or replace function public.zchat_plan_get(p_plan uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  p public.live_plans;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'signin');
  end if;
  select * into p from public.live_plans where id = p_plan;
  if not found or not public.zchat_plan_visible(p.kind, p.host_id, p.group_id) then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  return jsonb_build_object('ok', true, 'plan', public.zchat_plan_row(p));
end $$;

create or replace function public.zchat_plan_room_open(p_plan uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  p public.live_plans;
  ids uuid[];
  gname text;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'signin');
  end if;
  select * into p from public.live_plans where id = p_plan for update;
  if not found or p.kind <> 'room' then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  if p.host_id is distinct from me then
    return jsonb_build_object('ok', false, 'reason', 'host');
  end if;
  if public.zchat_room_rank(p.group_id, me) < 0 then
    return jsonb_build_object('ok', false, 'reason', 'member');
  end if;
  if exists (select 1 from public.voice_rooms r where r.group_id = p.group_id and not r.enabled) then
    return jsonb_build_object('ok', false, 'reason', 'off');
  end if;
  if p.status = 'started' then
    return jsonb_build_object('ok', true, 'plan', public.zchat_plan_row(p), 'push', '[]'::jsonb);
  end if;
  if p.status <> 'planned' then
    return jsonb_build_object('ok', false, 'reason', 'state');
  end if;
  update public.live_plans set status = 'started', started_at = now(), updated_at = now() where id = p_plan returning * into p;
  select g.name into gname from public.groups g where g.id = p.group_id;
  select array_agg(x.user_id) into ids from (
    select r.user_id from public.live_plan_reminders r where r.plan_id = p.id order by r.created_at limit 2000
  ) x;
  if ids is not null then
    perform public.zchat_notify(u, me, 'plan_live', null, p.title, jsonb_build_object('plan', p.id, 'kind', 'room', 'group', p.group_id, 'gname', gname)) from unnest(ids) as u;
  end if;
  return jsonb_build_object('ok', true, 'plan', public.zchat_plan_row(p), 'push', coalesce(to_jsonb(ids[1:200]), '[]'::jsonb));
end $$;

create or replace function public.zchat_plan_push(p_plan uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  p public.live_plans;
  ids uuid[];
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'signin');
  end if;
  select * into p from public.live_plans where id = p_plan for update;
  if not found or p.host_id is distinct from me then
    return jsonb_build_object('ok', false, 'reason', 'host');
  end if;
  if p.status <> 'planned' or p.pushed_at is not null
     or p.starts_at > now() + interval '11 minutes' or p.starts_at < now() - interval '20 minutes' then
    return jsonb_build_object('ok', true, 'push', '[]'::jsonb);
  end if;
  update public.live_plans set pushed_at = now() where id = p_plan;
  select array_agg(x.user_id) into ids from (
    select r.user_id from public.live_plan_reminders r where r.plan_id = p.id order by r.created_at limit 200
  ) x;
  return jsonb_build_object('ok', true, 'push', coalesce(to_jsonb(ids), '[]'::jsonb));
end $$;

create or replace function public.zchat_plan_tick()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  r record;
  n integer := 0;
  gname text;
begin
  for r in
    update public.live_plans lp set reminded_at = now()
    where lp.id in (
      select x.id from public.live_plans x
      where x.status = 'planned' and x.reminded_at is null
        and x.starts_at <= now() + interval '10 minutes' and x.starts_at > now() - interval '20 minutes'
      order by x.starts_at
      limit 200
      for update skip locked
    )
    returning lp.*
  loop
    begin
      gname := null;
      if r.group_id is not null then
        select g.name into gname from public.groups g where g.id = r.group_id;
      end if;
      perform public.zchat_notify(m.user_id, r.host_id, 'plan_soon', null, r.title, jsonb_build_object('plan', r.id, 'kind', r.kind, 'group', r.group_id, 'gname', gname, 'at', r.starts_at))
        from public.live_plan_reminders m where m.plan_id = r.id;
      n := n + 1;
    exception when others then
      raise notice 'zchat plan reminder skipped: %', sqlerrm;
    end;
  end loop;
  for r in
    update public.live_plans lp set nudged_at = now()
    where lp.id in (
      select x.id from public.live_plans x
      where x.status = 'planned' and x.nudged_at is null
        and x.starts_at <= now() and x.starts_at > now() - interval '30 minutes'
      order by x.starts_at
      limit 200
      for update skip locked
    )
    returning lp.*
  loop
    begin
      gname := null;
      if r.group_id is not null then
        select g.name into gname from public.groups g where g.id = r.group_id;
      end if;
      perform public.zchat_notify(r.host_id, null, 'plan_start', null, r.title, jsonb_build_object('plan', r.id, 'kind', r.kind, 'group', r.group_id, 'gname', gname, 'at', r.starts_at));
      n := n + 1;
    exception when others then
      raise notice 'zchat plan nudge skipped: %', sqlerrm;
    end;
  end loop;
  update public.live_plans set status = 'missed', updated_at = now()
    where status = 'planned' and starts_at < now() - interval '2 hours';
  return n;
end $$;

