do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'live_plans') then
    execute 'alter publication supabase_realtime add table public.live_plans';
  end if;
end $$;

do $$
begin
  if exists (select 1 from pg_namespace where nspname = 'cron')
     and exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'cron' and p.proname = 'schedule') then
    perform cron.schedule('zchat-live-plans', '* * * * *', 'select public.zchat_plan_tick()');
  end if;
end $$;

select public.zchat_apply_session_gate();
commit;

begin;
drop function if exists public.zchat_live_start(text);

create or replace function public.zchat_live_start(p_title text, p_plan uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  t text := left(public.zchat_live_clean(p_title, 80), 80);
  pr record;
  recent integer;
  today integer;
  s public.live_sessions;
  ids uuid[];
  sent integer := 0;
  pl public.live_plans;
  asked uuid[];
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  select p.name, p.is_deleted, p.banned, p.is_bot into pr from public.profiles p where p.id = me;
  if not found or coalesce(pr.is_deleted, false) or coalesce(pr.banned, false) or coalesce(pr.is_bot, false) then
    return jsonb_build_object('ok', false, 'reason', 'Your account cannot go live right now.');
  end if;
  if exists (select 1 from public.user_restrictions r where r.user_id = me and r.kind = 'post' and not r.lifted and r.until > now()) then
    return jsonb_build_object('ok', false, 'reason', 'Going live is paused on your account for now.');
  end if;
  if p_plan is not null then
    select * into pl from public.live_plans x
      where x.id = p_plan and x.host_id = me and x.kind = 'live' and x.status = 'planned'
      for update;
    if found and t is null then
      t := pl.title;
    end if;
  end if;
  if t is null then
    t := left(coalesce(nullif(split_part(btrim(coalesce(pr.name, '')), ' ', 1), ''), 'My') || ' live', 80);
  end if;
  select count(*) filter (where l.started_at > now() - interval '1 minute'), count(*)
    into recent, today
    from public.live_sessions l where l.host_id = me and l.started_at > now() - interval '1 day';
  if recent >= 1 then
    return jsonb_build_object('ok', false, 'reason', 'Give it a minute before you go live again.');
  end if;
  if today >= 12 then
    return jsonb_build_object('ok', false, 'reason', 'You went live a lot today. Try again tomorrow.');
  end if;
  update public.live_sessions set status = 'ended', ended_at = now() where host_id = me and status = 'live';
  insert into public.live_sessions (host_id, title) values (me, t) returning * into s;
  if pl.id is not null then
    update public.live_plans set status = 'started', started_at = now(), live_id = s.id, updated_at = now() where id = pl.id;
    select array_agg(y.user_id) into asked from (
      select r.user_id
      from public.live_plan_reminders r
      join public.profiles p on p.id = r.user_id
      where r.plan_id = pl.id and r.user_id <> me
        and not coalesce(p.is_deleted, false) and not coalesce(p.banned, false) and not coalesce(p.is_bot, false)
        and not public.zchat_blocked_pair(me, r.user_id)
      order by r.created_at
      limit 2000
    ) y;
  end if;
  select array_agg(x.uid) into ids from (
    select f.follower_id as uid
    from public.follows f
    join public.profiles p on p.id = f.follower_id
    where f.following_id = me and f.status = 'accepted' and f.follower_id <> me
      and not coalesce(p.is_deleted, false) and not coalesce(p.banned, false) and not coalesce(p.is_bot, false)
      and not public.zchat_blocked_pair(me, f.follower_id)
      and not exists (
        select 1 from public.notifications n
        where n.user_id = f.follower_id and n.actor_id = me and n.kind = 'live' and n.created_at > now() - interval '30 minutes'
      )
    limit 2000
  ) x;
  if asked is not null then
    ids := asked || coalesce((select array_agg(u) from unnest(ids) as u where not (u = any (asked))), '{}'::uuid[]);
  end if;
  if ids is not null and coalesce(array_length(ids, 1), 0) > 0 then
    perform public.zchat_notify(u, me, 'live', null, left('is live: ' || t, 140), jsonb_build_object('live', s.id)) from unnest(ids) as u;
    sent := coalesce(array_length(ids, 1), 0);
    update public.live_sessions set notified = sent where id = s.id returning * into s;
  end if;
  return jsonb_build_object('ok', true, 'live', public.zchat_live_row(s), 'push', coalesce(to_jsonb(ids[1:200]), '[]'::jsonb), 'plan', pl.id);
end $$;
revoke all on function public.zchat_live_start(text, uuid) from public, anon;
grant execute on function public.zchat_live_start(text, uuid) to authenticated;

create or replace function public.zchat_live_moderate(p_live uuid, p_action text, p_user uuid default null, p_value text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  s public.live_sessions;
  c record;
begin
  select * into s from public.live_sessions where id = p_live for update;
  if not found or s.host_id is distinct from me then
    return jsonb_build_object('ok', false, 'reason', 'host');
  end if;
  if s.status <> 'live' then
    return jsonb_build_object('ok', false, 'reason', 'ended');
  end if;
  if p_action in ('mute', 'unmute', 'remove', 'speaker_add', 'speaker_remove', 'mod_add', 'mod_remove') and (p_user is null or p_user = me) then
    return jsonb_build_object('ok', false, 'reason', 'user');
  end if;
  if p_action = 'comments' then
    update public.live_sessions set comments_on = (p_value = 'on') where id = p_live returning * into s;
  elsif p_action = 'questions' then
    update public.live_sessions set qa_on = (p_value = 'on') where id = p_live returning * into s;
  elsif p_action = 'pin' then
    select lc.id, lc.body, lc.user_id, p.name into c
      from public.live_comments lc left join public.profiles p on p.id = lc.user_id
      where lc.id::text = p_value and lc.live_id = p_live and not lc.hidden;
    if not found then
      return jsonb_build_object('ok', false, 'reason', 'comment');
    end if;
    update public.live_sessions set pinned = jsonb_build_object('id', c.id, 'body', c.body, 'user_id', c.user_id, 'name', c.name)
      where id = p_live returning * into s;
  elsif p_action = 'unpin' then
    update public.live_sessions set pinned = null where id = p_live returning * into s;
  elsif p_action = 'mute' then
    insert into public.live_bans (live_id, user_id, kind) values (p_live, p_user, 'mute')
      on conflict (live_id, user_id) do nothing;
  elsif p_action = 'unmute' then
    delete from public.live_bans where live_id = p_live and user_id = p_user and kind = 'mute';
  elsif p_action = 'remove' then
    insert into public.live_bans (live_id, user_id, kind) values (p_live, p_user, 'remove')
      on conflict (live_id, user_id) do update set kind = 'remove', created_at = now();
    update public.live_comments set hidden = true where live_id = p_live and user_id = p_user and not hidden;
    update public.live_questions set status = 'removed', body = case when shown_at is null then body else '' end where live_id = p_live and user_id = p_user and status in ('waiting', 'showing');
    update public.live_sessions set speakers = array_remove(speakers, p_user),
      mods = array_remove(mods, p_user),
      pinned = case when pinned ->> 'user_id' = p_user::text then null else pinned end
      where id = p_live returning * into s;
  elsif p_action = 'speaker_add' then
    if exists (select 1 from public.live_bans x where x.live_id = p_live and x.user_id = p_user and x.kind = 'remove') then
      return jsonb_build_object('ok', false, 'reason', 'removed');
    end if;
    if not (p_user = any (s.speakers)) then
      if coalesce(array_length(s.speakers, 1), 0) >= 3 then
        return jsonb_build_object('ok', false, 'reason', 'full');
      end if;
      update public.live_sessions set speakers = array_append(speakers, p_user) where id = p_live returning * into s;
    end if;
  elsif p_action = 'speaker_remove' then
    update public.live_sessions set speakers = array_remove(speakers, p_user) where id = p_live returning * into s;
  elsif p_action = 'mod_add' then
    if exists (select 1 from public.live_bans x where x.live_id = p_live and x.user_id = p_user and x.kind = 'remove') then
      return jsonb_build_object('ok', false, 'reason', 'removed');
    end if;
    if not exists (select 1 from public.profiles p where p.id = p_user and not coalesce(p.is_deleted, false) and not coalesce(p.banned, false) and not coalesce(p.is_bot, false)) then
      return jsonb_build_object('ok', false, 'reason', 'user');
    end if;
    if public.zchat_blocked_pair(me, p_user) then
      return jsonb_build_object('ok', false, 'reason', 'user');
    end if;
    if not (p_user = any (s.mods)) then
      if coalesce(array_length(s.mods, 1), 0) >= 5 then
        return jsonb_build_object('ok', false, 'reason', 'mods_full');
      end if;
      update public.live_sessions set mods = array_append(mods, p_user) where id = p_live returning * into s;
    end if;
  elsif p_action = 'mod_remove' then
    update public.live_sessions set mods = array_remove(mods, p_user) where id = p_live returning * into s;
  else
    return jsonb_build_object('ok', false, 'reason', 'action');
  end if;
  return jsonb_build_object('ok', true, 'live', to_jsonb(s));
end $$;
revoke all on function public.zchat_live_moderate(uuid, text, uuid, text) from public, anon;
grant execute on function public.zchat_live_moderate(uuid, text, uuid, text) to authenticated;

create or replace function public.zchat_live_get(p_live uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  s public.live_sessions;
  ban text;
  pl public.live_polls;
  vote smallint;
begin
  if me is null or p_live is null then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  select * into s from public.live_sessions where id = p_live;
  if not found or not public.zchat_live_visible(s.host_id) then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  if s.status = 'live' and s.beat_at < now() - interval '3 minutes' then
    update public.live_sessions set status = 'ended', ended_at = s.beat_at where id = s.id and status = 'live';
    select * into s from public.live_sessions where id = p_live;
  end if;
  select b.kind into ban from public.live_bans b where b.live_id = p_live and b.user_id = me;
  select * into pl from public.live_polls x
    where x.live_id = p_live and (x.status = 'open' or x.ended_at > now() - interval '12 seconds')
    order by x.created_at desc
    limit 1;
  if pl.id is not null then
    select v.choice into vote from public.live_poll_votes v where v.poll_id = pl.id and v.user_id = me;
  end if;
  return jsonb_build_object('ok', true, 'live', public.zchat_live_row(s), 'ban', ban,
    'pinned', s.pinned,
    'comments', coalesce((
      select jsonb_agg(x order by x.created_at) from (
        select c.id, c.user_id, c.body, c.client_id, c.created_at,
          (select jsonb_build_object('name', p.name, 'username', p.username, 'avatar', p.avatar, 'verified', p.verified) from public.profiles p where p.id = c.user_id) as who
        from public.live_comments c
        where c.live_id = p_live and not c.hidden and (c.user_id = me or not public.zchat_blocked_pair(me, c.user_id))
        order by c.created_at desc limit 40
      ) x
    ), '[]'::jsonb),
    'poll', case when pl.id is null then null else to_jsonb(pl) || jsonb_build_object('mine', vote) end,
    'goal', (select to_jsonb(g) from public.live_goals g where g.live_id = p_live and g.status <> 'ended' order by g.created_at desc limit 1),
    'questions', case when s.status = 'live' then public.zchat_live_questions(p_live) else '[]'::jsonb end,
    'supporters', case when s.status = 'ended' and (s.show_supporters or s.host_id = me) then public.zchat_live_top(p_live, me) else null end);
end $$;
revoke all on function public.zchat_live_get(uuid) from public, anon;
grant execute on function public.zchat_live_get(uuid) to authenticated;
commit;

begin;
create table if not exists public.zchat_cl_plans (
  message_id bigint primary key references public.messages(id) on delete cascade,
  sender_id uuid not null references public.profiles(id) on delete cascade,
  receiver_id uuid references public.profiles(id) on delete cascade,
  group_id uuid references public.groups(id) on delete cascade,
  starts_at timestamptz not null,
  title text,
  kind text not null default 'voice',
  cancelled_at timestamptz,
  reminded_at timestamptz,
  created_at timestamptz not null default now(),
  constraint zchat_cl_plans_target check ((receiver_id is null) <> (group_id is null)),
  constraint zchat_cl_plans_kind check (kind in ('voice', 'video')),
  constraint zchat_cl_plans_title check (title is null or char_length(title) <= 80)
);
create index if not exists zchat_cl_plans_due on public.zchat_cl_plans (starts_at) where reminded_at is null and cancelled_at is null;
create index if not exists zchat_cl_plans_sender on public.zchat_cl_plans (sender_id, created_at desc);
create index if not exists zchat_cl_plans_group on public.zchat_cl_plans (group_id, starts_at) where group_id is not null;

create table if not exists public.zchat_cl_plan_rsvps (
  message_id bigint not null references public.zchat_cl_plans(message_id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  going boolean not null default true,
  updated_at timestamptz not null default now(),
  primary key (message_id, user_id)
);

alter table public.zchat_cl_plans enable row level security;
alter table public.zchat_cl_plan_rsvps enable row level security;
alter table public.zchat_cl_plans replica identity full;
alter table public.zchat_cl_plan_rsvps replica identity full;
revoke all on public.zchat_cl_plans from anon;
revoke all on public.zchat_cl_plan_rsvps from anon;
revoke insert, update, delete, truncate on public.zchat_cl_plans from authenticated;
revoke insert, update, delete, truncate on public.zchat_cl_plan_rsvps from authenticated;
grant select on public.zchat_cl_plans to authenticated;
grant select on public.zchat_cl_plan_rsvps to authenticated;

create or replace function public.zchat_cl_plan_member(p_message bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select auth.uid() is not null and exists (
    select 1 from public.zchat_cl_plans p
    where p.message_id = p_message
      and ((p.group_id is null and auth.uid() in (p.sender_id, p.receiver_id))
        or (p.group_id is not null and public.zchat_group_visible(p.group_id)))
  )
$$;
revoke all on function public.zchat_cl_plan_member(bigint) from public, anon;
grant execute on function public.zchat_cl_plan_member(bigint) to authenticated;

drop policy if exists "zchat cl plans read" on public.zchat_cl_plans;
create policy "zchat cl plans read" on public.zchat_cl_plans for select to authenticated
  using ((group_id is null and auth.uid() in (sender_id, receiver_id)) or (group_id is not null and public.zchat_group_visible(group_id)));
drop policy if exists "zchat cl rsvps read" on public.zchat_cl_plan_rsvps;
create policy "zchat cl rsvps read" on public.zchat_cl_plan_rsvps for select to authenticated
  using (public.zchat_cl_plan_member(message_id));

create or replace function public.zchat_cl_plan_card_guard()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if tg_op = 'INSERT' then
    if left(coalesce(new.content, ''), 6) = 'zcall:' and coalesce(current_setting('zchat.callplan_ok', true), '') <> '1' then
      raise exception 'Planned calls are made by ZChat' using errcode = '42501';
    end if;
  elsif new.content is distinct from old.content then
    if (left(coalesce(old.content, ''), 6) = 'zcall:' and new.content is not null) or left(coalesce(new.content, ''), 6) = 'zcall:' then
      raise exception 'A planned call cannot be changed' using errcode = '42501';
    end if;
  end if;
  return new;
end $$;
drop trigger if exists zchat_cl_plan_card_guard on public.messages;
create trigger zchat_cl_plan_card_guard before insert or update of content on public.messages
  for each row execute function public.zchat_cl_plan_card_guard();

create or replace function public.zchat_cl_plan_attach(p_message bigint, p_at timestamptz, p_title text, p_kind text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  m public.messages%rowtype;
begin
  if me is null or coalesce(current_setting('zchat.callplan_attach', true), '') <> p_message::text then
    raise exception 'Planned calls are made by ZChat' using errcode = '42501';
  end if;
  perform set_config('zchat.callplan_attach', '', true);
  select * into m from public.messages where id = p_message;
  if not found or m.sender_id is distinct from me or left(coalesce(m.content, ''), 6) <> 'zcall:' then
    raise exception 'Planned calls are made by ZChat' using errcode = '42501';
  end if;
  insert into public.zchat_cl_plans (message_id, sender_id, receiver_id, group_id, starts_at, title, kind)
  values (m.id, me, m.receiver_id, m.group_id, p_at, p_title, p_kind);
  insert into public.zchat_cl_plan_rsvps (message_id, user_id, going) values (m.id, me, true)
  on conflict (message_id, user_id) do nothing;
end $$;
revoke all on function public.zchat_cl_plan_attach(bigint, timestamptz, text, text) from public, anon;
grant execute on function public.zchat_cl_plan_attach(bigint, timestamptz, text, text) to authenticated;

create or replace function public.zchat_cl_plan_send(p_to uuid, p_group uuid, p_at timestamptz, p_title text default null, p_kind text default 'voice', p_client_id text default null, p_topic text default null)
returns public.messages
language plpgsql
set search_path = public
as $$
declare
  me uuid := auth.uid();
  v_at timestamptz := date_trunc('minute', p_at);
  v_title text := nullif(btrim(regexp_replace(coalesce(p_title, ''), '\s+', ' ', 'g')), '');
  v_kind text := case when p_kind = 'video' then 'video' else 'voice' end;
  r public.messages%rowtype;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  if (p_to is null) = (p_group is null) then
    raise exception 'Pick one chat for the call' using errcode = '22023';
  end if;
  if p_to = me then
    raise exception 'Pick someone to call' using errcode = '22023';
  end if;
  if v_at is null or v_at < now() + interval '1 minute' then
    raise exception 'Pick a time later than now' using errcode = '22023';
  end if;
  if v_at > now() + interval '60 days' then
    raise exception 'You can plan a call up to two months ahead' using errcode = '22023';
  end if;
  if v_title is not null and char_length(v_title) > 80 then
    raise exception 'That title is too long' using errcode = '22023';
  end if;
  if p_to is not null and not public.zchat_can_interact('call', me, p_to) then
    raise exception 'They are not taking calls from you right now' using errcode = '42501';
  end if;
  if p_group is not null and not exists (select 1 from public.group_members gm where gm.group_id = p_group and gm.user_id = me) then
    raise exception 'Join the group first' using errcode = '42501';
  end if;
  if (select count(*) from public.zchat_cl_plans p where p.sender_id = me and p.created_at > now() - interval '1 hour') >= 20 then
    raise exception 'You planned a lot of calls this hour. Try again a little later.' using errcode = '54000';
  end if;
  perform set_config('zchat.callplan_ok', '1', true);
  insert into public.messages (sender_id, receiver_id, group_id, type, content, client_id, topic)
  values (me, p_to, p_group, 'text',
    'zcall:' || jsonb_build_object(
      'at', to_char(v_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      't', v_title,
      'k', v_kind,
      'x', case when v_kind = 'video' then 'Planned video call' else 'Planned voice call' end || coalesce(': ' || v_title, '')
    )::text,
    nullif(left(coalesce(p_client_id, ''), 80), ''),
    case when p_group is not null then nullif(left(btrim(coalesce(p_topic, '')), 40), '') end)
  returning * into r;
  perform set_config('zchat.callplan_ok', '', true);
  perform set_config('zchat.callplan_attach', r.id::text, true);
  perform public.zchat_cl_plan_attach(r.id, v_at, v_title, v_kind);
  return r;
exception when others then
  perform set_config('zchat.callplan_ok', '', true);
  perform set_config('zchat.callplan_attach', '', true);
  raise;
end $$;
revoke all on function public.zchat_cl_plan_send(uuid, uuid, timestamptz, text, text, text, text) from public, anon;
grant execute on function public.zchat_cl_plan_send(uuid, uuid, timestamptz, text, text, text, text) to authenticated;

create or replace function public.zchat_cl_plan_rsvp(p_message bigint, p_going boolean)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  p public.zchat_cl_plans%rowtype;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'auth');
  end if;
  select * into p from public.zchat_cl_plans where message_id = p_message;
  if not found or not public.zchat_cl_plan_member(p_message) then
    return jsonb_build_object('ok', false, 'reason', 'missing');
  end if;
  if p.group_id is not null and not exists (select 1 from public.group_members gm where gm.group_id = p.group_id and gm.user_id = me) then
    return jsonb_build_object('ok', false, 'reason', 'missing');
  end if;
  if p.cancelled_at is not null then
    return jsonb_build_object('ok', false, 'reason', 'cancelled');
  end if;
  if p.starts_at < now() - interval '2 hours' then
    return jsonb_build_object('ok', false, 'reason', 'past');
  end if;
  if not exists (select 1 from public.messages m where m.id = p_message and not coalesce(m.deleted, false)) then
    return jsonb_build_object('ok', false, 'reason', 'missing');
  end if;
  insert into public.zchat_cl_plan_rsvps (message_id, user_id, going, updated_at)
  values (p_message, me, coalesce(p_going, true), now())
  on conflict (message_id, user_id) do update set going = excluded.going, updated_at = now()
  where public.zchat_cl_plan_rsvps.going is distinct from excluded.going;
  return jsonb_build_object('ok', true, 'going', coalesce(p_going, true));
end $$;
revoke all on function public.zchat_cl_plan_rsvp(bigint, boolean) from public, anon;
grant execute on function public.zchat_cl_plan_rsvp(bigint, boolean) to authenticated;

create or replace function public.zchat_cl_plan_cancel(p_message bigint)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  p public.zchat_cl_plans%rowtype;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'auth');
  end if;
  select * into p from public.zchat_cl_plans where message_id = p_message;
  if not found or p.sender_id is distinct from me then
    return jsonb_build_object('ok', false, 'reason', 'owner');
  end if;
  if p.cancelled_at is null then
    update public.zchat_cl_plans set cancelled_at = now() where message_id = p_message;
  end if;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.zchat_cl_plan_cancel(bigint) from public, anon;
grant execute on function public.zchat_cl_plan_cancel(bigint) to authenticated;

create or replace function public.zchat_cl_plans_get(p_ids bigint[])
returns jsonb
language sql
stable
set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'message_id', p.message_id,
    'sender_id', p.sender_id,
    'starts_at', p.starts_at,
    'kind', p.kind,
    'title', p.title,
    'cancelled_at', p.cancelled_at,
    'going', coalesce((select jsonb_agg(r.user_id order by r.updated_at) from public.zchat_cl_plan_rsvps r where r.message_id = p.message_id and r.going), '[]'::jsonb)
  )), '[]'::jsonb)
  from public.zchat_cl_plans p
  where p.message_id = any ((coalesce(p_ids, '{}'::bigint[]))[1:60])
$$;
revoke all on function public.zchat_cl_plans_get(bigint[]) from public, anon;
grant execute on function public.zchat_cl_plans_get(bigint[]) to authenticated;

create or replace function public.zchat_cl_plan_tick()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  r record;
  mem record;
  n integer := 0;
  v_g text;
  v_meta jsonb;
begin
  for r in
    update public.zchat_cl_plans p set reminded_at = now()
    where p.message_id in (
      select p2.message_id from public.zchat_cl_plans p2
      where p2.reminded_at is null and p2.cancelled_at is null
        and p2.starts_at <= now() + interval '10 minutes'
      order by p2.starts_at
      limit 200
      for update skip locked
    )
    returning p.*
  loop
    begin
      if r.starts_at < now() - interval '5 minutes' or r.created_at > r.starts_at - interval '11 minutes' then
        continue;
      end if;
      if not exists (select 1 from public.messages m where m.id = r.message_id and not coalesce(m.deleted, false)) then
        continue;
      end if;
      v_meta := jsonb_build_object('message_id', r.message_id, 'at', r.starts_at, 'k', r.kind, 't', r.title);
      if r.group_id is null then
        perform public.zchat_notify(r.receiver_id, r.sender_id, 'callplan', null, r.title, v_meta || jsonb_build_object('peer', r.sender_id));
        perform public.zchat_notify(r.sender_id, r.receiver_id, 'callplan', null, r.title, v_meta || jsonb_build_object('peer', r.receiver_id, 'mine', true));
      else
        select g.name into v_g from public.groups g where g.id = r.group_id;
        v_meta := v_meta || jsonb_build_object('group_id', r.group_id, 'g', left(coalesce(v_g, ''), 80));
        for mem in
          select gm.user_id from public.group_members gm
          join public.profiles pr on pr.id = gm.user_id
          where gm.group_id = r.group_id and gm.user_id <> r.sender_id
            and not coalesce(pr.is_bot, false) and not coalesce(pr.is_deleted, false)
          limit 2000
        loop
          perform public.zchat_notify(mem.user_id, r.sender_id, 'callplan', null, r.title, v_meta);
        end loop;
        perform public.zchat_notify(r.sender_id, null, 'callplan', null, r.title, v_meta || jsonb_build_object('mine', true));
      end if;
      n := n + 1;
    exception when others then
      raise notice 'zchat call plan tick skipped: %', sqlerrm;
    end;
  end loop;
  return n;
end $$;
revoke all on function public.zchat_cl_plan_tick() from public, anon, authenticated;
grant execute on function public.zchat_cl_plan_tick() to service_role;

do $$
begin
  if exists (select 1 from pg_namespace where nspname = 'cron') then
    if not exists (select 1 from cron.job where jobname = 'zchat-call-plans') then
      perform cron.schedule('zchat-call-plans', '* * * * *', 'select public.zchat_cl_plan_tick()');
    end if;
  end if;
exception when others then
  raise notice 'zchat call plans: the minute job was not scheduled: %', sqlerrm;
end $$;

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'zchat_cl_plans') then
      execute 'alter publication supabase_realtime add table public.zchat_cl_plans';
    end if;
    if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'zchat_cl_plan_rsvps') then
      execute 'alter publication supabase_realtime add table public.zchat_cl_plan_rsvps';
    end if;
  end if;
end $$;

select public.zchat_apply_session_gate();

