create or replace function public.zchat_cl_live_guard()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  new.beat_at := now();
  if new.move_to is distinct from (case when tg_op = 'UPDATE' then old.move_to else null end) then
    new.move_at := case when new.move_to is null then null else now() end;
  end if;
  if new.call_id is null then
    new.dev := null;
    new.kind := null;
    new.mode := null;
    new.peer_id := null;
    new.group_id := null;
    new.title := null;
    new.started_at := null;
    new.move_to := null;
    new.move_at := null;
    new.can_move := false;
  elsif tg_op = 'UPDATE' and new.call_id is distinct from old.call_id then
    new.move_to := null;
    new.move_at := null;
  end if;
  return new;
end $$;
drop trigger if exists zchat_cl_live_guard on public.zchat_cl_live;
create trigger zchat_cl_live_guard before insert or update on public.zchat_cl_live
  for each row execute function public.zchat_cl_live_guard();

