     and not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'zchat_cl_live') then
    execute 'alter publication supabase_realtime add table public.zchat_cl_live';
  end if;
end $$;

