create or replace function public.zchat_status_visible(p_owner uuid, p_viewer uuid, p_audience text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select case
    when p_owner is null then false
    when p_viewer is not null and p_viewer = p_owner then true
    when exists (select 1 from public.profiles p where p.id = p_owner and (coalesce(p.is_deleted, false) or coalesce(p.banned, false))) then false
    when p_viewer is not null and public.zchat_blocked_pair(p_owner, p_viewer) then false
    when coalesce(p_audience, 'everyone') = 'everyone' then true
    when p_viewer is null then false
    when p_audience = 'followers' then public.zchat_follows(p_viewer, p_owner)
    when p_audience = 'close' then exists (select 1 from public.close_friends c where c.owner_id = p_owner and c.friend_id = p_viewer)
    else false
  end
$$;
revoke execute on function public.zchat_status_visible(uuid, uuid, text) from public, anon;
grant execute on function public.zchat_status_visible(uuid, uuid, text) to authenticated, service_role;

drop policy if exists zchat_status_read on public.zchat_status;
create policy zchat_status_read on public.zchat_status for select to authenticated
  using (user_id = auth.uid() or ((until is null or until > now()) and public.zchat_status_visible(user_id, auth.uid(), audience)));

create or replace function public.zchat_status_set(p_emoji text, p_text text, p_until timestamptz, p_audience text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  e text := nullif(btrim(coalesce(p_emoji, '')), '');
  t text := nullif(btrim(regexp_replace(coalesce(p_text, ''), '\s+', ' ', 'g')), '');
  u timestamptz := p_until;
  a text;
  n integer;
begin
  if me is null or not public.zchat_session_ok() then
    raise exception 'Log in to set a status' using errcode = '42501';
  end if;
  if t is not null and char_length(t) > 60 then
    raise exception 'Keep your status to 60 characters' using errcode = '22023';
  end if;
  if e is not null and (char_length(e) > 16 or e ~ '[<>]') then
    raise exception 'That emoji cannot be used' using errcode = '22023';
  end if;
  if t is null and e is not null then
    raise exception 'Write a few words for your status' using errcode = '22023';
  end if;
  if t is null then
    u := null;
  elsif u is not null and (u <= now() or u > now() + interval '31 days') then
    raise exception 'Pick an end time in the next month' using errcode = '22023';
  end if;
  select s.audience into a from public.zchat_status s where s.user_id = me;
  a := coalesce(nullif(btrim(coalesce(p_audience, '')), ''), a, 'everyone');
  if a not in ('everyone', 'followers', 'close', 'nobody') then
    raise exception 'Choose who can see your status' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('zchat_status:' || me::text, 0));
  select count(*) into n from public.zchat_status_log l where l.user_id = me and l.at > now() - interval '1 hour';
  if n >= 60 then
    raise exception 'Too many status changes. Try again in a little while' using errcode = '54000';
  end if;
  insert into public.zchat_status_log (user_id) values (me);
  if random() < 0.03 then
    delete from public.zchat_status_log where at < now() - interval '2 hours';
  end if;
  insert into public.zchat_status (user_id, emoji, body, until, audience, updated_at)
    values (me, case when t is null then null else e end, t, u, a, now())
    on conflict (user_id) do update set emoji = excluded.emoji, body = excluded.body, until = excluded.until, audience = excluded.audience, updated_at = excluded.updated_at;
  perform set_config('zchat.status_sync', '1', true);
  update public.profiles
    set status_text = case when a = 'everyone' then t end,
        status_emoji = case when a = 'everyone' and t is not null then e end,
        status_until = case when a = 'everyone' then u end
    where id = me;
  perform set_config('zchat.status_sync', '', true);
  return jsonb_build_object('ok', true, 'e', case when t is null then null else e end, 't', t, 'u', u, 'a', a, 'at', now());
end
$$;

revoke execute on function public.zchat_status_set(text, text, timestamptz, text) from public, anon;
grant execute on function public.zchat_status_set(text, text, timestamptz, text) to authenticated;

create or replace function public.zchat_status_sync()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  a text;
  t text;
begin
  if coalesce(current_setting('zchat.status_sync', true), '') = '1' then
    return new;
  end if;
  if new.status_text is not distinct from old.status_text and new.status_emoji is not distinct from old.status_emoji and new.status_until is not distinct from old.status_until then
    return new;
  end if;
  t := nullif(btrim(coalesce(new.status_text, '')), '');
  if t is not null and char_length(t) > 60 then
    raise exception 'Keep your status to 60 characters' using errcode = '22023';
  end if;
  select s.audience into a from public.zchat_status s where s.user_id = new.id;
  a := coalesce(a, 'everyone');
  insert into public.zchat_status (user_id, emoji, body, until, audience, updated_at)
    values (new.id, case when t is null then null else left(nullif(btrim(coalesce(new.status_emoji, '')), ''), 16) end, t, case when t is null then null else new.status_until end, a, now())
    on conflict (user_id) do update set emoji = excluded.emoji, body = excluded.body, until = excluded.until, updated_at = excluded.updated_at;
  if a <> 'everyone' then
    new.status_text := null;
    new.status_emoji := null;
    new.status_until := null;
  end if;
  return new;
end
$$;
drop trigger if exists zchat_status_sync on public.profiles;
create trigger zchat_status_sync before update of status_text, status_emoji, status_until on public.profiles
  for each row execute function public.zchat_status_sync();

create or replace function public.zchat_status_tick()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  n integer := 0;
  r record;
begin
  perform set_config('zchat.status_sync', '1', true);
  for r in
    update public.zchat_status s set emoji = null, body = null, until = null, updated_at = now()
    where s.user_id in (
      select s2.user_id from public.zchat_status s2
      where s2.until is not null and s2.until <= now() and s2.body is not null
      order by s2.until
      limit 500
      for update skip locked
    )
    returning s.user_id
  loop
    update public.profiles set status_text = null, status_emoji = null, status_until = null
      where id = r.user_id and (status_text is not null or status_emoji is not null or status_until is not null);
    n := n + 1;
  end loop;
  update public.profiles set status_text = null, status_emoji = null, status_until = null
    where status_until is not null and status_until <= now() and (status_text is not null or status_emoji is not null);
  perform set_config('zchat.status_sync', '', true);
  return n;
end
$$;
revoke execute on function public.zchat_status_tick() from public, anon, authenticated;
grant execute on function public.zchat_status_tick() to service_role;

insert into public.zchat_status (user_id, emoji, body, until, audience, updated_at)
  select p.id, left(nullif(btrim(coalesce(p.status_emoji, '')), ''), 16), left(btrim(p.status_text), 60), p.status_until, 'everyone', now()
  from public.profiles p
  where nullif(btrim(coalesce(p.status_text, '')), '') is not null and (p.status_until is null or p.status_until > now())
  on conflict (user_id) do nothing;

