    execute 'alter publication supabase_realtime add table public.zchat_status';
  end if;
end $$;

do $$
begin
  if exists (select 1 from pg_namespace where nspname = 'cron')
     and exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'cron' and p.proname = 'schedule') then
    perform cron.schedule('zchat-status-clear', '* * * * *', 'select public.zchat_status_tick()');
  end if;
end $$;

