create table if not exists public.zchat_breaks (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  started_at timestamptz not null default now(),
  quiet_until timestamptz not null default 'infinity'
);
alter table public.zchat_breaks enable row level security;
drop policy if exists zchat_breaks_own on public.zchat_breaks;
create policy zchat_breaks_own on public.zchat_breaks for select to authenticated using (user_id = auth.uid());

create or replace function public.zchat_on_break(p_user uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select p_user is not null and exists (select 1 from public.zchat_breaks b where b.user_id = p_user)
$$;
revoke execute on function public.zchat_on_break(uuid) from public;
grant execute on function public.zchat_on_break(uuid) to anon, authenticated, service_role;

create or replace function public.zchat_break_start(p_quiet_hours integer default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  q timestamptz;
  t timestamptz := now();
begin
  if me is null or not public.zchat_session_ok() then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  if exists (select 1 from public.profiles p where p.id = me and (coalesce(p.is_deleted, false) or coalesce(p.banned, false) or coalesce(p.is_bot, false))) then
    raise exception 'This account cannot take a break' using errcode = '42501';
  end if;
  q := case when p_quiet_hours is null or p_quiet_hours <= 0 then 'infinity'::timestamptz else t + make_interval(hours => least(p_quiet_hours, 24 * 90)) end;
  insert into public.zchat_breaks (user_id, started_at, quiet_until) values (me, t, q)
    on conflict (user_id) do update set started_at = excluded.started_at, quiet_until = excluded.quiet_until;
  begin
    execute 'delete from auth.sessions where user_id = $1' using me;
  exception when others then
    raise notice 'zchat break: sessions kept: %', sqlerrm;
  end;
  return jsonb_build_object('ok', true, 'started_at', t, 'quiet_until', q);
end
$$;
revoke execute on function public.zchat_break_start(integer) from public, anon;
grant execute on function public.zchat_break_start(integer) to authenticated;

create or replace function public.zchat_break_check()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  b public.zchat_breaks%rowtype;
  sid uuid := public.zchat_session_sid();
  made timestamptz;
  amr_t numeric;
begin
  if me is null then
    return jsonb_build_object('state', 'none');
  end if;
  select * into b from public.zchat_breaks z where z.user_id = me;
  if not found then
    return jsonb_build_object('state', 'none');
  end if;
  if sid is not null then
    begin
      execute 'select created_at from auth.sessions where id = $1 and user_id = $2' into made using sid, me;
    exception when others then
      made := null;
    end;
  end if;
  if made is null then
    begin
      amr_t := nullif(auth.jwt() -> 'amr' -> 0 ->> 'timestamp', '')::numeric;
    exception when others then
      amr_t := null;
    end;
    if amr_t is not null then
      made := to_timestamp(amr_t);
    end if;
  end if;
  if made is not null and made > b.started_at then
    delete from public.zchat_breaks where user_id = me;
    return jsonb_build_object('state', 'ended', 'since', b.started_at);
  end if;
  return jsonb_build_object('state', 'logout', 'since', b.started_at);
end
$$;
revoke execute on function public.zchat_break_check() from public, anon;
grant execute on function public.zchat_break_check() to authenticated;

create or replace function public.zchat_break_dm()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;
  if new.group_id is null and new.receiver_id is not null and new.receiver_id is distinct from new.sender_id and public.zchat_on_break(new.receiver_id) then
    raise exception 'They are taking a break, so new messages are paused' using errcode = '42501';
  end if;
  return new;
end
$$;
drop trigger if exists zchat_break_dm on public.messages;
create trigger zchat_break_dm before insert on public.messages for each row execute function public.zchat_break_dm();

drop policy if exists zchat_break_posts on public.posts;
