create or replace function public.zchat_pf_knows(p_owner uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select auth.uid() is not null and p_owner is not null and (
    exists (select 1 from public.conversations c where (c.user_a = auth.uid() and c.user_b = p_owner) or (c.user_a = p_owner and c.user_b = auth.uid()))
    or exists (select 1 from public.group_members b join public.group_members a on a.group_id = b.group_id and a.user_id = auth.uid() where b.user_id = p_owner)
  )
$$;
revoke execute on function public.zchat_pf_knows(uuid) from public;
grant execute on function public.zchat_pf_knows(uuid) to anon, authenticated, service_role;
drop policy if exists zchat_break_profiles on public.profiles;
