create policy zchat_break_status on public.zchat_status as restrictive for select using (user_id = auth.uid() or not public.zchat_on_break(user_id));

CREATE OR REPLACE FUNCTION public.zchat_owner_visible(p_owner uuid, p_scope text DEFAULT 'posts'::text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  pr jsonb;
  v text;
  fol boolean;
begin
  if p_owner is null then return false; end if;
  if me is not null and (me = p_owner or public.zchat_is_admin_id(me)) then return true; end if;
  if public.zchat_on_break(p_owner) then return false; end if;
  if me is not null and exists (select 1 from public.blocks b where (b.blocker_id = p_owner and b.blocked_id = me) or (b.blocker_id = me and b.blocked_id = p_owner)) then
    return false;
  end if;
  select to_jsonb(p) into pr from public.profiles p where p.id = p_owner;
  if pr is null then return true; end if;
  fol := me is not null and exists (select 1 from public.follows f where f.follower_id = me and f.following_id = p_owner and coalesce(f.status, 'accepted') = 'accepted');
  if coalesce((pr ->> 'is_private')::boolean, false) and not fol then return false; end if;
  if p_scope = 'posts' then
    v := coalesce(pr ->> 'privacy_profile', 'everyone');
    if v = 'followers' and not fol then return false; end if;
    if v = 'chosen' and not (me is not null and exists (select 1 from public.privacy_allow a where a.user_id = p_owner and a.scope = 'privacy_profile' and a.viewer_id = me)) then
      return false;
    end if;
  end if;
  return true;
end $function$;

create or replace function public.zchat_pf_can_see(p_owner uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select case
    when p_owner is null then false
    when auth.uid() is not null and auth.uid() = p_owner then true
    when exists (select 1 from public.profiles p where p.id = p_owner and (coalesce(p.is_deleted, false) or coalesce(p.banned, false))) then false
    when public.zchat_on_break(p_owner) then false
    else public.zchat_owner_visible(p_owner, 'posts')
  end
$$;
revoke execute on function public.zchat_pf_can_see(uuid) from public;
grant execute on function public.zchat_pf_can_see(uuid) to anon, authenticated, service_role;

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'zchat_breaks') then
    execute 'alter publication supabase_realtime add table public.zchat_breaks';
  end if;
end $$;

select public.zchat_apply_session_gate();
commit;

begin;
create or replace function public.zchat_pf_break_shape(p jsonb)
returns jsonb
language sql
immutable
as $$
  select jsonb_build_object(
    'id', p -> 'id', 'name', p -> 'name', 'username', p -> 'username', 'avatar', p -> 'avatar',
    'verified', p -> 'verified', 'custom_badge', p -> 'custom_badge', 'is_bot', coalesce(p -> 'is_bot', 'false'::jsonb),
    'is_deleted', coalesce(p -> 'is_deleted', 'false'::jsonb), 'banned', coalesce(p -> 'banned', 'false'::jsonb),
    'is_private', p -> 'is_private', 'created_at', p -> 'created_at',
    'last_seen', null, 'hide_activity', true, 'avatar_anim', null, 'cover_url', null, 'cover_anim', null,
    'status_text', null, 'status_emoji', null, 'status_until', null, 'bio', null, 'song', null,
    'privacy_messages', 'following', 'on_break', true
  )
$$;

create or replace function public.zchat_pf_dress(p_rows jsonb)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select case when p_rows is null or jsonb_typeof(p_rows) <> 'array' then p_rows else (
    with me as (select auth.uid() as uid, now() as at),
    x as (
      select e.value as j, e.ordinality as n, public.zchat_try_uuid(e.value ->> 'id') as id
      from jsonb_array_elements(p_rows) with ordinality e
    )
    select coalesce(jsonb_agg(
      case
        when x.id is null then x.j
        when b.user_id is not null and x.id is distinct from me.uid then public.zchat_pf_break_shape(x.j) || jsonb_build_object('zstatus', jsonb_build_object('at', me.at))
        else x.j || jsonb_build_object(
          'on_break', b.user_id is not null,
          'zstatus', case
            when s.user_id is not null and s.body is not null and (s.until is null or s.until > me.at) and public.zchat_status_visible(x.id, me.uid, s.audience)
              then jsonb_build_object('e', s.emoji, 't', s.body, 'u', s.until, 'at', me.at) || case when x.id = me.uid then jsonb_build_object('a', s.audience) else '{}'::jsonb end
            when x.id = me.uid then jsonb_build_object('at', me.at, 'a', coalesce(s.audience, 'everyone'))
            else jsonb_build_object('at', me.at)
          end)
      end order by x.n), '[]'::jsonb)
    from x
    cross join me
    left join public.zchat_status s on s.user_id = x.id
    left join public.zchat_breaks b on b.user_id = x.id
  ) end
$$;
revoke execute on function public.zchat_pf_dress(jsonb) from public, anon, authenticated;

do $$
declare
  src text;
begin
  select p.prosrc into src from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'zchat_profile_view' and pg_get_function_identity_arguments(p.oid) = 'p_ids uuid[]';
  if src is not null and src !~ 'zchat_pf_dress' then
    drop function if exists public.zchat_profile_view_core(uuid[]);
    alter function public.zchat_profile_view(uuid[]) rename to zchat_profile_view_core;
  end if;
  select p.prosrc into src from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'zchat_my_profile' and pg_get_function_identity_arguments(p.oid) = '';
  if src is not null and src !~ 'zchat_pf_dress' then
    drop function if exists public.zchat_my_profile_core();
    alter function public.zchat_my_profile() rename to zchat_my_profile_core;
  end if;
  select p.prosrc into src from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'zchat_push_gate' and pg_get_function_identity_arguments(p.oid) = 'p_caller uuid, p_target uuid, p_tag text, p_clear boolean';
  if src is not null and src !~ 'zchat_breaks' then
    drop function if exists public.zchat_push_gate_core(uuid, uuid, text, boolean);
    alter function public.zchat_push_gate(uuid, uuid, text, boolean) rename to zchat_push_gate_core;
  end if;
end $$;

create or replace function public.zchat_profile_view(p_ids uuid[])
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select public.zchat_pf_dress(public.zchat_profile_view_core(p_ids))
$$;

create or replace function public.zchat_my_profile()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select case when z.j is null or jsonb_typeof(z.j) <> 'object' then z.j else public.zchat_pf_dress(jsonb_build_array(z.j)) -> 0 end
  from (select public.zchat_my_profile_core() as j) z
$$;

create or replace function public.zchat_push_gate(p_caller uuid, p_target uuid, p_tag text default null, p_clear boolean default false)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  if not coalesce(p_clear, false) and p_target is not null
     and exists (select 1 from public.zchat_breaks b where b.user_id = p_target and b.quiet_until > now()) then
    return jsonb_build_object('ok', false, 'why', 'quiet');
  end if;
  return public.zchat_push_gate_core(p_caller, p_target, p_tag, p_clear);
end
$$;

revoke execute on function public.zchat_profile_view_core(uuid[]) from public, anon, authenticated;
revoke execute on function public.zchat_my_profile_core() from public, anon, authenticated;
revoke execute on function public.zchat_push_gate_core(uuid, uuid, text, boolean) from public, anon, authenticated;
grant execute on function public.zchat_profile_view_core(uuid[]) to service_role;
grant execute on function public.zchat_my_profile_core() to service_role;
grant execute on function public.zchat_push_gate_core(uuid, uuid, text, boolean) to service_role;
revoke execute on function public.zchat_profile_view(uuid[]) from public, anon;
revoke execute on function public.zchat_my_profile() from public, anon;
revoke execute on function public.zchat_push_gate(uuid, uuid, text, boolean) from public, anon, authenticated;
grant execute on function public.zchat_profile_view(uuid[]) to authenticated, service_role;
grant execute on function public.zchat_my_profile() to authenticated, service_role;
grant execute on function public.zchat_push_gate(uuid, uuid, text, boolean) to service_role;

alter table public.profiles add column if not exists cover_anim text;

create or replace function public.zchat_cover_anim_ok(p_user uuid, p_path text)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  ok boolean := false;
begin
  if p_user is null or p_path is null then
    return false;
  end if;
  if p_path !~ ('^' || p_user::text || '/[A-Za-z0-9_-][A-Za-z0-9._-]{0,139}\.(mp4|webm)$') then
    return false;
  end if;
  if to_regclass('storage.objects') is null then
    return true;
  end if;
  execute $q$
    select exists (
      select 1 from storage.objects o
      where o.bucket_id = 'chat-media' and o.name = $1
        and (case when coalesce(o.metadata ->> 'size', '') ~ '^[0-9]{1,12}$' then (o.metadata ->> 'size')::bigint else 0 end) between 1 and 4194304
        and lower(coalesce(o.metadata ->> 'mimetype', '')) like 'video/%'
    )
  $q$ into ok using p_path;
  return coalesce(ok, false);
end
$$;
revoke execute on function public.zchat_cover_anim_ok(uuid, text) from public, anon, authenticated;
grant execute on function public.zchat_cover_anim_ok(uuid, text) to service_role;

create or replace function public.zchat_cover_anim_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.cover_anim is not null and btrim(new.cover_anim) = '' then
    new.cover_anim := null;
  end if;
  if new.cover_anim is not null and (tg_op = 'INSERT' or new.cover_anim is distinct from old.cover_anim) then
    if not public.zchat_cover_anim_ok(new.id, new.cover_anim) then
      raise exception 'That cover video cannot be used' using errcode = '22023';
    end if;
  end if;
  if tg_op = 'UPDATE' and coalesce(new.is_deleted, false) and not coalesce(old.is_deleted, false) then
    new.cover_anim := null;
  end if;
  return new;
end
$$;
drop trigger if exists zchat_cover_anim_guard on public.profiles;
create trigger zchat_cover_anim_guard before insert or update of cover_anim, is_deleted on public.profiles
  for each row execute function public.zchat_cover_anim_guard();

select public.zchat_profile_grants();

create table if not exists public.zchat_voice_intros (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  path text not null,
  secs numeric(4,1) not null,
  say text,
  peaks jsonb,
  updated_at timestamptz not null default now(),
  constraint zchat_voice_secs_ok check (secs > 0 and secs <= 10.5),
  constraint zchat_voice_say_ok check (say is null or char_length(say) <= 40),
  constraint zchat_voice_peaks_ok check (peaks is null or (jsonb_typeof(peaks) = 'array' and jsonb_array_length(peaks) <= 48))
);
alter table public.zchat_voice_intros enable row level security;
drop policy if exists zchat_voice_own on public.zchat_voice_intros;
create policy zchat_voice_own on public.zchat_voice_intros for select to authenticated using (user_id = auth.uid());

create or replace function public.zchat_voice_intro_ok(p_user uuid, p_path text)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  ok boolean := false;
begin
  if p_user is null or p_path is null then
    return false;
  end if;
  if p_path !~ ('^' || p_user::text || '/[A-Za-z0-9_-][A-Za-z0-9._-]{0,139}\.(webm|ogg|oga|m4a|mp4|mp3|aac|wav)$') then
    return false;
  end if;
  if to_regclass('storage.objects') is null then
    return true;
  end if;
  execute $q$
    select exists (
      select 1 from storage.objects o
      where o.bucket_id = 'chat-media' and o.name = $1
        and (case when coalesce(o.metadata ->> 'size', '') ~ '^[0-9]{1,12}$' then (o.metadata ->> 'size')::bigint else 0 end) between 1 and 614400
        and lower(coalesce(o.metadata ->> 'mimetype', '')) like 'audio/%'
    )
  $q$ into ok using p_path;
  return coalesce(ok, false);
end
$$;
revoke execute on function public.zchat_voice_intro_ok(uuid, text) from public, anon, authenticated;
grant execute on function public.zchat_voice_intro_ok(uuid, text) to service_role;

create or replace function public.zchat_voice_intro_set(p_path text, p_secs numeric, p_say text default null, p_peaks jsonb default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  s text := nullif(btrim(regexp_replace(coalesce(p_say, ''), '\s+', ' ', 'g')), '');
  pk jsonb := null;
  sec numeric := round(coalesce(p_secs, 0)::numeric, 1);
begin
  if me is null or not public.zchat_session_ok() then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  if sec <= 0 or sec > 10.5 then
    raise exception 'Keep your voice intro to 10 seconds' using errcode = '22023';
  end if;
  if s is not null and char_length(s) > 40 then
    raise exception 'Keep how to say your name short' using errcode = '22023';
  end if;
  if p_peaks is not null and jsonb_typeof(p_peaks) = 'array' and jsonb_array_length(p_peaks) between 4 and 48
     and not exists (select 1 from jsonb_array_elements(p_peaks) v where jsonb_typeof(v) <> 'number' or (v #>> '{}')::numeric < 0 or (v #>> '{}')::numeric > 1) then
    pk := p_peaks;
  end if;
  if not public.zchat_voice_intro_ok(me, p_path) then
    raise exception 'That voice intro cannot be used' using errcode = '22023';
  end if;
  insert into public.zchat_voice_intros (user_id, path, secs, say, peaks, updated_at)
    values (me, p_path, sec, s, pk, now())
    on conflict (user_id) do update set path = excluded.path, secs = excluded.secs, say = excluded.say, peaks = excluded.peaks, updated_at = excluded.updated_at;
  return jsonb_build_object('ok', true, 'path', p_path, 'secs', sec, 'say', s, 'peaks', pk, 'at', now());
end
$$;
revoke execute on function public.zchat_voice_intro_set(text, numeric, text, jsonb) from public, anon;
grant execute on function public.zchat_voice_intro_set(text, numeric, text, jsonb) to authenticated;

create or replace function public.zchat_voice_intro_say(p_say text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  s text := nullif(btrim(regexp_replace(coalesce(p_say, ''), '\s+', ' ', 'g')), '');
begin
  if me is null or not public.zchat_session_ok() then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  if s is not null and char_length(s) > 40 then
    raise exception 'Keep how to say your name short' using errcode = '22023';
  end if;
  update public.zchat_voice_intros set say = s, updated_at = now() where user_id = me;
  return jsonb_build_object('ok', found, 'say', s);
end
$$;
revoke execute on function public.zchat_voice_intro_say(text) from public, anon;
grant execute on function public.zchat_voice_intro_say(text) to authenticated;

create or replace function public.zchat_voice_intro_clear()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
begin
  if me is null or not public.zchat_session_ok() then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  delete from public.zchat_voice_intros where user_id = me;
  return jsonb_build_object('ok', true);
end
$$;
revoke execute on function public.zchat_voice_intro_clear() from public, anon;
grant execute on function public.zchat_voice_intro_clear() to authenticated;

select public.zchat_apply_session_gate();

