create or replace function public.zchat_photo_visible(p_owner uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select case
    when p_owner is null then false
    when auth.uid() is not null and auth.uid() = p_owner then true
    when public.zchat_on_break(p_owner) then false
    when auth.uid() is not null and public.zchat_blocked_pair(p_owner, auth.uid()) then false
    else exists (
      select 1 from public.profiles p
      where p.id = p_owner and not coalesce(p.hide_photo, false) and not coalesce(p.is_deleted, false) and not coalesce(p.banned, false)
    )
  end
$$;
revoke execute on function public.zchat_photo_visible(uuid) from public;
