  using (user_id = auth.uid() or public.zchat_photo_visible(user_id));

create or replace function public.zchat_photo_url_ok(p_user uuid, p_url text)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  path text;
  ok boolean := false;
begin
  if p_user is null or p_url is null or char_length(p_url) > 600 or p_url !~* '^https://' or not public.zchat_url_ok(p_url) then
    return false;
  end if;
  path := substring(p_url from ('/chat-media/(' || p_user::text || '/[A-Za-z0-9_-][A-Za-z0-9._-]{0,139}\.(jpe?g|png|webp|gif|heic|avif))(\?|#|$)'));
  if path is null then
    return false;
  end if;
  if to_regclass('storage.objects') is null then
    return true;
  end if;
  execute $q$
    select exists (
      select 1 from storage.objects o
      where o.bucket_id = 'chat-media' and o.name = $1
        and (case when coalesce(o.metadata ->> 'size', '') ~ '^[0-9]{1,12}$' then (o.metadata ->> 'size')::bigint else 0 end) between 1 and 10485760
        and lower(coalesce(o.metadata ->> 'mimetype', '')) like 'image/%'
    )
  $q$ into ok using path;
  return coalesce(ok, false);
end
$$;
revoke execute on function public.zchat_photo_url_ok(uuid, text) from public, anon, authenticated;
grant execute on function public.zchat_photo_url_ok(uuid, text) to service_role;

create or replace function public.zchat_photos_set(p_urls text[])
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  list text[] := coalesce(p_urls, '{}'::text[]);
  i integer;
begin
  if me is null or not public.zchat_session_ok() then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  if cardinality(list) > 4 then
    raise exception 'You can add up to 4 more photos' using errcode = '22023';
  end if;
  for i in 1 .. cardinality(list) loop
    if not public.zchat_photo_url_ok(me, list[i]) then
      raise exception 'One of those photos cannot be used' using errcode = '22023';
    end if;
  end loop;
  perform pg_advisory_xact_lock(hashtextextended('zchat_photos:' || me::text, 0));
  delete from public.zchat_profile_photos where user_id = me;
  for i in 1 .. cardinality(list) loop
    insert into public.zchat_profile_photos (user_id, pos, url) values (me, i, list[i]);
  end loop;
  return jsonb_build_object('ok', true, 'n', cardinality(list));
end
$$;
revoke execute on function public.zchat_photos_set(text[]) from public, anon;
grant execute on function public.zchat_photos_set(text[]) to authenticated;

select public.zchat_apply_session_gate();
commit;

begin;
create table if not exists public.zchat_compliments (
  id uuid primary key default gen_random_uuid(),
  from_id uuid not null references public.profiles(id) on delete cascade,
  to_id uuid not null references public.profiles(id) on delete cascade,
  kind text not null,
  note text,
  shown boolean not null default false,
  seen_at timestamptz,
  created_at timestamptz not null default now(),
  constraint zchat_compliment_kind_ok check (kind in ('laugh', 'kind', 'there', 'music', 'group', 'sunshine', 'advice', 'proud', 'calm', 'legend')),
  constraint zchat_compliment_note_ok check (note is null or char_length(note) <= 120),
  constraint zchat_compliment_self check (from_id <> to_id)
);
create index if not exists zchat_compliments_to_idx on public.zchat_compliments (to_id, created_at desc);
create index if not exists zchat_compliments_from_idx on public.zchat_compliments (from_id, created_at desc);
alter table public.zchat_compliments enable row level security;
drop policy if exists zchat_compliments_read on public.zchat_compliments;
create policy zchat_compliments_read on public.zchat_compliments for select to authenticated
  using (to_id = auth.uid() or from_id = auth.uid());

create or replace function public.zchat_compliment_send(p_to uuid, p_kind text, p_note text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  k text := lower(btrim(coalesce(p_kind, '')));
  nt text := nullif(btrim(regexp_replace(coalesce(p_note, ''), '\s+', ' ', 'g')), '');
  n integer;
  made public.zchat_compliments%rowtype;
begin
  if me is null or not public.zchat_session_ok() then
    return jsonb_build_object('ok', false, 'why', 'login');
  end if;
  if p_to is null or p_to = me then
    return jsonb_build_object('ok', false, 'why', 'self');
  end if;
  if k not in ('laugh', 'kind', 'there', 'music', 'group', 'sunshine', 'advice', 'proud', 'calm', 'legend') then
    return jsonb_build_object('ok', false, 'why', 'kind');
  end if;
  if nt is not null and char_length(nt) > 120 then
    return jsonb_build_object('ok', false, 'why', 'long');
  end if;
  if exists (select 1 from public.profiles p where p.id in (me, p_to) and (coalesce(p.is_deleted, false) or coalesce(p.banned, false) or (p.id = p_to and coalesce(p.is_bot, false))))
     or not exists (select 1 from public.profiles p where p.id = p_to) then
    return jsonb_build_object('ok', false, 'why', 'gone');
  end if;
  if public.zchat_blocked_pair(me, p_to) then
    return jsonb_build_object('ok', false, 'why', 'blocked');
  end if;
  if public.zchat_on_break(p_to) then
    return jsonb_build_object('ok', false, 'why', 'break');
  end if;
  if not public.zchat_follows(me, p_to) and not exists (
    select 1 from public.conversations c where (c.user_a = me and c.user_b = p_to) or (c.user_a = p_to and c.user_b = me)
  ) then
    return jsonb_build_object('ok', false, 'why', 'friends');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('zchat_compliment:' || me::text, 0));
  select count(*) into n from public.zchat_compliments c where c.from_id = me and c.created_at > now() - interval '1 day';
  if n >= 5 then
    return jsonb_build_object('ok', false, 'why', 'limit');
  end if;
  insert into public.zchat_compliments (from_id, to_id, kind, note) values (me, p_to, k, nt) returning * into made;
  perform public.zchat_notify(p_to, me, 'compliment', null, nt, jsonb_build_object('compliment', made.id, 'k', k, 'name', (select left(coalesce(p.name, ''), 60) from public.profiles p where p.id = me)));
  return jsonb_build_object('ok', true, 'id', made.id, 'created_at', made.created_at, 'left', greatest(0, 4 - n));
end
$$;
revoke execute on function public.zchat_compliment_send(uuid, text, text) from public, anon;
grant execute on function public.zchat_compliment_send(uuid, text, text) to authenticated;

create or replace function public.zchat_compliment_set(p_id uuid, p_shown boolean default null, p_seen boolean default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
begin
  if me is null or not public.zchat_session_ok() then
    return jsonb_build_object('ok', false, 'why', 'login');
  end if;
  update public.zchat_compliments c
    set shown = coalesce(p_shown, c.shown),
        seen_at = case when coalesce(p_seen, false) and c.seen_at is null then now() else c.seen_at end
    where c.id = p_id and c.to_id = me;
  if not found then
    return jsonb_build_object('ok', false, 'why', 'gone');
  end if;
  return jsonb_build_object('ok', true);
end
$$;
revoke execute on function public.zchat_compliment_set(uuid, boolean, boolean) from public, anon;
grant execute on function public.zchat_compliment_set(uuid, boolean, boolean) to authenticated;

create or replace function public.zchat_compliments_mine(p_limit integer default 60)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'sent_today', (select count(*) from public.zchat_compliments c where c.from_id = auth.uid() and c.created_at > now() - interval '1 day'),
    'items', coalesce((
      select jsonb_agg(jsonb_build_object('id', x.id, 'from_id', x.from_id, 'kind', x.kind, 'note', x.note, 'shown', x.shown, 'seen', x.seen_at is not null, 'created_at', x.created_at,
        'name', x.name, 'username', x.username, 'avatar', x.avatar, 'verified', x.verified) order by x.created_at desc)
      from (
        select c.*, p.name, p.username, case when coalesce(p.hide_photo, false) then null else p.avatar end as avatar, p.verified
        from public.zchat_compliments c
        join public.profiles p on p.id = c.from_id
        where c.to_id = auth.uid() and auth.uid() is not null and public.zchat_session_ok() and not public.zchat_blocked_pair(c.to_id, c.from_id)
        order by c.created_at desc
        limit greatest(1, least(coalesce(p_limit, 60), 200))
      ) x
    ), '[]'::jsonb)
  )
$$;
revoke execute on function public.zchat_compliments_mine(integer) from public, anon;
grant execute on function public.zchat_compliments_mine(integer) to authenticated;

select public.zchat_apply_session_gate();

create table if not exists public.zchat_watch_items (
  id uuid primary key default gen_random_uuid(),
  chat_key text not null,
  title text not null,
  kind text not null default 'movie',
  year smallint,
  poster text,
  link text,
  added_by uuid not null references public.profiles(id) on delete cascade,
  watched_at timestamptz,
  watched_by uuid references public.profiles(id) on delete set null,
  removed_at timestamptz,
  created_at timestamptz not null default now(),
  constraint zchat_watch_title_ok check (char_length(btrim(title)) between 1 and 120),
  constraint zchat_watch_kind_ok check (kind in ('movie', 'show')),
  constraint zchat_watch_year_ok check (year is null or year between 1880 and 2100),
  constraint zchat_watch_poster_ok check (poster is null or (char_length(poster) <= 600 and poster ~* '^https://')),
  constraint zchat_watch_link_ok check (link is null or (char_length(link) <= 600 and link ~* '^https://')),
  constraint zchat_watch_key_ok check (chat_key ~ '^(g:[0-9a-f-]{36}|dm:[0-9a-f-]{36}:[0-9a-f-]{36})$')
);
alter table public.zchat_watch_items add column if not exists removed_at timestamptz;
create index if not exists zchat_watch_items_key_idx on public.zchat_watch_items (chat_key, created_at desc);
alter table public.zchat_watch_items enable row level security;

create table if not exists public.zchat_watch_reacts (
  item_id uuid not null references public.zchat_watch_items(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  chat_key text not null,
  emoji text not null,
  created_at timestamptz not null default now(),
  primary key (item_id, user_id),
  constraint zchat_watch_emoji_ok check (emoji in ('love', 'laugh', 'wow', 'fire', 'sleep', 'none'))
);
create index if not exists zchat_watch_reacts_key_idx on public.zchat_watch_reacts (chat_key);
alter table public.zchat_watch_reacts enable row level security;

drop policy if exists zchat_watch_items_read on public.zchat_watch_items;
create policy zchat_watch_items_read on public.zchat_watch_items for select to authenticated using (public.zchat_in_chat(chat_key));
drop policy if exists zchat_watch_reacts_read on public.zchat_watch_reacts;
create policy zchat_watch_reacts_read on public.zchat_watch_reacts for select to authenticated using (public.zchat_in_chat(chat_key));

create or replace function public.zchat_watch_key_ok(p_key text)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  a uuid;
  b uuid;
  me uuid := auth.uid();
begin
  if me is null or p_key is null or not public.zchat_in_chat(p_key) then
    return false;
  end if;
  if p_key like 'dm:%' then
    a := public.zchat_try_uuid(split_part(p_key, ':', 2));
    b := public.zchat_try_uuid(split_part(p_key, ':', 3));
    if a is null or b is null or a::text > b::text or public.zchat_blocked_pair(a, b) then
      return false;
    end if;
  end if;
  return true;
end
$$;
revoke execute on function public.zchat_watch_key_ok(text) from public, anon, authenticated;

create or replace function public.zchat_watch_add(p_key text, p_title text, p_kind text default 'movie', p_year integer default null, p_poster text default null, p_link text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  t text := nullif(btrim(regexp_replace(coalesce(p_title, ''), '\s+', ' ', 'g')), '');
  k text := case when p_kind = 'show' then 'show' else 'movie' end;
  po text := nullif(btrim(coalesce(p_poster, '')), '');
  li text := nullif(btrim(coalesce(p_link, '')), '');
  n integer;
  made public.zchat_watch_items%rowtype;
begin
  if me is null or not public.zchat_session_ok() then
    return jsonb_build_object('ok', false, 'why', 'login');
  end if;
  if not public.zchat_watch_key_ok(p_key) then
    return jsonb_build_object('ok', false, 'why', 'member');
  end if;
  if t is null or char_length(t) > 120 then
    return jsonb_build_object('ok', false, 'why', 'title');
  end if;
  if po is not null and (char_length(po) > 600 or po !~* '^https://([a-z0-9-]+\.)*mzstatic\.com/' or not public.zchat_url_ok(po)) then
    po := null;
  end if;
  if li is not null and (char_length(li) > 600 or li !~* '^https://' or not public.zchat_url_ok(li)) then
    return jsonb_build_object('ok', false, 'why', 'link');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('zchat_watch:' || p_key, 0));
  select count(*) into n from public.zchat_watch_items w where w.chat_key = p_key and w.removed_at is null;
  if n >= 300 then
    return jsonb_build_object('ok', false, 'why', 'full');
  end if;
  select count(*) into n from public.zchat_watch_items w where w.added_by = me and w.created_at > now() - interval '1 hour';
  if n >= 40 then
    return jsonb_build_object('ok', false, 'why', 'busy');
  end if;
  if exists (select 1 from public.zchat_watch_items w where w.chat_key = p_key and lower(w.title) = lower(t) and w.year is not distinct from case when p_year between 1880 and 2100 then p_year::smallint end and w.watched_at is null and w.removed_at is null) then
    return jsonb_build_object('ok', false, 'why', 'dupe');
  end if;
  insert into public.zchat_watch_items (chat_key, title, kind, year, poster, link, added_by)
    values (p_key, t, k, case when p_year between 1880 and 2100 then p_year::smallint end, po, li, me)
    returning * into made;
  return jsonb_build_object('ok', true, 'item', to_jsonb(made));
end
$$;
revoke execute on function public.zchat_watch_add(text, text, text, integer, text, text) from public, anon;
grant execute on function public.zchat_watch_add(text, text, text, integer, text, text) to authenticated;

create or replace function public.zchat_watch_mark(p_id uuid, p_watched boolean)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  w public.zchat_watch_items%rowtype;
begin
  if me is null or not public.zchat_session_ok() then
    return jsonb_build_object('ok', false, 'why', 'login');
  end if;
  select * into w from public.zchat_watch_items i where i.id = p_id and i.removed_at is null;
  if not found or not public.zchat_watch_key_ok(w.chat_key) then
    return jsonb_build_object('ok', false, 'why', 'member');
  end if;
  update public.zchat_watch_items
    set watched_at = case when coalesce(p_watched, false) then coalesce(watched_at, now()) end,
        watched_by = case when coalesce(p_watched, false) then coalesce(watched_by, me) end
    where id = p_id
    returning * into w;
  return jsonb_build_object('ok', true, 'item', to_jsonb(w));
end
$$;
revoke execute on function public.zchat_watch_mark(uuid, boolean) from public, anon;
grant execute on function public.zchat_watch_mark(uuid, boolean) to authenticated;

create or replace function public.zchat_watch_react(p_id uuid, p_emoji text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  w public.zchat_watch_items%rowtype;
  e text := nullif(btrim(coalesce(p_emoji, '')), '');
begin
  if me is null or not public.zchat_session_ok() then
    return jsonb_build_object('ok', false, 'why', 'login');
  end if;
  select * into w from public.zchat_watch_items i where i.id = p_id and i.removed_at is null;
  if not found or not public.zchat_watch_key_ok(w.chat_key) then
    return jsonb_build_object('ok', false, 'why', 'member');
  end if;
  if e is null or e = 'none' then
    update public.zchat_watch_reacts r set emoji = 'none', created_at = now() where r.item_id = p_id and r.user_id = me;
    return jsonb_build_object('ok', true, 'emoji', null);
  end if;
  if e not in ('love', 'laugh', 'wow', 'fire', 'sleep') then
    return jsonb_build_object('ok', false, 'why', 'emoji');
  end if;
  insert into public.zchat_watch_reacts (item_id, user_id, chat_key, emoji) values (p_id, me, w.chat_key, e)
    on conflict (item_id, user_id) do update set emoji = excluded.emoji, created_at = now();
  return jsonb_build_object('ok', true, 'emoji', e);
end
$$;
revoke execute on function public.zchat_watch_react(uuid, text) from public, anon;
grant execute on function public.zchat_watch_react(uuid, text) to authenticated;

create or replace function public.zchat_watch_remove(p_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  w public.zchat_watch_items%rowtype;
  gid uuid;
begin
  if me is null or not public.zchat_session_ok() then
    return jsonb_build_object('ok', false, 'why', 'login');
  end if;
  select * into w from public.zchat_watch_items i where i.id = p_id and i.removed_at is null;
  if not found or not public.zchat_watch_key_ok(w.chat_key) then
    return jsonb_build_object('ok', false, 'why', 'member');
  end if;
  if w.added_by <> me then
    gid := case when w.chat_key like 'g:%' then public.zchat_try_uuid(substr(w.chat_key, 3)) end;
    if gid is null or not exists (
      select 1 from public.groups g where g.id = gid and g.created_by = me
      union all
      select 1 from public.group_members gm where gm.group_id = gid and gm.user_id = me and gm.role in ('admin', 'owner')
    ) then
      return jsonb_build_object('ok', false, 'why', 'owner');
    end if;
  end if;
  update public.zchat_watch_items set removed_at = now() where id = p_id and removed_at is null;
  if random() < 0.05 then
    delete from public.zchat_watch_items where removed_at < now() - interval '2 days';
  end if;
  return jsonb_build_object('ok', true);
end
$$;
revoke execute on function public.zchat_watch_remove(uuid) from public, anon;
grant execute on function public.zchat_watch_remove(uuid) to authenticated;

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'zchat_watch_items') then
      execute 'alter publication supabase_realtime add table public.zchat_watch_items';
    end if;
    if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'zchat_watch_reacts') then
      execute 'alter publication supabase_realtime add table public.zchat_watch_reacts';
    end if;
  end if;
end $$;

select public.zchat_apply_session_gate();
commit;

begin;
create table if not exists public.zchat_user_tz (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  tz text not null,
  updated_at timestamptz not null default now(),
  constraint zchat_user_tz_ok check (char_length(tz) <= 64)
);
alter table public.zchat_user_tz enable row level security;
drop policy if exists zchat_user_tz_own on public.zchat_user_tz;
create policy zchat_user_tz_own on public.zchat_user_tz for select to authenticated using (user_id = auth.uid());

create or replace function public.zchat_pf_tz_set(p_tz text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  t text := btrim(coalesce(p_tz, ''));
begin
  if me is null or not public.zchat_session_ok() then
    return jsonb_build_object('ok', false);
  end if;
  if t = '' or char_length(t) > 64 or not exists (select 1 from pg_timezone_names z where z.name = t) then
    return jsonb_build_object('ok', false, 'why', 'tz');
  end if;
  insert into public.zchat_user_tz (user_id, tz, updated_at) values (me, t, now())
    on conflict (user_id) do update set tz = excluded.tz, updated_at = excluded.updated_at
    where public.zchat_user_tz.tz is distinct from excluded.tz;
  return jsonb_build_object('ok', true);
end
$$;
revoke execute on function public.zchat_pf_tz_set(text) from public, anon;
grant execute on function public.zchat_pf_tz_set(text) to authenticated;

create table if not exists public.zchat_bday_cards (
  id uuid primary key default gen_random_uuid(),
  for_id uuid not null references public.profiles(id) on delete cascade,
  year smallint not null,
  md text not null,
  opens_at timestamptz not null,
  starter_id uuid not null references public.profiles(id) on delete cascade,
  shown boolean not null default false,
  seen_at timestamptz,
  created_at timestamptz not null default now(),
  constraint zchat_bday_card_once unique (for_id, year)
);
create table if not exists public.zchat_bday_card_people (
  card_id uuid not null references public.zchat_bday_cards(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  invited_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  primary key (card_id, user_id)
);
create index if not exists zchat_bday_card_people_user_idx on public.zchat_bday_card_people (user_id);
create table if not exists public.zchat_bday_card_signs (
  card_id uuid not null references public.zchat_bday_cards(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  body text,
  sticker text,
  photo text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (card_id, user_id),
  constraint zchat_bday_sign_body_ok check (body is null or char_length(body) <= 140),
  constraint zchat_bday_sign_sticker_ok check (sticker is null or sticker ~ '^/[A-Za-z0-9][A-Za-z0-9._-]{1,90}\.(webp|gif|png)$'),
  constraint zchat_bday_sign_photo_ok check (photo is null or (char_length(photo) <= 600 and photo ~* '^https://')),
  constraint zchat_bday_sign_some check (body is not null or sticker is not null or photo is not null)
);
alter table public.zchat_bday_cards enable row level security;
alter table public.zchat_bday_card_people enable row level security;
alter table public.zchat_bday_card_signs enable row level security;

create or replace function public.zchat_bday_date(p_year integer, p_month integer, p_day integer)
returns date
language plpgsql
immutable
as $$
begin
  if p_month = 2 and p_day = 29 and not ((p_year % 4 = 0 and p_year % 100 <> 0) or p_year % 400 = 0) then
    return make_date(p_year, 2, 28);
  end if;
  return make_date(p_year, p_month, p_day);
exception when others then
  return null;
end
$$;

create or replace function public.zchat_bday_next(p_user uuid, out md text, out d date, out opens timestamptz, out yr integer, out days integer)
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  tzn text;
  today date;
  m integer;
  dd integer;
  y integer;
  cand date;
begin
  select b.md into md from public.birthdays b where b.user_id = p_user;
  if md is null or md !~ '^[0-9]{2}-[0-9]{2}$' then
    md := null;
    return;
  end if;
  select z.tz into tzn from public.zchat_user_tz z where z.user_id = p_user;
  if tzn is null or not exists (select 1 from pg_timezone_names n where n.name = tzn) then
    tzn := 'UTC';
  end if;
  today := (now() at time zone tzn)::date;
  m := split_part(md, '-', 1)::integer;
  dd := split_part(md, '-', 2)::integer;
  y := extract(year from today)::integer;
  cand := public.zchat_bday_date(y, m, dd);
  if cand is null then
    md := null;
    return;
  end if;
  if cand < today then
    cand := public.zchat_bday_date(y + 1, m, dd);
  end if;
  d := cand;
  yr := extract(year from cand)::integer;
  opens := (cand::timestamp) at time zone tzn;
  days := cand - today;
end
$$;
revoke execute on function public.zchat_bday_next(uuid) from public, anon, authenticated;

create or replace function public.zchat_bday_visible(p_user uuid, p_viewer uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select case
    when p_user is null or p_viewer is null then false
    when p_user = p_viewer then true
    when public.zchat_blocked_pair(p_user, p_viewer) or public.zchat_on_break(p_user) then false
    else exists (
      select 1 from public.birthdays b
      join public.profiles p on p.id = b.user_id and not coalesce(p.is_deleted, false) and not coalesce(p.banned, false)
      where b.user_id = p_user and (
        b.show = 'everyone'
        or (b.show = 'followers' and public.zchat_follows(p_viewer, p_user))
        or (b.show = 'mutual' and public.zchat_follows(p_viewer, p_user) and public.zchat_follows(p_user, p_viewer))
      )
    )
  end
$$;
revoke execute on function public.zchat_bday_visible(uuid, uuid) from public, anon, authenticated;

create or replace function public.zchat_bday_pool(p_user uuid, p_me uuid)
returns table (user_id uuid, via text)
language sql
stable
security definer
set search_path = public
as $$
  with friends as (
    select x.id from (
      select f.follower_id as id from public.follows f where f.following_id = p_user and coalesce(f.status, 'accepted') = 'accepted'
      union
      select f.following_id from public.follows f where f.follower_id = p_user and coalesce(f.status, 'accepted') = 'accepted'
    ) x
    where exists (select 1 from public.follows f where f.follower_id = p_me and f.following_id = x.id and coalesce(f.status, 'accepted') = 'accepted')
       or exists (select 1 from public.follows f where f.following_id = p_me and f.follower_id = x.id and coalesce(f.status, 'accepted') = 'accepted')
  ),
  groupmates as (
    select distinct gm.user_id as id
    from public.group_members a
    join public.group_members b on b.group_id = a.group_id and b.user_id = p_me
    join public.group_members gm on gm.group_id = a.group_id
    where a.user_id = p_user
  ),
  pool as (
    select id, 'friend'::text as via from friends
    union all
    select id, 'group'::text from groupmates where id not in (select id from friends)
  )
  select pl.id, min(pl.via)
  from pool pl
  join public.profiles p on p.id = pl.id
  where pl.id <> p_user and pl.id <> p_me
    and not coalesce(p.is_deleted, false) and not coalesce(p.banned, false) and not coalesce(p.is_bot, false)
    and not public.zchat_blocked_pair(pl.id, p_user) and not public.zchat_blocked_pair(pl.id, p_me)
    and not public.zchat_on_break(pl.id)
  group by pl.id
  limit 400
$$;
revoke execute on function public.zchat_bday_pool(uuid, uuid) from public, anon, authenticated;

create or replace function public.zchat_bday_candidates(p_user uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select case when auth.uid() is null or not public.zchat_session_ok() or not public.zchat_bday_visible(p_user, auth.uid()) or p_user = auth.uid() then '[]'::jsonb else coalesce((
    select jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name, 'username', p.username, 'avatar', case when coalesce(p.hide_photo, false) then null else p.avatar end, 'verified', p.verified, 'via', c.via) order by c.via desc, lower(p.name))
    from public.zchat_bday_pool(p_user, auth.uid()) c
    join public.profiles p on p.id = c.user_id
  ), '[]'::jsonb) end
$$;
revoke execute on function public.zchat_bday_candidates(uuid) from public, anon;
grant execute on function public.zchat_bday_candidates(uuid) to authenticated;

create or replace function public.zchat_bday_card_for(p_user uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  nx record;
  c public.zchat_bday_cards%rowtype;
  n integer;
begin
  if me is null or not public.zchat_session_ok() or p_user is null or p_user = me then
    return jsonb_build_object('ok', false);
  end if;
  if not public.zchat_bday_visible(p_user, me) then
    return jsonb_build_object('ok', false);
  end if;
  select * into nx from public.zchat_bday_next(p_user);
  if nx.md is null then
    return jsonb_build_object('ok', false);
  end if;
  if nx.days > 30 then
    return jsonb_build_object('ok', true, 'soon', false, 'days', nx.days);
  end if;
  select * into c from public.zchat_bday_cards b where b.for_id = p_user and b.year = nx.yr;
  if not found then
    return jsonb_build_object('ok', true, 'soon', true, 'days', nx.days, 'md', nx.md, 'opens_at', nx.opens, 'can_start', true);
  end if;
  if not exists (select 1 from public.zchat_bday_card_people pp where pp.card_id = c.id and pp.user_id = me) then
    return jsonb_build_object('ok', true, 'soon', true, 'days', nx.days, 'md', nx.md, 'opens_at', nx.opens, 'can_start', false, 'taken', true);
  end if;
  select count(*) into n from public.zchat_bday_card_signs s where s.card_id = c.id;
  return jsonb_build_object('ok', true, 'soon', true, 'days', nx.days, 'md', nx.md, 'opens_at', c.opens_at, 'can_start', false,
    'card', jsonb_build_object('id', c.id, 'n', n, 'signed', exists (select 1 from public.zchat_bday_card_signs s where s.card_id = c.id and s.user_id = me), 'starter', c.starter_id = me));
end
$$;
revoke execute on function public.zchat_bday_card_for(uuid) from public, anon;
grant execute on function public.zchat_bday_card_for(uuid) to authenticated;

create or replace function public.zchat_bday_card_start(p_user uuid, p_invite uuid[] default '{}'::uuid[])
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  nx record;
  c public.zchat_bday_cards%rowtype;
  who text;
  inv uuid;
  added integer := 0;
begin
  if me is null or not public.zchat_session_ok() then
    return jsonb_build_object('ok', false, 'why', 'login');
  end if;
  if p_user is null or p_user = me then
    return jsonb_build_object('ok', false, 'why', 'self');
  end if;
  if not public.zchat_bday_visible(p_user, me) then
    return jsonb_build_object('ok', false, 'why', 'hidden');
  end if;
  select * into nx from public.zchat_bday_next(p_user);
  if nx.md is null or nx.days > 30 then
    return jsonb_build_object('ok', false, 'why', 'early');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('zchat_bday:' || p_user::text || ':' || nx.yr::text, 0));
  select * into c from public.zchat_bday_cards b where b.for_id = p_user and b.year = nx.yr;
  if found then
    if exists (select 1 from public.zchat_bday_card_people pp where pp.card_id = c.id and pp.user_id = me) then
      return jsonb_build_object('ok', false, 'why', 'exists', 'id', c.id);
    end if;
    return jsonb_build_object('ok', false, 'why', 'taken');
  end if;
  insert into public.zchat_bday_cards (for_id, year, md, opens_at, starter_id) values (p_user, nx.yr, nx.md, nx.opens, me) returning * into c;
  insert into public.zchat_bday_card_people (card_id, user_id, invited_by) values (c.id, me, me);
  select p.name into who from public.profiles p where p.id = p_user;
  for inv in
    select distinct u from unnest(coalesce(p_invite, '{}'::uuid[])) u
    where u in (select pl.user_id from public.zchat_bday_pool(p_user, me) pl)
    limit 60
  loop
    insert into public.zchat_bday_card_people (card_id, user_id, invited_by) values (c.id, inv, me) on conflict do nothing;
    perform public.zchat_notify(inv, me, 'bday_card', null, who, jsonb_build_object('card', c.id, 'for', p_user));
    added := added + 1;
  end loop;
  perform public.zchat_notify(p_user, null, 'bday_open', null, null, jsonb_build_object('card', c.id), greatest(c.opens_at, now()));
  return jsonb_build_object('ok', true, 'id', c.id, 'invited', added, 'opens_at', c.opens_at);
end
$$;
revoke execute on function public.zchat_bday_card_start(uuid, uuid[]) from public, anon;
grant execute on function public.zchat_bday_card_start(uuid, uuid[]) to authenticated;

create or replace function public.zchat_bday_card_invite(p_card uuid, p_invite uuid[])
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  c public.zchat_bday_cards%rowtype;
  who text;
  inv uuid;
  added integer := 0;
  have integer;
begin
  if me is null or not public.zchat_session_ok() then
    return jsonb_build_object('ok', false, 'why', 'login');
  end if;
  select * into c from public.zchat_bday_cards b where b.id = p_card;
  if not found or c.starter_id <> me then
    return jsonb_build_object('ok', false, 'why', 'starter');
  end if;
  if now() > c.opens_at + interval '3 days' then
    return jsonb_build_object('ok', false, 'why', 'late');
  end if;
  select count(*) into have from public.zchat_bday_card_people pp where pp.card_id = c.id;
  select p.name into who from public.profiles p where p.id = c.for_id;
  for inv in
    select distinct u from unnest(coalesce(p_invite, '{}'::uuid[])) u
    where u in (select pl.user_id from public.zchat_bday_pool(c.for_id, me) pl)
      and not exists (select 1 from public.zchat_bday_card_people pp where pp.card_id = c.id and pp.user_id = u)
    limit greatest(0, 61 - have)
  loop
    insert into public.zchat_bday_card_people (card_id, user_id, invited_by) values (c.id, inv, me) on conflict do nothing;
    perform public.zchat_notify(inv, me, 'bday_card', null, who, jsonb_build_object('card', c.id, 'for', c.for_id));
    added := added + 1;
  end loop;
  return jsonb_build_object('ok', true, 'invited', added);
end
$$;
revoke execute on function public.zchat_bday_card_invite(uuid, uuid[]) from public, anon;
grant execute on function public.zchat_bday_card_invite(uuid, uuid[]) to authenticated;

create or replace function public.zchat_bday_card_sign(p_card uuid, p_body text, p_sticker text default null, p_photo text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  c public.zchat_bday_cards%rowtype;
  b text := nullif(btrim(coalesce(p_body, '')), '');
  s text := nullif(btrim(coalesce(p_sticker, '')), '');
  ph text := nullif(btrim(coalesce(p_photo, '')), '');
begin
  if me is null or not public.zchat_session_ok() then
    return jsonb_build_object('ok', false, 'why', 'login');
  end if;
  select * into c from public.zchat_bday_cards x where x.id = p_card;
  if not found or c.for_id = me or not exists (select 1 from public.zchat_bday_card_people pp where pp.card_id = c.id and pp.user_id = me) then
    return jsonb_build_object('ok', false, 'why', 'member');
  end if;
  if now() > c.opens_at + interval '3 days' then
    return jsonb_build_object('ok', false, 'why', 'late');
  end if;
  if b is null and s is null and ph is null then
    return jsonb_build_object('ok', false, 'why', 'empty');
  end if;
  if b is not null and char_length(b) > 140 then
    return jsonb_build_object('ok', false, 'why', 'long');
  end if;
  if s is not null and s !~ '^/[A-Za-z0-9][A-Za-z0-9._-]{1,90}\.(webp|gif|png)$' then
    return jsonb_build_object('ok', false, 'why', 'sticker');
  end if;
  if ph is not null and not public.zchat_photo_url_ok(me, ph) then
    return jsonb_build_object('ok', false, 'why', 'photo');
  end if;
  insert into public.zchat_bday_card_signs (card_id, user_id, body, sticker, photo) values (c.id, me, b, s, ph)
    on conflict (card_id, user_id) do update set body = excluded.body, sticker = excluded.sticker, photo = excluded.photo, updated_at = now();
  return jsonb_build_object('ok', true);
end
$$;
revoke execute on function public.zchat_bday_card_sign(uuid, text, text, text) from public, anon;
grant execute on function public.zchat_bday_card_sign(uuid, text, text, text) to authenticated;

create or replace function public.zchat_bday_card_unsign(p_card uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
begin
  if me is null or not public.zchat_session_ok() then
    return jsonb_build_object('ok', false, 'why', 'login');
  end if;
  delete from public.zchat_bday_card_signs s where s.card_id = p_card and s.user_id = me
    and exists (select 1 from public.zchat_bday_cards c where c.id = p_card and now() <= c.opens_at + interval '3 days');
  return jsonb_build_object('ok', found);
end
$$;
revoke execute on function public.zchat_bday_card_unsign(uuid) from public, anon;
grant execute on function public.zchat_bday_card_unsign(uuid) to authenticated;

create or replace function public.zchat_bday_card_get(p_card uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  c public.zchat_bday_cards%rowtype;
  role text;
  is_open boolean;
  out_signs jsonb;
  out_people jsonb;
begin
  if me is null or not public.zchat_session_ok() then
    return jsonb_build_object('ok', false, 'why', 'login');
  end if;
  select * into c from public.zchat_bday_cards x where x.id = p_card;
  if not found then
    return jsonb_build_object('ok', false, 'why', 'gone');
  end if;
  is_open := now() >= c.opens_at;
  if me = c.for_id then
    role := case when is_open then 'owner' end;
  elsif exists (select 1 from public.zchat_bday_card_people pp where pp.card_id = c.id and pp.user_id = me) then
    role := 'member';
  elsif c.shown and is_open and public.zchat_pf_can_see(c.for_id) then
    role := 'viewer';
  end if;
  if role is null then
    return jsonb_build_object('ok', false, 'why', 'hidden');
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('user_id', s.user_id, 'name', p.name, 'username', p.username, 'avatar', case when coalesce(p.hide_photo, false) then null else p.avatar end,
      'body', s.body, 'sticker', s.sticker, 'photo', s.photo, 'at', s.updated_at) order by s.created_at), '[]'::jsonb)
    into out_signs
    from public.zchat_bday_card_signs s
    join public.profiles p on p.id = s.user_id and not coalesce(p.is_deleted, false) and not coalesce(p.banned, false)
    where s.card_id = c.id and not public.zchat_blocked_pair(s.user_id, me);
  if role = 'member' then
    select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name, 'avatar', case when coalesce(p.hide_photo, false) then null else p.avatar end,
        'signed', exists (select 1 from public.zchat_bday_card_signs s where s.card_id = c.id and s.user_id = p.id)) order by pp.created_at), '[]'::jsonb)
      into out_people
      from public.zchat_bday_card_people pp
      join public.profiles p on p.id = pp.user_id
      where pp.card_id = c.id;
  end if;
  return jsonb_build_object('ok', true, 'role', role, 'id', c.id, 'year', c.year, 'md', c.md, 'opens_at', c.opens_at, 'open', is_open,
    'shown', c.shown, 'seen', c.seen_at is not null, 'starter', c.starter_id = me, 'can_sign', role = 'member' and now() <= c.opens_at + interval '3 days',
    'for', (select jsonb_build_object('id', p.id, 'name', p.name, 'username', p.username, 'avatar', case when coalesce(p.hide_photo, false) then null else p.avatar end) from public.profiles p where p.id = c.for_id),
    'signs', out_signs, 'people', out_people);
end
$$;
revoke execute on function public.zchat_bday_card_get(uuid) from public, anon;
grant execute on function public.zchat_bday_card_get(uuid) to authenticated;

create or replace function public.zchat_bday_cards_mine()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select case when auth.uid() is null or not public.zchat_session_ok() then '[]'::jsonb else coalesce((
    select jsonb_agg(jsonb_build_object('id', c.id, 'year', c.year, 'opens_at', c.opens_at, 'seen', c.seen_at is not null, 'shown', c.shown,
      'n', (select count(*) from public.zchat_bday_card_signs s where s.card_id = c.id)) order by c.opens_at desc)
    from public.zchat_bday_cards c
    where c.for_id = auth.uid() and c.opens_at <= now()
  ), '[]'::jsonb) end
$$;
revoke execute on function public.zchat_bday_cards_mine() from public, anon;
grant execute on function public.zchat_bday_cards_mine() to authenticated;

create or replace function public.zchat_bday_card_mark(p_card uuid, p_seen boolean default null, p_shown boolean default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
begin
  if me is null or not public.zchat_session_ok() then
    return jsonb_build_object('ok', false, 'why', 'login');
  end if;
  update public.zchat_bday_cards c
    set seen_at = case when coalesce(p_seen, false) and c.seen_at is null then now() else c.seen_at end,
        shown = coalesce(p_shown, c.shown)
    where c.id = p_card and c.for_id = me and c.opens_at <= now();
  return jsonb_build_object('ok', found);
end
$$;
revoke execute on function public.zchat_bday_card_mark(uuid, boolean, boolean) from public, anon;
grant execute on function public.zchat_bday_card_mark(uuid, boolean, boolean) to authenticated;

select public.zchat_apply_session_gate();
commit;

begin;
create or replace function public.zchat_pf_extras(p_user uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select case when p_user is null or auth.uid() is null or not public.zchat_session_ok() then jsonb_build_object('ok', false) else jsonb_build_object(
    'ok', true,
    'self', auth.uid() = p_user,
    'photos', case when public.zchat_photo_visible(p_user) then coalesce((select jsonb_agg(ph.url order by ph.pos) from public.zchat_profile_photos ph where ph.user_id = p_user), '[]'::jsonb) else '[]'::jsonb end,
    'voice', case when z.vis then (select jsonb_build_object('path', v.path, 'secs', v.secs, 'say', v.say, 'peaks', v.peaks, 'at', v.updated_at) from public.zchat_voice_intros v where v.user_id = p_user) end,
    'compliments', case when z.vis then coalesce((
      select jsonb_agg(jsonb_build_object('k', c.kind, 'n', c.n) order by c.n desc, c.kind)
      from (
        select cc.kind, count(*) as n from public.zchat_compliments cc
        where cc.to_id = p_user and cc.shown and not public.zchat_blocked_pair(cc.to_id, cc.from_id)
        group by cc.kind
      ) c
    ), '[]'::jsonb) else '[]'::jsonb end,
    'compliments_new', case when auth.uid() = p_user then (select count(*) from public.zchat_compliments cc where cc.to_id = p_user and cc.seen_at is null) else 0 end,
    'compliments_all', case when auth.uid() = p_user then (select count(*) from public.zchat_compliments cc where cc.to_id = p_user) else 0 end,
    'cards', case when z.vis then coalesce((
      select jsonb_agg(jsonb_build_object('id', b.id, 'year', b.year, 'n', (select count(*) from public.zchat_bday_card_signs s where s.card_id = b.id)) order by b.year desc)
      from public.zchat_bday_cards b
      where b.for_id = p_user and b.opens_at <= now() and (b.shown or auth.uid() = p_user)
    ), '[]'::jsonb) else '[]'::jsonb end
  ) end
  from (select public.zchat_pf_can_see(p_user) as vis) z
$$;
revoke execute on function public.zchat_pf_extras(uuid) from public, anon;
grant execute on function public.zchat_pf_extras(uuid) to authenticated;

drop policy if exists "zchat stories own delete" on public.stories;
create policy "zchat stories own delete" on public.stories for delete to authenticated
  using (user_id = (select auth.uid()));

drop policy if exists "zchat story views private" on public.story_views;
create policy "zchat story views private" on public.story_views as restrictive for select to authenticated
  using (viewer_id = (select auth.uid()) or exists (select 1 from public.stories s where s.id = story_views.story_id and s.user_id = (select auth.uid())));

drop policy if exists "zchat story likes private" on public.story_likes;
create policy "zchat story likes private" on public.story_likes as restrictive for select to authenticated
  using (user_id = (select auth.uid()) or exists (select 1 from public.stories s where s.id = story_likes.story_id and s.user_id = (select auth.uid())));

drop policy if exists "zchat private account highlights" on public.highlights;
create policy "zchat private account highlights" on public.highlights as restrictive for select to authenticated
  using (user_id is null or user_id = (select auth.uid()) or public.zchat_owner_visible(user_id, 'stories'));

drop policy if exists "zchat private account highlight items" on public.highlight_items;
create policy "zchat private account highlight items" on public.highlight_items as restrictive for select to authenticated
  using (user_id is null or user_id = (select auth.uid()) or public.zchat_owner_visible(user_id, 'stories'));

create table if not exists public.zchat_story_lists (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users(id) on delete cascade,
  name text not null,
  created_at timestamptz not null default now(),
  constraint zchat_story_lists_name check (char_length(btrim(name)) between 1 and 30)
);
create index if not exists zchat_story_lists_owner on public.zchat_story_lists (owner_id, created_at);

create table if not exists public.zchat_story_list_members (
  list_id uuid not null references public.zchat_story_lists(id) on delete cascade,
  member_id uuid not null references auth.users(id) on delete cascade,
  owner_id uuid not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (list_id, member_id),
  constraint zchat_story_list_members_self check (member_id <> owner_id)
);
create index if not exists zchat_story_list_members_member on public.zchat_story_list_members (member_id, list_id);
create index if not exists zchat_story_list_members_owner on public.zchat_story_list_members (owner_id);

alter table public.zchat_story_lists enable row level security;
alter table public.zchat_story_list_members enable row level security;

drop policy if exists "zchat story lists own" on public.zchat_story_lists;
create policy "zchat story lists own" on public.zchat_story_lists for all to authenticated
  using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));

drop policy if exists "zchat story list members own" on public.zchat_story_list_members;
create policy "zchat story list members own" on public.zchat_story_list_members for all to authenticated
  using (owner_id = (select auth.uid()))
  with check (owner_id = (select auth.uid()) and exists (select 1 from public.zchat_story_lists l where l.id = list_id and l.owner_id = (select auth.uid())));

revoke all on table public.zchat_story_lists from anon;
revoke all on table public.zchat_story_list_members from anon;
grant select, insert, update, delete on table public.zchat_story_lists to authenticated;
grant select, insert, delete on table public.zchat_story_list_members to authenticated;
revoke update on table public.zchat_story_list_members from authenticated;

create or replace function public.zchat_story_lists_guard()
returns trigger
language plpgsql
set search_path to 'public'
as $$
declare
  n integer;
begin
  new.name := btrim(new.name);
  if tg_op = 'UPDATE' then
    new.owner_id := old.owner_id;
    new.created_at := old.created_at;
    return new;
  end if;
  perform pg_advisory_xact_lock(hashtext('zchat_story_lists:' || new.owner_id::text));
  select count(*) into n from public.zchat_story_lists where owner_id = new.owner_id;
  if n >= 10 then
    raise exception 'You can have up to 10 lists' using errcode = '54000';
  end if;
  return new;
end $$;
drop trigger if exists zchat_story_lists_guard on public.zchat_story_lists;
create trigger zchat_story_lists_guard before insert or update on public.zchat_story_lists
  for each row execute function public.zchat_story_lists_guard();

create or replace function public.zchat_story_list_members_guard()
returns trigger
language plpgsql
set search_path to 'public'
as $$
declare
  n integer;
  o uuid;
begin
  select l.owner_id into o from public.zchat_story_lists l where l.id = new.list_id;
  if o is null or o <> new.owner_id then
    raise exception 'That list is not yours' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtext('zchat_story_list_members:' || new.list_id::text));
  select count(*) into n from public.zchat_story_list_members where list_id = new.list_id;
  if n >= 1000 then
    raise exception 'This list is full' using errcode = '54000';
  end if;
  return new;
end $$;
drop trigger if exists zchat_story_list_members_guard on public.zchat_story_list_members;
create trigger zchat_story_list_members_guard before insert on public.zchat_story_list_members
  for each row execute function public.zchat_story_list_members_guard();

create or replace function public.zchat_story_visible(p_owner uuid, p_audience text, p_viewer uuid)
returns boolean
language sql
stable security definer
set search_path to 'public'
as $function$
  select (p_viewer is not null and p_viewer = p_owner)
    or (
      (p_viewer is null or not exists (select 1 from public.story_hidden h where h.owner_id = p_owner and h.hidden_id = p_viewer))
      and (
        case
          when coalesce(p_audience, 'all') = 'close' then
            p_viewer is not null and exists (select 1 from public.close_friends c where c.owner_id = p_owner and c.friend_id = p_viewer)
          when p_audience like 'list:%' then
            p_viewer is not null and exists (
              select 1 from public.zchat_story_list_members m
              join public.zchat_story_lists l on l.id = m.list_id
              where l.id = public.zchat_try_uuid(substr(p_audience, 6)) and l.owner_id = p_owner and m.member_id = p_viewer
            )
          else true
        end
      )
    )
    or public.zchat_is_admin_id(p_viewer)
$function$;

create or replace function public.zchat_story_audience_guard()
returns trigger
language plpgsql
set search_path to 'public'
as $$
declare
  a text := coalesce(new.audience, 'all');
  sid text := to_jsonb(new) ->> 'shared_id';
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;
  if a = 'all' then
    return new;
  end if;
  if sid is not null then
    raise exception 'Shared stories use their own audience' using errcode = '22023';
  end if;
  if a = 'close' then
    return new;
  end if;
  if a like 'list:%' then
    if not exists (select 1 from public.zchat_story_lists l where l.id = public.zchat_try_uuid(substr(a, 6)) and l.owner_id = new.user_id) then
      raise exception 'That list is not yours' using errcode = '42501';
    end if;
    return new;
  end if;
  raise exception 'That audience is not available' using errcode = '22023';
end $$;
drop trigger if exists zchat_story_audience_guard on public.stories;
create trigger zchat_story_audience_guard before insert or update of audience on public.stories
  for each row execute function public.zchat_story_audience_guard();

select public.zchat_apply_session_gate();

create table if not exists public.zchat_drafts (
  user_id uuid not null references auth.users(id) on delete cascade,
  id text not null,
  kind text not null,
  data jsonb not null default '{}'::jsonb,
  thumb text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, id),
  constraint zchat_drafts_id check (id ~ '^[A-Za-z0-9_-]{4,40}$'),
  constraint zchat_drafts_kind check (kind in ('post', 'story')),
  constraint zchat_drafts_data check (jsonb_typeof(data) = 'object' and pg_column_size(data) <= 300000),
  constraint zchat_drafts_thumb check (thumb is null or (char_length(thumb) <= 300 and thumb !~ '[[:space:]]'))
);
create index if not exists zchat_drafts_user_time on public.zchat_drafts (user_id, updated_at desc);

alter table public.zchat_drafts enable row level security;
drop policy if exists "zchat drafts own" on public.zchat_drafts;
create policy "zchat drafts own" on public.zchat_drafts for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
revoke all on table public.zchat_drafts from anon;
grant select, insert, update, delete on table public.zchat_drafts to authenticated;

create or replace function public.zchat_drafts_guard()
returns trigger
language plpgsql
set search_path to 'public'
as $$
declare
  n integer;
begin
  if tg_op = 'UPDATE' then
    new.user_id := old.user_id;
    new.id := old.id;
    new.created_at := old.created_at;
    new.updated_at := now();
    return new;
  end if;
  perform pg_advisory_xact_lock(hashtext('zchat_drafts:' || new.user_id::text));
  if not exists (select 1 from public.zchat_drafts where user_id = new.user_id and id = new.id) then
    select count(*) into n from public.zchat_drafts where user_id = new.user_id;
    if n >= 20 then
      raise exception 'You can keep up to 20 drafts. Delete one to save this.' using errcode = '54000';
    end if;
  end if;
  new.created_at := now();
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists zchat_drafts_guard on public.zchat_drafts;
create trigger zchat_drafts_guard before insert or update on public.zchat_drafts
  for each row execute function public.zchat_drafts_guard();

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'zchat_drafts') then
    execute 'alter publication supabase_realtime add table public.zchat_drafts';
  end if;
end $$;

select public.zchat_apply_session_gate();
commit;

begin;
create table if not exists public.zchat_shared_stories (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users(id) on delete cascade,
  title text not null,
  audience text not null default 'members',
  group_id uuid references public.groups(id) on delete set null,
  keep boolean not null default false,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default (now() + interval '24 hours'),
  constraint zchat_shared_stories_title check (char_length(btrim(title)) between 1 and 40),
  constraint zchat_shared_stories_audience check (audience in ('members', 'followers', 'everyone'))
);
create index if not exists zchat_shared_stories_owner on public.zchat_shared_stories (owner_id, created_at desc);

create table if not exists public.zchat_shared_members (
  shared_id uuid not null references public.zchat_shared_stories(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  added_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  primary key (shared_id, user_id)
);
create index if not exists zchat_shared_members_user on public.zchat_shared_members (user_id, shared_id);

alter table public.stories add column if not exists shared_id uuid references public.zchat_shared_stories(id) on delete cascade;
create index if not exists zchat_stories_shared on public.stories (shared_id, created_at) where shared_id is not null;

create or replace function public.zchat_shared_member(p_shared uuid, p_user uuid)
returns boolean
language sql
stable security definer
set search_path to 'public'
as $$
  select p_shared is not null and p_user is not null and (
    exists (select 1 from public.zchat_shared_stories s where s.id = p_shared and s.owner_id = p_user)
    or exists (select 1 from public.zchat_shared_members m where m.shared_id = p_shared and m.user_id = p_user)
  )
$$;

create or replace function public.zchat_shared_can_see(p_shared uuid)
returns boolean
language plpgsql
stable security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  s record;
begin
  if p_shared is null then
    return false;
  end if;
  select id, owner_id, audience into s from public.zchat_shared_stories where id = p_shared;
  if not found then
    return false;
  end if;
  if me is not null and (me = s.owner_id or public.zchat_is_admin_id(me)) then
    return true;
  end if;
  if me is not null and exists (select 1 from public.zchat_shared_members m where m.shared_id = p_shared and m.user_id = me) then
    return true;
  end if;
  if s.audience = 'members' then
    return false;
  end if;
  if me is not null and public.zchat_blocked_pair(me, s.owner_id) then
    return false;
  end if;
  if s.audience = 'followers' then
    return me is not null and public.zchat_follows(me, s.owner_id);
  end if;
  return public.zchat_owner_visible(s.owner_id, 'stories');
end $$;

create or replace function public.zchat_shared_can_add(p_shared uuid)
returns boolean
language plpgsql
stable security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  s record;
  n integer;
  mine integer;
begin
  if p_shared is null then
    return true;
  end if;
  if me is null then
    return false;
  end if;
  select id, owner_id, expires_at into s from public.zchat_shared_stories where id = p_shared;
  if not found or s.expires_at <= now() then
    return false;
  end if;
  if not public.zchat_shared_member(p_shared, me) then
    return false;
  end if;
  select count(*), count(*) filter (where user_id = me) into n, mine from public.stories where shared_id = p_shared;
  return n < 100 and mine < 30;
end $$;

create or replace function public.zchat_shared_clip_guard()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  ends timestamptz;
begin
  if new.shared_id is null then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.shared_id is distinct from old.shared_id then
    raise exception 'Clips can not move between shared stories' using errcode = '42501';
  end if;
  select expires_at into ends from public.zchat_shared_stories where id = new.shared_id;
  if ends is not null then
    new.expires_at := least(coalesce(new.expires_at, now() + interval '24 hours'), ends);
  end if;
  return new;
end $$;
drop trigger if exists zchat_shared_clip_guard on public.stories;
create trigger zchat_shared_clip_guard before insert or update of shared_id on public.stories
  for each row execute function public.zchat_shared_clip_guard();

drop policy if exists "zchat shared story clips" on public.stories;
create policy "zchat shared story clips" on public.stories as restrictive for select to anon, authenticated
  using (shared_id is null or user_id = (select auth.uid()) or public.zchat_shared_can_see(shared_id));

drop policy if exists "zchat shared story add" on public.stories;
create policy "zchat shared story add" on public.stories as restrictive for insert to authenticated
  with check (shared_id is null or public.zchat_shared_can_add(shared_id));

drop policy if exists "zchat shared story owner delete" on public.stories;
create policy "zchat shared story owner delete" on public.stories for delete to authenticated
  using (shared_id is not null and exists (select 1 from public.zchat_shared_stories s where s.id = stories.shared_id and s.owner_id = (select auth.uid())));

alter table public.zchat_shared_stories enable row level security;
alter table public.zchat_shared_members enable row level security;

drop policy if exists "zchat shared stories read" on public.zchat_shared_stories;
create policy "zchat shared stories read" on public.zchat_shared_stories for select to authenticated
  using (public.zchat_shared_can_see(id));
drop policy if exists "zchat shared stories owner delete" on public.zchat_shared_stories;
create policy "zchat shared stories owner delete" on public.zchat_shared_stories for delete to authenticated
  using (owner_id = (select auth.uid()));

drop policy if exists "zchat shared members read" on public.zchat_shared_members;
create policy "zchat shared members read" on public.zchat_shared_members for select to authenticated
  using (public.zchat_shared_member(shared_id, (select auth.uid())));

revoke all on table public.zchat_shared_stories from anon;
revoke all on table public.zchat_shared_members from anon;
revoke insert, update, truncate, references, trigger on table public.zchat_shared_stories from authenticated;
revoke insert, update, delete, truncate, references, trigger on table public.zchat_shared_members from authenticated;
grant select, delete on table public.zchat_shared_stories to authenticated;
grant select on table public.zchat_shared_members to authenticated;

create or replace function public.zchat_shared_person_ok(p_me uuid, p_user uuid)
returns boolean
language sql
stable security definer
set search_path to 'public'
as $$
  select p_user is not null and p_me is not null and p_user <> p_me
    and exists (select 1 from public.profiles p where p.id = p_user and not coalesce(p.is_deleted, false) and not coalesce(p.banned, false) and not coalesce(p.is_bot, false))
    and not public.zchat_blocked_pair(p_me, p_user)
    and (public.zchat_follows(p_me, p_user) or public.zchat_follows(p_user, p_me))
$$;

create or replace function public.zchat_shared_invite(p_shared uuid, p_people uuid[], p_group uuid)
returns integer
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  s public.zchat_shared_stories;
  u uuid;
  n integer := 0;
  total integer;
begin
  select * into s from public.zchat_shared_stories where id = p_shared;
  if not found or s.owner_id <> me then
    raise exception 'Only the person who made it can add people' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtext('zchat_shared_members:' || p_shared::text));
  select count(*) into total from public.zchat_shared_members where shared_id = p_shared;
  for u in select distinct x from unnest(coalesce(p_people, '{}'::uuid[])) x loop
    exit when total >= 101;
    if public.zchat_shared_person_ok(me, u) then
      insert into public.zchat_shared_members (shared_id, user_id, added_by) values (p_shared, u, me) on conflict do nothing;
      if found then
        n := n + 1;
        total := total + 1;
        perform public.zchat_notify(u, me, 'shared_story', null, s.title, jsonb_build_object('shared_id', s.id::text, 'title', s.title));
      end if;
    end if;
  end loop;
  if p_group is not null then
    if not exists (select 1 from public.group_members gm where gm.group_id = p_group and gm.user_id = me) then
      raise exception 'You are not in that group' using errcode = '42501';
    end if;
    for u in
      select gm.user_id from public.group_members gm join public.profiles p on p.id = gm.user_id
      where gm.group_id = p_group and gm.user_id <> me and not coalesce(p.is_bot, false) and not coalesce(p.is_deleted, false) and not coalesce(p.banned, false)
      order by gm.user_id limit 200
    loop
      exit when total >= 101;
      if not public.zchat_blocked_pair(me, u) then
        insert into public.zchat_shared_members (shared_id, user_id, added_by) values (p_shared, u, me) on conflict do nothing;
        if found then
          n := n + 1;
          total := total + 1;
          perform public.zchat_notify(u, me, 'shared_story', null, s.title, jsonb_build_object('shared_id', s.id::text, 'title', s.title));
        end if;
      end if;
    end loop;
  end if;
  return n;
end $$;
revoke execute on function public.zchat_shared_invite(uuid, uuid[], uuid) from public, anon;

create or replace function public.zchat_shared_create(p_title text, p_audience text, p_people uuid[], p_group uuid, p_keep boolean)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  v_title text := left(btrim(coalesce(p_title, '')), 40);
  v_aud text := coalesce(nullif(btrim(coalesce(p_audience, '')), ''), 'members');
  r public.zchat_shared_stories;
  made integer;
  added integer;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  if v_title = '' then
    raise exception 'Give it a name first' using errcode = '22023';
  end if;
  if v_aud not in ('members', 'followers', 'everyone') then
    raise exception 'Pick who can see it' using errcode = '22023';
  end if;
  if p_group is not null and not exists (select 1 from public.group_members gm where gm.group_id = p_group and gm.user_id = me) then
    raise exception 'You are not in that group' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtext('zchat_shared_make:' || me::text));
  select count(*) into made from public.zchat_shared_stories where owner_id = me and created_at > now() - interval '1 day';
  if made >= 10 then
    raise exception 'You made a lot of shared stories today. Try again tomorrow.' using errcode = '54000';
  end if;
  insert into public.zchat_shared_stories (owner_id, title, audience, group_id, keep)
  values (me, v_title, v_aud, p_group, coalesce(p_keep, false)) returning * into r;
  insert into public.zchat_shared_members (shared_id, user_id, added_by) values (r.id, me, me);
  added := public.zchat_shared_invite(r.id, p_people, p_group);
  return jsonb_build_object('ok', true, 'row', to_jsonb(r), 'added', added);
end $$;

create or replace function public.zchat_shared_add(p_shared uuid, p_people uuid[], p_group uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  added integer;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  added := public.zchat_shared_invite(p_shared, p_people, p_group);
  return jsonb_build_object('ok', true, 'added', added);
end $$;

create or replace function public.zchat_shared_remove(p_shared uuid, p_user uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  s public.zchat_shared_stories;
  gone integer;
begin
  select * into s from public.zchat_shared_stories where id = p_shared;
  if me is null or not found then
    raise exception 'This shared story is gone' using errcode = '22023';
  end if;
  if p_user is null or p_user = s.owner_id then
    raise exception 'The person who made it can not be removed' using errcode = '22023';
  end if;
  if me <> s.owner_id and me <> p_user then
    raise exception 'Only the person who made it can remove people' using errcode = '42501';
  end if;
  delete from public.zchat_shared_members where shared_id = p_shared and user_id = p_user;
  delete from public.stories where shared_id = p_shared and user_id = p_user;
  get diagnostics gone = row_count;
  return jsonb_build_object('ok', true, 'clips', gone);
end $$;

create or replace function public.zchat_shared_update(p_shared uuid, p_title text, p_audience text, p_keep boolean)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  s public.zchat_shared_stories;
  v_title text := nullif(left(btrim(coalesce(p_title, '')), 40), '');
begin
  select * into s from public.zchat_shared_stories where id = p_shared;
  if me is null or not found or s.owner_id <> me then
    raise exception 'Only the person who made it can change it' using errcode = '42501';
  end if;
  if p_audience is not null and p_audience not in ('members', 'followers', 'everyone') then
    raise exception 'Pick who can see it' using errcode = '22023';
  end if;
  update public.zchat_shared_stories
  set title = coalesce(v_title, title), audience = coalesce(p_audience, audience), keep = coalesce(p_keep, keep)
  where id = p_shared returning * into s;
  return jsonb_build_object('ok', true, 'row', to_jsonb(s));
end $$;

revoke execute on function public.zchat_shared_create(text, text, uuid[], uuid, boolean) from public, anon;
revoke execute on function public.zchat_shared_add(uuid, uuid[], uuid) from public, anon;
revoke execute on function public.zchat_shared_remove(uuid, uuid) from public, anon;
revoke execute on function public.zchat_shared_update(uuid, text, text, boolean) from public, anon;
