grant execute on function public.zchat_shared_add(uuid, uuid[], uuid) to authenticated;
grant execute on function public.zchat_shared_remove(uuid, uuid) to authenticated;
grant execute on function public.zchat_shared_update(uuid, text, text, boolean) to authenticated;

