create or replace function public.zchat_place_ok(p jsonb)
returns boolean
language plpgsql
immutable
as $$
begin
  if p is null then
    return true;
  end if;
  if jsonb_typeof(p) <> 'object' or pg_column_size(p) > 1500 then
    return false;
  end if;
  if coalesce(jsonb_typeof(p -> 'lat'), '') <> 'number' or coalesce(jsonb_typeof(p -> 'lng'), '') <> 'number' or coalesce(jsonb_typeof(p -> 'n'), '') <> 'string' then
    return false;
  end if;
  if (p ->> 'lat')::float8 not between -90 and 90 or (p ->> 'lng')::float8 not between -180 and 180 then
    return false;
  end if;
  if char_length(btrim(p ->> 'n')) not between 1 and 80 then
    return false;
  end if;
  if p ? 'a' and (jsonb_typeof(p -> 'a') <> 'string' or char_length(p ->> 'a') > 120) then
    return false;
  end if;
  if p ? 'k' and (jsonb_typeof(p -> 'k') <> 'string' or char_length(p ->> 'k') > 20) then
    return false;
  end if;
  return true;
end $$;

alter table public.stories add column if not exists place jsonb;
alter table public.posts add column if not exists place jsonb;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'zchat_stories_place_ok') then
    alter table public.stories add constraint zchat_stories_place_ok check (public.zchat_place_ok(place));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'zchat_posts_place_ok') then
    alter table public.posts add constraint zchat_posts_place_ok check (public.zchat_place_ok(place));
  end if;
end $$;

create index if not exists zchat_posts_place on public.posts ((((place ->> 'lat'))::float8), (((place ->> 'lng'))::float8)) where place is not null;
create index if not exists zchat_stories_place on public.stories ((((place ->> 'lat'))::float8), (((place ->> 'lng'))::float8)) where place is not null;

create or replace function public.zchat_place_feed(p_lat double precision, p_lng double precision, p_km double precision)
returns jsonb
language plpgsql
stable
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  km double precision := least(greatest(coalesce(p_km, 0.4), 0.05), 25);
  dlat double precision;
  dlng double precision;
  out_posts jsonb;
  out_stories jsonb;
begin
  if me is null or p_lat is null or p_lng is null or p_lat not between -90 and 90 or p_lng not between -180 and 180 then
    return jsonb_build_object('posts', '[]'::jsonb, 'stories', '[]'::jsonb);
  end if;
  dlat := km / 111.0;
  dlng := km / greatest(0.01, 111.0 * cos(radians(p_lat)));
  select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc), '[]'::jsonb) into out_posts from (
    select p.id, p.user_id, p.media_url, p.media_type, p.media_urls, p.caption, p.created_at, p.place, p.sensitive
    from public.posts p
    where p.place is not null
      and ((p.place ->> 'lat'))::float8 between p_lat - dlat and p_lat + dlat
      and ((p.place ->> 'lng'))::float8 between p_lng - dlng and p_lng + dlng
      and (p.user_id = me or public.zchat_follows(me, p.user_id))
    order by p.created_at desc
    limit 60
  ) x;
  select coalesce(jsonb_agg(to_jsonb(y) order by y.created_at desc), '[]'::jsonb) into out_stories from (
    select s.id, s.user_id, s.media_url, s.media_type, s.overlay_url, s.caption, s.created_at, s.expires_at, s.place
    from public.stories s
    where s.place is not null
      and s.shared_id is null
      and coalesce(s.audience, 'all') = 'all'
      and s.expires_at > now()
      and ((s.place ->> 'lat'))::float8 between p_lat - dlat and p_lat + dlat
      and ((s.place ->> 'lng'))::float8 between p_lng - dlng and p_lng + dlng
      and (s.user_id = me or public.zchat_follows(me, s.user_id))
    order by s.created_at desc
    limit 60
  ) y;
  return jsonb_build_object('posts', out_posts, 'stories', out_stories);
end $$;
revoke execute on function public.zchat_place_feed(double precision, double precision, double precision) from public, anon;
grant execute on function public.zchat_place_feed(double precision, double precision, double precision) to authenticated;

create or replace function public.zchat_post_place(p_post uuid, p_place jsonb)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  n integer;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  if p_place is not null and not public.zchat_place_ok(p_place) then
    raise exception 'That place can not be used' using errcode = '22023';
  end if;
  update public.posts
  set place = p_place,
      location = case when p_place is null then location else left(btrim(p_place ->> 'n'), 120) end
  where id = p_post and user_id = me;
  get diagnostics n = row_count;
  if n = 0 then
    raise exception 'That post is not yours' using errcode = '42501';
  end if;
  return jsonb_build_object('ok', true);
end $$;
revoke execute on function public.zchat_post_place(uuid, jsonb) from public, anon;
grant execute on function public.zchat_post_place(uuid, jsonb) to authenticated;
commit;

begin;
create table if not exists public.zchat_booths (
  id uuid primary key default gen_random_uuid(),
  chat_key text not null,
  created_by uuid not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  join_until timestamptz not null,
  shoot_at timestamptz not null,
  status text not null default 'open',
  constraint zchat_booths_key check (chat_key ~ '^(g:[0-9a-f-]{36}|dm:[0-9a-f-]{36}:[0-9a-f-]{36})$'),
  constraint zchat_booths_status check (status in ('open', 'cancelled'))
);
create index if not exists zchat_booths_chat on public.zchat_booths (chat_key, created_at desc);
create index if not exists zchat_booths_maker on public.zchat_booths (created_by, created_at desc);

create table if not exists public.zchat_booth_people (
  booth_id uuid not null references public.zchat_booths(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  joined_at timestamptz not null default now(),
  cam boolean not null default true,
  photo_url text,
  primary key (booth_id, user_id),
  constraint zchat_booth_people_photo check (photo_url is null or (char_length(photo_url) <= 600 and public.zchat_url_ok(photo_url)))
);

alter table public.zchat_booths enable row level security;
alter table public.zchat_booth_people enable row level security;
drop policy if exists "zchat booths read" on public.zchat_booths;
create policy "zchat booths read" on public.zchat_booths for select to authenticated using (public.zchat_in_chat(chat_key));
drop policy if exists "zchat booth people read" on public.zchat_booth_people;
create policy "zchat booth people read" on public.zchat_booth_people for select to authenticated
  using (exists (select 1 from public.zchat_booths b where b.id = zchat_booth_people.booth_id and public.zchat_in_chat(b.chat_key)));
revoke all on table public.zchat_booths from anon;
revoke all on table public.zchat_booth_people from anon;
revoke insert, update, delete, truncate, references, trigger on table public.zchat_booths from authenticated;
revoke insert, update, delete, truncate, references, trigger on table public.zchat_booth_people from authenticated;
grant select on table public.zchat_booths to authenticated;
grant select on table public.zchat_booth_people to authenticated;

create or replace function public.zchat_booth_view(p_booth uuid)
returns jsonb
language sql
volatile security definer
set search_path to 'public'
as $$
  select to_jsonb(b) || jsonb_build_object(
    'now', clock_timestamp(),
    'people', coalesce((
      select jsonb_agg(jsonb_build_object('user_id', p.user_id, 'joined_at', p.joined_at, 'cam', p.cam, 'photo_url', p.photo_url) order by p.joined_at, p.user_id)
      from public.zchat_booth_people p where p.booth_id = b.id
    ), '[]'::jsonb))
  from public.zchat_booths b where b.id = p_booth
$$;
revoke execute on function public.zchat_booth_view(uuid) from public, anon;

create or replace function public.zchat_booth_other(p_key text, p_me uuid)
returns uuid
language sql
immutable
as $$
  select case when p_key like 'dm:%' then public.zchat_try_uuid(case when split_part(p_key, ':', 2) = p_me::text then split_part(p_key, ':', 3) else split_part(p_key, ':', 2) end) else null end
$$;

create or replace function public.zchat_booth_open(p_key text)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  k text := btrim(coalesce(p_key, ''));
  other uuid;
  b public.zchat_booths;
  n integer;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  if k !~ '^(g:[0-9a-f-]{36}|dm:[0-9a-f-]{36}:[0-9a-f-]{36})$' or not public.zchat_in_chat(k) then
    raise exception 'You are not in this chat' using errcode = '42501';
  end if;
  if k like 'dm:%' then
    other := public.zchat_booth_other(k, me);
    if other is null or other = me or public.zchat_blocked_pair(me, other) then
      raise exception 'You can not open a photo booth here' using errcode = '42501';
    end if;
    if not exists (select 1 from public.conversations c where (c.user_a = me and c.user_b = other) or (c.user_a = other and c.user_b = me)) then
      raise exception 'Say hi first, then open the photo booth' using errcode = '42501';
    end if;
  end if;
  perform pg_advisory_xact_lock(hashtext('zchat_booth:' || k));
  select * into b from public.zchat_booths where chat_key = k and status = 'open' and join_until > now() order by created_at desc limit 1;
  if found then
    select count(*) into n from public.zchat_booth_people where booth_id = b.id;
    if n < 6 then
      insert into public.zchat_booth_people (booth_id, user_id) values (b.id, me) on conflict do nothing;
    end if;
    return public.zchat_booth_view(b.id);
  end if;
  select count(*) into n from public.zchat_booths where created_by = me and created_at > now() - interval '1 hour';
  if n >= 12 then
    raise exception 'That is a lot of photo booths. Try again in a little while.' using errcode = '54000';
  end if;
  delete from public.zchat_booths where chat_key = k and created_at < now() - interval '1 day';
  insert into public.zchat_booths (chat_key, created_by, join_until, shoot_at)
  values (k, me, now() + interval '30 seconds', now() + interval '34 seconds') returning * into b;
  insert into public.zchat_booth_people (booth_id, user_id) values (b.id, me);
  return public.zchat_booth_view(b.id);
end $$;

create or replace function public.zchat_booth_join(p_booth uuid, p_cam boolean)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  b public.zchat_booths;
  n integer;
begin
  if me is null then
    raise exception 'Log in first' using errcode = '42501';
  end if;
  select * into b from public.zchat_booths where id = p_booth;
  if not found or not public.zchat_in_chat(b.chat_key) then
    raise exception 'This photo booth is not here anymore' using errcode = '22023';
  end if;
  if exists (select 1 from public.zchat_booth_people where booth_id = b.id and user_id = me) then
    update public.zchat_booth_people set cam = coalesce(p_cam, cam) where booth_id = b.id and user_id = me;
    return public.zchat_booth_view(b.id);
  end if;
  if b.status <> 'open' or b.join_until <= now() then
    raise exception 'This photo booth already closed' using errcode = '22023';
  end if;
  if public.zchat_blocked_pair(me, b.created_by) then
    raise exception 'You can not join this photo booth' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtext('zchat_booth_join:' || b.id::text));
  select count(*) into n from public.zchat_booth_people where booth_id = b.id;
  if n >= 6 then
    raise exception 'This photo booth is full' using errcode = '54000';
  end if;
  insert into public.zchat_booth_people (booth_id, user_id, cam) values (b.id, me, coalesce(p_cam, true));
  return public.zchat_booth_view(b.id);
end $$;

create or replace function public.zchat_booth_start(p_booth uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  b public.zchat_booths;
  n integer;
begin
  select * into b from public.zchat_booths where id = p_booth for update;
  if me is null or not found or b.created_by <> me then
    raise exception 'Only the person who opened it can start it' using errcode = '42501';
  end if;
  if b.status <> 'open' then
    raise exception 'This photo booth already closed' using errcode = '22023';
  end if;
  if b.join_until > now() then
    select count(*) into n from public.zchat_booth_people where booth_id = b.id;
    if n < 2 then
      raise exception 'Wait for someone to join first' using errcode = '22023';
    end if;
    update public.zchat_booths set join_until = now(), shoot_at = now() + interval '4 seconds' where id = b.id;
  end if;
  return public.zchat_booth_view(b.id);
end $$;

create or replace function public.zchat_booth_shot(p_booth uuid, p_url text)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  b public.zchat_booths;
  u text := btrim(coalesce(p_url, ''));
begin
  select * into b from public.zchat_booths where id = p_booth;
  if me is null or not found or not exists (select 1 from public.zchat_booth_people where booth_id = b.id and user_id = me) then
    raise exception 'You are not in this photo booth' using errcode = '42501';
  end if;
  if b.status <> 'open' or now() < b.shoot_at - interval '3 seconds' or now() > b.shoot_at + interval '3 minutes' then
    raise exception 'The photo booth is not taking photos right now' using errcode = '22023';
  end if;
  if u = '' or char_length(u) > 600 or u !~* '^https://' or position(('/' || me::text || '/') in u) = 0 or not public.zchat_url_ok(u) then
    raise exception 'That photo did not upload. Try again.' using errcode = '22023';
  end if;
  update public.zchat_booth_people set photo_url = u where booth_id = b.id and user_id = me;
  return public.zchat_booth_view(b.id);
end $$;

create or replace function public.zchat_booth_leave(p_booth uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  b public.zchat_booths;
begin
  select * into b from public.zchat_booths where id = p_booth;
  if me is null or not found then
    return jsonb_build_object('ok', true);
  end if;
  if b.shoot_at > now() then
    if b.created_by = me then
      update public.zchat_booths set status = 'cancelled' where id = b.id;
    else
      delete from public.zchat_booth_people where booth_id = b.id and user_id = me;
    end if;
  end if;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.zchat_booth_state(p_booth uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  b public.zchat_booths;
begin
  select * into b from public.zchat_booths where id = p_booth;
  if auth.uid() is null or not found or not public.zchat_in_chat(b.chat_key) then
    return null;
  end if;
  return public.zchat_booth_view(b.id);
end $$;

