insert into public.zchat_safety_config (k, v) values ('push_url', 'https://etcmbghcmlgeezwgnwuz.supabase.co/functions/v1/hyper-worker') on conflict (k) do nothing;

create table if not exists public.zchat_safety_push (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  actor_id uuid references auth.users(id) on delete cascade,
  kind text not null check (kind in ('safety_alert', 'safety_check', 'recovery_help', 'recovery_notice', 'recovery_denied', 'data_ready')),
  title text not null check (char_length(title) <= 80),
  body text not null default '' check (char_length(body) <= 200),
  url text not null default '/' check (url like '/%' and url not like '//%' and char_length(url) <= 300),
  tag text check (tag is null or tag ~ '^[A-Za-z][A-Za-z0-9-]{0,99}$'),
  created_at timestamptz not null default now(),
  sent_at timestamptz,
  tries integer not null default 0
);
create index if not exists zchat_safety_push_due on public.zchat_safety_push (created_at) where sent_at is null;
alter table public.zchat_safety_push enable row level security;
revoke all on public.zchat_safety_push from public, anon, authenticated;
grant all on public.zchat_safety_push to service_role;

create or replace function public.zchat_safety_queue(p_user uuid, p_actor uuid, p_kind text, p_title text, p_body text, p_url text, p_tag text)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_user is null or p_kind is null then
    return;
  end if;
  if p_actor is not null and (p_actor = p_user or public.zchat_blocked_pair(p_user, p_actor)) then
    return;
  end if;
  if (select count(*) from public.zchat_safety_push q where q.user_id = p_user and q.created_at > now() - interval '1 hour') >= 40 then
    return;
  end if;
  insert into public.zchat_safety_push (user_id, actor_id, kind, title, body, url, tag)
  values (p_user, p_actor, p_kind, left(coalesce(nullif(btrim(p_title), ''), 'ZChat'), 80), left(coalesce(p_body, ''), 200),
    coalesce(p_url, '/') || case when position('?' in coalesce(p_url, '/')) > 0 then '&' else '?' end || 'acc=' || p_user::text, p_tag);
exception when others then
  raise notice 'zchat safety queue skipped: %', sqlerrm;
end $$;
revoke all on function public.zchat_safety_queue(uuid, uuid, text, text, text, text, text) from public, anon, authenticated;
grant execute on function public.zchat_safety_queue(uuid, uuid, text, text, text, text, text) to service_role;

create or replace function public.zchat_safety_kick()
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_url text;
  v_secret text;
  v_auth text;
  h jsonb;
  took boolean;
begin
  if not exists (select 1 from public.zchat_safety_push q where q.sent_at is null and q.created_at > now() - interval '2 hours' and q.tries < 3) then
    return false;
  end if;
  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'net' and p.proname = 'http_post') then
    return false;
  end if;
  select c.v into v_url from public.zchat_safety_config c where c.k = 'push_url';
  select c.v into v_secret from public.zchat_safety_config c where c.k = 'push_secret';
  select c.v into v_auth from public.zchat_safety_config c where c.k = 'push_auth';
  if v_url is null or v_url !~ '^https://' or v_secret is null then
    return false;
  end if;
  insert into public.zchat_safety_config as c (k, v, updated_at) values ('last_kick', now()::text, now())
  on conflict (k) do update set v = excluded.v, updated_at = now() where c.updated_at < now() - interval '10 seconds'
  returning true into took;
  if took is not true then
    return false;
  end if;
  h := jsonb_build_object('Content-Type', 'application/json', 'x-zchat-safety', v_secret);
  if v_auth is not null and btrim(v_auth) <> '' then
    h := h || jsonb_build_object('Authorization', 'Bearer ' || btrim(v_auth), 'apikey', btrim(v_auth));
  end if;
  execute 'select net.http_post(url := $1, body := $2, headers := $3, timeout_milliseconds := 8000)' using v_url, '{"mode":"safety"}'::jsonb, h;
  return true;
exception when others then
  raise notice 'zchat safety kick skipped: %', sqlerrm;
  return false;
end $$;
revoke all on function public.zchat_safety_kick() from public, anon, authenticated;
grant execute on function public.zchat_safety_kick() to service_role;

create or replace function public.zchat_safety_push_claim(p_secret text, p_limit integer default 40)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_secret text;
  r record;
  subs jsonb;
  items jsonb := '[]'::jsonb;
begin
  select c.v into v_secret from public.zchat_safety_config c where c.k = 'push_secret';
  if v_secret is null or p_secret is null or length(p_secret) <> length(v_secret) or p_secret <> v_secret then
    return jsonb_build_object('ok', false);
  end if;
  for r in
    update public.zchat_safety_push q set sent_at = now(), tries = q.tries + 1
    where q.id in (
      select q2.id from public.zchat_safety_push q2
      where q2.sent_at is null and q2.created_at > now() - interval '2 hours' and q2.tries < 3
      order by q2.created_at
      limit greatest(1, least(coalesce(p_limit, 40), 100))
      for update skip locked
    )
    returning q.*
  loop
    if r.actor_id is not null and public.zchat_blocked_pair(r.user_id, r.actor_id) then
      continue;
    end if;
    select coalesce(jsonb_agg(jsonb_build_object('endpoint', s.endpoint, 'p256dh', s.p256dh, 'auth', s.auth)), '[]'::jsonb)
      into subs
      from (
        select ps.endpoint, ps.p256dh, ps.auth from public.push_subscriptions ps
        where ps.user_id = r.user_id and ps.sw >= 1 and ps.endpoint is not null
        order by ps.seen_at desc nulls last, ps.id
        limit 10
      ) s;
    if jsonb_array_length(subs) = 0 then
      continue;
    end if;
    items := items || jsonb_build_array(jsonb_build_object('id', r.id, 'user_id', r.user_id, 'kind', r.kind, 'title', r.title, 'body', r.body, 'url', r.url, 'tag', r.tag, 'subs', subs));
  end loop;
  return jsonb_build_object('ok', true, 'items', items);
end $$;
revoke all on function public.zchat_safety_push_claim(text, integer) from public, anon, authenticated;
grant execute on function public.zchat_safety_push_claim(text, integer) to service_role;

select public.zchat_apply_session_gate();
commit;

begin;
create table if not exists public.zchat_safety_timers (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users(id) on delete cascade,
  label text not null default '' check (char_length(label) <= 80),
  friends uuid[] not null check (cardinality(friends) between 1 and 5),
  minutes integer not null check (minutes between 1 and 720),
  started_at timestamptz not null default now(),
  ends_at timestamptz not null,
  status text not null default 'running' check (status in ('running', 'safe', 'alerted', 'closed')),
  lat double precision check (lat between -90 and 90),
  lng double precision check (lng between -180 and 180),
  acc real,
  loc_at timestamptz,
  extended integer not null default 0,
  alerted_at timestamptz,
  ended_at timestamptz,
  updated_at timestamptz not null default now()
);
create index if not exists zchat_safety_timers_owner on public.zchat_safety_timers (owner_id, started_at desc);
create index if not exists zchat_safety_timers_due on public.zchat_safety_timers (ends_at) where status = 'running';
create index if not exists zchat_safety_timers_friends on public.zchat_safety_timers using gin (friends);
alter table public.zchat_safety_timers enable row level security;
revoke all on public.zchat_safety_timers from public, anon, authenticated;
grant select on public.zchat_safety_timers to authenticated;
grant all on public.zchat_safety_timers to service_role;
drop policy if exists "zchat safety owner" on public.zchat_safety_timers;
create policy "zchat safety owner" on public.zchat_safety_timers for select to authenticated using (owner_id = (select auth.uid()));
drop policy if exists "zchat safety friends" on public.zchat_safety_timers;
create policy "zchat safety friends" on public.zchat_safety_timers for select to authenticated using (
  (select auth.uid()) = any (friends)
  and (status in ('running', 'alerted') or ended_at > now() - interval '10 minutes')
  and not public.zchat_blocked_pair(owner_id, (select auth.uid()))
);

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'zchat_safety_timers') then
    execute 'alter publication supabase_realtime add table public.zchat_safety_timers';
  end if;
end $$;

create or replace function public.zchat_safety_friend_ok(p_owner uuid, p_friend uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select p_owner is not null and p_friend is not null and p_owner <> p_friend
    and exists (select 1 from public.profiles p where p.id = p_friend and not coalesce(p.is_deleted, false) and not coalesce(p.banned, false) and not coalesce(p.is_bot, false))
    and public.zchat_follows(p_owner, p_friend) and public.zchat_follows(p_friend, p_owner)
    and not public.zchat_blocked_pair(p_owner, p_friend)
$$;
revoke all on function public.zchat_safety_friend_ok(uuid, uuid) from public, anon, authenticated;
grant execute on function public.zchat_safety_friend_ok(uuid, uuid) to service_role;

create or replace function public.zchat_safety_start(p_minutes integer, p_label text, p_friends uuid[], p_lat double precision default null, p_lng double precision default null, p_acc real default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  v_friends uuid[];
  f uuid;
  n integer;
  v_label text;
  v_id uuid;
  v_ends timestamptz;
  v_loc boolean;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'auth');
  end if;
  if exists (select 1 from public.profiles p where p.id = me and (coalesce(p.banned, false) or coalesce(p.is_deleted, false))) then
    return jsonb_build_object('ok', false, 'reason', 'auth');
  end if;
  if p_minutes is null or p_minutes < 5 or p_minutes > 720 then
    return jsonb_build_object('ok', false, 'reason', 'minutes');
  end if;
  select array_agg(distinct x) into v_friends from unnest(coalesce(p_friends, '{}'::uuid[])) as x where x is not null and x <> me;
  if v_friends is null or cardinality(v_friends) < 1 or cardinality(v_friends) > 5 then
    return jsonb_build_object('ok', false, 'reason', 'friends');
  end if;
  foreach f in array v_friends loop
    if not public.zchat_safety_friend_ok(me, f) then
      return jsonb_build_object('ok', false, 'reason', 'friend', 'id', f);
    end if;
  end loop;
  perform pg_advisory_xact_lock(hashtextextended('zchat_safety:' || me::text, 0));
  if exists (select 1 from public.zchat_safety_timers t where t.owner_id = me and t.status = 'running' and t.ends_at > now()) then
    return jsonb_build_object('ok', false, 'reason', 'running');
  end if;
  select count(*) into n from public.zchat_safety_timers t where t.owner_id = me and t.started_at > now() - interval '1 day';
  if n >= 12 then
    return jsonb_build_object('ok', false, 'reason', 'limited');
  end if;
  update public.zchat_safety_timers
    set status = 'safe', ended_at = now(), lat = null, lng = null, acc = null, loc_at = null, updated_at = now()
    where owner_id = me and status in ('running', 'alerted');
  v_label := left(btrim(regexp_replace(coalesce(p_label, ''), '[[:cntrl:]]+', ' ', 'g')), 80);
  v_ends := now() + make_interval(mins => p_minutes);
  v_loc := p_lat is not null and p_lng is not null and p_lat between -90 and 90 and p_lng between -180 and 180;
  insert into public.zchat_safety_timers (owner_id, label, friends, minutes, ends_at, lat, lng, acc, loc_at)
  values (me, v_label, v_friends, p_minutes, v_ends,
    case when v_loc then p_lat end, case when v_loc then p_lng end, case when v_loc then greatest(0, least(coalesce(p_acc, 0), 100000)) end, case when v_loc then now() end)
  returning id into v_id;
  foreach f in array v_friends loop
    perform public.zchat_notify(f, me, 'safety_start', null, nullif(v_label, ''), jsonb_build_object('timer_id', v_id, 'ends_at', v_ends));
  end loop;
  return jsonb_build_object('ok', true, 'id', v_id, 'started_at', now(), 'ends_at', v_ends, 'friends', to_jsonb(v_friends));
end $$;
revoke all on function public.zchat_safety_start(integer, text, uuid[], double precision, double precision, real) from public, anon;
grant execute on function public.zchat_safety_start(integer, text, uuid[], double precision, double precision, real) to authenticated, service_role;

create or replace function public.zchat_safety_loc(p_id uuid, p_lat double precision, p_lng double precision, p_acc real default null)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null or p_id is null or p_lat is null or p_lng is null or p_lat not between -90 and 90 or p_lng not between -180 and 180 then
    return false;
  end if;
  update public.zchat_safety_timers
    set lat = p_lat, lng = p_lng, acc = greatest(0, least(coalesce(p_acc, 0), 100000)), loc_at = now(), updated_at = now()
    where id = p_id and owner_id = auth.uid() and status = 'running' and ends_at > now()
      and (loc_at is null or loc_at < now() - interval '8 seconds');
  return found;
end $$;
revoke all on function public.zchat_safety_loc(uuid, double precision, double precision, real) from public, anon;
grant execute on function public.zchat_safety_loc(uuid, double precision, double precision, real) to authenticated, service_role;

create or replace function public.zchat_safety_extend(p_id uuid, p_minutes integer)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  t public.zchat_safety_timers%rowtype;
  f uuid;
  was text;
begin
  if me is null or p_id is null then
    return jsonb_build_object('ok', false, 'reason', 'auth');
  end if;
  if p_minutes is null or p_minutes < 5 or p_minutes > 120 then
    return jsonb_build_object('ok', false, 'reason', 'minutes');
  end if;
  select * into t from public.zchat_safety_timers where id = p_id and owner_id = me for update;
  if not found or t.status not in ('running', 'alerted') then
    return jsonb_build_object('ok', false, 'reason', 'ended');
  end if;
  if t.extended >= 8 or t.minutes + p_minutes > 720 then
    return jsonb_build_object('ok', false, 'reason', 'limit');
  end if;
  was := t.status;
  update public.zchat_safety_timers
    set ends_at = greatest(ends_at, now()) + make_interval(mins => p_minutes), minutes = minutes + p_minutes, extended = extended + 1,
        status = 'running', alerted_at = null, updated_at = now()
    where id = p_id
    returning * into t;
  if was = 'alerted' then
    foreach f in array t.friends loop
      perform public.zchat_notify(f, me, 'safety_ok', null, nullif(t.label, ''), jsonb_build_object('timer_id', t.id, 'more', true));
    end loop;
  end if;
  return jsonb_build_object('ok', true, 'ends_at', t.ends_at, 'was', was);
end $$;
revoke all on function public.zchat_safety_extend(uuid, integer) from public, anon;
grant execute on function public.zchat_safety_extend(uuid, integer) to authenticated, service_role;

create or replace function public.zchat_safety_end(p_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  t public.zchat_safety_timers%rowtype;
  f uuid;
  was text;
begin
  if me is null or p_id is null then
    return jsonb_build_object('ok', false, 'reason', 'auth');
  end if;
  select * into t from public.zchat_safety_timers where id = p_id and owner_id = me for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'missing');
  end if;
  was := t.status;
  if was not in ('running', 'alerted') then
    return jsonb_build_object('ok', true, 'was', was);
  end if;
  update public.zchat_safety_timers
    set status = 'safe', ended_at = now(), lat = null, lng = null, acc = null, loc_at = null, updated_at = now()
    where id = p_id;
  if was = 'alerted' then
    foreach f in array t.friends loop
      perform public.zchat_notify(f, me, 'safety_ok', null, nullif(t.label, ''), jsonb_build_object('timer_id', t.id));
    end loop;
  end if;
  return jsonb_build_object('ok', true, 'was', was);
end $$;
revoke all on function public.zchat_safety_end(uuid) from public, anon;
grant execute on function public.zchat_safety_end(uuid) to authenticated, service_role;

create or replace function public.zchat_safety_tick()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  r record;
  f uuid;
  n integer := 0;
  v_name text;
begin
  for r in
    update public.zchat_safety_timers t set status = 'alerted', alerted_at = now(), updated_at = now()
    where t.id in (
      select t2.id from public.zchat_safety_timers t2
      where t2.status = 'running' and t2.ends_at <= now()
      order by t2.ends_at
      limit 200
      for update skip locked
    )
    returning t.*
  loop
    begin
      select left(coalesce(nullif(btrim(p.name), ''), p.username, 'Your friend'), 40) into v_name from public.profiles p where p.id = r.owner_id;
      foreach f in array r.friends loop
        if public.zchat_blocked_pair(r.owner_id, f) then
          continue;
        end if;
        perform public.zchat_notify(f, r.owner_id, 'safety_alert', null, nullif(r.label, ''), jsonb_build_object('timer_id', r.id));
        perform public.zchat_safety_queue(f, r.owner_id, 'safety_alert', coalesce(v_name, 'Your friend') || ' has not checked in',
          'Their safety timer ran out. Tap to see where they were and call them.', '/?safety=' || r.id, 'safety-' || r.id);
      end loop;
      perform public.zchat_notify(r.owner_id, null, 'safety_check', null, nullif(r.label, ''), jsonb_build_object('timer_id', r.id));
      perform public.zchat_safety_queue(r.owner_id, null, 'safety_check', 'Are you okay?',
        'Your safety timer ran out and your friends were told. Tap I''m safe to let them know.', '/?safety=' || r.id, 'safety-' || r.id);
      n := n + 1;
    exception when others then
      raise notice 'zchat safety tick skipped: %', sqlerrm;
    end;
  end loop;
  update public.zchat_safety_timers
    set status = 'closed', ended_at = now(), lat = null, lng = null, acc = null, loc_at = null, updated_at = now()
    where status = 'alerted' and alerted_at < now() - interval '24 hours';
  update public.zchat_safety_timers
    set lat = null, lng = null, acc = null, loc_at = null
    where status in ('safe', 'closed') and (lat is not null or lng is not null);
  delete from public.zchat_safety_timers where status in ('safe', 'closed') and coalesce(ended_at, ends_at) < now() - interval '30 days';
  delete from public.zchat_safety_push where created_at < now() - interval '3 days';
  perform public.zchat_safety_kick();
  return n;
end $$;
revoke all on function public.zchat_safety_tick() from public, anon, authenticated;
grant execute on function public.zchat_safety_tick() to service_role;

do $$
begin
  if exists (select 1 from pg_namespace where nspname = 'cron') then
    if not exists (select 1 from cron.job where jobname = 'zchat-safety') then
      perform cron.schedule('zchat-safety', '* * * * *', 'select public.zchat_safety_tick()');
    end if;
  end if;
exception when others then
  raise notice 'zchat safety: the minute job was not scheduled: %', sqlerrm;
end $$;

select public.zchat_apply_session_gate();
commit;

begin;
create table if not exists public.zchat_trusted_friends (
  owner_id uuid not null references auth.users(id) on delete cascade,
  friend_id uuid not null references auth.users(id) on delete cascade,
  added_at timestamptz not null default now(),
  primary key (owner_id, friend_id),
  check (owner_id <> friend_id)
);
create index if not exists zchat_trusted_friends_friend on public.zchat_trusted_friends (friend_id);
alter table public.zchat_trusted_friends enable row level security;
revoke all on public.zchat_trusted_friends from public, anon, authenticated;
grant select on public.zchat_trusted_friends to authenticated;
grant all on public.zchat_trusted_friends to service_role;
drop policy if exists "zchat trusted own" on public.zchat_trusted_friends;
create policy "zchat trusted own" on public.zchat_trusted_friends for select to authenticated using (owner_id = (select auth.uid()) or friend_id = (select auth.uid()));

create table if not exists public.zchat_recovery_requests (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  secret_hash text not null check (secret_hash ~ '^[0-9a-f]{64}$'),
  status text not null default 'open' check (status in ('open', 'verified', 'waiting', 'done', 'cancelled', 'denied', 'expired', 'locked')),
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  verified_at timestamptz,
  new_email text,
  apply_after timestamptz,
  cancel_hash text,
  fails integer not null default 0,
  ip text,
  place text,
  device text,
  denied_by uuid,
  ended_at timestamptz
);
create index if not exists zchat_recovery_requests_user on public.zchat_recovery_requests (user_id, created_at desc);
create index if not exists zchat_recovery_requests_cancel on public.zchat_recovery_requests (cancel_hash) where cancel_hash is not null;
alter table public.zchat_recovery_requests enable row level security;
revoke all on public.zchat_recovery_requests from public, anon, authenticated;
grant all on public.zchat_recovery_requests to service_role;

create table if not exists public.zchat_recovery_codes (
  request_id uuid not null references public.zchat_recovery_requests(id) on delete cascade,
  friend_id uuid not null references auth.users(id) on delete cascade,
  code_hash text,
  shows integer not null default 0,
  shown_at timestamptz,
  used_at timestamptz,
  denied_at timestamptz,
  primary key (request_id, friend_id)
);
create index if not exists zchat_recovery_codes_friend on public.zchat_recovery_codes (friend_id);
alter table public.zchat_recovery_codes enable row level security;
revoke all on public.zchat_recovery_codes from public, anon, authenticated;
grant all on public.zchat_recovery_codes to service_role;

create table if not exists public.zchat_recovery_log (
  id bigint generated always as identity primary key,
  user_id uuid references auth.users(id) on delete cascade,
  request_id uuid,
  event text not null,
  actor uuid,
  ip text,
  at timestamptz not null default now()
);
create index if not exists zchat_recovery_log_user on public.zchat_recovery_log (user_id, at desc);
alter table public.zchat_recovery_log enable row level security;
revoke all on public.zchat_recovery_log from public, anon, authenticated;
grant select on public.zchat_recovery_log to authenticated;
grant all on public.zchat_recovery_log to service_role;
drop policy if exists "zchat recovery log own" on public.zchat_recovery_log;
create policy "zchat recovery log own" on public.zchat_recovery_log for select to authenticated using (user_id = (select auth.uid()));

create table if not exists public.zchat_recovery_tries (
  id bigint generated always as identity primary key,
  ip text not null,
  kind text not null,
  at timestamptz not null default now()
);
create index if not exists zchat_recovery_tries_ip on public.zchat_recovery_tries (ip, kind, at);
alter table public.zchat_recovery_tries enable row level security;
revoke all on public.zchat_recovery_tries from public, anon, authenticated;
grant all on public.zchat_recovery_tries to service_role;

create table if not exists public.zchat_recovery_locks (
  user_id uuid primary key references auth.users(id) on delete cascade,
  until timestamptz not null
);
alter table public.zchat_recovery_locks enable row level security;
revoke all on public.zchat_recovery_locks from public, anon, authenticated;
grant all on public.zchat_recovery_locks to service_role;

create or replace function public.zchat_rec_log(p_user uuid, p_request uuid, p_event text, p_actor uuid, p_ip text)
returns void
language sql
security definer
set search_path = public
as $$
  insert into public.zchat_recovery_log (user_id, request_id, event, actor, ip) values (p_user, p_request, left(p_event, 40), p_actor, left(p_ip, 64));
$$;
revoke all on function public.zchat_rec_log(uuid, uuid, text, uuid, text) from public, anon, authenticated;
grant execute on function public.zchat_rec_log(uuid, uuid, text, uuid, text) to service_role;

create or replace function public.zchat_rec_lock(p_user uuid, p_hours integer)
returns void
language sql
security definer
set search_path = public
as $$
  insert into public.zchat_recovery_locks (user_id, until) values (p_user, now() + make_interval(hours => p_hours))
  on conflict (user_id) do update set until = greatest(public.zchat_recovery_locks.until, excluded.until);
$$;
revoke all on function public.zchat_rec_lock(uuid, integer) from public, anon, authenticated;
grant execute on function public.zchat_rec_lock(uuid, integer) to service_role;

create or replace function public.zchat_trusted_list()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'friends', coalesce((
      select jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name, 'username', p.username, 'avatar', case when coalesce(p.hide_photo, false) then null else p.avatar end,
        'added_at', t.added_at, 'ready_at', t.added_at + interval '3 days', 'ok', public.zchat_safety_friend_ok(t.owner_id, t.friend_id)) order by t.added_at)
      from public.zchat_trusted_friends t join public.profiles p on p.id = t.friend_id
      where t.owner_id = auth.uid()
    ), '[]'::jsonb),
    'requests', coalesce((
      select jsonb_agg(jsonb_build_object('id', r.id, 'status', r.status, 'created_at', r.created_at, 'apply_after', r.apply_after, 'place', r.place, 'device', r.device) order by r.created_at desc)
      from public.zchat_recovery_requests r
      where r.user_id = auth.uid() and r.status in ('open', 'verified', 'waiting') and (r.status <> 'open' or r.expires_at > now())
    ), '[]'::jsonb)
  )
  where auth.uid() is not null;
$$;
revoke all on function public.zchat_trusted_list() from public, anon;
grant execute on function public.zchat_trusted_list() to authenticated, service_role;

create or replace function public.zchat_trusted_set(p_friends uuid[])
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  v_new uuid[];
  f uuid;
  n integer;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'auth');
  end if;
  select coalesce(array_agg(distinct x), '{}'::uuid[]) into v_new from unnest(coalesce(p_friends, '{}'::uuid[])) as x where x is not null and x <> me;
  if cardinality(v_new) <> 0 and (cardinality(v_new) < 3 or cardinality(v_new) > 5) then
    return jsonb_build_object('ok', false, 'reason', 'count');
  end if;
  foreach f in array v_new loop
    if not public.zchat_safety_friend_ok(me, f) and not exists (select 1 from public.zchat_trusted_friends t where t.owner_id = me and t.friend_id = f) then
      return jsonb_build_object('ok', false, 'reason', 'friend', 'id', f);
    end if;
  end loop;
  perform pg_advisory_xact_lock(hashtextextended('zchat_trusted:' || me::text, 0));
  select count(*) into n from public.zchat_recovery_log l where l.user_id = me and l.event = 'trusted_set' and l.at > now() - interval '1 day';
  if n >= 8 then
    return jsonb_build_object('ok', false, 'reason', 'limited');
  end if;
  delete from public.zchat_trusted_friends t where t.owner_id = me and not (t.friend_id = any (v_new));
  foreach f in array v_new loop
    insert into public.zchat_trusted_friends (owner_id, friend_id) values (me, f) on conflict do nothing;
    if found then
      perform public.zchat_notify(f, me, 'trusted_added', null, null, jsonb_build_object('by', me));
    end if;
  end loop;
  perform public.zchat_rec_log(me, null, 'trusted_set', me, null);
  return jsonb_build_object('ok', true, 'count', cardinality(v_new));
end $$;
revoke all on function public.zchat_trusted_set(uuid[]) from public, anon;
grant execute on function public.zchat_trusted_set(uuid[]) to authenticated, service_role;

create or replace function public.zchat_rec_start(p_username text, p_secret_hash text, p_ip text, p_device text, p_place text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  pr public.profiles%rowtype;
  v_user text := lower(btrim(ltrim(coalesce(p_username, ''), '@ ')));
  v_ip text := left(coalesce(nullif(btrim(p_ip), ''), 'unknown'), 64);
  v_friends uuid[];
  v_id uuid;
  v_name text;
  f uuid;
  n integer;
begin
  if p_secret_hash is null or p_secret_hash !~ '^[0-9a-f]{64}$' or v_user !~ '^[a-z0-9._]{2,40}$' then
    return jsonb_build_object('ok', false, 'reason', 'input');
  end if;
  select count(*) into n from public.zchat_recovery_tries t where t.ip = v_ip and t.kind = 'start' and t.at > now() - interval '1 hour';
  if n >= 6 then
    return jsonb_build_object('ok', false, 'reason', 'limited');
  end if;
  insert into public.zchat_recovery_tries (ip, kind) values (v_ip, 'start');
  if random() < 0.05 then
    delete from public.zchat_recovery_tries where at < now() - interval '2 days';
  end if;
  select * into pr from public.profiles p where lower(p.username) = v_user and not coalesce(p.is_deleted, false) and not coalesce(p.banned, false) and not coalesce(p.is_bot, false) limit 1;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('zchat_recovery:' || pr.id::text, 0));
  if exists (select 1 from public.zchat_recovery_locks l where l.user_id = pr.id and l.until > now()) then
    return jsonb_build_object('ok', false, 'reason', 'locked');
  end if;
  update public.zchat_recovery_requests set status = 'expired', ended_at = now() where user_id = pr.id and status = 'open' and expires_at <= now();
  if exists (select 1 from public.zchat_recovery_requests r where r.user_id = pr.id and r.status in ('open', 'verified', 'waiting')) then
    return jsonb_build_object('ok', false, 'reason', 'busy');
  end if;
  select count(*) into n from public.zchat_recovery_requests r where r.user_id = pr.id and r.created_at > now() - interval '1 day';
  if n >= 3 then
    return jsonb_build_object('ok', false, 'reason', 'limited');
  end if;
  select array_agg(t.friend_id order by t.added_at) into v_friends
    from public.zchat_trusted_friends t
    where t.owner_id = pr.id and t.added_at < now() - interval '3 days' and public.zchat_safety_friend_ok(pr.id, t.friend_id);
  if v_friends is null or cardinality(v_friends) < 3 then
    return jsonb_build_object('ok', false, 'reason', 'not_ready');
  end if;
  insert into public.zchat_recovery_requests (user_id, secret_hash, expires_at, ip, place, device)
  values (pr.id, p_secret_hash, now() + interval '24 hours', v_ip, left(nullif(btrim(p_place), ''), 80), left(nullif(btrim(p_device), ''), 80))
  returning id into v_id;
  v_name := left(coalesce(nullif(btrim(pr.name), ''), pr.username), 40);
  foreach f in array v_friends loop
    insert into public.zchat_recovery_codes (request_id, friend_id) values (v_id, f);
    perform public.zchat_notify(f, pr.id, 'recovery_help', null, null, jsonb_build_object('request_id', v_id));
    perform public.zchat_safety_queue(f, pr.id, 'recovery_help', v_name || ' asked for your help',
      'They are trying to get back into their account. Only help if you have talked to them.', '/?recovery=' || v_id, 'recovery-' || v_id);
  end loop;
  perform public.zchat_notify(pr.id, null, 'recovery_notice', null, null, jsonb_build_object('request_id', v_id, 'ev', 'started'));
  perform public.zchat_safety_queue(pr.id, null, 'recovery_notice', 'Someone asked your trusted friends for help',
    'If this was not you, open ZChat and stop it.', '/?recovery=' || v_id, 'recovery-' || v_id);
  perform public.zchat_rec_log(pr.id, v_id, 'started', null, v_ip);
  perform public.zchat_safety_kick();
  return jsonb_build_object('ok', true, 'id', v_id, 'friends', cardinality(v_friends), 'expires_at', now() + interval '24 hours');
end $$;
revoke all on function public.zchat_rec_start(text, text, text, text, text) from public, anon, authenticated;
grant execute on function public.zchat_rec_start(text, text, text, text, text) to service_role;

create or replace function public.zchat_rec_check(p_id uuid, p_secret_hash text, p_code_hash text, p_ip text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  r public.zchat_recovery_requests%rowtype;
  v_ip text := left(coalesce(nullif(btrim(p_ip), ''), 'unknown'), 64);
  v_friend uuid;
  n integer;
begin
  if p_id is null or p_secret_hash is null or p_code_hash is null or p_code_hash !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object('ok', false, 'reason', 'input');
  end if;
  select * into r from public.zchat_recovery_requests where id = p_id for update;
  if not found or r.secret_hash <> p_secret_hash then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  if r.status = 'open' and r.expires_at <= now() then
    update public.zchat_recovery_requests set status = 'expired', ended_at = now() where id = p_id;
    return jsonb_build_object('ok', false, 'reason', 'expired');
  end if;
  if r.status <> 'open' then
    return jsonb_build_object('ok', r.status in ('verified', 'waiting', 'done'), 'status', r.status, 'reason', r.status);
  end if;
  select count(*) into n from public.zchat_recovery_tries t where t.ip = v_ip and t.kind = 'code' and t.at > now() - interval '1 hour';
  if n >= 30 then
    return jsonb_build_object('ok', false, 'reason', 'limited');
  end if;
  update public.zchat_recovery_codes c set used_at = now()
    where c.request_id = p_id and c.code_hash = p_code_hash and c.used_at is null and c.denied_at is null
    returning c.friend_id into v_friend;
  if v_friend is null then
    insert into public.zchat_recovery_tries (ip, kind) values (v_ip, 'code');
    update public.zchat_recovery_requests set fails = fails + 1 where id = p_id returning fails into n;
    perform public.zchat_rec_log(r.user_id, p_id, 'code_wrong', null, v_ip);
    if n >= 6 then
      update public.zchat_recovery_requests set status = 'locked', ended_at = now() where id = p_id;
      perform public.zchat_rec_lock(r.user_id, 24);
      perform public.zchat_rec_log(r.user_id, p_id, 'locked', null, v_ip);
      return jsonb_build_object('ok', false, 'reason', 'locked');
    end if;
    return jsonb_build_object('ok', false, 'reason', 'wrong', 'left', 6 - n);
  end if;
  perform public.zchat_rec_log(r.user_id, p_id, 'code_ok', v_friend, v_ip);
  select count(*) into n from public.zchat_recovery_codes c where c.request_id = p_id and c.used_at is not null;
  if n >= 3 then
    update public.zchat_recovery_requests set status = 'verified', verified_at = now() where id = p_id;
    perform public.zchat_rec_log(r.user_id, p_id, 'verified', null, v_ip);
    return jsonb_build_object('ok', true, 'used', n, 'need', 3, 'status', 'verified');
  end if;
  return jsonb_build_object('ok', true, 'used', n, 'need', 3, 'status', 'open');
end $$;
revoke all on function public.zchat_rec_check(uuid, text, text, text) from public, anon, authenticated;
grant execute on function public.zchat_rec_check(uuid, text, text, text) to service_role;

create or replace function public.zchat_rec_status(p_id uuid, p_secret_hash text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  r public.zchat_recovery_requests%rowtype;
  n integer;
  total integer;
begin
  select * into r from public.zchat_recovery_requests where id = p_id;
  if not found or p_secret_hash is null or r.secret_hash <> p_secret_hash then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  if r.status = 'open' and r.expires_at <= now() then
    update public.zchat_recovery_requests set status = 'expired', ended_at = now() where id = p_id;
    r.status := 'expired';
  end if;
  select count(*) filter (where c.used_at is not null), count(*) into n, total from public.zchat_recovery_codes c where c.request_id = p_id;
  return jsonb_build_object('ok', true, 'status', r.status, 'used', n, 'need', 3, 'friends', total, 'expires_at', r.expires_at, 'apply_after', r.apply_after, 'has_email', r.new_email is not null);
end $$;
revoke all on function public.zchat_rec_status(uuid, text) from public, anon, authenticated;
grant execute on function public.zchat_rec_status(uuid, text) to service_role;

create or replace function public.zchat_rec_email(p_id uuid, p_secret_hash text, p_email text, p_cancel_hash text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  r public.zchat_recovery_requests%rowtype;
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_old text;
  v_name text;
begin
  if p_cancel_hash is null or p_cancel_hash !~ '^[0-9a-f]{64}$' or v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' or char_length(v_email) > 200 then
    return jsonb_build_object('ok', false, 'reason', 'input');
  end if;
  select * into r from public.zchat_recovery_requests where id = p_id for update;
  if not found or p_secret_hash is null or r.secret_hash <> p_secret_hash then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  if r.status <> 'verified' or r.verified_at < now() - interval '24 hours' then
    return jsonb_build_object('ok', false, 'reason', coalesce(nullif(r.status, 'verified'), 'expired'));
  end if;
  select u.email into v_old from auth.users u where u.id = r.user_id;
  if exists (select 1 from auth.users u where lower(u.email) = v_email and u.id <> r.user_id) then
    return jsonb_build_object('ok', false, 'reason', 'taken');
  end if;
  update public.zchat_recovery_requests set new_email = v_email, status = 'waiting', apply_after = now() + interval '24 hours', cancel_hash = p_cancel_hash where id = p_id;
  select left(coalesce(nullif(btrim(p.name), ''), p.username), 40) into v_name from public.profiles p where p.id = r.user_id;
  perform public.zchat_notify(r.user_id, null, 'recovery_notice', null, null, jsonb_build_object('request_id', p_id, 'ev', 'waiting', 'apply_after', now() + interval '24 hours'));
  perform public.zchat_safety_queue(r.user_id, null, 'recovery_notice', 'Your login email is about to change',
    'Your trusted friends confirmed it was you. If it was not, open ZChat and stop it within 24 hours.', '/?recovery=' || p_id, 'recovery-' || p_id);
  perform public.zchat_rec_log(r.user_id, p_id, 'email_set', null, null);
  perform public.zchat_safety_kick();
  return jsonb_build_object('ok', true, 'apply_after', now() + interval '24 hours', 'old_email', v_old, 'name', v_name, 'user_id', r.user_id);
end $$;
revoke all on function public.zchat_rec_email(uuid, text, text, text) from public, anon, authenticated;
grant execute on function public.zchat_rec_email(uuid, text, text, text) to service_role;

create or replace function public.zchat_rec_ready(p_id uuid, p_secret_hash text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  r public.zchat_recovery_requests%rowtype;
begin
  select * into r from public.zchat_recovery_requests where id = p_id;
  if not found or p_secret_hash is null or r.secret_hash <> p_secret_hash then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  if r.status <> 'waiting' then
    return jsonb_build_object('ok', false, 'reason', r.status);
  end if;
  if r.apply_after > now() then
    return jsonb_build_object('ok', false, 'reason', 'wait', 'apply_after', r.apply_after);
  end if;
  if r.apply_after < now() - interval '7 days' then
    update public.zchat_recovery_requests set status = 'expired', ended_at = now() where id = p_id;
    return jsonb_build_object('ok', false, 'reason', 'expired');
  end if;
  return jsonb_build_object('ok', true, 'user_id', r.user_id, 'new_email', r.new_email);
end $$;
revoke all on function public.zchat_rec_ready(uuid, text) from public, anon, authenticated;
grant execute on function public.zchat_rec_ready(uuid, text) to service_role;

create or replace function public.zchat_rec_mark_done(p_id uuid, p_secret_hash text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  r public.zchat_recovery_requests%rowtype;
  n integer := 0;
  v_gate boolean;
begin
  select * into r from public.zchat_recovery_requests where id = p_id for update;
  if not found or p_secret_hash is null or r.secret_hash <> p_secret_hash or r.status <> 'waiting' or r.apply_after > now() then
    return jsonb_build_object('ok', false);
  end if;
  update public.zchat_recovery_requests set status = 'done', ended_at = now() where id = p_id;
  if to_regclass('auth.sessions') is not null then
    execute 'delete from auth.sessions where user_id = $1' using r.user_id;
    get diagnostics n = row_count;
  end if;
  delete from public.login_approval a where a.user_id = r.user_id;
  v_gate := found;
  delete from public.approved_sessions s where s.user_id = r.user_id;
  perform public.zchat_notify(r.user_id, null, 'recovery_notice', null, null, jsonb_build_object('request_id', p_id, 'ev', 'done', 'approval_off', v_gate));
  perform public.zchat_rec_log(r.user_id, p_id, 'done', null, null);
  return jsonb_build_object('ok', true, 'ended', n, 'approval_off', v_gate);
exception when others then
  raise notice 'zchat recovery finish: %', sqlerrm;
  return jsonb_build_object('ok', false);
end $$;
revoke all on function public.zchat_rec_mark_done(uuid, text) from public, anon, authenticated;
grant execute on function public.zchat_rec_mark_done(uuid, text) to service_role;

create or replace function public.zchat_rec_cancel(p_cancel_hash text, p_ip text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  r public.zchat_recovery_requests%rowtype;
begin
  if p_cancel_hash is null or p_cancel_hash !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object('ok', false, 'reason', 'input');
  end if;
  select * into r from public.zchat_recovery_requests where cancel_hash = p_cancel_hash for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  if r.status not in ('open', 'verified', 'waiting') then
    return jsonb_build_object('ok', r.status = 'cancelled', 'reason', r.status);
  end if;
  update public.zchat_recovery_requests set status = 'cancelled', ended_at = now() where id = r.id;
  perform public.zchat_rec_lock(r.user_id, 72);
  perform public.zchat_notify(r.user_id, null, 'recovery_notice', null, null, jsonb_build_object('request_id', r.id, 'ev', 'cancelled'));
  perform public.zchat_rec_log(r.user_id, r.id, 'cancelled_email', null, left(p_ip, 64));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.zchat_rec_cancel(text, text) from public, anon, authenticated;
grant execute on function public.zchat_rec_cancel(text, text) to service_role;

create or replace function public.zchat_rec_owner_cancel(p_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  r public.zchat_recovery_requests%rowtype;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'auth');
  end if;
  select * into r from public.zchat_recovery_requests where id = p_id and user_id = me for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  if r.status not in ('open', 'verified', 'waiting') then
    return jsonb_build_object('ok', r.status = 'cancelled', 'reason', r.status);
  end if;
  update public.zchat_recovery_requests set status = 'cancelled', ended_at = now() where id = r.id;
  perform public.zchat_rec_lock(me, 72);
  perform public.zchat_rec_log(me, r.id, 'cancelled_owner', me, null);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.zchat_rec_owner_cancel(uuid) from public, anon;
grant execute on function public.zchat_rec_owner_cancel(uuid) to authenticated, service_role;

create or replace function public.zchat_rec_for_me()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', r.id,
      'user', jsonb_build_object('id', p.id, 'name', p.name, 'username', p.username, 'avatar', case when coalesce(p.hide_photo, false) then null else p.avatar end),
      'created_at', r.created_at, 'expires_at', r.expires_at, 'place', r.place, 'device', r.device,
      'state', case when c.denied_at is not null then 'denied' when c.used_at is not null then 'used' when c.code_hash is not null then 'shown' else 'new' end
    ) order by r.created_at desc), '[]'::jsonb)
  from public.zchat_recovery_codes c
  join public.zchat_recovery_requests r on r.id = c.request_id
  join public.profiles p on p.id = r.user_id
  where c.friend_id = auth.uid() and r.status = 'open' and r.expires_at > now();
$$;
revoke all on function public.zchat_rec_for_me() from public, anon;
grant execute on function public.zchat_rec_for_me() to authenticated, service_role;

create or replace function public.zchat_rec_friend_code(p_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  r public.zchat_recovery_requests%rowtype;
  c public.zchat_recovery_codes%rowtype;
  alphabet constant text := 'ACDEFGHJKMNPQRTUVWXY346789';
  b bytea;
  v_code text := '';
  i integer;
begin
  if me is null or p_id is null then
    return jsonb_build_object('ok', false, 'reason', 'auth');
  end if;
  select * into r from public.zchat_recovery_requests where id = p_id;
  if not found or r.status <> 'open' or r.expires_at <= now() then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  select * into c from public.zchat_recovery_codes where request_id = p_id and friend_id = me for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  if c.denied_at is not null or c.used_at is not null then
    return jsonb_build_object('ok', false, 'reason', case when c.used_at is not null then 'used' else 'denied' end);
  end if;
  if not public.zchat_safety_friend_ok(r.user_id, me) then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  if c.shows >= 3 then
    return jsonb_build_object('ok', false, 'reason', 'limited');
  end if;
  while length(v_code) < 8 loop
    b := extensions.gen_random_bytes(16);
    for i in 0 .. 15 loop
      if get_byte(b, i) < 234 and length(v_code) < 8 then
        v_code := v_code || substr(alphabet, (get_byte(b, i) % 26) + 1, 1);
      end if;
    end loop;
  end loop;
  update public.zchat_recovery_codes
    set code_hash = encode(extensions.digest(p_id::text || ':' || v_code, 'sha256'), 'hex'), shows = shows + 1, shown_at = now()
    where request_id = p_id and friend_id = me;
  perform public.zchat_rec_log(r.user_id, p_id, 'code_shown', me, null);
  return jsonb_build_object('ok', true, 'code', v_code, 'expires_at', r.expires_at);
end $$;
revoke all on function public.zchat_rec_friend_code(uuid) from public, anon;
grant execute on function public.zchat_rec_friend_code(uuid) to authenticated, service_role;

create or replace function public.zchat_rec_deny(p_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  r public.zchat_recovery_requests%rowtype;
  v_name text;
begin
  if me is null or p_id is null then
    return jsonb_build_object('ok', false, 'reason', 'auth');
  end if;
  select * into r from public.zchat_recovery_requests where id = p_id for update;
  if not found or not exists (select 1 from public.zchat_recovery_codes c where c.request_id = p_id and c.friend_id = me) then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  update public.zchat_recovery_codes set denied_at = coalesce(denied_at, now()) where request_id = p_id and friend_id = me;
  if r.status in ('open', 'verified', 'waiting') then
    update public.zchat_recovery_requests set status = 'denied', denied_by = me, ended_at = now() where id = p_id;
    perform public.zchat_rec_lock(r.user_id, 72);
    select left(coalesce(nullif(btrim(p.name), ''), p.username), 40) into v_name from public.profiles p where p.id = me;
    perform public.zchat_notify(r.user_id, me, 'recovery_denied', null, null, jsonb_build_object('request_id', p_id));
    perform public.zchat_safety_queue(r.user_id, me, 'recovery_denied', coalesce(v_name, 'A trusted friend') || ' stopped a request',
      'Someone tried to get into your account with help from your trusted friends. It was stopped.', '/?recovery=' || p_id, 'recovery-' || p_id);
    perform public.zchat_safety_kick();
  end if;
  perform public.zchat_rec_log(r.user_id, p_id, 'denied', me, null);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.zchat_rec_deny(uuid) from public, anon;
grant execute on function public.zchat_rec_deny(uuid) to authenticated, service_role;

select public.zchat_apply_session_gate();
commit;

begin;
create table if not exists public.zchat_data_exports (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  status text not null default 'queued' check (status in ('queued', 'working', 'ready', 'failed', 'expired')),
  phase text,
  progress integer not null default 0 check (progress between 0 and 100),
  parts jsonb not null default '[]'::jsonb,
  bytes bigint not null default 0,
  error text,
  cursor jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  finished_at timestamptz,
  expires_at timestamptz
);
create index if not exists zchat_data_exports_user on public.zchat_data_exports (user_id, created_at desc);
create index if not exists zchat_data_exports_expiry on public.zchat_data_exports (expires_at) where status = 'ready';
alter table public.zchat_data_exports enable row level security;
revoke all on public.zchat_data_exports from public, anon, authenticated;
grant select on public.zchat_data_exports to authenticated;
grant all on public.zchat_data_exports to service_role;
drop policy if exists "zchat data exports own" on public.zchat_data_exports;
create policy "zchat data exports own" on public.zchat_data_exports for select to authenticated using (user_id = (select auth.uid()));

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'zchat_data_exports') then
    execute 'alter publication supabase_realtime add table public.zchat_data_exports';
  end if;
end $$;

do $$
begin
  if to_regclass('storage.buckets') is not null then
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('zchat-exports', 'zchat-exports', false, 52428800, array['application/zip'])
    on conflict (id) do update set public = false;
  end if;
exception when others then
  raise notice 'zchat safety: the exports bucket was not made: %', sqlerrm;
end $$;

create or replace function public.zchat_export_begin(p_user uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  last public.zchat_data_exports%rowtype;
  v_id uuid;
begin
  if p_user is null or not exists (select 1 from public.profiles p where p.id = p_user and not coalesce(p.is_deleted, false) and not coalesce(p.banned, false)) then
    return jsonb_build_object('ok', false, 'reason', 'auth');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('zchat_export:' || p_user::text, 0));
  update public.zchat_data_exports set status = 'failed', error = 'stalled', updated_at = now()
    where user_id = p_user and status in ('queued', 'working') and updated_at < now() - interval '20 minutes';
  select * into last from public.zchat_data_exports e where e.user_id = p_user and e.status <> 'failed' order by e.created_at desc limit 1;
  if found and last.status in ('queued', 'working') then
    return jsonb_build_object('ok', false, 'reason', 'busy', 'id', last.id);
  end if;
  if found and last.created_at > now() - interval '24 hours' then
    return jsonb_build_object('ok', false, 'reason', 'limited', 'id', last.id, 'next_at', last.created_at + interval '24 hours');
  end if;
  insert into public.zchat_data_exports (user_id) values (p_user) returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id);
end $$;
revoke all on function public.zchat_export_begin(uuid) from public, anon, authenticated;
grant execute on function public.zchat_export_begin(uuid) to service_role;

create or replace function public.zchat_export_done(p_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  e public.zchat_data_exports%rowtype;
begin
  update public.zchat_data_exports
    set status = 'ready', progress = 100, phase = 'ready', finished_at = now(), expires_at = now() + interval '3 days', updated_at = now(), cursor = null
    where id = p_id and status = 'working'
    returning * into e;
  if not found then
    return jsonb_build_object('ok', false);
  end if;
  perform public.zchat_notify(e.user_id, null, 'data_ready', null, null, jsonb_build_object('export_id', e.id, 'expires_at', e.expires_at));
  perform public.zchat_safety_queue(e.user_id, null, 'data_ready', 'Your ZChat data is ready',
    'Download it in Settings, Privacy. The link works for 3 days.', '/?data=' || e.id, 'data-' || e.id);
  perform public.zchat_safety_kick();
  return jsonb_build_object('ok', true, 'expires_at', e.expires_at);
end $$;
revoke all on function public.zchat_export_done(uuid) from public, anon, authenticated;
grant execute on function public.zchat_export_done(uuid) to service_role;

create or replace function public.zchat_export_expire()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  n integer;
begin
  update public.zchat_data_exports set status = 'expired', updated_at = now()
    where status = 'ready' and expires_at < now();
  get diagnostics n = row_count;
  update public.zchat_data_exports set status = 'failed', error = 'stalled', updated_at = now()
    where status in ('queued', 'working') and updated_at < now() - interval '1 hour';
  delete from public.zchat_data_exports where created_at < now() - interval '60 days' and status in ('expired', 'failed');
  return n;
end $$;
revoke all on function public.zchat_export_expire() from public, anon, authenticated;
grant execute on function public.zchat_export_expire() to service_role;

do $$
begin
  if exists (select 1 from pg_namespace where nspname = 'cron') then
    if not exists (select 1 from cron.job where jobname = 'zchat-data-exports') then
      perform cron.schedule('zchat-data-exports', '41 * * * *', 'select public.zchat_export_expire()');
    end if;
  end if;
exception when others then
  raise notice 'zchat safety: the export cleanup job was not scheduled: %', sqlerrm;
end $$;

select public.zchat_apply_session_gate();

create or replace function public.zchat_name_key(p text)
returns text
language plpgsql
immutable
set search_path = public
as $$
declare
  s text := lower(coalesce(p, ''));
begin
  s := translate(s, E'\u0430\u0435\u043e\u0440\u0441\u0443\u0445\u043a\u043c\u0442\u0432\u043d\u0455\u0456\u0458\u0501\u0261\u04cf\u04bb\u051b\u051d\u04af\u03bf\u03b1\u03c1\u03c4\u03c5\u03bd\u03ba\u03bc\u03c7\u03b9\u03b5\u03b7\u03b2\u03b3\u0581\u0585\u057d\u0570\u0578\u00e0\u00e1\u00e2\u00e3\u00e4\u00e5\u0101\u0103\u0105\u00e7\u0107\u010d\u010f\u00e8\u00e9\u00ea\u00eb\u0113\u0117\u0119\u011b\u011f\u00ec\u00ed\u00ee\u00ef\u012b\u012f\u0131\u013e\u0142\u00f1\u0144\u0148\u00f2\u00f3\u00f4\u00f5\u00f6\u00f8\u014d\u0151\u0159\u015b\u0161\u015f\u0165\u00f9\u00fa\u00fb\u00fc\u016b\u016f\u0171\u0173\u00fd\u00ff\u017e\u017a\u017c@$!|\uff41\uff42\uff43\uff44\uff45\uff46\uff47\uff48\uff49\uff4a\uff4b\uff4c\uff4d\uff4e\uff4f\uff50\uff51\uff52\uff53\uff54\uff55\uff56\uff57\uff58\uff59\uff5a', 'aeopcyxkmtbhsijdglhqwyoaptuvkmxienbygouhnaaaaaaaaacccdeeeeeeeegiiiiiiillnnnoooooooorssstuuuuuuuuyyzzzasilabcdefghijklmnopqrstuvwxyz');
  s := regexp_replace(s, '[._\-]+', ' ', 'g');
  s := regexp_replace(s, '\m(official|offical|real|the|its|im|iam|support|team|help|helpdesk|service|services|care|admin|admins|verified|original|page|account|hq|tv|fan|fans|fanpage|club|backup|private|alt)\M', ' ', 'g');
  s := regexp_replace(s, '[0-9]+\s*$', '');
  s := translate(s, '013457890', 'oleastbgo');
  s := regexp_replace(s, '[^a-z]', '', 'g');
  s := replace(replace(s, 'rn', 'm'), 'vv', 'w');
  s := regexp_replace(s, '^(the|real|official|its|get|team|my)?zchat(support|team|official|offical|help|helpdesk|admin|admins|security|staff|care|service|services|app|bot|hq|verify|verification|mod|moderator|login|account|accounts|safety|update|updates|news)*$', 'zchat');
  s := translate(s, 'i', 'l');
  s := regexp_replace(s, '(.)\1+', '\1', 'g');
  return s;
end $$;
revoke all on function public.zchat_name_key(text) from public, anon;
grant execute on function public.zchat_name_key(text) to authenticated, service_role;

create or replace function public.zchat_lev1(a text, b text)
returns boolean
language plpgsql
immutable
set search_path = public
as $$
declare
  la integer := length(coalesce(a, ''));
  lb integer := length(coalesce(b, ''));
  i integer := 1;
  j integer := 1;
  diff integer := 0;
begin
  if a is null or b is null then
    return false;
  end if;
  if a = b then
    return true;
  end if;
  if abs(la - lb) > 1 then
    return false;
  end if;
  while i <= la and j <= lb loop
    if substr(a, i, 1) <> substr(b, j, 1) then
      diff := diff + 1;
      if diff > 1 then
        return false;
      end if;
      if la > lb then
        i := i + 1;
      elsif lb > la then
        j := j + 1;
      else
        i := i + 1;
        j := j + 1;
      end if;
    else
      i := i + 1;
      j := j + 1;
    end if;
  end loop;
  return diff + (la - i + 1) + (lb - j + 1) <= 1;
end $$;
revoke all on function public.zchat_lev1(text, text) from public, anon;
grant execute on function public.zchat_lev1(text, text) to authenticated, service_role;

create table if not exists public.zchat_name_keys (
  user_id uuid primary key references auth.users(id) on delete cascade,
  name_key text not null default '',
  user_key text not null default '',
  protected boolean not null default false,
  official boolean not null default false,
  active boolean not null default true,
  updated_at timestamptz not null default now()
);
create index if not exists zchat_name_keys_name on public.zchat_name_keys (name_key);
create index if not exists zchat_name_keys_user on public.zchat_name_keys (user_key);
create index if not exists zchat_name_keys_protected on public.zchat_name_keys (user_id) where protected;
alter table public.zchat_name_keys enable row level security;
revoke all on public.zchat_name_keys from public, anon, authenticated;
grant all on public.zchat_name_keys to service_role;

create table if not exists public.zchat_lookalikes (
  user_id uuid primary key references auth.users(id) on delete cascade,
  of_id uuid references auth.users(id) on delete cascade,
  kind text not null check (kind in ('user', 'zchat')),
  at timestamptz not null default now()
);
create index if not exists zchat_lookalikes_of on public.zchat_lookalikes (of_id);
alter table public.zchat_lookalikes enable row level security;
revoke all on public.zchat_lookalikes from public, anon, authenticated;
grant all on public.zchat_lookalikes to service_role;

create or replace function public.zchat_lookalike_compute(p_user uuid)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  k public.zchat_name_keys%rowtype;
  v_hit uuid;
  v_kind text;
  v_common integer;
begin
  select * into k from public.zchat_name_keys where user_id = p_user;
  if not found or k.protected or k.official or not k.active then
    delete from public.zchat_lookalikes where user_id = p_user;
    return null;
  end if;
  if k.name_key = 'zchat' or k.user_key = 'zchat' then
    v_kind := 'zchat';
    select n.user_id into v_hit from public.zchat_name_keys n where n.official order by n.updated_at limit 1;
  else
    select count(*) into v_common from public.zchat_name_keys n where n.name_key = k.name_key and not n.protected;
    select n.user_id into v_hit from public.zchat_name_keys n
      where n.protected and n.active and n.user_id <> p_user and (
        (length(k.user_key) >= 4 and n.user_key = k.user_key)
        or (length(k.user_key) >= 6 and n.name_key = k.user_key)
        or (length(k.name_key) >= 6 and n.user_key = k.name_key)
        or (length(k.name_key) >= 5 and n.name_key = k.name_key and v_common <= 8)
        or (length(k.user_key) >= 6 and length(n.user_key) >= 6 and public.zchat_lev1(n.user_key, k.user_key))
        or (length(k.name_key) >= 8 and v_common <= 8 and length(n.name_key) >= 8 and public.zchat_lev1(n.name_key, k.name_key))
      )
      order by (n.user_key = k.user_key) desc, (n.name_key = k.name_key) desc, n.updated_at
      limit 1;
    if v_hit is not null then
      v_kind := 'user';
    end if;
  end if;
  if v_kind is null then
    delete from public.zchat_lookalikes where user_id = p_user;
    return null;
  end if;
  insert into public.zchat_lookalikes (user_id, of_id, kind, at) values (p_user, v_hit, v_kind, now())
  on conflict (user_id) do update set of_id = excluded.of_id, kind = excluded.kind, at = now()
  where public.zchat_lookalikes.of_id is distinct from excluded.of_id or public.zchat_lookalikes.kind <> excluded.kind;
  return v_kind;
end $$;
revoke all on function public.zchat_lookalike_compute(uuid) from public, anon, authenticated;
grant execute on function public.zchat_lookalike_compute(uuid) to service_role;

create or replace function public.zchat_name_keys_put(p public.profiles)
returns public.zchat_name_keys
language plpgsql
security definer
set search_path = public
as $$
declare
  row public.zchat_name_keys%rowtype;
begin
  insert into public.zchat_name_keys (user_id, name_key, user_key, protected, official, active, updated_at)
  values (p.id, public.zchat_name_key(p.name), public.zchat_name_key(p.username),
    coalesce(p.verified, '') in ('blue', 'red', 'pink', 'green') and not coalesce(p.is_deleted, false) and not coalesce(p.banned, false),
    coalesce(p.verified, '') = 'red' and not coalesce(p.is_deleted, false) and not coalesce(p.banned, false),
    not coalesce(p.is_deleted, false) and not coalesce(p.banned, false),
    now())
  on conflict (user_id) do update set name_key = excluded.name_key, user_key = excluded.user_key, protected = excluded.protected,
    official = excluded.official, active = excluded.active, updated_at = now()
  returning * into row;
  return row;
end $$;
revoke all on function public.zchat_name_keys_put(public.profiles) from public, anon, authenticated;
grant execute on function public.zchat_name_keys_put(public.profiles) to service_role;

create or replace function public.zchat_lookalike_sync()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  old_k public.zchat_name_keys%rowtype;
  new_k public.zchat_name_keys%rowtype;
  r record;
begin
  select * into old_k from public.zchat_name_keys where user_id = new.id;
  new_k := public.zchat_name_keys_put(new);
  perform public.zchat_lookalike_compute(new.id);
  if (new_k.protected or new_k.official or coalesce(old_k.protected, false) or coalesce(old_k.official, false))
     and (old_k.user_id is null or old_k.name_key is distinct from new_k.name_key or old_k.user_key is distinct from new_k.user_key
          or old_k.protected is distinct from new_k.protected or old_k.official is distinct from new_k.official or old_k.active is distinct from new_k.active) then
    for r in
      select l.user_id from public.zchat_lookalikes l where l.of_id = new.id
      union
      select n.user_id from public.zchat_name_keys n
      where not n.protected and n.user_id <> new.id and (
        n.name_key in (new_k.name_key, new_k.user_key, coalesce(old_k.name_key, ''), coalesce(old_k.user_key, ''))
        or n.user_key in (new_k.name_key, new_k.user_key, coalesce(old_k.name_key, ''), coalesce(old_k.user_key, ''))
        or ((new_k.official or coalesce(old_k.official, false)) and (n.name_key = 'zchat' or n.user_key = 'zchat'))
      )
      limit 500
    loop
      perform public.zchat_lookalike_compute(r.user_id);
    end loop;
  end if;
  return null;
exception when others then
  raise notice 'zchat lookalike sync skipped: %', sqlerrm;
  return null;
end $$;
revoke all on function public.zchat_lookalike_sync() from public, anon, authenticated;

drop trigger if exists zchat_lookalike_sync on public.profiles;
create trigger zchat_lookalike_sync after insert or update of name, username, verified, is_deleted, banned on public.profiles
  for each row execute function public.zchat_lookalike_sync();

create or replace function public.zchat_lookalike(p_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select case when l.user_id is null then null
    else jsonb_build_object('kind', l.kind, 'id', p.id, 'name', coalesce(p.name, 'ZChat'), 'username', p.username) end
  from public.zchat_lookalikes l
  left join public.profiles p on p.id = l.of_id
  where l.user_id = p_id and auth.uid() is not null and p_id <> auth.uid()
$$;
revoke all on function public.zchat_lookalike(uuid) from public, anon;
grant execute on function public.zchat_lookalike(uuid) to authenticated, service_role;

create or replace function public.zchat_lookalike_many(p_ids uuid[])
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(jsonb_object_agg(l.user_id::text,
    jsonb_build_object('kind', l.kind, 'id', p.id, 'name', coalesce(p.name, 'ZChat'), 'username', p.username)), '{}'::jsonb)
  from public.zchat_lookalikes l
  left join public.profiles p on p.id = l.of_id
  where auth.uid() is not null
    and l.user_id in (select x from unnest(coalesce(p_ids, '{}'::uuid[])) as u(x) limit 200)
    and l.user_id <> auth.uid()
$$;
revoke all on function public.zchat_lookalike_many(uuid[]) from public, anon;
grant execute on function public.zchat_lookalike_many(uuid[]) to authenticated, service_role;

do $$
declare
  p public.profiles%rowtype;
begin
  for p in select * from public.profiles loop
    perform public.zchat_name_keys_put(p);
  end loop;
  perform public.zchat_lookalike_compute(n.user_id) from public.zchat_name_keys n where not n.protected and not n.official;
end $$;

select public.zchat_apply_session_gate();

create table if not exists public.zchat_link_cache (
  k text primary key check (char_length(k) <= 300),
  verdict text not null check (verdict in ('ok', 'warn', 'danger')),
  reason text check (reason is null or char_length(reason) <= 160),
  target text check (target is null or char_length(target) <= 300),
  checked_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '1 day'
);
create index if not exists zchat_link_cache_expiry on public.zchat_link_cache (expires_at);
alter table public.zchat_link_cache enable row level security;
revoke all on public.zchat_link_cache from public, anon, authenticated;
grant all on public.zchat_link_cache to service_role;

create table if not exists public.zchat_link_blocklist (
  host text primary key check (host ~ '^[a-z0-9.-]{3,253}$'),
  reason text not null default 'Reported as a scam' check (char_length(reason) <= 160),
  added_by uuid references auth.users(id) on delete set null,
  added_at timestamptz not null default now()
);
alter table public.zchat_link_blocklist enable row level security;
revoke all on public.zchat_link_blocklist from public, anon, authenticated;
grant select, insert, delete on public.zchat_link_blocklist to authenticated;
grant all on public.zchat_link_blocklist to service_role;
drop policy if exists "zchat link blocklist admins read" on public.zchat_link_blocklist;
create policy "zchat link blocklist admins read" on public.zchat_link_blocklist for select to authenticated using ((select public.zchat_is_admin()));
drop policy if exists "zchat link blocklist admins add" on public.zchat_link_blocklist;
create policy "zchat link blocklist admins add" on public.zchat_link_blocklist for insert to authenticated with check ((select public.zchat_is_admin()) and added_by = (select auth.uid()));
drop policy if exists "zchat link blocklist admins remove" on public.zchat_link_blocklist;
create policy "zchat link blocklist admins remove" on public.zchat_link_blocklist for delete to authenticated using ((select public.zchat_is_admin()));

create or replace function public.zchat_link_lookup(p_keys text[])
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'cache', coalesce((select jsonb_object_agg(c.k, jsonb_build_object('v', c.verdict, 'why', c.reason, 'to', c.target))
      from public.zchat_link_cache c where c.k = any (p_keys[1:60]) and c.expires_at > now()), '{}'::jsonb),
    'blocked', coalesce((select jsonb_object_agg(b.host, b.reason)
      from public.zchat_link_blocklist b where b.host = any (p_keys[1:60])), '{}'::jsonb)
  );
$$;
revoke all on function public.zchat_link_lookup(text[]) from public, anon, authenticated;
grant execute on function public.zchat_link_lookup(text[]) to service_role;

create or replace function public.zchat_link_store(p_rows jsonb)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  r jsonb;
  n integer := 0;
begin
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    return 0;
  end if;
  for r in select value from jsonb_array_elements(p_rows) limit 60 loop
    if coalesce(r ->> 'k', '') = '' or coalesce(r ->> 'v', '') not in ('ok', 'warn', 'danger') then
      continue;
    end if;
    insert into public.zchat_link_cache (k, verdict, reason, target, checked_at, expires_at)
    values (left(r ->> 'k', 300), r ->> 'v', left(r ->> 'why', 160), left(r ->> 'to', 300), now(),
      now() + make_interval(hours => greatest(1, least(coalesce((r ->> 'h')::integer, 24), 168))))
    on conflict (k) do update set verdict = excluded.verdict, reason = excluded.reason, target = excluded.target, checked_at = now(), expires_at = excluded.expires_at;
    n := n + 1;
  end loop;
  if random() < 0.02 then
    delete from public.zchat_link_cache where expires_at < now() - interval '7 days';
  end if;
  return n;
end $$;
revoke all on function public.zchat_link_store(jsonb) from public, anon, authenticated;
grant execute on function public.zchat_link_store(jsonb) to service_role;

select public.zchat_apply_session_gate();
commit;

begin;
create table if not exists public.zchat_search_prefs (
  user_id uuid primary key references auth.users(id) on delete cascade,
  visible boolean not null,
  updated_at timestamptz not null default now()
);
alter table public.zchat_search_prefs enable row level security;
revoke all on public.zchat_search_prefs from public, anon, authenticated;
grant select on public.zchat_search_prefs to authenticated;
grant all on public.zchat_search_prefs to service_role;
drop policy if exists "zchat search prefs own" on public.zchat_search_prefs;
create policy "zchat search prefs own" on public.zchat_search_prefs for select to authenticated using (user_id = (select auth.uid()));

create or replace function public.zchat_search_visible(p_user uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select s.visible from public.zchat_search_prefs s where s.user_id = p_user),
    (select not coalesce(p.is_private, false) from public.profiles p where p.id = p_user),
    false
  )
$$;
revoke all on function public.zchat_search_visible(uuid) from public;
grant execute on function public.zchat_search_visible(uuid) to anon, authenticated, service_role;

create or replace function public.zchat_search_pref_set(p_on boolean)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
begin
  if me is null or p_on is null then
    return jsonb_build_object('ok', false, 'reason', 'auth');
  end if;
  insert into public.zchat_search_prefs (user_id, visible, updated_at) values (me, p_on, now())
  on conflict (user_id) do update set visible = excluded.visible, updated_at = now();
  return jsonb_build_object('ok', true, 'visible', p_on);
end $$;
revoke all on function public.zchat_search_pref_set(boolean) from public, anon;
grant execute on function public.zchat_search_pref_set(boolean) to authenticated, service_role;

create or replace function public.zchat_search_pref_get()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object('visible', public.zchat_search_visible(auth.uid()),
    'set', exists (select 1 from public.zchat_search_prefs s where s.user_id = auth.uid()))
  where auth.uid() is not null
$$;
revoke all on function public.zchat_search_pref_get() from public, anon;
grant execute on function public.zchat_search_pref_get() to authenticated, service_role;

CREATE OR REPLACE FUNCTION public.public_profile_preview(p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  p public.profiles%rowtype;
  priv boolean;
  open_profile boolean;
  posts jsonb := '[]'::jsonb;
  n_posts int;
  n_foll int;
  n_fing int;
begin
  select * into p from public.profiles where id::text = p_id limit 1;
  if not found or coalesce(p.is_deleted, false) or coalesce(p.banned, false) then
    return jsonb_build_object('found', false);
  end if;
  priv := coalesce(p.is_private, false);
  open_profile := public.zchat_owner_visible(p.id, 'posts');
  select count(*) into n_posts from public.posts x where x.user_id = p.id and (x.scheduled_for is null or x.scheduled_for <= now());
  select count(*) into n_foll from public.follows where following_id = p.id and status = 'accepted';
  select count(*) into n_fing from public.follows where follower_id = p.id and status = 'accepted';
  if open_profile then
    select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'media_url', x.media_url, 'media_type', x.media_type)), '[]'::jsonb)
      into posts
      from (select id, media_url, media_type from public.posts
            where user_id = p.id and (scheduled_for is null or scheduled_for <= now())
            order by created_at desc limit 9) x;
  end if;
  return jsonb_build_object('found', true, 'id', p.id, 'name', p.name, 'username', p.username,
    'avatar', case when coalesce(p.hide_photo, false) then '' else coalesce(p.avatar, '') end,
    'avatar_frame', to_jsonb(p.avatar_frame), 'verified', to_jsonb(p.verified), 'custom_badge', to_jsonb(p.custom_badge),
    'bio', case when open_profile and not coalesce(p.hide_bio, false) and public.zchat_pv_allows(p.privacy_bio, 'privacy_bio', false, false, null) then coalesce(p.bio, '') else '' end,
    'is_private', priv, 'posts_count', n_posts, 'followers_count', n_foll, 'following_count', n_fing, 'posts', posts,
    'noindex', not public.zchat_search_visible(p.id));
end
$function$;

CREATE OR REPLACE FUNCTION public.public_post_preview(p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  po public.posts%rowtype;
  o public.profiles%rowtype;
  card jsonb;
  n_likes int;
  n_comments int;
begin
  select * into po from public.posts where id::text = p_id limit 1;
  if not found or (po.scheduled_for is not null and po.scheduled_for > now()) then
    return jsonb_build_object('found', false);
  end if;
  select * into o from public.profiles pr where pr.id = po.user_id;
  if not found or coalesce(o.is_deleted, false) or coalesce(o.banned, false) then
    return jsonb_build_object('found', false);
  end if;
  card := jsonb_build_object('id', o.id, 'name', o.name, 'username', o.username,
    'avatar', case when coalesce(o.hide_photo, false) then '' else coalesce(o.avatar, '') end,
    'avatar_frame', to_jsonb(o.avatar_frame), 'verified', to_jsonb(o.verified), 'custom_badge', to_jsonb(o.custom_badge));
  if not public.zchat_owner_visible(po.user_id, 'posts') then
    return jsonb_build_object('found', true, 'restricted', true, 'owner', card, 'noindex', not public.zchat_search_visible(po.user_id));
  end if;
  select count(*) into n_likes from public.post_likes where post_id = po.id;
  select count(*) into n_comments from public.post_comments where post_id = po.id;
  return jsonb_build_object('found', true, 'restricted', false, 'owner', card, 'media_url', po.media_url,
    'media_type', po.media_type, 'caption', po.caption, 'created_at', po.created_at, 'likes', n_likes, 'comments', n_comments,
    'noindex', not public.zchat_search_visible(po.user_id));
end
$function$;

select public.zchat_apply_session_gate();

alter table public.posts add column if not exists kind text;
alter table public.posts add column if not exists voice jsonb;
alter table public.posts add column if not exists alt_texts jsonb;
alter table public.posts add column if not exists captions jsonb;
alter table public.posts add column if not exists poll jsonb;
alter table public.posts add column if not exists remix_of uuid;
alter table public.posts add column if not exists remix_layout text;
alter table public.posts add column if not exists remix_ok boolean not null default true;
alter table public.posts add column if not exists archived_at timestamptz;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'zchat_posts_remix_of_fkey') then
    alter table public.posts add constraint zchat_posts_remix_of_fkey foreign key (remix_of) references public.posts(id) on delete set null;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'zchat_posts_kind_ok') then
    alter table public.posts add constraint zchat_posts_kind_ok check (kind is null or kind = 'voice') not valid;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'zchat_posts_remix_layout_ok') then
    alter table public.posts add constraint zchat_posts_remix_layout_ok check (remix_layout is null or remix_layout in ('side', 'corner')) not valid;
  end if;
end $$;

create index if not exists zchat_posts_remix_of on public.posts (remix_of) where remix_of is not null;
create index if not exists zchat_posts_user_archived on public.posts (user_id, archived_at desc) where archived_at is not null;
create index if not exists zchat_posts_user_voice on public.posts (user_id, created_at desc) where kind = 'voice';

create or replace function public.zchat_can_view_posts(p_viewer uuid, p_owner uuid)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  pr record;
  fol boolean;
  v text;
begin
  if p_owner is null or p_viewer is null then return false; end if;
  if p_viewer = p_owner then return true; end if;
  if public.zchat_blocked_pair(p_viewer, p_owner) then return false; end if;
  select p.is_private, p.privacy_profile, p.is_deleted, p.banned into pr from public.profiles p where p.id = p_owner;
  if not found or coalesce(pr.is_deleted, false) or coalesce(pr.banned, false) then return false; end if;
  fol := public.zchat_follows(p_viewer, p_owner);
  if coalesce(pr.is_private, false) and not fol then return false; end if;
  v := coalesce(pr.privacy_profile, 'everyone');
  if v = 'followers' and not fol then return false; end if;
  if v = 'chosen' and not exists (select 1 from public.privacy_allow a where a.user_id = p_owner and a.scope = 'privacy_profile' and a.viewer_id = p_viewer) then
    return false;
  end if;
  return true;
end $$;

create or replace function public.zchat_remix_block_reason(p_of uuid, p_user uuid)
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  o record;
  pr record;
begin
  select p.id, p.user_id, p.kind, p.remix_ok, p.archived_at, p.scheduled_for into o from public.posts p where p.id = p_of;
  if not found or o.archived_at is not null or (o.scheduled_for is not null and o.scheduled_for > now()) then
    return 'That post is not available anymore.';
  end if;
  if o.kind = 'voice' then return 'Voice posts cannot be remixed.'; end if;
  if not coalesce(o.remix_ok, true) then return 'Remixes are turned off for that post.'; end if;
  select p.is_private, p.privacy_profile, p.is_deleted, p.banned into pr from public.profiles p where p.id = o.user_id;
  if not found or coalesce(pr.is_deleted, false) or coalesce(pr.banned, false) then return 'That post is not available anymore.'; end if;
  if coalesce(pr.is_private, false) or coalesce(pr.privacy_profile, 'everyone') <> 'everyone' then
    return 'Only public posts can be remixed.';
  end if;
  if public.zchat_blocked_pair(p_user, o.user_id) then return 'That post is not available anymore.'; end if;
  return null;
end $$;

create or replace function public.zchat_posts_extras_guard()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  why text;
  el jsonb;
  cue jsonb;
  n integer;
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    new.id := old.id;
    new.user_id := old.user_id;
    new.media_url := old.media_url;
    new.media_type := old.media_type;
    new.overlay_url := old.overlay_url;
    new.media_urls := old.media_urls;
    new.kind := old.kind;
    new.voice := old.voice;
    new.poll := old.poll;
    new.remix_of := old.remix_of;
    new.remix_layout := old.remix_layout;
    new.pinned_at := old.pinned_at;
    if old.scheduled_for is not null and old.scheduled_for > now() then
      if new.scheduled_for is null or new.scheduled_for <= now() then
        new.scheduled_for := null;
        new.created_at := now();
      else
        if new.scheduled_for > now() + interval '60 days' then
          raise exception 'Pick a time in the next 60 days' using errcode = '22023';
        end if;
        new.created_at := new.scheduled_for;
      end if;
    else
      new.scheduled_for := old.scheduled_for;
      new.created_at := old.created_at;
    end if;
    if new.pinned_comment_id is distinct from old.pinned_comment_id and new.pinned_comment_id is not null
       and not exists (select 1 from public.post_comments c where c.id = new.pinned_comment_id and c.post_id = old.id) then
      raise exception 'That comment cannot be pinned' using errcode = '22023';
    end if;
    if new.archived_at is not null then
      new.archived_at := coalesce(old.archived_at, now());
    end if;
  else
    new.archived_at := null;
    new.pinned_at := null;
    if new.kind is not null and new.kind <> 'voice' then
      raise exception 'Unknown post kind' using errcode = '22023';
    end if;
    if new.kind = 'voice' then
      if new.voice is null or jsonb_typeof(new.voice) <> 'object'
         or coalesce(new.voice ->> 'u', '') !~* '^https?://'
         or not public.zchat_url_ok(new.voice ->> 'u')
         or char_length(new.voice ->> 'u') > 600
         or jsonb_typeof(new.voice -> 'd') <> 'number' or (new.voice ->> 'd')::numeric <= 0 or (new.voice ->> 'd')::numeric > 61
         or (new.voice ? 'w' and (jsonb_typeof(new.voice -> 'w') <> 'array' or jsonb_array_length(new.voice -> 'w') > 64)) then
        raise exception 'That voice clip cannot be posted' using errcode = '22023';
      end if;
      new.voice := jsonb_build_object('u', new.voice ->> 'u', 'd', round((new.voice ->> 'd')::numeric, 1), 'w', coalesce(new.voice -> 'w', '[]'::jsonb), 'c', coalesce(new.voice -> 'c' = 'true'::jsonb, false));
    elsif new.voice is not null then
      new.voice := null;
    end if;
    if new.poll is not null then
      if jsonb_typeof(new.poll) <> 'object' or jsonb_typeof(new.poll -> 'o') <> 'array'
         or jsonb_array_length(new.poll -> 'o') not between 2 and 4
         or char_length(coalesce(new.poll ->> 'q', '')) > 140 then
        raise exception 'That poll cannot be posted' using errcode = '22023';
      end if;
      for el in select * from jsonb_array_elements(new.poll -> 'o') loop
        if jsonb_typeof(el) <> 'string' or char_length(btrim(el #>> '{}')) not between 1 and 60 then
          raise exception 'Each poll choice needs 1 to 60 characters' using errcode = '22023';
        end if;
      end loop;
      if new.poll ? 'e' and new.poll ->> 'e' is not null then
        begin
          if (new.poll ->> 'e')::timestamptz < now() + interval '5 minutes' or (new.poll ->> 'e')::timestamptz > coalesce(new.scheduled_for, now()) + interval '31 days' then
            raise exception 'bad end';
          end if;
        exception when others then
          raise exception 'Pick a poll end time in the next 30 days' using errcode = '22023';
        end;
      end if;
      new.poll := jsonb_strip_nulls(jsonb_build_object('q', nullif(btrim(coalesce(new.poll ->> 'q', '')), ''), 'o', new.poll -> 'o', 'e', new.poll ->> 'e'));
    end if;
    if new.remix_of is not null then
      why := public.zchat_remix_block_reason(new.remix_of, new.user_id);
      if why is not null then
        raise exception '%', why using errcode = '42501';
      end if;
      new.remix_layout := coalesce(new.remix_layout, 'side');
    else
      new.remix_layout := null;
    end if;
  end if;
  if new.alt_texts is not null then
    if jsonb_typeof(new.alt_texts) <> 'array' or jsonb_array_length(new.alt_texts) > 10 then
      raise exception 'Alt text cannot be saved' using errcode = '22023';
    end if;
    for el in select * from jsonb_array_elements(new.alt_texts) loop
      if not (jsonb_typeof(el) = 'null' or (jsonb_typeof(el) = 'string' and char_length(el #>> '{}') <= 300)) then
        raise exception 'Alt text can be up to 300 characters' using errcode = '22023';
      end if;
    end loop;
  end if;
  if new.captions is not null then
    if jsonb_typeof(new.captions) <> 'array' or jsonb_array_length(new.captions) > 10 or octet_length(new.captions::text) > 90000 then
      raise exception 'Captions cannot be saved' using errcode = '22023';
    end if;
    for el in select * from jsonb_array_elements(new.captions) loop
      if jsonb_typeof(el) = 'null' then continue; end if;
      if jsonb_typeof(el) <> 'object' or jsonb_typeof(el -> 'c') <> 'array' or jsonb_array_length(el -> 'c') > 800 or char_length(coalesce(el ->> 'l', '')) > 12 then
        raise exception 'Captions cannot be saved' using errcode = '22023';
      end if;
      for cue in select * from jsonb_array_elements(el -> 'c') loop
        if jsonb_typeof(cue) <> 'array' or jsonb_array_length(cue) <> 3
           or jsonb_typeof(cue -> 0) <> 'number' or jsonb_typeof(cue -> 1) <> 'number' or jsonb_typeof(cue -> 2) <> 'string'
           or char_length(cue ->> 2) > 240 then
          raise exception 'Captions cannot be saved' using errcode = '22023';
        end if;
      end loop;
    end loop;
  end if;
  return new;
end $$;

drop trigger if exists zchat_posts_extras_guard on public.posts;
create trigger zchat_posts_extras_guard before insert or update on public.posts
  for each row execute function public.zchat_posts_extras_guard();

drop policy if exists "zchat posts update own" on public.posts;
create policy "zchat posts update own" on public.posts for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

create or replace function public.zchat_post_remix_notify()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  owner uuid;
begin
  begin
    if new.remix_of is null then return null; end if;
    select p.user_id into owner from public.posts p where p.id = new.remix_of;
    if owner is not null and owner <> new.user_id then
      perform public.zchat_notify(owner, new.user_id, 'remix', new.id, 'remixed your post.', jsonb_build_object('of', new.remix_of::text),
        greatest(coalesce(new.scheduled_for, now()), now()));
    end if;
  exception when others then
    raise notice 'remix notify skipped: %', sqlerrm;
  end;
  return null;
end $$;

drop trigger if exists zchat_post_remix_notify on public.posts;
create trigger zchat_post_remix_notify after insert on public.posts
  for each row execute function public.zchat_post_remix_notify();

revoke all on function public.zchat_remix_block_reason(uuid, uuid) from public, anon;
grant execute on function public.zchat_remix_block_reason(uuid, uuid) to authenticated;
revoke all on function public.zchat_can_view_posts(uuid, uuid) from public, anon;
grant execute on function public.zchat_can_view_posts(uuid, uuid) to authenticated;
commit;

begin;
drop policy if exists "zchat archived posts" on public.posts;
create policy "zchat archived posts" on public.posts as restrictive for select to anon, authenticated
  using (archived_at is null or user_id = (select auth.uid()));

drop policy if exists "zchat likes need a visible post" on public.post_likes;
create policy "zchat likes need a visible post" on public.post_likes as restrictive for insert to authenticated
  with check (exists (select 1 from public.posts p where p.id = post_likes.post_id));

create or replace function public.zchat_post_visible(p_post uuid)
 returns uuid
 language sql
 stable security definer
 set search_path to 'public'
as $function$
      select p.user_id from public.posts p
      where p.id = p_post and (p.scheduled_for is null or p.scheduled_for <= now() or p.user_id = auth.uid())
        and (p.archived_at is null or p.user_id = auth.uid())
    $function$;

create or replace function public.zchat_post_count(p_user uuid)
 returns integer
 language sql
 stable security definer
 set search_path to 'public'
as $function$
  select count(*)::integer from public.posts p
  where p.user_id = p_user and (p.scheduled_for is null or p.scheduled_for <= now() or p.user_id = auth.uid())
    and p.archived_at is null
$function$;

create or replace function public.zchat_comment_ok(p_post uuid)
 returns boolean
 language sql
 stable security definer
 set search_path to 'public'
as $function$
        select coalesce((
          select case
            when p.user_id = auth.uid() then true
            when p.archived_at is not null then false
            when p.scheduled_for is not null and p.scheduled_for > now() then false
            when coalesce(p.comments_off, false) then false
            else public.zchat_can_interact_as(auth.uid(), 'comment', p.user_id)
          end
          from public.posts p where p.id = p_post
        ), false)
      $function$;

create or replace function public.public_post_preview(p_id text)
 returns jsonb
 language plpgsql
 stable security definer
 set search_path to 'public'
as $function$
declare
  po public.posts%rowtype;
  o public.profiles%rowtype;
  card jsonb;
  n_likes int;
  n_comments int;
  noidx boolean := false;
begin
  select * into po from public.posts where id::text = p_id limit 1;
  if not found or (po.scheduled_for is not null and po.scheduled_for > now()) or po.archived_at is not null then
    return jsonb_build_object('found', false);
  end if;
  select * into o from public.profiles pr where pr.id = po.user_id;
  if not found or coalesce(o.is_deleted, false) or coalesce(o.banned, false) then
    return jsonb_build_object('found', false);
  end if;
  card := jsonb_build_object('id', o.id, 'name', o.name, 'username', o.username,
    'avatar', case when coalesce(o.hide_photo, false) then '' else coalesce(o.avatar, '') end,
    'avatar_frame', to_jsonb(o.avatar_frame), 'verified', to_jsonb(o.verified), 'custom_badge', to_jsonb(o.custom_badge));
  if to_regprocedure('public.zchat_search_visible(uuid)') is not null then
    execute 'select not public.zchat_search_visible($1)' into noidx using po.user_id;
  end if;
  if not public.zchat_owner_visible(po.user_id, 'posts') then
    return jsonb_build_object('found', true, 'restricted', true, 'owner', card, 'noindex', coalesce(noidx, false));
  end if;
  select count(*) into n_likes from public.post_likes where post_id = po.id;
  select count(*) into n_comments from public.post_comments where post_id = po.id;
  return jsonb_build_object('found', true, 'restricted', false, 'owner', card, 'media_url', po.media_url,
    'media_type', po.media_type, 'caption', po.caption, 'created_at', po.created_at, 'likes', n_likes, 'comments', n_comments,
    'noindex', coalesce(noidx, false));
end
$function$;

create or replace function public.public_profile_preview(p_id text)
 returns jsonb
 language plpgsql
 stable security definer
 set search_path to 'public'
as $function$
declare
  p public.profiles%rowtype;
  priv boolean;
  open_profile boolean;
  posts jsonb := '[]'::jsonb;
  n_posts int;
  n_foll int;
  n_fing int;
  noidx boolean := false;
begin
  select * into p from public.profiles where id::text = p_id limit 1;
  if not found or coalesce(p.is_deleted, false) or coalesce(p.banned, false) then
    return jsonb_build_object('found', false);
  end if;
  priv := coalesce(p.is_private, false);
  open_profile := public.zchat_owner_visible(p.id, 'posts');
  if to_regprocedure('public.zchat_search_visible(uuid)') is not null then
    execute 'select not public.zchat_search_visible($1)' into noidx using p.id;
  end if;
  select count(*) into n_posts from public.posts x where x.user_id = p.id and (x.scheduled_for is null or x.scheduled_for <= now()) and x.archived_at is null;
  select count(*) into n_foll from public.follows where following_id = p.id and status = 'accepted';
  select count(*) into n_fing from public.follows where follower_id = p.id and status = 'accepted';
  if open_profile then
    select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'media_url', x.media_url, 'media_type', x.media_type)), '[]'::jsonb)
      into posts
      from (select id, media_url, media_type from public.posts
            where user_id = p.id and (scheduled_for is null or scheduled_for <= now()) and archived_at is null
            order by created_at desc limit 9) x;
  end if;
  return jsonb_build_object('found', true, 'id', p.id, 'name', p.name, 'username', p.username,
    'avatar', case when coalesce(p.hide_photo, false) then '' else coalesce(p.avatar, '') end,
    'avatar_frame', to_jsonb(p.avatar_frame), 'verified', to_jsonb(p.verified), 'custom_badge', to_jsonb(p.custom_badge),
    'bio', case when open_profile and not coalesce(p.hide_bio, false) and public.zchat_pv_allows(p.privacy_bio, 'privacy_bio', false, false, null) then coalesce(p.bio, '') else '' end,
    'is_private', priv, 'posts_count', n_posts, 'followers_count', n_foll, 'following_count', n_fing, 'posts', posts,
    'noindex', coalesce(noidx, false));
end
$function$;

create or replace function public.zchat_trending_tags(p_days integer default 7, p_limit integer default 24)
 returns table(tag text, n integer, people integer, sample_url text, sample_id text)
 language sql
 stable security definer
 set search_path to 'public'
as $function$
      with recent as (
        select p.id, p.user_id, p.media_url, p.media_type, p.created_at, lower(p.caption) as cap
        from public.posts p
        join public.profiles pr on pr.id = p.user_id
        where p.created_at > now() - make_interval(days => greatest(1, least(coalesce(p_days, 7), 30)))
          and p.created_at <= now()
          and (p.scheduled_for is null or p.scheduled_for <= now())
          and p.archived_at is null
          and p.caption like '%#%'
          and not coalesce(pr.is_private, false) and not coalesce(pr.is_deleted, false) and not coalesce(pr.banned, false)
          and not public.zchat_blocked_pair(auth.uid(), p.user_id)
        order by p.created_at desc
        limit 3000
      ),
      tags as (
        select r.id, r.user_id, r.media_url, r.media_type, r.created_at, m[1] as tag
        from recent r, lateral regexp_matches(r.cap, '#([[:alnum:]_]{2,40})', 'g') m
      )
      select t.tag, count(distinct t.id)::integer, count(distinct t.user_id)::integer,
        (array_agg(t.media_url order by t.created_at desc) filter (where coalesce(t.media_type, 'image') <> 'video' and t.media_url is not null))[1],
        (array_agg(t.id::text order by t.created_at desc) filter (where coalesce(t.media_type, 'image') <> 'video' and t.media_url is not null))[1]
      from tags t
      group by t.tag
      order by count(distinct t.user_id) desc, count(distinct t.id) desc, t.tag
      limit greatest(1, least(coalesce(p_limit, 24), 50))
    $function$;

create or replace function public.zchat_tip_post(p_post uuid, p_amount integer, p_note text default null::text)
 returns jsonb
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  me uuid := auth.uid();
  v_note text := nullif(btrim(left(regexp_replace(regexp_replace(left(coalesce(p_note, ''), 400), '[[:cntrl:]]+', ' ', 'g'), '[\u200B\u200E\u200F\u202A-\u202E\u2060-\u2069\uFEFF]+', '', 'g'), 80)), '');
  v_owner uuid;
  v_sched timestamptz;
  v_collab uuid;
  v_collab_ok text;
  v_owner_user text;
  v_my_user text;
  v_day_coins bigint;
  v_day_n bigint;
  v_bal integer;
  v_tip public.post_tips;
  v_archived timestamptz;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if p_amount is null or p_amount < 1 or p_amount > 5000 then
    return jsonb_build_object('ok', false, 'reason', 'Tip between 1 and 5,000 coins.');
  end if;
  if exists (select 1 from public.profiles p where p.id = me and (coalesce(p.banned, false) or coalesce(p.is_deleted, false) or coalesce(p.is_bot, false))) then
    return jsonb_build_object('ok', false, 'reason', 'Your account cannot send tips right now.');
  end if;
  select p.user_id, p.scheduled_for, p.collab_id, p.collab_status, p.archived_at into v_owner, v_sched, v_collab, v_collab_ok, v_archived from public.posts p where p.id = p_post;
  if v_owner is null or (v_sched is not null and v_sched > now() and v_owner <> me) or (v_archived is not null and v_owner <> me) then
    return jsonb_build_object('ok', false, 'reason', 'This post is not available anymore.');
  end if;
  if v_owner = me or (v_collab = me and v_collab_ok = 'accepted') then
    return jsonb_build_object('ok', false, 'reason', 'You cannot tip your own post.');
  end if;
  if exists (select 1 from public.profiles p where p.id = v_owner and (coalesce(p.banned, false) or coalesce(p.is_deleted, false) or coalesce(p.is_bot, false))) then
    return jsonb_build_object('ok', false, 'reason', 'This account cannot get tips.');
  end if;
  if public.zchat_blocked_pair(me, v_owner) or not public.zchat_owner_visible(v_owner, 'posts') then
    return jsonb_build_object('ok', false, 'reason', 'This post is not available anymore.');
  end if;
  if coalesce(public.zchat_account_created(me) > now() - interval '1 day', true)
     and not exists (select 1 from public.coin_orders o where o.user_id = me and o.status = 'paid') then
    return jsonb_build_object('ok', false, 'reason', 'New accounts can send tips after their first day.');
  end if;
  insert into public.wallets (user_id) values (me), (v_owner) on conflict (user_id) do nothing;
  perform 1 from public.wallets w where w.user_id in (me, v_owner) order by w.user_id for update;
  select coalesce(sum(-l.delta), 0), count(*) into v_day_coins, v_day_n
    from public.coin_ledger l where l.user_id = me and l.reason = 'tip_out' and l.created_at > now() - interval '1 day';
  if v_day_n >= 30 then
    return jsonb_build_object('ok', false, 'reason', 'You sent a lot of tips today. Try again tomorrow.');
  end if;
  if v_day_coins + p_amount > 5000 then
    return jsonb_build_object('ok', false, 'reason', 'You can tip up to 5,000 coins a day. You have ' || to_char(greatest(5000 - v_day_coins, 0), 'FM9,999') || ' left today.', 'left', greatest(5000 - v_day_coins, 0));
  end if;
  if (select coalesce(sum(l.delta), 0) from public.coin_ledger l where l.user_id = v_owner and l.reason = 'tip_in' and l.created_at > now() - interval '1 day') + p_amount > 10000 then
    return jsonb_build_object('ok', false, 'reason', 'They got a lot of tips today. Try again tomorrow.');
  end if;
  select coalesce(p.username, 'someone') into v_owner_user from public.profiles p where p.id = v_owner;
  select coalesce(p.username, 'someone') into v_my_user from public.profiles p where p.id = me;
  v_bal := public.zchat_coins_move(me, -p_amount, 'tip_out', 'Tip for @' || v_owner_user, v_owner);
  if v_bal is null then
    return jsonb_build_object('ok', false, 'reason', 'You do not have enough coins.');
  end if;
  if public.zchat_coins_move(v_owner, p_amount, 'tip_in', 'Tip from @' || v_my_user, me) is null then
    raise exception 'The tip could not be delivered' using errcode = 'P0001';
  end if;
  insert into public.post_tips (post_id, owner_id, tipper_id, amount, note)
    values (p_post, v_owner, me, p_amount, v_note)
    returning * into v_tip;
  perform public.zchat_notify(v_owner, me, 'tip', p_post,
    'tipped ' || to_char(p_amount, 'FM9,999') || case when p_amount = 1 then ' coin' else ' coins' end || ' on your post' || coalesce(': "' || v_note || '"', ''),
    jsonb_build_object('coins', p_amount, 'note', v_note, 'tip', v_tip.id));
  return jsonb_build_object('ok', true, 'coins', v_bal, 'tip', jsonb_build_object('id', v_tip.id, 'post_id', v_tip.post_id, 'amount', v_tip.amount, 'created_at', v_tip.created_at));
end $function$;
commit;

begin;
create table if not exists public.zchat_post_tags (
  id uuid primary key default gen_random_uuid(),
  post_id uuid not null references public.posts(id) on delete cascade,
  tagger_id uuid not null references public.profiles(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  media_idx smallint not null default 0 check (media_idx between 0 and 9),
  x real not null check (x >= 0 and x <= 1),
  y real not null check (y >= 0 and y <= 1),
  status text not null default 'pending' check (status in ('pending', 'approved', 'removed')),
  created_at timestamptz not null default now(),
  decided_at timestamptz,
  unique (post_id, user_id, media_idx)
);
create index if not exists zchat_post_tags_user on public.zchat_post_tags (user_id, status, created_at desc);
create index if not exists zchat_post_tags_post on public.zchat_post_tags (post_id);
create index if not exists zchat_post_tags_tagger on public.zchat_post_tags (tagger_id, created_at desc);

create table if not exists public.zchat_tag_settings (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  auto text not null default 'ask' check (auto in ('ask', 'following')),
  updated_at timestamptz not null default now()
);

alter table public.zchat_post_tags enable row level security;
alter table public.zchat_tag_settings enable row level security;
revoke all on public.zchat_post_tags from anon;
revoke all on public.zchat_tag_settings from anon;
grant select, insert, delete on public.zchat_post_tags to authenticated;
revoke update on public.zchat_post_tags from authenticated;
grant select, insert, update on public.zchat_tag_settings to authenticated;

drop policy if exists "zchat tags read" on public.zchat_post_tags;
create policy "zchat tags read" on public.zchat_post_tags for select to authenticated using (
  user_id = (select auth.uid()) or tagger_id = (select auth.uid())
  or (status <> 'removed' and exists (select 1 from public.posts p where p.id = zchat_post_tags.post_id))
);
drop policy if exists "zchat tags add" on public.zchat_post_tags;
create policy "zchat tags add" on public.zchat_post_tags for insert to authenticated with check (tagger_id = (select auth.uid()));
drop policy if exists "zchat tags take back" on public.zchat_post_tags;
create policy "zchat tags take back" on public.zchat_post_tags for delete to authenticated using (tagger_id = (select auth.uid()) and status <> 'removed');

drop policy if exists "zchat tag settings own" on public.zchat_tag_settings;
create policy "zchat tag settings own" on public.zchat_tag_settings for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

create or replace function public.zchat_tag_block_reason(p_post uuid, p_tagger uuid, p_user uuid, p_idx integer)
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  po record;
  pr record;
  n_media integer;
  is_video boolean;
  v text;
begin
  select p.user_id, p.media_type, p.media_urls, p.kind, p.archived_at into po from public.posts p where p.id = p_post;
  if not found or po.user_id <> p_tagger then return 'You can only tag people in your own photos.'; end if;
  if po.archived_at is not null then return 'Show the post on your profile again to tag people.'; end if;
  if po.kind = 'voice' then return 'Voice posts cannot have tags.'; end if;
  if p_user = p_tagger then return 'You cannot tag yourself.'; end if;
  if jsonb_typeof(po.media_urls) = 'array' and jsonb_array_length(po.media_urls) > 0 then
    n_media := jsonb_array_length(po.media_urls);
    is_video := coalesce(po.media_urls -> p_idx ->> 't', '') = 'video';
  else
    n_media := 1;
    is_video := po.media_type = 'video';
  end if;
  if p_idx < 0 or p_idx >= n_media then return 'That photo is not in the post.'; end if;
  if is_video then return 'Tags work on photos.'; end if;
  select p.privacy_tags, p.is_deleted, p.banned, p.is_bot into pr from public.profiles p where p.id = p_user;
  if not found or coalesce(pr.is_deleted, false) or coalesce(pr.banned, false) or coalesce(pr.is_bot, false) then
    return 'That account cannot be tagged.';
  end if;
  if public.zchat_blocked_pair(p_tagger, p_user) then return 'That account cannot be tagged.'; end if;
  v := coalesce(pr.privacy_tags, 'everyone');
  if v in ('nobody', 'off') then return 'They do not allow tags.'; end if;
  if v = 'followers' and not public.zchat_follows(p_tagger, p_user) then return 'They only allow tags from their followers.'; end if;
  if v = 'chosen' and not exists (select 1 from public.privacy_allow a where a.user_id = p_user and a.scope = 'privacy_tags' and a.viewer_id = p_tagger) then
    return 'They only allow tags from people they chose.';
  end if;
  if not public.zchat_can_view_posts(p_user, p_tagger) then return 'They cannot see your posts, so they cannot be tagged.'; end if;
  if (select count(*) from public.zchat_post_tags t where t.post_id = p_post and t.media_idx = p_idx) >= 20 then
    return 'A photo can have up to 20 tags.';
  end if;
  if (select count(*) from public.zchat_post_tags t where t.tagger_id = p_tagger and t.created_at > now() - interval '1 day') >= 150 then
    return 'You tagged a lot of people today. Try again tomorrow.';
  end if;
  return null;
end $$;

create or replace function public.zchat_post_tags_guard()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  why text;
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;
  why := public.zchat_tag_block_reason(new.post_id, new.tagger_id, new.user_id, new.media_idx);
  if why is not null then
    raise exception '%', why using errcode = '42501';
  end if;
  new.created_at := now();
  if public.zchat_tag_auto_ok(new.user_id, new.tagger_id) then
    new.status := 'approved';
    new.decided_at := now();
  else
    new.status := 'pending';
    new.decided_at := null;
  end if;
  return new;
end $$;

create or replace function public.zchat_tag_auto_ok(p_user uuid, p_tagger uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((select s.auto = 'following' from public.zchat_tag_settings s where s.user_id = p_user), false)
    and public.zchat_follows(p_user, p_tagger)
$$;

drop trigger if exists zchat_post_tags_guard on public.zchat_post_tags;
create trigger zchat_post_tags_guard before insert on public.zchat_post_tags
  for each row execute function public.zchat_post_tags_guard();

create or replace function public.zchat_post_tags_notify()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  at timestamptz;
begin
  begin
    if tg_op = 'DELETE' then
      delete from public.notifications n where n.kind = 'photo_tag' and n.meta ->> 'tag' = old.id::text;
      return null;
    end if;
    select greatest(coalesce(p.scheduled_for, now()), now()) into at from public.posts p where p.id = new.post_id;
    perform public.zchat_notify(new.user_id, new.tagger_id, 'photo_tag', new.post_id,
      case when new.status = 'approved' then 'tagged you in a photo.' else 'tagged you in a photo. Approve it to show it on your profile.' end,
      jsonb_build_object('tag', new.id::text), at);
  exception when others then
    raise notice 'tag notify skipped: %', sqlerrm;
  end;
  return null;
end $$;

drop trigger if exists zchat_post_tags_notify on public.zchat_post_tags;
create trigger zchat_post_tags_notify after insert or delete on public.zchat_post_tags
  for each row execute function public.zchat_post_tags_notify();

create or replace function public.zchat_tag_decide(p_tag uuid, p_action text)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  t record;
begin
  if me is null or p_tag is null or p_action not in ('approve', 'remove') then return false; end if;
  select * into t from public.zchat_post_tags where id = p_tag for update;
  if not found or t.user_id <> me then return false; end if;
  if p_action = 'approve' then
    if t.status = 'removed' then return false; end if;
    update public.zchat_post_tags set status = 'approved', decided_at = now() where id = p_tag;
  else
    update public.zchat_post_tags set status = 'removed', decided_at = now() where id = p_tag;
    delete from public.notifications n where n.user_id = me and n.kind = 'photo_tag' and n.meta ->> 'tag' = p_tag::text;
  end if;
  return true;
end $$;

create or replace function public.zchat_tagged_posts(p_user uuid, p_limit integer default 60)
returns setof public.posts
language sql
stable
security invoker
set search_path = public
as $$
  select p.* from public.posts p
  where p.id in (select t.post_id from public.zchat_post_tags t where t.user_id = p_user and t.status = 'approved')
  order by p.created_at desc
  limit greatest(1, least(coalesce(p_limit, 60), 120))
$$;

revoke all on function public.zchat_tag_block_reason(uuid, uuid, uuid, integer) from public, anon;
grant execute on function public.zchat_tag_block_reason(uuid, uuid, uuid, integer) to authenticated;
revoke all on function public.zchat_tag_auto_ok(uuid, uuid) from public, anon;
grant execute on function public.zchat_tag_auto_ok(uuid, uuid) to authenticated;
revoke all on function public.zchat_tag_decide(uuid, text) from public, anon;
grant execute on function public.zchat_tag_decide(uuid, text) to authenticated;
revoke all on function public.zchat_tagged_posts(uuid, integer) from public, anon;
grant execute on function public.zchat_tagged_posts(uuid, integer) to authenticated;

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'zchat_post_tags') then
    execute 'alter publication supabase_realtime add table public.zchat_post_tags';
  end if;
end $$;

select public.zchat_apply_session_gate();

create table if not exists public.zchat_post_poll_votes (
  post_id uuid not null references public.posts(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  choice smallint not null check (choice between 0 and 3),
  created_at timestamptz not null default now(),
  primary key (post_id, user_id)
);
create index if not exists zchat_post_poll_votes_user on public.zchat_post_poll_votes (user_id, created_at desc);

create table if not exists public.zchat_post_poll_counts (
  post_id uuid primary key references public.posts(id) on delete cascade,
  counts integer[] not null default '{0,0,0,0}',
  total integer not null default 0,
  updated_at timestamptz not null default now()
);

alter table public.zchat_post_poll_votes enable row level security;
alter table public.zchat_post_poll_counts enable row level security;
revoke all on public.zchat_post_poll_votes from anon;
revoke all on public.zchat_post_poll_counts from anon;
revoke insert, update, delete on public.zchat_post_poll_votes from authenticated;
revoke insert, update, delete on public.zchat_post_poll_counts from authenticated;
grant select on public.zchat_post_poll_votes to authenticated;
grant select on public.zchat_post_poll_counts to authenticated;

drop policy if exists "zchat poll votes own" on public.zchat_post_poll_votes;
create policy "zchat poll votes own" on public.zchat_post_poll_votes for select to authenticated using (user_id = (select auth.uid()));

drop policy if exists "zchat poll counts after voting" on public.zchat_post_poll_counts;
create policy "zchat poll counts after voting" on public.zchat_post_poll_counts for select to authenticated using (
  exists (select 1 from public.posts p where p.id = zchat_post_poll_counts.post_id and (
    p.user_id = (select auth.uid())
    or (p.poll ->> 'e' is not null and (p.poll ->> 'e')::timestamptz <= now())
    or exists (select 1 from public.zchat_post_poll_votes v where v.post_id = p.id and v.user_id = (select auth.uid()))
  ))
);

create or replace function public.zchat_post_poll_vote(p_post uuid, p_choice integer)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  po record;
  n integer;
  c record;
begin
  if me is null then return jsonb_build_object('ok', false, 'reason', 'Log in first.'); end if;
  if (select count(*) from public.zchat_post_poll_votes v where v.user_id = me and v.created_at > now() - interval '1 minute') >= 30 then
    return jsonb_build_object('ok', false, 'reason', 'You voted a lot just now. Try again in a minute.');
  end if;
  select p.id, p.user_id, p.poll, p.archived_at, p.scheduled_for into po from public.posts p where p.id = p_post;
  if not found or po.poll is null then return jsonb_build_object('ok', false, 'reason', 'This poll is not available anymore.'); end if;
  if po.user_id <> me and (po.archived_at is not null or (po.scheduled_for is not null and po.scheduled_for > now()) or not public.zchat_can_view_posts(me, po.user_id)) then
    return jsonb_build_object('ok', false, 'reason', 'This poll is not available anymore.');
  end if;
  n := jsonb_array_length(po.poll -> 'o');
  if p_choice is null or p_choice < 0 or p_choice >= n then return jsonb_build_object('ok', false, 'reason', 'Pick one of the choices.'); end if;
  if po.poll ->> 'e' is not null and (po.poll ->> 'e')::timestamptz <= now() then
    return jsonb_build_object('ok', false, 'reason', 'This poll has ended.', 'ended', true);
  end if;
  insert into public.zchat_post_poll_votes (post_id, user_id, choice) values (p_post, me, p_choice) on conflict do nothing;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'You already voted.', 'voted', true);
  end if;
  insert into public.zchat_post_poll_counts (post_id) values (p_post) on conflict (post_id) do nothing;
  update public.zchat_post_poll_counts
    set counts[p_choice + 1] = coalesce(counts[p_choice + 1], 0) + 1, total = total + 1, updated_at = now()
    where post_id = p_post
    returning counts, total into c;
  return jsonb_build_object('ok', true, 'mine', p_choice, 'counts', to_jsonb(c.counts[1:n]), 'total', c.total);
end $$;

revoke all on function public.zchat_post_poll_vote(uuid, integer) from public, anon;
grant execute on function public.zchat_post_poll_vote(uuid, integer) to authenticated;

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'zchat_post_poll_counts') then
    execute 'alter publication supabase_realtime add table public.zchat_post_poll_counts';
  end if;
end $$;

select public.zchat_apply_session_gate();

create index if not exists zchat_post_events_user_time on public.post_events (user_id, created_at desc);

create or replace function public.zchat_post_event(p_post uuid, p_kind text)
 returns boolean
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
    declare
      me uuid := auth.uid();
      owner uuid;
      v_collab uuid;
      v_collab_ok text;
    begin
      if me is null or p_post is null or p_kind not in ('view', 'share', 'profile') then
        return false;
      end if;
      owner := public.zchat_post_visible(p_post);
      if owner is null or owner = me or public.zchat_blocked_pair(me, owner) then
        return false;
      end if;
      select p.collab_id, p.collab_status into v_collab, v_collab_ok from public.posts p where p.id = p_post;
      if v_collab = me and v_collab_ok = 'accepted' then
        return false;
      end if;
      if not public.zchat_can_view_posts(me, owner) then
        return false;
      end if;
      if (select count(*) from public.post_events e where e.user_id = me and e.created_at > now() - interval '10 minutes') >= 400 then
        return false;
      end if;
      insert into public.post_events (post_id, user_id, kind, day) values (p_post, me, p_kind, current_date)
      on conflict do nothing;
      return true;
    end $function$;

create or replace function public.zchat_post_views(p_posts uuid[])
returns table(post_id uuid, views integer)
language sql
stable
security definer
set search_path = public
as $$
  select p.id, (select count(distinct e.user_id)::integer from public.post_events e where e.post_id = p.id and e.kind = 'view')
  from public.posts p
  where p.id = any ((coalesce(p_posts, '{}'::uuid[]))[1:200]) and p.user_id = auth.uid()
$$;

revoke all on function public.zchat_post_views(uuid[]) from public, anon;
grant execute on function public.zchat_post_views(uuid[]) to authenticated;

create or replace function public.zchat_comment_gif_guard()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;
  if coalesce(new.content, '') like 'gif:%'
     and new.content !~ '^gif:https://(media[0-9]?|i)\.giphy\.com/media/[A-Za-z0-9._/-]{1,240}\.(gif|webp)(#[0-9]{1,4}x[0-9]{1,4})?$' then
    raise exception 'That GIF cannot be posted' using errcode = '22023';
  end if;
  return new;
end $$;

drop trigger if exists zchat_comment_gif_guard on public.post_comments;
create trigger zchat_comment_gif_guard before insert or update of content on public.post_comments
  for each row execute function public.zchat_comment_gif_guard();

create or replace function public.zchat_comment_notify()
 returns trigger
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  owner uuid;
  par_user uuid;
  body text;
  snippet text;
  meta jsonb;
  mid uuid;
  par_id text;
begin
  begin
    if tg_op = 'DELETE' then
      delete from public.notifications n where n.meta ->> 'comment_id' = old.id::text;
      return null;
    end if;
    body := coalesce(to_jsonb(new) ->> 'content', to_jsonb(new) ->> 'text', '');
    snippet := case when body like 'sticker:%' or body like 'gif:%' then null else left(body, 120) end;
    meta := jsonb_build_object('comment_id', new.id::text);
    select p.user_id into owner from public.posts p where p.id = new.post_id;
    par_id := to_jsonb(new) ->> 'parent_id';
    if par_id is not null then
      execute 'select user_id from public.post_comments where id::text = $1' into par_user using par_id;
    end if;
    if par_user is not null and par_user <> new.user_id then
      perform public.zchat_notify(par_user, new.user_id, 'reply', new.post_id, snippet, meta);
    end if;
    if owner is not null and owner <> new.user_id and owner is distinct from par_user then
      perform public.zchat_notify(owner, new.user_id, 'comment', new.post_id, snippet, meta);
    end if;
    for mid in select * from public.zchat_mentioned_users(body, 5) loop
      if mid <> new.user_id and mid is distinct from owner and mid is distinct from par_user
        and public.zchat_can_interact_as(new.user_id, 'mention', mid) then
        perform public.zchat_notify(mid, new.user_id, 'mention', new.post_id, snippet, meta);
      end if;
    end loop;
  exception when others then
    raise notice 'comment notify skipped: %', sqlerrm;
  end;
  return null;
end $function$;

create or replace function public.zchat_break_call_guard()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  if new.callee_id is not null and new.callee_id is distinct from new.caller_id and public.zchat_on_break(new.callee_id) then
    raise exception 'They are taking a break, so calls are paused' using errcode = '42501';
  end if;
  return new;
end
$$;
revoke all on function public.zchat_break_call_guard() from public, anon, authenticated;

drop trigger if exists zchat_break_call_guard on public.calls;
create trigger zchat_break_call_guard
  before insert on public.calls
  for each row execute function public.zchat_break_call_guard();

do $$
declare
  v_sig text;
  v_open text;
begin
  select string_agg(p.oid::regprocedure::text, ', ') into v_sig
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'zchat_notify';
  if v_sig is null then
    return;
  end if;
  select string_agg(p.proname, ', ') into v_open
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname <> 'zchat_notify' and not p.prosecdef and p.prosrc ilike '%zchat_notify%';
  if v_open is not null then
    raise notice 'zchat safety: zchat_notify stays open because these functions call it without security definer: %', v_open;
    return;
  end if;
  execute (
    select string_agg(format('revoke execute on function %s from public, anon, authenticated; grant execute on function %s to service_role;', p.oid::regprocedure, p.oid::regprocedure), ' ')
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'zchat_notify'
  );
end $$;
commit;

begin;
create or replace function public.zchat_name_key(p text)
returns text
language plpgsql
immutable
set search_path = public
as $$
declare
  s text := lower(coalesce(p, ''));
begin
  s := translate(s, (select string_agg(chr(u.c), '' order by u.o) from unnest('{1072,1077,1086,1088,1089,1091,1093,1082,1084,1090,1074,1085,1109,1110,1112,1281,609,1231,1211,1307,1309,1199,959,945,961,964,965,957,954,956,967,953,949,951,946,947,1409,1413,1405,1392,1400,224,225,226,227,228,229,257,259,261,231,263,269,271,232,233,234,235,275,279,281,283,287,236,237,238,239,299,303,305,318,322,241,324,328,242,243,244,245,246,248,333,337,345,347,353,351,357,249,250,251,252,363,367,369,371,253,255,382,378,380,64,36,33,124,65345,65346,65347,65348,65349,65350,65351,65352,65353,65354,65355,65356,65357,65358,65359,65360,65361,65362,65363,65364,65365,65366,65367,65368,65369,65370}'::int[]) with ordinality as u(c, o)), 'aeopcyxkmtbhsijdglhqwyoaptuvkmxienbygouhnaaaaaaaaacccdeeeeeeeegiiiiiiillnnnoooooooorssstuuuuuuuuyyzzzasilabcdefghijklmnopqrstuvwxyz');
  s := regexp_replace(s, '[._\-]+', ' ', 'g');
  s := regexp_replace(s, '\m(official|offical|real|the|its|im|iam|support|team|help|helpdesk|service|services|care|admin|admins|verified|original|page|account|hq|tv|fan|fans|fanpage|club|backup|private|alt)\M', ' ', 'g');
  s := regexp_replace(s, '[0-9]+\s*$', '');
  s := translate(s, '013457890', 'oleastbgo');
  s := regexp_replace(s, '[^a-z]', '', 'g');
  s := replace(replace(s, 'rn', 'm'), 'vv', 'w');
  s := regexp_replace(s, '^(the|real|official|its|get|team|my)?zchat(support|team|official|offical|help|helpdesk|admin|admins|security|staff|care|service|services|app|bot|hq|verify|verification|mod|moderator|login|account|accounts|safety|update|updates|news)*$', 'zchat');
  s := translate(s, 'i', 'l');
  s := regexp_replace(s, '(.)\1+', '\1', 'g');
  return s;
end $$;
revoke all on function public.zchat_name_key(text) from public, anon;
grant execute on function public.zchat_name_key(text) to authenticated, service_role;

create or replace function public.zchat_tip_post(p_post uuid, p_amount integer, p_note text default null::text)
 returns jsonb
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  me uuid := auth.uid();
  v_note text := nullif(btrim(left(regexp_replace(regexp_replace(left(coalesce(p_note, ''), 400), '[[:cntrl:]]+', ' ', 'g'), '[' || chr(8203) || chr(8206) || chr(8207) || chr(8234) || '-' || chr(8238) || chr(8288) || '-' || chr(8297) || chr(65279) || ']+', '', 'g'), 80)), '');
  v_owner uuid;
  v_sched timestamptz;
  v_collab uuid;
  v_collab_ok text;
  v_owner_user text;
  v_my_user text;
  v_day_coins bigint;
  v_day_n bigint;
  v_bal integer;
  v_tip public.post_tips;
  v_archived timestamptz;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if p_amount is null or p_amount < 1 or p_amount > 5000 then
    return jsonb_build_object('ok', false, 'reason', 'Tip between 1 and 5,000 coins.');
  end if;
  if exists (select 1 from public.profiles p where p.id = me and (coalesce(p.banned, false) or coalesce(p.is_deleted, false) or coalesce(p.is_bot, false))) then
    return jsonb_build_object('ok', false, 'reason', 'Your account cannot send tips right now.');
  end if;
  select p.user_id, p.scheduled_for, p.collab_id, p.collab_status, p.archived_at into v_owner, v_sched, v_collab, v_collab_ok, v_archived from public.posts p where p.id = p_post;
  if v_owner is null or (v_sched is not null and v_sched > now() and v_owner <> me) or (v_archived is not null and v_owner <> me) then
    return jsonb_build_object('ok', false, 'reason', 'This post is not available anymore.');
  end if;
  if v_owner = me or (v_collab = me and v_collab_ok = 'accepted') then
    return jsonb_build_object('ok', false, 'reason', 'You cannot tip your own post.');
  end if;
  if exists (select 1 from public.profiles p where p.id = v_owner and (coalesce(p.banned, false) or coalesce(p.is_deleted, false) or coalesce(p.is_bot, false))) then
    return jsonb_build_object('ok', false, 'reason', 'This account cannot get tips.');
  end if;
  if public.zchat_blocked_pair(me, v_owner) or not public.zchat_owner_visible(v_owner, 'posts') then
    return jsonb_build_object('ok', false, 'reason', 'This post is not available anymore.');
  end if;
  if coalesce(public.zchat_account_created(me) > now() - interval '1 day', true)
     and not exists (select 1 from public.coin_orders o where o.user_id = me and o.status = 'paid') then
    return jsonb_build_object('ok', false, 'reason', 'New accounts can send tips after their first day.');
  end if;
  insert into public.wallets (user_id) values (me), (v_owner) on conflict (user_id) do nothing;
  perform 1 from public.wallets w where w.user_id in (me, v_owner) order by w.user_id for update;
  select coalesce(sum(-l.delta), 0), count(*) into v_day_coins, v_day_n
    from public.coin_ledger l where l.user_id = me and l.reason = 'tip_out' and l.created_at > now() - interval '1 day';
  if v_day_n >= 30 then
    return jsonb_build_object('ok', false, 'reason', 'You sent a lot of tips today. Try again tomorrow.');
  end if;
  if v_day_coins + p_amount > 5000 then
    return jsonb_build_object('ok', false, 'reason', 'You can tip up to 5,000 coins a day. You have ' || to_char(greatest(5000 - v_day_coins, 0), 'FM9,999') || ' left today.', 'left', greatest(5000 - v_day_coins, 0));
  end if;
  if (select coalesce(sum(l.delta), 0) from public.coin_ledger l where l.user_id = v_owner and l.reason = 'tip_in' and l.created_at > now() - interval '1 day') + p_amount > 10000 then
    return jsonb_build_object('ok', false, 'reason', 'They got a lot of tips today. Try again tomorrow.');
  end if;
  select coalesce(p.username, 'someone') into v_owner_user from public.profiles p where p.id = v_owner;
  select coalesce(p.username, 'someone') into v_my_user from public.profiles p where p.id = me;
  v_bal := public.zchat_coins_move(me, -p_amount, 'tip_out', 'Tip for @' || v_owner_user, v_owner);
  if v_bal is null then
    return jsonb_build_object('ok', false, 'reason', 'You do not have enough coins.');
  end if;
  if public.zchat_coins_move(v_owner, p_amount, 'tip_in', 'Tip from @' || v_my_user, me) is null then
    raise exception 'The tip could not be delivered' using errcode = 'P0001';
  end if;
  insert into public.post_tips (post_id, owner_id, tipper_id, amount, note)
    values (p_post, v_owner, me, p_amount, v_note)
    returning * into v_tip;
  perform public.zchat_notify(v_owner, me, 'tip', p_post,
    'tipped ' || to_char(p_amount, 'FM9,999') || case when p_amount = 1 then ' coin' else ' coins' end || ' on your post' || coalesce(': "' || v_note || '"', ''),
    jsonb_build_object('coins', p_amount, 'note', v_note, 'tip', v_tip.id));
  return jsonb_build_object('ok', true, 'coins', v_bal, 'tip', jsonb_build_object('id', v_tip.id, 'post_id', v_tip.post_id, 'amount', v_tip.amount, 'created_at', v_tip.created_at));
end $function$;

do $$
declare
  p public.profiles%rowtype;
begin
  for p in select * from public.profiles loop
    perform public.zchat_name_keys_put(p);
  end loop;
  perform public.zchat_lookalike_compute(n.user_id) from public.zchat_name_keys n where not n.protected and not n.official;
end $$;
commit;

begin;
create or replace function public.zchat_g1_clean(p_text text, p_max integer, p_lines boolean default false)
returns text
language sql
immutable
as $$
  select nullif(left(btrim(
    case when p_lines
      then regexp_replace(regexp_replace(regexp_replace(coalesce(p_text, ''), '[' || chr(1) || '-' || chr(9) || chr(11) || '-' || chr(31) || chr(127) || '-' || chr(159) || chr(8203) || '-' || chr(8207) || chr(8234) || '-' || chr(8238) || chr(8288) || '-' || chr(8303) || chr(65279) || ']+', '', 'g'), '[ ' || chr(9) || ']+', ' ', 'g'), chr(10) || '{3,}', chr(10) || chr(10), 'g')
      else regexp_replace(regexp_replace(coalesce(p_text, ''), '[' || chr(1) || '-' || chr(31) || chr(127) || '-' || chr(159) || chr(8203) || '-' || chr(8207) || chr(8234) || '-' || chr(8238) || chr(8288) || '-' || chr(8303) || chr(65279) || ']+', ' ', 'g'), '[[:space:]]+', ' ', 'g')
    end), p_max), '')
$$;

create or replace function public.zchat_g1_on_join()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  g record;
  first text;
  body text;
begin
  select x.welcome_text, x.welcome_name, x.created_by into g from public.groups x where x.id = new.group_id;
  if not found or g.welcome_text is null or new.user_id = g.created_by or public.zchat_g1_is_bot(new.user_id) then
    return null;
  end if;
  if exists (select 1 from public.zchat_grp_welcomed w where w.group_id = new.group_id and w.user_id = new.user_id and w.at > now() - interval '10 minutes') then
    return null;
  end if;
  insert into public.zchat_grp_welcomed (group_id, user_id, at) values (new.group_id, new.user_id, now())
    on conflict (group_id, user_id) do update set at = excluded.at;
  if g.welcome_name then
    select split_part(public.zchat_g1_clean(coalesce(nullif(btrim(p.name), ''), p.username), 40), ' ', 1) into first from public.profiles p where p.id = new.user_id;
  end if;
  body := public.zchat_g1_greeting(first, g.welcome_text);
  perform set_config('zchat.g1_ok', '1', true);
  insert into public.messages (sender_id, group_id, type, content, as_group)
    values (null, new.group_id, 'text', chr(8291) || chr(8292) || left(body, 360), true);
  perform set_config('zchat.g1_ok', '', true);
  return null;
exception when others then
  perform set_config('zchat.g1_ok', '', true);
  return null;
end $$;

create or replace function public.zchat_g1_short(p_text text, p_max integer default 80)
returns text
language sql
immutable
as $$
  select case when p_text is null then null when char_length(p_text) > p_max then left(p_text, p_max - 1) || chr(8230) else p_text end
$$;

create or replace function public.zchat_saved_folders_guard()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  n integer;
begin
  new.name := btrim(regexp_replace(coalesce(new.name, ''), '[' || chr(1) || '-' || chr(31) || chr(127) || chr(8203) || '-' || chr(8207) || chr(8234) || '-' || chr(8238) || chr(8288) || '-' || chr(8297) || chr(65279) || ']+', ' ', 'g'));
  new.name := left(regexp_replace(new.name, '[[:space:]]+', ' ', 'g'), 40);
  if tg_op = 'UPDATE' then
    if new.user_id is distinct from old.user_id then
      raise exception 'This folder is not yours' using errcode = '42501';
    end if;
    return new;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('zchat_saved_folders:' || new.user_id::text, 0));
  select count(*) into n from public.zchat_saved_folders f where f.user_id = new.user_id;
  if n >= 50 then
    raise exception 'You can have up to 50 folders' using errcode = 'P0001';
  end if;
  return new;
end $$;

create or replace function public.zchat_tones_guard()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  n integer;
begin
  new.name := left(btrim(regexp_replace(coalesce(new.name, ''), '[' || chr(1) || '-' || chr(31) || chr(127) || chr(8203) || '-' || chr(8207) || chr(8234) || '-' || chr(8238) || chr(8288) || '-' || chr(8297) || chr(65279) || ']+', ' ', 'g')), 40);
  if tg_op = 'UPDATE' and (new.user_id is distinct from old.user_id or new.path is distinct from old.path) then
    raise exception 'Only the name of a tone can change' using errcode = '42501';
  end if;
  if new.path !~ ('^zp:' || new.user_id::text || '/tones/[A-Za-z0-9-]{8,64}\.(wav|webm|ogg|m4a|mp3)$') then
    raise exception 'Tones live in your own folder' using errcode = '42501';
  end if;
  if tg_op = 'INSERT' then
    perform pg_advisory_xact_lock(hashtextextended('zchat_tones:' || new.user_id::text, 0));
    select count(*) into n from public.zchat_tones t where t.user_id = new.user_id;
    if n >= 20 then
      raise exception 'You can keep up to 20 tones' using errcode = 'P0001';
    end if;
  end if;
  return new;
end $$;
commit;

begin;
do $$
declare
  v text[];
  t record;
begin
  for t in select * from (values
    ('shop_items', 'shop_items_kind_check', array['frame', 'nameplate', 'charm', 'bubble', 'effect', 'namestyle', 'theme', 'reaction', 'wallpaper']),
    ('user_rewards', 'user_rewards_kind_check', array['frame', 'nameplate', 'charm', 'bubble', 'effect', 'namestyle', 'theme', 'reaction', 'wallpaper'])
  ) as x(tbl, con, dflt) loop
    if to_regclass('public.' || t.tbl) is null then
      continue;
    end if;
    select array_agg(distinct m[1] order by m[1]) into v
    from pg_constraint c, regexp_matches(pg_get_constraintdef(c.oid), '([a-z_]+)', 'g') as m
    where c.conname = t.con and c.conrelid = ('public.' || t.tbl)::regclass and m[1] not in ('kind', 'text', 'any', 'array');
    if v is null then
      v := t.dflt;
    end if;
    if not ('wrap' = any (v)) then
      v := v || 'wrap'::text;
      execute format('alter table public.%I drop constraint if exists %I', t.tbl, t.con);
      execute format('alter table public.%I add constraint %I check (kind = any (%L::text[]))', t.tbl, t.con, v);
    end if;
  end loop;
end $$;

do $$
declare
  v text[];
  w text;
  mine text[] := array['bag_out', 'bag_in', 'bag_back', 'bday_hold', 'bday_back', 'chip_out', 'chip_back', 'santa_out', 'santa_back'];
  changed boolean := false;
begin
  select array_agg(distinct m[1] order by m[1]) into v
  from pg_constraint c, regexp_matches(pg_get_constraintdef(c.oid), '([a-z_]+)', 'g') as m
  where c.conname = 'coin_ledger_reason_check' and c.conrelid = 'public.coin_ledger'::regclass and m[1] not in ('reason', 'text', 'any', 'array');
  if v is null then
    v := array['daily', 'invite', 'invited', 'gift_in', 'gift_out', 'shop', 'gift_item', 'admin', 'achievement', 'purchase', 'refund', 'drop', 'deal', 'milestone', 'trade', 'code', 'tip_in', 'tip_out', 'live_in', 'live_out'];
  end if;
  foreach w in array mine loop
    if not (w = any (v)) then
      v := v || w;
      changed := true;
    end if;
  end loop;
  if changed then
    alter table public.coin_ledger drop constraint if exists coin_ledger_reason_check;
    execute format('alter table public.coin_ledger add constraint coin_ledger_reason_check check (reason = any (%L::text[]))', v);
  end if;
end $$;

insert into public.shop_items (kind, key, label, rarity, price, active) values
  ('wrap', 'galaxy', 'Galaxy gift wrap', 'rare', 50, true),
  ('wrap', 'goldfoil', 'Gold foil gift wrap', 'rare', 50, true),
  ('wrap', 'sakura', 'Sakura gift wrap', 'rare', 50, true),
  ('wrap', 'neon', 'Neon gift wrap', 'rare', 50, true)
on conflict (kind, key) do update set label = excluded.label, rarity = excluded.rarity, price = excluded.price, active = true;

create or replace function public.zchat_gf_wrap(p_user uuid, p_paper text, p_ribbon text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_paper text := lower(btrim(coalesce(p_paper, '')));
  v_ribbon text := lower(btrim(coalesce(p_ribbon, '')));
begin
  if v_paper = '' then
    return null;
  end if;
  if v_ribbon = '' then
    v_ribbon := 'gold';
  end if;
  if v_ribbon not in ('gold', 'silver', 'red', 'white', 'purple', 'black') then
    return null;
  end if;
  if v_paper in ('lilac', 'rose', 'mint', 'sky', 'sun', 'ink', 'confetti', 'stripes', 'dots', 'stars') then
    return jsonb_build_object('p', v_paper, 'r', v_ribbon);
  end if;
  if exists (select 1 from public.shop_items s where s.kind = 'wrap' and s.key = v_paper and s.active)
     and public.zchat_owns_forever(p_user, 'wrap', v_paper) then
    return jsonb_build_object('p', v_paper, 'r', v_ribbon);
  end if;
  return null;
end $$;

revoke execute on function public.zchat_gf_wrap(uuid, text, text) from public, anon, authenticated;
grant execute on function public.zchat_gf_wrap(uuid, text, text) to service_role;

create or replace function public.zchat_buy_wrap(p_key text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  it public.shop_items%rowtype;
  bal integer;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  select * into it from public.shop_items where kind = 'wrap' and key = p_key and active;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'That wrap is not in the Shop.');
  end if;
  perform public.zchat_wallet_lock(me);
  if public.zchat_owns_forever(me, 'wrap', p_key) then
    return jsonb_build_object('ok', true, 'had', true, 'coins', (select coins from public.wallets where user_id = me));
  end if;
  bal := public.zchat_coins_move(me, -it.price, 'shop', it.label, null);
  if bal is null then
    return jsonb_build_object('ok', false, 'reason', 'You do not have enough coins.');
  end if;
  perform public.zchat_grant_item(me, 'wrap', p_key, null, true);
  return jsonb_build_object('ok', true, 'coins', bal);
end $$;

revoke execute on function public.zchat_buy_wrap(text) from public, anon;
grant execute on function public.zchat_buy_wrap(text) to authenticated, service_role;

create or replace function public.zchat_gift_send(p_to uuid, p_kind text, p_key text, p_amount integer, p_note text, p_paper text, p_ribbon text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  w jsonb := public.zchat_gf_wrap(auth.uid(), p_paper, p_ribbon);
  r jsonb;
  v_before uuid[];
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if nullif(btrim(coalesce(p_paper, '')), '') is not null and w is null then
    return jsonb_build_object('ok', false, 'reason', 'That wrap is not yours yet. Pick another one.');
  end if;
  select coalesce(array_agg(n.id), '{}'::uuid[]) into v_before from public.notifications n
    where n.user_id = p_to and n.actor_id = me and n.kind = 'gift' and n.created_at = now();
  if p_kind = 'coins' then
    r := public.zchat_send_gift(p_to, p_amount, p_note);
  else
    r := public.zchat_gift_item(p_to, p_kind, p_key, p_note);
  end if;
  if coalesce((r ->> 'ok')::boolean, false) and w is not null then
    update public.notifications n set meta = coalesce(n.meta, '{}'::jsonb) || jsonb_build_object('wrap', w)
    where n.user_id = p_to and n.actor_id = me and n.kind = 'gift' and n.created_at = now() and not (n.id = any (v_before));
  end if;
  return r;
end $$;

revoke execute on function public.zchat_gift_send(uuid, text, text, integer, text, text, text) from public, anon;
grant execute on function public.zchat_gift_send(uuid, text, text, integer, text, text, text) to authenticated, service_role;

create or replace function public.zchat_gf_target(p_from uuid, p_to uuid)
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  pr record;
begin
  if p_from is null then return 'Log in first.'; end if;
  if p_to is null or p_to = p_from then return 'Pick someone else.'; end if;
  if exists (select 1 from public.profiles p where p.id = p_from and (coalesce(p.banned, false) or coalesce(p.is_deleted, false) or coalesce(p.is_bot, false))) then
    return 'Your account cannot send gifts right now.';
  end if;
  select p.id, p.is_deleted, p.is_bot, p.banned into pr from public.profiles p where p.id = p_to;
  if not found or coalesce(pr.is_deleted, false) or coalesce(pr.banned, false) then return 'That account is not available.'; end if;
  if coalesce(pr.is_bot, false) then return 'Bots cannot get gifts.'; end if;
  if public.zchat_blocked_pair(p_from, p_to) then return 'You cannot send gifts to this person.'; end if;
  return null;
end $$;

revoke execute on function public.zchat_gf_target(uuid, uuid) from public, anon, authenticated;
grant execute on function public.zchat_gf_target(uuid, uuid) to service_role;

create or replace function public.zchat_gf_price(p_to uuid, p_kind text, p_key text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  kinds text[];
  k text;
  it public.shop_items%rowtype;
  v_price integer := 0;
  v_name text;
  v_label text;
  got text[] := array[]::text[];
begin
  if p_kind = 'set' then
    kinds := array['frame', 'nameplate', 'effect'];
  elsif p_kind in ('frame', 'nameplate', 'effect', 'charm', 'bubble', 'namestyle', 'theme', 'reaction', 'wallpaper') then
    kinds := array[p_kind];
  else
    return jsonb_build_object('ok', false, 'reason', 'That item is not in the Shop.');
  end if;
  foreach k in array kinds loop
    select * into it from public.shop_items where kind = k and key = p_key and active;
    if not found then
      return jsonb_build_object('ok', false, 'reason', 'That item is not in the Shop.');
    end if;
    v_name := regexp_replace(it.label, ' (frame|nameplate|effect)$', '');
    if not public.zchat_owns_forever(p_to, k, p_key) then
      v_price := v_price + it.price;
      got := got || k;
      v_label := it.label;
    end if;
  end loop;
  if coalesce(array_length(got, 1), 0) = 0 then
    return jsonb_build_object('ok', false, 'reason', case when p_kind = 'set' then 'They already have this set.' else 'They already have this one.' end, 'owned', true);
  end if;
  if array_length(got, 1) > 1 then
    v_label := v_name || case when array_length(got, 1) = 3 then ' set' else ' ' || array_to_string(got, ' and ') end;
  end if;
  return jsonb_build_object('ok', true, 'price', v_price, 'got', to_jsonb(got), 'label', v_label,
    'kind', case when array_length(got, 1) > 1 then 'set' else got[1] end);
end $$;

revoke execute on function public.zchat_gf_price(uuid, text, text) from public, anon, authenticated;
grant execute on function public.zchat_gf_price(uuid, text, text) to service_role;

create or replace function public.zchat_gf_grant(p_to uuid, p_from uuid, p_kind text, p_key text, p_note text, p_meta jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  pr jsonb := public.zchat_gf_price(p_to, p_kind, p_key);
  k text;
  v_note text := nullif(btrim(regexp_replace(left(coalesce(p_note, ''), 80), '[[:cntrl:]]+', ' ', 'g')), '');
begin
  if not coalesce((pr ->> 'ok')::boolean, false) then
    return pr;
  end if;
  for k in select jsonb_array_elements_text(pr -> 'got') loop
    perform public.zchat_grant_item(p_to, k, p_key, null, false);
  end loop;
  perform public.zchat_notify(p_to, p_from, 'gift', null, 'the ' || (pr ->> 'label') || coalesce(', "' || v_note || '"', ''),
    jsonb_build_object('kind', pr ->> 'kind', 'key', p_key, 'got', pr -> 'got') || coalesce(p_meta, '{}'::jsonb));
  return pr;
end $$;

revoke execute on function public.zchat_gf_grant(uuid, uuid, text, text, text, jsonb) from public, anon, authenticated;
grant execute on function public.zchat_gf_grant(uuid, uuid, text, text, text, jsonb) to service_role;

create or replace function public.zchat_guard_gift_cards()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if coalesce(current_setting('zchat.giftcard_ok', true), '') = '1' then
    return new;
  end if;
  if tg_op = 'INSERT' and (left(coalesce(new.content, ''), 5) = 'zbag:' or left(coalesce(new.content, ''), 6) = 'zchip:' or left(coalesce(new.content, ''), 7) = 'zsanta:') then
    raise exception 'Gift cards are made by ZChat' using errcode = '42501';
  end if;
  if tg_op = 'UPDATE' and new.content is distinct from old.content
     and (left(coalesce(new.content, ''), 5) = 'zbag:' or left(coalesce(new.content, ''), 6) = 'zchip:' or left(coalesce(new.content, ''), 7) = 'zsanta:'
       or ((left(coalesce(old.content, ''), 5) = 'zbag:' or left(coalesce(old.content, ''), 6) = 'zchip:' or left(coalesce(old.content, ''), 7) = 'zsanta:') and new.content is not null)) then
    raise exception 'Gift cards cannot be changed' using errcode = '42501';
  end if;
  return new;
end $$;

drop trigger if exists zchat_guard_gift_cards on public.messages;
create trigger zchat_guard_gift_cards before insert or update of content on public.messages
  for each row execute function public.zchat_guard_gift_cards();

create table if not exists public.spend_limits (
  user_id uuid primary key references auth.users(id) on delete cascade,
  monthly integer,
  next_monthly integer,
  next_at timestamptz,
  tz text not null default 'UTC',
  pin_hash text,
  pin_fails integer not null default 0,
  pin_locked_until timestamptz,
  allow_coins integer not null default 0,
  allow_until timestamptz,
  updated_at timestamptz not null default now(),
  constraint spend_limits_monthly_ok check (monthly is null or monthly between 1 and 1000000),
  constraint spend_limits_next_ok check (next_monthly is null or next_monthly between 1 and 1000000)
);
alter table public.spend_limits enable row level security;

create table if not exists public.spend_months (
  user_id uuid not null references auth.users(id) on delete cascade,
  month date not null,
  spent integer not null default 0,
  primary key (user_id, month),
  constraint spend_months_spent_ok check (spent >= 0)
);
alter table public.spend_months enable row level security;
drop policy if exists "zchat spend months read" on public.spend_months;
create policy "zchat spend months read" on public.spend_months for select to authenticated using (user_id = auth.uid());

create or replace function public.zchat_spend_month(p_tz text)
returns date
language sql
stable
set search_path = public
as $$
  select (date_trunc('month', now() at time zone public.zchat_tz(coalesce(p_tz, 'UTC'))))::date
$$;

create or replace function public.zchat_spend_state(p_user uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  l public.spend_limits%rowtype;
  m date;
  s integer := 0;
begin
  select * into l from public.spend_limits where user_id = p_user;
  if found and l.next_at is not null and l.next_at <= now() then
    update public.spend_limits set monthly = next_monthly, next_monthly = null, next_at = null, updated_at = now()
    where user_id = p_user returning * into l;
  end if;
  m := public.zchat_spend_month(l.tz);
  select spent into s from public.spend_months where user_id = p_user and month = m;
  s := coalesce(s, 0);
  return jsonb_build_object(
    'limit', l.monthly,
    'spent', s,
    'left', case when l.monthly is null then null else greatest(l.monthly - s, 0) end,
    'next_set', l.next_at is not null,
    'next_limit', l.next_monthly,
    'next_at', l.next_at,
    'resets', to_char((m + interval '1 month')::date, 'YYYY-MM-DD'),
    'tz', coalesce(l.tz, 'UTC'),
    'has_pin', l.pin_hash is not null,
    'locked_until', case when l.pin_locked_until > now() then l.pin_locked_until end,
    'allow_left', case when l.allow_until > now() then l.allow_coins else 0 end
  );
end $$;

revoke execute on function public.zchat_spend_state(uuid) from public, anon, authenticated;
grant execute on function public.zchat_spend_state(uuid) to service_role;

create or replace function public.zchat_spend_count(p_user uuid, p_coins integer)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  l public.spend_limits%rowtype;
  m date;
  s integer;
  v_left integer;
begin
  if p_user is null or p_coins is null or p_coins <= 0 then
    return;
  end if;
  select * into l from public.spend_limits where user_id = p_user for update;
  if found and l.next_at is not null and l.next_at <= now() then
    update public.spend_limits set monthly = next_monthly, next_monthly = null, next_at = null, updated_at = now()
    where user_id = p_user returning * into l;
  end if;
  m := public.zchat_spend_month(l.tz);
  insert into public.spend_months (user_id, month, spent) values (p_user, m, 0) on conflict (user_id, month) do nothing;
  select spent into s from public.spend_months where user_id = p_user and month = m for update;
  if l.monthly is not null and s + p_coins > l.monthly then
    if l.allow_until is not null and l.allow_until > now() and l.allow_coins >= p_coins then
      update public.spend_limits set allow_coins = allow_coins - p_coins where user_id = p_user;
    else
      v_left := greatest(l.monthly - s, 0);
      raise exception using errcode = 'ZL001',
        message = case when v_left = 0
          then 'You have used your monthly limit. It starts again on ' || to_char((m + interval '1 month')::date, 'FMMonth FMDD') || '.'
          else 'This goes over your monthly limit. You have ' || to_char(v_left, 'FM999,999,999') || case when v_left = 1 then ' coin' else ' coins' end || ' left this month.' end,
        hint = jsonb_build_object('left', v_left, 'limit', l.monthly, 'need', p_coins, 'resets', to_char((m + interval '1 month')::date, 'YYYY-MM-DD'))::text;
    end if;
  end if;
  update public.spend_months set spent = spent + p_coins where user_id = p_user and month = m;
  if random() < 0.002 then
    delete from public.spend_months where user_id = p_user and month < (m - interval '13 months')::date;
  end if;
end $$;

revoke execute on function public.zchat_spend_count(uuid, integer) from public, anon, authenticated;
grant execute on function public.zchat_spend_count(uuid, integer) to service_role;

create or replace function public.zchat_spend_back(p_user uuid, p_coins integer)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_tz text;
  m date;
begin
  if p_user is null or p_coins is null or p_coins <= 0 then
    return;
  end if;
  select tz into v_tz from public.spend_limits where user_id = p_user;
  m := public.zchat_spend_month(v_tz);
  update public.spend_months set spent = greatest(spent - p_coins, 0) where user_id = p_user and month = m;
end $$;

revoke execute on function public.zchat_spend_back(uuid, integer) from public, anon, authenticated;
grant execute on function public.zchat_spend_back(uuid, integer) to service_role;

create or replace function public.zchat_coins_move(p_user uuid, p_delta integer, p_reason text, p_note text default null, p_other uuid default null)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  bal integer;
begin
  if p_user is null or p_delta is null or p_delta = 0 or abs(p_delta::bigint) > 100000000 or coalesce(p_reason, '') = '' then
    return null;
  end if;
  insert into public.wallets (user_id) values (p_user) on conflict (user_id) do nothing;
  select coins into bal from public.wallets where user_id = p_user for update;
  if bal is null or bal::bigint + p_delta < 0 or bal::bigint + p_delta > 2000000000 then
    return null;
  end if;
  if p_delta < 0 and p_user = auth.uid() then
    perform public.zchat_spend_count(p_user, -p_delta);
  end if;
  update public.wallets set coins = coins + p_delta, updated_at = now() where user_id = p_user returning coins into bal;
  insert into public.coin_ledger (user_id, delta, reason, note, other_id) values (p_user, p_delta, p_reason, left(p_note, 120), p_other);
  return bal;
end $$;

create or replace function public.zchat_spend_limit(p_tz text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    return null;
  end if;
  return public.zchat_spend_state(me);
end $$;

revoke execute on function public.zchat_spend_limit(text) from public, anon;
grant execute on function public.zchat_spend_limit(text) to authenticated, service_role;

create or replace function public.zchat_spend_hash_ok(p text)
returns boolean
language sql
immutable
as $$
  select p is not null and (p ~ '^[0-9a-f]{64}$' or p ~ '^x[0-9a-f]{1,8}$')
$$;

create or replace function public.zchat_spend_limit_set(p_limit integer, p_tz text default 'UTC', p_pin text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  l public.spend_limits%rowtype;
  v_new integer := case when p_limit is null or p_limit <= 0 then null else p_limit end;
  v_pin text := lower(btrim(coalesce(p_pin, '')));
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if v_new is not null and (v_new < 10 or v_new > 1000000) then
    return jsonb_build_object('ok', false, 'reason', 'Pick a limit from 10 to 1,000,000 coins a month.');
  end if;
  insert into public.spend_limits (user_id, tz) values (me, public.zchat_tz(p_tz)) on conflict (user_id) do nothing;
  select * into l from public.spend_limits where user_id = me for update;
  if l.next_at is not null and l.next_at <= now() then
    update public.spend_limits set monthly = next_monthly, next_monthly = null, next_at = null where user_id = me returning * into l;
  end if;
  if v_new is not null and (l.monthly is null or v_new <= l.monthly) then
    update public.spend_limits set monthly = v_new, next_monthly = null, next_at = null, updated_at = now(),
      tz = case when l.monthly is null then public.zchat_tz(p_tz) else tz end
    where user_id = me;
  elsif v_new is not distinct from l.monthly then
    update public.spend_limits set next_monthly = null, next_at = null, updated_at = now() where user_id = me;
  else
    update public.spend_limits set
      next_monthly = v_new,
      next_at = case when l.next_at is not null and l.next_monthly is not distinct from v_new then l.next_at else now() + interval '24 hours' end,
      updated_at = now()
    where user_id = me;
  end if;
  if l.pin_hash is null and public.zchat_spend_hash_ok(v_pin) then
    update public.spend_limits set pin_hash = v_pin, pin_fails = 0, pin_locked_until = null where user_id = me;
  end if;
  return jsonb_build_object('ok', true, 'state', public.zchat_spend_state(me));
end $$;

revoke execute on function public.zchat_spend_limit_set(integer, text, text) from public, anon;
grant execute on function public.zchat_spend_limit_set(integer, text, text) to authenticated, service_role;

create or replace function public.zchat_spend_pin_check(p_user uuid, p_pin text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  l public.spend_limits%rowtype;
  v_pin text := lower(btrim(coalesce(p_pin, '')));
begin
  select * into l from public.spend_limits where user_id = p_user for update;
  if not found or l.pin_hash is null then
    return 'none';
  end if;
  if l.pin_locked_until is not null and l.pin_locked_until > now() then
    return 'locked';
  end if;
  if v_pin = l.pin_hash then
    update public.spend_limits set pin_fails = 0, pin_locked_until = null where user_id = p_user;
    return 'ok';
  end if;
  update public.spend_limits
    set pin_fails = pin_fails + 1,
        pin_locked_until = case when (pin_fails + 1) % 5 = 0 then now() + least(interval '1 hour', interval '1 minute' * ((pin_fails + 1) / 5)) else null end
    where user_id = p_user;
  return 'wrong';
end $$;

revoke execute on function public.zchat_spend_pin_check(uuid, text) from public, anon, authenticated;
grant execute on function public.zchat_spend_pin_check(uuid, text) to service_role;

create or replace function public.zchat_spend_pin(p_hash text, p_old text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  v_new text := lower(btrim(coalesce(p_hash, '')));
  v_chk text;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if not public.zchat_spend_hash_ok(v_new) then
    return jsonb_build_object('ok', false, 'reason', 'That PIN cannot be used.');
  end if;
  insert into public.spend_limits (user_id) values (me) on conflict (user_id) do nothing;
  if exists (select 1 from public.spend_limits where user_id = me and pin_hash is not null) then
    v_chk := public.zchat_spend_pin_check(me, p_old);
    if v_chk = 'locked' then
      return jsonb_build_object('ok', false, 'reason', 'Too many wrong PINs. Wait a minute and try again.');
    end if;
    if v_chk <> 'ok' then
      return jsonb_build_object('ok', false, 'reason', 'Your old PIN did not match.');
    end if;
  end if;
  update public.spend_limits set pin_hash = v_new, pin_fails = 0, pin_locked_until = null, updated_at = now() where user_id = me;
  return jsonb_build_object('ok', true);
end $$;

revoke execute on function public.zchat_spend_pin(text, text) from public, anon;
grant execute on function public.zchat_spend_pin(text, text) to authenticated, service_role;

create or replace function public.zchat_spend_allow(p_pin text, p_coins integer)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  v_chk text;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if p_coins is null or p_coins < 1 or p_coins > 100000 then
    return jsonb_build_object('ok', false, 'reason', 'That amount cannot be allowed.');
  end if;
  v_chk := public.zchat_spend_pin_check(me, p_pin);
  if v_chk = 'none' then
    return jsonb_build_object('ok', false, 'reason', 'Set a PIN for your monthly limit first.', 'no_pin', true);
  end if;
  if v_chk = 'locked' then
    return jsonb_build_object('ok', false, 'reason', 'Too many wrong PINs. Wait a minute and try again.', 'locked', true);
  end if;
  if v_chk <> 'ok' then
    return jsonb_build_object('ok', false, 'reason', 'Wrong PIN, try again.', 'wrong', true);
  end if;
  update public.spend_limits set allow_coins = p_coins, allow_until = now() + interval '3 minutes' where user_id = me;
  return jsonb_build_object('ok', true, 'state', public.zchat_spend_state(me));
end $$;

revoke execute on function public.zchat_spend_allow(text, integer) from public, anon;
grant execute on function public.zchat_spend_allow(text, integer) to authenticated, service_role;

select public.zchat_apply_session_gate();
commit;

begin;
create table if not exists public.coin_bags (
  id uuid primary key default gen_random_uuid(),
  sender_id uuid not null references auth.users(id) on delete cascade,
  receiver_id uuid references auth.users(id) on delete cascade,
  group_id uuid references public.groups(id) on delete cascade,
  total integer not null,
  slots integer not null,
  share integer not null,
  opened integer not null default 0,
  left_coins integer not null,
  note text,
  message_id bigint,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '24 hours',
  closed_at timestamptz,
  returned integer not null default 0,
  constraint coin_bags_total_ok check (total between 1 and 100000),
  constraint coin_bags_slots_ok check (slots between 1 and 20),
  constraint coin_bags_left_ok check (left_coins >= 0),
  constraint coin_bags_chat_ok check ((receiver_id is null) <> (group_id is null))
);
create index if not exists zchat_coin_bags_open on public.coin_bags (expires_at) where closed_at is null;
create index if not exists zchat_coin_bags_sender on public.coin_bags (sender_id, created_at desc);
alter table public.coin_bags enable row level security;

create table if not exists public.coin_bag_opens (
  id uuid primary key default gen_random_uuid(),
  bag_id uuid not null references public.coin_bags(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  coins integer not null,
  created_at timestamptz not null default now(),
  constraint coin_bag_opens_once unique (bag_id, user_id),
  constraint coin_bag_opens_coins_ok check (coins > 0)
);
alter table public.coin_bag_opens enable row level security;

create or replace function public.zchat_bag_can_see(p_bag uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select auth.uid() is not null and exists (
    select 1 from public.coin_bags b
    where b.id = p_bag and (
      b.sender_id = auth.uid() or b.receiver_id = auth.uid()
      or (b.group_id is not null and exists (select 1 from public.group_members gm where gm.group_id = b.group_id and gm.user_id = auth.uid()))
    )
  )
$$;
revoke execute on function public.zchat_bag_can_see(uuid) from public, anon;
grant execute on function public.zchat_bag_can_see(uuid) to authenticated, service_role;

drop policy if exists "zchat coin bags read" on public.coin_bags;
create policy "zchat coin bags read" on public.coin_bags for select to authenticated
  using (sender_id = auth.uid() or receiver_id = auth.uid() or (group_id is not null and is_group_member(group_id, auth.uid())));
drop policy if exists "zchat coin bag opens read" on public.coin_bag_opens;
create policy "zchat coin bag opens read" on public.coin_bag_opens for select to authenticated
  using (public.zchat_bag_can_see(bag_id));

create or replace function public.zchat_bag_json(p_bag uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'id', b.id, 'sender', b.sender_id, 'to', b.receiver_id, 'group', b.group_id, 'total', b.total, 'slots', b.slots, 'share', b.share,
    'opened', b.opened, 'left', b.left_coins, 'note', b.note, 'message_id', b.message_id, 'created_at', b.created_at, 'expires_at', b.expires_at,
    'closed_at', b.closed_at, 'returned', b.returned,
    'opens', coalesce((select jsonb_agg(jsonb_build_object('u', o.user_id, 'c', o.coins, 'at', o.created_at) order by o.created_at) from public.coin_bag_opens o where o.bag_id = b.id), '[]'::jsonb))
  from public.coin_bags b where b.id = p_bag
$$;
revoke execute on function public.zchat_bag_json(uuid) from public, anon, authenticated;
grant execute on function public.zchat_bag_json(uuid) to service_role;

create or replace function public.zchat_bags(p_ids uuid[])
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(jsonb_agg(public.zchat_bag_json(x.id)), '[]'::jsonb)
  from (select distinct u as id from unnest(coalesce(p_ids, '{}'::uuid[])) u limit 60) x
  where auth.uid() is not null and public.zchat_bag_can_see(x.id)
$$;
revoke execute on function public.zchat_bags(uuid[]) from public, anon;
grant execute on function public.zchat_bags(uuid[]) to authenticated, service_role;

create or replace function public.zchat_bag_send(p_to uuid, p_group uuid, p_total integer, p_slots integer, p_note text default null, p_client_id text default null, p_topic text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  why text;
  v_note text := nullif(btrim(regexp_replace(left(coalesce(p_note, ''), 60), '[[:cntrl:]]+', ' ', 'g')), '');
  v_slots integer := coalesce(p_slots, 1);
  v_sent bigint;
  bal integer;
  v_id uuid;
  v_msg public.messages%rowtype;
  v_words text;
  v_to_name text;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if (p_to is null) = (p_group is null) then
    return jsonb_build_object('ok', false, 'reason', 'Pick one chat for the gift bag.');
  end if;
  if exists (select 1 from public.profiles p where p.id = me and (coalesce(p.banned, false) or coalesce(p.is_deleted, false) or coalesce(p.is_bot, false))) then
    return jsonb_build_object('ok', false, 'reason', 'Your account cannot send gifts right now.');
  end if;
  if p_to is not null then
    why := public.zchat_gf_target(me, p_to);
    if why is not null then
      return jsonb_build_object('ok', false, 'reason', why);
    end if;
    if not public.zchat_can_dm(me, p_to) then
      return jsonb_build_object('ok', false, 'reason', 'They only take messages from people they follow.');
    end if;
    v_slots := 1;
  else
    if not exists (select 1 from public.group_members gm where gm.group_id = p_group and gm.user_id = me) then
      return jsonb_build_object('ok', false, 'reason', 'Only people in this group can send a gift bag here.');
    end if;
    if not public.is_group_member_unmuted(p_group, me) or not public.zchat_can_post_group(p_group, 'text') then
      return jsonb_build_object('ok', false, 'reason', 'You cannot send messages in this group right now.');
    end if;
    if v_slots < 2 or v_slots > 20 then
      return jsonb_build_object('ok', false, 'reason', 'A gift bag can be opened by 2 to 20 people.');
    end if;
  end if;
  if p_total is null or p_total < v_slots then
    return jsonb_build_object('ok', false, 'reason', 'Put in at least 1 coin for each person.');
  end if;
  if p_total > 5000 then
    return jsonb_build_object('ok', false, 'reason', 'A gift bag can hold up to 5,000 coins.');
  end if;
  if coalesce(public.zchat_account_created(me) > now() - interval '1 day', true)
     and not exists (select 1 from public.coin_orders o where o.user_id = me and o.status = 'paid') then
    return jsonb_build_object('ok', false, 'reason', 'New accounts can send coin gifts after their first day.');
  end if;
  perform public.zchat_wallet_lock(me);
  if (select count(*) from public.coin_bags b where b.sender_id = me and b.created_at > now() - interval '1 hour') >= 10 then
    return jsonb_build_object('ok', false, 'reason', 'You sent a lot of gift bags in the last hour. Try again a little later.');
  end if;
  if (select count(*) from public.coin_bags b where b.sender_id = me and b.created_at > now() - interval '1 day') >= 30 then
    return jsonb_build_object('ok', false, 'reason', 'You sent a lot of gift bags today. Try again tomorrow.');
  end if;
  select coalesce(sum(-l.delta), 0) into v_sent from public.coin_ledger l
    where l.user_id = me and l.reason in ('gift_out', 'bag_out') and l.created_at > now() - interval '1 day';
  if v_sent + p_total > 5000 then
    return jsonb_build_object('ok', false, 'reason', 'You can send up to 5,000 coins a day. You have ' || to_char(greatest(5000 - v_sent, 0), 'FM9,999') || ' left today.');
  end if;
  if p_to is not null then
    select p.username into v_to_name from public.profiles p where p.id = p_to;
  end if;
  bal := public.zchat_coins_move(me, -p_total, 'bag_out', case when p_to is not null then 'Gift bag for @' || coalesce(v_to_name, 'someone') else 'Gift bag' end, p_to);
  if bal is null then
    return jsonb_build_object('ok', false, 'reason', 'You do not have enough coins.');
  end if;
  insert into public.coin_bags (sender_id, receiver_id, group_id, total, slots, share, left_coins, note)
    values (me, p_to, p_group, p_total, v_slots, p_total / v_slots, p_total, v_note)
    returning id into v_id;
  v_words := 'Coin gift bag, ' || to_char(p_total, 'FM999,999') || ' coins' || case when v_slots > 1 then ' for ' || v_slots || ' people' else '' end;
  perform set_config('zchat.giftcard_ok', '1', true);
  insert into public.messages (sender_id, receiver_id, group_id, type, content, client_id, topic)
    values (me, p_to, p_group, 'text', 'zbag:' || jsonb_build_object('i', v_id, 'n', p_total, 's', v_slots, 't', v_words)::text,
      nullif(left(coalesce(p_client_id, ''), 80), ''),
      case when p_group is not null then nullif(left(btrim(coalesce(p_topic, '')), 40), '') end)
    returning * into v_msg;
  perform set_config('zchat.giftcard_ok', '', true);
  update public.coin_bags set message_id = v_msg.id where id = v_id;
  return jsonb_build_object('ok', true, 'coins', bal, 'bag', public.zchat_bag_json(v_id), 'message', to_jsonb(v_msg));
end $$;
revoke execute on function public.zchat_bag_send(uuid, uuid, integer, integer, text, text, text) from public, anon;
grant execute on function public.zchat_bag_send(uuid, uuid, integer, integer, text, text, text) to authenticated, service_role;

create or replace function public.zchat_bag_open(p_bag uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  b public.coin_bags%rowtype;
  v_coins integer;
  bal integer;
  v_from text;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  select * into b from public.coin_bags where id = p_bag for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'This gift bag is not here anymore.');
  end if;
  if b.sender_id = me then
    return jsonb_build_object('ok', false, 'reason', 'You cannot open your own gift bag.', 'bag', public.zchat_bag_json(b.id));
  end if;
  if (b.receiver_id is not null and b.receiver_id <> me)
     or (b.group_id is not null and not exists (select 1 from public.group_members gm where gm.group_id = b.group_id and gm.user_id = me)) then
    return jsonb_build_object('ok', false, 'reason', 'Only people in this chat can open it.');
  end if;
  if exists (select 1 from public.profiles p where p.id = me and (coalesce(p.banned, false) or coalesce(p.is_deleted, false) or coalesce(p.is_bot, false))) then
    return jsonb_build_object('ok', false, 'reason', 'Your account cannot open gift bags right now.');
  end if;
  if public.zchat_blocked_pair(me, b.sender_id) then
    return jsonb_build_object('ok', false, 'reason', 'You cannot open this gift bag.');
  end if;
  if exists (select 1 from public.coin_bag_opens o where o.bag_id = b.id and o.user_id = me) then
    return jsonb_build_object('ok', false, 'reason', 'You already opened this one.', 'bag', public.zchat_bag_json(b.id));
  end if;
  if b.opened >= b.slots then
    return jsonb_build_object('ok', false, 'reason', 'Everyone already opened this gift bag.', 'bag', public.zchat_bag_json(b.id));
  end if;
  if b.closed_at is not null or b.expires_at <= now() then
    return jsonb_build_object('ok', false, 'reason', 'This gift bag has closed.', 'bag', public.zchat_bag_json(b.id));
  end if;
  v_coins := case when b.opened + 1 >= b.slots then b.left_coins else b.share end;
  if v_coins <= 0 then
    return jsonb_build_object('ok', false, 'reason', 'This gift bag is empty.', 'bag', public.zchat_bag_json(b.id));
  end if;
  insert into public.coin_bag_opens (bag_id, user_id, coins) values (b.id, me, v_coins);
  update public.coin_bags set opened = opened + 1, left_coins = left_coins - v_coins,
    closed_at = case when opened + 1 >= slots then now() else closed_at end
    where id = b.id;
  select p.username into v_from from public.profiles p where p.id = b.sender_id;
  bal := public.zchat_coins_move(me, v_coins, 'bag_in', 'Gift bag from @' || coalesce(v_from, 'someone'), b.sender_id);
  if bal is null then
    raise exception 'Your wallet cannot take these coins right now' using errcode = 'P0001';
  end if;
  return jsonb_build_object('ok', true, 'coins', v_coins, 'balance', bal, 'bag', public.zchat_bag_json(b.id));
end $$;
revoke execute on function public.zchat_bag_open(uuid) from public, anon;
grant execute on function public.zchat_bag_open(uuid) to authenticated, service_role;

create or replace function public.zchat_bag_sweep()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  r record;
  n integer := 0;
begin
  for r in
    update public.coin_bags b set closed_at = now(), returned = b.left_coins, left_coins = 0
    where b.id in (
      select b2.id from public.coin_bags b2
      where b2.closed_at is null and b2.expires_at <= now()
      order by b2.expires_at
      limit 200
      for update skip locked
    )
    returning b.*
  loop
    begin
      if r.returned > 0 then
        perform public.zchat_coins_move(r.sender_id, r.returned, 'bag_back', 'Gift bag coins back', null);
        perform public.zchat_spend_back(r.sender_id, r.returned);
        perform public.zchat_notify(r.sender_id, null, 'coins', null,
          to_char(r.returned, 'FM999,999') || case when r.returned = 1 then ' coin' else ' coins' end || ' from your gift bag came back to you',
          jsonb_build_object('coins', r.returned, 'bag', r.id));
      end if;
      n := n + 1;
    exception when others then
      raise notice 'zchat bag sweep skipped: %', sqlerrm;
    end;
  end loop;
  return n;
end $$;
revoke execute on function public.zchat_bag_sweep() from public, anon, authenticated;
grant execute on function public.zchat_bag_sweep() to service_role;

do $$
declare
  t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime' and not puballtables) then
    foreach t in array array['coin_bags', 'coin_bag_opens'] loop
      if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
        execute format('alter publication supabase_realtime add table public.%I', t);
      end if;
    end loop;
  end if;
end $$;

select public.zchat_apply_session_gate();

create table if not exists public.birthday_gifts (
  id uuid primary key default gen_random_uuid(),
  from_id uuid not null references auth.users(id) on delete cascade,
  to_id uuid not null references auth.users(id) on delete cascade,
  kind text not null,
  item_key text,
  coins integer,
  price integer not null default 0,
  held integer not null default 0,
  pay text not null default 'now',
  note text,
  wrap jsonb,
  md text not null,
  tz text not null default 'UTC',
  deliver_at timestamptz not null,
  status text not null default 'waiting',
  reason text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  sent_at timestamptz,
  constraint birthday_gifts_pay_ok check (pay in ('now', 'later')),
  constraint birthday_gifts_status_ok check (status in ('waiting', 'sent', 'cancelled', 'failed')),
  constraint birthday_gifts_held_ok check (held >= 0 and price >= 0)
);
create unique index if not exists zchat_birthday_gifts_one on public.birthday_gifts (from_id, to_id) where status = 'waiting';
create index if not exists zchat_birthday_gifts_due on public.birthday_gifts (deliver_at) where status = 'waiting';
alter table public.birthday_gifts enable row level security;
drop policy if exists "zchat birthday gifts read" on public.birthday_gifts;
create policy "zchat birthday gifts read" on public.birthday_gifts for select to authenticated using (from_id = auth.uid());

create or replace function public.zchat_bday_tz(p_to uuid, p_fallback text)
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v text;
begin
  if to_regclass('public.zchat_app_prefs') is not null then
    begin
      execute 'select tz from public.zchat_app_prefs where user_id = $1' into v using p_to;
    exception when others then
      v := null;
    end;
  end if;
  if v is not null and public.zchat_tz(v) = v then
    return v;
  end if;
  return public.zchat_tz(p_fallback);
end $$;
revoke execute on function public.zchat_bday_tz(uuid, text) from public, anon, authenticated;
grant execute on function public.zchat_bday_tz(uuid, text) to service_role;

create or replace function public.zchat_bday_next(p_md text, p_tz text)
returns timestamptz
language plpgsql
stable
set search_path = public
as $$
declare
  v_tz text := public.zchat_tz(p_tz);
  v_today date := (now() at time zone v_tz)::date;
  v_m integer := split_part(p_md, '-', 1)::integer;
  v_d integer := split_part(p_md, '-', 2)::integer;
  v_y integer := extract(year from v_today)::integer;
  v_day date;
begin
  for i in 0..1 loop
    v_day := make_date(v_y + i, v_m, least(v_d, extract(day from (make_date(v_y + i, v_m, 1) + interval '1 month - 1 day'))::integer));
    if v_day = v_today then
      return now();
    end if;
    if v_day > v_today then
      return (v_day::timestamp at time zone v_tz);
    end if;
  end loop;
  return null;
exception when others then
  return null;
end $$;

create or replace function public.zchat_bday_json(g public.birthday_gifts)
returns jsonb
language sql
stable
as $$
  select jsonb_build_object('id', g.id, 'to', g.to_id, 'kind', g.kind, 'key', g.item_key, 'coins', g.coins, 'price', g.price, 'held', g.held,
    'pay', g.pay, 'note', g.note, 'wrap', g.wrap, 'md', g.md, 'deliver_at', g.deliver_at, 'status', g.status, 'reason', g.reason)
$$;

create or replace function public.zchat_bday_gift_save(p_to uuid, p_kind text, p_key text, p_coins integer, p_note text, p_paper text, p_ribbon text, p_pay text, p_tz text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  why text := public.zchat_gift_target_reason(p_to);
  bd record;
  v_note text := nullif(btrim(regexp_replace(left(coalesce(p_note, ''), 80), '[[:cntrl:]]+', ' ', 'g')), '');
  v_pay text := case when p_pay = 'later' then 'later' else 'now' end;
  v_wrap jsonb;
  v_tz text;
  v_at timestamptz;
  v_price integer;
  pr jsonb;
  old public.birthday_gifts%rowtype;
  v_had boolean;
  bal integer;
  v_row public.birthday_gifts%rowtype;
  v_user text;
begin
  if why is not null then
    return jsonb_build_object('ok', false, 'reason', why);
  end if;
  if exists (select 1 from public.profiles p where p.id = me and (coalesce(p.banned, false) or coalesce(p.is_deleted, false) or coalesce(p.is_bot, false))) then
    return jsonb_build_object('ok', false, 'reason', 'Your account cannot send gifts right now.');
  end if;
  select b.md, b.show into bd from public.birthdays b where b.user_id = p_to;
  if not found or bd.show = 'nobody'
     or (bd.show = 'followers' and not public.zchat_follows(me, p_to))
     or (bd.show = 'mutual' and not (public.zchat_follows(me, p_to) and public.zchat_follows(p_to, me))) then
    return jsonb_build_object('ok', false, 'reason', 'Their birthday is not shared with you.');
  end if;
  v_wrap := coalesce(public.zchat_gf_wrap(me, p_paper, p_ribbon), jsonb_build_object('p', 'birthday', 'r', 'gold'));
  if p_kind = 'coins' then
    if p_coins is null or p_coins < 1 or p_coins > 1000 then
      return jsonb_build_object('ok', false, 'reason', 'Send from 1 to 1,000 coins at a time.');
    end if;
    if coalesce(public.zchat_account_created(me) > now() - interval '1 day', true)
       and not exists (select 1 from public.coin_orders o where o.user_id = me and o.status = 'paid') then
      return jsonb_build_object('ok', false, 'reason', 'New accounts can send coin gifts after their first day.');
    end if;
    v_price := p_coins;
  else
    pr := public.zchat_gf_price(p_to, p_kind, p_key);
    if not coalesce((pr ->> 'ok')::boolean, false) then
      return jsonb_build_object('ok', false, 'reason', pr ->> 'reason');
    end if;
    v_price := (pr ->> 'price')::integer;
  end if;
  v_tz := public.zchat_bday_tz(p_to, p_tz);
  v_at := public.zchat_bday_next(bd.md, v_tz);
  if v_at is null then
    return jsonb_build_object('ok', false, 'reason', 'That birthday date does not look right.');
  end if;
  perform public.zchat_wallet_lock(me);
  select * into old from public.birthday_gifts g where g.from_id = me and g.to_id = p_to and g.status = 'waiting' for update;
  v_had := found;
  if not v_had and (select count(*) from public.birthday_gifts g where g.from_id = me and g.status = 'waiting') >= 30 then
    return jsonb_build_object('ok', false, 'reason', 'You have 30 birthday gifts waiting. Let some go out first.');
  end if;
  if (select count(*) from public.birthday_gifts g where g.from_id = me and g.updated_at > now() - interval '1 hour') >= 20 then
    return jsonb_build_object('ok', false, 'reason', 'You changed a lot of birthday gifts this hour. Try again a little later.');
  end if;
  select p.username into v_user from public.profiles p where p.id = p_to;
  begin
    if v_had and old.held > 0 then
      perform public.zchat_coins_move(me, old.held, 'bday_back', 'Birthday gift for @' || coalesce(v_user, 'someone') || ' changed', p_to);
      perform public.zchat_spend_back(me, old.held);
    end if;
    if v_pay = 'now' then
      bal := public.zchat_coins_move(me, -v_price, 'bday_hold', 'Birthday gift for @' || coalesce(v_user, 'someone'), p_to);
      if bal is null then
        raise exception 'short' using errcode = 'ZG001';
      end if;
    end if;
  exception when sqlstate 'ZG001' then
    return jsonb_build_object('ok', false, 'reason', 'You do not have enough coins to hold it now. Pick pay on the day, or a smaller gift.');
  end;
  if v_had then
    update public.birthday_gifts set kind = p_kind, item_key = case when p_kind = 'coins' then null else p_key end, coins = case when p_kind = 'coins' then p_coins end,
      price = v_price, held = case when v_pay = 'now' then v_price else 0 end, pay = v_pay, note = v_note, wrap = v_wrap,
      md = bd.md, tz = v_tz, deliver_at = v_at, updated_at = now()
    where id = old.id returning * into v_row;
  else
    insert into public.birthday_gifts (from_id, to_id, kind, item_key, coins, price, held, pay, note, wrap, md, tz, deliver_at)
    values (me, p_to, p_kind, case when p_kind = 'coins' then null else p_key end, case when p_kind = 'coins' then p_coins end,
      v_price, case when v_pay = 'now' then v_price else 0 end, v_pay, v_note, v_wrap, bd.md, v_tz, v_at)
    returning * into v_row;
  end if;
  return jsonb_build_object('ok', true, 'gift', public.zchat_bday_json(v_row), 'coins', (select coins from public.wallets where user_id = me));
end $$;
revoke execute on function public.zchat_bday_gift_save(uuid, text, text, integer, text, text, text, text, text) from public, anon;
grant execute on function public.zchat_bday_gift_save(uuid, text, text, integer, text, text, text, text, text) to authenticated, service_role;

create or replace function public.zchat_bday_gift_cancel(p_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  g public.birthday_gifts%rowtype;
  v_user text;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  perform public.zchat_wallet_lock(me);
  select * into g from public.birthday_gifts where id = p_id and from_id = me for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'That birthday gift is not here anymore.');
  end if;
  if g.status <> 'waiting' then
    return jsonb_build_object('ok', false, 'reason', case when g.status = 'sent' then 'It already went out.' else 'It was already cancelled.' end, 'gift', public.zchat_bday_json(g));
  end if;
  if g.held > 0 then
    select p.username into v_user from public.profiles p where p.id = g.to_id;
    perform public.zchat_coins_move(me, g.held, 'bday_back', 'Birthday gift for @' || coalesce(v_user, 'someone') || ' cancelled', g.to_id);
    perform public.zchat_spend_back(me, g.held);
  end if;
  update public.birthday_gifts set status = 'cancelled', held = 0, updated_at = now() where id = g.id returning * into g;
  return jsonb_build_object('ok', true, 'gift', public.zchat_bday_json(g), 'coins', (select coins from public.wallets where user_id = me));
end $$;
revoke execute on function public.zchat_bday_gift_cancel(uuid) from public, anon;
grant execute on function public.zchat_bday_gift_cancel(uuid) to authenticated, service_role;

create or replace function public.zchat_bday_fail(p_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  g public.birthday_gifts%rowtype;
  v_name text;
begin
  select * into g from public.birthday_gifts where id = p_id for update;
  if not found or g.status <> 'waiting' then
    return;
  end if;
  if g.held > 0 then
    perform public.zchat_coins_move(g.from_id, g.held, 'bday_back', 'Birthday gift returned', g.to_id);
    perform public.zchat_spend_back(g.from_id, g.held);
  end if;
  update public.birthday_gifts set status = 'failed', reason = left(p_reason, 200), held = 0, updated_at = now() where id = g.id;
  select split_part(coalesce(p.name, p.username, 'your friend'), ' ', 1) into v_name from public.profiles p where p.id = g.to_id;
  perform public.zchat_notify(g.from_id, null, 'coins', null, left('Your birthday gift for ' || coalesce(v_name, 'your friend') || ' could not go out. ' || p_reason, 140),
    jsonb_build_object('bday', g.id, 'coins', g.held));
end $$;
revoke execute on function public.zchat_bday_fail(uuid, text) from public, anon, authenticated;
grant execute on function public.zchat_bday_fail(uuid, text) to service_role;

create or replace function public.zchat_bday_deliver()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  g public.birthday_gifts%rowtype;
  n integer := 0;
  why text;
  pr jsonb;
  v_price integer;
  bal integer;
  v_from text;
  v_meta jsonb;
begin
  for g in
    select * from public.birthday_gifts b
    where b.status = 'waiting' and b.deliver_at <= now()
    order by b.deliver_at
    limit 100
    for update skip locked
  loop
    begin
      why := public.zchat_gf_target(g.from_id, g.to_id);
      if why is not null then
        perform public.zchat_bday_fail(g.id, why);
        continue;
      end if;
      v_meta := jsonb_build_object('wrap', coalesce(g.wrap, jsonb_build_object('p', 'birthday', 'r', 'gold')), 'bday', true);
      select p.username into v_from from public.profiles p where p.id = g.from_id;
      if g.kind = 'coins' then
        if g.pay = 'later' then
          begin
            perform public.zchat_spend_count(g.from_id, g.coins);
          exception when sqlstate 'ZL001' then
            perform public.zchat_bday_fail(g.id, 'It went over your monthly limit.');
            continue;
          end;
          bal := public.zchat_coins_move(g.from_id, -g.coins, 'gift_out', 'Birthday gift', g.to_id);
          if bal is null then
            perform public.zchat_bday_fail(g.id, 'You did not have enough coins on the day.');
            continue;
          end if;
        end if;
        if public.zchat_coins_move(g.to_id, g.coins, 'gift_in', coalesce(g.note, 'Birthday gift from @' || coalesce(v_from, 'someone')), g.from_id) is null then
          raise exception 'wallet full';
        end if;
        perform public.zchat_notify(g.to_id, g.from_id, 'gift', null, g.coins || ' coins' || coalesce(', "' || g.note || '"', ''),
          jsonb_build_object('coins', g.coins) || v_meta);
      else
        pr := public.zchat_gf_price(g.to_id, g.kind, g.item_key);
        if not coalesce((pr ->> 'ok')::boolean, false) then
          perform public.zchat_bday_fail(g.id, case when coalesce((pr ->> 'owned')::boolean, false) then 'They already had it, so your coins came back.' else 'That item is not in the Shop anymore.' end);
          continue;
        end if;
        v_price := (pr ->> 'price')::integer;
        if g.pay = 'later' then
          begin
            perform public.zchat_spend_count(g.from_id, v_price);
          exception when sqlstate 'ZL001' then
            perform public.zchat_bday_fail(g.id, 'It went over your monthly limit.');
            continue;
          end;
          bal := public.zchat_coins_move(g.from_id, -v_price, 'gift_item', 'Birthday gift: ' || (pr ->> 'label'), g.to_id);
          if bal is null then
            perform public.zchat_bday_fail(g.id, 'You did not have enough coins on the day.');
            continue;
          end if;
        elsif g.held > v_price then
          perform public.zchat_coins_move(g.from_id, g.held - v_price, 'bday_back', 'Birthday gift change back', g.to_id);
          perform public.zchat_spend_back(g.from_id, g.held - v_price);
        end if;
        perform public.zchat_gf_grant(g.to_id, g.from_id, g.kind, g.item_key, g.note, v_meta);
      end if;
      update public.birthday_gifts set status = 'sent', sent_at = now(), updated_at = now() where id = g.id;
      n := n + 1;
    exception when others then
      raise notice 'zchat birthday gift skipped: %', sqlerrm;
    end;
  end loop;
  return n;
end $$;
revoke execute on function public.zchat_bday_deliver() from public, anon, authenticated;
grant execute on function public.zchat_bday_deliver() to service_role;

select public.zchat_apply_session_gate();
commit;

begin;
create table if not exists public.group_gifts (
  id uuid primary key default gen_random_uuid(),
  organizer_id uuid not null references auth.users(id) on delete cascade,
  to_id uuid not null references auth.users(id) on delete cascade,
  kind text not null,
  item_key text not null,
  label text,
  price integer not null,
  raised integer not null default 0,
  status text not null default 'open',
  note text,
  wrap jsonb,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '7 days',
  done_at timestamptz,
  constraint group_gifts_price_ok check (price > 0 and raised >= 0 and raised <= price),
  constraint group_gifts_status_ok check (status in ('open', 'sent', 'returned', 'cancelled'))
);
create index if not exists zchat_group_gifts_open on public.group_gifts (expires_at) where status = 'open';
create index if not exists zchat_group_gifts_org on public.group_gifts (organizer_id, created_at desc);
alter table public.group_gifts enable row level security;

create table if not exists public.group_gift_people (
  gift_id uuid not null references public.group_gifts(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  coins integer not null default 0,
  invited_at timestamptz not null default now(),
  paid_at timestamptz,
  primary key (gift_id, user_id),
  constraint group_gift_people_coins_ok check (coins >= 0)
);
alter table public.group_gift_people enable row level security;

create or replace function public.zchat_chip_in(p_gift uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select auth.uid() is not null and exists (select 1 from public.group_gift_people p where p.gift_id = p_gift and p.user_id = auth.uid())
$$;
revoke execute on function public.zchat_chip_in(uuid) from public, anon;
grant execute on function public.zchat_chip_in(uuid) to authenticated, service_role;

drop policy if exists "zchat group gifts read" on public.group_gifts;
create policy "zchat group gifts read" on public.group_gifts for select to authenticated using (public.zchat_chip_in(id));
drop policy if exists "zchat group gift people read" on public.group_gift_people;
create policy "zchat group gift people read" on public.group_gift_people for select to authenticated using (public.zchat_chip_in(gift_id));

create or replace function public.zchat_chip_json(p_gift uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object('id', g.id, 'organizer', g.organizer_id, 'to', g.to_id, 'kind', g.kind, 'key', g.item_key, 'label', g.label,
    'price', g.price, 'raised', g.raised, 'status', g.status, 'note', g.note, 'created_at', g.created_at, 'expires_at', g.expires_at, 'done_at', g.done_at,
    'people', coalesce((select jsonb_agg(jsonb_build_object('u', p.user_id, 'c', p.coins, 'at', p.paid_at) order by p.paid_at nulls last, p.invited_at)
      from public.group_gift_people p where p.gift_id = g.id), '[]'::jsonb))
  from public.group_gifts g where g.id = p_gift
$$;
revoke execute on function public.zchat_chip_json(uuid) from public, anon, authenticated;
grant execute on function public.zchat_chip_json(uuid) to service_role;

create or replace function public.zchat_chips(p_ids uuid[])
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(jsonb_agg(public.zchat_chip_json(x.id)), '[]'::jsonb)
  from (select distinct u as id from unnest(coalesce(p_ids, '{}'::uuid[])) u limit 60) x
  where public.zchat_chip_in(x.id)
$$;
revoke execute on function public.zchat_chips(uuid[]) from public, anon;
grant execute on function public.zchat_chips(uuid[]) to authenticated, service_role;

create or replace function public.zchat_chip_refund(p_gift uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  g public.group_gifts%rowtype;
  p record;
  v_name text;
begin
  select * into g from public.group_gifts where id = p_gift for update;
  if not found or g.status <> 'open' then
    return;
  end if;
  select split_part(coalesce(pr.name, pr.username, 'your friend'), ' ', 1) into v_name from public.profiles pr where pr.id = g.to_id;
  for p in select * from public.group_gift_people x where x.gift_id = g.id and x.coins > 0 for update loop
    perform public.zchat_coins_move(p.user_id, p.coins, 'chip_back', 'Group gift for ' || coalesce(v_name, 'a friend') || ' returned', g.to_id);
    perform public.zchat_spend_back(p.user_id, p.coins);
    if p_status = 'returned' then
      perform public.zchat_notify(p.user_id, null, 'coins', null,
        left('The group gift for ' || coalesce(v_name, 'your friend') || ' was not finished in 7 days, so your ' || to_char(p.coins, 'FM999,999') || case when p.coins = 1 then ' coin' else ' coins' end || ' came back', 140),
        jsonb_build_object('coins', p.coins, 'chip', g.id));
    end if;
  end loop;
  update public.group_gift_people set coins = 0 where gift_id = g.id;
  update public.group_gifts set status = p_status, raised = 0, done_at = now() where id = g.id;
end $$;
revoke execute on function public.zchat_chip_refund(uuid, text) from public, anon, authenticated;
grant execute on function public.zchat_chip_refund(uuid, text) to service_role;

create or replace function public.zchat_chip_finish(p_gift uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  g public.group_gifts%rowtype;
  pr jsonb;
  v_price integer;
  v_extra integer;
  v_back integer;
  p record;
  v_names jsonb;
begin
  select * into g from public.group_gifts where id = p_gift for update;
  if not found or g.status <> 'open' or g.raised < g.price then
    return jsonb_build_object('ok', false);
  end if;
  if public.zchat_gf_target(g.organizer_id, g.to_id) is not null then
    perform public.zchat_chip_refund(g.id, 'returned');
    return jsonb_build_object('ok', false, 'reason', 'They cannot get gifts right now, so everyone got their coins back.');
  end if;
  pr := public.zchat_gf_price(g.to_id, g.kind, g.item_key);
  if not coalesce((pr ->> 'ok')::boolean, false) then
    perform public.zchat_chip_refund(g.id, 'returned');
    return jsonb_build_object('ok', false, 'reason', 'They already have it now, so everyone got their coins back.');
  end if;
  v_price := (pr ->> 'price')::integer;
  v_extra := g.raised - v_price;
  if v_extra > 0 then
    for p in select * from public.group_gift_people x where x.gift_id = g.id and x.coins > 0 order by x.paid_at desc nulls last for update loop
      exit when v_extra <= 0;
      v_back := least(v_extra, p.coins);
      perform public.zchat_coins_move(p.user_id, v_back, 'chip_back', 'Group gift change back', g.to_id);
      perform public.zchat_spend_back(p.user_id, v_back);
      update public.group_gift_people set coins = coins - v_back where gift_id = g.id and user_id = p.user_id;
      v_extra := v_extra - v_back;
    end loop;
  end if;
  select coalesce(jsonb_agg(split_part(coalesce(pf.name, pf.username, 'Friend'), ' ', 1) order by (x.user_id = g.organizer_id) desc, x.paid_at), '[]'::jsonb) into v_names
    from public.group_gift_people x join public.profiles pf on pf.id = x.user_id
    where x.gift_id = g.id and (x.coins > 0 or x.user_id = g.organizer_id);
  perform public.zchat_gf_grant(g.to_id, g.organizer_id, g.kind, g.item_key, g.note,
    jsonb_build_object('chip', g.id, 'from', v_names) || case when g.wrap is not null then jsonb_build_object('wrap', g.wrap) else '{}'::jsonb end);
  update public.group_gifts set status = 'sent', raised = least(raised, v_price), done_at = now() where id = g.id;
  for p in select x.user_id from public.group_gift_people x where x.gift_id = g.id and x.user_id <> g.organizer_id and x.coins > 0 loop
    perform public.zchat_notify(p.user_id, g.organizer_id, 'coins', null, 'The group gift you chipped in for was sent', jsonb_build_object('chip', g.id));
  end loop;
  return jsonb_build_object('ok', true, 'sent', true);
end $$;
revoke execute on function public.zchat_chip_finish(uuid) from public, anon, authenticated;
grant execute on function public.zchat_chip_finish(uuid) to service_role;

create or replace function public.zchat_chip_pay(p_gift uuid, p_coins integer)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  g public.group_gifts%rowtype;
  v_take integer;
  bal integer;
  v_name text;
  fin jsonb;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if p_coins is null or p_coins < 1 or p_coins > 100000 then
    return jsonb_build_object('ok', false, 'reason', 'Add at least 1 coin.');
  end if;
  perform public.zchat_wallet_lock(me);
  select * into g from public.group_gifts where id = p_gift for update;
  if not found or not exists (select 1 from public.group_gift_people p where p.gift_id = p_gift and p.user_id = me) then
    return jsonb_build_object('ok', false, 'reason', 'Only people invited to this group gift can add coins.');
  end if;
  if g.status <> 'open' then
    return jsonb_build_object('ok', false, 'reason', case when g.status = 'sent' then 'This gift was already sent.' else 'This group gift has closed.' end, 'gift', public.zchat_chip_json(g.id));
  end if;
  if g.expires_at <= now() then
    return jsonb_build_object('ok', false, 'reason', 'This group gift has closed.', 'gift', public.zchat_chip_json(g.id));
  end if;
  if me = g.to_id then
    return jsonb_build_object('ok', false, 'reason', 'This gift is for you.');
  end if;
  if exists (select 1 from public.profiles p where p.id = me and (coalesce(p.banned, false) or coalesce(p.is_deleted, false) or coalesce(p.is_bot, false))) then
    return jsonb_build_object('ok', false, 'reason', 'Your account cannot send gifts right now.');
  end if;
  v_take := least(p_coins, g.price - g.raised);
  if v_take <= 0 then
    return jsonb_build_object('ok', false, 'reason', 'This gift is already paid for.', 'gift', public.zchat_chip_json(g.id));
  end if;
  select split_part(coalesce(p.name, p.username, 'a friend'), ' ', 1) into v_name from public.profiles p where p.id = g.to_id;
  bal := public.zchat_coins_move(me, -v_take, 'chip_out', left('Group gift for ' || coalesce(v_name, 'a friend'), 120), g.to_id);
  if bal is null then
    return jsonb_build_object('ok', false, 'reason', 'You do not have enough coins.');
  end if;
  update public.group_gift_people set coins = coins + v_take, paid_at = now() where gift_id = g.id and user_id = me;
  update public.group_gifts set raised = raised + v_take where id = g.id;
  if g.raised + v_take >= g.price then
    fin := public.zchat_chip_finish(g.id);
    if not coalesce((fin ->> 'ok')::boolean, false) then
      return jsonb_build_object('ok', false, 'reason', coalesce(fin ->> 'reason', 'The gift could not be sent.'), 'gift', public.zchat_chip_json(g.id),
        'balance', (select coins from public.wallets where user_id = me));
    end if;
  end if;
  return jsonb_build_object('ok', true, 'took', v_take, 'balance', (select coins from public.wallets where user_id = me), 'gift', public.zchat_chip_json(g.id));
end $$;
revoke execute on function public.zchat_chip_pay(uuid, integer) from public, anon;
grant execute on function public.zchat_chip_pay(uuid, integer) to authenticated, service_role;

create or replace function public.zchat_chip_start(p_to uuid, p_kind text, p_key text, p_people uuid[], p_coins integer, p_note text, p_paper text, p_ribbon text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  why text := public.zchat_gift_target_reason(p_to);
  pr jsonb;
  v_id uuid;
  v_note text := nullif(btrim(regexp_replace(left(coalesce(p_note, ''), 80), '[[:cntrl:]]+', ' ', 'g')), '');
  v_wrap jsonb := public.zchat_gf_wrap(auth.uid(), p_paper, p_ribbon);
  u uuid;
  v_ok uuid[] := array[]::uuid[];
  v_msgs jsonb := '[]'::jsonb;
  v_msg public.messages%rowtype;
  v_name text;
  v_words text;
  pay jsonb;
begin
  if why is not null then
    return jsonb_build_object('ok', false, 'reason', why);
  end if;
  if exists (select 1 from public.profiles p where p.id = me and (coalesce(p.banned, false) or coalesce(p.is_deleted, false) or coalesce(p.is_bot, false))) then
    return jsonb_build_object('ok', false, 'reason', 'Your account cannot send gifts right now.');
  end if;
  pr := public.zchat_gf_price(p_to, p_kind, p_key);
  if not coalesce((pr ->> 'ok')::boolean, false) then
    return jsonb_build_object('ok', false, 'reason', pr ->> 'reason');
  end if;
  if (select count(*) from public.group_gifts g where g.organizer_id = me and g.status = 'open') >= 5 then
    return jsonb_build_object('ok', false, 'reason', 'You have 5 group gifts going. Finish or cancel one first.');
  end if;
  if (select count(*) from public.group_gifts g where g.organizer_id = me and g.created_at > now() - interval '1 day') >= 10 then
    return jsonb_build_object('ok', false, 'reason', 'You started a lot of group gifts today. Try again tomorrow.');
  end if;
  foreach u in array coalesce(p_people, '{}'::uuid[]) loop
    exit when array_length(v_ok, 1) >= 20;
    if u is null or u = me or u = p_to or u = any (v_ok) then
      continue;
    end if;
    if public.zchat_gf_target(me, u) is not null or not public.zchat_can_dm(me, u) or public.zchat_blocked_pair(u, p_to) then
      continue;
    end if;
    v_ok := v_ok || u;
  end loop;
  if coalesce(array_length(v_ok, 1), 0) = 0 then
    return jsonb_build_object('ok', false, 'reason', 'Pick at least one friend to chip in with you.');
  end if;
  insert into public.group_gifts (organizer_id, to_id, kind, item_key, label, price, note, wrap)
    values (me, p_to, p_kind, p_key, pr ->> 'label', (pr ->> 'price')::integer, v_note, v_wrap)
    returning id into v_id;
  insert into public.group_gift_people (gift_id, user_id) values (v_id, me);
  insert into public.group_gift_people (gift_id, user_id) select v_id, x from unnest(v_ok) x;
  select split_part(coalesce(p.name, p.username, 'a friend'), ' ', 1) into v_name from public.profiles p where p.id = p_to;
  v_words := 'Chip in for ' || coalesce(v_name, 'a friend') || '''s gift, the ' || (pr ->> 'label');
  perform set_config('zchat.giftcard_ok', '1', true);
  foreach u in array v_ok loop
    insert into public.messages (sender_id, receiver_id, group_id, type, content)
      values (me, u, null, 'text', 'zchip:' || jsonb_build_object('i', v_id, 't', v_words)::text)
      returning * into v_msg;
    insert into public.conversations (user_a, user_b, last_message, last_message_at, last_sender_id)
      values (least(me, u), greatest(me, u), 'Group gift', now(), me)
      on conflict (user_a, user_b) do update set last_message = excluded.last_message, last_message_at = excluded.last_message_at, last_sender_id = excluded.last_sender_id;
    v_msgs := v_msgs || jsonb_build_array(to_jsonb(v_msg));
  end loop;
  perform set_config('zchat.giftcard_ok', '', true);
  if coalesce(p_coins, 0) > 0 then
    pay := public.zchat_chip_pay(v_id, p_coins);
    if not coalesce((pay ->> 'ok')::boolean, false) then
      raise exception '%', coalesce(pay ->> 'reason', 'Your coins could not go in') using errcode = 'P0001';
    end if;
  end if;
  return jsonb_build_object('ok', true, 'gift', public.zchat_chip_json(v_id), 'messages', v_msgs, 'balance', (select coins from public.wallets where user_id = me));
end $$;
revoke execute on function public.zchat_chip_start(uuid, text, text, uuid[], integer, text, text, text) from public, anon;
grant execute on function public.zchat_chip_start(uuid, text, text, uuid[], integer, text, text, text) to authenticated, service_role;

create or replace function public.zchat_chip_cancel(p_gift uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  g public.group_gifts%rowtype;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  select * into g from public.group_gifts where id = p_gift for update;
  if not found or g.organizer_id <> me then
    return jsonb_build_object('ok', false, 'reason', 'Only the person who started it can cancel it.');
  end if;
  if g.status <> 'open' then
    return jsonb_build_object('ok', false, 'reason', 'This group gift has closed.', 'gift', public.zchat_chip_json(g.id));
  end if;
  perform public.zchat_chip_refund(g.id, 'cancelled');
  return jsonb_build_object('ok', true, 'gift', public.zchat_chip_json(g.id), 'balance', (select coins from public.wallets where user_id = me));
end $$;
revoke execute on function public.zchat_chip_cancel(uuid) from public, anon;
grant execute on function public.zchat_chip_cancel(uuid) to authenticated, service_role;

create or replace function public.zchat_chip_sweep()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  r record;
  n integer := 0;
begin
  for r in
    select g.id from public.group_gifts g
    where g.status = 'open' and g.expires_at <= now()
    order by g.expires_at
    limit 100
    for update skip locked
  loop
    begin
      perform public.zchat_chip_refund(r.id, 'returned');
      n := n + 1;
    exception when others then
      raise notice 'zchat chip sweep skipped: %', sqlerrm;
    end;
  end loop;
  return n;
end $$;
revoke execute on function public.zchat_chip_sweep() from public, anon, authenticated;
grant execute on function public.zchat_chip_sweep() to service_role;

do $$
declare
  t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime' and not puballtables) then
    foreach t in array array['group_gifts', 'group_gift_people'] loop
      if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
        execute format('alter publication supabase_realtime add table public.%I', t);
      end if;
    end loop;
  end if;
end $$;

select public.zchat_apply_session_gate();
commit;

begin;
create table if not exists public.santa_events (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.groups(id) on delete cascade,
  organizer_id uuid not null references auth.users(id) on delete cascade,
  budget integer not null,
  join_until timestamptz not null,
  reveal_at timestamptz not null,
  status text not null default 'open',
  note text,
  message_id bigint,
  created_at timestamptz not null default now(),
  drawn_at timestamptz,
  reminded_at timestamptz,
  revealed_at timestamptz,
  constraint santa_events_budget_ok check (budget between 50 and 5000),
  constraint santa_events_dates_ok check (reveal_at > join_until),
  constraint santa_events_status_ok check (status in ('open', 'drawn', 'revealed', 'cancelled'))
);
alter table public.santa_events add column if not exists picked integer not null default 0;
create index if not exists zchat_santa_events_group on public.santa_events (group_id, created_at desc);
create index if not exists zchat_santa_events_due on public.santa_events (status, join_until, reveal_at) where status in ('open', 'drawn');
alter table public.santa_events enable row level security;

create table if not exists public.santa_people (
  event_id uuid not null references public.santa_events(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  joined_at timestamptz not null default now(),
  primary key (event_id, user_id)
);
alter table public.santa_people enable row level security;

create table if not exists public.santa_pairs (
  event_id uuid not null references public.santa_events(id) on delete cascade,
  giver_id uuid not null references auth.users(id) on delete cascade,
  receiver_id uuid not null references auth.users(id) on delete cascade,
  kind text,
  item_key text,
  price integer not null default 0,
  note text,
  picked_at timestamptz,
  outcome text,
  primary key (event_id, giver_id),
  constraint santa_pairs_receiver_once unique (event_id, receiver_id),
  constraint santa_pairs_not_self check (giver_id <> receiver_id)
);
alter table public.santa_pairs enable row level security;

create or replace function public.zchat_santa_member(p_event uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select auth.uid() is not null and exists (
    select 1 from public.santa_events e join public.group_members gm on gm.group_id = e.group_id and gm.user_id = auth.uid()
    where e.id = p_event
  )
$$;
revoke execute on function public.zchat_santa_member(uuid) from public, anon;
grant execute on function public.zchat_santa_member(uuid) to authenticated, service_role;

drop policy if exists "zchat santa events read" on public.santa_events;
create policy "zchat santa events read" on public.santa_events for select to authenticated using (is_group_member(group_id, auth.uid()));
drop policy if exists "zchat santa people read" on public.santa_people;
create policy "zchat santa people read" on public.santa_people for select to authenticated using (public.zchat_santa_member(event_id));
drop policy if exists "zchat santa pairs read" on public.santa_pairs;
create policy "zchat santa pairs read" on public.santa_pairs for select to authenticated
  using (giver_id = auth.uid() or (public.zchat_santa_member(event_id) and exists (select 1 from public.santa_events e where e.id = event_id and e.status = 'revealed')));

create or replace function public.zchat_santa_json(p_event uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object('id', e.id, 'group', e.group_id, 'organizer', e.organizer_id, 'budget', e.budget, 'join_until', e.join_until,
    'reveal_at', e.reveal_at, 'status', e.status, 'note', e.note, 'message_id', e.message_id, 'drawn_at', e.drawn_at, 'revealed_at', e.revealed_at,
    'people', coalesce((select jsonb_agg(p.user_id order by p.joined_at) from public.santa_people p where p.event_id = e.id), '[]'::jsonb),
    'my', (select jsonb_build_object('to', x.receiver_id, 'kind', x.kind, 'key', x.item_key, 'price', x.price, 'note', x.note, 'picked_at', x.picked_at)
      from public.santa_pairs x where x.event_id = e.id and x.giver_id = auth.uid()),
    'picked', (select count(*) from public.santa_pairs x where x.event_id = e.id and x.kind is not null),
    'pairs', case when e.status = 'revealed' then coalesce((select jsonb_agg(jsonb_build_object('g', x.giver_id, 'r', x.receiver_id, 'kind', x.kind, 'key', x.item_key, 'o', x.outcome) order by x.picked_at nulls last)
      from public.santa_pairs x where x.event_id = e.id), '[]'::jsonb) end)
  from public.santa_events e where e.id = p_event
$$;
revoke execute on function public.zchat_santa_json(uuid) from public, anon, authenticated;
grant execute on function public.zchat_santa_json(uuid) to service_role;

create or replace function public.zchat_santas(p_ids uuid[])
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(jsonb_agg(public.zchat_santa_json(x.id)), '[]'::jsonb)
  from (select distinct u as id from unnest(coalesce(p_ids, '{}'::uuid[])) u limit 30) x
  where public.zchat_santa_member(x.id)
$$;
revoke execute on function public.zchat_santas(uuid[]) from public, anon;
grant execute on function public.zchat_santas(uuid[]) to authenticated, service_role;

create or replace function public.zchat_santa_start(p_group uuid, p_budget integer, p_join_until timestamptz, p_reveal_at timestamptz, p_note text default null, p_client_id text default null, p_topic text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  v_id uuid;
  v_join timestamptz := date_trunc('minute', p_join_until);
  v_reveal timestamptz := date_trunc('minute', p_reveal_at);
  v_note text := nullif(btrim(regexp_replace(left(coalesce(p_note, ''), 120), '[[:cntrl:]]+', ' ', 'g')), '');
  v_msg public.messages%rowtype;
  v_gname text;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if not exists (select 1 from public.group_members gm where gm.group_id = p_group and gm.user_id = me) then
    return jsonb_build_object('ok', false, 'reason', 'Only people in this group can start Secret Santa here.');
  end if;
  if not public.is_group_member_unmuted(p_group, me) or not public.zchat_can_post_group(p_group, 'text') then
    return jsonb_build_object('ok', false, 'reason', 'You cannot send messages in this group right now.');
  end if;
  if exists (select 1 from public.profiles p where p.id = me and (coalesce(p.banned, false) or coalesce(p.is_deleted, false) or coalesce(p.is_bot, false))) then
    return jsonb_build_object('ok', false, 'reason', 'Your account cannot start Secret Santa right now.');
  end if;
  if p_budget is null or p_budget < 50 or p_budget > 5000 then
    return jsonb_build_object('ok', false, 'reason', 'Pick a budget from 50 to 5,000 coins.');
  end if;
  if v_join is null or v_join < now() + interval '10 minutes' or v_join > now() + interval '60 days' then
    return jsonb_build_object('ok', false, 'reason', 'People need at least 10 minutes to join, and at most 60 days.');
  end if;
  if v_reveal is null or v_reveal < v_join + interval '1 hour' or v_reveal > v_join + interval '60 days' then
    return jsonb_build_object('ok', false, 'reason', 'The gifts open at least an hour after joining closes.');
  end if;
  if exists (select 1 from public.santa_events e where e.group_id = p_group and e.status in ('open', 'drawn')) then
    return jsonb_build_object('ok', false, 'reason', 'This group already has a Secret Santa going.');
  end if;
  if (select count(*) from public.santa_events e where e.organizer_id = me and e.created_at > now() - interval '1 day') >= 5 then
    return jsonb_build_object('ok', false, 'reason', 'You started a lot of Secret Santas today. Try again tomorrow.');
  end if;
  insert into public.santa_events (group_id, organizer_id, budget, join_until, reveal_at, note)
    values (p_group, me, p_budget, v_join, v_reveal, v_note) returning id into v_id;
  insert into public.santa_people (event_id, user_id) values (v_id, me);
  select g.name into v_gname from public.groups g where g.id = p_group;
  perform set_config('zchat.giftcard_ok', '1', true);
  insert into public.messages (sender_id, receiver_id, group_id, type, content, client_id, topic)
    values (me, null, p_group, 'text', 'zsanta:' || jsonb_build_object('i', v_id, 't', 'Secret Santa in ' || coalesce(v_gname, 'the group') || ', budget ' || p_budget || ' coins')::text,
      nullif(left(coalesce(p_client_id, ''), 80), ''), nullif(left(btrim(coalesce(p_topic, '')), 40), ''))
    returning * into v_msg;
  perform set_config('zchat.giftcard_ok', '', true);
  update public.santa_events set message_id = v_msg.id where id = v_id;
  return jsonb_build_object('ok', true, 'event', public.zchat_santa_json(v_id), 'message', to_jsonb(v_msg));
end $$;
revoke execute on function public.zchat_santa_start(uuid, integer, timestamptz, timestamptz, text, text, text) from public, anon;
grant execute on function public.zchat_santa_start(uuid, integer, timestamptz, timestamptz, text, text, text) to authenticated, service_role;

create or replace function public.zchat_santa_join(p_event uuid, p_on boolean default true)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  e public.santa_events%rowtype;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  select * into e from public.santa_events where id = p_event for update;
  if not found or not exists (select 1 from public.group_members gm where gm.group_id = e.group_id and gm.user_id = me) then
    return jsonb_build_object('ok', false, 'reason', 'Only people in this group can join.');
  end if;
  if e.status <> 'open' or e.join_until <= now() then
    return jsonb_build_object('ok', false, 'reason', 'Joining has closed for this Secret Santa.', 'event', public.zchat_santa_json(e.id));
  end if;
  if coalesce(p_on, true) then
    if exists (select 1 from public.profiles p where p.id = me and (coalesce(p.banned, false) or coalesce(p.is_deleted, false) or coalesce(p.is_bot, false))) then
      return jsonb_build_object('ok', false, 'reason', 'Your account cannot join right now.');
    end if;
    if (select count(*) from public.santa_people p where p.event_id = e.id) >= 100 then
      return jsonb_build_object('ok', false, 'reason', 'This Secret Santa is full.');
    end if;
    insert into public.santa_people (event_id, user_id) values (e.id, me) on conflict do nothing;
  else
    delete from public.santa_people where event_id = e.id and user_id = me;
  end if;
  return jsonb_build_object('ok', true, 'event', public.zchat_santa_json(e.id));
end $$;
revoke execute on function public.zchat_santa_join(uuid, boolean) from public, anon;
grant execute on function public.zchat_santa_join(uuid, boolean) to authenticated, service_role;

create or replace function public.zchat_santa_pick(p_event uuid, p_kind text, p_key text, p_note text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  e public.santa_events%rowtype;
  x public.santa_pairs%rowtype;
  pr jsonb;
  v_price integer;
  bal integer;
  v_note text := nullif(btrim(regexp_replace(left(coalesce(p_note, ''), 80), '[[:cntrl:]]+', ' ', 'g')), '');
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  perform public.zchat_wallet_lock(me);
  select * into e from public.santa_events where id = p_event for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'This Secret Santa is not here anymore.');
  end if;
  select * into x from public.santa_pairs where event_id = e.id and giver_id = me for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'You are not giving a gift in this Secret Santa.');
  end if;
  if e.status <> 'drawn' or e.reveal_at <= now() then
    return jsonb_build_object('ok', false, 'reason', 'Gifts can not be changed anymore.', 'event', public.zchat_santa_json(e.id));
  end if;
  if p_kind is null then
    if x.price > 0 then
      perform public.zchat_coins_move(me, x.price, 'santa_back', 'Secret Santa gift changed', null);
      perform public.zchat_spend_back(me, x.price);
    end if;
    update public.santa_pairs set kind = null, item_key = null, price = 0, note = null, picked_at = null where event_id = e.id and giver_id = me;
    update public.santa_events set picked = (select count(*) from public.santa_pairs p where p.event_id = e.id and p.kind is not null) where id = e.id;
    return jsonb_build_object('ok', true, 'event', public.zchat_santa_json(e.id), 'balance', (select coins from public.wallets where user_id = me));
  end if;
  if public.zchat_gf_target(me, x.receiver_id) is not null then
    return jsonb_build_object('ok', false, 'reason', public.zchat_gf_target(me, x.receiver_id));
  end if;
  pr := public.zchat_gf_price(x.receiver_id, p_kind, p_key);
  if not coalesce((pr ->> 'ok')::boolean, false) then
    return jsonb_build_object('ok', false, 'reason', pr ->> 'reason');
  end if;
  v_price := (pr ->> 'price')::integer;
  if v_price > e.budget then
    return jsonb_build_object('ok', false, 'reason', 'That costs more than the budget of ' || e.budget || ' coins.');
  end if;
  begin
    if x.price > 0 then
      perform public.zchat_coins_move(me, x.price, 'santa_back', 'Secret Santa gift changed', null);
      perform public.zchat_spend_back(me, x.price);
    end if;
    bal := public.zchat_coins_move(me, -v_price, 'santa_out', 'Secret Santa gift', null);
    if bal is null then
      raise exception 'short' using errcode = 'ZG001';
    end if;
  exception when sqlstate 'ZG001' then
    return jsonb_build_object('ok', false, 'reason', 'You do not have enough coins.');
  end;
  update public.santa_pairs set kind = p_kind, item_key = p_key, price = v_price, note = v_note, picked_at = now()
    where event_id = e.id and giver_id = me;
  update public.santa_events set picked = (select count(*) from public.santa_pairs p where p.event_id = e.id and p.kind is not null) where id = e.id;
  return jsonb_build_object('ok', true, 'event', public.zchat_santa_json(e.id), 'balance', bal);
end $$;
revoke execute on function public.zchat_santa_pick(uuid, text, text, text) from public, anon;
grant execute on function public.zchat_santa_pick(uuid, text, text, text) to authenticated, service_role;

create or replace function public.zchat_santa_refund(p_event uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  x record;
begin
  for x in select * from public.santa_pairs p where p.event_id = p_event and p.price > 0 and p.outcome is null for update loop
    perform public.zchat_coins_move(x.giver_id, x.price, 'santa_back', 'Secret Santa cancelled', null);
    perform public.zchat_spend_back(x.giver_id, x.price);
    update public.santa_pairs set outcome = 'returned' where event_id = p_event and giver_id = x.giver_id;
  end loop;
end $$;
revoke execute on function public.zchat_santa_refund(uuid) from public, anon, authenticated;
grant execute on function public.zchat_santa_refund(uuid) to service_role;

create or replace function public.zchat_santa_cancel(p_event uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  e public.santa_events%rowtype;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  select * into e from public.santa_events where id = p_event for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'This Secret Santa is not here anymore.');
  end if;
  if e.organizer_id <> me and coalesce(public.zchat_my_group_role(e.group_id), '') not in ('owner', 'admin') then
    return jsonb_build_object('ok', false, 'reason', 'Only the person who started it or a group admin can cancel it.');
  end if;
  if e.status not in ('open', 'drawn') then
    return jsonb_build_object('ok', false, 'reason', 'This Secret Santa is already over.', 'event', public.zchat_santa_json(e.id));
  end if;
  perform public.zchat_santa_refund(e.id);
  update public.santa_events set status = 'cancelled' where id = e.id;
  return jsonb_build_object('ok', true, 'event', public.zchat_santa_json(e.id), 'balance', (select coins from public.wallets where user_id = me));
end $$;
revoke execute on function public.zchat_santa_cancel(uuid) from public, anon;
grant execute on function public.zchat_santa_cancel(uuid) to authenticated, service_role;

create or replace function public.zchat_santa_tick()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  e public.santa_events%rowtype;
  x record;
  v_list uuid[];
  v_n integer;
  i integer;
  n integer := 0;
  v_gname text;
  pr jsonb;
  v_msg public.messages%rowtype;
begin
  for e in
    select * from public.santa_events s
    where s.status = 'open' and s.join_until <= now()
    order by s.join_until limit 50
    for update skip locked
  loop
    begin
      select g.name into v_gname from public.groups g where g.id = e.group_id;
      select array_agg(p.user_id order by random()) into v_list
        from public.santa_people p
        join public.group_members gm on gm.group_id = e.group_id and gm.user_id = p.user_id
        join public.profiles pf on pf.id = p.user_id and not coalesce(pf.banned, false) and not coalesce(pf.is_deleted, false) and not coalesce(pf.is_bot, false)
        where p.event_id = e.id;
      v_n := coalesce(array_length(v_list, 1), 0);
      if v_n < 3 then
        update public.santa_events set status = 'cancelled' where id = e.id;
        perform public.zchat_notify(e.organizer_id, null, 'santa', null, left('Secret Santa in ' || coalesce(v_gname, 'your group') || ' needed at least 3 people, so it did not start', 140),
          jsonb_build_object('santa', e.id, 'group', e.group_id, 'ev', 'small'));
        n := n + 1;
        continue;
      end if;
      for i in 1..v_n loop
        insert into public.santa_pairs (event_id, giver_id, receiver_id) values (e.id, v_list[i], v_list[(i % v_n) + 1]);
      end loop;
      update public.santa_events set status = 'drawn', drawn_at = now() where id = e.id;
      for i in 1..v_n loop
        perform public.zchat_notify(v_list[i], null, 'santa', null, left('Names are drawn for Secret Santa in ' || coalesce(v_gname, 'your group') || '. See who you are giving to', 140),
          jsonb_build_object('santa', e.id, 'group', e.group_id, 'ev', 'drawn'));
      end loop;
      n := n + 1;
    exception when others then
      raise notice 'zchat santa draw skipped: %', sqlerrm;
    end;
  end loop;

  for e in
    select * from public.santa_events s
    where s.status = 'drawn' and s.reminded_at is null and s.reveal_at <= now() + interval '24 hours' and s.reveal_at > now()
    order by s.reveal_at limit 50
    for update skip locked
  loop
    begin
      select g.name into v_gname from public.groups g where g.id = e.group_id;
      for x in select p.giver_id from public.santa_pairs p where p.event_id = e.id and p.kind is null loop
        perform public.zchat_notify(x.giver_id, null, 'santa', null, left('Secret Santa in ' || coalesce(v_gname, 'your group') || ' opens soon. Pick your gift', 140),
          jsonb_build_object('santa', e.id, 'group', e.group_id, 'ev', 'remind'));
      end loop;
      update public.santa_events set reminded_at = now() where id = e.id;
    exception when others then
      raise notice 'zchat santa remind skipped: %', sqlerrm;
    end;
  end loop;

  for e in
    select * from public.santa_events s
    where s.status = 'drawn' and s.reveal_at <= now()
    order by s.reveal_at limit 50
    for update skip locked
  loop
    begin
      select g.name into v_gname from public.groups g where g.id = e.group_id;
      for x in select * from public.santa_pairs p where p.event_id = e.id and p.kind is not null and p.outcome is null for update loop
        if public.zchat_gf_target(x.giver_id, x.receiver_id) is not null then
          pr := jsonb_build_object('ok', false);
        else
          pr := public.zchat_gf_grant(x.receiver_id, x.giver_id, x.kind, x.item_key, x.note,
            jsonb_build_object('santa', e.id, 'group', e.group_id, 'wrap', jsonb_build_object('p', 'stars', 'r', 'red')));
        end if;
        if coalesce((pr ->> 'ok')::boolean, false) then
          if (pr ->> 'price')::integer < x.price then
            perform public.zchat_coins_move(x.giver_id, x.price - (pr ->> 'price')::integer, 'santa_back', 'Secret Santa change back', null);
            perform public.zchat_spend_back(x.giver_id, x.price - (pr ->> 'price')::integer);
          end if;
          update public.santa_pairs set outcome = 'sent' where event_id = e.id and giver_id = x.giver_id;
        else
          perform public.zchat_coins_move(x.giver_id, x.price, 'santa_back', 'Secret Santa gift returned', null);
          perform public.zchat_spend_back(x.giver_id, x.price);
          update public.santa_pairs set outcome = 'returned' where event_id = e.id and giver_id = x.giver_id;
        end if;
      end loop;
      update public.santa_events set status = 'revealed', revealed_at = now() where id = e.id;
      perform set_config('zchat.giftcard_ok', '1', true);
      insert into public.messages (sender_id, receiver_id, group_id, type, content)
        values (e.organizer_id, null, e.group_id, 'text', 'zsanta:' || jsonb_build_object('i', e.id, 'r', 1, 't', 'Secret Santa is open in ' || coalesce(v_gname, 'the group'))::text)
        returning * into v_msg;
      perform set_config('zchat.giftcard_ok', '', true);
      n := n + 1;
    exception when others then
      perform set_config('zchat.giftcard_ok', '', true);
      raise notice 'zchat santa reveal skipped: %', sqlerrm;
    end;
  end loop;
  return n;
end $$;
revoke execute on function public.zchat_santa_tick() from public, anon, authenticated;
grant execute on function public.zchat_santa_tick() to service_role;

do $$
declare
  t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime' and not puballtables) then
    foreach t in array array['santa_events', 'santa_people'] loop
      if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
        execute format('alter publication supabase_realtime add table public.%I', t);
      end if;
    end loop;
  end if;
end $$;

select public.zchat_apply_session_gate();
commit;

begin;
create table if not exists public.verified_gift_orders (
  id uuid primary key default gen_random_uuid(),
  from_id uuid not null references auth.users(id) on delete cascade,
  to_id uuid not null references auth.users(id) on delete cascade,
  note text,
  status text not null default 'open',
  order_id text unique,
  total integer,
  tier text,
  days integer not null default 30,
  starts_at timestamptz,
  ends_at timestamptz,
  reason text,
  created_at timestamptz not null default now(),
  paid_at timestamptz,
  constraint verified_gift_orders_status_ok check (status in ('open', 'paid', 'refunded', 'failed')),
  constraint verified_gift_orders_days_ok check (days between 1 and 366)
);
create index if not exists zchat_verified_gift_orders_from on public.verified_gift_orders (from_id, created_at desc);
alter table public.verified_gift_orders enable row level security;
drop policy if exists "zchat verified gift orders read" on public.verified_gift_orders;
create policy "zchat verified gift orders read" on public.verified_gift_orders for select to authenticated using (from_id = auth.uid());

create table if not exists public.verified_state (
  user_id uuid primary key references auth.users(id) on delete cascade,
  sub_until timestamptz,
  gift_until timestamptz,
  tier text,
  updated_at timestamptz not null default now()
);
alter table public.verified_state enable row level security;

create or replace function public.zchat_set_verified_sub(p_user uuid, p_until timestamptz, p_tier text default 'blue')
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  cur record;
  v_gift timestamptz;
begin
  select verified, verified_until into cur from public.profiles where id = p_user;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no such user');
  end if;
  if cur.verified is not null and cur.verified <> '' and cur.verified_until is null and cur.verified <> coalesce(p_tier, 'blue') then
    return jsonb_build_object('ok', true, 'kept', cur.verified);
  end if;
  insert into public.verified_state (user_id, sub_until, tier) values (p_user, p_until, coalesce(nullif(p_tier, ''), 'blue'))
    on conflict (user_id) do update set sub_until = excluded.sub_until, updated_at = now();
  select gift_until into v_gift from public.verified_state where user_id = p_user;
  if v_gift is not null and v_gift > now() then
    update public.profiles set verified = coalesce(nullif(p_tier, ''), 'blue'), verified_until = greatest(coalesce(p_until, v_gift), v_gift) where id = p_user;
    return jsonb_build_object('ok', true, 'until', greatest(coalesce(p_until, v_gift), v_gift), 'gift', true);
  end if;
  if p_until is null or p_until <= now() then
    update public.profiles set verified = case when verified_until is not null then null else verified end, verified_until = null where id = p_user;
    return jsonb_build_object('ok', true, 'ended', true);
  end if;
  update public.profiles set verified = coalesce(nullif(p_tier, ''), 'blue'), verified_until = p_until where id = p_user;
  return jsonb_build_object('ok', true, 'until', p_until);
end $$;

create or replace function public.zchat_verified_gift_check(p_from uuid, p_to uuid)
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  why text := public.zchat_gf_target(p_from, p_to);
  pr record;
begin
  if why is not null then
    return why;
  end if;
  select p.verified, p.verified_until into pr from public.profiles p where p.id = p_to;
  if pr.verified is not null and pr.verified <> '' and pr.verified_until is null then
    return 'They already have a badge from the ZChat team.';
  end if;
  if pr.verified_until is not null and pr.verified_until > now() + interval '330 days' then
    return 'Their badge is already on for most of the next year.';
  end if;
  return null;
end $$;
revoke execute on function public.zchat_verified_gift_check(uuid, uuid) from public, anon, authenticated;
grant execute on function public.zchat_verified_gift_check(uuid, uuid) to service_role;

create or replace function public.zchat_verified_gift_start(p_to uuid, p_note text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  why text;
  v_id uuid;
  v_until timestamptz;
  v_note text := nullif(btrim(regexp_replace(left(coalesce(p_note, ''), 80), '[[:cntrl:]]+', ' ', 'g')), '');
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  why := public.zchat_verified_gift_check(me, p_to);
  if why is not null then
    return jsonb_build_object('ok', false, 'reason', why);
  end if;
  if (select count(*) from public.verified_gift_orders o where o.from_id = me and o.created_at > now() - interval '1 day') >= 10 then
    return jsonb_build_object('ok', false, 'reason', 'You started a lot of Verified gifts today. Try again tomorrow.');
  end if;
  insert into public.verified_gift_orders (from_id, to_id, note) values (me, p_to, v_note) returning id into v_id;
  select case when p.verified_until > now() then p.verified_until end into v_until from public.profiles p where p.id = p_to;
  return jsonb_build_object('ok', true, 'token', v_id, 'until', v_until);
end $$;
revoke execute on function public.zchat_verified_gift_start(uuid, text) from public, anon;
grant execute on function public.zchat_verified_gift_start(uuid, text) to authenticated, service_role;

create or replace function public.zchat_verified_gift_paid(p_token uuid, p_buyer uuid, p_order text, p_total integer, p_tier text default 'blue')
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  o public.verified_gift_orders%rowtype;
  why text;
  v_tier text := coalesce(nullif(lower(btrim(coalesce(p_tier, ''))), ''), 'blue');
  pr record;
  v_start timestamptz;
  v_end timestamptz;
  st public.verified_state%rowtype;
  v_buyer text;
begin
  if p_order is null or btrim(p_order) = '' then
    return jsonb_build_object('ok', false, 'reason', 'no order');
  end if;
  if exists (select 1 from public.verified_gift_orders x where x.order_id = p_order) then
    return jsonb_build_object('ok', true, 'duplicate', true);
  end if;
  select * into o from public.verified_gift_orders where id = p_token for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no such gift');
  end if;
  if o.from_id <> p_buyer then
    return jsonb_build_object('ok', false, 'reason', 'buyer mismatch');
  end if;
  if o.status <> 'open' then
    return jsonb_build_object('ok', true, 'duplicate', true, 'status', o.status);
  end if;
  why := public.zchat_verified_gift_check(o.from_id, o.to_id);
  if why is not null then
    update public.verified_gift_orders set status = 'failed', order_id = p_order, total = p_total, reason = why, paid_at = now() where id = o.id;
    perform public.zchat_notify(o.from_id, null, 'coins', null, left('Your Verified gift could not be given: ' || why || ' Write to support@getzchat.com for a refund.', 140),
      jsonb_build_object('vgift', o.id));
    return jsonb_build_object('ok', false, 'reason', why, 'held', true);
  end if;
  perform 1 from public.profiles where id = o.to_id for update;
  select p.verified, p.verified_until into pr from public.profiles p where p.id = o.to_id;
  v_start := case when pr.verified = v_tier and pr.verified_until is not null and pr.verified_until > now() then pr.verified_until else now() end;
  v_end := v_start + make_interval(days => o.days);
  insert into public.verified_state (user_id, gift_until, tier) values (o.to_id, v_end, v_tier)
    on conflict (user_id) do update set gift_until = excluded.gift_until, tier = excluded.tier, updated_at = now()
    returning * into st;
  update public.profiles set verified = v_tier, verified_seen = v_tier, verified_until = greatest(v_end, coalesce(st.sub_until, v_end)) where id = o.to_id;
  update public.verified_gift_orders set status = 'paid', order_id = p_order, total = p_total, tier = v_tier, starts_at = v_start, ends_at = v_end, paid_at = now() where id = o.id;
  select p.username into v_buyer from public.profiles p where p.id = o.from_id;
  perform public.zchat_notify(o.to_id, o.from_id, 'gift', null, left('a month of ZChat Verified' || coalesce(', "' || o.note || '"', ''), 140),
    jsonb_build_object('kind', 'verified', 'key', v_tier, 'days', o.days, 'until', v_end, 'start', v_start, 'wrap', jsonb_build_object('p', 'sky', 'r', 'white')));
  return jsonb_build_object('ok', true, 'until', v_end);
end $$;
revoke execute on function public.zchat_verified_gift_paid(uuid, uuid, text, integer, text) from public, anon, authenticated;
grant execute on function public.zchat_verified_gift_paid(uuid, uuid, text, integer, text) to service_role;

create or replace function public.zchat_verified_gift_refund(p_order text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  o public.verified_gift_orders%rowtype;
  st public.verified_state%rowtype;
  v_gift timestamptz;
  v_until timestamptz;
begin
  select * into o from public.verified_gift_orders where order_id = p_order for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no such order');
  end if;
  if o.status = 'refunded' then
    return jsonb_build_object('ok', true, 'duplicate', true);
  end if;
  if o.status <> 'paid' then
    update public.verified_gift_orders set status = 'refunded' where id = o.id;
    return jsonb_build_object('ok', true, 'nothing', true);
  end if;
  update public.verified_gift_orders set status = 'refunded' where id = o.id;
  select * into st from public.verified_state where user_id = o.to_id for update;
  if found and st.gift_until is not null then
    v_gift := st.gift_until - make_interval(days => o.days);
    if v_gift <= now() then
      v_gift := null;
    end if;
    update public.verified_state set gift_until = v_gift, updated_at = now() where user_id = o.to_id;
    v_until := case
      when v_gift is null and (st.sub_until is null or st.sub_until <= now()) then null
      else greatest(coalesce(v_gift, st.sub_until), coalesce(st.sub_until, v_gift)) end;
    update public.profiles set verified_until = v_until, verified = case when v_until is null then null else verified end
      where id = o.to_id and verified_until is not null;
  end if;
  return jsonb_build_object('ok', true);
end $$;
revoke execute on function public.zchat_verified_gift_refund(text) from public, anon, authenticated;
grant execute on function public.zchat_verified_gift_refund(text) to service_role;

select public.zchat_apply_session_gate();

create or replace function public.zchat_gifts_tick()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  a integer := 0;
  b integer := 0;
  c integer := 0;
  d integer := 0;
begin
  if not pg_try_advisory_xact_lock(hashtextextended('zchat gifts tick', 0)) then
    return jsonb_build_object('busy', true);
  end if;
  begin a := public.zchat_bag_sweep(); exception when others then raise notice 'zchat bag sweep failed: %', sqlerrm; end;
  begin b := public.zchat_bday_deliver(); exception when others then raise notice 'zchat birthday gifts failed: %', sqlerrm; end;
  begin c := public.zchat_chip_sweep(); exception when others then raise notice 'zchat chip sweep failed: %', sqlerrm; end;
  begin d := public.zchat_santa_tick(); exception when others then raise notice 'zchat santa tick failed: %', sqlerrm; end;
  return jsonb_build_object('bags', a, 'birthdays', b, 'chips', c, 'santa', d);
end $$;
revoke execute on function public.zchat_gifts_tick() from public, anon, authenticated;
grant execute on function public.zchat_gifts_tick() to service_role;

do $$
begin
  if exists (select 1 from pg_namespace where nspname = 'cron')
     and exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'cron' and p.proname = 'schedule') then
    perform cron.schedule('zchat-gifts', '* * * * *', 'select public.zchat_gifts_tick()');
  end if;
end $$;

do $$
declare
  v text[];
  t record;
  k text;
begin
  for t in select * from (values
    ('shop_items', 'shop_items_kind_check', array['frame', 'nameplate', 'charm', 'bubble', 'effect', 'namestyle', 'theme', 'reaction', 'wallpaper']),
    ('user_rewards', 'user_rewards_kind_check', array['frame', 'nameplate', 'charm', 'bubble', 'effect', 'namestyle', 'theme', 'reaction', 'wallpaper']),
    ('wishlist_items', 'wishlist_items_kind_check', array['set', 'bubble', 'charm', 'namestyle', 'theme', 'reaction', 'wallpaper'])
  ) as x(tbl, con, dflt) loop
    if to_regclass('public.' || t.tbl) is null then
      continue;
    end if;
    select array_agg(distinct m[1] order by m[1]) into v
    from pg_constraint c, regexp_matches(pg_get_constraintdef(c.oid), '([a-z_]+)', 'g') as m
    where c.conname = t.con and c.conrelid = ('public.' || t.tbl)::regclass and m[1] not in ('kind', 'text');
    if v is null then
      v := t.dflt;
    end if;
    if not (v @> array['stickerpack', 'soundpack', 'typing']) then
      foreach k in array array['stickerpack', 'soundpack', 'typing'] loop
        if not (k = any (v)) then
          v := v || k;
        end if;
      end loop;
      execute format('alter table public.%I drop constraint if exists %I', t.tbl, t.con);
      execute format('alter table public.%I add constraint %I check (kind = any (%L::text[]))', t.tbl, t.con, v);
    end if;
  end loop;
end $$;

