create or replace function public.zchat_buy_item(p_kind text, p_key text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  it public.shop_items%rowtype;
  bal integer;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if p_kind is null or p_kind not in ('frame', 'nameplate', 'effect', 'charm', 'bubble', 'namestyle', 'theme', 'reaction', 'wallpaper', 'stickerpack', 'soundpack', 'typing') then
    return jsonb_build_object('ok', false, 'reason', 'That item is not in the Shop.');
  end if;
  select * into it from public.shop_items where kind = p_kind and key = p_key and active;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'That item is not in the Shop.');
  end if;
  perform public.zchat_wallet_lock(me);
  if public.zchat_owns_forever(me, p_kind, p_key) then
    return jsonb_build_object('ok', false, 'reason', 'You already have this one.');
  end if;
  bal := public.zchat_coins_move(me, -it.price, 'shop', it.label, null);
  if bal is null then
    return jsonb_build_object('ok', false, 'reason', 'You do not have enough coins.');
  end if;
  perform public.zchat_grant_item(me, p_kind, p_key, null, true);
  return jsonb_build_object('ok', true, 'coins', bal, 'expires_at', null);
end $$;

create or replace function public.zchat_gift_item(p_to uuid, p_kind text, p_key text, p_note text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  why text := public.zchat_gift_target_reason(p_to);
  kinds text[];
  k text;
  it public.shop_items%rowtype;
  v_price integer := 0;
  v_name text;
  v_label text;
  got text[] := array[]::text[];
  bal integer;
  v_note text := nullif(btrim(left(coalesce(p_note, ''), 80)), '');
begin
  if why is not null then
    return jsonb_build_object('ok', false, 'reason', why);
  end if;
  if exists (select 1 from public.profiles p where p.id = me and (coalesce(p.banned, false) or coalesce(p.is_deleted, false) or coalesce(p.is_bot, false))) then
    return jsonb_build_object('ok', false, 'reason', 'Your account cannot send gifts right now.');
  end if;
  if p_kind = 'set' then
    kinds := array['frame', 'nameplate', 'effect'];
  elsif p_kind in ('frame', 'nameplate', 'effect', 'charm', 'bubble', 'namestyle', 'theme', 'reaction', 'wallpaper', 'stickerpack', 'soundpack', 'typing') then
    kinds := array[p_kind];
  else
    return jsonb_build_object('ok', false, 'reason', 'That item is not in the Shop.');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('zchat gift ' || p_to::text || ' ' || coalesce(p_key, ''), 0));
  perform public.zchat_wallet_lock(me);
  if (select count(*) from public.coin_ledger l where l.user_id = me and l.reason in ('gift_out', 'gift_item') and l.created_at > now() - interval '1 hour') >= 10 then
    return jsonb_build_object('ok', false, 'reason', 'You sent a lot of gifts in the last hour. Try again a little later.');
  end if;
  foreach k in array kinds loop
    select * into it from public.shop_items where kind = k and key = p_key and active;
    if not found then
      return jsonb_build_object('ok', false, 'reason', 'That item is not in the Shop.');
    end if;
    v_name := regexp_replace(it.label, ' (frame|nameplate|effect)$', '');
    if not public.zchat_owns_forever(p_to, k, p_key) then
      v_price := v_price + it.price;
      got := got || k;
      v_label := it.label;
    end if;
  end loop;
  if coalesce(array_length(got, 1), 0) = 0 then
    return jsonb_build_object('ok', false, 'reason', case when p_kind = 'set' then 'They already have this set.' else 'They already have this one.' end);
  end if;
  if array_length(got, 1) > 1 then
    v_label := v_name || case when array_length(got, 1) = 3 then ' set' else ' ' || array_to_string(got, ' and ') end;
  end if;
  bal := public.zchat_coins_move(me, -v_price, 'gift_item', v_label, p_to);
  if bal is null then
    return jsonb_build_object('ok', false, 'reason', 'You do not have enough coins.');
  end if;
  foreach k in array got loop
    perform public.zchat_grant_item(p_to, k, p_key, null, false);
  end loop;
  perform public.zchat_notify(p_to, me, 'gift', null, 'the ' || v_label || coalesce(', "' || v_note || '"', ''),
    jsonb_build_object('kind', case when array_length(got, 1) > 1 then 'set' else got[1] end, 'key', p_key, 'got', to_jsonb(got)));
  return jsonb_build_object('ok', true, 'coins', bal, 'got', to_jsonb(got));
end $$;

create or replace function public.zchat_shop_popular(p_limit integer default 12)
returns table(kind text, item_key text, owners integer)
language sql
stable
security definer
set search_path = public
as $$
  with base as (
    select case when r.kind in ('frame', 'nameplate', 'effect') then 'set' else r.kind end as k, r.reward_key as key, r.user_id
    from public.user_rewards r
    where r.expires_at is null and r.kind in ('frame', 'nameplate', 'effect', 'bubble', 'charm', 'namestyle', 'theme', 'reaction', 'stickerpack', 'soundpack', 'typing')
  )
  select b.k, b.key, count(distinct b.user_id)::integer
  from base b
  where exists (select 1 from public.shop_items s where s.key = b.key and s.active and (s.kind = b.k or (b.k = 'set' and s.kind = 'frame')))
  group by b.k, b.key
  order by 3 desc, 2
  limit greatest(1, least(coalesce(p_limit, 12), 30))
$$;

create or replace function public.zchat_decor_family(p_key text)
returns text[]
language sql
immutable
set search_path = public
as $$
  with v(k, b) as (values
    ('koi_pond_night', 'koi_pond'),
    ('sakura_shrine_night', 'sakura_shrine'),
    ('snow_globe_night', 'snow_globe'),
    ('hot_air_balloon_dusk', 'hot_air_balloon'),
    ('bubble_tea_matcha', 'bubble_tea'),
    ('ocean_reef_night', 'ocean_reef'),
    ('candy_land_mint', 'candy_land'),
    ('robot_buddy_gold', 'robot_buddy')
  ), base as (
    select coalesce((select v.b from v where v.k = p_key), p_key) as b
  )
  select array[base.b] || coalesce((select array_agg(v.k order by v.k) from v where v.b = base.b), array[]::text[])
  from base
$$;

create or replace function public.zchat_owns_item(p_user uuid, p_kind text, p_key text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select p_user is not null and exists (
    select 1 from public.user_rewards r
    where r.user_id = p_user and r.kind = p_kind
      and (r.reward_key = p_key or (p_kind = 'effect' and r.reward_key = any (public.zchat_decor_family(p_key))))
      and (r.expires_at is null or r.expires_at > now())
  )
$$;

create or replace function public.zchat_owns_forever(p_user uuid, p_kind text, p_key text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select p_user is not null and exists (
    select 1 from public.user_rewards r
    where r.user_id = p_user and r.kind = p_kind
      and (r.reward_key = p_key or (p_kind = 'effect' and r.reward_key = any (public.zchat_decor_family(p_key))))
      and r.expires_at is null
  )
$$;

revoke execute on function public.zchat_decor_family(text) from public, anon;
grant execute on function public.zchat_decor_family(text) to authenticated, service_role;

create or replace function public.zchat_match_mate(p_key text)
returns text
language sql
immutable
set search_path = public
as $$
  select case p_key
    when 'sun_half' then 'moon_half'
    when 'moon_half' then 'sun_half'
    when 'lock_half' then 'key_half'
    when 'key_half' then 'lock_half'
    when 'koi_gold' then 'koi_ink'
    when 'koi_ink' then 'koi_gold'
    else null
  end
$$;

create or replace function public.zchat_match_worn(p_frame text, p_plate text)
returns text
language sql
immutable
set search_path = public
as $$
  select case
    when public.zchat_match_mate(p_frame) is not null then p_frame
    when public.zchat_match_mate(p_plate) is not null then p_plate
    else null
  end
$$;

create or replace function public.zchat_match_with(p_user uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  pr record;
  half text;
  mate text;
  y record;
begin
  if me is null or p_user is null then
    return null;
  end if;
  select p.id, p.avatar_frame, p.nameplate, coalesce(p.is_deleted, false) as gone, coalesce(p.banned, false) as banned into pr from public.profiles p where p.id = p_user;
  if not found or pr.gone or pr.banned then
    return null;
  end if;
  half := public.zchat_match_worn(pr.avatar_frame, pr.nameplate);
  if half is null or not public.zchat_owner_visible(p_user, 'profile') then
    return null;
  end if;
  if not (public.zchat_owns_item(p_user, 'frame', half) or public.zchat_owns_item(p_user, 'nameplate', half)) then
    return null;
  end if;
  mate := public.zchat_match_mate(half);
  select q.id, q.name, q.username, q.avatar, q.avatar_frame, q.nameplate, q.verified, q.custom_badge into y
  from public.profiles q
  join public.follows a on a.follower_id = p_user and a.following_id = q.id and coalesce(a.status, 'accepted') = 'accepted'
  join public.follows b on b.follower_id = q.id and b.following_id = p_user and coalesce(b.status, 'accepted') = 'accepted'
  where (q.avatar_frame = mate or q.nameplate = mate)
    and q.id <> p_user
    and not coalesce(q.is_deleted, false) and not coalesce(q.banned, false)
    and (public.zchat_owns_item(q.id, 'frame', mate) or public.zchat_owns_item(q.id, 'nameplate', mate))
    and public.zchat_owner_visible(q.id, 'profile')
  order by (q.id = me) desc, greatest(a.created_at, b.created_at) desc nulls last, q.id
  limit 1;
  if not found then
    return null;
  end if;
  return jsonb_build_object('key', half, 'mate', mate, 'id', y.id, 'name', y.name, 'username', y.username, 'avatar', y.avatar,
    'avatar_frame', y.avatar_frame, 'nameplate', y.nameplate, 'verified', y.verified, 'custom_badge', y.custom_badge);
end $$;

create or replace function public.zchat_match_pairs(p_ids uuid[])
returns table(a uuid, b uuid, key_a text, key_b text)
language sql
stable
security definer
set search_path = public
as $$
  with ids as (
    select distinct x as id from unnest((coalesce(p_ids, array[]::uuid[]))[1:300]) as x
  ), worn as (
    select p.id, public.zchat_match_worn(p.avatar_frame, p.nameplate) as half
    from public.profiles p join ids on ids.id = p.id
    where not coalesce(p.is_deleted, false) and not coalesce(p.banned, false)
  ), ok as (
    select w.id, w.half from worn w
    where w.half is not null
      and (public.zchat_owns_item(w.id, 'frame', w.half) or public.zchat_owns_item(w.id, 'nameplate', w.half))
      and public.zchat_owner_visible(w.id, 'profile')
  )
  select x.id, y.id, x.half, y.half
  from ok x
  join ok y on y.half = public.zchat_match_mate(x.half) and x.id < y.id
  where auth.uid() is not null
    and public.zchat_follows(x.id, y.id) and public.zchat_follows(y.id, x.id)
  limit 150
$$;

create or replace function public.zchat_buy_match_pair(p_key text, p_to uuid, p_note text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  mate text := public.zchat_match_mate(p_key);
  g jsonb;
  b jsonb;
  bal integer;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if mate is null then
    return jsonb_build_object('ok', false, 'reason', 'That is not a matching set.');
  end if;
  if p_to is null or p_to = me then
    return jsonb_build_object('ok', false, 'reason', 'Pick a friend for the other half.');
  end if;
  if not (public.zchat_follows(me, p_to) and public.zchat_follows(p_to, me)) then
    return jsonb_build_object('ok', false, 'reason', 'Matching halves are for friends who follow each other.');
  end if;
  begin
    g := public.zchat_gift_item(p_to, 'set', mate, p_note);
    if not coalesce((g ->> 'ok')::boolean, false) then
      raise exception using errcode = 'P0001', message = coalesce(g ->> 'reason', 'That gift could not be sent.');
    end if;
    bal := (g ->> 'coins')::integer;
    if not (public.zchat_owns_forever(me, 'frame', p_key) and public.zchat_owns_forever(me, 'nameplate', p_key) and public.zchat_owns_forever(me, 'effect', p_key)) then
      b := public.zchat_buy_set(p_key);
      if not coalesce((b ->> 'ok')::boolean, false) then
        raise exception using errcode = 'P0001', message = coalesce(b ->> 'reason', 'That did not work. Try again.');
      end if;
      bal := (b ->> 'coins')::integer;
    end if;
  exception when sqlstate 'P0001' then
    return jsonb_build_object('ok', false, 'reason', sqlerrm);
  end;
  return jsonb_build_object('ok', true, 'coins', bal, 'gift', g -> 'got', 'mine', coalesce(b -> 'got', '[]'::jsonb));
end $$;

revoke execute on function public.zchat_match_mate(text) from public, anon;
revoke execute on function public.zchat_match_worn(text, text) from public, anon;
revoke execute on function public.zchat_match_with(uuid) from public, anon;
revoke execute on function public.zchat_match_pairs(uuid[]) from public, anon;
revoke execute on function public.zchat_buy_match_pair(text, uuid, text) from public, anon;
grant execute on function public.zchat_match_mate(text) to authenticated, service_role;
grant execute on function public.zchat_match_worn(text, text) to authenticated, service_role;
grant execute on function public.zchat_match_with(uuid) to authenticated, service_role;
grant execute on function public.zchat_match_pairs(uuid[]) to authenticated, service_role;
grant execute on function public.zchat_buy_match_pair(text, uuid, text) to authenticated, service_role;
commit;

begin;
create or replace function public.zchat_own_style_ok(p text)
returns boolean
language sql
immutable
set search_path = public
as $$
  select p is not null and length(p) <= 40 and p ~ '^own:[0-9a-f]{6}(\.[0-9a-f]{6}){1,2}\.(still|shimmer|wave|pulse)\.[6-9]$'
$$;

create or replace function public.zchat_namestyle_guard()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if current_user not in ('authenticated', 'anon') or pg_trigger_depth() > 1 or public.zchat_is_admin() then
    return new;
  end if;
  if coalesce(new.name_style, '') = '' then
    new.name_style := null;
  elsif (tg_op = 'INSERT' or new.name_style is distinct from old.name_style) and left(new.name_style, 4) = 'own:' then
    if not public.zchat_own_style_ok(new.name_style) then
      raise exception 'That name style does not look right' using errcode = '22023';
    end if;
    if not public.zchat_owns_item(new.id, 'namestyle', 'own') then
      raise exception 'Get your own name style in the Shop first' using errcode = '42501';
    end if;
  elsif (tg_op = 'INSERT' or new.name_style is distinct from old.name_style)
    and (not (new.name_style = any (public.zchat_namestyle_keys())) or not public.zchat_owns_item(new.id, 'namestyle', new.name_style)) then
    raise exception 'Get this name style in the Shop first' using errcode = '42501';
  end if;
  if coalesce(new.profile_theme, '') = '' then
    new.profile_theme := null;
  elsif (tg_op = 'INSERT' or new.profile_theme is distinct from old.profile_theme)
    and (not (new.profile_theme = any (public.zchat_theme_keys())) or not public.zchat_owns_item(new.id, 'theme', new.profile_theme)) then
    raise exception 'Get this theme in the Shop first' using errcode = '42501';
  end if;
  return new;
end $$;

revoke execute on function public.zchat_own_style_ok(text) from public, anon;
grant execute on function public.zchat_own_style_ok(text) to authenticated, service_role;

create or replace function public.zchat_sticker_pack_of(p text)
returns text
language sql
immutable
set search_path = public
as $$
  select (regexp_match(coalesce(p, ''), '(?:^|/)ps-([a-z]+)-[a-z0-9]+\.webp'))[1]
$$;

create or replace function public.zchat_premium_sticker_guard()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  pack text;
  who uuid;
  body text;
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;
  if tg_table_name = 'messages' then
    if coalesce(new.type, '') <> 'sticker' then
      return new;
    end if;
    body := new.content;
    who := new.sender_id;
  else
    body := new.content;
    who := new.user_id;
    if left(coalesce(body, ''), 8) <> 'sticker:' then
      return new;
    end if;
  end if;
  if tg_op = 'UPDATE' and body is not distinct from old.content then
    return new;
  end if;
  pack := public.zchat_sticker_pack_of(body);
  if pack is null then
    return new;
  end if;
  if not exists (select 1 from public.shop_items s where s.kind = 'stickerpack' and s.key = pack) then
    raise exception 'That sticker is not in ZChat' using errcode = '22023';
  end if;
  if who is distinct from auth.uid() or not public.zchat_owns_item(who, 'stickerpack', pack) then
    raise exception 'Get this sticker pack in the Shop to send its stickers' using errcode = '42501';
  end if;
  return new;
end $$;

drop trigger if exists zchat_premium_sticker_guard on public.messages;
create trigger zchat_premium_sticker_guard before insert or update of content on public.messages
  for each row execute function public.zchat_premium_sticker_guard();

drop trigger if exists zchat_premium_sticker_guard on public.post_comments;
create trigger zchat_premium_sticker_guard before insert or update of content on public.post_comments
  for each row execute function public.zchat_premium_sticker_guard();

revoke execute on function public.zchat_sticker_pack_of(text) from public, anon;
grant execute on function public.zchat_sticker_pack_of(text) to authenticated, service_role;

do $$
declare
  v text[];
  w text;
  mine text[] := array['creator_out', 'creator_in', 'creator_back'];
  changed boolean := false;
begin
  select array_agg(distinct m[1] order by m[1]) into v
  from pg_constraint c, regexp_matches(pg_get_constraintdef(c.oid), '([a-z_]+)', 'g') as m
  where c.conname = 'coin_ledger_reason_check' and c.conrelid = 'public.coin_ledger'::regclass and m[1] not in ('reason', 'text', 'any', 'array');
  if v is null then
    v := array['daily', 'invite', 'invited', 'gift_in', 'gift_out', 'shop', 'gift_item', 'admin', 'achievement', 'purchase', 'refund', 'drop', 'deal', 'milestone', 'trade', 'code', 'tip_in', 'tip_out', 'live_in', 'live_out'];
  end if;
  foreach w in array mine loop
    if not (w = any (v)) then
      v := v || w;
      changed := true;
    end if;
  end loop;
  if changed then
    alter table public.coin_ledger drop constraint if exists coin_ledger_reason_check;
    execute format('alter table public.coin_ledger add constraint coin_ledger_reason_check check (reason = any (%L::text[]))', v);
  end if;
end $$;

create or replace function public.zchat_cr_share_pct()
returns integer
language sql
immutable
as $$ select 20 $$;

create or replace function public.zchat_cr_cut(p_price integer)
returns integer
language sql
immutable
as $$ select greatest(0, p_price - ceil(p_price * public.zchat_cr_share_pct() / 100.0)::integer) $$;

create or replace function public.zchat_cr_min_followers()
returns integer
language sql
immutable
as $$ select 50 $$;

create or replace function public.zchat_cr_prices(p_kind text)
returns integer[]
language sql
immutable
as $$
  select case p_kind
    when 'group' then array[50, 100, 200, 300, 500, 1000, 2000]
    when 'pack' then array[50, 100, 150, 200, 300, 500]
    when 'member' then array[50, 100, 200, 300, 500, 1000]
    when 'message' then array[20, 50, 100, 200, 500]
    when 'shout' then array[200, 300, 500, 1000, 2000, 5000]
    else array[]::integer[]
  end
$$;

create or replace function public.zchat_cr_followers(p_user uuid)
returns integer
language sql
stable
security definer
set search_path = public
as $$
  select count(*)::integer from public.follows f where f.following_id = p_user and coalesce(f.status, 'accepted') = 'accepted'
$$;

create or replace function public.zchat_cr_active(p_user uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select p_user is not null and exists (
    select 1 from public.profiles p
    where p.id = p_user and not coalesce(p.banned, false) and not coalesce(p.is_deleted, false) and not coalesce(p.is_bot, false)
  )
$$;

create or replace function public.zchat_cr_can_create(p_user uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.zchat_cr_active(p_user) and (
    public.zchat_is_admin_id(p_user)
    or exists (select 1 from public.profiles p where p.id = p_user and coalesce(p.verified, '') <> '')
    or public.zchat_cr_followers(p_user) >= public.zchat_cr_min_followers()
  )
$$;

create or replace function public.zchat_cr_new_account(p_user uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(public.zchat_account_created(p_user) > now() - interval '1 day', true)
    and not exists (select 1 from public.coin_orders o where o.user_id = p_user and o.status = 'paid')
$$;

create table if not exists public.creator_settings (
  user_id uuid primary key references auth.users(id) on delete cascade,
  member_price integer,
  member_perks text,
  msg_price integer,
  shout_price integer,
  shout_note text,
  members_group uuid references public.groups(id) on delete set null,
  updated_at timestamptz not null default now(),
  constraint creator_settings_perks_len check (member_perks is null or char_length(member_perks) <= 300),
  constraint creator_settings_note_len check (shout_note is null or char_length(shout_note) <= 200)
);
alter table public.creator_settings enable row level security;
drop policy if exists "zchat creator settings read" on public.creator_settings;
create policy "zchat creator settings read" on public.creator_settings for select to authenticated using (true);
revoke insert, update, delete on public.creator_settings from anon, authenticated;
create unique index if not exists zchat_creator_settings_group on public.creator_settings (members_group) where members_group is not null;

create table if not exists public.creator_dm_open (
  creator_id uuid not null references auth.users(id) on delete cascade,
  fan_id uuid not null references auth.users(id) on delete cascade,
  opened_at timestamptz not null default now(),
  primary key (creator_id, fan_id)
);
alter table public.creator_dm_open enable row level security;
drop policy if exists "zchat creator dm open read" on public.creator_dm_open;
create policy "zchat creator dm open read" on public.creator_dm_open for select to authenticated using (creator_id = (select auth.uid()) or fan_id = (select auth.uid()));
revoke insert, update, delete on public.creator_dm_open from anon, authenticated;

create or replace function public.zchat_cr_note(p_user uuid, p_actor uuid, p_ev text, p_text text, p_meta jsonb default null)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.zchat_notify(p_user, p_actor, 'creator', null, p_text, jsonb_build_object('ev', p_ev) || coalesce(p_meta, '{}'::jsonb));
exception when others then
  null;
end $$;

create or replace function public.zchat_cr_coins(p_n integer)
returns text
language sql
immutable
as $$ select to_char(p_n, 'FM999,999,990') || case when p_n = 1 then ' coin' else ' coins' end $$;

create or replace function public.zchat_cr_uname(p_user uuid)
returns text
language sql
stable
security definer
set search_path = public
as $$ select '@' || coalesce((select p.username from public.profiles p where p.id = p_user), 'someone') $$;

create or replace function public.zchat_cr_lock2(p_a uuid, p_b uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.wallets (user_id) select x from unnest(array[p_a, p_b]) x where x is not null on conflict (user_id) do nothing;
  perform 1 from public.wallets w where w.user_id in (p_a, p_b) order by w.user_id for update;
end $$;

create or replace function public.zchat_cr_conv_touch(p_from uuid, p_to uuid, p_text text)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.conversations c set last_message = left(p_text, 200), last_message_at = now(), last_sender_id = p_from
    where (c.user_a = p_from and c.user_b = p_to) or (c.user_a = p_to and c.user_b = p_from);
  if not found then
    insert into public.conversations (user_a, user_b, last_message, last_message_at, last_sender_id)
    values (least(p_from, p_to), greatest(p_from, p_to), left(p_text, 200), now(), p_from)
    on conflict (user_a, user_b) do update set last_message = excluded.last_message, last_message_at = excluded.last_message_at, last_sender_id = excluded.last_sender_id;
  end if;
exception when others then
  null;
end $$;

create or replace function public.zchat_cr_settings_save(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  cur public.creator_settings;
  v_member integer;
  v_msg integer;
  v_shout integer;
  v_perks text;
  v_note text;
  turning_on boolean := false;
  k text;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if p is null or jsonb_typeof(p) <> 'object' then
    return jsonb_build_object('ok', false, 'reason', 'Nothing to save.');
  end if;
  insert into public.creator_settings (user_id) values (me) on conflict (user_id) do nothing;
  select * into cur from public.creator_settings where user_id = me for update;
  v_member := cur.member_price;
  v_msg := cur.msg_price;
  v_shout := cur.shout_price;
  v_perks := cur.member_perks;
  v_note := cur.shout_note;
  foreach k in array array['member_price', 'msg_price', 'shout_price'] loop
    if p ? k and jsonb_typeof(p -> k) not in ('null', 'number') then
      return jsonb_build_object('ok', false, 'reason', 'Pick a price from the list.');
    end if;
  end loop;
  if p ? 'member_price' then
    v_member := (p ->> 'member_price')::integer;
    if v_member is not null and not (v_member = any (public.zchat_cr_prices('member'))) then
      return jsonb_build_object('ok', false, 'reason', 'Pick a price from the list.');
    end if;
    if v_member is not null and cur.member_price is null then turning_on := true; end if;
  end if;
  if p ? 'msg_price' then
    v_msg := (p ->> 'msg_price')::integer;
    if v_msg is not null and not (v_msg = any (public.zchat_cr_prices('message'))) then
      return jsonb_build_object('ok', false, 'reason', 'Pick a price from the list.');
    end if;
    if v_msg is not null and cur.msg_price is null then turning_on := true; end if;
  end if;
  if p ? 'shout_price' then
    v_shout := (p ->> 'shout_price')::integer;
    if v_shout is not null and not (v_shout = any (public.zchat_cr_prices('shout'))) then
      return jsonb_build_object('ok', false, 'reason', 'Pick a price from the list.');
    end if;
    if v_shout is not null and cur.shout_price is null then turning_on := true; end if;
  end if;
  if p ? 'member_perks' then
    v_perks := nullif(btrim(left(regexp_replace(coalesce(p ->> 'member_perks', ''), '[[:cntrl:]]+', ' ', 'g'), 300)), '');
  end if;
  if p ? 'shout_note' then
    v_note := nullif(btrim(left(regexp_replace(coalesce(p ->> 'shout_note', ''), '[[:cntrl:]]+', ' ', 'g'), 200)), '');
  end if;
  if turning_on and not public.zchat_cr_can_create(me) then
    return jsonb_build_object('ok', false, 'reason', 'Creator tools open up once ' || public.zchat_cr_min_followers() || ' people follow you.', 'need', public.zchat_cr_min_followers(), 'followers', public.zchat_cr_followers(me));
  end if;
  if v_msg is not null and cur.msg_price is null then
    insert into public.creator_dm_open (creator_id, fan_id)
      select me, a.other_id from public.chat_accepts a where a.user_id = me and a.other_id <> me
      on conflict do nothing;
  end if;
  update public.creator_settings set member_price = v_member, msg_price = v_msg, shout_price = v_shout, member_perks = v_perks, shout_note = v_note, updated_at = now()
    where user_id = me returning * into cur;
  return jsonb_build_object('ok', true, 'settings', to_jsonb(cur));
end $$;

create or replace function public.zchat_cr_me()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  s jsonb;
begin
  if me is null then
    return null;
  end if;
  select to_jsonb(x) into s from public.creator_settings x where x.user_id = me;
  return jsonb_build_object(
    'settings', coalesce(s, jsonb_build_object('user_id', me)),
    'eligible', public.zchat_cr_can_create(me),
    'followers', public.zchat_cr_followers(me),
    'need', public.zchat_cr_min_followers(),
    'share', public.zchat_cr_share_pct(),
    'month', coalesce((select sum(l.delta) from public.coin_ledger l where l.user_id = me and l.reason = 'creator_in' and l.created_at > date_trunc('month', now())), 0),
    'total', coalesce((select sum(l.delta) from public.coin_ledger l where l.user_id = me and l.reason = 'creator_in'), 0)
  );
end $$;

revoke execute on function public.zchat_cr_note(uuid, uuid, text, text, jsonb) from public, anon, authenticated;
revoke execute on function public.zchat_cr_lock2(uuid, uuid) from public, anon, authenticated;
revoke execute on function public.zchat_cr_conv_touch(uuid, uuid, text) from public, anon, authenticated;
revoke execute on function public.zchat_cr_new_account(uuid) from public, anon;
grant execute on function public.zchat_cr_settings_save(jsonb) to authenticated;
grant execute on function public.zchat_cr_me() to authenticated;
grant execute on function public.zchat_cr_can_create(uuid) to authenticated;
grant execute on function public.zchat_cr_prices(text) to authenticated;
revoke execute on function public.zchat_cr_settings_save(jsonb) from public, anon;
revoke execute on function public.zchat_cr_me() from public, anon;

select public.zchat_apply_session_gate();

alter table public.groups add column if not exists entry_price integer;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'zchat_groups_entry_price_ok') then
    alter table public.groups add constraint zchat_groups_entry_price_ok check (entry_price is null or entry_price > 0) not valid;
  end if;
end $$;

create table if not exists public.group_entry_payments (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null,
  group_name text,
  user_id uuid not null references auth.users(id) on delete cascade,
  owner_id uuid not null,
  price integer not null check (price > 0),
  cut integer not null check (cut >= 0),
  status text not null default 'held' check (status in ('held', 'paid', 'refunded')),
  created_at timestamptz not null default now(),
  settled_at timestamptz
);
create index if not exists zchat_entry_pay_group on public.group_entry_payments (group_id, user_id);
create index if not exists zchat_entry_pay_held on public.group_entry_payments (created_at) where status = 'held';
alter table public.group_entry_payments enable row level security;
drop policy if exists "zchat entry payments read" on public.group_entry_payments;
create policy "zchat entry payments read" on public.group_entry_payments for select to authenticated
  using (user_id = (select auth.uid()) or owner_id = (select auth.uid())
    or exists (select 1 from public.groups g where g.id = group_entry_payments.group_id and g.created_by = (select auth.uid())));
revoke insert, update, delete on public.group_entry_payments from anon, authenticated;

create or replace function public.zchat_cr_groups_guard()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if current_user not in ('authenticated', 'anon') or coalesce(current_setting('zchat.cr_ok', true), '') = '1' then
    return new;
  end if;
  if tg_op = 'INSERT' then
    new.entry_price := null;
    return new;
  end if;
  if new.entry_price is distinct from old.entry_price then
    raise exception 'Only the group owner can change the entry price' using errcode = '42501';
  end if;
  return new;
end $$;
drop trigger if exists zchat_cr_groups_guard on public.groups;
create trigger zchat_cr_groups_guard before insert or update of entry_price on public.groups
  for each row execute function public.zchat_cr_groups_guard();

create or replace function public.zchat_cr_gate_check(p_group uuid, p_user uuid, p_role text)
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  g record;
  owner_of uuid;
begin
  select s.user_id into owner_of from public.creator_settings s where s.members_group = p_group;
  if owner_of is not null then
    if p_user = owner_of or exists (
      select 1 from public.creator_members m where m.creator_id = owner_of and m.member_id = p_user and m.status = 'active'
    ) then
      return 'ok';
    end if;
    return 'This group is only for members';
  end if;
  select x.entry_price, x.created_by into g from public.groups x where x.id = p_group;
  if g.entry_price is null or p_user = g.created_by then
    return 'ok';
  end if;
  if coalesce(current_setting('zchat.cr_join', true), '') = p_group::text || ':' || p_user::text then
    return 'ok';
  end if;
  if exists (select 1 from public.group_join_requests r where r.group_id = p_group and r.user_id = p_user and r.status = 'approved' and r.reviewed_at = now()) then
    return 'skip';
  end if;
  if me is not null and me <> p_user and me = g.created_by then
    return 'ok';
  end if;
  if me is null and p_role not in ('authenticated', 'anon') then
    return 'ok';
  end if;
  return 'This group has an entry price. Open the invite link to join';
end $$;
grant execute on function public.zchat_cr_gate_check(uuid, uuid, text) to authenticated, service_role;

create or replace function public.zchat_cr_entry_gate()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v text;
begin
  if coalesce(current_setting('zchat.cr_ok', true), '') = '1' then
    return new;
  end if;
  v := public.zchat_cr_gate_check(new.group_id, new.user_id, current_user::text);
  if v = 'ok' then
    return new;
  end if;
  if v = 'skip' then
    return null;
  end if;
  raise exception '%', v using errcode = '42501';
end $$;
drop trigger if exists zchat_cr_entry_gate on public.group_members;
create trigger zchat_cr_entry_gate before insert on public.group_members
  for each row execute function public.zchat_cr_entry_gate();

create or replace function public.zchat_cr_entry_left()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  p public.group_entry_payments;
begin
  begin
    if me is not null and me = old.user_id then
      return null;
    end if;
    select * into p from public.group_entry_payments x
      where x.group_id = old.group_id and x.user_id = old.user_id and x.status = 'held' and x.created_at > now() - interval '24 hours'
      order by x.created_at desc limit 1 for update;
    if not found or not exists (select 1 from auth.users u where u.id = old.user_id) then
      return null;
    end if;
    perform public.zchat_wallet_lock(old.user_id);
    if public.zchat_coins_move(old.user_id, p.price, 'creator_back', 'Entry refund: ' || left(coalesce(p.group_name, 'a group'), 80), p.owner_id) is null then
      return null;
    end if;
    update public.group_entry_payments set status = 'refunded', settled_at = now() where id = p.id;
    perform public.zchat_cr_note(old.user_id, null, 'entry_refund',
      'You were removed from ' || coalesce(p.group_name, 'a group') || ' within a day, so your ' || public.zchat_cr_coins(p.price) || ' are back.',
      jsonb_build_object('group_id', p.group_id, 'coins', p.price));
  exception when others then
    raise notice 'zchat entry refund skipped: %', sqlerrm;
  end;
  return null;
end $$;
drop trigger if exists zchat_cr_entry_left on public.group_members;
create trigger zchat_cr_entry_left after delete on public.group_members
  for each row execute function public.zchat_cr_entry_left();

create or replace function public.zchat_cr_group_price(p_group uuid, p_price integer)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  g record;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  select x.id, x.created_by into g from public.groups x where x.id = p_group for update;
  if not found or g.created_by is distinct from me then
    return jsonb_build_object('ok', false, 'reason', 'Only the group owner can set an entry price.');
  end if;
  if exists (select 1 from public.creator_settings s where s.members_group = p_group) then
    return jsonb_build_object('ok', false, 'reason', 'Your members group is part of your membership.');
  end if;
  if p_price is not null then
    if not (p_price = any (public.zchat_cr_prices('group'))) then
      return jsonb_build_object('ok', false, 'reason', 'Pick a price from the list.');
    end if;
    if not public.zchat_cr_active(me) then
      return jsonb_build_object('ok', false, 'reason', 'Your account cannot do this right now.');
    end if;
    if coalesce(public.zchat_account_created(me) > now() - interval '7 days', true) then
      return jsonb_build_object('ok', false, 'reason', 'Entry prices open up after your first week on ZChat.');
    end if;
  end if;
  perform set_config('zchat.cr_ok', '1', true);
  update public.groups set entry_price = p_price where id = p_group;
  perform set_config('zchat.cr_ok', '', true);
  return jsonb_build_object('ok', true, 'price', p_price);
end $$;

create or replace function public.zchat_cr_group_join(p_code text, p_expect integer)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  inv jsonb;
  gid uuid;
  g record;
  v_bal integer;
  v_cut integer;
  r jsonb;
  n integer;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  inv := public.zchat_group_invite(p_code);
  if inv is null or coalesce((inv ->> 'expired')::boolean, false) or inv -> 'group' is null then
    return jsonb_build_object('ok', false, 'reason', 'This invite link isn''t valid anymore');
  end if;
  gid := (inv -> 'group' ->> 'id')::uuid;
  select x.id, x.name, x.created_by, x.entry_price, x.join_approval into g from public.groups x where x.id = gid;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'This invite link isn''t valid anymore');
  end if;
  if g.entry_price is null or g.created_by = me or exists (select 1 from public.group_members gm where gm.group_id = gid and gm.user_id = me) then
    return public.zchat_join_group(p_code);
  end if;
  if p_expect is distinct from g.entry_price then
    return jsonb_build_object('ok', false, 'price', g.entry_price, 'reason', 'The entry price is now ' || public.zchat_cr_coins(g.entry_price) || '.');
  end if;
  if not public.zchat_cr_active(me) then
    return jsonb_build_object('ok', false, 'reason', 'You cannot join groups right now.');
  end if;
  if public.zchat_blocked_pair(me, g.created_by) then
    return jsonb_build_object('ok', false, 'reason', 'You cannot join this group.');
  end if;
  if not public.zchat_cr_active(g.created_by) then
    return jsonb_build_object('ok', false, 'reason', 'This group is not taking new members right now.');
  end if;
  if coalesce(g.join_approval, false) and not exists (
    select 1 from public.group_join_requests jr where jr.group_id = gid and jr.user_id = me and jr.status = 'approved'
  ) then
    return jsonb_build_object('ok', false, 'approval', true, 'group', inv -> 'group');
  end if;
  if public.zchat_cr_new_account(me) then
    return jsonb_build_object('ok', false, 'reason', 'New accounts can pay to join groups after their first day.');
  end if;
  perform public.zchat_cr_lock2(me, g.created_by);
  select count(*) into n from public.group_entry_payments x where x.user_id = me and x.created_at > now() - interval '1 hour';
  if n >= 10 then
    return jsonb_build_object('ok', false, 'reason', 'You joined a lot of groups in the last hour. Try again a little later.');
  end if;
  v_cut := public.zchat_cr_cut(g.entry_price);
  begin
    v_bal := public.zchat_coins_move(me, -g.entry_price, 'creator_out', 'Entry to ' || left(coalesce(g.name, 'a group'), 80), g.created_by);
    if v_bal is null then
      return jsonb_build_object('ok', false, 'reason', 'You do not have enough coins.', 'price', g.entry_price);
    end if;
    insert into public.group_entry_payments (group_id, group_name, user_id, owner_id, price, cut)
      values (gid, left(coalesce(g.name, 'a group'), 80), me, g.created_by, g.entry_price, v_cut);
    perform set_config('zchat.cr_join', gid::text || ':' || me::text, true);
    r := public.zchat_join_group(p_code);
    perform set_config('zchat.cr_join', '', true);
    if not coalesce((r ->> 'ok')::boolean, false) then
      raise exception '%', coalesce(r ->> 'reason', 'You could not join this group.') using errcode = 'P0001';
    end if;
  exception when others then
    return jsonb_build_object('ok', false, 'reason', case when sqlstate = 'P0001' then sqlerrm else 'You could not join this group. Try again.' end);
  end;
  perform public.zchat_cr_note(g.created_by, me, 'entry_paid',
    'paid ' || public.zchat_cr_coins(g.entry_price) || ' to join ' || left(coalesce(g.name, 'your group'), 60) || '. You get ' || public.zchat_cr_coins(v_cut) || ' after a day.',
    jsonb_build_object('group_id', gid, 'coins', g.entry_price));
  return r || jsonb_build_object('coins', v_bal, 'paid', g.entry_price);
end $$;

revoke execute on function public.zchat_cr_group_price(uuid, integer) from public, anon;
revoke execute on function public.zchat_cr_group_join(text, integer) from public, anon;
grant execute on function public.zchat_cr_group_price(uuid, integer) to authenticated;
grant execute on function public.zchat_cr_group_join(text, integer) to authenticated;

select public.zchat_apply_session_gate();
commit;

begin;
create table if not exists public.creator_packs (
  id uuid primary key default gen_random_uuid(),
  pack_id uuid unique references public.sticker_packs(id) on delete set null,
  owner_id uuid references auth.users(id) on delete set null,
  name text not null check (char_length(name) between 1 and 40),
  preview jsonb not null default '[]'::jsonb,
  count integer not null default 0,
  price integer not null check (price > 0),
  status text not null default 'review' check (status in ('review', 'live', 'rejected', 'off')),
  note text,
  sales integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  reviewed_at timestamptz,
  reviewed_by uuid
);
create index if not exists zchat_creator_packs_owner on public.creator_packs (owner_id, created_at desc);
create index if not exists zchat_creator_packs_live on public.creator_packs (sales desc, created_at desc) where status = 'live';

create table if not exists public.creator_pack_items (
  pack_id uuid primary key references public.creator_packs(id) on delete cascade,
  stickers jsonb not null default '[]'::jsonb,
  updated_at timestamptz not null default now()
);

create table if not exists public.creator_pack_reviews (
  pack_id uuid primary key references public.creator_packs(id) on delete cascade,
  stickers jsonb not null,
  flags jsonb not null default '[]'::jsonb,
  submitted_at timestamptz not null default now()
);
alter table public.creator_pack_reviews add column if not exists name text;

create table if not exists public.creator_pack_buyers (
  pack_id uuid not null references public.creator_packs(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  price integer not null,
  cut integer not null,
  created_at timestamptz not null default now(),
  primary key (pack_id, user_id)
);
create index if not exists zchat_creator_pack_buyers_user on public.creator_pack_buyers (user_id, created_at desc);

alter table public.creator_packs enable row level security;
alter table public.creator_pack_items enable row level security;
alter table public.creator_pack_reviews enable row level security;
alter table public.creator_pack_buyers enable row level security;

create or replace function public.zchat_cr_pack_owner(p_pack uuid)
returns uuid
language sql
stable
security definer
set search_path = public
as $$ select p.owner_id from public.creator_packs p where p.id = p_pack $$;

create or replace function public.zchat_cr_pack_bought(p_pack uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$ select exists (select 1 from public.creator_pack_buyers b where b.pack_id = p_pack and b.user_id = auth.uid()) $$;
grant execute on function public.zchat_cr_pack_owner(uuid) to authenticated;
grant execute on function public.zchat_cr_pack_bought(uuid) to authenticated;

drop policy if exists "zchat creator packs read" on public.creator_packs;
create policy "zchat creator packs read" on public.creator_packs for select to authenticated
  using (status = 'live' or owner_id = (select auth.uid()) or public.zchat_cr_pack_bought(id) or public.zchat_is_admin());
drop policy if exists "zchat creator pack items read" on public.creator_pack_items;
create policy "zchat creator pack items read" on public.creator_pack_items for select to authenticated
  using (public.zchat_cr_pack_bought(pack_id) or public.zchat_cr_pack_owner(pack_id) = (select auth.uid()) or public.zchat_is_admin());
create or replace function public.zchat_cr_pack_on_sale(p_source uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$ select exists (select 1 from public.creator_packs c where c.pack_id = p_source and c.status in ('review', 'live')) $$;
grant execute on function public.zchat_cr_pack_on_sale(uuid) to authenticated;
do $$
begin
  if to_regclass('public.sticker_packs') is not null then
    execute 'drop policy if exists "zchat creator pack source" on public.sticker_packs';
    execute 'create policy "zchat creator pack source" on public.sticker_packs as restrictive for select to authenticated using (owner_id = (select auth.uid()) or not public.zchat_cr_pack_on_sale(id) or public.zchat_is_admin())';
  end if;
end $$;
drop policy if exists "zchat creator pack reviews read" on public.creator_pack_reviews;
create policy "zchat creator pack reviews read" on public.creator_pack_reviews for select to authenticated
  using (public.zchat_cr_pack_owner(pack_id) = (select auth.uid()) or public.zchat_is_admin());
drop policy if exists "zchat creator pack buyers read" on public.creator_pack_buyers;
create policy "zchat creator pack buyers read" on public.creator_pack_buyers for select to authenticated
  using (user_id = (select auth.uid()) or public.zchat_cr_pack_owner(pack_id) = (select auth.uid()));
revoke insert, update, delete on public.creator_packs, public.creator_pack_items, public.creator_pack_reviews, public.creator_pack_buyers from anon, authenticated;

create or replace function public.zchat_cr_pack_flags(p_name text)
returns jsonb
language sql
immutable
as $$
  select coalesce(jsonb_agg(w), '[]'::jsonb) from unnest(array[
    'disney', 'pixar', 'marvel', 'pokemon', 'pikachu', 'nintendo', 'mario', 'sanrio', 'hello kitty', 'kuromi', 'cinnamoroll', 'melody',
    'bt21', 'line friends', 'spongebob', 'minecraft', 'fortnite', 'roblox', 'naruto', 'one piece', 'dragon ball', 'doraemon', 'shinchan',
    'peppa', 'mickey', 'frozen', 'barbie', 'star wars', 'harry potter', 'batman', 'spiderman', 'spider man', 'superman', 'snoopy',
    'garfield', 'sonic', 'kirby', 'zelda', 'genshin', 'goma', 'pusheen', 'molang', 'rilakkuma', 'squid game', 'bts', 'blackpink'
  ]) w where lower(coalesce(p_name, '')) like '%' || w || '%'
$$;

create or replace function public.zchat_cr_pack_sell(p_pack uuid, p_price integer)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  sp record;
  cp public.creator_packs;
  v_list jsonb;
  v_n integer;
  v_foreign integer;
  v_items jsonb;
  v_flags jsonb;
  v_today integer;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if not public.zchat_cr_active(me) then
    return jsonb_build_object('ok', false, 'reason', 'Your account cannot sell right now.');
  end if;
  if p_price is null or not (p_price = any (public.zchat_cr_prices('pack'))) then
    return jsonb_build_object('ok', false, 'reason', 'Pick a price from the list.');
  end if;
  select s.id, s.owner_id, s.name, s.stickers into sp from public.sticker_packs s where s.id = p_pack;
  if not found or sp.owner_id is distinct from me then
    return jsonb_build_object('ok', false, 'reason', 'You can only sell packs you made.');
  end if;
  if coalesce(public.zchat_account_created(me) > now() - interval '7 days', true) then
    return jsonb_build_object('ok', false, 'reason', 'Selling packs opens up after your first week on ZChat.');
  end if;
  select coalesce(jsonb_agg(u order by i), '[]'::jsonb) into v_list from (
    select distinct on (u) u, i from jsonb_array_elements_text(case when jsonb_typeof(sp.stickers) = 'array' then sp.stickers else '[]'::jsonb end) with ordinality as t(u, i)
    where u ~ '^(https?://|/)' and char_length(u) <= 600 order by u, i
  ) z;
  v_n := jsonb_array_length(v_list);
  if v_n < 4 then
    return jsonb_build_object('ok', false, 'reason', 'A pack needs at least 4 stickers to sell.');
  end if;
  if v_n > 120 then
    return jsonb_build_object('ok', false, 'reason', 'A pack can have up to 120 stickers.');
  end if;
  select count(*) into v_foreign from jsonb_array_elements_text(v_list) u
    where not exists (select 1 from public.user_stickers us where us.user_id = me and us.url = u);
  if v_foreign > 0 then
    return jsonb_build_object('ok', false, 'reason', 'Only stickers you made yourself can be sold. Remove the others from this pack first.');
  end if;
  v_flags := public.zchat_cr_pack_flags(sp.name);
  select * into cp from public.creator_packs where pack_id = p_pack for update;
  if not found then
    select count(*) into v_today from public.creator_packs x where x.owner_id = me and x.created_at > now() - interval '1 day';
    if v_today >= 5 then
      return jsonb_build_object('ok', false, 'reason', 'You put a lot of packs up today. Try again tomorrow.');
    end if;
    insert into public.creator_packs (pack_id, owner_id, name, price, status, count, preview)
      values (p_pack, me, left(sp.name, 40), p_price, 'review', v_n, '[]'::jsonb) returning * into cp;
  else
    if cp.owner_id is distinct from me then
      return jsonb_build_object('ok', false, 'reason', 'You can only sell packs you made.');
    end if;
    update public.creator_packs set price = p_price, name = case when status = 'live' then name else left(sp.name, 40) end, updated_at = now(),
      status = case when status in ('rejected', 'off') and not exists (select 1 from public.creator_pack_items it where it.pack_id = cp.id) then 'review'
                    when status = 'rejected' then 'review' else status end
      where id = cp.id returning * into cp;
  end if;
  select it.stickers into v_items from public.creator_pack_items it where it.pack_id = cp.id;
  if v_items is not null and v_items = v_list and cp.name = left(sp.name, 40) then
    delete from public.creator_pack_reviews where pack_id = cp.id;
    if cp.status in ('off', 'review') then
      update public.creator_packs set status = 'live', updated_at = now() where id = cp.id returning * into cp;
    end if;
    return jsonb_build_object('ok', true, 'pack', to_jsonb(cp), 'review', false);
  end if;
  if exists (select 1 from public.creator_pack_reviews r where r.pack_id = cp.id and r.stickers = v_list and r.name is not distinct from left(sp.name, 40)) then
    return jsonb_build_object('ok', true, 'pack', to_jsonb(cp), 'review', true);
  end if;
  if (select count(*) from public.creator_pack_reviews r join public.creator_packs x on x.id = r.pack_id where x.owner_id = me and r.submitted_at > now() - interval '1 day') >= 5 then
    return jsonb_build_object('ok', false, 'reason', 'You sent a lot of packs for review today. Try again tomorrow.');
  end if;
  insert into public.creator_pack_reviews (pack_id, stickers, flags, submitted_at, name) values (cp.id, v_list, v_flags, now(), left(sp.name, 40))
    on conflict (pack_id) do update set stickers = excluded.stickers, flags = excluded.flags, submitted_at = now(), name = excluded.name;
  return jsonb_build_object('ok', true, 'pack', to_jsonb(cp), 'review', true, 'flags', v_flags);
end $$;

create or replace function public.zchat_cr_pack_stop(p_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  cp public.creator_packs;
begin
  select * into cp from public.creator_packs where id = p_id for update;
  if not found or cp.owner_id is distinct from me then
    return jsonb_build_object('ok', false, 'reason', 'You can only change your own packs.');
  end if;
  delete from public.creator_pack_reviews where pack_id = p_id;
  update public.creator_packs set status = case when exists (select 1 from public.creator_pack_items it where it.pack_id = p_id) then 'off' else 'rejected' end,
    note = case when exists (select 1 from public.creator_pack_items it where it.pack_id = p_id) then note else 'You took it off sale.' end, updated_at = now()
    where id = p_id returning * into cp;
  return jsonb_build_object('ok', true, 'pack', to_jsonb(cp));
end $$;

create or replace function public.zchat_cr_pack_buy(p_id uuid, p_expect integer)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  cp public.creator_packs;
  v_bal integer;
  v_cut integer;
  v_items jsonb;
  n integer;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  select * into cp from public.creator_packs where id = p_id;
  if not found or cp.status <> 'live' or cp.owner_id is null or not public.zchat_cr_active(cp.owner_id) then
    return jsonb_build_object('ok', false, 'reason', 'This pack is not for sale right now.');
  end if;
  if cp.owner_id = me then
    return jsonb_build_object('ok', false, 'reason', 'This is your own pack.');
  end if;
  select it.stickers into v_items from public.creator_pack_items it where it.pack_id = p_id;
  if exists (select 1 from public.creator_pack_buyers b where b.pack_id = p_id and b.user_id = me) then
    return jsonb_build_object('ok', true, 'had', true, 'stickers', coalesce(v_items, '[]'::jsonb));
  end if;
  if v_items is null then
    return jsonb_build_object('ok', false, 'reason', 'This pack is not for sale right now.');
  end if;
  if p_expect is distinct from cp.price then
    return jsonb_build_object('ok', false, 'price', cp.price, 'reason', 'The price is now ' || public.zchat_cr_coins(cp.price) || '.');
  end if;
  if not public.zchat_cr_active(me) then
    return jsonb_build_object('ok', false, 'reason', 'Your account cannot buy right now.');
  end if;
  if public.zchat_blocked_pair(me, cp.owner_id) then
    return jsonb_build_object('ok', false, 'reason', 'This pack is not for sale right now.');
  end if;
  if public.zchat_cr_new_account(me) then
    return jsonb_build_object('ok', false, 'reason', 'New accounts can buy packs after their first day.');
  end if;
  perform public.zchat_cr_lock2(me, cp.owner_id);
  select count(*) into n from public.creator_pack_buyers b where b.user_id = me and b.created_at > now() - interval '1 hour';
  if n >= 20 then
    return jsonb_build_object('ok', false, 'reason', 'You bought a lot of packs in the last hour. Try again a little later.');
  end if;
  v_cut := public.zchat_cr_cut(cp.price);
  v_bal := public.zchat_coins_move(me, -cp.price, 'creator_out', 'Sticker pack: ' || cp.name, cp.owner_id);
  if v_bal is null then
    return jsonb_build_object('ok', false, 'reason', 'You do not have enough coins.', 'price', cp.price);
  end if;
  if public.zchat_coins_move(cp.owner_id, v_cut, 'creator_in', 'Sticker pack: ' || cp.name, me) is null then
    raise exception 'The pack could not be bought' using errcode = 'P0001';
  end if;
  insert into public.creator_pack_buyers (pack_id, user_id, price, cut) values (p_id, me, cp.price, v_cut);
  update public.creator_packs set sales = sales + 1 where id = p_id;
  perform public.zchat_cr_note(cp.owner_id, me, 'pack_sold', 'bought your sticker pack ' || cp.name || '. You got ' || public.zchat_cr_coins(v_cut) || '.', jsonb_build_object('pack', p_id, 'coins', v_cut));
  return jsonb_build_object('ok', true, 'coins', v_bal, 'stickers', v_items, 'pack', jsonb_build_object('id', cp.id, 'name', cp.name, 'owner_id', cp.owner_id));
end $$;

create or replace function public.zchat_cr_pack_queue()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.zchat_is_admin() then
    raise exception 'Only admins can see this' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', p.id, 'name', coalesce(r.name, p.name), 'price', p.price, 'status', p.status, 'sales', p.sales,
      'stickers', r.stickers, 'flags', r.flags, 'submitted_at', r.submitted_at, 'live', exists (select 1 from public.creator_pack_items it where it.pack_id = p.id),
      'owner', (select jsonb_build_object('id', pr.id, 'name', pr.name, 'username', pr.username, 'avatar', pr.avatar, 'verified', pr.verified, 'created_at', pr.created_at) from public.profiles pr where pr.id = p.owner_id)
    ) order by r.submitted_at)
    from public.creator_pack_reviews r join public.creator_packs p on p.id = r.pack_id
  ), '[]'::jsonb);
end $$;

create or replace function public.zchat_cr_pack_review(p_id uuid, p_ok boolean, p_note text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  cp public.creator_packs;
  rv public.creator_pack_reviews;
  v_note text := nullif(btrim(left(coalesce(p_note, ''), 200)), '');
  v_live boolean;
begin
  if not public.zchat_is_admin() then
    raise exception 'Only admins can review packs' using errcode = '42501';
  end if;
  select * into cp from public.creator_packs where id = p_id for update;
  select * into rv from public.creator_pack_reviews where pack_id = p_id for update;
  if cp.id is null or rv.pack_id is null then
    return jsonb_build_object('ok', false, 'reason', 'That pack is not waiting for review.');
  end if;
  v_live := exists (select 1 from public.creator_pack_items it where it.pack_id = p_id);
  if p_ok then
    insert into public.creator_pack_items (pack_id, stickers, updated_at) values (p_id, rv.stickers, now())
      on conflict (pack_id) do update set stickers = excluded.stickers, updated_at = now();
    update public.creator_packs set status = case when status = 'off' then 'off' else 'live' end, note = null, name = coalesce(rv.name, name),
      count = jsonb_array_length(rv.stickers),
      preview = (select coalesce(jsonb_agg(u), '[]'::jsonb) from (select u from jsonb_array_elements_text(rv.stickers) with ordinality t(u, i) order by i limit 4) z),
      reviewed_at = now(), reviewed_by = me, updated_at = now()
      where id = p_id returning * into cp;
    perform public.zchat_cr_note(cp.owner_id, null, 'pack_live', 'Your sticker pack ' || cp.name || case when v_live then ' was updated.' else ' is live. People can buy it from your profile.' end, jsonb_build_object('pack', p_id));
  else
    update public.creator_packs set status = case when v_live then status else 'rejected' end, note = coalesce(v_note, 'It looks like art you did not make.'),
      reviewed_at = now(), reviewed_by = me, updated_at = now()
      where id = p_id returning * into cp;
    perform public.zchat_cr_note(cp.owner_id, null, 'pack_rejected', 'Your sticker pack ' || cp.name || ' was not approved: ' || coalesce(v_note, 'It looks like art you did not make.'), jsonb_build_object('pack', p_id));
  end if;
  delete from public.creator_pack_reviews where pack_id = p_id;
  return jsonb_build_object('ok', true, 'pack', to_jsonb(cp));
end $$;

create or replace function public.zchat_cr_packs_of(p_owner uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name, 'preview', p.preview, 'count', p.count, 'price', p.price, 'sales', p.sales,
    'mine', exists (select 1 from public.creator_pack_buyers b where b.pack_id = p.id and b.user_id = auth.uid())) order by p.sales desc, p.created_at desc), '[]'::jsonb)
  from public.creator_packs p
  where p.owner_id = p_owner and p.status = 'live'
    and (auth.uid() = p_owner or (not public.zchat_blocked_pair(auth.uid(), p_owner) and public.zchat_owner_visible(p_owner, 'posts')))
$$;

create or replace function public.zchat_cr_packs_top(p_limit integer default 12)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(jsonb_agg(x.j), '[]'::jsonb) from (
    select jsonb_build_object('id', p.id, 'name', p.name, 'preview', p.preview, 'count', p.count, 'price', p.price, 'sales', p.sales, 'owner_id', p.owner_id,
      'owner', jsonb_build_object('id', pr.id, 'name', pr.name, 'username', pr.username, 'avatar', case when coalesce(pr.hide_photo, false) then '' else pr.avatar end, 'verified', pr.verified),
      'mine', exists (select 1 from public.creator_pack_buyers b where b.pack_id = p.id and b.user_id = auth.uid())) as j
    from public.creator_packs p join public.profiles pr on pr.id = p.owner_id
    where p.status = 'live' and not coalesce(pr.banned, false) and not coalesce(pr.is_deleted, false)
      and (auth.uid() = p.owner_id or (not public.zchat_blocked_pair(auth.uid(), p.owner_id) and public.zchat_owner_visible(p.owner_id, 'posts')))
    order by (p.owner_id in (select f.following_id from public.follows f where f.follower_id = auth.uid() and coalesce(f.status, 'accepted') = 'accepted')) desc, p.sales desc, p.created_at desc
    limit greatest(1, least(coalesce(p_limit, 12), 40))
  ) x
$$;

create or replace function public.zchat_cr_packs_bought()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name, 'owner_id', p.owner_id, 'stickers', coalesce(it.stickers, '[]'::jsonb)) order by b.created_at desc), '[]'::jsonb)
  from public.creator_pack_buyers b join public.creator_packs p on p.id = b.pack_id left join public.creator_pack_items it on it.pack_id = p.id
  where b.user_id = auth.uid()
$$;

revoke execute on function public.zchat_cr_pack_sell(uuid, integer), public.zchat_cr_pack_stop(uuid), public.zchat_cr_pack_buy(uuid, integer),
  public.zchat_cr_pack_queue(), public.zchat_cr_pack_review(uuid, boolean, text), public.zchat_cr_packs_of(uuid), public.zchat_cr_packs_top(integer), public.zchat_cr_packs_bought() from public, anon;
grant execute on function public.zchat_cr_pack_sell(uuid, integer), public.zchat_cr_pack_stop(uuid), public.zchat_cr_pack_buy(uuid, integer),
  public.zchat_cr_pack_queue(), public.zchat_cr_pack_review(uuid, boolean, text), public.zchat_cr_packs_of(uuid), public.zchat_cr_packs_top(integer), public.zchat_cr_packs_bought() to authenticated;

select public.zchat_apply_session_gate();
commit;

begin;
create table if not exists public.creator_members (
  id uuid primary key default gen_random_uuid(),
  creator_id uuid not null references auth.users(id) on delete cascade,
  member_id uuid not null references auth.users(id) on delete cascade,
  price integer not null check (price > 0),
  status text not null default 'active' check (status in ('active', 'ended')),
  started_at timestamptz not null default now(),
  period_end timestamptz not null,
  cancel_at_end boolean not null default false,
  reminded_for timestamptz,
  renewals integer not null default 0,
  ended_at timestamptz,
  end_reason text,
  unique (creator_id, member_id)
);
create index if not exists zchat_creator_members_due on public.creator_members (period_end) where status = 'active';
create index if not exists zchat_creator_members_member on public.creator_members (member_id) where status = 'active';
alter table public.creator_members enable row level security;
drop policy if exists "zchat creator members read" on public.creator_members;
create policy "zchat creator members read" on public.creator_members for select to authenticated
  using (member_id = (select auth.uid()) or creator_id = (select auth.uid()));
revoke insert, update, delete on public.creator_members from anon, authenticated;

create or replace function public.zchat_cr_is_member(p_creator uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select auth.uid() is not null and (
    auth.uid() = p_creator
    or public.zchat_is_admin_id(auth.uid())
    or exists (select 1 from public.creator_members m where m.creator_id = p_creator and m.member_id = auth.uid() and m.status = 'active')
  )
$$;
grant execute on function public.zchat_cr_is_member(uuid) to anon, authenticated;

alter table public.posts add column if not exists members_only boolean not null default false;
alter table public.stories add column if not exists members_only boolean not null default false;

drop policy if exists "zchat members only posts" on public.posts;
create policy "zchat members only posts" on public.posts as restrictive for select to anon, authenticated
  using (not members_only or user_id = (select auth.uid()) or public.zchat_cr_is_member(user_id));
drop policy if exists "zchat members only stories" on public.stories;
create policy "zchat members only stories" on public.stories as restrictive for select to anon, authenticated
  using (not members_only or user_id = (select auth.uid()) or public.zchat_cr_is_member(user_id));

create or replace function public.zchat_cr_members_only_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.members_only and (tg_op = 'INSERT' or not old.members_only)
     and not exists (select 1 from public.creator_settings s where s.user_id = new.user_id and s.member_price is not null) then
    raise exception 'Turn on memberships first to share with members only' using errcode = '42501';
  end if;
  return new;
end $$;
drop trigger if exists zchat_cr_members_only_guard on public.posts;
create trigger zchat_cr_members_only_guard before insert or update of members_only on public.posts
  for each row execute function public.zchat_cr_members_only_guard();
drop trigger if exists zchat_cr_members_only_guard on public.stories;
create trigger zchat_cr_members_only_guard before insert or update of members_only on public.stories
  for each row execute function public.zchat_cr_members_only_guard();

do $$
declare
  def text;
  fixed text;
begin
  if to_regprocedure('public.public_post_preview(text)') is not null then
    def := pg_get_functiondef('public.public_post_preview(text)'::regprocedure);
    if position('members_only' in def) = 0 then
      fixed := replace(def, 'if not public.zchat_owner_visible(po.user_id, ''posts'') then',
        'if not public.zchat_owner_visible(po.user_id, ''posts'') or (coalesce((to_jsonb(po) ->> ''members_only'')::boolean, false) and not public.zchat_cr_is_member(po.user_id)) then');
      if fixed <> def then
        execute fixed;
      else
        raise notice 'zchat creator: public_post_preview was not changed, add the members only check by hand';
      end if;
    end if;
  end if;
  if to_regprocedure('public.public_profile_preview(text)') is not null then
    def := pg_get_functiondef('public.public_profile_preview(text)'::regprocedure);
    if position('members_only' in def) = 0 then
      fixed := regexp_replace(def, '(\s+)order by created_at desc limit 9\) x', '\1and not coalesce(members_only, false) order by created_at desc limit 9) x');
      if fixed <> def then
        execute fixed;
      else
        raise notice 'zchat creator: public_profile_preview was not changed, add the members only check by hand';
      end if;
    end if;
  end if;
end $$;

create or replace function public.zchat_cr_members_group(p_creator uuid)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  gid uuid;
  pr record;
begin
  select s.members_group into gid from public.creator_settings s where s.user_id = p_creator for update;
  if gid is not null and exists (select 1 from public.groups g where g.id = gid) then
    return gid;
  end if;
  select p.name, p.avatar into pr from public.profiles p where p.id = p_creator;
  perform set_config('zchat.cr_ok', '1', true);
  insert into public.groups (name, bio, avatar, created_by, invite_enabled)
    values (left(coalesce(nullif(btrim(pr.name), ''), 'Creator'), 28) || ' members', 'A chat for members only', pr.avatar, p_creator, false)
    returning id into gid;
  insert into public.group_members (group_id, user_id, role) values (gid, p_creator, 'admin') on conflict do nothing;
  insert into public.group_members (group_id, user_id, role)
    select gid, m.member_id, 'member' from public.creator_members m where m.creator_id = p_creator and m.status = 'active'
    on conflict do nothing;
  perform set_config('zchat.cr_ok', '', true);
  update public.creator_settings set members_group = gid where user_id = p_creator;
  return gid;
end $$;
revoke execute on function public.zchat_cr_members_group(uuid) from public, anon, authenticated;

create or replace function public.zchat_cr_member_join(p_creator uuid, p_expect integer)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  st public.creator_settings;
  cur public.creator_members;
  v_bal integer;
  v_cut integer;
  gid uuid;
  n integer;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if p_creator is null or p_creator = me then
    return jsonb_build_object('ok', false, 'reason', 'You cannot join your own membership.');
  end if;
  select * into st from public.creator_settings s where s.user_id = p_creator;
  select * into cur from public.creator_members m where m.creator_id = p_creator and m.member_id = me for update;
  if cur.id is not null and cur.status = 'active' then
    if cur.cancel_at_end then
      update public.creator_members set cancel_at_end = false where id = cur.id returning * into cur;
      return jsonb_build_object('ok', true, 'resumed', true, 'member', to_jsonb(cur));
    end if;
    return jsonb_build_object('ok', true, 'already', true, 'member', to_jsonb(cur));
  end if;
  if st.member_price is null or not public.zchat_cr_can_create(p_creator) then
    return jsonb_build_object('ok', false, 'reason', 'Memberships are not open right now.');
  end if;
  if p_expect is distinct from st.member_price then
    return jsonb_build_object('ok', false, 'price', st.member_price, 'reason', 'The membership is now ' || public.zchat_cr_coins(st.member_price) || ' a month.');
  end if;
  if not public.zchat_cr_active(me) then
    return jsonb_build_object('ok', false, 'reason', 'Your account cannot join right now.');
  end if;
  if public.zchat_blocked_pair(me, p_creator) or not public.zchat_owner_visible(p_creator, 'posts') then
    return jsonb_build_object('ok', false, 'reason', 'You cannot join this membership.');
  end if;
  if public.zchat_cr_new_account(me) then
    return jsonb_build_object('ok', false, 'reason', 'New accounts can join memberships after their first day.');
  end if;
  perform public.zchat_cr_lock2(me, p_creator);
  select count(*) into n from public.creator_members m where m.member_id = me and m.started_at > now() - interval '1 hour';
  if n >= 10 then
    return jsonb_build_object('ok', false, 'reason', 'You joined a lot of memberships in the last hour. Try again a little later.');
  end if;
  v_cut := public.zchat_cr_cut(st.member_price);
  v_bal := public.zchat_coins_move(me, -st.member_price, 'creator_out', 'Membership: ' || public.zchat_cr_uname(p_creator), p_creator);
  if v_bal is null then
    return jsonb_build_object('ok', false, 'reason', 'You do not have enough coins.', 'price', st.member_price);
  end if;
  if public.zchat_coins_move(p_creator, v_cut, 'creator_in', 'Membership: ' || public.zchat_cr_uname(me), me) is null then
    raise exception 'The membership could not be started' using errcode = 'P0001';
  end if;
  insert into public.creator_members (creator_id, member_id, price, status, started_at, period_end, cancel_at_end, reminded_for, renewals, ended_at, end_reason)
    values (p_creator, me, st.member_price, 'active', now(), now() + interval '1 month', false, null, 0, null, null)
    on conflict (creator_id, member_id) do update set price = excluded.price, status = 'active', started_at = now(), period_end = excluded.period_end,
      cancel_at_end = false, reminded_for = null, renewals = 0, ended_at = null, end_reason = null
    returning * into cur;
  gid := public.zchat_cr_members_group(p_creator);
  perform set_config('zchat.cr_ok', '1', true);
  insert into public.group_members (group_id, user_id, role) values (gid, me, 'member') on conflict do nothing;
  perform set_config('zchat.cr_ok', '', true);
  perform public.zchat_cr_note(p_creator, me, 'member_join', 'joined your membership. You got ' || public.zchat_cr_coins(v_cut) || '.', jsonb_build_object('coins', v_cut));
  return jsonb_build_object('ok', true, 'coins', v_bal, 'member', to_jsonb(cur), 'group_id', gid);
end $$;

create or replace function public.zchat_cr_member_cancel(p_creator uuid, p_cancel boolean)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  cur public.creator_members;
begin
  update public.creator_members set cancel_at_end = coalesce(p_cancel, true)
    where creator_id = p_creator and member_id = me and status = 'active'
    returning * into cur;
  if cur.id is null then
    return jsonb_build_object('ok', false, 'reason', 'You are not a member right now.');
  end if;
  return jsonb_build_object('ok', true, 'member', to_jsonb(cur));
end $$;

create or replace function public.zchat_cr_member_end(p_row uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  m public.creator_members;
  gid uuid;
begin
  update public.creator_members set status = 'ended', ended_at = now(), end_reason = p_reason
    where id = p_row and status = 'active' returning * into m;
  if m.id is null then
    return;
  end if;
  select s.members_group into gid from public.creator_settings s where s.user_id = m.creator_id;
  if gid is not null then
    perform set_config('zchat.cr_ok', '1', true);
    delete from public.group_members gm where gm.group_id = gid and gm.user_id = m.member_id;
    perform set_config('zchat.cr_ok', '', true);
  end if;
end $$;
revoke execute on function public.zchat_cr_member_end(uuid, text) from public, anon, authenticated;

create or replace function public.zchat_cr_member_ids(p_creator uuid)
returns uuid[]
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(array_agg(m.member_id), array[]::uuid[]) from (
    select m.member_id from public.creator_members m
    where m.creator_id = p_creator and m.status = 'active'
      and (auth.uid() = p_creator or (not public.zchat_blocked_pair(auth.uid(), p_creator) and public.zchat_owner_visible(p_creator, 'posts')))
    order by m.started_at limit 5000
  ) m
$$;

create or replace function public.zchat_cr_page(p_creator uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  st public.creator_settings;
  mine public.creator_members;
  vis boolean;
begin
  if me is null or p_creator is null then
    return null;
  end if;
  vis := me = p_creator or (not public.zchat_blocked_pair(me, p_creator) and public.zchat_owner_visible(p_creator, 'posts'));
  select * into st from public.creator_settings s where s.user_id = p_creator;
  select * into mine from public.creator_members m where m.creator_id = p_creator and m.member_id = me;
  return jsonb_build_object(
    'visible', vis,
    'creator', public.zchat_cr_can_create(p_creator),
    'member_price', case when vis and public.zchat_cr_can_create(p_creator) then st.member_price end,
    'member_perks', case when vis then st.member_perks end,
    'msg_price', case when vis and public.zchat_cr_can_create(p_creator) then st.msg_price end,
    'shout_price', case when vis and public.zchat_cr_can_create(p_creator) then st.shout_price end,
    'shout_note', case when vis then st.shout_note end,
    'members', case when vis then (select count(*) from public.creator_members m where m.creator_id = p_creator and m.status = 'active') else 0 end,
    'mine', case when mine.id is null then null else to_jsonb(mine) end,
    'group_id', case when mine.status = 'active' or me = p_creator then st.members_group end,
    'packs', case when vis then public.zchat_cr_packs_of(p_creator) else '[]'::jsonb end,
    'shop', case when vis then (select count(*) from public.shop_listings l where l.owner_id = p_creator) else 0 end
  );
exception when undefined_table then
  return jsonb_build_object('visible', vis, 'creator', public.zchat_cr_can_create(p_creator), 'member_price', st.member_price, 'msg_price', st.msg_price, 'shout_price', st.shout_price,
    'members', 0, 'mine', case when mine.id is null then null else to_jsonb(mine) end, 'packs', '[]'::jsonb, 'shop', 0);
end $$;

revoke execute on function public.zchat_cr_member_join(uuid, integer), public.zchat_cr_member_cancel(uuid, boolean), public.zchat_cr_member_ids(uuid), public.zchat_cr_page(uuid) from public, anon;
grant execute on function public.zchat_cr_member_join(uuid, integer), public.zchat_cr_member_cancel(uuid, boolean), public.zchat_cr_member_ids(uuid), public.zchat_cr_page(uuid) to authenticated;

select public.zchat_apply_session_gate();

create table if not exists public.creator_msg_holds (
  id uuid primary key default gen_random_uuid(),
  sender_id uuid not null references auth.users(id) on delete cascade,
  receiver_id uuid not null references auth.users(id) on delete cascade,
  message_id bigint,
  price integer not null check (price > 0),
  cut integer not null check (cut >= 0),
  status text not null default 'held' check (status in ('held', 'paid', 'refunded')),
  created_at timestamptz not null default now(),
  settled_at timestamptz
);
create index if not exists zchat_cr_holds_pair on public.creator_msg_holds (receiver_id, sender_id) where status = 'held';
create index if not exists zchat_cr_holds_due on public.creator_msg_holds (created_at) where status = 'held';
create index if not exists zchat_cr_holds_sender on public.creator_msg_holds (sender_id, created_at desc);
alter table public.creator_msg_holds enable row level security;
drop policy if exists "zchat creator holds read" on public.creator_msg_holds;
create policy "zchat creator holds read" on public.creator_msg_holds for select to authenticated
  using (sender_id = (select auth.uid()) or receiver_id = (select auth.uid()));
revoke insert, update, delete on public.creator_msg_holds from anon, authenticated;

create or replace function public.zchat_cr_dm_free(p_from uuid, p_to uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select p_from is null or p_to is null or p_from = p_to
    or not exists (select 1 from public.creator_settings s where s.user_id = p_to and s.msg_price is not null)
    or public.zchat_follows(p_to, p_from)
    or exists (select 1 from public.creator_dm_open o where o.creator_id = p_to and o.fan_id = p_from)
    or public.zchat_is_admin_id(p_from)
    or exists (select 1 from public.profiles p where p.id = p_from and coalesce(p.is_bot, false))
    or not public.zchat_cr_can_create(p_to)
$$;
grant execute on function public.zchat_cr_dm_free(uuid, uuid) to authenticated, service_role;

create or replace function public.zchat_cr_msg_gate()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if new.group_id is not null or new.receiver_id is null or new.sender_id is null or new.sender_id = new.receiver_id then
    return new;
  end if;
  if pg_trigger_depth() > 1 or coalesce(current_setting('zchat.cr_msg_ok', true), '') = '1' then
    return new;
  end if;
  if public.zchat_cr_dm_free(new.sender_id, new.receiver_id) then
    return new;
  end if;
  raise exception 'This person takes messages for coins. Open the chat to send one' using errcode = 'P0001';
end $$;
drop trigger if exists zchat_cr_msg_gate on public.messages;
create trigger zchat_cr_msg_gate before insert on public.messages
  for each row execute function public.zchat_cr_msg_gate();

create or replace function public.zchat_cr_msg_reply()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  h record;
  v_open boolean;
begin
  if new.group_id is not null or new.receiver_id is null or new.sender_id is null or new.sender_id = new.receiver_id or pg_trigger_depth() > 1 then
    return null;
  end if;
  if coalesce(new.type, 'text') = 'system' or coalesce(new.content, '') like 'zaway:%' or coalesce(new.bot_reply, false) then
    return null;
  end if;
  begin
    v_open := exists (select 1 from public.creator_settings s where s.user_id = new.sender_id and s.msg_price is not null);
    for h in
      select * from public.creator_msg_holds x where x.receiver_id = new.sender_id and x.sender_id = new.receiver_id and x.status = 'held'
      order by x.created_at for update
    loop
      v_open := true;
      perform public.zchat_wallet_lock(h.receiver_id);
      if public.zchat_coins_move(h.receiver_id, h.cut, 'creator_in', 'Paid message: ' || public.zchat_cr_uname(h.sender_id), h.sender_id) is not null then
        update public.creator_msg_holds set status = 'paid', settled_at = now() where id = h.id;
      end if;
    end loop;
    if v_open then
      insert into public.creator_dm_open (creator_id, fan_id) values (new.sender_id, new.receiver_id) on conflict do nothing;
    end if;
  exception when others then
    raise notice 'zchat paid message release skipped: %', sqlerrm;
  end;
  return null;
end $$;
drop trigger if exists zchat_cr_msg_reply on public.messages;
create trigger zchat_cr_msg_reply after insert on public.messages
  for each row execute function public.zchat_cr_msg_reply();

create or replace function public.zchat_cr_chat_state(p_other uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  v_price integer;
begin
  if me is null or p_other is null then
    return null;
  end if;
  select s.msg_price into v_price from public.creator_settings s where s.user_id = p_other;
  return jsonb_build_object(
    'price', v_price,
    'free', public.zchat_cr_dm_free(me, p_other),
    'mine_on', exists (select 1 from public.creator_settings s where s.user_id = me and s.msg_price is not null),
    'holds', coalesce((
      select jsonb_agg(jsonb_build_object('id', h.id, 'sender_id', h.sender_id, 'receiver_id', h.receiver_id, 'message_id', h.message_id, 'price', h.price, 'cut', h.cut,
        'status', h.status, 'created_at', h.created_at, 'until', h.created_at + interval '3 days') order by h.created_at desc)
      from (select * from public.creator_msg_holds x where (x.sender_id = me and x.receiver_id = p_other) or (x.sender_id = p_other and x.receiver_id = me) order by x.created_at desc limit 30) h
    ), '[]'::jsonb)
  );
end $$;

create or replace function public.zchat_cr_msg_send(p_to uuid, p_text text, p_expect integer, p_client text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  v_text text := nullif(btrim(left(regexp_replace(coalesce(p_text, ''), '[' || chr(8203) || chr(8206) || chr(8207) || chr(8234) || '-' || chr(8238) || chr(8288) || '-' || chr(8297) || chr(65279) || ']+', '', 'g'), 1000)), '');
  v_price integer;
  v_bal integer;
  v_cut integer;
  msg public.messages;
  hold public.creator_msg_holds;
  n integer;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if v_text is null then
    return jsonb_build_object('ok', false, 'reason', 'Write your message first.');
  end if;
  if p_to is null or p_to = me then
    return jsonb_build_object('ok', false, 'reason', 'Pick someone else.');
  end if;
  select s.msg_price into v_price from public.creator_settings s where s.user_id = p_to;
  if public.zchat_cr_dm_free(me, p_to) then
    return jsonb_build_object('ok', false, 'free', true, 'reason', 'You can message them for free now.');
  end if;
  if p_expect is distinct from v_price then
    return jsonb_build_object('ok', false, 'price', v_price, 'reason', 'A message now costs ' || public.zchat_cr_coins(v_price) || '.');
  end if;
  if not public.zchat_cr_active(me) or not public.zchat_cr_active(p_to) then
    return jsonb_build_object('ok', false, 'reason', 'You cannot message this person right now.');
  end if;
  if public.zchat_blocked_pair(me, p_to) or not public.zchat_can_dm(me, p_to) then
    return jsonb_build_object('ok', false, 'reason', 'You cannot message this person right now.');
  end if;
  if exists (select 1 from public.creator_msg_holds h where h.sender_id = me and h.receiver_id = p_to and h.status = 'held') then
    return jsonb_build_object('ok', false, 'reason', 'Your last message is still waiting for a reply.');
  end if;
  if public.zchat_cr_new_account(me) then
    return jsonb_build_object('ok', false, 'reason', 'New accounts can send paid messages after their first day.');
  end if;
  perform public.zchat_cr_lock2(me, p_to);
  select count(*) into n from public.creator_msg_holds h where h.sender_id = me and h.created_at > now() - interval '1 day';
  if n >= 20 then
    return jsonb_build_object('ok', false, 'reason', 'You sent a lot of paid messages today. Try again tomorrow.');
  end if;
  v_cut := public.zchat_cr_cut(v_price);
  v_bal := public.zchat_coins_move(me, -v_price, 'creator_out', 'Paid message: ' || public.zchat_cr_uname(p_to), p_to);
  if v_bal is null then
    return jsonb_build_object('ok', false, 'reason', 'You do not have enough coins.', 'price', v_price);
  end if;
  perform set_config('zchat.cr_msg_ok', '1', true);
  perform set_config('zchat.cr_card_ok', '1', true);
  insert into public.messages (sender_id, receiver_id, type, content, client_id)
    values (me, p_to, 'text', 'zpaid:' || jsonb_build_object('t', v_text, 'n', v_price)::text, nullif(left(coalesce(p_client, ''), 64), ''))
    returning * into msg;
  perform set_config('zchat.cr_msg_ok', '', true);
  perform set_config('zchat.cr_card_ok', '', true);
  insert into public.creator_msg_holds (sender_id, receiver_id, message_id, price, cut) values (me, p_to, msg.id, v_price, v_cut) returning * into hold;
  perform public.zchat_cr_conv_touch(me, p_to, 'Paid message: ' || v_text);
  perform public.zchat_cr_note(p_to, me, 'msg_paid', 'sent you a paid message. Reply in 3 days to get ' || public.zchat_cr_coins(v_cut) || '.', jsonb_build_object('coins', v_cut, 'message_id', msg.id));
  return jsonb_build_object('ok', true, 'coins', v_bal, 'message', to_jsonb(msg),
    'hold', jsonb_build_object('id', hold.id, 'sender_id', me, 'receiver_id', p_to, 'message_id', msg.id, 'price', v_price, 'cut', v_cut, 'status', 'held', 'created_at', hold.created_at, 'until', hold.created_at + interval '3 days'));
end $$;

revoke execute on function public.zchat_cr_chat_state(uuid), public.zchat_cr_msg_send(uuid, text, integer, text) from public, anon;
grant execute on function public.zchat_cr_chat_state(uuid), public.zchat_cr_msg_send(uuid, text, integer, text) to authenticated;

select public.zchat_apply_session_gate();
commit;

begin;
create table if not exists public.creator_shoutouts (
  id uuid primary key default gen_random_uuid(),
  fan_id uuid not null references auth.users(id) on delete cascade,
  creator_id uuid not null references auth.users(id) on delete cascade,
  price integer not null check (price > 0),
  cut integer not null check (cut >= 0),
  occasion text not null default 'message' check (occasion in ('birthday', 'message')),
  to_name text not null check (char_length(to_name) between 1 and 40),
  note text check (note is null or char_length(note) <= 300),
  status text not null default 'pending' check (status in ('pending', 'delivered', 'declined', 'refunded')),
  reason text check (reason is null or char_length(reason) <= 200),
  message_id bigint,
  media_url text,
  secs integer,
  due_at timestamptz not null default now() + interval '7 days',
  created_at timestamptz not null default now(),
  settled_at timestamptz
);
create index if not exists zchat_cr_shout_creator on public.creator_shoutouts (creator_id, created_at desc);
create index if not exists zchat_cr_shout_fan on public.creator_shoutouts (fan_id, created_at desc);
create index if not exists zchat_cr_shout_due on public.creator_shoutouts (due_at) where status = 'pending';
alter table public.creator_shoutouts enable row level security;
drop policy if exists "zchat creator shoutouts read" on public.creator_shoutouts;
create policy "zchat creator shoutouts read" on public.creator_shoutouts for select to authenticated
  using (fan_id = (select auth.uid()) or creator_id = (select auth.uid()));
revoke insert, update, delete on public.creator_shoutouts from anon, authenticated;

create or replace function public.zchat_cr_card_guard()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if coalesce(current_setting('zchat.cr_card_ok', true), '') = '1' then
    return new;
  end if;
  if tg_op = 'UPDATE' and current_user not in ('authenticated', 'anon') then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if left(coalesce(new.content, ''), 7) = 'zshout:' then
      raise exception 'Shoutouts are sent from the order page' using errcode = '42501';
    end if;
    if left(coalesce(new.content, ''), 6) = 'zpaid:' then
      raise exception 'Paid messages are sent with coins' using errcode = '42501';
    end if;
  elsif left(coalesce(old.content, ''), 7) = 'zshout:' and (new.content is distinct from old.content or new.media_url is distinct from old.media_url or coalesce(new.deleted, false)) then
    raise exception 'A shoutout stays with the person who ordered it' using errcode = '42501';
  elsif (left(coalesce(new.content, ''), 7) = 'zshout:' or left(coalesce(new.content, ''), 6) = 'zpaid:') and new.content is distinct from old.content then
    raise exception 'This message cannot be changed' using errcode = '42501';
  end if;
  return new;
end $$;
drop trigger if exists zchat_cr_card_guard on public.messages;
create trigger zchat_cr_card_guard before insert or update of content, media_url, deleted on public.messages
  for each row execute function public.zchat_cr_card_guard();

create or replace function public.zchat_cr_shout_order(p_creator uuid, p_occasion text, p_to_name text, p_note text, p_expect integer)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  v_price integer;
  v_name text := nullif(btrim(left(regexp_replace(coalesce(p_to_name, ''), '[[:cntrl:]]+', ' ', 'g'), 40)), '');
  v_note text := nullif(btrim(left(regexp_replace(coalesce(p_note, ''), '[[:cntrl:]]+', ' ', 'g'), 300)), '');
  v_bal integer;
  o public.creator_shoutouts;
  n integer;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if p_creator is null or p_creator = me then
    return jsonb_build_object('ok', false, 'reason', 'You cannot order a shoutout from yourself.');
  end if;
  if coalesce(p_occasion, '') not in ('birthday', 'message') then
    return jsonb_build_object('ok', false, 'reason', 'Pick what the shoutout is for.');
  end if;
  if v_name is null then
    return jsonb_build_object('ok', false, 'reason', 'Add who the shoutout is for.');
  end if;
  select s.shout_price into v_price from public.creator_settings s where s.user_id = p_creator;
  if v_price is null or not public.zchat_cr_can_create(p_creator) then
    return jsonb_build_object('ok', false, 'reason', 'Shoutouts are not open right now.');
  end if;
  if p_expect is distinct from v_price then
    return jsonb_build_object('ok', false, 'price', v_price, 'reason', 'A shoutout now costs ' || public.zchat_cr_coins(v_price) || '.');
  end if;
  if not public.zchat_cr_active(me) or public.zchat_blocked_pair(me, p_creator) or not public.zchat_owner_visible(p_creator, 'posts') then
    return jsonb_build_object('ok', false, 'reason', 'You cannot order a shoutout from this person.');
  end if;
  if public.zchat_cr_new_account(me) then
    return jsonb_build_object('ok', false, 'reason', 'New accounts can order shoutouts after their first day.');
  end if;
  perform public.zchat_cr_lock2(me, p_creator);
  select count(*) into n from public.creator_shoutouts x where x.fan_id = me and x.creator_id = p_creator and x.status = 'pending';
  if n >= 3 then
    return jsonb_build_object('ok', false, 'reason', 'You already have 3 shoutouts waiting from them.');
  end if;
  select count(*) into n from public.creator_shoutouts x where x.creator_id = p_creator and x.status = 'pending';
  if n >= 30 then
    return jsonb_build_object('ok', false, 'reason', 'They have a lot of shoutouts to record. Try again in a few days.');
  end if;
  v_bal := public.zchat_coins_move(me, -v_price, 'creator_out', 'Shoutout: ' || public.zchat_cr_uname(p_creator), p_creator);
  if v_bal is null then
    return jsonb_build_object('ok', false, 'reason', 'You do not have enough coins.', 'price', v_price);
  end if;
  insert into public.creator_shoutouts (fan_id, creator_id, price, cut, occasion, to_name, note)
    values (me, p_creator, v_price, public.zchat_cr_cut(v_price), p_occasion, v_name, v_note) returning * into o;
  perform public.zchat_cr_note(p_creator, me, 'shout_order',
    'ordered a shoutout' || case when p_occasion = 'birthday' then ' for a birthday' else '' end || '. Send it within 7 days to get ' || public.zchat_cr_coins(o.cut) || '.',
    jsonb_build_object('order', o.id, 'coins', o.cut));
  return jsonb_build_object('ok', true, 'coins', v_bal, 'order', to_jsonb(o));
end $$;

create or replace function public.zchat_cr_shout_decline(p_id uuid, p_reason text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  o public.creator_shoutouts;
  v_reason text := nullif(btrim(left(regexp_replace(coalesce(p_reason, ''), '[[:cntrl:]]+', ' ', 'g'), 200)), '');
begin
  select * into o from public.creator_shoutouts where id = p_id for update;
  if not found or o.creator_id is distinct from me then
    return jsonb_build_object('ok', false, 'reason', 'That order is not yours.');
  end if;
  if o.status <> 'pending' then
    return jsonb_build_object('ok', false, 'reason', 'That order is already closed.');
  end if;
  if v_reason is null then
    return jsonb_build_object('ok', false, 'reason', 'Tell them why in a few words.');
  end if;
  perform public.zchat_wallet_lock(o.fan_id);
  if public.zchat_coins_move(o.fan_id, o.price, 'creator_back', 'Shoutout refund: ' || public.zchat_cr_uname(me), me) is null then
    return jsonb_build_object('ok', false, 'reason', 'That did not work. Try again.');
  end if;
  update public.creator_shoutouts set status = 'declined', reason = v_reason, settled_at = now() where id = p_id returning * into o;
  perform public.zchat_cr_note(o.fan_id, me, 'shout_declined', 'could not record your shoutout: "' || v_reason || '". Your ' || public.zchat_cr_coins(o.price) || ' are back.', jsonb_build_object('order', o.id, 'coins', o.price));
  return jsonb_build_object('ok', true, 'order', to_jsonb(o));
end $$;

create or replace function public.zchat_cr_shout_deliver(p_id uuid, p_media text, p_secs integer)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  o public.creator_shoutouts;
  msg public.messages;
  v_secs integer := greatest(1, least(coalesce(p_secs, 1), 60));
  v_media text := btrim(coalesce(p_media, ''));
begin
  select * into o from public.creator_shoutouts where id = p_id for update;
  if not found or o.creator_id is distinct from me then
    return jsonb_build_object('ok', false, 'reason', 'That order is not yours.');
  end if;
  if o.status <> 'pending' then
    return jsonb_build_object('ok', false, 'reason', case when o.status = 'refunded' then 'The 7 days ran out, so the coins went back.' else 'That order is already closed.' end);
  end if;
  if not (v_media ~ ('^zp:' || me::text || '/[A-Za-z0-9._-]{1,140}$') or v_media ~ ('^https://[A-Za-z0-9.-]+/storage/v1/object/public/chat-media/' || me::text || '/[A-Za-z0-9._-]{1,140}$')) then
    return jsonb_build_object('ok', false, 'reason', 'Record the video in ZChat first.');
  end if;
  if p_secs is null or p_secs < 1 or p_secs > 61 then
    return jsonb_build_object('ok', false, 'reason', 'A shoutout can be up to 60 seconds.');
  end if;
  perform public.zchat_wallet_lock(me);
  perform set_config('zchat.cr_msg_ok', '1', true);
  perform set_config('zchat.cr_card_ok', '1', true);
  insert into public.messages (sender_id, receiver_id, type, content, media_url)
    values (me, o.fan_id, 'text', 'zshout:' || jsonb_build_object('o', o.id, 'n', o.to_name, 'k', o.occasion, 'd', v_secs, 't', 'A shoutout for ' || o.to_name)::text, v_media)
    returning * into msg;
  perform set_config('zchat.cr_msg_ok', '', true);
  perform set_config('zchat.cr_card_ok', '', true);
  if public.zchat_coins_move(me, o.cut, 'creator_in', 'Shoutout: ' || public.zchat_cr_uname(o.fan_id), o.fan_id) is null then
    raise exception 'The shoutout could not be sent' using errcode = 'P0001';
  end if;
  update public.creator_shoutouts set status = 'delivered', message_id = msg.id, media_url = v_media, secs = v_secs, settled_at = now() where id = p_id returning * into o;
  perform public.zchat_cr_conv_touch(me, o.fan_id, 'Shoutout');
  perform public.zchat_cr_note(o.fan_id, me, 'shout_done', 'sent your shoutout for ' || o.to_name || '.', jsonb_build_object('order', o.id, 'message_id', msg.id));
  return jsonb_build_object('ok', true, 'order', to_jsonb(o), 'message', to_jsonb(msg), 'cut', o.cut);
end $$;

