create or replace function public.zchat_cr_listing_guard()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  n integer;
  u text;
  app boolean := current_user in ('authenticated', 'anon');
begin
  if app and tg_op = 'UPDATE' and (new.owner_id is distinct from old.owner_id or new.created_at is distinct from old.created_at) then
    raise exception 'This item cannot be moved' using errcode = '42501';
  end if;
  new.title := btrim(regexp_replace(left(coalesce(new.title, ''), 200), '[[:cntrl:]]+', ' ', 'g'));
  new.price_text := nullif(btrim(regexp_replace(left(coalesce(new.price_text, ''), 60), '[[:cntrl:]]+', ' ', 'g')), '');
  new.description := nullif(btrim(regexp_replace(left(coalesce(new.description, ''), 1200), '[' || chr(1) || '-' || chr(9) || chr(11) || '-' || chr(31) || ']+', ' ', 'g')), '');
  if char_length(new.title) < 1 or char_length(new.title) > 80 then
    raise exception 'Give the item a title up to 80 letters' using errcode = '22023';
  end if;
  if new.price_text is not null and char_length(new.price_text) > 24 then
    raise exception 'Keep the price short' using errcode = '22023';
  end if;
  if new.description is not null and char_length(new.description) > 600 then
    raise exception 'Keep the description under 600 letters' using errcode = '22023';
  end if;
  if jsonb_typeof(new.photos) <> 'array' or jsonb_array_length(new.photos) < 1 or jsonb_array_length(new.photos) > 6 then
    raise exception 'Add 1 to 6 photos' using errcode = '22023';
  end if;
  for u in select jsonb_array_elements_text(new.photos) loop
    if u !~ '^(https://|/)' or char_length(u) > 600 or not public.zchat_url_ok(u) then
      raise exception 'That photo cannot be used' using errcode = '22023';
    end if;
  end loop;
  new.updated_at := now();
  if tg_op = 'INSERT' then
    if app then
      new.created_at := now();
    end if;
    select count(*) into n from public.shop_listings l where l.owner_id = new.owner_id;
    if n >= 50 then
      raise exception 'Your shop can have up to 50 items' using errcode = '54000';
    end if;
    select count(*) into n from public.shop_listings l where l.owner_id = new.owner_id and l.created_at > now() - interval '1 hour';
    if n >= 20 and app then
      raise exception 'You added a lot of items in the last hour. Try again a little later' using errcode = '54000';
    end if;
    if not public.zchat_cr_active(new.owner_id) then
      raise exception 'Your account cannot add items right now' using errcode = '42501';
    end if;
  end if;
  return new;
end $$;
drop trigger if exists zchat_cr_listing_guard on public.shop_listings;
create trigger zchat_cr_listing_guard before insert or update on public.shop_listings
  for each row execute function public.zchat_cr_listing_guard();

select public.zchat_apply_session_gate();

create or replace function public.zchat_cr_tick()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  r record;
  n integer := 0;
  v_price integer;
  v_cut integer;
  v_days integer;
  st public.creator_settings;
begin
  for r in select * from public.group_entry_payments p where p.status = 'held' and p.created_at <= now() - interval '24 hours' order by p.created_at limit 300 for update skip locked loop
    begin
      perform public.zchat_wallet_lock(r.owner_id);
      if exists (select 1 from auth.users u where u.id = r.owner_id) and r.cut > 0 then
        if public.zchat_coins_move(r.owner_id, r.cut, 'creator_in', 'Entry to ' || left(coalesce(r.group_name, 'your group'), 80), r.user_id) is null then
          continue;
        end if;
      end if;
      update public.group_entry_payments set status = 'paid', settled_at = now() where id = r.id and status = 'held';
      n := n + 1;
    exception when others then
      raise notice 'zchat entry release skipped: %', sqlerrm;
    end;
  end loop;

  for r in select * from public.creator_msg_holds h where h.status = 'held' and h.created_at <= now() - interval '3 days' order by h.created_at limit 300 for update skip locked loop
    begin
      perform public.zchat_wallet_lock(r.sender_id);
      if public.zchat_coins_move(r.sender_id, r.price, 'creator_back', 'No reply: ' || public.zchat_cr_uname(r.receiver_id), r.receiver_id) is null then
        continue;
      end if;
      update public.creator_msg_holds set status = 'refunded', settled_at = now() where id = r.id and status = 'held';
      perform public.zchat_cr_note(r.sender_id, r.receiver_id, 'msg_refund', 'did not reply in 3 days, so your ' || public.zchat_cr_coins(r.price) || ' are back.', jsonb_build_object('coins', r.price));
      n := n + 1;
    exception when others then
      raise notice 'zchat paid message refund skipped: %', sqlerrm;
    end;
  end loop;

  for r in select * from public.creator_shoutouts s where s.status = 'pending' and s.due_at <= now() order by s.due_at limit 300 for update skip locked loop
    begin
      perform public.zchat_wallet_lock(r.fan_id);
      if public.zchat_coins_move(r.fan_id, r.price, 'creator_back', 'Shoutout refund: ' || public.zchat_cr_uname(r.creator_id), r.creator_id) is null then
        continue;
      end if;
      update public.creator_shoutouts set status = 'refunded', reason = 'Not sent within 7 days', settled_at = now() where id = r.id and status = 'pending';
      perform public.zchat_cr_note(r.fan_id, r.creator_id, 'shout_refund', 'did not send your shoutout in 7 days, so your ' || public.zchat_cr_coins(r.price) || ' are back.', jsonb_build_object('order', r.id, 'coins', r.price));
      n := n + 1;
    exception when others then
      raise notice 'zchat shoutout refund skipped: %', sqlerrm;
    end;
  end loop;

  for r in select * from public.creator_members m
    where m.status = 'active' and not m.cancel_at_end and m.period_end > now() and m.period_end <= now() + interval '3 days'
      and m.reminded_for is distinct from m.period_end
    order by m.period_end limit 300 for update skip locked
  loop
    begin
      select * into st from public.creator_settings s where s.user_id = r.creator_id;
      update public.creator_members set reminded_for = r.period_end where id = r.id;
      if st.member_price is not null then
        v_days := greatest(1, ceil(extract(epoch from (r.period_end - now())) / 86400.0)::integer);
        v_price := least(r.price, st.member_price);
        perform public.zchat_cr_note(r.member_id, r.creator_id, 'member_soon',
          'Your membership renews in ' || v_days || case when v_days = 1 then ' day' else ' days' end || ' for ' || public.zchat_cr_coins(v_price) || '. You can cancel any time before that.',
          jsonb_build_object('coins', v_price, 'at', r.period_end));
      end if;
      n := n + 1;
    exception when others then
      raise notice 'zchat membership reminder skipped: %', sqlerrm;
    end;
  end loop;

  for r in select * from public.creator_members m where m.status = 'active' and m.period_end <= now() order by m.period_end limit 300 for update skip locked loop
    begin
      select * into st from public.creator_settings s where s.user_id = r.creator_id;
      if r.cancel_at_end then
        perform public.zchat_cr_member_end(r.id, 'cancelled');
      elsif st.member_price is null or not public.zchat_cr_active(r.creator_id) then
        perform public.zchat_cr_member_end(r.id, 'closed');
        perform public.zchat_cr_note(r.member_id, r.creator_id, 'member_closed', 'closed their membership, so yours has ended. You were not charged again.', null);
      elsif not public.zchat_cr_active(r.member_id) or public.zchat_blocked_pair(r.member_id, r.creator_id) then
        perform public.zchat_cr_member_end(r.id, 'closed');
      else
        v_price := least(r.price, st.member_price);
        v_cut := public.zchat_cr_cut(v_price);
        perform public.zchat_cr_lock2(r.member_id, r.creator_id);
        if public.zchat_coins_move(r.member_id, -v_price, 'creator_out', 'Membership: ' || public.zchat_cr_uname(r.creator_id), r.creator_id) is null then
          perform public.zchat_cr_member_end(r.id, 'coins');
          perform public.zchat_cr_note(r.member_id, r.creator_id, 'member_ended',
            'Your membership ended because you did not have ' || public.zchat_cr_coins(v_price) || ' to renew it. You can join again any time.', jsonb_build_object('coins', v_price));
        else
          perform public.zchat_coins_move(r.creator_id, v_cut, 'creator_in', 'Membership: ' || public.zchat_cr_uname(r.member_id), r.member_id);
          update public.creator_members set price = v_price, period_end = greatest(r.period_end, now() - interval '1 day') + interval '1 month', renewals = renewals + 1, reminded_for = null
            where id = r.id;
        end if;
      end if;
      n := n + 1;
    exception when others then
      raise notice 'zchat membership renewal skipped: %', sqlerrm;
    end;
  end loop;
  return n;
end $$;

revoke execute on function public.zchat_cr_tick() from public, anon, authenticated;
grant execute on function public.zchat_cr_tick() to service_role;

do $$
begin
  if exists (select 1 from pg_namespace where nspname = 'cron')
     and exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'cron' and p.proname = 'schedule') then
    perform cron.schedule('zchat-creator', '* * * * *', 'select public.zchat_cr_tick()');
  end if;
end $$;

do $do$
declare
  t text;
begin
  if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    return;
  end if;
  foreach t in array array['creator_msg_holds', 'creator_shoutouts', 'creator_members', 'group_entry_payments', 'shop_listings', 'creator_settings'] loop
    if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end
$do$;

select public.zchat_apply_session_gate();

create or replace function public.zchat_aiphoto_take(p_user uuid, p_kind text, p_n integer, p_cap integer)
returns integer
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  cur integer;
  give integer;
begin
  if p_user is null or p_kind is null or p_kind !~ '^[a-z_]{2,32}$' or p_n is null or p_n < 1 or p_n > 500 or p_cap is null or p_cap < 1 then
    return 0;
  end if;
  insert into public.ai_usage as u (user_id, day, kind, count) values (p_user, current_date, p_kind, 0)
  on conflict (user_id, day, kind) do nothing;
  select u.count into cur from public.ai_usage u where u.user_id = p_user and u.day = current_date and u.kind = p_kind for update;
  give := greatest(0, least(p_n, p_cap - coalesce(cur, 0)));
  if give > 0 then
    update public.ai_usage u set count = u.count + give where u.user_id = p_user and u.day = current_date and u.kind = p_kind;
  end if;
  return give;
end
$$;

revoke all on function public.zchat_aiphoto_take(uuid, text, integer, integer) from public, anon, authenticated;
grant execute on function public.zchat_aiphoto_take(uuid, text, integer, integer) to service_role;

