create or replace function public.zchat_aiphoto_job(p_kind text, p_prompt text default null, p_style text default null)
returns uuid
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  words text := btrim(regexp_replace(coalesce(p_prompt, ''), '\s+', ' ', 'g'));
  cap integer;
  busy integer;
  jid uuid;
begin
  if me is null or not public.zchat_session_ok() then
    raise exception 'Please log in again.' using errcode = 'P0001';
  end if;
  if p_kind = 'sticker' then
    if p_style is null or p_style not in ('cartoon', 'sticker', 'threed', 'pixel', 'comic', 'clay', 'anime', 'watercolor') then
      raise exception 'Pick a style first.' using errcode = 'P0001';
    end if;
    if char_length(words) < 3 then
      raise exception 'Describe your sticker in a few words.' using errcode = 'P0001';
    end if;
    if char_length(words) > 200 then
      raise exception 'Keep the description under 200 letters.' using errcode = 'P0001';
    end if;
    cap := 6;
  elsif p_kind = 'restyle' then
    if p_style is null or p_style not in ('oil', 'cartoon', 'sketch', 'comic', 'watercolor') then
      raise exception 'Pick a style first.' using errcode = 'P0001';
    end if;
    words := null;
    cap := 12;
  else
    raise exception 'That is not something ZChat can make.' using errcode = 'P0001';
  end if;
  select count(*) into busy from public.ai_photo_jobs j
  where j.user_id = me and j.status in ('queued', 'working') and j.created_at > now() - interval '3 minutes';
  if busy >= 2 then
    raise exception 'Wait for the last one to finish first.' using errcode = 'P0001';
  end if;
  if public.zchat_aiphoto_take(me, 'ai_' || p_kind, 1, cap) < 1 then
    raise exception '%', case when p_kind = 'sticker' then 'You have made a lot of stickers today. More tomorrow.' else 'You have restyled a lot of photos today. More tomorrow.' end using errcode = 'P0001';
  end if;
  insert into public.ai_photo_jobs (user_id, kind, prompt, style) values (me, p_kind, nullif(words, ''), p_style) returning id into jid;
  return jid;
end
$$;

revoke all on function public.zchat_aiphoto_job(text, text, text) from public, anon;
grant execute on function public.zchat_aiphoto_job(text, text, text) to authenticated, service_role;

