create or replace function public.zchat_photo_label_key(p_user uuid, p_id bigint)
returns text
language sql
stable
security definer
set search_path to 'public'
as $$
  select case
    when m.group_id is not null then 'g:' || m.group_id::text
    else 'dm:' || least(m.sender_id::text collate "C", m.receiver_id::text collate "C") || ':' || greatest(m.sender_id::text collate "C", m.receiver_id::text collate "C")
  end
  from public.messages m
  where p_user is not null
    and m.id = p_id
    and m.type = 'image'
    and m.media_url is not null
    and not coalesce(m.deleted, false)
    and (m.expires_at is null or m.expires_at > now())
    and coalesce(m.content, '') not like 'zonce:%'
    and coalesce(m.content, '') not like 'zblur:%'
    and (m.group_id is not null or (m.sender_id is not null and m.receiver_id is not null))
    and (
      (m.group_id is null and (m.sender_id = p_user or m.receiver_id = p_user))
      or (m.group_id is not null and exists (select 1 from public.group_members gm where gm.group_id = m.group_id and gm.user_id = p_user))
    )
    and not exists (select 1 from public.hidden_messages h where h.user_id = p_user and h.message_id = m.id::text)
$$;

create or replace function public.zchat_photo_labels_todo(p_user uuid, p_ids bigint[])
returns bigint[]
language sql
stable
security definer
set search_path to 'public'
as $$
  select coalesce(array_agg(x.id order by x.ord), '{}'::bigint[])
  from (select distinct on (u.id) u.id, u.ord from unnest(coalesce(p_ids, '{}'::bigint[])) with ordinality as u(id, ord) where u.ord <= 24 order by u.id, u.ord) x
  where public.zchat_photo_label_key(p_user, x.id) is not null
    and not exists (select 1 from public.photo_labels l where l.user_id = p_user and l.message_id = x.id)
$$;

create or replace function public.zchat_photo_labels_put(p_user uuid, p_items jsonb)
returns integer
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  it jsonb;
  mid bigint;
  k text;
  words text;
  n integer := 0;
begin
  if p_user is null or p_items is null or jsonb_typeof(p_items) <> 'array' then
    return 0;
  end if;
  for it in select e.value from jsonb_array_elements(p_items) with ordinality as e(value, ord) where e.ord <= 24 loop
    if jsonb_typeof(it) <> 'object' or coalesce(it->>'id', '') !~ '^[0-9]{1,18}$' then
      continue;
    end if;
    mid := (it->>'id')::bigint;
    k := public.zchat_photo_label_key(p_user, mid);
    if k is null then
      continue;
    end if;
    words := lower(coalesce(it->>'labels', ''));
    words := regexp_replace(words, '[^a-z0-9 ]+', ' ', 'g');
    words := left(btrim(regexp_replace(words, '\s+', ' ', 'g')), 400);
    insert into public.photo_labels (user_id, message_id, chat_key, labels) values (p_user, mid, k, words)
    on conflict (user_id, message_id) do update set labels = excluded.labels, chat_key = excluded.chat_key, created_at = now();
    n := n + 1;
  end loop;
  return n;
end
$$;

revoke all on function public.zchat_photo_label_key(uuid, bigint) from public, anon, authenticated;
revoke all on function public.zchat_photo_labels_todo(uuid, bigint[]) from public, anon, authenticated;
revoke all on function public.zchat_photo_labels_put(uuid, jsonb) from public, anon, authenticated;
grant execute on function public.zchat_photo_label_key(uuid, bigint) to service_role;
grant execute on function public.zchat_photo_labels_todo(uuid, bigint[]) to service_role;
grant execute on function public.zchat_photo_labels_put(uuid, jsonb) to service_role;

create or replace function public.zchat_photo_find(p_q text, p_chat text default null, p_limit integer default 60)
returns table (message_id bigint, media_url text, created_at timestamptz, sender_id uuid, group_id uuid, peer_id uuid, chat_name text, labels text)
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  words text[];
begin
  if me is null or not public.zchat_session_ok() then
    return;
  end if;
  words := array(
    select case when char_length(w) > 3 then regexp_replace(w, 's$', '') else w end
    from regexp_split_to_table(btrim(regexp_replace(lower(coalesce(p_q, '')), '[^a-z0-9 ]+', ' ', 'g')), '\s+') as w
    where char_length(w) between 1 and 40
    limit 6
  );
  if coalesce(array_length(words, 1), 0) = 0 then
    return;
  end if;
  return query
  select l.message_id, m.media_url, m.created_at, m.sender_id, m.group_id,
    case when m.group_id is null then (case when m.sender_id = me then m.receiver_id else m.sender_id end) end,
    coalesce(g.name, p.name, '')::text,
    l.labels
  from public.photo_labels l
  join public.messages m on m.id = l.message_id
  left join public.groups g on g.id = m.group_id
  left join public.profiles p on m.group_id is null and p.id = (case when m.sender_id = me then m.receiver_id else m.sender_id end)
  where l.user_id = me
    and (p_chat is null or l.chat_key = p_chat)
    and not coalesce(m.deleted, false)
    and (m.expires_at is null or m.expires_at > now())
    and (
      (m.group_id is null and (m.sender_id = me or m.receiver_id = me))
      or (m.group_id is not null and exists (select 1 from public.group_members gm where gm.group_id = m.group_id and gm.user_id = me))
    )
    and not exists (select 1 from unnest(words) as w where (' ' || l.labels) not like ('% ' || w || '%'))
  order by m.created_at desc
  limit greatest(1, least(coalesce(p_limit, 60), 120));
end
$$;

revoke all on function public.zchat_photo_find(text, text, integer) from public, anon;
grant execute on function public.zchat_photo_find(text, text, integer) to authenticated, service_role;

