create or replace function public.zchat_character_sig(p_name text, p_tagline text, p_personality text, p_greeting text, p_avatar text)
returns text
language sql
immutable
set search_path to 'public'
as $$
  select md5(concat_ws(chr(10), btrim(coalesce(p_name, '')), btrim(coalesce(p_tagline, '')), btrim(coalesce(p_personality, '')), btrim(coalesce(p_greeting, '')), coalesce(p_avatar, '')))
$$;

create or replace function public.zchat_ai_characters_guard()
returns trigger
language plpgsql
set search_path to 'public'
as $function$
begin
  if current_user in ('authenticated', 'anon') then
    if tg_op = 'INSERT' then
      new.chats := 0;
      new.created_at := now();
      if (select count(*) from public.ai_characters c where c.owner_id = new.owner_id) >= 30 then
        raise exception 'You can make up to 30 characters. Delete one to make another.' using errcode = 'P0001';
      end if;
      new.visibility := 'private';
      new.checked_sig := null;
      new.checked_at := null;
      new.published_at := null;
      new.held := false;
      new.reports := 0;
    else
      new.chats := old.chats;
      new.owner_id := old.owner_id;
      new.created_at := old.created_at;
      new.checked_sig := old.checked_sig;
      new.checked_at := old.checked_at;
      new.held := old.held;
      new.reports := old.reports;
      new.published_at := old.published_at;
      if new.visibility = 'public' and (old.visibility <> 'public'
        or public.zchat_character_sig(new.name, new.tagline, new.personality, new.greeting, new.avatar)
           is distinct from public.zchat_character_sig(old.name, old.tagline, old.personality, old.greeting, old.avatar)) then
        if old.held then
          raise exception 'This character is hidden while reports about it are looked at.' using errcode = '42501';
        end if;
        if old.checked_sig is null or old.checked_at is null or old.checked_at < now() - interval '30 minutes'
          or old.checked_sig <> public.zchat_character_sig(new.name, new.tagline, new.personality, new.greeting, new.avatar) then
          raise exception 'Check this character again before sharing it.' using errcode = '42501';
        end if;
        if old.visibility <> 'public' then
          new.published_at := now();
        end if;
      end if;
    end if;
    new.updated_at := now();
  end if;
  return new;
end $function$;

create or replace function public.zchat_character_mark_checked(p_id uuid, p_owner uuid, p_name text, p_tagline text, p_personality text, p_greeting text, p_avatar text)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  ch record;
begin
  if p_id is null or p_owner is null then
    return jsonb_build_object('ok', false, 'reason', 'args');
  end if;
  select id, owner_id, held into ch from public.ai_characters where id = p_id for update;
  if not found or ch.owner_id <> p_owner then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  if ch.held then
    return jsonb_build_object('ok', false, 'reason', 'held');
  end if;
  update public.ai_characters
     set checked_sig = public.zchat_character_sig(p_name, p_tagline, p_personality, p_greeting, p_avatar), checked_at = now()
   where id = p_id;
  return jsonb_build_object('ok', true);
end $$;

revoke all on function public.zchat_character_mark_checked(uuid, uuid, text, text, text, text, text) from public, anon, authenticated;
grant execute on function public.zchat_character_mark_checked(uuid, uuid, text, text, text, text, text) to service_role;

