create or replace function public.zchat_character_report(p_id uuid, p_reason text)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  ch record;
  n integer;
  today integer;
  why text := left(coalesce(nullif(btrim(p_reason), ''), 'No reason given'), 200);
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'auth');
  end if;
  select id, owner_id, name, visibility, held into ch from public.ai_characters where id = p_id for update;
  if not found or (ch.visibility <> 'public' and not ch.held) then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  if ch.owner_id = me then
    return jsonb_build_object('ok', false, 'reason', 'own');
  end if;
  select count(*) into today from public.ai_character_reports r where r.reporter_id = me and r.created_at > now() - interval '1 day';
  if today >= 20 then
    return jsonb_build_object('ok', false, 'reason', 'limited');
  end if;
  insert into public.ai_character_reports (character_id, reporter_id, reason) values (p_id, me, why)
  on conflict (character_id, reporter_id) do nothing;
  if not found then
    return jsonb_build_object('ok', true, 'again', true, 'held', ch.held);
  end if;
  insert into public.report_queue (kind, target_id, reporter_id, reason, status)
  values ('character', ch.owner_id, me, left(format('AI character %s (%s): %s', ch.name, ch.id, why), 400), 'open');
  select count(*) into n from public.ai_character_reports r where r.character_id = p_id;
  update public.ai_characters
     set reports = n,
         held = held or n >= 3,
         visibility = case when n >= 3 then 'private' else visibility end
   where id = p_id;
  return jsonb_build_object('ok', true, 'held', ch.held or n >= 3);
end $$;

revoke all on function public.zchat_character_report(uuid, text) from public, anon;
grant execute on function public.zchat_character_report(uuid, text) to authenticated, service_role;

create or replace function public.zchat_character_release(p_id uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  if not public.zchat_is_admin() then
    return jsonb_build_object('ok', false, 'reason', 'admin');
  end if;
  update public.ai_characters set held = false, reports = 0 where id = p_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'gone');
  end if;
  delete from public.ai_character_reports where character_id = p_id;
  return jsonb_build_object('ok', true);
end $$;

