create or replace function public.zchat_flash_decks_guard()
returns trigger
language plpgsql
set search_path to 'public'
as $$
begin
  if current_user in ('authenticated', 'anon') then
    if tg_op = 'INSERT' then
      new.owner_id := auth.uid();
      new.created_at := now();
      if (select count(*) from public.ai_flash_decks d where d.owner_id = new.owner_id) >= 200 then
        raise exception 'You can keep up to 200 decks. Delete one to make another.' using errcode = 'P0001';
      end if;
    else
      new.owner_id := old.owner_id;
      new.created_at := old.created_at;
    end if;
    if exists (
      select 1 from jsonb_array_elements(new.cards) c
      where jsonb_typeof(c) <> 'object' or jsonb_typeof(c -> 'q') is distinct from 'string' or jsonb_typeof(c -> 'a') is distinct from 'string'
        or char_length(btrim(c ->> 'q')) not between 1 and 200 or char_length(btrim(c ->> 'a')) not between 1 and 400
    ) then
      raise exception 'Each card needs a question and an answer.' using errcode = '22023';
    end if;
    if exists (
      select 1 from jsonb_array_elements(new.known) k
      where jsonb_typeof(k) <> 'number' or (k #>> '{}')::numeric not between 0 and 59
    ) then
      raise exception 'That progress could not be saved.' using errcode = '22023';
    end if;
    new.updated_at := now();
  end if;
  return new;
end $$;

