create or replace function public.zchat_g1_hit(p_key text, p_max integer, p_secs integer)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  v integer;
begin
  if me is null then return false; end if;
  insert into public.zchat_g1_hits as h (user_id, key, win, n) values (me, p_key, now(), 1)
  on conflict (user_id, key) do update
    set n = case when h.win < now() - make_interval(secs => p_secs) then 1 else h.n + 1 end,
        win = case when h.win < now() - make_interval(secs => p_secs) then now() else h.win end
  returning n into v;
  return v <= p_max;
end $$;
revoke all on function public.zchat_g1_hit(text, integer, integer) from public, anon;

create or replace function public.zchat_g1_fnv(s text)
returns text
language plpgsql
immutable
as $$
declare
  h bigint := 2166136261;
  i integer;
begin
  for i in 1..length(s) loop
    h := ((h # ascii(substr(s, i, 1))) * 16777619) % 4294967296;
  end loop;
  return to_hex(h);
end $$;

create or replace function public.zchat_g1_int(v jsonb)
returns integer
language sql
immutable
as $$
  select case when jsonb_typeof(v) = 'number' and (v #>> '{}') ~ '^-?[0-9]{1,9}$' then (v #>> '{}')::integer else null end
$$;

create or replace function public.zchat_g1_num(v jsonb)
returns numeric
language sql
immutable
as $$
