create or replace function public.ga2__wolf_role(p_game uuid, p_idx integer)
returns text
language sql
stable
as $$
  select coalesce(public.ga2__vault(p_game) -> 'roles' ->> p_idx::text, 'villager')
$$;

create or replace function public.ga2__wolf_win(g public.ga2_games)
returns public.ga2_games
language plpgsql
as $$
declare
  alive integer[] := public.ga2__ints(g.state -> 'alive');
  roles jsonb := public.ga2__vault(g.id) -> 'roles';
  wolves integer;
  others integer;
  side text;
  x integer;
begin
  select count(*) filter (where roles ->> a::text = 'wolf'), count(*) filter (where coalesce(roles ->> a::text, '') <> 'wolf') into wolves, others from unnest(alive) as a;
  if wolves = 0 then side := 'village';
  elsif wolves >= others then side := 'wolves';
  else return g;
  end if;
  for x in select k::int from jsonb_each_text(roles) as e(k, v) where (side = 'wolves') = (v = 'wolf') loop
    g.players := public.ga2__pl_add(g.players, x, 1);
  end loop;
  g.state := g.state || jsonb_build_object('win', side, 'roles', roles);
  return public.ga2__finish(g);
end
$$;

create or replace function public.ga2__wolf_night(g public.ga2_games)
returns public.ga2_games
language plpgsql
as $$
begin
  g.phase := 'night';
  g.ends_at := now() + interval '40 seconds';
  g.state := g.state || jsonb_build_object('dawn', null, 'voted', '[]'::jsonb);
  return g;
end
$$;

create or replace function public.ga2__wolf_start(g public.ga2_games)
returns public.ga2_games
language plpgsql
as $$
declare
  live integer[] := public.ga2__shuffle(public.ga2__live(g.players));
  n integer := coalesce(array_length(live, 1), 0);
  nw integer := case when n <= 6 then 1 when n <= 10 then 2 else 3 end;
  roles jsonb := '{}'::jsonb;
  pack jsonb;
  k integer;
  role text;
begin
  for k in 1..n loop
    role := case when k <= nw then 'wolf' when k = nw + 1 then 'seer' when k = nw + 2 then 'doctor' else 'villager' end;
    roles := roles || jsonb_build_object(live[k]::text, role);
  end loop;
  pack := to_jsonb(live[1:nw]);
  perform public.ga2__vput(g.id, jsonb_build_object('roles', roles));
  for k in 1..n loop
    role := roles ->> live[k]::text;
    perform public.ga2__sec(g.id, public.ga2__uid(g.players, live[k]),
      case role
        when 'wolf' then jsonb_build_object('role', 'wolf', 'pack', pack, 'picks', '{}'::jsonb)
        when 'seer' then jsonb_build_object('role', 'seer', 'seen', '[]'::jsonb)
        when 'doctor' then jsonb_build_object('role', 'doctor', 'last', null)
        else jsonb_build_object('role', 'villager')
      end);
  end loop;
  g.state := jsonb_build_object('day', 1, 'alive', to_jsonb(public.ga2__live(g.players)), 'dawn', null, 'dusk', null, 'voted', '[]'::jsonb);
  return public.ga2__wolf_night(g);
end
$$;

create or replace function public.ga2__wolf_night_done(g public.ga2_games)
returns boolean
language plpgsql
stable
as $$
declare
  alive integer[] := public.ga2__ints(g.state -> 'alive');
  roles jsonb := public.ga2__vault(g.id) -> 'roles';
  need integer;
  have integer;
  targets integer;
begin
  select count(*) into need from unnest(alive) as a where roles ->> a::text = 'wolf';
  select count(*), count(distinct (x.answer ->> 'k')) into have, targets
  from public.ga2_answers x
  where x.game_id = g.id and x.round = g.round and x.answer ? 'k';
  if have < need or targets > 1 then return false; end if;
  if exists (select 1 from unnest(alive) as a where roles ->> a::text = 'seer')
     and not exists (select 1 from public.ga2_answers x where x.game_id = g.id and x.round = g.round and x.answer ? 's') then return false; end if;
  if exists (select 1 from unnest(alive) as a where roles ->> a::text = 'doctor')
     and not exists (select 1 from public.ga2_answers x where x.game_id = g.id and x.round = g.round and x.answer ? 'd') then return false; end if;
  return true;
end
$$;

create or replace function public.ga2__wolf_dawn(g public.ga2_games)
returns public.ga2_games
language plpgsql
as $$
declare
  alive integer[] := public.ga2__ints(g.state -> 'alive');
  roles jsonb := public.ga2__vault(g.id) -> 'roles';
  target integer;
  save integer;
  victim integer;
  doc integer;
begin
  select t.k into target from (
    select (x.answer ->> 'k')::int as k, count(*) as n
    from public.ga2_answers x where x.game_id = g.id and x.round = g.round and x.answer ? 'k'
    group by 1
  ) t where t.k = any(alive) order by t.n desc, random() limit 1;
  select (x.answer ->> 'd')::int into save from public.ga2_answers x where x.game_id = g.id and x.round = g.round and x.answer ? 'd' limit 1;
  select a into doc from unnest(alive) as a where roles ->> a::text = 'doctor' limit 1;
  if doc is not null then
    perform public.ga2__sec(g.id, public.ga2__uid(g.players, doc), jsonb_build_object('last', save));
  end if;
  if target is not null and target is distinct from save then
    victim := target;
    alive := array_remove(alive, victim);
  end if;
  g.round := g.round + 1;
  g.state := g.state || jsonb_build_object('alive', to_jsonb(alive), 'dawn', jsonb_build_object('out', victim), 'dusk', null);
  g := public.ga2__wolf_win(g);
  if g.status = 'done' then return g; end if;
  g.phase := 'day';
  g.ends_at := now() + make_interval(secs => coalesce((g.settings ->> 'talk')::int, 120));
  return g;
end
$$;

create or replace function public.ga2__wolf_vote_open(g public.ga2_games)
returns public.ga2_games
language plpgsql
as $$
begin
  g.round := g.round + 1;
  g.phase := 'vote';
  g.ends_at := now() + interval '40 seconds';
  g.state := g.state || jsonb_build_object('voted', '[]'::jsonb);
  return g;
end
$$;

create or replace function public.ga2__wolf_dusk(g public.ga2_games)
returns public.ga2_games
language plpgsql
as $$
declare
  alive integer[] := public.ga2__ints(g.state -> 'alive');
  tally jsonb;
  skips integer;
  top integer;
  second integer;
  out_ integer;
begin
  select coalesce(jsonb_agg(jsonb_build_object('i', t.v, 'n', t.n) order by t.n desc, t.v), '[]'::jsonb) into tally
  from (
    select (x.answer ->> 'v')::int as v, count(*)::int as n
    from public.ga2_answers x where x.game_id = g.id and x.round = g.round and x.answer ->> 'v' <> 'skip'
    group by 1
  ) t;
  select count(*) into skips from public.ga2_answers x where x.game_id = g.id and x.round = g.round and x.answer ->> 'v' = 'skip';
  top := coalesce((tally -> 0 ->> 'n')::int, 0);
  second := coalesce((tally -> 1 ->> 'n')::int, 0);
  if top > 0 and top > second and top > skips then
    out_ := (tally -> 0 ->> 'i')::int;
    alive := array_remove(alive, out_);
  end if;
  g.state := g.state || jsonb_build_object('alive', to_jsonb(alive), 'dusk', jsonb_build_object('out', out_, 'tally', tally, 'skip', skips));
  g := public.ga2__wolf_win(g);
  if g.status = 'done' then return g; end if;
  g.phase := 'dusk';
  g.ends_at := now() + interval '8 seconds';
  return g;
end
$$;

create or replace function public.ga2__wolf_act(g public.ga2_games, me uuid, a jsonb)
returns public.ga2_games
language plpgsql
as $$
declare
  i integer := public.ga2__pidx(g.players, me);
  alive integer[] := public.ga2__ints(g.state -> 'alive');
  roles jsonb := public.ga2__vault(g.id) -> 'roles';
  role text := coalesce(roles ->> i::text, 'villager');
  t integer;
  n integer;
  sec jsonb;
  picks jsonb;
  w integer;
  vtxt text;
begin
  if not (i = any(alive)) then raise exception 'ga2:not_player'; end if;
  if g.phase = 'night' then
    if role = 'wolf' then
      begin t := (a ->> 'k')::int; exception when others then raise exception 'ga2:bad'; end;
      if t is null or not (t = any(alive)) or roles ->> t::text = 'wolf' then raise exception 'ga2:bad'; end if;
      insert into public.ga2_answers (game_id, round, user_id, answer) values (g.id, g.round, me, jsonb_build_object('k', t))
      on conflict (game_id, round, user_id) do update set answer = excluded.answer, created_at = now();
      select coalesce(jsonb_object_agg(public.ga2__pidx(g.players, x.user_id)::text, (x.answer ->> 'k')::int), '{}'::jsonb) into picks
      from public.ga2_answers x where x.game_id = g.id and x.round = g.round and x.answer ? 'k';
      for w in select k::int from jsonb_each_text(roles) as e(k, v) where v = 'wolf' loop
        perform public.ga2__sec(g.id, public.ga2__uid(g.players, w), jsonb_build_object('picks', picks));
      end loop;
    elsif role = 'seer' then
      begin t := (a ->> 's')::int; exception when others then raise exception 'ga2:bad'; end;
      if t is null or t = i or not (t = any(alive)) then raise exception 'ga2:bad'; end if;
      insert into public.ga2_answers (game_id, round, user_id, answer) values (g.id, g.round, me, jsonb_build_object('s', t)) on conflict do nothing;
      get diagnostics n = row_count;
      if n = 0 then raise exception 'ga2:already'; end if;
      sec := public.ga2__secget(g.id, me);
      perform public.ga2__sec(g.id, me, jsonb_build_object('seen', coalesce(sec -> 'seen', '[]'::jsonb) || jsonb_build_array(jsonb_build_object('i', t, 'w', roles ->> t::text = 'wolf', 'd', coalesce((g.state ->> 'day')::int, 1)))));
    elsif role = 'doctor' then
      begin t := (a ->> 'd')::int; exception when others then raise exception 'ga2:bad'; end;
      if t is null or not (t = any(alive)) or t is not distinct from (public.ga2__secget(g.id, me) ->> 'last')::int then raise exception 'ga2:bad'; end if;
      insert into public.ga2_answers (game_id, round, user_id, answer) values (g.id, g.round, me, jsonb_build_object('d', t)) on conflict do nothing;
      get diagnostics n = row_count;
      if n = 0 then raise exception 'ga2:already'; end if;
    else
      raise exception 'ga2:bad';
    end if;
    if public.ga2__wolf_night_done(g) then g := public.ga2__wolf_dawn(g); end if;
    return g;
  elsif g.phase = 'vote' then
    vtxt := a ->> 'v';
    if vtxt is null then raise exception 'ga2:bad'; end if;
    if vtxt <> 'skip' then
      begin t := vtxt::int; exception when others then raise exception 'ga2:bad'; end;
      if t = i or not (t = any(alive)) then raise exception 'ga2:bad'; end if;
      vtxt := t::text;
    end if;
    insert into public.ga2_answers (game_id, round, user_id, answer) values (g.id, g.round, me, jsonb_build_object('v', vtxt)) on conflict do nothing;
    get diagnostics n = row_count;
    if n = 0 then raise exception 'ga2:already'; end if;
    g.state := jsonb_set(g.state, '{voted}', coalesce(g.state -> 'voted', '[]'::jsonb) || to_jsonb(i));
    if not exists (select 1 from unnest(alive) as x where not ((g.state -> 'voted') @> to_jsonb(x))) then g := public.ga2__wolf_dusk(g); end if;
    return g;
  end if;
  raise exception 'ga2:stale';
end
$$;

create or replace function public.ga2__wolf_tick(g public.ga2_games, p_force boolean)
returns public.ga2_games
language plpgsql
as $$
begin
  if not p_force and (g.ends_at is null or g.ends_at > now()) then return g; end if;
  if g.phase = 'night' then
    if p_force then return g; end if;
    return public.ga2__wolf_dawn(g);
  elsif g.phase = 'day' then
    return public.ga2__wolf_vote_open(g);
  elsif g.phase = 'vote' then
    return public.ga2__wolf_dusk(g);
  elsif g.phase = 'dusk' then
    g.round := g.round + 1;
    g.state := g.state || jsonb_build_object('day', coalesce((g.state ->> 'day')::int, 1) + 1);
    return public.ga2__wolf_night(g);
  end if;
  return g;
end
$$;

create or replace function public.ga2__wolf_leave(g public.ga2_games, me uuid)
returns public.ga2_games
language plpgsql
as $$
declare
  i integer := public.ga2__pidx(g.players, me);
  alive integer[] := public.ga2__ints(g.state -> 'alive');
begin
  if not (i = any(alive)) then return g; end if;
  alive := array_remove(alive, i);
  g.state := g.state || jsonb_build_object('alive', to_jsonb(alive));
  g := public.ga2__wolf_win(g);
  if g.status = 'done' then return g; end if;
  if g.phase = 'night' and public.ga2__wolf_night_done(g) then return public.ga2__wolf_dawn(g); end if;
  if g.phase = 'vote' and not exists (select 1 from unnest(alive) as x where not (coalesce(g.state -> 'voted', '[]'::jsonb) @> to_jsonb(x))) then return public.ga2__wolf_dusk(g); end if;
  return g;
end
$$;

create or replace function public.ga2__wolf_end(g public.ga2_games)
returns public.ga2_games
language plpgsql
as $$
begin
  g.state := g.state || jsonb_build_object('roles', public.ga2__vault(g.id) -> 'roles');
  return g;
end
$$;

