returns text
language sql
immutable
as $$
  select case p_kind
    when 'ttt' then 'Tic tac toe' when 'fade' then 'Fade tac toe' when 'c4' then 'Connect four'
    when 'gomoku' then 'Five in a row' when 'reversi' then 'Reversi' when 'dots' then 'Dots and boxes'
    when 'mancala' then 'Mancala' when 'nim' then 'Nim sticks' when 'paint' then 'Paint war'
    when 'ship' then 'Sea battle' when 'hang' then 'Hangman'
    else 'Game' end
$$;

create or replace function public.zchat_gh_kinds()
returns text[]
language sql
immutable
as $$ select array['ttt', 'fade', 'c4', 'gomoku', 'reversi', 'dots', 'mancala', 'nim', 'paint', 'ship', 'hang'] $$;

create or replace function public.zchat_gh_tour_kinds()
returns text[]
language sql
immutable
as $$ select array['ttt', 'fade', 'c4', 'gomoku', 'reversi', 'dots', 'mancala', 'nim', 'paint', 'ship'] $$;

create or replace function public.zchat_gh_ints(p jsonb)
returns int[]
language sql
immutable
as $$
  select coalesce(array_agg((e.v)::int order by e.i), '{}'::int[])
  from jsonb_array_elements_text(case when jsonb_typeof(p) = 'array' then p else '[]'::jsonb end) with ordinality as e(v, i)
$$;

create or replace function public.zchat_gh_count(b int[], v int)
returns int
language sql
immutable
as $$ select count(*)::int from unnest(b) z where z = v $$;

create or replace function public.zchat_gh_line_winner(b int[], w int, h int, need int)
returns int
language plpgsql
immutable
as $$
declare
  x int;
  y int;
  d int;
  k int;
  v int;
  nx int;
  ny int;
  ok boolean;
  dx int[] := array[1, 0, 1, 1];
  dy int[] := array[0, 1, 1, -1];
begin
  for y in 0 .. h - 1 loop
    for x in 0 .. w - 1 loop
      v := coalesce(b[y * w + x + 1], 0);
      continue when v = 0;
      for d in 1 .. 4 loop
        ok := true;
        for k in 1 .. need - 1 loop
          nx := x + dx[d] * k;
          ny := y + dy[d] * k;
          if nx < 0 or ny < 0 or nx >= w or ny >= h or coalesce(b[ny * w + nx + 1], 0) <> v then
            ok := false;
            exit;
          end if;
        end loop;
        if ok then
          return v;
        end if;
      end loop;
    end loop;
  end loop;
  if not exists (select 1 from unnest(b) z where coalesce(z, 0) = 0) then
    return 3;
  end if;
  return 0;
end $$;

create or replace function public.zchat_gh_mul32(a bigint, b bigint)
returns bigint
language sql
immutable
as $$ select ((a::numeric * b::numeric) % 4294967296::numeric)::bigint $$;

create or replace function public.zchat_gh_rng_seed(p text)
returns bigint
language plpgsql
immutable
as $$
declare
  s text := coalesce(nullif(p, ''), 'z');
  h bigint;
  i int;
begin
  h := (1779033703::bigint # length(s)::bigint) & 4294967295::bigint;
  for i in 1 .. length(s) loop
    h := public.zchat_gh_mul32(h # ascii(substr(s, i, 1))::bigint, 3432918353);
    h := ((h << 13) & 4294967295::bigint) | (h >> 19);
  end loop;
  return h;
end $$;

create or replace function public.zchat_gh_rng_next(h bigint)
returns bigint
language plpgsql
immutable
as $$
declare
  t bigint;
begin
  t := public.zchat_gh_mul32(h # (h >> 16), 2246822507);
  t := public.zchat_gh_mul32(t # (t >> 13), 3266489909);
  return t # (t >> 16);
end $$;

create or replace function public.zchat_gh_fleet(p_seed text)
returns jsonb
language plpgsql
immutable
as $$
declare
  h bigint := public.zchat_gh_rng_seed(p_seed);
  sizes int[] := array[3, 3, 2, 2];
  len int;
  tries int;
  horiz boolean;
  x int;
  y int;
  k int;
  cells int[];
  taken int[] := '{}';
  ships jsonb := '[]'::jsonb;
begin
  foreach len in array sizes loop
    for tries in 1 .. 300 loop
      h := public.zchat_gh_rng_next(h);
      horiz := (h::float8 / 4294967296::float8) < 0.5;
      h := public.zchat_gh_rng_next(h);
      x := floor((h::float8 / 4294967296::float8) * (case when horiz then 7 - len else 6 end)::float8)::int;
      h := public.zchat_gh_rng_next(h);
      y := floor((h::float8 / 4294967296::float8) * (case when horiz then 6 else 7 - len end)::float8)::int;
      cells := '{}';
      for k in 0 .. len - 1 loop
        cells := cells || (case when horiz then y * 6 + x + k else (y + k) * 6 + x end);
      end loop;
      continue when cells && taken;
      taken := taken || cells;
      ships := ships || jsonb_build_array(to_jsonb(cells));
      exit;
    end loop;
  end loop;
  return ships;
end $$;

create or replace function public.zchat_gh_fleet_cells(p_seed text)
returns int[]
language sql
immutable
as $$
  select coalesce(array_agg(c::int), '{}'::int[])
  from jsonb_array_elements(public.zchat_gh_fleet(p_seed)) s, jsonb_array_elements_text(s) c
$$;

create or replace function public.zchat_gh_paint_grow(b int[], own_in int[], mark int)
returns int[]
language plpgsql
immutable
as $$
declare
  own int[] := own_in;
  color int;
  i int;
  j int;
  x int;
  y int;
  changed boolean := true;
  nb int[];
begin
  for i in 1 .. 49 loop
    if own[i] = mark then
      color := b[i];
      exit;
    end if;
  end loop;
  if color is null then
    return own;
  end if;
  while changed loop
    changed := false;
    for i in 0 .. 48 loop
      continue when own[i + 1] <> mark;
      x := i % 7;
      y := i / 7;
      nb := array[case when x < 6 then i + 1 else -1 end, case when x > 0 then i - 1 else -1 end, case when y < 6 then i + 7 else -1 end, case when y > 0 then i - 7 else -1 end];
      foreach j in array nb loop
        if j >= 0 and own[j + 1] = 0 and b[j + 1] = color then
          own[j + 1] := mark;
          changed := true;
        end if;
      end loop;
    end loop;
  end loop;
  return own;
end $$;

create or replace function public.zchat_gh_paint_init(p_seed text)
returns jsonb
language plpgsql
immutable
as $$
declare
  h bigint := public.zchat_gh_rng_seed('paint:' || p_seed);
  b int[] := '{}';
  own int[] := array_fill(0, array[49]);
  i int;
begin
  for i in 1 .. 49 loop
    h := public.zchat_gh_rng_next(h);
    b := b || floor((h::float8 / 4294967296::float8) * 5::float8)::int;
  end loop;
  if b[49] = b[1] then
    b[49] := (b[1] + 2) % 5;
  end if;
  own[1] := 1;
  own[49] := 2;
  own := public.zchat_gh_paint_grow(b, own, 1);
  own := public.zchat_gh_paint_grow(b, own, 2);
  return jsonb_build_object('b', to_jsonb(b), 'own', to_jsonb(own));
end $$;

create or replace function public.zchat_gh_reversi_flips(b int[], i int, mark int)
returns int[]
language plpgsql
immutable
as $$
declare
  out_ int[] := '{}';
  run int[];
  x0 int := i % 6;
  y0 int := i / 6;
  other int := case when mark = 1 then 2 else 1 end;
  dxs int[] := array[1, -1, 0, 0, 1, 1, -1, -1];
  dys int[] := array[0, 0, 1, -1, 1, -1, 1, -1];
  d int;
  x int;
  y int;
begin
  if coalesce(b[i + 1], 0) <> 0 then
    return out_;
  end if;
  for d in 1 .. 8 loop
    run := '{}';
    x := x0 + dxs[d];
    y := y0 + dys[d];
    while x >= 0 and y >= 0 and x < 6 and y < 6 and b[y * 6 + x + 1] = other loop
      run := run || (y * 6 + x);
      x := x + dxs[d];
      y := y + dys[d];
    end loop;
    if coalesce(array_length(run, 1), 0) > 0 and x >= 0 and y >= 0 and x < 6 and y < 6 and b[y * 6 + x + 1] = mark then
      out_ := out_ || run;
    end if;
  end loop;
  return out_;
end $$;

create or replace function public.zchat_gh_reversi_has_move(b int[], mark int)
returns boolean
language plpgsql
immutable
as $$
declare
  i int;
begin
  for i in 0 .. 35 loop
    if coalesce(b[i + 1], 0) = 0 and coalesce(array_length(public.zchat_gh_reversi_flips(b, i, mark), 1), 0) > 0 then
      return true;
    end if;
  end loop;
  return false;
end $$;

create or replace function public.zchat_gh_err(p_text text)
returns void
language plpgsql
as $$
begin
  raise exception '%', p_text using errcode = 'ZG001';
end $$;

create or replace function public.zchat_gh_card_guard()
returns trigger
language plpgsql
set search_path to 'public'
as $$
begin
  if coalesce(current_setting('zchat.gh_ok', true), '') = '1' then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if left(coalesce(new.content, ''), 7) = 'zmatch:' or left(coalesce(new.content, ''), 6) = 'ztour:' then
      raise exception 'Matches and tournaments are made by ZChat' using errcode = '42501';
    end if;
  elsif new.content is distinct from old.content then
    if left(coalesce(new.content, ''), 7) = 'zmatch:' or left(coalesce(new.content, ''), 6) = 'ztour:'
       or ((left(coalesce(old.content, ''), 7) = 'zmatch:' or left(coalesce(old.content, ''), 6) = 'ztour:') and new.content is not null) then
      raise exception 'Matches and tournaments cannot be changed by hand' using errcode = '42501';
    end if;
  end if;
  return new;
end $$;

drop trigger if exists zchat_gh_card_guard on public.messages;
create trigger zchat_gh_card_guard before insert or update of content on public.messages
  for each row execute function public.zchat_gh_card_guard();

select public.zchat_apply_session_gate();
commit;

begin;
create or replace function public.zchat_gh_wcode(v int)
returns text
language sql
immutable
as $$ select case v when 1 then 'x' when 2 then 'o' when 3 then 'd' else null end $$;

create or replace function public.zchat_gh_one_place(b0 int[], b1 int[], mark int)
returns int
language plpgsql
immutable
as $$
declare
  i int;
  at_ int := -1;
  n int := 0;
begin
  if coalesce(array_length(b0, 1), 0) = 0 or array_length(b0, 1) is distinct from array_length(b1, 1) then
    return -1;
  end if;
  for i in 1 .. array_length(b0, 1) loop
    if b0[i] is distinct from b1[i] then
      n := n + 1;
      if b0[i] <> 0 or b1[i] <> mark then
        return -1;
      end if;
      at_ := i - 1;
    end if;
  end loop;
  if n <> 1 then
    return -1;
  end if;
  return at_;
end $$;

create or replace function public.zchat_gh_texts(p jsonb)
returns text[]
language sql
immutable
as $$
  select coalesce(array_agg(e.v order by e.i), '{}'::text[])
  from jsonb_array_elements_text(case when jsonb_typeof(p) = 'array' then p else '[]'::jsonb end) with ordinality as e(v, i)
$$;

create or replace function public.zchat_gh_initial(p_kind text, p_id uuid, p_x uuid, p_o uuid)
returns jsonb
language plpgsql
immutable
as $$
declare
  base jsonb := jsonb_build_object('g', p_kind, 'id', p_id, 'x', p_x, 'o', p_o, 'w', null, 'n', 0);
  b int[];
  pi jsonb;
begin
  if p_kind = 'ttt' then
    return base || jsonb_build_object('b', to_jsonb(array_fill(0, array[9])), 't', p_o);
  elsif p_kind = 'fade' then
    return base || jsonb_build_object('b', to_jsonb(array_fill(0, array[9])), 'qx', '[]'::jsonb, 'qo', '[]'::jsonb, 't', p_o);
  elsif p_kind = 'c4' then
    return base || jsonb_build_object('b', to_jsonb(array_fill(0, array[42])), 't', p_o);
  elsif p_kind = 'gomoku' then
    return base || jsonb_build_object('b', to_jsonb(array_fill(0, array[81])), 't', p_o);
  elsif p_kind = 'reversi' then
    b := array_fill(0, array[36]);
    b[15] := 2;
    b[16] := 1;
    b[21] := 1;
    b[22] := 2;
    return base || jsonb_build_object('b', to_jsonb(b), 't', p_o);
  elsif p_kind = 'dots' then
    return base || jsonb_build_object('h', to_jsonb(array_fill(0, array[12])), 'v', to_jsonb(array_fill(0, array[12])), 'bx', to_jsonb(array_fill(0, array[9])), 't', p_o);
  elsif p_kind = 'mancala' then
    return base || jsonb_build_object('p', '[4,4,4,4,4,4,0,4,4,4,4,4,4,0]'::jsonb, 't', p_o);
  elsif p_kind = 'nim' then
    return base || jsonb_build_object('r', '[3,5,7]'::jsonb, 't', p_o);
  elsif p_kind = 'paint' then
    pi := public.zchat_gh_paint_init(p_id::text);
    return base || jsonb_build_object('b', pi -> 'b', 'own', pi -> 'own', 't', p_o);
  elsif p_kind = 'ship' then
    return base || jsonb_build_object('sx', '[]'::jsonb, 'so', '[]'::jsonb, 't', p_o);
  elsif p_kind = 'hang' then
    return base || jsonb_build_object('gl', '[]'::jsonb);
  end if;
  return null;
end $$;

create or replace function public.zchat_gh_mancala_sow(p int[], pit int, mark int)
returns jsonb
language plpgsql
immutable
as $$
declare
  np int[] := p;
  my_store int := case when mark = 2 then 13 else 6 end;
  their_store int := case when mark = 2 then 6 else 13 end;
  lo int := case when mark = 2 then 7 else 0 end;
  stones int;
  pos int := pit;
  again boolean;
  w text := null;
  i int;
begin
  stones := np[pit + 1];
  np[pit + 1] := 0;
  while stones > 0 loop
    pos := (pos + 1) % 14;
    continue when pos = their_store;
    np[pos + 1] := np[pos + 1] + 1;
    stones := stones - 1;
  end loop;
  again := pos = my_store;
  if not again and pos >= lo and pos <= lo + 5 and np[pos + 1] = 1 and np[12 - pos + 1] > 0 then
    np[my_store + 1] := np[my_store + 1] + np[12 - pos + 1] + 1;
    np[12 - pos + 1] := 0;
    np[pos + 1] := 0;
  end if;
  if (np[1] + np[2] + np[3] + np[4] + np[5] + np[6]) = 0 or (np[8] + np[9] + np[10] + np[11] + np[12] + np[13]) = 0 then
    for i in 0 .. 5 loop
      np[7] := np[7] + np[i + 1];
      np[i + 1] := 0;
    end loop;
    for i in 7 .. 12 loop
      np[14] := np[14] + np[i + 1];
      np[i + 1] := 0;
    end loop;
    w := case when np[7] > np[14] then 'x' when np[14] > np[7] then 'o' else 'd' end;
    again := false;
  end if;
  return jsonb_build_object('p', to_jsonb(np), 'again', again, 'w', w);
end $$;

create or replace function public.zchat_gh_next(p_kind text, p_old jsonb, p_new jsonb, p_me uuid, p_sid uuid, p_secret jsonb)
returns jsonb
language plpgsql
immutable
as $$
declare
  x uuid := (p_old ->> 'x')::uuid;
  o uuid := (p_old ->> 'o')::uuid;
  mark int := case when p_me = (p_old ->> 'x')::uuid then 1 else 2 end;
  omark int;
  other uuid;
  n int := coalesce((p_old ->> 'n')::int, 0);
  b0 int[];
  b1 int[];
  b int[];
  h0 int[];
  h1 int[];
  v0 int[];
  v1 int[];
  bx int[];
  q int[];
  flips int[];
  own int[];
  own1 int[];
  i int;
  k int;
  r int;
  c int;
  cnt int;
  at_ int;
  v int;
  gained int;
  w text;
  t uuid;
  res jsonb;
  side text;
  fleet int[];
  word text;
  gl0 text[];
  gl1 text[];
  letter text;
  misses int;
  done boolean;
  my_color int;
  their_color int;
  ci int;
  bad constant text := 'That move is not allowed';
begin
  omark := case when mark = 1 then 2 else 1 end;
  other := case when mark = 1 then o else x end;
  if p_kind in ('ttt', 'gomoku', 'c4') then
    b0 := public.zchat_gh_ints(p_old -> 'b');
    b1 := public.zchat_gh_ints(p_new -> 'b');
    i := public.zchat_gh_one_place(b0, b1, mark);
    if i < 0 then
      perform public.zchat_gh_err(bad);
    end if;
    b := b0;
    b[i + 1] := mark;
    if p_kind = 'ttt' then
      v := public.zchat_gh_line_winner(b, 3, 3, 3);
      return p_old || jsonb_build_object('b', to_jsonb(b), 't', other, 'n', n + 1, 'w', public.zchat_gh_wcode(v));
    elsif p_kind = 'c4' then
      if not ((i / 7) = 5 or b0[((i / 7) + 1) * 7 + (i % 7) + 1] <> 0) then
        perform public.zchat_gh_err(bad);
      end if;
      v := public.zchat_gh_line_winner(b, 7, 6, 4);
      return p_old || jsonb_build_object('b', to_jsonb(b), 't', other, 'n', n + 1, 'w', public.zchat_gh_wcode(v));
    else
      v := public.zchat_gh_line_winner(b, 9, 9, 5);
      return p_old || jsonb_build_object('b', to_jsonb(b), 't', other, 'n', n + 1, 'w', public.zchat_gh_wcode(v), 'lastIdx', i);
    end if;
  elsif p_kind = 'fade' then
    b0 := public.zchat_gh_ints(p_old -> 'b');
    b1 := public.zchat_gh_ints(p_new -> 'b');
    if array_length(b0, 1) <> 9 or array_length(b1, 1) is distinct from 9 then
      perform public.zchat_gh_err(bad);
    end if;
    cnt := 0;
    for k in 1 .. 9 loop
      if b0[k] = 0 and b1[k] = mark then
        cnt := cnt + 1;
        at_ := k - 1;
      end if;
    end loop;
    if cnt <> 1 then
      perform public.zchat_gh_err(bad);
    end if;
    q := public.zchat_gh_ints(p_old -> (case when mark = 1 then 'qx' else 'qo' end)) || at_;
    b := b0;
    b[at_ + 1] := mark;
    if array_length(q, 1) > 3 then
      b[q[1] + 1] := 0;
      q := q[2:];
    end if;
    if b is distinct from b1 then
      perform public.zchat_gh_err(bad);
    end if;
    v := public.zchat_gh_line_winner(b, 3, 3, 3);
    w := case when v in (1, 2) then public.zchat_gh_wcode(v) when n + 1 >= 60 then 'd' else null end;
    return p_old || jsonb_build_object('b', to_jsonb(b), (case when mark = 1 then 'qx' else 'qo' end), to_jsonb(q), 't', other, 'n', n + 1, 'w', w);
  elsif p_kind = 'reversi' then
    b0 := public.zchat_gh_ints(p_old -> 'b');
    b1 := public.zchat_gh_ints(p_new -> 'b');
    if array_length(b0, 1) <> 36 or array_length(b1, 1) is distinct from 36 then
      perform public.zchat_gh_err(bad);
    end if;
    cnt := 0;
    for k in 1 .. 36 loop
      if b0[k] = 0 and b1[k] <> 0 then
        cnt := cnt + 1;
        at_ := k - 1;
      end if;
    end loop;
    if cnt <> 1 or b1[at_ + 1] <> mark then
      perform public.zchat_gh_err(bad);
    end if;
    flips := public.zchat_gh_reversi_flips(b0, at_, mark);
    if coalesce(array_length(flips, 1), 0) = 0 then
      perform public.zchat_gh_err(bad);
    end if;
    b := b0;
    b[at_ + 1] := mark;
    foreach k in array flips loop
      b[k + 1] := mark;
    end loop;
    if b is distinct from b1 then
      perform public.zchat_gh_err(bad);
    end if;
    t := other;
    w := null;
    if not public.zchat_gh_reversi_has_move(b, omark) then
      if public.zchat_gh_reversi_has_move(b, mark) then
        t := p_me;
      else
        w := case when public.zchat_gh_count(b, 1) > public.zchat_gh_count(b, 2) then 'x' when public.zchat_gh_count(b, 2) > public.zchat_gh_count(b, 1) then 'o' else 'd' end;
      end if;
    end if;
    return p_old || jsonb_build_object('b', to_jsonb(b), 't', t, 'n', n + 1, 'w', w, 'lastIdx', at_);
  elsif p_kind = 'dots' then
    h0 := public.zchat_gh_ints(p_old -> 'h');
    h1 := public.zchat_gh_ints(p_new -> 'h');
    v0 := public.zchat_gh_ints(p_old -> 'v');
    v1 := public.zchat_gh_ints(p_new -> 'v');
    if array_length(h1, 1) is distinct from 12 or array_length(v1, 1) is distinct from 12 then
      perform public.zchat_gh_err(bad);
    end if;
    cnt := 0;
    for k in 1 .. 12 loop
      if h0[k] is distinct from h1[k] then
        if h0[k] <> 0 or h1[k] <> mark then
          perform public.zchat_gh_err(bad);
        end if;
        cnt := cnt + 1;
      end if;
      if v0[k] is distinct from v1[k] then
        if v0[k] <> 0 or v1[k] <> mark then
          perform public.zchat_gh_err(bad);
        end if;
        cnt := cnt + 1;
      end if;
    end loop;
    if cnt <> 1 then
      perform public.zchat_gh_err(bad);
    end if;
    bx := public.zchat_gh_ints(p_old -> 'bx');
    gained := 0;
    for r in 0 .. 2 loop
      for c in 0 .. 2 loop
        continue when bx[r * 3 + c + 1] <> 0;
        if h1[r * 3 + c + 1] <> 0 and h1[(r + 1) * 3 + c + 1] <> 0 and v1[r * 4 + c + 1] <> 0 and v1[r * 4 + c + 2] <> 0 then
          bx[r * 3 + c + 1] := mark;
          gained := gained + 1;
        end if;
      end loop;
    end loop;
    w := null;
    if 0 <> all(h1) and 0 <> all(v1) then
      w := case when public.zchat_gh_count(bx, 1) > public.zchat_gh_count(bx, 2) then 'x' when public.zchat_gh_count(bx, 2) > public.zchat_gh_count(bx, 1) then 'o' else 'd' end;
    end if;
    return p_old || jsonb_build_object('h', to_jsonb(h1), 'v', to_jsonb(v1), 'bx', to_jsonb(bx), 't', case when gained > 0 then p_me else other end, 'n', n + 1, 'w', w);
  elsif p_kind = 'mancala' then
    b0 := public.zchat_gh_ints(p_old -> 'p');
    b1 := public.zchat_gh_ints(p_new -> 'p');
    if array_length(b0, 1) <> 14 or array_length(b1, 1) is distinct from 14 then
      perform public.zchat_gh_err(bad);
    end if;
    for k in (case when mark = 2 then 7 else 0 end) .. (case when mark = 2 then 12 else 5 end) loop
      continue when b0[k + 1] <= 0;
      res := public.zchat_gh_mancala_sow(b0, k, mark);
      if public.zchat_gh_ints(res -> 'p') = b1 then
        w := res ->> 'w';
        t := case when w is not null then (p_old ->> 't')::uuid when (res ->> 'again')::boolean then p_me else other end;
        return p_old || jsonb_build_object('p', res -> 'p', 't', t, 'n', n + 1, 'w', w);
      end if;
    end loop;
    perform public.zchat_gh_err(bad);
  elsif p_kind = 'nim' then
    b0 := public.zchat_gh_ints(p_old -> 'r');
    b1 := public.zchat_gh_ints(p_new -> 'r');
    if array_length(b0, 1) <> 3 or array_length(b1, 1) is distinct from 3 then
      perform public.zchat_gh_err(bad);
    end if;
    cnt := 0;
    for k in 1 .. 3 loop
      if b0[k] is distinct from b1[k] then
        if b1[k] < 0 or b1[k] >= b0[k] then
          perform public.zchat_gh_err(bad);
        end if;
        cnt := cnt + 1;
      end if;
    end loop;
    if cnt <> 1 then
      perform public.zchat_gh_err(bad);
    end if;
    w := case when (b1[1] + b1[2] + b1[3]) = 0 then (case when mark = 1 then 'x' else 'o' end) else null end;
    return p_old || jsonb_build_object('r', to_jsonb(b1), 't', other, 'n', n + 1, 'w', w);
  elsif p_kind = 'paint' then
    b0 := public.zchat_gh_ints(p_old -> 'b');
    b1 := public.zchat_gh_ints(p_new -> 'b');
    own := public.zchat_gh_ints(p_old -> 'own');
    own1 := public.zchat_gh_ints(p_new -> 'own');
    if array_length(b0, 1) <> 49 or array_length(own, 1) <> 49 then
      perform public.zchat_gh_err(bad);
    end if;
    my_color := b0[array_position(own, mark)];
    their_color := b0[array_position(own, omark)];
    for ci in 0 .. 4 loop
      continue when ci = my_color or ci = their_color;
      b := b0;
      for k in 1 .. 49 loop
        if own[k] = mark then
          b[k] := ci;
        end if;
      end loop;
      q := public.zchat_gh_paint_grow(b, own, mark);
      if b = b1 and q = own1 then
        cnt := public.zchat_gh_count(q, 1);
        k := public.zchat_gh_count(q, 2);
        w := case when cnt > 24 then 'x' when k > 24 then 'o'
                  when not (0 = any(q)) or n + 1 >= 90 then (case when cnt > k then 'x' when k > cnt then 'o' else 'd' end)
                  else null end;
        return p_old || jsonb_build_object('b', to_jsonb(b), 'own', to_jsonb(q), 't', other, 'n', n + 1, 'w', w);
      end if;
    end loop;
    perform public.zchat_gh_err(bad);
  elsif p_kind = 'ship' then
    side := case when mark = 1 then 'sx' else 'so' end;
    b0 := public.zchat_gh_ints(p_old -> side);
    b1 := public.zchat_gh_ints(p_new -> side);
    if coalesce(array_length(b1, 1), 0) <> coalesce(array_length(b0, 1), 0) + 1 then
      perform public.zchat_gh_err(bad);
    end if;
    i := b1[array_length(b1, 1)];
    if i < 0 or i > 35 or i = any(b0) or (coalesce(array_length(b0, 1), 0) > 0 and b1[1:array_length(b0, 1)] is distinct from b0) then
      perform public.zchat_gh_err(bad);
    end if;
    fleet := public.zchat_gh_fleet_cells(p_sid::text || ':' || (case when mark = 1 then 'o' else 'x' end));
    done := fleet <@ b1;
    w := case when done then (case when mark = 1 then 'x' else 'o' end) else null end;
    t := case when done then (p_old ->> 't')::uuid when i = any(fleet) then p_me else other end;
    return p_old || jsonb_build_object(side, to_jsonb(b1), 't', t, 'n', n + 1, 'w', w, 'lastIdx', i);
  elsif p_kind = 'hang' then
    if p_me <> o then
      perform public.zchat_gh_err(bad);
    end if;
    word := lower(coalesce(p_secret ->> 'sw', ''));
    gl0 := public.zchat_gh_texts(p_old -> 'gl');
    gl1 := public.zchat_gh_texts(p_new -> 'gl');
    if coalesce(array_length(gl1, 1), 0) <> coalesce(array_length(gl0, 1), 0) + 1 or word = '' then
      perform public.zchat_gh_err(bad);
    end if;
    letter := gl1[array_length(gl1, 1)];
    if letter !~ '^[a-z]$' or letter = any(gl0) or (coalesce(array_length(gl0, 1), 0) > 0 and gl1[1:array_length(gl0, 1)] is distinct from gl0) then
      perform public.zchat_gh_err(bad);
    end if;
    done := not exists (select 1 from regexp_split_to_table(word, '') ch where not (ch = any(gl1)));
    select count(*) into misses from unnest(gl1) l where position(l in word) = 0;
    w := case when done then 'o' when misses >= 6 then 'x' else null end;
    return p_old || jsonb_build_object('gl', to_jsonb(gl1), 'n', n + 1, 'w', w);
  end if;
  perform public.zchat_gh_err('That game cannot be played here');
  return null;
end $$;

create or replace function public.zchat_gh_public(p_kind text, p_state jsonb, p_sid uuid, p_secret jsonb)
returns jsonb
language plpgsql
immutable
as $$
declare
  fx jsonb;
  fo jsonb;
  sx int[];
  so int[];
  cx int[];
  co int[];
  kx int[] := '{}';
  ko int[] := '{}';
  ship jsonb;
  cells int[];
  word text;
  gl text[];
  masked text := '';
  i int;
  ch text;
begin
  if p_kind = 'ship' then
    fx := public.zchat_gh_fleet(p_sid::text || ':x');
    fo := public.zchat_gh_fleet(p_sid::text || ':o');
    sx := public.zchat_gh_ints(p_state -> 'sx');
    so := public.zchat_gh_ints(p_state -> 'so');
    select coalesce(array_agg(c::int), '{}') into cx from jsonb_array_elements(fx) s, jsonb_array_elements_text(s) c;
    select coalesce(array_agg(c::int), '{}') into co from jsonb_array_elements(fo) s, jsonb_array_elements_text(s) c;
    for ship in select * from jsonb_array_elements(fo) loop
      cells := public.zchat_gh_ints(ship);
      if cells <@ sx then kx := kx || cells; end if;
    end loop;
    for ship in select * from jsonb_array_elements(fx) loop
      cells := public.zchat_gh_ints(ship);
      if cells <@ so then ko := ko || cells; end if;
    end loop;
    return p_state || jsonb_build_object(
      'hx', to_jsonb(array(select s from unnest(sx) s where s = any(co))),
      'ho', to_jsonb(array(select s from unnest(so) s where s = any(cx))),
      'kx', to_jsonb(kx), 'ko', to_jsonb(ko),
      'fx', case when p_state ->> 'w' is not null then to_jsonb(cx) else null end,
      'fo', case when p_state ->> 'w' is not null then to_jsonb(co) else null end);
  elsif p_kind = 'hang' then
    word := lower(coalesce(p_secret ->> 'sw', ''));
    if p_state ->> 'w' is not null then
      return p_state || jsonb_build_object('sw', word);
    end if;
    gl := public.zchat_gh_texts(p_state -> 'gl');
    for i in 1 .. length(word) loop
      ch := substr(word, i, 1);
      masked := masked || case when ch = any(gl) then ch else '_' end;
    end loop;
    return p_state || jsonb_build_object('sw', masked);
  end if;
  return p_state;
end $$;
commit;

begin;
create or replace function public.zchat_gh_card(p_game public.zchat_gh_games)
returns text
language plpgsql
stable
set search_path to 'public'
as $$
declare
  rd jsonb := null;
  t public.zchat_gh_tours;
begin
  if p_game.tour_id is not null then
    select * into t from public.zchat_gh_tours where id = p_game.tour_id;
    if found and t.bracket is not null then
      rd := jsonb_build_array(p_game.slot / 100, jsonb_array_length(t.bracket -> 'r'),
        coalesce((t.bracket -> 'r' -> (p_game.slot / 100) -> (p_game.slot % 100) ->> 'd')::int, 0));
    end if;
  end if;
  return 'zmatch:' || jsonb_build_object(
    't', public.zchat_gh_title(p_game.kind) || ' match on ZChat. Open ZChat to play or watch.',
    'm', public.zchat_gh_public(p_game.kind, p_game.state, p_game.sid, p_game.secret),
    'tr', p_game.tour_id,
    'rd', rd)::text;
end $$;

create or replace function public.zchat_gh_put_card(p_game public.zchat_gh_games)
returns void
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  if p_game.msg_id is null then
    return;
  end if;
  perform set_config('zchat.gh_ok', '1', true);
  perform set_config('zchat.role_ok', '1', true);
  update public.messages set content = public.zchat_gh_card(p_game)
  where id = p_game.msg_id and coalesce(deleted, false) = false;
  perform set_config('zchat.gh_ok', '', true);
  perform set_config('zchat.role_ok', '', true);
end $$;

drop function if exists public.zchat_gh_spawn(uuid, text, uuid, uuid, uuid, jsonb, uuid, int);
create or replace function public.zchat_gh_spawn(p_group uuid, p_kind text, p_x uuid, p_o uuid, p_by uuid, p_secret jsonb, p_tour uuid, p_slot int, p_id uuid default null)
returns public.zchat_gh_games
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  g public.zchat_gh_games;
  m public.messages;
  gid uuid := coalesce(p_id, gen_random_uuid());
begin
  insert into public.zchat_gh_games (id, group_id, kind, x, o, state, secret, tour_id, slot, created_by)
  values (gid, p_group, p_kind, p_x, p_o, public.zchat_gh_initial(p_kind, gid, p_x, p_o), p_secret, p_tour, p_slot, p_by)
  returning * into g;
  perform set_config('zchat.gh_ok', '1', true);
  perform set_config('zchat.role_ok', '1', true);
  insert into public.messages (sender_id, receiver_id, group_id, type, content, client_id)
  values (p_by, null, p_group, 'text', public.zchat_gh_card(g), 'gh:' || gid::text)
  returning * into m;
  perform set_config('zchat.gh_ok', '', true);
  perform set_config('zchat.role_ok', '', true);
  update public.zchat_gh_games set msg_id = m.id where id = gid returning * into g;
  return g;
end $$;

drop function if exists public.zchat_gh_new(uuid, text, uuid, text);
create or replace function public.zchat_gh_new(p_group uuid, p_kind text, p_other uuid, p_word text default null, p_id uuid default null)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  g public.zchat_gh_games;
  n int;
  word text := lower(btrim(coalesce(p_word, '')));
begin
  if me is null then
    perform public.zchat_gh_err('Log in first');
  end if;
  if not public.zchat_session_ok() then
    perform public.zchat_gh_err('Approve this login on your other device first');
  end if;
  if p_id is not null then
    select * into g from public.zchat_gh_games where id = p_id;
    if found then
      if g.created_by is distinct from me or g.group_id is distinct from p_group then
        perform public.zchat_gh_err('That is not possible');
      end if;
      return jsonb_build_object('ok', true, 'id', g.id, 'sec', jsonb_build_object('sid', g.sid, 'sw', g.secret ->> 'sw'),
        'msg', (select to_jsonb(m) from public.messages m where m.id = g.msg_id));
    end if;
  end if;
  if p_kind is null or not (p_kind = any(public.zchat_gh_kinds())) then
    perform public.zchat_gh_err('That game cannot be played in groups yet');
  end if;
  if p_group is null or not public.is_group_member_unmuted(p_group, me) or not public.zchat_can_post_group(p_group, 'text') then
    perform public.zchat_gh_err('You cannot post in this group right now');
  end if;
  if p_other is null or p_other = me or not exists (select 1 from public.group_members gm where gm.group_id = p_group and gm.user_id = p_other) then
    perform public.zchat_gh_err('Pick someone who is in this group');
  end if;
  if exists (select 1 from public.profiles p where p.id = p_other and (coalesce(p.is_bot, false) or coalesce(p.is_deleted, false))) then
    perform public.zchat_gh_err('Pick someone who is in this group');
  end if;
  if public.is_blocked_either_way(me, p_other) then
    perform public.zchat_gh_err('You cannot play with this person');
  end if;
  if p_kind = 'hang' and word !~ '^[a-z]{3,12}$' then
    perform public.zchat_gh_err('Pick a word of 3 to 12 letters');
  end if;
  select count(*) into n from public.zchat_gh_games where created_by = me and created_at > now() - interval '1 hour';
  if n >= 30 then
    perform public.zchat_gh_err('You started a lot of games. Try again in a little while');
  end if;
  select count(*) into n from public.zchat_gh_games
  where group_id = p_group and ended_at is null and tour_id is null
    and ((x = me and o = p_other) or (x = p_other and o = me));
  if n >= 3 then
    perform public.zchat_gh_err('Finish one of your games with them first');
  end if;
  g := public.zchat_gh_spawn(p_group, p_kind, me, p_other, me, case when p_kind = 'hang' then jsonb_build_object('sw', word) else null end, null, null, p_id);
  return jsonb_build_object('ok', true, 'id', g.id, 'sec', jsonb_build_object('sid', g.sid, 'sw', g.secret ->> 'sw'),
    'msg', (select to_jsonb(m) from public.messages m where m.id = g.msg_id));
end $$;

create or replace function public.zchat_gh_secret(p_game uuid)
returns jsonb
language plpgsql
security definer
stable
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  g public.zchat_gh_games;
begin
  select * into g from public.zchat_gh_games where id = p_game;
  if not found or me is null or me not in (g.x, g.o) or not public.zchat_session_ok() then
    perform public.zchat_gh_err('Only the two players can see this');
  end if;
  return jsonb_build_object('sid', g.sid, 'sw', g.secret ->> 'sw');
end $$;

create or replace function public.zchat_gh_finish(p_game uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  g public.zchat_gh_games;
begin
  select * into g from public.zchat_gh_games where id = p_game;
  if not found or g.tour_id is null then
    return '[]'::jsonb;
  end if;
  return public.zchat_gh_tour_after(p_game);
end $$;

create or replace function public.zchat_gh_move(p_game uuid, p_state jsonb)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  g public.zchat_gh_games;
  nx jsonb;
  made jsonb := '[]'::jsonb;
begin
  if me is null or not public.zchat_session_ok() then
    perform public.zchat_gh_err('Log in first');
  end if;
  select * into g from public.zchat_gh_games where id = p_game for update;
  if not found then
    perform public.zchat_gh_err('This game is gone');
  end if;
  if me not in (g.x, g.o) then
    perform public.zchat_gh_err('Only the two players can move');
  end if;
  if not exists (select 1 from public.group_members gm where gm.group_id = g.group_id and gm.user_id = me) then
    perform public.zchat_gh_err('You are not in this group anymore');
  end if;
  if g.ended_at is not null or (g.state ->> 'w') is not null then
    perform public.zchat_gh_err('This game is over');
  end if;
  if jsonb_typeof(p_state) is distinct from 'object' or length(p_state::text) > 8000 then
    perform public.zchat_gh_err('That move is not allowed');
  end if;
  if coalesce((p_state ->> 'n')::int, -1) <> coalesce((g.state ->> 'n')::int, 0) + 1 then
    perform public.zchat_gh_err('The board changed. Look again and make your move');
  end if;
  if g.kind = 'hang' then
    if me <> g.o then
      perform public.zchat_gh_err('It is not your turn');
    end if;
  elsif (g.state ->> 't') is distinct from me::text then
    perform public.zchat_gh_err('It is not your turn');
  end if;
  nx := public.zchat_gh_next(g.kind, g.state, p_state, me, g.sid, g.secret);
  update public.zchat_gh_games
  set state = nx, updated_at = now(), ended_at = case when nx ->> 'w' is not null then now() else null end
  where id = g.id
  returning * into g;
  perform public.zchat_gh_put_card(g);
  if g.ended_at is not null then
    made := public.zchat_gh_finish(g.id);
  end if;
  return jsonb_build_object('ok', true, 'm', public.zchat_gh_public(g.kind, g.state, g.sid, g.secret), 'made', made);
end $$;

create or replace function public.zchat_gh_end(p_game uuid, p_mode text)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  g public.zchat_gh_games;
  foe uuid;
  waiting uuid;
  nx jsonb;
  made jsonb := '[]'::jsonb;
begin
  if me is null or not public.zchat_session_ok() then
    perform public.zchat_gh_err('Log in first');
  end if;
  select * into g from public.zchat_gh_games where id = p_game for update;
  if not found or me not in (g.x, g.o) then
    perform public.zchat_gh_err('Only the two players can do this');
  end if;
  if g.ended_at is not null or (g.state ->> 'w') is not null then
    perform public.zchat_gh_err('This game is over');
  end if;
  foe := case when me = g.x then g.o else g.x end;
  if p_mode = 'claim' then
    if exists (select 1 from public.group_members gm where gm.group_id = g.group_id and gm.user_id = foe) then
      waiting := case when g.kind = 'hang' then g.o else (g.state ->> 't')::uuid end;
      if waiting is distinct from foe then
        perform public.zchat_gh_err('It is your turn, so there is nothing to claim');
      end if;
      if g.updated_at > now() - interval '24 hours' then
        perform public.zchat_gh_err('You can claim the win when they have not played for a day');
      end if;
    end if;
    nx := g.state || jsonb_build_object('w', case when me = g.x then 'x' else 'o' end, 'n', coalesce((g.state ->> 'n')::int, 0) + 1, 'to', true);
  elsif p_mode = 'resign' then
    nx := g.state || jsonb_build_object('w', case when me = g.x then 'o' else 'x' end, 'n', coalesce((g.state ->> 'n')::int, 0) + 1, 'gu', me);
  else
    perform public.zchat_gh_err('That is not possible');
  end if;
  update public.zchat_gh_games set state = nx, updated_at = now(), ended_at = now() where id = g.id returning * into g;
  perform public.zchat_gh_put_card(g);
  made := public.zchat_gh_finish(g.id);
  return jsonb_build_object('ok', true, 'm', public.zchat_gh_public(g.kind, g.state, g.sid, g.secret), 'made', made);
end $$;

create or replace function public.zchat_gh_live(p_group uuid)
returns jsonb
language plpgsql
security definer
stable
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
begin
  if me is null or not public.zchat_session_ok() or not exists (select 1 from public.group_members gm where gm.group_id = p_group and gm.user_id = me) then
    perform public.zchat_gh_err('Only people in this group can see its games');
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', g.id, 'g', g.kind, 'x', g.x, 'o', g.o, 't', g.state ->> 't', 'n', (g.state ->> 'n')::int,
      'msg', g.msg_id, 'tr', g.tour_id, 'at', g.updated_at) order by g.updated_at desc)
    from (select * from public.zchat_gh_games where group_id = p_group and ended_at is null order by updated_at desc limit 40) g
  ), '[]'::jsonb);
end $$;

create or replace function public.zchat_gh_get(p_game uuid)
returns jsonb
language plpgsql
security definer
stable
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  g public.zchat_gh_games;
begin
  select * into g from public.zchat_gh_games where id = p_game;
  if not found or me is null or not public.zchat_session_ok() or not exists (select 1 from public.group_members gm where gm.group_id = g.group_id and gm.user_id = me) then
    perform public.zchat_gh_err('Only people in this group can watch');
  end if;
  return jsonb_build_object('id', g.id, 'msg', g.msg_id, 'group', g.group_id, 'card', public.zchat_gh_card(g), 'at', g.updated_at);
end $$;

revoke all on function public.zchat_gh_put_card(public.zchat_gh_games) from public, anon, authenticated;
revoke all on function public.zchat_gh_spawn(uuid, text, uuid, uuid, uuid, jsonb, uuid, int, uuid) from public, anon, authenticated;
revoke all on function public.zchat_gh_finish(uuid) from public, anon, authenticated;
revoke all on function public.zchat_gh_card(public.zchat_gh_games) from public, anon, authenticated;
