create or replace function public.zchat_gh_seed_order(p_size int)
returns int[]
language plpgsql
immutable
as $$
declare
  ord int[] := array[1, 2];
  nxt int[];
  s int;
  len int;
begin
  if p_size <= 1 then
    return array[1];
  end if;
  while array_length(ord, 1) < p_size loop
    len := array_length(ord, 1) * 2;
    nxt := '{}';
    foreach s in array ord loop
      nxt := nxt || s || (len + 1 - s);
    end loop;
    ord := nxt;
  end loop;
  return ord;
end $$;

create or replace function public.zchat_gh_tour_card(p_tour public.zchat_gh_tours)
returns text
language sql
stable
as $$
  select 'ztour:' || jsonb_build_object(
    't', public.zchat_gh_title(p_tour.kind) || ' tournament on ZChat. Open ZChat to join or watch.',
    'i', p_tour.id, 'g', p_tour.kind, 's', p_tour.status, 'by', p_tour.created_by,
    'p', to_jsonb(p_tour.players), 'r', coalesce(p_tour.bracket -> 'r', '[]'::jsonb), 'w', p_tour.winner,
    'at', (extract(epoch from p_tour.updated_at) * 1000)::bigint)::text
$$;

create or replace function public.zchat_gh_tour_put(p_tour uuid)
returns void
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  t public.zchat_gh_tours;
begin
  update public.zchat_gh_tours set updated_at = clock_timestamp() where id = p_tour returning * into t;
  if t.msg_id is null then
    return;
  end if;
  perform set_config('zchat.gh_ok', '1', true);
  perform set_config('zchat.role_ok', '1', true);
  update public.messages set content = public.zchat_gh_tour_card(t) where id = t.msg_id and coalesce(deleted, false) = false;
  perform set_config('zchat.gh_ok', '', true);
  perform set_config('zchat.role_ok', '', true);
end $$;

create or replace function public.zchat_gh_tour_fill(p_tour uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  t public.zchat_gh_tours;
  br jsonb;
  made jsonb := '[]'::jsonb;
  rounds int;
  r int;
  k int;
  slot jsonb;
  a uuid;
  b uuid;
  win uuid;
  g public.zchat_gh_games;
  changed boolean := true;
  ina boolean;
  inb boolean;
begin
  select * into t from public.zchat_gh_tours where id = p_tour;
  br := t.bracket;
  rounds := jsonb_array_length(br -> 'r');
  while changed loop
    changed := false;
    for r in 0 .. rounds - 1 loop
      for k in 0 .. jsonb_array_length(br -> 'r' -> r) - 1 loop
        slot := br -> 'r' -> r -> k;
        a := public.zchat_try_uuid(slot ->> 'a');
        b := public.zchat_try_uuid(slot ->> 'b');
        win := public.zchat_try_uuid(slot ->> 'w');
        if win is not null and r < rounds - 1 then
          if br -> 'r' -> (r + 1) -> (k / 2) ->> (case when k % 2 = 0 then 'a' else 'b' end) is null then
            br := jsonb_set(br, array['r', (r + 1)::text, (k / 2)::text, case when k % 2 = 0 then 'a' else 'b' end], to_jsonb(win));
            changed := true;
          end if;
        end if;
        continue when win is not null or (slot ->> 'm') is not null or a is null or b is null;
        ina := exists (select 1 from public.group_members gm where gm.group_id = t.group_id and gm.user_id = a);
        inb := exists (select 1 from public.group_members gm where gm.group_id = t.group_id and gm.user_id = b);
        if not ina or not inb then
          br := jsonb_set(br, array['r', r::text, k::text, 'w'], to_jsonb(case when ina then a when inb then b else a end));
          br := jsonb_set(br, array['r', r::text, k::text, 'f'], 'true'::jsonb);
          changed := true;
          continue;
        end if;
        g := public.zchat_gh_spawn(t.group_id, t.kind, a, b, a, null, t.id, r * 100 + k);
        br := jsonb_set(br, array['r', r::text, k::text, 'm'], to_jsonb(g.id));
        made := made || jsonb_build_array(jsonb_build_object('id', g.id, 'x', a, 'o', b, 'g', t.kind, 'msg', g.msg_id));
        changed := true;
      end loop;
    end loop;
  end loop;
  win := public.zchat_try_uuid(br -> 'r' -> (rounds - 1) -> 0 ->> 'w');
  if win is not null then
    update public.zchat_gh_tours set bracket = br, status = 'done', winner = win, ended_at = now() where id = p_tour;
  else
    update public.zchat_gh_tours set bracket = br where id = p_tour;
  end if;
  return made;
end $$;

create or replace function public.zchat_gh_tour_after(p_game uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  g public.zchat_gh_games;
  t public.zchat_gh_tours;
  br jsonb;
  r int;
  k int;
  slot jsonb;
  d int;
  winner uuid;
  ng public.zchat_gh_games;
  made jsonb := '[]'::jsonb;
  found_ boolean := false;
begin
  select * into g from public.zchat_gh_games where id = p_game;
  if not found or g.tour_id is null then
    return made;
  end if;
  select * into t from public.zchat_gh_tours where id = g.tour_id for update;
  if not found or t.status <> 'live' or t.bracket is null then
    return made;
  end if;
  br := t.bracket;
  r := g.slot / 100;
  k := g.slot % 100;
  slot := br -> 'r' -> r -> k;
  if slot is null or (slot ->> 'm') is distinct from g.id::text or (slot ->> 'w') is not null then
    return made;
  end if;
  if g.state ->> 'w' = 'd' then
    d := coalesce((slot ->> 'd')::int, 0) + 1;
    br := jsonb_set(br, array['r', r::text, k::text, 'd'], to_jsonb(d));
    if d < 3 then
      update public.zchat_gh_tours set bracket = br where id = t.id;
      ng := public.zchat_gh_spawn(g.group_id, g.kind, g.o, g.x, g.o, null, t.id, g.slot);
      br := jsonb_set(br, array['r', r::text, k::text, 'm'], to_jsonb(ng.id));
      update public.zchat_gh_tours set bracket = br where id = t.id;
      perform public.zchat_gh_tour_put(t.id);
      return jsonb_build_array(jsonb_build_object('id', ng.id, 'x', ng.x, 'o', ng.o, 'g', ng.kind, 'msg', ng.msg_id, 'again', d));
    end if;
    winner := case when random() < 0.5 then g.x else g.o end;
    br := jsonb_set(br, array['r', r::text, k::text, 'c'], 'true'::jsonb);
  else
    winner := case when g.state ->> 'w' = 'x' then g.x else g.o end;
  end if;
  br := jsonb_set(br, array['r', r::text, k::text, 'w'], to_jsonb(winner));
  update public.zchat_gh_tours set bracket = br where id = t.id;
  made := public.zchat_gh_tour_fill(t.id);
  perform public.zchat_gh_tour_put(t.id);
  return made;
end $$;

drop function if exists public.zchat_gh_tour_new(uuid, text);
create or replace function public.zchat_gh_tour_new(p_group uuid, p_kind text, p_id uuid default null)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  t public.zchat_gh_tours;
  m public.messages;
  n int;
  r record;
begin
  if me is null or not public.zchat_session_ok() then
    perform public.zchat_gh_err('Log in first');
  end if;
  if p_id is not null then
    select * into t from public.zchat_gh_tours where id = p_id;
    if found then
      if t.created_by is distinct from me or t.group_id is distinct from p_group then
        perform public.zchat_gh_err('That is not possible');
      end if;
      return jsonb_build_object('ok', true, 'id', t.id, 'msg', (select to_jsonb(x) from public.messages x where x.id = t.msg_id));
    end if;
  end if;
  if p_kind is null or not (p_kind = any(public.zchat_gh_tour_kinds())) then
    perform public.zchat_gh_err('That game cannot be a tournament yet');
  end if;
  if p_group is null or not public.is_group_member_unmuted(p_group, me) or not public.zchat_can_post_group(p_group, 'text') then
    perform public.zchat_gh_err('You cannot post in this group right now');
  end if;
  for r in select x.id from public.zchat_gh_tours x where x.group_id = p_group and x.status = 'open' and x.created_at < now() - interval '7 days' for update skip locked loop
    update public.zchat_gh_tours set status = 'off', ended_at = now() where id = r.id;
    perform public.zchat_gh_tour_put(r.id);
  end loop;
  select count(*) into n from public.zchat_gh_tours where group_id = p_group and status in ('open', 'live');
  if n >= 3 then
    perform public.zchat_gh_err('This group already has three tournaments going. Finish or call off one first');
  end if;
  select count(*) into n from public.zchat_gh_tours where created_by = me and created_at > now() - interval '1 day';
  if n >= 6 then
    perform public.zchat_gh_err('You made a lot of tournaments today. Try again tomorrow');
  end if;
  insert into public.zchat_gh_tours (id, group_id, kind, created_by, players) values (coalesce(p_id, gen_random_uuid()), p_group, p_kind, me, array[me]) returning * into t;
  perform set_config('zchat.gh_ok', '1', true);
  perform set_config('zchat.role_ok', '1', true);
  insert into public.messages (sender_id, receiver_id, group_id, type, content, client_id)
  values (me, null, p_group, 'text', public.zchat_gh_tour_card(t), 'ght:' || t.id::text)
  returning * into m;
  perform set_config('zchat.gh_ok', '', true);
  perform set_config('zchat.role_ok', '', true);
  update public.zchat_gh_tours set msg_id = m.id where id = t.id;
  return jsonb_build_object('ok', true, 'id', t.id, 'msg', to_jsonb(m));
end $$;

create or replace function public.zchat_gh_tour_join(p_tour uuid, p_on boolean)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  t public.zchat_gh_tours;
begin
  if me is null or not public.zchat_session_ok() then
    perform public.zchat_gh_err('Log in first');
  end if;
  select * into t from public.zchat_gh_tours where id = p_tour for update;
  if not found or not exists (select 1 from public.group_members gm where gm.group_id = t.group_id and gm.user_id = me) then
    perform public.zchat_gh_err('Only people in this group can join');
  end if;
  if exists (select 1 from public.profiles p where p.id = me and coalesce(p.is_bot, false)) then
    perform public.zchat_gh_err('Only people can join');
  end if;
  if t.status <> 'open' then
    perform public.zchat_gh_err('This tournament already started');
  end if;
  if coalesce(p_on, true) then
    if me = any(t.players) then
      return jsonb_build_object('ok', true, 'card', public.zchat_gh_tour_card(t));
    end if;
    if coalesce(array_length(t.players, 1), 0) >= 16 then
      perform public.zchat_gh_err('This tournament is full');
    end if;
    update public.zchat_gh_tours set players = players || me where id = t.id;
  else
    update public.zchat_gh_tours set players = array_remove(players, me) where id = t.id;
  end if;
  perform public.zchat_gh_tour_put(t.id);
  select * into t from public.zchat_gh_tours where id = p_tour;
  return jsonb_build_object('ok', true, 'card', public.zchat_gh_tour_card(t));
end $$;

create or replace function public.zchat_gh_tour_start(p_tour uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  t public.zchat_gh_tours;
  ps uuid[];
  cnt int;
  size int := 2;
  ord int[];
  rounds jsonb := '[]'::jsonb;
  rd jsonb;
  k int;
  a uuid;
  b uuid;
  slots int;
  made jsonb;
begin
  if me is null or not public.zchat_session_ok() then
    perform public.zchat_gh_err('Log in first');
  end if;
  select * into t from public.zchat_gh_tours where id = p_tour for update;
  if not found then
    perform public.zchat_gh_err('This tournament is gone');
  end if;
  if me <> t.created_by and public.zchat_group_role_rank(t.group_id, me) < 2 then
    perform public.zchat_gh_err('Only the person who made it or a group admin can start it');
  end if;
  if t.status <> 'open' then
    perform public.zchat_gh_err('This tournament already started');
  end if;
  select array_agg(p order by random()) into ps
  from unnest(t.players) p
  where exists (select 1 from public.group_members gm where gm.group_id = t.group_id and gm.user_id = p);
  cnt := coalesce(array_length(ps, 1), 0);
  if cnt < 2 then
    perform public.zchat_gh_err('At least two players are needed to start');
  end if;
  while size < cnt loop
    size := size * 2;
  end loop;
  ord := public.zchat_gh_seed_order(size);
  rd := '[]'::jsonb;
  for k in 0 .. size / 2 - 1 loop
    a := case when ord[2 * k + 1] <= cnt then ps[ord[2 * k + 1]] else null end;
    b := case when ord[2 * k + 2] <= cnt then ps[ord[2 * k + 2]] else null end;
    rd := rd || jsonb_build_array(jsonb_build_object('a', coalesce(a, b), 'b', case when a is null then null else b end,
      'w', case when a is null or b is null then coalesce(a, b) else null end, 'm', null, 'd', 0,
      'by', a is null or b is null));
  end loop;
  rounds := jsonb_build_array(rd);
  slots := size / 4;
  while slots >= 1 loop
    rd := '[]'::jsonb;
    for k in 1 .. slots loop
      rd := rd || jsonb_build_array(jsonb_build_object('a', null, 'b', null, 'w', null, 'm', null, 'd', 0));
    end loop;
    rounds := rounds || jsonb_build_array(rd);
    slots := slots / 2;
  end loop;
  update public.zchat_gh_tours set status = 'live', started_at = now(), players = ps, bracket = jsonb_build_object('size', size, 'r', rounds) where id = t.id;
  made := public.zchat_gh_tour_fill(t.id);
  perform public.zchat_gh_tour_put(t.id);
  select * into t from public.zchat_gh_tours where id = p_tour;
  return jsonb_build_object('ok', true, 'made', made, 'card', public.zchat_gh_tour_card(t));
end $$;

create or replace function public.zchat_gh_tour_cancel(p_tour uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  t public.zchat_gh_tours;
begin
  if me is null or not public.zchat_session_ok() then
    perform public.zchat_gh_err('Log in first');
  end if;
  select * into t from public.zchat_gh_tours where id = p_tour for update;
  if not found then
    perform public.zchat_gh_err('This tournament is gone');
  end if;
  if me <> t.created_by and public.zchat_group_role_rank(t.group_id, me) < 2 then
    perform public.zchat_gh_err('Only the person who made it or a group admin can end it');
  end if;
  if t.status not in ('open', 'live') then
    perform public.zchat_gh_err('This tournament is already over');
  end if;
  update public.zchat_gh_tours set status = 'off', ended_at = now() where id = t.id;
  perform public.zchat_gh_tour_put(t.id);
  select * into t from public.zchat_gh_tours where id = p_tour;
  return jsonb_build_object('ok', true, 'card', public.zchat_gh_tour_card(t));
end $$;

revoke all on function public.zchat_gh_tour_put(uuid) from public, anon, authenticated;
revoke all on function public.zchat_gh_tour_fill(uuid) from public, anon, authenticated;
revoke all on function public.zchat_gh_tour_after(uuid) from public, anon, authenticated;
revoke all on function public.zchat_gh_tour_card(public.zchat_gh_tours) from public, anon, authenticated;
grant execute on function public.zchat_gh_tour_new(uuid, text, uuid) to authenticated;
grant execute on function public.zchat_gh_tour_join(uuid, boolean) to authenticated;
grant execute on function public.zchat_gh_tour_start(uuid) to authenticated;
grant execute on function public.zchat_gh_tour_cancel(uuid) to authenticated;
commit;

begin;
create or replace function public.zchat_gh_bot_move(p_bot uuid, p_after bigint, p_content text)
returns public.messages
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me uuid := auth.uid();
  st jsonb;
  prev jsonb;
  pm public.messages;
  r public.messages;
  gid text;
  cid text;
  n int;
begin
  if me is null or not public.zchat_session_ok() then
    perform public.zchat_gh_err('Log in first');
  end if;
  if p_bot is null or not exists (select 1 from public.profiles p where p.id = p_bot and coalesce(p.is_bot, false) and not coalesce(p.is_deleted, false)) then
    perform public.zchat_gh_err('ZChat Bot is not around right now');
  end if;
  if p_content is null or left(p_content, 6) <> 'zgame:' or length(p_content) > 8000 then
    perform public.zchat_gh_err('That move is not allowed');
  end if;
  st := public.zchat_try_jsonb(substr(p_content, 7));
  gid := st ->> 'id';
  if st is null or jsonb_typeof(st) <> 'object' or gid is null or length(gid) > 80 or coalesce(st ->> 'g', '') !~ '^[a-z0-9]{2,12}$'
     or jsonb_typeof(st -> 'n') is distinct from 'number' then
    perform public.zchat_gh_err('That move is not allowed');
  end if;
  if not ((st ->> 'x' = me::text and st ->> 'o' = p_bot::text) or (st ->> 'x' = p_bot::text and st ->> 'o' = me::text)) then
    perform public.zchat_gh_err('That move is not allowed');
  end if;
  select count(*) into n from public.messages m
  where m.receiver_id = me and m.group_id is null and m.sender_id = p_bot and m.created_at > now() - interval '1 minute' and m.content like 'zgame:%';
  if n >= 40 then
    perform public.zchat_gh_err('ZChat Bot needs a short break. Try again in a minute');
  end if;
  select count(*) into n from public.messages m
  where m.receiver_id = me and m.group_id is null and m.sender_id = p_bot and m.created_at > now() - interval '1 day' and m.content like 'zgame:%';
  if n >= 2500 then
    perform public.zchat_gh_err('ZChat Bot played a lot today. Try again tomorrow');
  end if;
  cid := 'ghbot:' || left(gid, 80) || ':' || (st ->> 'n');
  select * into r from public.messages m where m.sender_id = p_bot and m.receiver_id = me and m.client_id = cid limit 1;
  if found then
    return r;
  end if;
  if p_after is null then
    if (st ->> 'n')::numeric <> 0 or (st ->> 'w') is not null or st ->> 'x' <> p_bot::text then
      perform public.zchat_gh_err('That move is not allowed');
    end if;
    if exists (select 1 from public.messages m
               where ((m.sender_id = me and m.receiver_id = p_bot) or (m.sender_id = p_bot and m.receiver_id = me))
                 and m.group_id is null and m.content like 'zgame:%' and strpos(m.content, gid) > 0) then
      perform public.zchat_gh_err('That move is not allowed');
    end if;
  else
    select * into pm from public.messages m where m.id = p_after;
    if not found or pm.group_id is not null or coalesce(pm.deleted, false)
       or not ((pm.sender_id = me and pm.receiver_id = p_bot) or (pm.sender_id = p_bot and pm.receiver_id = me))
       or left(coalesce(pm.content, ''), 6) <> 'zgame:' then
      perform public.zchat_gh_err('That move is not allowed');
    end if;
    prev := public.zchat_try_jsonb(substr(pm.content, 7));
    if prev is null or prev ->> 'id' is distinct from gid or prev ->> 'g' is distinct from st ->> 'g'
       or prev ->> 'x' is distinct from st ->> 'x' or prev ->> 'o' is distinct from st ->> 'o'
       or (prev ->> 'w') is not null or (st ->> 'n')::numeric <> coalesce((prev ->> 'n')::numeric, 0) + 1 then
      perform public.zchat_gh_err('That move is not allowed');
    end if;
    if prev ? 't' and prev ->> 't' is distinct from p_bot::text then
      perform public.zchat_gh_err('It is not the turn of ZChat Bot');
    end if;
    if exists (select 1 from public.messages m
               where ((m.sender_id = me and m.receiver_id = p_bot) or (m.sender_id = p_bot and m.receiver_id = me))
                 and m.group_id is null and m.id > p_after and coalesce(m.deleted, false) = false
                 and m.content like 'zgame:%' and strpos(m.content, gid) > 0) then
      perform public.zchat_gh_err('The board changed. Look again');
    end if;
  end if;
  perform set_config('zchat.gh_bot', p_bot::text, true);
  insert into public.messages (sender_id, receiver_id, group_id, type, content, client_id, read, delivered)
  values (p_bot, me, null, 'text', p_content, cid, false, true)
  returning * into r;
  perform set_config('zchat.gh_bot', '', true);
  return r;
end $$;

grant execute on function public.zchat_gh_bot_move(uuid, bigint, text) to authenticated;

do $$
declare
  r record;
begin
  for r in
    select p.oid::regprocedure as f, p.proname as n
    from pg_proc p join pg_namespace s on s.oid = p.pronamespace
    where s.nspname = 'public' and p.proname like 'zchat\_gh\_%'
  loop
    if r.n in ('zchat_gh_new', 'zchat_gh_secret', 'zchat_gh_move', 'zchat_gh_end', 'zchat_gh_live', 'zchat_gh_get',
               'zchat_gh_tour_new', 'zchat_gh_tour_join', 'zchat_gh_tour_start', 'zchat_gh_tour_cancel', 'zchat_gh_bot_move') then
      execute format('revoke all on function %s from public, anon', r.f);
      execute format('grant execute on function %s to authenticated', r.f);
    else
      execute format('revoke all on function %s from public, anon, authenticated', r.f);
    end if;
  end loop;
end $$;

create or replace function public.zchat_gf_price(p_to uuid, p_kind text, p_key text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  kinds text[];
  k text;
  it public.shop_items%rowtype;
  v_price integer := 0;
  v_name text;
  v_label text;
  got text[] := array[]::text[];
begin
  if p_kind = 'set' then
    kinds := array['frame', 'nameplate', 'effect'];
  elsif p_kind in ('frame', 'nameplate', 'effect', 'charm', 'bubble', 'namestyle', 'theme', 'reaction', 'wallpaper', 'stickerpack', 'soundpack', 'typing') then
    kinds := array[p_kind];
  else
    return jsonb_build_object('ok', false, 'reason', 'That item is not in the Shop.');
  end if;
  foreach k in array kinds loop
    select * into it from public.shop_items where kind = k and key = p_key and active;
    if not found then
      return jsonb_build_object('ok', false, 'reason', 'That item is not in the Shop.');
    end if;
    v_name := regexp_replace(it.label, ' (frame|nameplate|effect)$', '');
    if not public.zchat_owns_forever(p_to, k, p_key) then
      v_price := v_price + it.price;
      got := got || k;
      v_label := it.label;
    end if;
  end loop;
  if coalesce(array_length(got, 1), 0) = 0 then
    return jsonb_build_object('ok', false, 'reason', case when p_kind = 'set' then 'They already have this set.' else 'They already have this one.' end, 'owned', true);
  end if;
  if array_length(got, 1) > 1 then
    v_label := v_name || case when array_length(got, 1) = 3 then ' set' else ' ' || array_to_string(got, ' and ') end;
  end if;
  return jsonb_build_object('ok', true, 'price', v_price, 'got', to_jsonb(got), 'label', v_label,
    'kind', case when array_length(got, 1) > 1 then 'set' else got[1] end);
end $$;

revoke execute on function public.zchat_gf_price(uuid, text, text) from public, anon, authenticated;
grant execute on function public.zchat_gf_price(uuid, text, text) to service_role;

create or replace function public.zchat_chip_start(p_to uuid, p_kind text, p_key text, p_people uuid[], p_coins integer, p_note text, p_paper text, p_ribbon text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  why text := public.zchat_gift_target_reason(p_to);
  pr jsonb;
  v_id uuid;
  v_note text := nullif(btrim(regexp_replace(left(coalesce(p_note, ''), 80), '[[:cntrl:]]+', ' ', 'g')), '');
  v_wrap jsonb := public.zchat_gf_wrap(auth.uid(), p_paper, p_ribbon);
  u uuid;
  v_ok uuid[] := array[]::uuid[];
  v_msgs jsonb := '[]'::jsonb;
  v_msg public.messages%rowtype;
  v_name text;
  v_words text;
  pay jsonb;
begin
  if why is not null then
    return jsonb_build_object('ok', false, 'reason', why);
  end if;
  if exists (select 1 from public.profiles p where p.id = me and (coalesce(p.banned, false) or coalesce(p.is_deleted, false) or coalesce(p.is_bot, false))) then
    return jsonb_build_object('ok', false, 'reason', 'Your account cannot send gifts right now.');
  end if;
  pr := public.zchat_gf_price(p_to, p_kind, p_key);
  if not coalesce((pr ->> 'ok')::boolean, false) then
    return jsonb_build_object('ok', false, 'reason', pr ->> 'reason');
  end if;
  if (select count(*) from public.group_gifts g where g.organizer_id = me and g.status = 'open') >= 5 then
    return jsonb_build_object('ok', false, 'reason', 'You have 5 group gifts going. Finish or cancel one first.');
  end if;
  if (select count(*) from public.group_gifts g where g.organizer_id = me and g.created_at > now() - interval '1 day') >= 10 then
    return jsonb_build_object('ok', false, 'reason', 'You started a lot of group gifts today. Try again tomorrow.');
  end if;
  foreach u in array coalesce(p_people, '{}'::uuid[]) loop
    exit when array_length(v_ok, 1) >= 20;
    if u is null or u = me or u = p_to or u = any (v_ok) then
      continue;
    end if;
    if public.zchat_gf_target(me, u) is not null or not public.zchat_can_dm(me, u) or public.zchat_blocked_pair(u, p_to)
       or not public.zchat_cr_dm_free(me, u) then
      continue;
    end if;
    v_ok := v_ok || u;
  end loop;
  if coalesce(array_length(v_ok, 1), 0) = 0 then
    return jsonb_build_object('ok', false, 'reason', 'Pick at least one friend to chip in with you.');
  end if;
  insert into public.group_gifts (organizer_id, to_id, kind, item_key, label, price, note, wrap)
    values (me, p_to, p_kind, p_key, pr ->> 'label', (pr ->> 'price')::integer, v_note, v_wrap)
    returning id into v_id;
  insert into public.group_gift_people (gift_id, user_id) values (v_id, me);
  insert into public.group_gift_people (gift_id, user_id) select v_id, x from unnest(v_ok) x;
  select split_part(coalesce(p.name, p.username, 'a friend'), ' ', 1) into v_name from public.profiles p where p.id = p_to;
  v_words := 'Chip in for ' || coalesce(v_name, 'a friend') || '''s gift, the ' || (pr ->> 'label');
  perform set_config('zchat.giftcard_ok', '1', true);
  foreach u in array v_ok loop
    insert into public.messages (sender_id, receiver_id, group_id, type, content)
      values (me, u, null, 'text', 'zchip:' || jsonb_build_object('i', v_id, 't', v_words)::text)
      returning * into v_msg;
    insert into public.conversations (user_a, user_b, last_message, last_message_at, last_sender_id)
      values (least(me, u), greatest(me, u), 'Group gift', now(), me)
      on conflict (user_a, user_b) do update set last_message = excluded.last_message, last_message_at = excluded.last_message_at, last_sender_id = excluded.last_sender_id;
    v_msgs := v_msgs || jsonb_build_array(to_jsonb(v_msg));
  end loop;
  perform set_config('zchat.giftcard_ok', '', true);
  if coalesce(p_coins, 0) > 0 then
    pay := public.zchat_chip_pay(v_id, p_coins);
    if not coalesce((pay ->> 'ok')::boolean, false) then
      raise exception '%', coalesce(pay ->> 'reason', 'Your coins could not go in') using errcode = 'P0001';
    end if;
  end if;
  return jsonb_build_object('ok', true, 'gift', public.zchat_chip_json(v_id), 'messages', v_msgs, 'balance', (select coins from public.wallets where user_id = me));
end $$;
revoke execute on function public.zchat_chip_start(uuid, text, text, uuid[], integer, text, text, text) from public, anon;
grant execute on function public.zchat_chip_start(uuid, text, text, uuid[], integer, text, text, text) to authenticated, service_role;

create or replace function public.zchat_g1_check_insert(p_id bigint, p_sender uuid, p_receiver uuid, p_group uuid, p_content text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := coalesce(nullif(current_setting('zchat.gh_bot', true), '')::uuid, auth.uid());
  st jsonb := public.zchat_try_jsonb(substr(p_content, 7));
  k text;
  gid text;
  v_n integer;
  x uuid; o uuid;
  g record;
  ex jsonb;
  mx integer; tg integer;
begin
  if pg_trigger_depth() < 1 then perform public.zchat_g1_bad('Not allowed'); end if;
  if st is null or jsonb_typeof(st) <> 'object' then return; end if;
  k := st ->> 'g';
  if k is null or not (k = any (public.zchat_g1_kinds())) then return; end if;
  if me is null or p_sender is distinct from me then perform public.zchat_g1_bad('Game moves are sent in your own name'); end if;
  gid := st ->> 'id';
  v_n := public.zchat_g1_int(st -> 'n');
  if gid is null or length(gid) > 64 or gid !~ '^[A-Za-z0-9-]+$' or v_n is null or v_n < 0 or length(p_content) > 24000 then perform public.zchat_g1_bad('That game is not valid'); end if;
  if not public.zchat_g1_hit('move', 120, 60) then perform public.zchat_g1_bad('Too many moves in a minute. Wait a moment and try again.'); end if;
  if k = 'dom' then
    mx := public.zchat_g1_int(st -> 'mx'); tg := public.zchat_g1_int(st -> 'tg');
    if p_group is null and (p_receiver is null or mx is distinct from 2) then perform public.zchat_g1_bad('That game is not valid'); end if;
    if mx is null or mx not between 2 and 4 or tg is null or tg not in (0, 50, 100) then perform public.zchat_g1_bad('That game is not valid'); end if;
    ex := jsonb_build_object('g', 'dom', 'id', gid, 'n', 0, 'st', 'lobby', 'p', jsonb_build_array(me), 'by', me, 'mx', mx, 'tg', tg, 'sc', '[]'::jsonb, 'ln', '[]'::jsonb,
      'ld', 0, 't', null, 'cnt', '[]'::jsonb, 'rd', 0, 'ps', 0, 'w', null);
    if ex <> st then perform public.zchat_g1_bad('That game is not valid'); end if;
    if exists (select 1 from public.zchat_g1_dom d where d.game_id = gid) then perform public.zchat_g1_bad('That game is not valid'); end if;
    insert into public.zchat_g1_dom (msg_id, game_id, grp, a, b) values (p_id, gid, p_group, me, p_receiver);
    return;
  end if;
  if p_group is not null or p_receiver is null then perform public.zchat_g1_bad('This game is played in a chat between two people'); end if;
  x := public.zchat_try_uuid(st ->> 'x');
  o := public.zchat_try_uuid(st ->> 'o');
  if x is null or o is null or x = o or not ((x = p_sender and o = p_receiver) or (x = p_receiver and o = p_sender)) then
    perform public.zchat_g1_bad('The players do not match this chat');
  end if;
  select * into g from public.zchat_g1_games where game_id = gid for update;
  if not found then
    if v_n <> 0 or x <> p_sender then perform public.zchat_g1_bad('That game is not valid'); end if;
    ex := public.zchat_g1_initial(k, st);
    if ex is null or ex <> st then perform public.zchat_g1_bad('That game is not valid'); end if;
    insert into public.zchat_g1_games (game_id, kind, a, b, n, st, msg_id, done) values (gid, k, x, o, 0, st, p_id, false);
    if k = 'xw' then
      insert into public.zchat_g1_xw (game_id, x, o, w, h, sol, cells, owners)
      values (gid, x, o, (st #>> '{pz,w}')::integer, (st #>> '{pz,h}')::integer, st #>> '{pz,cells}', regexp_replace(st #>> '{pz,cells}', '[A-Z]', '.', 'g'), repeat('.', length(st #>> '{pz,cells}')))
      on conflict (game_id) do nothing;
    end if;
    return;
  end if;
  if g.kind <> k or g.a <> x or g.b <> o then perform public.zchat_g1_bad('That game is not valid'); end if;
  if g.done then perform public.zchat_g1_bad('This game is already over'); end if;
  if v_n <> g.n + 1 then perform public.zchat_g1_bad('That move is out of date. Open the chat again to catch up.'); end if;
  ex := public.zchat_g1_step(k, g.st, st, p_sender);
  if ex is null or ex <> st then perform public.zchat_g1_bad('That move is not allowed'); end if;
  update public.zchat_g1_games set n = v_n, st = ex, msg_id = p_id, done = (ex ->> 'w') is not null, updated_at = now() where game_id = gid;
end $$;
revoke all on function public.zchat_g1_check_insert(bigint, uuid, uuid, uuid, text) from public, anon;
grant execute on function public.zchat_g1_check_insert(bigint, uuid, uuid, uuid, text) to authenticated;

create or replace function public.zchat_g1_guard()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if current_user not in ('authenticated', 'anon') and coalesce(current_setting('zchat.gh_bot', true), '') = '' then return new; end if;
  if tg_op = 'INSERT' then
    perform public.zchat_g1_check_insert(new.id, new.sender_id, new.receiver_id, new.group_id, new.content);
  else
    perform public.zchat_g1_check_update(old.content, new.content, old.deleted, new.deleted);
  end if;
  return new;
end $$;
commit;

begin;
CREATE OR REPLACE FUNCTION public.zchat_post_visible(p_post uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
      select p.user_id from public.posts p
      where p.id = p_post and (p.scheduled_for is null or p.scheduled_for <= now() or p.user_id = auth.uid())
        and (p.archived_at is null or p.user_id = auth.uid())
        and (not coalesce(p.members_only, false) or p.user_id = auth.uid() or public.zchat_cr_is_member(p.user_id))
    $function$;

CREATE OR REPLACE FUNCTION public.zchat_comment_ok(p_post uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
        select coalesce((
          select case
            when p.user_id = auth.uid() then true
            when coalesce(p.members_only, false) and not public.zchat_cr_is_member(p.user_id) then false
            when p.archived_at is not null then false
            when p.scheduled_for is not null and p.scheduled_for > now() then false
            when coalesce(p.comments_off, false) then false
            else public.zchat_can_interact_as(auth.uid(), 'comment', p.user_id)
          end
          from public.posts p where p.id = p_post
        ), false)
      $function$;

CREATE OR REPLACE FUNCTION public.zchat_trending_tags(p_days integer DEFAULT 7, p_limit integer DEFAULT 24)
 RETURNS TABLE(tag text, n integer, people integer, sample_url text, sample_id text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
      with recent as (
        select p.id, p.user_id, p.media_url, p.media_type, p.created_at, lower(p.caption) as cap
        from public.posts p
        join public.profiles pr on pr.id = p.user_id
        where p.created_at > now() - make_interval(days => greatest(1, least(coalesce(p_days, 7), 30)))
          and p.created_at <= now()
          and (p.scheduled_for is null or p.scheduled_for <= now())
          and p.archived_at is null
          and (not coalesce(p.members_only, false) or p.user_id = auth.uid() or public.zchat_cr_is_member(p.user_id))
          and p.caption like '%#%'
          and not coalesce(pr.is_private, false) and not coalesce(pr.is_deleted, false) and not coalesce(pr.banned, false)
          and not public.zchat_blocked_pair(auth.uid(), p.user_id)
        order by p.created_at desc
        limit 3000
      ),
      tags as (
        select r.id, r.user_id, r.media_url, r.media_type, r.created_at, m[1] as tag
        from recent r, lateral regexp_matches(r.cap, '#([[:alnum:]_]{2,40})', 'g') m
      )
      select t.tag, count(distinct t.id)::integer, count(distinct t.user_id)::integer,
        (array_agg(t.media_url order by t.created_at desc) filter (where coalesce(t.media_type, 'image') <> 'video' and t.media_url is not null))[1],
        (array_agg(t.id::text order by t.created_at desc) filter (where coalesce(t.media_type, 'image') <> 'video' and t.media_url is not null))[1]
      from tags t
      group by t.tag
      order by count(distinct t.user_id) desc, count(distinct t.id) desc, t.tag
      limit greatest(1, least(coalesce(p_limit, 24), 50))
    $function$;

CREATE OR REPLACE FUNCTION public.zchat_post_poll_vote(p_post uuid, p_choice integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  po record;
  n integer;
  c record;
begin
  if me is null then return jsonb_build_object('ok', false, 'reason', 'Log in first.'); end if;
  if (select count(*) from public.zchat_post_poll_votes v where v.user_id = me and v.created_at > now() - interval '1 minute') >= 30 then
    return jsonb_build_object('ok', false, 'reason', 'You voted a lot just now. Try again in a minute.');
  end if;
  select p.id, p.user_id, p.poll, p.archived_at, p.scheduled_for, p.members_only into po from public.posts p where p.id = p_post;
  if not found or po.poll is null then return jsonb_build_object('ok', false, 'reason', 'This poll is not available anymore.'); end if;
  if po.user_id <> me and (po.archived_at is not null or (po.scheduled_for is not null and po.scheduled_for > now()) or not public.zchat_can_view_posts(me, po.user_id) or (coalesce(po.members_only, false) and not public.zchat_cr_is_member(po.user_id))) then
    return jsonb_build_object('ok', false, 'reason', 'This poll is not available anymore.');
  end if;
  n := jsonb_array_length(po.poll -> 'o');
  if p_choice is null or p_choice < 0 or p_choice >= n then return jsonb_build_object('ok', false, 'reason', 'Pick one of the choices.'); end if;
  if po.poll ->> 'e' is not null and (po.poll ->> 'e')::timestamptz <= now() then
    return jsonb_build_object('ok', false, 'reason', 'This poll has ended.', 'ended', true);
  end if;
  insert into public.zchat_post_poll_votes (post_id, user_id, choice) values (p_post, me, p_choice) on conflict do nothing;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'You already voted.', 'voted', true);
  end if;
  insert into public.zchat_post_poll_counts (post_id) values (p_post) on conflict (post_id) do nothing;
  update public.zchat_post_poll_counts
    set counts[p_choice + 1] = coalesce(counts[p_choice + 1], 0) + 1, total = total + 1, updated_at = now()
    where post_id = p_post
    returning counts, total into c;
  return jsonb_build_object('ok', true, 'mine', p_choice, 'counts', to_jsonb(c.counts[1:n]), 'total', c.total);
end $function$;

CREATE OR REPLACE FUNCTION public.zchat_remix_block_reason(p_of uuid, p_user uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  o record;
  pr record;
begin
  select p.id, p.user_id, p.kind, p.remix_ok, p.archived_at, p.scheduled_for, p.members_only into o from public.posts p where p.id = p_of;
  if not found or o.archived_at is not null or (o.scheduled_for is not null and o.scheduled_for > now()) then
    return 'That post is not available anymore.';
  end if;
  if o.kind = 'voice' then return 'Voice posts cannot be remixed.'; end if;
  if coalesce(o.members_only, false) and p_user is distinct from o.user_id then return 'Posts for members cannot be remixed.'; end if;
  if not coalesce(o.remix_ok, true) then return 'Remixes are turned off for that post.'; end if;
  select p.is_private, p.privacy_profile, p.is_deleted, p.banned into pr from public.profiles p where p.id = o.user_id;
  if not found or coalesce(pr.is_deleted, false) or coalesce(pr.banned, false) then return 'That post is not available anymore.'; end if;
  if coalesce(pr.is_private, false) or coalesce(pr.privacy_profile, 'everyone') <> 'everyone' then
    return 'Only public posts can be remixed.';
  end if;
  if public.zchat_blocked_pair(p_user, o.user_id) then return 'That post is not available anymore.'; end if;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.zchat_tag_block_reason(p_post uuid, p_tagger uuid, p_user uuid, p_idx integer)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  po record;
  pr record;
  n_media integer;
  is_video boolean;
  v text;
begin
  select p.user_id, p.media_type, p.media_urls, p.kind, p.archived_at, p.members_only into po from public.posts p where p.id = p_post;
  if not found or po.user_id <> p_tagger then return 'You can only tag people in your own photos.'; end if;
  if po.archived_at is not null then return 'Show the post on your profile again to tag people.'; end if;
  if po.kind = 'voice' then return 'Voice posts cannot have tags.'; end if;
  if p_user = p_tagger then return 'You cannot tag yourself.'; end if;
  if jsonb_typeof(po.media_urls) = 'array' and jsonb_array_length(po.media_urls) > 0 then
    n_media := jsonb_array_length(po.media_urls);
    is_video := coalesce(po.media_urls -> p_idx ->> 't', '') = 'video';
  else
    n_media := 1;
    is_video := po.media_type = 'video';
  end if;
  if p_idx < 0 or p_idx >= n_media then return 'That photo is not in the post.'; end if;
  if is_video then return 'Tags work on photos.'; end if;
  select p.privacy_tags, p.is_deleted, p.banned, p.is_bot into pr from public.profiles p where p.id = p_user;
  if not found or coalesce(pr.is_deleted, false) or coalesce(pr.banned, false) or coalesce(pr.is_bot, false) then
    return 'That account cannot be tagged.';
  end if;
  if public.zchat_blocked_pair(p_tagger, p_user) then return 'That account cannot be tagged.'; end if;
  v := coalesce(pr.privacy_tags, 'everyone');
  if v in ('nobody', 'off') then return 'They do not allow tags.'; end if;
  if v = 'followers' and not public.zchat_follows(p_tagger, p_user) then return 'They only allow tags from their followers.'; end if;
  if v = 'chosen' and not exists (select 1 from public.privacy_allow a where a.user_id = p_user and a.scope = 'privacy_tags' and a.viewer_id = p_tagger) then
    return 'They only allow tags from people they chose.';
  end if;
  if not public.zchat_can_view_posts(p_user, p_tagger) then return 'They cannot see your posts, so they cannot be tagged.'; end if;
  if coalesce(po.members_only, false) and not exists (select 1 from public.creator_members m where m.creator_id = p_tagger and m.member_id = p_user and m.status = 'active') then
    return 'Only your members can be tagged in a post for members.';
  end if;
  if (select count(*) from public.zchat_post_tags t where t.post_id = p_post and t.media_idx = p_idx) >= 20 then
    return 'A photo can have up to 20 tags.';
  end if;
  if (select count(*) from public.zchat_post_tags t where t.tagger_id = p_tagger and t.created_at > now() - interval '1 day') >= 150 then
    return 'You tagged a lot of people today. Try again tomorrow.';
  end if;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.zchat_tip_post(p_post uuid, p_amount integer, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  v_note text := nullif(btrim(left(regexp_replace(regexp_replace(left(coalesce(p_note, ''), 400), '[[:cntrl:]]+', ' ', 'g'), '[' || chr(8203) || chr(8206) || chr(8207) || chr(8234) || '-' || chr(8238) || chr(8288) || '-' || chr(8297) || chr(65279) || ']+', '', 'g'), 80)), '');
  v_owner uuid;
  v_sched timestamptz;
  v_collab uuid;
  v_collab_ok text;
  v_owner_user text;
  v_my_user text;
  v_day_coins bigint;
  v_day_n bigint;
  v_bal integer;
  v_tip public.post_tips;
  v_archived timestamptz;
  v_members boolean;
begin
  if me is null then
    return jsonb_build_object('ok', false, 'reason', 'Log in first.');
  end if;
  if p_amount is null or p_amount < 1 or p_amount > 5000 then
    return jsonb_build_object('ok', false, 'reason', 'Tip between 1 and 5,000 coins.');
  end if;
  if exists (select 1 from public.profiles p where p.id = me and (coalesce(p.banned, false) or coalesce(p.is_deleted, false) or coalesce(p.is_bot, false))) then
    return jsonb_build_object('ok', false, 'reason', 'Your account cannot send tips right now.');
  end if;
  select p.user_id, p.scheduled_for, p.collab_id, p.collab_status, p.archived_at, p.members_only into v_owner, v_sched, v_collab, v_collab_ok, v_archived, v_members from public.posts p where p.id = p_post;
  if v_owner is null or (v_sched is not null and v_sched > now() and v_owner <> me) or (v_archived is not null and v_owner <> me) or (coalesce(v_members, false) and not public.zchat_cr_is_member(v_owner)) then
    return jsonb_build_object('ok', false, 'reason', 'This post is not available anymore.');
  end if;
  if v_owner = me or (v_collab = me and v_collab_ok = 'accepted') then
    return jsonb_build_object('ok', false, 'reason', 'You cannot tip your own post.');
  end if;
  if exists (select 1 from public.profiles p where p.id = v_owner and (coalesce(p.banned, false) or coalesce(p.is_deleted, false) or coalesce(p.is_bot, false))) then
    return jsonb_build_object('ok', false, 'reason', 'This account cannot get tips.');
  end if;
  if public.zchat_blocked_pair(me, v_owner) or not public.zchat_owner_visible(v_owner, 'posts') then
    return jsonb_build_object('ok', false, 'reason', 'This post is not available anymore.');
  end if;
  if coalesce(public.zchat_account_created(me) > now() - interval '1 day', true)
     and not exists (select 1 from public.coin_orders o where o.user_id = me and o.status = 'paid') then
    return jsonb_build_object('ok', false, 'reason', 'New accounts can send tips after their first day.');
  end if;
  insert into public.wallets (user_id) values (me), (v_owner) on conflict (user_id) do nothing;
  perform 1 from public.wallets w where w.user_id in (me, v_owner) order by w.user_id for update;
  select coalesce(sum(-l.delta), 0), count(*) into v_day_coins, v_day_n
    from public.coin_ledger l where l.user_id = me and l.reason = 'tip_out' and l.created_at > now() - interval '1 day';
  if v_day_n >= 30 then
    return jsonb_build_object('ok', false, 'reason', 'You sent a lot of tips today. Try again tomorrow.');
  end if;
  if v_day_coins + p_amount > 5000 then
    return jsonb_build_object('ok', false, 'reason', 'You can tip up to 5,000 coins a day. You have ' || to_char(greatest(5000 - v_day_coins, 0), 'FM9,999') || ' left today.', 'left', greatest(5000 - v_day_coins, 0));
  end if;
  if (select coalesce(sum(l.delta), 0) from public.coin_ledger l where l.user_id = v_owner and l.reason = 'tip_in' and l.created_at > now() - interval '1 day') + p_amount > 10000 then
    return jsonb_build_object('ok', false, 'reason', 'They got a lot of tips today. Try again tomorrow.');
  end if;
  select coalesce(p.username, 'someone') into v_owner_user from public.profiles p where p.id = v_owner;
  select coalesce(p.username, 'someone') into v_my_user from public.profiles p where p.id = me;
  v_bal := public.zchat_coins_move(me, -p_amount, 'tip_out', 'Tip for @' || v_owner_user, v_owner);
  if v_bal is null then
    return jsonb_build_object('ok', false, 'reason', 'You do not have enough coins.');
  end if;
  if public.zchat_coins_move(v_owner, p_amount, 'tip_in', 'Tip from @' || v_my_user, me) is null then
    raise exception 'The tip could not be delivered' using errcode = 'P0001';
  end if;
  insert into public.post_tips (post_id, owner_id, tipper_id, amount, note)
    values (p_post, v_owner, me, p_amount, v_note)
    returning * into v_tip;
  perform public.zchat_notify(v_owner, me, 'tip', p_post,
    'tipped ' || to_char(p_amount, 'FM9,999') || case when p_amount = 1 then ' coin' else ' coins' end || ' on your post' || coalesce(': "' || v_note || '"', ''),
    jsonb_build_object('coins', p_amount, 'note', v_note, 'tip', v_tip.id));
  return jsonb_build_object('ok', true, 'coins', v_bal, 'tip', jsonb_build_object('id', v_tip.id, 'post_id', v_tip.post_id, 'amount', v_tip.amount, 'created_at', v_tip.created_at));
end $function$;

CREATE OR REPLACE FUNCTION public.zchat_story_results(p_story uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when exists (
    select 1 from public.stories s
    where s.id = p_story and public.zchat_story_visible(s.user_id, s.audience, auth.uid())
      and (not coalesce(s.members_only, false) or s.user_id = auth.uid() or public.zchat_cr_is_member(s.user_id))
  ) then jsonb_build_object(
    'poll', (select coalesce(jsonb_object_agg(x.value, x.n), '{}'::jsonb) from (
      select value, count(*) as n from public.story_responses where story_id = p_story and kind = 'poll' group by value
    ) x),
    'slider', (select jsonb_build_object('avg', coalesce(avg(num), 0), 'n', count(*)) from public.story_responses where story_id = p_story and kind = 'slider'),
    'answers', (select count(*) from public.story_responses where story_id = p_story and kind = 'answer'),
    'mine', (select coalesce(jsonb_object_agg(kind, coalesce(value, num::text)), '{}'::jsonb) from public.story_responses where story_id = p_story and user_id = auth.uid())
  ) else null end
$function$;

CREATE OR REPLACE FUNCTION public.zchat_story_mentions_notify()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  el jsonb;
  target uuid;
  n integer := 0;
  is_video boolean;
  ms jsonb;
begin
  begin
    ms := to_jsonb(new) -> 'mentions';
    if ms is null or jsonb_typeof(ms) <> 'array' then
      return null;
    end if;
    is_video := coalesce(to_jsonb(new) ->> 'media_type', '') = 'video';
    for el in select value from jsonb_array_elements(ms) loop
      exit when n >= 20;
      target := null;
      if jsonb_typeof(el) = 'object' then
        if coalesce(el ->> 'kind', 'user') = 'group' then
          continue;
        end if;
        target := public.zchat_try_uuid(el ->> 'id');
      elsif jsonb_typeof(el) = 'string' then
        target := public.zchat_try_uuid(el #>> '{}');
      end if;
      if target is null or target = new.user_id then
        continue;
      end if;
      if coalesce((to_jsonb(new) ->> 'members_only')::boolean, false) and not public.zchat_is_admin_id(target)
         and not exists (select 1 from public.creator_members m where m.creator_id = new.user_id and m.member_id = target and m.status = 'active') then
        continue;
      end if;
      if not public.zchat_can_interact_as(new.user_id, 'mention', target) then
        continue;
      end if;
      n := n + 1;
      perform public.zchat_notify(target, new.user_id, 'story_mention', null, null,
        jsonb_build_object('story_id', new.id::text, 'media', case when is_video then null else to_jsonb(new) ->> 'media_url' end, 'video', is_video));
    end loop;
  exception when others then
    raise notice 'story mention notify skipped: %', sqlerrm;
  end;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.zchat_post_mention_notify()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  mid uuid;
  cap text;
  at timestamptz;
begin
  begin
    cap := coalesce(to_jsonb(new) ->> 'caption', '');
    if position('@' in cap) = 0 then
      return null;
    end if;
    at := greatest(coalesce((to_jsonb(new) ->> 'scheduled_for')::timestamptz, now()), now());
    for mid in select * from public.zchat_mentioned_users(cap, 10) loop
      if mid <> new.user_id and public.zchat_can_interact_as(new.user_id, 'mention', mid)
         and (not coalesce((to_jsonb(new) ->> 'members_only')::boolean, false) or public.zchat_is_admin_id(mid)
           or exists (select 1 from public.creator_members m where m.creator_id = new.user_id and m.member_id = mid and m.status = 'active')) then
        perform public.zchat_notify(mid, new.user_id, 'mention', new.id, left(cap, 120), null, at);
      end if;
    end loop;
  exception when others then
    raise notice 'post mention notify skipped: %', sqlerrm;
  end;
  return null;
end $function$;

create or replace function public.zchat_cr_story_msg_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  s record;
begin
  if new.story_id is null then
    return new;
  end if;
  select st.user_id, st.members_only into s from public.stories st where st.id = new.story_id;
  if not found or not coalesce(s.members_only, false) then
    return new;
  end if;
  if new.group_id is null and new.receiver_id is not null
     and (new.receiver_id = s.user_id or public.zchat_is_admin_id(new.receiver_id)
       or exists (select 1 from public.creator_members m where m.creator_id = s.user_id and m.member_id = new.receiver_id and m.status = 'active')) then
    return new;
  end if;
  raise exception 'This story is for members only' using errcode = '42501';
end $$;
revoke execute on function public.zchat_cr_story_msg_guard() from public, anon, authenticated;
drop trigger if exists zchat_cr_story_msg_guard on public.messages;
create trigger zchat_cr_story_msg_guard before insert on public.messages
  for each row when (new.story_id is not null) execute function public.zchat_cr_story_msg_guard();

do $$
declare
  v_sig text;
  v_open text;
begin
  select string_agg(p.oid::regprocedure::text, ', ') into v_sig
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'zchat_notify';
  if v_sig is null then
    return;
  end if;
  select string_agg(p.proname, ', ') into v_open
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname <> 'zchat_notify' and not p.prosecdef and p.prosrc ilike '%zchat_notify%';
  if v_open is not null then
    raise notice 'zchat safety: zchat_notify stays open because these functions call it without security definer: %', v_open;
    return;
  end if;
  execute (
    select string_agg(format('revoke execute on function %s from public, anon, authenticated; grant execute on function %s to service_role;', p.oid::regprocedure, p.oid::regprocedure), ' ')
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'zchat_notify'
  );
end $$;
commit;
